('quranapp-cache-surah_2_ar.uthmani', 'a:8:{s:6:\"number\";i:2;s:4:\"name\";s:35:\"سُورَةُ البَقَرَةِ\";s:11:\"englishName\";s:9:\"Al-Baqara\";s:22:\"englishNameTranslation\";s:7:\"The Cow\";s:14:\"revelationType\";s:7:\"Medinan\";s:13:\"numberOfAyahs\";i:286;s:5:\"ayahs\";a:286:{i:0;a:9:{s:6:\"number\";i:8;s:4:\"text\";s:87:\"بِسۡمِ ٱللَّهِ ٱلرَّحۡمَـٰنِ ٱلرَّحِیمِ الۤمۤ\n\";s:13:\"numberInSurah\";i:1;s:3:\"juz\";i:1;s:6:\"manzil\";i:1;s:4:\"page\";i:2;s:4:\"ruku\";i:2;s:11:\"hizbQuarter\";i:1;s:5:\"sajda\";b:0;}i:1;a:9:{s:6:\"number\";i:9;s:4:\"text\";s:122:\"ذَ ٰ⁠لِكَ ٱلۡكِتَـٰبُ لَا رَیۡبَۛ فِیهِۛ هُدࣰى لِّلۡمُتَّقِینَ\n\";s:13:\"numberInSurah\";i:2;s:3:\"juz\";i:1;s:6:\"manzil\";i:1;s:4:\"page\";i:2;s:4:\"ruku\";i:2;s:11:\"hizbQuarter\";i:1;s:5:\"sajda\";b:0;}i:2;a:9:{s:6:\"number\";i:10;s:4:\"text\";s:180:\"ٱلَّذِینَ یُؤۡمِنُونَ بِٱلۡغَیۡبِ وَیُقِیمُونَ ٱلصَّلَوٰةَ وَمِمَّا رَزَقۡنَـٰهُمۡ یُنفِقُونَ\n\";s:13:\"numberInSurah\";i:3;s:3:\"juz\";i:1;s:6:\"manzil\";i:1;s:4:\"page\";i:2;s:4:\"ruku\";i:2;s:11:\"hizbQuarter\";i:1;s:5:\"sajda\";b:0;}i:3;a:9:{s:6:\"number\";i:11;s:4:\"text\";s:208:\"وَٱلَّذِینَ یُؤۡمِنُونَ بِمَاۤ أُنزِلَ إِلَیۡكَ وَمَاۤ أُنزِلَ مِن قَبۡلِكَ وَبِٱلۡـَٔاخِرَةِ هُمۡ یُوقِنُونَ\n\";s:13:\"numberInSurah\";i:4;s:3:\"juz\";i:1;s:6:\"manzil\";i:1;s:4:\"page\";i:2;s:4:\"ruku\";i:2;s:11:\"hizbQuarter\";i:1;s:5:\"sajda\";b:0;}i:4;a:9:{s:6:\"number\";i:12;s:4:\"text\";s:157:\"أُو۟لَـٰۤىِٕكَ عَلَىٰ هُدࣰى مِّن رَّبِّهِمۡۖ وَأُو۟لَـٰۤىِٕكَ هُمُ ٱلۡمُفۡلِحُونَ\n\";s:13:\"numberInSurah\";i:5;s:3:\"juz\";i:1;s:6:\"manzil\";i:1;s:4:\"page\";i:2;s:4:\"ruku\";i:2;s:11:\"hizbQuarter\";i:1;s:5:\"sajda\";b:0;}i:5;a:9:{s:6:\"number\";i:13;s:4:\"text\";s:189:\"إِنَّ ٱلَّذِینَ كَفَرُوا۟ سَوَاۤءٌ عَلَیۡهِمۡ ءَأَنذَرۡتَهُمۡ أَمۡ لَمۡ تُنذِرۡهُمۡ لَا یُؤۡمِنُونَ\n\";s:13:\"numberInSurah\";i:6;s:3:\"juz\";i:1;s:6:\"manzil\";i:1;s:4:\"page\";i:3;s:4:\"ruku\";i:2;s:11:\"hizbQuarter\";i:1;s:5:\"sajda\";b:0;}i:6;a:9:{s:6:\"number\";i:14;s:4:\"text\";s:224:\"خَتَمَ ٱللَّهُ عَلَىٰ قُلُوبِهِمۡ وَعَلَىٰ سَمۡعِهِمۡۖ وَعَلَىٰۤ أَبۡصَـٰرِهِمۡ غِشَـٰوَةࣱۖ وَلَهُمۡ عَذَابٌ عَظِیمࣱ\n\";s:13:\"numberInSurah\";i:7;s:3:\"juz\";i:1;s:6:\"manzil\";i:1;s:4:\"page\";i:3;s:4:\"ruku\";i:2;s:11:\"hizbQuarter\";i:1;s:5:\"sajda\";b:0;}i:7;a:9:{s:6:\"number\";i:15;s:4:\"text\";s:185:\"وَمِنَ ٱلنَّاسِ مَن یَقُولُ ءَامَنَّا بِٱللَّهِ وَبِٱلۡیَوۡمِ ٱلۡـَٔاخِرِ وَمَا هُم بِمُؤۡمِنِینَ\n\";s:13:\"numberInSurah\";i:8;s:3:\"juz\";i:1;s:6:\"manzil\";i:1;s:4:\"page\";i:3;s:4:\"ruku\";i:3;s:11:\"hizbQuarter\";i:1;s:5:\"sajda\";b:0;}i:8;a:9:{s:6:\"number\";i:16;s:4:\"text\";s:192:\"یُخَـٰدِعُونَ ٱللَّهَ وَٱلَّذِینَ ءَامَنُوا۟ وَمَا یَخۡدَعُونَ إِلَّاۤ أَنفُسَهُمۡ وَمَا یَشۡعُرُونَ\n\";s:13:\"numberInSurah\";i:9;s:3:\"juz\";i:1;s:6:\"manzil\";i:1;s:4:\"page\";i:3;s:4:\"ruku\";i:3;s:11:\"hizbQuarter\";i:1;s:5:\"sajda\";b:0;}i:9;a:9:{s:6:\"number\";i:17;s:4:\"text\";s:200:\"فِی قُلُوبِهِم مَّرَضࣱ فَزَادَهُمُ ٱللَّهُ مَرَضࣰاۖ وَلَهُمۡ عَذَابٌ أَلِیمُۢ بِمَا كَانُوا۟ یَكۡذِبُونَ\n\";s:13:\"numberInSurah\";i:10;s:3:\"juz\";i:1;s:6:\"manzil\";i:1;s:4:\"page\";i:3;s:4:\"ruku\";i:3;s:11:\"hizbQuarter\";i:1;s:5:\"sajda\";b:0;}i:10;a:9:{s:6:\"number\";i:18;s:4:\"text\";s:167:\"وَإِذَا قِیلَ لَهُمۡ لَا تُفۡسِدُوا۟ فِی ٱلۡأَرۡضِ قَالُوۤا۟ إِنَّمَا نَحۡنُ مُصۡلِحُونَ\n\";s:13:\"numberInSurah\";i:11;s:3:\"juz\";i:1;s:6:\"manzil\";i:1;s:4:\"page\";i:3;s:4:\"ruku\";i:3;s:11:\"hizbQuarter\";i:1;s:5:\"sajda\";b:0;}i:11;a:9:{s:6:\"number\";i:19;s:4:\"text\";s:121:\"أَلَاۤ إِنَّهُمۡ هُمُ ٱلۡمُفۡسِدُونَ وَلَـٰكِن لَّا یَشۡعُرُونَ\n\";s:13:\"numberInSurah\";i:12;s:3:\"juz\";i:1;s:6:\"manzil\";i:1;s:4:\"page\";i:3;s:4:\"ruku\";i:3;s:11:\"hizbQuarter\";i:1;s:5:\"sajda\";b:0;}i:12;a:9:{s:6:\"number\";i:20;s:4:\"text\";s:321:\"وَإِذَا قِیلَ لَهُمۡ ءَامِنُوا۟ كَمَاۤ ءَامَنَ ٱلنَّاسُ قَالُوۤا۟ أَنُؤۡمِنُ كَمَاۤ ءَامَنَ ٱلسُّفَهَاۤءُۗ أَلَاۤ إِنَّهُمۡ هُمُ ٱلسُّفَهَاۤءُ وَلَـٰكِن لَّا یَعۡلَمُونَ\n\";s:13:\"numberInSurah\";i:13;s:3:\"juz\";i:1;s:6:\"manzil\";i:1;s:4:\"page\";i:3;s:4:\"ruku\";i:3;s:11:\"hizbQuarter\";i:1;s:5:\"sajda\";b:0;}i:13;a:9:{s:6:\"number\";i:21;s:4:\"text\";s:294:\"وَإِذَا لَقُوا۟ ٱلَّذِینَ ءَامَنُوا۟ قَالُوۤا۟ ءَامَنَّا وَإِذَا خَلَوۡا۟ إِلَىٰ شَیَـٰطِینِهِمۡ قَالُوۤا۟ إِنَّا مَعَكُمۡ إِنَّمَا نَحۡنُ مُسۡتَهۡزِءُونَ\n\";s:13:\"numberInSurah\";i:14;s:3:\"juz\";i:1;s:6:\"manzil\";i:1;s:4:\"page\";i:3;s:4:\"ruku\";i:3;s:11:\"hizbQuarter\";i:1;s:5:\"sajda\";b:0;}i:14;a:9:{s:6:\"number\";i:22;s:4:\"text\";s:139:\"ٱللَّهُ یَسۡتَهۡزِئُ بِهِمۡ وَیَمُدُّهُمۡ فِی طُغۡیَـٰنِهِمۡ یَعۡمَهُونَ\n\";s:13:\"numberInSurah\";i:15;s:3:\"juz\";i:1;s:6:\"manzil\";i:1;s:4:\"page\";i:3;s:4:\"ruku\";i:3;s:11:\"hizbQuarter\";i:1;s:5:\"sajda\";b:0;}i:15;a:9:{s:6:\"number\";i:23;s:4:\"text\";s:229:\"أُو۟لَـٰۤىِٕكَ ٱلَّذِینَ ٱشۡتَرَوُا۟ ٱلضَّلَـٰلَةَ بِٱلۡهُدَىٰ فَمَا رَبِحَت تِّجَـٰرَتُهُمۡ وَمَا كَانُوا۟ مُهۡتَدِینَ\n\";s:13:\"numberInSurah\";i:16;s:3:\"juz\";i:1;s:6:\"manzil\";i:1;s:4:\"page\";i:3;s:4:\"ruku\";i:3;s:11:\"hizbQuarter\";i:1;s:5:\"sajda\";b:0;}i:16;a:9:{s:6:\"number\";i:24;s:4:\"text\";s:293:\"مَثَلُهُمۡ كَمَثَلِ ٱلَّذِی ٱسۡتَوۡقَدَ نَارࣰا فَلَمَّاۤ أَضَاۤءَتۡ مَا حَوۡلَهُۥ ذَهَبَ ٱللَّهُ بِنُورِهِمۡ وَتَرَكَهُمۡ فِی ظُلُمَـٰتࣲ لَّا یُبۡصِرُونَ\n\";s:13:\"numberInSurah\";i:17;s:3:\"juz\";i:1;s:6:\"manzil\";i:1;s:4:\"page\";i:4;s:4:\"ruku\";i:3;s:11:\"hizbQuarter\";i:1;s:5:\"sajda\";b:0;}i:17;a:9:{s:6:\"number\";i:25;s:4:\"text\";s:83:\"صُمُّۢ بُكۡمٌ عُمۡیࣱ فَهُمۡ لَا یَرۡجِعُونَ\n\";s:13:\"numberInSurah\";i:18;s:3:\"juz\";i:1;s:6:\"manzil\";i:1;s:4:\"page\";i:4;s:4:\"ruku\";i:3;s:11:\"hizbQuarter\";i:1;s:5:\"sajda\";b:0;}i:18;a:9:{s:6:\"number\";i:26;s:4:\"text\";s:361:\"أَوۡ كَصَیِّبࣲ مِّنَ ٱلسَّمَاۤءِ فِیهِ ظُلُمَـٰتࣱ وَرَعۡدࣱ وَبَرۡقࣱ یَجۡعَلُونَ أَصَـٰبِعَهُمۡ فِیۤ ءَاذَانِهِم مِّنَ ٱلصَّوَ ٰ⁠عِقِ حَذَرَ ٱلۡمَوۡتِۚ وَٱللَّهُ مُحِیطُۢ بِٱلۡكَـٰفِرِینَ\n\";s:13:\"numberInSurah\";i:19;s:3:\"juz\";i:1;s:6:\"manzil\";i:1;s:4:\"page\";i:4;s:4:\"ruku\";i:3;s:11:\"hizbQuarter\";i:1;s:5:\"sajda\";b:0;}i:19;a:9:{s:6:\"number\";i:27;s:4:\"text\";s:431:\"یَكَادُ ٱلۡبَرۡقُ یَخۡطَفُ أَبۡصَـٰرَهُمۡۖ كُلَّمَاۤ أَضَاۤءَ لَهُم مَّشَوۡا۟ فِیهِ وَإِذَاۤ أَظۡلَمَ عَلَیۡهِمۡ قَامُوا۟ۚ وَلَوۡ شَاۤءَ ٱللَّهُ لَذَهَبَ بِسَمۡعِهِمۡ وَأَبۡصَـٰرِهِمۡۚ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَیۡءࣲ قَدِیرࣱ\n\";s:13:\"numberInSurah\";i:20;s:3:\"juz\";i:1;s:6:\"manzil\";i:1;s:4:\"page\";i:4;s:4:\"ruku\";i:3;s:11:\"hizbQuarter\";i:1;s:5:\"sajda\";b:0;}i:20;a:9:{s:6:\"number\";i:28;s:4:\"text\";s:215:\"یَـٰۤأَیُّهَا ٱلنَّاسُ ٱعۡبُدُوا۟ رَبَّكُمُ ٱلَّذِی خَلَقَكُمۡ وَٱلَّذِینَ مِن قَبۡلِكُمۡ لَعَلَّكُمۡ تَتَّقُونَ\n\";s:13:\"numberInSurah\";i:21;s:3:\"juz\";i:1;s:6:\"manzil\";i:1;s:4:\"page\";i:4;s:4:\"ruku\";i:4;s:11:\"hizbQuarter\";i:1;s:5:\"sajda\";b:0;}i:21;a:9:{s:6:\"number\";i:29;s:4:\"text\";s:410:\"ٱلَّذِی جَعَلَ لَكُمُ ٱلۡأَرۡضَ فِرَ ٰ⁠شࣰا وَٱلسَّمَاۤءَ بِنَاۤءࣰ وَأَنزَلَ مِنَ ٱلسَّمَاۤءِ مَاۤءࣰ فَأَخۡرَجَ بِهِۦ مِنَ ٱلثَّمَرَ ٰ⁠تِ رِزۡقࣰا لَّكُمۡۖ فَلَا تَجۡعَلُوا۟ لِلَّهِ أَندَادࣰا وَأَنتُمۡ تَعۡلَمُونَ\n\";s:13:\"numberInSurah\";i:22;s:3:\"juz\";i:1;s:6:\"manzil\";i:1;s:4:\"page\";i:4;s:4:\"ruku\";i:4;s:11:\"hizbQuarter\";i:1;s:5:\"sajda\";b:0;}i:22;a:9:{s:6:\"number\";i:30;s:4:\"text\";s:312:\"وَإِن كُنتُمۡ فِی رَیۡبࣲ مِّمَّا نَزَّلۡنَا عَلَىٰ عَبۡدِنَا فَأۡتُوا۟ بِسُورَةࣲ مِّن مِّثۡلِهِۦ وَٱدۡعُوا۟ شُهَدَاۤءَكُم مِّن دُونِ ٱللَّهِ إِن كُنتُمۡ صَـٰدِقِینَ\n\";s:13:\"numberInSurah\";i:23;s:3:\"juz\";i:1;s:6:\"manzil\";i:1;s:4:\"page\";i:4;s:4:\"ruku\";i:4;s:11:\"hizbQuarter\";i:1;s:5:\"sajda\";b:0;}i:23;a:9:{s:6:\"number\";i:31;s:4:\"text\";s:253:\"فَإِن لَّمۡ تَفۡعَلُوا۟ وَلَن تَفۡعَلُوا۟ فَٱتَّقُوا۟ ٱلنَّارَ ٱلَّتِی وَقُودُهَا ٱلنَّاسُ وَٱلۡحِجَارَةُۖ أُعِدَّتۡ لِلۡكَـٰفِرِینَ\n\";s:13:\"numberInSurah\";i:24;s:3:\"juz\";i:1;s:6:\"manzil\";i:1;s:4:\"page\";i:4;s:4:\"ruku\";i:4;s:11:\"hizbQuarter\";i:1;s:5:\"sajda\";b:0;}i:24;a:9:{s:6:\"number\";i:32;s:4:\"text\";s:604:\"وَبَشِّرِ ٱلَّذِینَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ أَنَّ لَهُمۡ جَنَّـٰتࣲ تَجۡرِی مِن تَحۡتِهَا ٱلۡأَنۡهَـٰرُۖ كُلَّمَا رُزِقُوا۟ مِنۡهَا مِن ثَمَرَةࣲ رِّزۡقࣰا قَالُوا۟ هَـٰذَا ٱلَّذِی رُزِقۡنَا مِن قَبۡلُۖ وَأُتُوا۟ بِهِۦ مُتَشَـٰبِهࣰاۖ وَلَهُمۡ فِیهَاۤ أَزۡوَ ٰ⁠جࣱ مُّطَهَّرَةࣱۖ وَهُمۡ فِیهَا خَـٰلِدُونَ\n\";s:13:\"numberInSurah\";i:25;s:3:\"juz\";i:1;s:6:\"manzil\";i:1;s:4:\"page\";i:5;s:4:\"ruku\";i:4;s:11:\"hizbQuarter\";i:1;s:5:\"sajda\";b:0;}i:25;a:9:{s:6:\"number\";i:33;s:4:\"text\";s:645:\"۞ إِنَّ ٱللَّهَ لَا یَسۡتَحۡیِۦۤ أَن یَضۡرِبَ مَثَلࣰا مَّا بَعُوضَةࣰ فَمَا فَوۡقَهَاۚ فَأَمَّا ٱلَّذِینَ ءَامَنُوا۟ فَیَعۡلَمُونَ أَنَّهُ ٱلۡحَقُّ مِن رَّبِّهِمۡۖ وَأَمَّا ٱلَّذِینَ كَفَرُوا۟ فَیَقُولُونَ مَاذَاۤ أَرَادَ ٱللَّهُ بِهَـٰذَا مَثَلࣰاۘ یُضِلُّ بِهِۦ كَثِیرࣰا وَیَهۡدِی بِهِۦ كَثِیرࣰاۚ وَمَا یُضِلُّ بِهِۦۤ إِلَّا ٱلۡفَـٰسِقِینَ\n\";s:13:\"numberInSurah\";i:26;s:3:\"juz\";i:1;s:6:\"manzil\";i:1;s:4:\"page\";i:5;s:4:\"ruku\";i:4;s:11:\"hizbQuarter\";i:2;s:5:\"sajda\";b:0;}i:26;a:9:{s:6:\"number\";i:34;s:4:\"text\";s:336:\"ٱلَّذِینَ یَنقُضُونَ عَهۡدَ ٱللَّهِ مِنۢ بَعۡدِ مِیثَـٰقِهِۦ وَیَقۡطَعُونَ مَاۤ أَمَرَ ٱللَّهُ بِهِۦۤ أَن یُوصَلَ وَیُفۡسِدُونَ فِی ٱلۡأَرۡضِۚ أُو۟لَـٰۤىِٕكَ هُمُ ٱلۡخَـٰسِرُونَ\n\";s:13:\"numberInSurah\";i:27;s:3:\"juz\";i:1;s:6:\"manzil\";i:1;s:4:\"page\";i:5;s:4:\"ruku\";i:4;s:11:\"hizbQuarter\";i:2;s:5:\"sajda\";b:0;}i:27;a:9:{s:6:\"number\";i:35;s:4:\"text\";s:252:\"كَیۡفَ تَكۡفُرُونَ بِٱللَّهِ وَكُنتُمۡ أَمۡوَ ٰ⁠تࣰا فَأَحۡیَـٰكُمۡۖ ثُمَّ یُمِیتُكُمۡ ثُمَّ یُحۡیِیكُمۡ ثُمَّ إِلَیۡهِ تُرۡجَعُونَ\n\";s:13:\"numberInSurah\";i:28;s:3:\"juz\";i:1;s:6:\"manzil\";i:1;s:4:\"page\";i:5;s:4:\"ruku\";i:4;s:11:\"hizbQuarter\";i:2;s:5:\"sajda\";b:0;}i:28;a:9:{s:6:\"number\";i:36;s:4:\"text\";s:298:\"هُوَ ٱلَّذِی خَلَقَ لَكُم مَّا فِی ٱلۡأَرۡضِ جَمِیعࣰا ثُمَّ ٱسۡتَوَىٰۤ إِلَى ٱلسَّمَاۤءِ فَسَوَّىٰهُنَّ سَبۡعَ سَمَـٰوَ ٰ⁠تࣲۚ وَهُوَ بِكُلِّ شَیۡءٍ عَلِیمࣱ\n\";s:13:\"numberInSurah\";i:29;s:3:\"juz\";i:1;s:6:\"manzil\";i:1;s:4:\"page\";i:5;s:4:\"ruku\";i:4;s:11:\"hizbQuarter\";i:2;s:5:\"sajda\";b:0;}i:29;a:9:{s:6:\"number\";i:37;s:4:\"text\";s:458:\"وَإِذۡ قَالَ رَبُّكَ لِلۡمَلَـٰۤىِٕكَةِ إِنِّی جَاعِلࣱ فِی ٱلۡأَرۡضِ خَلِیفَةࣰۖ قَالُوۤا۟ أَتَجۡعَلُ فِیهَا مَن یُفۡسِدُ فِیهَا وَیَسۡفِكُ ٱلدِّمَاۤءَ وَنَحۡنُ نُسَبِّحُ بِحَمۡدِكَ وَنُقَدِّسُ لَكَۖ قَالَ إِنِّیۤ أَعۡلَمُ مَا لَا تَعۡلَمُونَ\n\";s:13:\"numberInSurah\";i:30;s:3:\"juz\";i:1;s:6:\"manzil\";i:1;s:4:\"page\";i:6;s:4:\"ruku\";i:5;s:11:\"hizbQuarter\";i:2;s:5:\"sajda\";b:0;}i:30;a:9:{s:6:\"number\";i:38;s:4:\"text\";s:295:\"وَعَلَّمَ ءَادَمَ ٱلۡأَسۡمَاۤءَ كُلَّهَا ثُمَّ عَرَضَهُمۡ عَلَى ٱلۡمَلَـٰۤىِٕكَةِ فَقَالَ أَنۢبِـُٔونِی بِأَسۡمَاۤءِ هَـٰۤؤُلَاۤءِ إِن كُنتُمۡ صَـٰدِقِینَ\n\";s:13:\"numberInSurah\";i:31;s:3:\"juz\";i:1;s:6:\"manzil\";i:1;s:4:\"page\";i:6;s:4:\"ruku\";i:5;s:11:\"hizbQuarter\";i:2;s:5:\"sajda\";b:0;}i:31;a:9:{s:6:\"number\";i:39;s:4:\"text\";s:192:\"قَالُوا۟ سُبۡحَـٰنَكَ لَا عِلۡمَ لَنَاۤ إِلَّا مَا عَلَّمۡتَنَاۤۖ إِنَّكَ أَنتَ ٱلۡعَلِیمُ ٱلۡحَكِیمُ\n\";s:13:\"numberInSurah\";i:32;s:3:\"juz\";i:1;s:6:\"manzil\";i:1;s:4:\"page\";i:6;s:4:\"ruku\";i:5;s:11:\"hizbQuarter\";i:2;s:5:\"sajda\";b:0;}i:32;a:9:{s:6:\"number\";i:40;s:4:\"text\";s:424:\"قَالَ یَـٰۤـَٔادَمُ أَنۢبِئۡهُم بِأَسۡمَاۤىِٕهِمۡۖ فَلَمَّاۤ أَنۢبَأَهُم بِأَسۡمَاۤىِٕهِمۡ قَالَ أَلَمۡ أَقُل لَّكُمۡ إِنِّیۤ أَعۡلَمُ غَیۡبَ ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِ وَأَعۡلَمُ مَا تُبۡدُونَ وَمَا كُنتُمۡ تَكۡتُمُونَ\n\";s:13:\"numberInSurah\";i:33;s:3:\"juz\";i:1;s:6:\"manzil\";i:1;s:4:\"page\";i:6;s:4:\"ruku\";i:5;s:11:\"hizbQuarter\";i:2;s:5:\"sajda\";b:0;}i:33;a:9:{s:6:\"number\";i:41;s:4:\"text\";s:259:\"وَإِذۡ قُلۡنَا لِلۡمَلَـٰۤىِٕكَةِ ٱسۡجُدُوا۟ لِـَٔادَمَ فَسَجَدُوۤا۟ إِلَّاۤ إِبۡلِیسَ أَبَىٰ وَٱسۡتَكۡبَرَ وَكَانَ مِنَ ٱلۡكَـٰفِرِینَ\n\";s:13:\"numberInSurah\";i:34;s:3:\"juz\";i:1;s:6:\"manzil\";i:1;s:4:\"page\";i:6;s:4:\"ruku\";i:5;s:11:\"hizbQuarter\";i:2;s:5:\"sajda\";b:0;}i:34;a:9:{s:6:\"number\";i:42;s:4:\"text\";s:320:\"وَقُلۡنَا یَـٰۤـَٔادَمُ ٱسۡكُنۡ أَنتَ وَزَوۡجُكَ ٱلۡجَنَّةَ وَكُلَا مِنۡهَا رَغَدًا حَیۡثُ شِئۡتُمَا وَلَا تَقۡرَبَا هَـٰذِهِ ٱلشَّجَرَةَ فَتَكُونَا مِنَ ٱلظَّـٰلِمِینَ\n\";s:13:\"numberInSurah\";i:35;s:3:\"juz\";i:1;s:6:\"manzil\";i:1;s:4:\"page\";i:6;s:4:\"ruku\";i:5;s:11:\"hizbQuarter\";i:2;s:5:\"sajda\";b:0;}i:35;a:9:{s:6:\"number\";i:43;s:4:\"text\";s:350:\"فَأَزَلَّهُمَا ٱلشَّیۡطَـٰنُ عَنۡهَا فَأَخۡرَجَهُمَا مِمَّا كَانَا فِیهِۖ وَقُلۡنَا ٱهۡبِطُوا۟ بَعۡضُكُمۡ لِبَعۡضٍ عَدُوࣱّۖ وَلَكُمۡ فِی ٱلۡأَرۡضِ مُسۡتَقَرࣱّ وَمَتَـٰعٌ إِلَىٰ حِینࣲ\n\";s:13:\"numberInSurah\";i:36;s:3:\"juz\";i:1;s:6:\"manzil\";i:1;s:4:\"page\";i:6;s:4:\"ruku\";i:5;s:11:\"hizbQuarter\";i:2;s:5:\"sajda\";b:0;}i:36;a:9:{s:6:\"number\";i:44;s:4:\"text\";s:192:\"فَتَلَقَّىٰۤ ءَادَمُ مِن رَّبِّهِۦ كَلِمَـٰتࣲ فَتَابَ عَلَیۡهِۚ إِنَّهُۥ هُوَ ٱلتَّوَّابُ ٱلرَّحِیمُ\n\";s:13:\"numberInSurah\";i:37;s:3:\"juz\";i:1;s:6:\"manzil\";i:1;s:4:\"page\";i:6;s:4:\"ruku\";i:5;s:11:\"hizbQuarter\";i:2;s:5:\"sajda\";b:0;}i:37;a:9:{s:6:\"number\";i:45;s:4:\"text\";s:271:\"قُلۡنَا ٱهۡبِطُوا۟ مِنۡهَا جَمِیعࣰاۖ فَإِمَّا یَأۡتِیَنَّكُم مِّنِّی هُدࣰى فَمَن تَبِعَ هُدَایَ فَلَا خَوۡفٌ عَلَیۡهِمۡ وَلَا هُمۡ یَحۡزَنُونَ\n\";s:13:\"numberInSurah\";i:38;s:3:\"juz\";i:1;s:6:\"manzil\";i:1;s:4:\"page\";i:7;s:4:\"ruku\";i:5;s:11:\"hizbQuarter\";i:2;s:5:\"sajda\";b:0;}i:38;a:9:{s:6:\"number\";i:46;s:4:\"text\";s:214:\"وَٱلَّذِینَ كَفَرُوا۟ وَكَذَّبُوا۟ بِـَٔایَـٰتِنَاۤ أُو۟لَـٰۤىِٕكَ أَصۡحَـٰبُ ٱلنَّارِۖ هُمۡ فِیهَا خَـٰلِدُونَ\n\";s:13:\"numberInSurah\";i:39;s:3:\"juz\";i:1;s:6:\"manzil\";i:1;s:4:\"page\";i:7;s:4:\"ruku\";i:5;s:11:\"hizbQuarter\";i:2;s:5:\"sajda\";b:0;}i:39;a:9:{s:6:\"number\";i:47;s:4:\"text\";s:283:\"یَـٰبَنِیۤ إِسۡرَ ٰ⁠ۤءِیلَ ٱذۡكُرُوا۟ نِعۡمَتِیَ ٱلَّتِیۤ أَنۡعَمۡتُ عَلَیۡكُمۡ وَأَوۡفُوا۟ بِعَهۡدِیۤ أُوفِ بِعَهۡدِكُمۡ وَإِیَّـٰیَ فَٱرۡهَبُونِ\n\";s:13:\"numberInSurah\";i:40;s:3:\"juz\";i:1;s:6:\"manzil\";i:1;s:4:\"page\";i:7;s:4:\"ruku\";i:6;s:11:\"hizbQuarter\";i:2;s:5:\"sajda\";b:0;}i:40;a:9:{s:6:\"number\";i:48;s:4:\"text\";s:329:\"وَءَامِنُوا۟ بِمَاۤ أَنزَلۡتُ مُصَدِّقࣰا لِّمَا مَعَكُمۡ وَلَا تَكُونُوۤا۟ أَوَّلَ كَافِرِۭ بِهِۦۖ وَلَا تَشۡتَرُوا۟ بِـَٔایَـٰتِی ثَمَنࣰا قَلِیلࣰا وَإِیَّـٰیَ فَٱتَّقُونِ\n\";s:13:\"numberInSurah\