('quranapp-cache-surah_17_ar.uthmani', 'a:8:{s:6:\"number\";i:17;s:4:\"name\";s:37:\"سُورَةُ الإِسۡرَاءِ\";s:11:\"englishName\";s:8:\"Al-Israa\";s:22:\"englishNameTranslation\";s:17:\"The Night Journey\";s:14:\"revelationType\";s:6:\"Meccan\";s:13:\"numberOfAyahs\";i:111;s:5:\"ayahs\";a:111:{i:0;a:9:{s:6:\"number\";i:2030;s:4:\"text\";s:466:\"بِسۡمِ ٱللَّهِ ٱلرَّحۡمَـٰنِ ٱلرَّحِیمِ سُبۡحَـٰنَ ٱلَّذِیۤ أَسۡرَىٰ بِعَبۡدِهِۦ لَیۡلࣰا مِّنَ ٱلۡمَسۡجِدِ ٱلۡحَرَامِ إِلَى ٱلۡمَسۡجِدِ ٱلۡأَقۡصَا ٱلَّذِی بَـٰرَكۡنَا حَوۡلَهُۥ لِنُرِیَهُۥ مِنۡ ءَایَـٰتِنَاۤۚ إِنَّهُۥ هُوَ ٱلسَّمِیعُ ٱلۡبَصِیرُ\n\";s:13:\"numberInSurah\";i:1;s:3:\"juz\";i:15;s:6:\"manzil\";i:4;s:4:\"page\";i:282;s:4:\"ruku\";i:240;s:11:\"hizbQuarter\";i:113;s:5:\"sajda\";b:0;}i:1;a:9:{s:6:\"number\";i:2031;s:4:\"text\";s:230:\"وَءَاتَیۡنَا مُوسَى ٱلۡكِتَـٰبَ وَجَعَلۡنَـٰهُ هُدࣰى لِّبَنِیۤ إِسۡرَ ٰ⁠ۤءِیلَ أَلَّا تَتَّخِذُوا۟ مِن دُونِی وَكِیلࣰا\n\";s:13:\"numberInSurah\";i:2;s:3:\"juz\";i:15;s:6:\"manzil\";i:4;s:4:\"page\";i:282;s:4:\"ruku\";i:240;s:11:\"hizbQuarter\";i:113;s:5:\"sajda\";b:0;}i:2;a:9:{s:6:\"number\";i:2032;s:4:\"text\";s:133:\"ذُرِّیَّةَ مَنۡ حَمَلۡنَا مَعَ نُوحٍۚ إِنَّهُۥ كَانَ عَبۡدࣰا شَكُورࣰا\n\";s:13:\"numberInSurah\";i:3;s:3:\"juz\";i:15;s:6:\"manzil\";i:4;s:4:\"page\";i:282;s:4:\"ruku\";i:240;s:11:\"hizbQuarter\";i:113;s:5:\"sajda\";b:0;}i:3;a:9:{s:6:\"number\";i:2033;s:4:\"text\";s:253:\"وَقَضَیۡنَاۤ إِلَىٰ بَنِیۤ إِسۡرَ ٰ⁠ۤءِیلَ فِی ٱلۡكِتَـٰبِ لَتُفۡسِدُنَّ فِی ٱلۡأَرۡضِ مَرَّتَیۡنِ وَلَتَعۡلُنَّ عُلُوࣰّا كَبِیرࣰا\n\";s:13:\"numberInSurah\";i:4;s:3:\"juz\";i:15;s:6:\"manzil\";i:4;s:4:\"page\";i:282;s:4:\"ruku\";i:240;s:11:\"hizbQuarter\";i:113;s:5:\"sajda\";b:0;}i:4;a:9:{s:6:\"number\";i:2034;s:4:\"text\";s:300:\"فَإِذَا جَاۤءَ وَعۡدُ أُولَىٰهُمَا بَعَثۡنَا عَلَیۡكُمۡ عِبَادࣰا لَّنَاۤ أُو۟لِی بَأۡسࣲ شَدِیدࣲ فَجَاسُوا۟ خِلَـٰلَ ٱلدِّیَارِۚ وَكَانَ وَعۡدࣰا مَّفۡعُولࣰا\n\";s:13:\"numberInSurah\";i:5;s:3:\"juz\";i:15;s:6:\"manzil\";i:4;s:4:\"page\";i:282;s:4:\"ruku\";i:240;s:11:\"hizbQuarter\";i:113;s:5:\"sajda\";b:0;}i:5;a:9:{s:6:\"number\";i:2035;s:4:\"text\";s:236:\"ثُمَّ رَدَدۡنَا لَكُمُ ٱلۡكَرَّةَ عَلَیۡهِمۡ وَأَمۡدَدۡنَـٰكُم بِأَمۡوَ ٰ⁠لࣲ وَبَنِینَ وَجَعَلۡنَـٰكُمۡ أَكۡثَرَ نَفِیرًا\n\";s:13:\"numberInSurah\";i:6;s:3:\"juz\";i:15;s:6:\"manzil\";i:4;s:4:\"page\";i:282;s:4:\"ruku\";i:240;s:11:\"hizbQuarter\";i:113;s:5:\"sajda\";b:0;}i:6;a:9:{s:6:\"number\";i:2036;s:4:\"text\";s:451:\"إِنۡ أَحۡسَنتُمۡ أَحۡسَنتُمۡ لِأَنفُسِكُمۡۖ وَإِنۡ أَسَأۡتُمۡ فَلَهَاۚ فَإِذَا جَاۤءَ وَعۡدُ ٱلۡـَٔاخِرَةِ لِیَسُـࣳۤـُٔوا۟ وُجُوهَكُمۡ وَلِیَدۡخُلُوا۟ ٱلۡمَسۡجِدَ كَمَا دَخَلُوهُ أَوَّلَ مَرَّةࣲ وَلِیُتَبِّرُوا۟ مَا عَلَوۡا۟ تَتۡبِیرًا\n\";s:13:\"numberInSurah\";i:7;s:3:\"juz\";i:15;s:6:\"manzil\";i:4;s:4:\"page\";i:282;s:4:\"ruku\";i:240;s:11:\"hizbQuarter\";i:113;s:5:\"sajda\";b:0;}i:7;a:9:{s:6:\"number\";i:2037;s:4:\"text\";s:203:\"عَسَىٰ رَبُّكُمۡ أَن یَرۡحَمَكُمۡۚ وَإِنۡ عُدتُّمۡ عُدۡنَاۚ وَجَعَلۡنَا جَهَنَّمَ لِلۡكَـٰفِرِینَ حَصِیرًا\n\";s:13:\"numberInSurah\";i:8;s:3:\"juz\";i:15;s:6:\"manzil\";i:4;s:4:\"page\";i:283;s:4:\"ruku\";i:240;s:11:\"hizbQuarter\";i:113;s:5:\"sajda\";b:0;}i:8;a:9:{s:6:\"number\";i:2038;s:4:\"text\";s:292:\"إِنَّ هَـٰذَا ٱلۡقُرۡءَانَ یَهۡدِی لِلَّتِی هِیَ أَقۡوَمُ وَیُبَشِّرُ ٱلۡمُؤۡمِنِینَ ٱلَّذِینَ یَعۡمَلُونَ ٱلصَّـٰلِحَـٰتِ أَنَّ لَهُمۡ أَجۡرࣰا كَبِیرࣰا\n\";s:13:\"numberInSurah\";i:9;s:3:\"juz\";i:15;s:6:\"manzil\";i:4;s:4:\"page\";i:283;s:4:\"ruku\";i:240;s:11:\"hizbQuarter\";i:113;s:5:\"sajda\";b:0;}i:9;a:9:{s:6:\"number\";i:2039;s:4:\"text\";s:166:\"وَأَنَّ ٱلَّذِینَ لَا یُؤۡمِنُونَ بِٱلۡـَٔاخِرَةِ أَعۡتَدۡنَا لَهُمۡ عَذَابًا أَلِیمࣰا\n\";s:13:\"numberInSurah\";i:10;s:3:\"juz\";i:15;s:6:\"manzil\";i:4;s:4:\"page\";i:283;s:4:\"ruku\";i:240;s:11:\"hizbQuarter\";i:113;s:5:\"sajda\";b:0;}i:10;a:9:{s:6:\"number\";i:2040;s:4:\"text\";s:169:\"وَیَدۡعُ ٱلۡإِنسَـٰنُ بِٱلشَّرِّ دُعَاۤءَهُۥ بِٱلۡخَیۡرِۖ وَكَانَ ٱلۡإِنسَـٰنُ عَجُولࣰا\n\";s:13:\"numberInSurah\";i:11;s:3:\"juz\";i:15;s:6:\"manzil\";i:4;s:4:\"page\";i:283;s:4:\"ruku\";i:241;s:11:\"hizbQuarter\";i:113;s:5:\"sajda\";b:0;}i:11;a:9:{s:6:\"number\";i:2041;s:4:\"text\";s:475:\"وَجَعَلۡنَا ٱلَّیۡلَ وَٱلنَّهَارَ ءَایَتَیۡنِۖ فَمَحَوۡنَاۤ ءَایَةَ ٱلَّیۡلِ وَجَعَلۡنَاۤ ءَایَةَ ٱلنَّهَارِ مُبۡصِرَةࣰ لِّتَبۡتَغُوا۟ فَضۡلࣰا مِّن رَّبِّكُمۡ وَلِتَعۡلَمُوا۟ عَدَدَ ٱلسِّنِینَ وَٱلۡحِسَابَۚ وَكُلَّ شَیۡءࣲ فَصَّلۡنَـٰهُ تَفۡصِیلࣰا\n\";s:13:\"numberInSurah\";i:12;s:3:\"juz\";i:15;s:6:\"manzil\";i:4;s:4:\"page\";i:283;s:4:\"ruku\";i:241;s:11:\"hizbQuarter\";i:113;s:5:\"sajda\";b:0;}i:12;a:9:{s:6:\"number\";i:2042;s:4:\"text\";s:250:\"وَكُلَّ إِنسَـٰنٍ أَلۡزَمۡنَـٰهُ طَـٰۤىِٕرَهُۥ فِی عُنُقِهِۦۖ وَنُخۡرِجُ لَهُۥ یَوۡمَ ٱلۡقِیَـٰمَةِ كِتَـٰبࣰا یَلۡقَىٰهُ مَنشُورًا\n\";s:13:\"numberInSurah\";i:13;s:3:\"juz\";i:15;s:6:\"manzil\";i:4;s:4:\"page\";i:283;s:4:\"ruku\";i:241;s:11:\"hizbQuarter\";i:113;s:5:\"sajda\";b:0;}i:13;a:9:{s:6:\"number\";i:2043;s:4:\"text\";s:124:\"ٱقۡرَأۡ كِتَـٰبَكَ كَفَىٰ بِنَفۡسِكَ ٱلۡیَوۡمَ عَلَیۡكَ حَسِیبࣰا\n\";s:13:\"numberInSurah\";i:14;s:3:\"juz\";i:15;s:6:\"manzil\";i:4;s:4:\"page\";i:283;s:4:\"ruku\";i:241;s:11:\"hizbQuarter\";i:113;s:5:\"sajda\";b:0;}i:14;a:9:{s:6:\"number\";i:2044;s:4:\"text\";s:349:\"مَّنِ ٱهۡتَدَىٰ فَإِنَّمَا یَهۡتَدِی لِنَفۡسِهِۦۖ وَمَن ضَلَّ فَإِنَّمَا یَضِلُّ عَلَیۡهَاۚ وَلَا تَزِرُ وَازِرَةࣱ وِزۡرَ أُخۡرَىٰۗ وَمَا كُنَّا مُعَذِّبِینَ حَتَّىٰ نَبۡعَثَ رَسُولࣰا\n\";s:13:\"numberInSurah\";i:15;s:3:\"juz\";i:15;s:6:\"manzil\";i:4;s:4:\"page\";i:283;s:4:\"ruku\";i:241;s:11:\"hizbQuarter\";i:113;s:5:\"sajda\";b:0;}i:15;a:9:{s:6:\"number\";i:2045;s:4:\"text\";s:269:\"وَإِذَاۤ أَرَدۡنَاۤ أَن نُّهۡلِكَ قَرۡیَةً أَمَرۡنَا مُتۡرَفِیهَا فَفَسَقُوا۟ فِیهَا فَحَقَّ عَلَیۡهَا ٱلۡقَوۡلُ فَدَمَّرۡنَـٰهَا تَدۡمِیرࣰا\n\";s:13:\"numberInSurah\";i:16;s:3:\"juz\";i:15;s:6:\"manzil\";i:4;s:4:\"page\";i:283;s:4:\"ruku\";i:241;s:11:\"hizbQuarter\";i:113;s:5:\"sajda\";b:0;}i:16;a:9:{s:6:\"number\";i:2046;s:4:\"text\";s:215:\"وَكَمۡ أَهۡلَكۡنَا مِنَ ٱلۡقُرُونِ مِنۢ بَعۡدِ نُوحࣲۗ وَكَفَىٰ بِرَبِّكَ بِذُنُوبِ عِبَادِهِۦ خَبِیرَۢا بَصِیرࣰا\n\";s:13:\"numberInSurah\";i:17;s:3:\"juz\";i:15;s:6:\"manzil\";i:4;s:4:\"page\";i:283;s:4:\"ruku\";i:241;s:11:\"hizbQuarter\";i:113;s:5:\"sajda\";b:0;}i:17;a:9:{s:6:\"number\";i:2047;s:4:\"text\";s:286:\"مَّن كَانَ یُرِیدُ ٱلۡعَاجِلَةَ عَجَّلۡنَا لَهُۥ فِیهَا مَا نَشَاۤءُ لِمَن نُّرِیدُ ثُمَّ جَعَلۡنَا لَهُۥ جَهَنَّمَ یَصۡلَىٰهَا مَذۡمُومࣰا مَّدۡحُورࣰا\n\";s:13:\"numberInSurah\";i:18;s:3:\"juz\";i:15;s:6:\"manzil\";i:4;s:4:\"page\";i:284;s:4:\"ruku\";i:241;s:11:\"hizbQuarter\";i:113;s:5:\"sajda\";b:0;}i:18;a:9:{s:6:\"number\";i:2048;s:4:\"text\";s:220:\"وَمَنۡ أَرَادَ ٱلۡـَٔاخِرَةَ وَسَعَىٰ لَهَا سَعۡیَهَا وَهُوَ مُؤۡمِنࣱ فَأُو۟لَـٰۤىِٕكَ كَانَ سَعۡیُهُم مَّشۡكُورࣰا\n\";s:13:\"numberInSurah\";i:19;s:3:\"juz\";i:15;s:6:\"manzil\";i:4;s:4:\"page\";i:284;s:4:\"ruku\";i:241;s:11:\"hizbQuarter\";i:113;s:5:\"sajda\";b:0;}i:19;a:9:{s:6:\"number\";i:2049;s:4:\"text\";s:207:\"كُلࣰّا نُّمِدُّ هَـٰۤؤُلَاۤءِ وَهَـٰۤؤُلَاۤءِ مِنۡ عَطَاۤءِ رَبِّكَۚ وَمَا كَانَ عَطَاۤءُ رَبِّكَ مَحۡظُورًا\n\";s:13:\"numberInSurah\";i:20;s:3:\"juz\";i:15;s:6:\"manzil\";i:4;s:4:\"page\";i:284;s:4:\"ruku\";i:241;s:11:\"hizbQuarter\";i:113;s:5:\"sajda\";b:0;}i:20;a:9:{s:6:\"number\";i:2050;s:4:\"text\";s:212:\"ٱنظُرۡ كَیۡفَ فَضَّلۡنَا بَعۡضَهُمۡ عَلَىٰ بَعۡضࣲۚ وَلَلۡـَٔاخِرَةُ أَكۡبَرُ دَرَجَـٰتࣲ وَأَكۡبَرُ تَفۡضِیلࣰا\n\";s:13:\"numberInSurah\";i:21;s:3:\"juz\";i:15;s:6:\"manzil\";i:4;s:4:\"page\";i:284;s:4:\"ruku\";i:241;s:11:\"hizbQuarter\";i:113;s:5:\"sajda\";b:0;}i:21;a:9:{s:6:\"number\";i:2051;s:4:\"text\";s:151:\"لَّا تَجۡعَلۡ مَعَ ٱللَّهِ إِلَـٰهًا ءَاخَرَ فَتَقۡعُدَ مَذۡمُومࣰا مَّخۡذُولࣰا\n\";s:13:\"numberInSurah\";i:22;s:3:\"juz\";i:15;s:6:\"manzil\";i:4;s:4:\"page\";i:284;s:4:\"ruku\";i:241;s:11:\"hizbQuarter\";i:113;s:5:\"sajda\";b:0;}i:22;a:9:{s:6:\"number\";i:2052;s:4:\"text\";s:451:\"۞ وَقَضَىٰ رَبُّكَ أَلَّا تَعۡبُدُوۤا۟ إِلَّاۤ إِیَّاهُ وَبِٱلۡوَ ٰ⁠لِدَیۡنِ إِحۡسَـٰنًاۚ إِمَّا یَبۡلُغَنَّ عِندَكَ ٱلۡكِبَرَ أَحَدُهُمَاۤ أَوۡ كِلَاهُمَا فَلَا تَقُل لَّهُمَاۤ أُفࣲّ وَلَا تَنۡهَرۡهُمَا وَقُل لَّهُمَا قَوۡلࣰا كَرِیمࣰا\n\";s:13:\"numberInSurah\";i:23;s:3:\"juz\";i:15;s:6:\"manzil\";i:4;s:4:\"page\";i:284;s:4:\"ruku\";i:242;s:11:\"hizbQuarter\";i:114;s:5:\"sajda\";b:0;}i:23;a:9:{s:6:\"number\";i:2053;s:4:\"text\";s:199:\"وَٱخۡفِضۡ لَهُمَا جَنَاحَ ٱلذُّلِّ مِنَ ٱلرَّحۡمَةِ وَقُل رَّبِّ ٱرۡحَمۡهُمَا كَمَا رَبَّیَانِی صَغِیرࣰا\n\";s:13:\"numberInSurah\";i:24;s:3:\"juz\";i:15;s:6:\"manzil\";i:4;s:4:\"page\";i:284;s:4:\"ruku\";i:242;s:11:\"hizbQuarter\";i:114;s:5:\"sajda\";b:0;}i:24;a:9:{s:6:\"number\";i:2054;s:4:\"text\";s:219:\"رَّبُّكُمۡ أَعۡلَمُ بِمَا فِی نُفُوسِكُمۡۚ إِن تَكُونُوا۟ صَـٰلِحِینَ فَإِنَّهُۥ كَانَ لِلۡأَوَّ ٰ⁠بِینَ غَفُورࣰا\n\";s:13:\"numberInSurah\";i:25;s:3:\"juz\";i:15;s:6:\"manzil\";i:4;s:4:\"page\";i:284;s:4:\"ruku\";i:242;s:11:\"hizbQuarter\";i:114;s:5:\"sajda\";b:0;}i:25;a:9:{s:6:\"number\";i:2055;s:4:\"text\";s:178:\"وَءَاتِ ذَا ٱلۡقُرۡبَىٰ حَقَّهُۥ وَٱلۡمِسۡكِینَ وَٱبۡنَ ٱلسَّبِیلِ وَلَا تُبَذِّرۡ تَبۡذِیرًا\n\";s:13:\"numberInSurah\";i:26;s:3:\"juz\";i:15;s:6:\"manzil\";i:4;s:4:\"page\";i:284;s:4:\"ruku\";i:242;s:11:\"hizbQuarter\";i:114;s:5:\"sajda\";b:0;}i:26;a:9:{s:6:\"number\";i:2056;s:4:\"text\";s:198:\"إِنَّ ٱلۡمُبَذِّرِینَ كَانُوۤا۟ إِخۡوَ ٰ⁠نَ ٱلشَّیَـٰطِینِۖ وَكَانَ ٱلشَّیۡطَـٰنُ لِرَبِّهِۦ كَفُورࣰا\n\";s:13:\"numberInSurah\";i:27;s:3:\"juz\";i:15;s:6:\"manzil\";i:4;s:4:\"page\";i:284;s:4:\"ruku\";i:242;s:11:\"hizbQuarter\";i:114;s:5:\"sajda\";b:0;}i:27;a:9:{s:6:\"number\";i:2057;s:4:\"text\";s:211:\"وَإِمَّا تُعۡرِضَنَّ عَنۡهُمُ ٱبۡتِغَاۤءَ رَحۡمَةࣲ مِّن رَّبِّكَ تَرۡجُوهَا فَقُل لَّهُمۡ قَوۡلࣰا مَّیۡسُورࣰا\n\";s:13:\"numberInSurah\";i:28;s:3:\"juz\";i:15;s:6:\"manzil\";i:4;s:4:\"page\";i:285;s:4:\"ruku\";i:242;s:11:\"hizbQuarter\";i:114;s:5:\"sajda\";b:0;}i:28;a:9:{s:6:\"number\";i:2058;s:4:\"text\";s:220:\"وَلَا تَجۡعَلۡ یَدَكَ مَغۡلُولَةً إِلَىٰ عُنُقِكَ وَلَا تَبۡسُطۡهَا كُلَّ ٱلۡبَسۡطِ فَتَقۡعُدَ مَلُومࣰا مَّحۡسُورًا\n\";s:13:\"numberInSurah\";i:29;s:3:\"juz\";i:15;s:6:\"manzil\";i:4;s:4:\"page\";i:285;s:4:\"ruku\";i:242;s:11:\"hizbQuarter\";i:114;s:5:\"sajda\";b:0;}i:29;a:9:{s:6:\"number\";i:2059;s:4:\"text\";s:203:\"إِنَّ رَبَّكَ یَبۡسُطُ ٱلرِّزۡقَ لِمَن یَشَاۤءُ وَیَقۡدِرُۚ إِنَّهُۥ كَانَ بِعِبَادِهِۦ خَبِیرَۢا بَصِیرࣰا\n\";s:13:\"numberInSurah\";i:30;s:3:\"juz\";i:15;s:6:\"manzil\";i:4;s:4:\"page\";i:285;s:4:\"ruku\";i:242;s:11:\"hizbQuarter\";i:114;s:5:\"sajda\";b:0;}i:30;a:9:{s:6:\"number\";i:2060;s:4:\"text\";s:252:\"وَلَا تَقۡتُلُوۤا۟ أَوۡلَـٰدَكُمۡ خَشۡیَةَ إِمۡلَـٰقࣲۖ نَّحۡنُ نَرۡزُقُهُمۡ وَإِیَّاكُمۡۚ إِنَّ قَتۡلَهُمۡ كَانَ خِطۡـࣰٔا كَبِیرࣰا\n\";s:13:\"numberInSurah\";i:31;s:3:\"juz\";i:15;s:6:\"manzil\";i:4;s:4:\"page\";i:285;s:4:\"ruku\";i:243;s:11:\"hizbQuarter\";i:114;s:5:\"sajda\";b:0;}i:31;a:9:{s:6:\"number\";i:2061;s:4:\"text\";s:142:\"وَلَا تَقۡرَبُوا۟ ٱلزِّنَىٰۤۖ إِنَّهُۥ كَانَ فَـٰحِشَةࣰ وَسَاۤءَ سَبِیلࣰا\n\";s:13:\"numberInSurah\";i:32;s:3:\"juz\";i:15;s:6:\"manzil\";i:4;s:4:\"page\";i:285;s:4:\"ruku\";i:243;s:11:\"hizbQuarter\";i:114;s:5:\"sajda\";b:0;}i:32;a:9:{s:6:\"number\";i:2062;s:4:\"text\";s:365:\"وَلَا تَقۡتُلُوا۟ ٱلنَّفۡسَ ٱلَّتِی حَرَّمَ ٱللَّهُ إِلَّا بِٱلۡحَقِّۗ وَمَن قُتِلَ مَظۡلُومࣰا فَقَدۡ جَعَلۡنَا لِوَلِیِّهِۦ سُلۡطَـٰنࣰا فَلَا یُسۡرِف فِّی ٱلۡقَتۡلِۖ إِنَّهُۥ كَانَ مَنصُورࣰا\n\";s:13:\"numberInSurah\";i:33;s:3:\"juz\";i:15;s:6:\"manzil\";i:4;s:4:\"page\";i:285;s:4:\"ruku\";i:243;s:11:\"hizbQuarter\";i:114;s:5:\"sajda\";b:0;}i:33;a:9:{s:6:\"number\";i:2063;s:4:\"text\";s:292:\"وَلَا تَقۡرَبُوا۟ مَالَ ٱلۡیَتِیمِ إِلَّا بِٱلَّتِی هِیَ أَحۡسَنُ حَتَّىٰ یَبۡلُغَ أَشُدَّهُۥۚ وَأَوۡفُوا۟ بِٱلۡعَهۡدِۖ إِنَّ ٱلۡعَهۡدَ كَانَ مَسۡـُٔولࣰا\n\";s:13:\"numberInSurah\";i:34;s:3:\"juz\";i:15;s:6:\"manzil\";i:4;s:4:\"page\";i:285;s:4:\"ruku\";i:243;s:11:\"hizbQuarter\";i:114;s:5:\"sajda\";b:0;}i:34;a:9:{s:6:\"number\";i:2064;s:4:\"text\";s:227:\"وَأَوۡفُوا۟ ٱلۡكَیۡلَ إِذَا كِلۡتُمۡ وَزِنُوا۟ بِٱلۡقِسۡطَاسِ ٱلۡمُسۡتَقِیمِۚ ذَ ٰ⁠لِكَ خَیۡرࣱ وَأَحۡسَنُ تَأۡوِیلࣰا\n\";s:13:\"numberInSurah\";i:35;s:3:\"juz\";i:15;s:6:\"manzil\";i:4;s:4:\"page\";i:285;s:4:\