('quranapp-cache-surah_20_ar.uthmani', 'a:8:{s:6:\"number\";i:20;s:4:\"name\";s:19:\"سُورَةُ طه\";s:11:\"englishName\";s:7:\"Taa-Haa\";s:22:\"englishNameTranslation\";s:7:\"Taa-Haa\";s:14:\"revelationType\";s:6:\"Meccan\";s:13:\"numberOfAyahs\";i:135;s:5:\"ayahs\";a:135:{i:0;a:9:{s:6:\"number\";i:2349;s:4:\"text\";s:81:\"بِسۡمِ ٱللَّهِ ٱلرَّحۡمَـٰنِ ٱلرَّحِیمِ طه\n\";s:13:\"numberInSurah\";i:1;s:3:\"juz\";i:16;s:6:\"manzil\";i:4;s:4:\"page\";i:312;s:4:\"ruku\";i:270;s:11:\"hizbQuarter\";i:125;s:5:\"sajda\";b:0;}i:1;a:9:{s:6:\"number\";i:2350;s:4:\"text\";s:95:\"مَاۤ أَنزَلۡنَا عَلَیۡكَ ٱلۡقُرۡءَانَ لِتَشۡقَىٰۤ\n\";s:13:\"numberInSurah\";i:2;s:3:\"juz\";i:16;s:6:\"manzil\";i:4;s:4:\"page\";i:312;s:4:\"ruku\";i:270;s:11:\"hizbQuarter\";i:125;s:5:\"sajda\";b:0;}i:2;a:9:{s:6:\"number\";i:2351;s:4:\"text\";s:65:\"إِلَّا تَذۡكِرَةࣰ لِّمَن یَخۡشَىٰ\n\";s:13:\"numberInSurah\";i:3;s:3:\"juz\";i:16;s:6:\"manzil\";i:4;s:4:\"page\";i:312;s:4:\"ruku\";i:270;s:11:\"hizbQuarter\";i:125;s:5:\"sajda\";b:0;}i:3;a:9:{s:6:\"number\";i:2352;s:4:\"text\";s:125:\"تَنزِیلࣰا مِّمَّنۡ خَلَقَ ٱلۡأَرۡضَ وَٱلسَّمَـٰوَ ٰ⁠تِ ٱلۡعُلَى\n\";s:13:\"numberInSurah\";i:4;s:3:\"juz\";i:16;s:6:\"manzil\";i:4;s:4:\"page\";i:312;s:4:\"ruku\";i:270;s:11:\"hizbQuarter\";i:125;s:5:\"sajda\";b:0;}i:4;a:9:{s:6:\"number\";i:2353;s:4:\"text\";s:76:\"ٱلرَّحۡمَـٰنُ عَلَى ٱلۡعَرۡشِ ٱسۡتَوَىٰ\n\";s:13:\"numberInSurah\";i:5;s:3:\"juz\";i:16;s:6:\"manzil\";i:4;s:4:\"page\";i:312;s:4:\"ruku\";i:270;s:11:\"hizbQuarter\";i:125;s:5:\"sajda\";b:0;}i:5;a:9:{s:6:\"number\";i:2354;s:4:\"text\";s:174:\"لَهُۥ مَا فِی ٱلسَّمَـٰوَ ٰ⁠تِ وَمَا فِی ٱلۡأَرۡضِ وَمَا بَیۡنَهُمَا وَمَا تَحۡتَ ٱلثَّرَىٰ\n\";s:13:\"numberInSurah\";i:6;s:3:\"juz\";i:16;s:6:\"manzil\";i:4;s:4:\"page\";i:312;s:4:\"ruku\";i:270;s:11:\"hizbQuarter\";i:125;s:5:\"sajda\";b:0;}i:6;a:9:{s:6:\"number\";i:2355;s:4:\"text\";s:125:\"وَإِن تَجۡهَرۡ بِٱلۡقَوۡلِ فَإِنَّهُۥ یَعۡلَمُ ٱلسِّرَّ وَأَخۡفَى\n\";s:13:\"numberInSurah\";i:7;s:3:\"juz\";i:16;s:6:\"manzil\";i:4;s:4:\"