:9:{s:6:\"number\";i:2407;s:4:\"text\";s:127:\"قَالَ مَوۡعِدُكُمۡ یَوۡمُ ٱلزِّینَةِ وَأَن یُحۡشَرَ ٱلنَّاسُ ضُحࣰى\n\";s:13:\"numberInSurah\";i:59;s:3:\"juz\";i:16;s:6:\"manzil\";i:4;s:4:\"page\";i:315;s:4:\"ruku\";i:272;s:11:\"hizbQuarter\";i:126;s:5:\"sajda\";b:0;}i:59;a:9:{s:6:\"number\";i:2408;s:4:\"text\";s:104:\"فَتَوَلَّىٰ فِرۡعَوۡنُ فَجَمَعَ كَیۡدَهُۥ ثُمَّ أَتَىٰ\n\";s:13:\"numberInSurah\";i:60;s:3:\"juz\";i:16;s:6:\"manzil\";i:4;s:4:\"page\";i:315;s:4:\"ruku\";i:272;s:11:\"hizbQuarter\";i:126;s:5:\"sajda\";b:0;}i:60;a:9:{s:6:\"number\";i:2409;s:4:\"text\";s:233:\"قَالَ لَهُم مُّوسَىٰ وَیۡلَكُمۡ لَا تَفۡتَرُوا۟ عَلَى ٱللَّهِ كَذِبࣰا فَیُسۡحِتَكُم بِعَذَابࣲۖ وَقَدۡ خَابَ مَنِ ٱفۡتَرَىٰ\n\";s:13:\"numberInSurah\";i:61;s:3:\"juz\";i:16;s:6:\"manzil\";i:4;s:4:\"page\";i:315;s:4:\"ruku\";i:272;s:11:\"hizbQuarter\";i:126;s:5:\"sajda\";b:0;}i:61;a:9:{s:6:\"number\";i:2410;s:4:\"text\";s:121:\"فَتَنَـٰزَعُوۤا۟ أَمۡرَهُم بَیۡنَهُمۡ وَأَسَرُّوا۟ ٱلنَّجۡوَىٰ\n\";s:13:\"numberInSurah\";i:62;s:3:\"juz\";i:16;s:6:\"manzil\";i:4;s:4:\"page\";i:315;s:4:\"ruku\";i:272;s:11:\"hizbQuarter\";i:126;s:5:\"sajda\";b:0;}i:62;a:9:{s:6:\"number\";i:2411;s:4:\"text\";s:273:\"قَالُوۤا۟ إِنۡ هَـٰذَ ٰ⁠نِ لَسَـٰحِرَ ٰ⁠نِ یُرِیدَانِ أَن یُخۡرِجَاكُم مِّنۡ أَرۡضِكُم بِسِحۡرِهِمَا وَیَذۡهَبَا بِطَرِیقَتِكُمُ ٱلۡمُثۡلَىٰ\n\";s:13:\"numberInSurah\";i:63;s:3:\"juz\";i:16;s:6:\"manzil\";i:4;s:4:\"page\";i:315;s:4:\"ruku\";i:272;s:11:\"hizbQuarter\";i:126;s:5:\"sajda\";b:0;}i:63;a:9:{s:6:\"number\";i:2412;s:4:\"text\";s:173:\"فَأَجۡمِعُوا۟ كَیۡدَكُمۡ ثُمَّ ٱئۡتُوا۟ صَفࣰّاۚ وَقَدۡ أَفۡلَحَ ٱلۡیَوۡمَ مَنِ ٱسۡتَعۡلَىٰ\n\";s:13:\"numberInSurah\";i:64;s:3:\"juz\";i:16;s:6:\"manzil\";i:4;s:4:\"page\";i:315;s:4:\"ruku\";i:272;s:11:\"hizbQuarter\";i:126;s:5:\"sajda\";b:0;}i:64;a:9:{s:6:\"number\";i:2413;s:4:\"text\";s:165:\"قَالُوا۟ یَـٰمُوسَىٰۤ إِمَّاۤ أَن تُلۡقِیَ وَإِمَّاۤ أَن نَّكُونَ أَوَّلَ مَنۡ أَلۡقَىٰ\n\";s:13:\"numberInSurah\";i:65;s:3:\"juz\";i:16;s:6:\"manzil\";i:4;s:4:\"page\";i:316;s:4:\"ruku\";i:272;s:11:\"hizbQuarter\";i:126;s:5:\"sajda\";b:0;}i:65;a:9:{s:6:\"number\";i:2414;s:4:\"text\";s:204:\"قَالَ بَلۡ أَلۡقُوا۟ۖ فَإِذَا حِبَالُهُمۡ وَعِصِیُّهُمۡ یُخَیَّلُ إِلَیۡهِ مِن سِحۡرِهِمۡ أَنَّهَا تَسۡعَىٰ\n\";s:13:\"numberInSurah\";i:66;s:3:\"juz\";i:16;s:6:\"manzil\";i:4;s:4:\"page\";i:316;s:4:\"ruku\";i:272;s:11:\"hizbQuarter\";i:126;s:5:\"sajda\";b:0;}i:66;a:9:{s:6:\"number\";i:2415;s:4:\"text\";s:80:\"فَأَوۡجَسَ فِی نَفۡسِهِۦ خِیفَةࣰ مُّوسَىٰ\n\";s:13:\"numberInSurah\";i:67;s:3:\"juz\";i:16;s:6:\"manzil\";i:4;s:4:\"page\";i:316;s:4:\"ruku\";i:272;s:11:\"hizbQuarter\";i:126;s:5:\"sajda\";b:0;}i:67;a:9:{s:6:\"number\";i:2416;s:4:\"text\";s:84:\"قُلۡنَا لَا تَخَفۡ إِنَّكَ أَنتَ ٱلۡأَعۡلَىٰ\n\";s:13:\"numberInSurah\";i:68;s:3:\"juz\";i:16;s:6:\"manzil\";i:4;s:4:\"page\";i:316;s:4:\"ruku\";i:272;s:11:\"hizbQuarter\";i:126;s:5:\"sajda\";b:0;}i:68;a:9:{s:6:\"number\";i:2417;s:4:\"text\";s:241:\"وَأَلۡقِ مَا فِی یَمِینِكَ تَلۡقَفۡ مَا صَنَعُوۤا۟ۖ إِنَّمَا صَنَعُوا۟ كَیۡدُ سَـٰحِرࣲۖ وَلَا یُفۡلِحُ ٱلسَّاحِرُ حَیۡثُ أَتَىٰ\n\";s:13:\"numberInSurah\";i:69;s:3:\"juz\";i:16;s:6:\"manzil\";i:4;s:4:\"page\";i:316;s:4:\"ruku\";i:272;s:11:\"hizbQuarter\";i:126;s:5:\"sajda\";b:0;}i:69;a:9:{s:6:\"number\";i:2418;s:4:\"text\";s:153:\"فَأُلۡقِیَ ٱلسَّحَرَةُ سُجَّدࣰا قَالُوۤا۟ ءَامَنَّا بِرَبِّ هَـٰرُونَ وَمُوسَىٰ\n\";s:13:\"numberInSurah\";i:70;s:3:\"juz\";i:16;s:6:\"manzil\";i:4;s:4:\"page\";i:316;s:4:\"ruku\";i:272;s:11:\"hizbQuarter\";i:126;s:5:\"sajda\";b:0;}i:70;a:9:{s:6:\"number\";i:2419;s:4:\"text\";s:498:\"قَالَ ءَامَنتُمۡ لَهُۥ قَبۡلَ أَنۡ ءَاذَنَ لَكُمۡۖ إِنَّهُۥ لَكَبِیرُكُمُ ٱلَّذِی عَلَّمَكُمُ ٱلسِّحۡرَۖ فَلَأُقَطِّعَنَّ أَیۡدِیَكُمۡ وَأَرۡجُلَكُم مِّنۡ خِلَـٰفࣲ وَلَأُصَلِّبَنَّكُمۡ فِی جُذُوعِ ٱلنَّخۡلِ وَلَتَعۡلَمُنَّ أَیُّنَاۤ أَشَدُّ عَذَابࣰا وَأَبۡقَىٰ\n\";s:13:\"numberInSurah\";i:71;s:3:\"juz\";i:16;s:6:\"manzil\";i:4;s:4:\"page\";i:316;s:4:\"ruku\";i:272;s:11:\"hizbQuarter\";i:126;s:5:\"sajda\";b:0;}i:71;a:9:{s:6:\"number\";i:2420;s:4:\"text\";s:307:\"قَالُوا۟ لَن نُّؤۡثِرَكَ عَلَىٰ مَا جَاۤءَنَا مِنَ ٱلۡبَیِّنَـٰتِ وَٱلَّذِی فَطَرَنَاۖ فَٱقۡضِ مَاۤ أَنتَ قَاضٍۖ إِنَّمَا تَقۡضِی هَـٰذِهِ ٱلۡحَیَوٰةَ ٱلدُّنۡیَاۤ\n\";s:13:\"numberInSurah\";i:72;s:3:\"juz\";i:16;s:6:\"manzil\";i:4;s:4:\"page\";i:316;s:4:\"ruku\";i:272;s:11:\"hizbQuarter\";i:126;s:5:\"sajda\";b:0;}i:72;a:9:{s:6:\"number\";i:2421;s:4:\"text\";s:257:\"إِنَّاۤ ءَامَنَّا بِرَبِّنَا لِیَغۡفِرَ لَنَا خَطَـٰیَـٰنَا وَمَاۤ أَكۡرَهۡتَنَا عَلَیۡهِ مِنَ ٱلسِّحۡرِۗ وَٱللَّهُ خَیۡرࣱ وَأَبۡقَىٰۤ\n\";s:13:\"numberInSurah\";i:73;s:3:\"juz\";i:16;s:6:\"manzil\";i:4;s:4:\"page\";i:316;s:4:\"ruku\";i:272;s:11:\"hizbQuarter\";i:126;s:5:\"sajda\";b:0;}i:73;a:9:{s:6:\"number\";i:2422;s:4:\"text\";s:182:\"إِنَّهُۥ مَن یَأۡتِ رَبَّهُۥ مُجۡرِمࣰا فَإِنَّ لَهُۥ جَهَنَّمَ لَا یَمُوتُ فِیهَا وَلَا یَحۡیَىٰ\n\";s:13:\"numberInSurah\";i:74;s:3:\"juz\";i:16;s:6:\"manzil\";i:4;s:4:\"page\";i:316;s:4:\"ruku\";i:272;s:11:\"hizbQuarter\";i:126;s:5:\"sajda\";b:0;}i:74;a:9:{s:6:\"number\";i:2423;s:4:\"text\";s:195:\"وَمَن یَأۡتِهِۦ مُؤۡمِنࣰا قَدۡ عَمِلَ ٱلصَّـٰلِحَـٰتِ فَأُو۟لَـٰۤىِٕكَ لَهُمُ ٱلدَّرَجَـٰتُ ٱلۡعُلَىٰ\n\";s:13:\"numberInSurah\";i:75;s:3:\"juz\";i:16;s:6:\"manzil\";i:4;s:4:\"page\";i:316;s:4:\"ruku\";i:272;s:11:\"hizbQuarter\";i:126;s:5:\"sajda\";b:0;}i:75;a:9:{s:6:\"number\";i:2424;s:4:\"text\";s:207:\"جَنَّـٰتُ عَدۡنࣲ تَجۡرِی مِن تَحۡتِهَا ٱلۡأَنۡهَـٰرُ خَـٰلِدِینَ فِیهَاۚ وَذَ ٰ⁠لِكَ جَزَاۤءُ مَن تَزَكَّىٰ\n\";s:13:\"numberInSurah\";i:76;s:3:\"juz\";i:16;s:6:\"manzil\";i:4;s:4:\"page\";i:316;s:4:\"ruku\";i:272;s:11:\"hizbQuarter\";i:126;s:5:\"sajda\";b:0;}i:76;a:9:{s:6:\"number\";i:2425;s:4:\"text\";s:277:\"وَلَقَدۡ أَوۡحَیۡنَاۤ إِلَىٰ مُوسَىٰۤ أَنۡ أَسۡرِ بِعِبَادِی فَٱضۡرِبۡ لَهُمۡ طَرِیقࣰا فِی ٱلۡبَحۡرِ یَبَسࣰا لَّا تَخَـٰفُ دَرَكࣰا وَلَا تَخۡشَىٰ\n\";s:13:\"numberInSurah\";i:77;s:3:\"juz\";i:16;s:6:\"manzil\";i:4;s:4:\"page\";i:317;s:4:\"ruku\";i:273;s:11:\"hizbQuarter\";i:126;s:5:\"sajda\";b:0;}i:77;a:9:{s:6:\"number\";i:2426;s:4:\"text\";s:154:\"فَأَتۡبَعَهُمۡ فِرۡعَوۡنُ بِجُنُودِهِۦ فَغَشِیَهُم مِّنَ ٱلۡیَمِّ مَا غَشِیَهُمۡ\n\";s:13:\"numberInSurah\";i:78;s:3:\"juz\";i:16;s:6:\"manzil\";i:4;s:4:\"page\";i:317;s:4:\"ruku\";i:273;s:11:\"hizbQuarter\";i:126;s:5:\"sajda\";b:0;}i:78;a:9:{s:6:\"number\";i:2427;s:4:\"text\";s:83:\"وَأَضَلَّ فِرۡعَوۡنُ قَوۡمَهُۥ وَمَا هَدَىٰ\n\";s:13:\"numberInSurah\";i:79;s:3:\"juz\";i:16;s:6:\"manzil\";i:4;s:4:\"page\";i:317;s:4:\"ruku\";i:273;s:11:\"hizbQuarter\";i:126;s:5:\"sajda\";b:0;}i:79;a:9:{s:6:\"number\";i:2428;s:4:\"text\";s:312:\"یَـٰبَنِیۤ إِسۡرَ ٰ⁠ۤءِیلَ قَدۡ أَنجَیۡنَـٰكُم مِّنۡ عَدُوِّكُمۡ وَوَ ٰ⁠عَدۡنَـٰكُمۡ جَانِبَ ٱلطُّورِ ٱلۡأَیۡمَنَ وَنَزَّلۡنَا عَلَیۡكُمُ ٱلۡمَنَّ وَٱلسَّلۡوَىٰ\n\";s:13:\"numberInSurah\";i:80;s:3:\"juz\";i:16;s:6:\"manzil\";i:4;s:4:\"page\";i:317;s:4:\"ruku\";i:273;s:11:\"hizbQuarter\";i:126;s:5:\"sajda\";b:0;}i:80;a:9:{s:6:\"number\";i:2429;s:4:\"text\";s:267:\"كُلُوا۟ مِن طَیِّبَـٰتِ مَا رَزَقۡنَـٰكُمۡ وَلَا تَطۡغَوۡا۟ فِیهِ فَیَحِلَّ عَلَیۡكُمۡ غَضَبِیۖ وَمَن یَحۡلِلۡ عَلَیۡهِ غَضَبِی فَقَدۡ هَوَىٰ\n\";s:13:\"numberInSurah\";i:81;s:3:\"juz\";i:16;s:6:\"manzil\";i:4;s:4:\"page\";i:317;s:4:\"ruku\";i:273;s:11:\"hizbQuarter\";i:126;s:5:\"sajda\";b:0;}i:81;a:9:{s:6:\"number\";i:2430;s:4:\"text\";s:149:\"وَإِنِّی لَغَفَّارࣱ لِّمَن تَابَ وَءَامَنَ وَعَمِلَ صَـٰلِحࣰا ثُمَّ ٱهۡتَدَىٰ\n\";s:13:\"numberInSurah\";i:82;s:3:\"juz\";i:16;s:6:\"manzil\";i:4;s:4:\"page\";i:317;s:4:\"ruku\";i:273;s:11:\"hizbQuarter\";i:126;s:5:\"sajda\";b:0;}i:82;a:9:{s:6:\"number\";i:2431;s:4:\"text\";s:84:\"۞ وَمَاۤ أَعۡجَلَكَ عَن قَوۡمِكَ یَـٰمُوسَىٰ\n\";s:13:\"numberInSurah\";i:83;s:3:\"juz\";i:16;s:6:\"manzil\";i:4;s:4:\"page\";i:317;s:4:\"ruku\";i:273;s:11:\"hizbQuarter\";i:127;s:5:\"sajda\";b:0;}i:83;a:9:{s:6:\"number\";i:2432;s:4:\"text\";s:141:\"قَالَ هُمۡ أُو۟لَاۤءِ عَلَىٰۤ أَثَرِی وَعَجِلۡتُ إِلَیۡكَ رَبِّ لِتَرۡضَىٰ\n\";s:13:\"numberInSurah\";i:84;s:3:\"juz\";i:16;s:6:\"manzil\";i:4;s:4:\"page\";i:317;s:4:\"ruku\";i:273;s:11:\"hizbQuarter\";i:127;s:5:\"sajda\";b:0;}i:84;a:9:{s:6:\"number\";i:2433;s:4:\"text\";s:151:\"قَالَ فَإِنَّا قَدۡ فَتَنَّا قَوۡمَكَ مِنۢ بَعۡدِكَ وَأَضَلَّهُمُ ٱلسَّامِرِیُّ\n\";s:13:\"numberInSurah\";i:85;s:3:\"juz\";i:16;s:6:\"manzil\";i:4;s:4:\"page\";i:317;s:4:\"ruku\";i:273;s:11:\"hizbQuarter\";i:127;s:5:\"sajda\";b:0;}i:85;a:9:{s:6:\"number\";i:2434;s:4:\"text\";s:446:\"فَرَجَعَ مُوسَىٰۤ إِلَىٰ قَوۡمِهِۦ غَضۡبَـٰنَ أَسِفࣰاۚ قَالَ یَـٰقَوۡمِ أَلَمۡ یَعِدۡكُمۡ رَبُّكُمۡ وَعۡدًا حَسَنًاۚ أَفَطَالَ عَلَیۡكُمُ ٱلۡعَهۡدُ أَمۡ أَرَدتُّمۡ أَن یَحِلَّ عَلَیۡكُمۡ غَضَبࣱ مِّن رَّبِّكُمۡ فَأَخۡلَفۡتُم مَّوۡعِدِی\n\";s:13:\"numberInSurah\";i:86;s:3:\"juz\";i:16;s:6:\"manzil\";i:4;s:4:\"page\";i:317;s:4:\"ruku\";i:273;s:11:\"hizbQuarter\";i:127;s:5:\"sajda\";b:0;}i:86;a:9:{s:6:\"number\";i:2435;s:4:\"text\";s:308:\"قَالُوا۟ مَاۤ أَخۡلَفۡنَا مَوۡعِدَكَ بِمَلۡكِنَا وَلَـٰكِنَّا حُمِّلۡنَاۤ أَوۡزَارࣰا مِّن زِینَةِ ٱلۡقَوۡمِ فَقَذَفۡنَـٰهَا فَكَذَ ٰ⁠لِكَ أَلۡقَى ٱلسَّامِرِیُّ\n\";s:13:\"numberInSurah\";i:87;s:3:\"juz\";i:16;s:6:\"manzil\";i:4;s:4:\"page\";i:317;s:4:\"ruku\";i:273;s:11:\"hizbQuarter\";i:127;s:5:\"sajda\";b:0;}i:87;a:9:{s:6:\"number\";i:2436;s:4:\"text\";s:211:\"فَأَخۡرَجَ لَهُمۡ عِجۡلࣰا جَسَدࣰا لَّهُۥ خُوَارࣱ فَقَالُوا۟ هَـٰذَاۤ إِلَـٰهُكُمۡ وَإِلَـٰهُ مُوسَىٰ فَنَسِیَ\n\";s:13:\"numberInSurah\";i:88;s:3:\"juz\";i:16;s:6:\"manzil\";i:4;s:4:\"page\";i:318;s:4:\"ruku\";i:273;s:11:\"hizbQuarter\";i:127;s:5:\"sajda\";b:0;}i:88;a:9:{s:6:\"number\";i:2437;s:4:\"text\";s:181:\"أَفَلَا یَرَوۡنَ أَلَّا یَرۡجِعُ إِلَیۡهِمۡ قَوۡلࣰا وَلَا یَمۡلِكُ لَهُمۡ ضَرࣰّا وَلَا نَفۡعࣰا\n\";s:13:\"numberInSurah\";i:89;s:3:\"juz\";i:16;s:6:\"manzil\";i:4;s:4:\"page\";i:318;s:4:\"ruku\";i:273;s:11:\"hizbQuarter\";i:127;s:5:\"sajda\";b:0;}i:89;a:9:{s:6:\"number\";i:2438;s:4:\"text\";s:280:\"وَلَقَدۡ قَالَ لَهُمۡ هَـٰرُونُ مِن قَبۡلُ یَـٰقَوۡمِ إِنَّمَا فُتِنتُم بِهِۦۖ وَإِنَّ رَبَّكُمُ ٱلرَّحۡمَـٰنُ فَٱتَّبِعُونِی وَأَطِیعُوۤا۟ أَمۡرِی\n\";s:13:\"numberInSurah\";i:90;s:3:\"juz\";i:16;s:6:\"manzil\";i:4;s:4:\"page\";i:318;s:4:\"ruku\";i:274;s:11:\"hizbQuarter\";i:127;s:5:\"sajda\";b:0;}i:90;a:9:{s:6:\"number\";i:2439;s:4:\"text\";s:149:\"قَالُوا۟ لَن نَّبۡرَحَ عَلَیۡهِ عَـٰكِفِینَ حَتَّىٰ یَرۡجِعَ إِلَیۡنَا مُوسَىٰ\n\";s:13:\"numberInSurah\";i:91;s:3:\"juz\";i:16;s:6:\"manzil\";i:4;s:4:\"page\";i:318;s:4:\"ruku\";i:274;s:11:\"hizbQuarter\";i:127;s:5:\"sajda\";b:0;}i:91;a:9:{s:6:\"number\";i:2440;s:4:\"text\";s:115:\"قَالَ یَـٰهَـٰرُونُ مَا مَنَعَكَ إِذۡ رَأَیۡتَهُمۡ ضَلُّوۤا۟\n\";s:13:\"numberInSurah\";i:92;s:3:\"juz\";i:16;s:6:\"manzil\";i:4;s:4:\"page\";i:318;s:4:\"ruku\";i:274;s:11:\"hizbQuarter\";i:127;s:5:\"sajda\";b:0;}i:92;a:9:{s:6:\"number\";i:2441;s:4:\"text\";s:78:\"أَلَّا تَتَّبِعَنِۖ أَفَعَصَیۡتَ أَمۡرِی\n\";s:13:\"numberInSurah\";i:93;s:3:\"juz\";i:16;s:6:\"manzil\";i:4;s:4:\"page\";i:318;s:4:\"ruku\";i:274;s:11:\"hizbQuarter\";i:127;s:5:\"sajda\";b:0;}i:93;a:9:{s:6:\"number\";i:2442;s:4:\"text\";s:288:\"قَالَ یَبۡنَؤُمَّ لَا تَأۡخُذۡ بِلِحۡیَتِی وَلَا بِرَأۡسِیۤۖ إِنِّی خَشِیتُ أَن تَقُولَ فَرَّقۡتَ بَیۡنَ بَنِیۤ إِسۡرَ ٰ⁠ۤءِیلَ وَلَمۡ تَرۡقُبۡ قَوۡلِی\n\";s:13:\"numberInSurah\";i:94;s:3:\"juz\";i:16;s:6:\"manzil\";i:4;s:4:\"page\";i:318;s:4:\"ruku\";i:274;s:11:\"hizbQuarter\";i:127;s:5:\"sajda\";b:0;}i:94;a:9:{s:6:\"number\";i:2443;s:4:\"text\";s:70:\"قَالَ فَمَا خَطۡبُكَ یَـٰسَـٰمِرِیُّ\n\";s:13:\"numberInSurah\";i:95;s:3:\"juz\";i:16;s:6:\"manzil\";i:4;s:4:\"page\";i:318;s:4:\"ruku\";i:274;s:11:\"hizbQuarter\";i:127;s:5:\"sajda\";b:0;}i:95;a:9:{s:6:\"number\";i:2444;s:4:\"text\";s:263:\"قَالَ بَصُرۡتُ بِمَا لَمۡ یَبۡصُرُوا۟ بِهِۦ فَقَبَضۡتُ قَبۡضَةࣰ مِّنۡ أَثَرِ ٱلرَّسُولِ فَنَبَذۡتُهَا وَكَذَ ٰ⁠لِكَ سَوَّلَتۡ لِی نَفۡسِی\n\";s:13:\"numberInSurah\";i:96;s:3:\"juz\";i:16;s:6:\"manzil\";i:4;s:4:\"page\";i:318;s:4:\"ruku\";i:274;s:11:\"hizbQuarter\";i:127;s:5:\"sajda\";b:0;}i:96;a:9:{s:6:\"number\";i:2445;s:4:\"text\";s:444:\"قَالَ فَٱذۡهَبۡ فَإِنَّ لَكَ فِی ٱلۡحَیَوٰةِ أَن تَقُولَ لَا مِسَاسَۖ وَإِنَّ لَكَ مَوۡعِدࣰا لَّن تُخۡلَفَهُۥۖ وَٱنظُرۡ إِلَىٰۤ إِلَـٰهِكَ ٱلَّذِی ظَلۡتَ عَلَیۡهِ ع