('quranapp-cache-surah_21_ar.uthmani', 'a:8:{s:6:\"number\";i:21;s:4:\"name\";s:39:\"سُورَةُ الأَنبِيَاءِ\";s:11:\"englishName\";s:10:\"Al-Anbiyaa\";s:22:\"englishNameTranslation\";s:12:\"The Prophets\";s:14:\"revelationType\";s:6:\"Meccan\";s:13:\"numberOfAyahs\";i:112;s:5:\"ayahs\";a:112:{i:0;a:9:{s:6:\"number\";i:2484;s:4:\"text\";s:200:\"بِسۡمِ ٱللَّهِ ٱلرَّحۡمَـٰنِ ٱلرَّحِیمِ ٱقۡتَرَبَ لِلنَّاسِ حِسَابُهُمۡ وَهُمۡ فِی غَفۡلَةࣲ مُّعۡرِضُونَ\n\";s:13:\"numberInSurah\";i:1;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:322;s:4:\"ruku\";i:278;s:11:\"hizbQuarter\";i:129;s:5:\"sajda\";b:0;}i:1;a:9:{s:6:\"number\";i:2485;s:4:\"text\";s:172:\"مَا یَأۡتِیهِم مِّن ذِكۡرࣲ مِّن رَّبِّهِم مُّحۡدَثٍ إِلَّا ٱسۡتَمَعُوهُ وَهُمۡ یَلۡعَبُونَ\n\";s:13:\"numberInSurah\";i:2;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:322;s:4:\"ruku\";i:278;s:11:\"hizbQuarter\";i:129;s:5:\"sajda\";b:0;}i:2;a:9:{s:6:\"number\";i:2486;s:4:\"text\";s:295:\"لَاهِیَةࣰ قُلُوبُهُمۡۗ وَأَسَرُّوا۟ ٱلنَّجۡوَى ٱلَّذِینَ ظَلَمُوا۟ هَلۡ هَـٰذَاۤ إِلَّا بَشَرࣱ مِّثۡلُكُمۡۖ أَفَتَأۡتُونَ ٱلسِّحۡرَ وَأَنتُمۡ تُبۡصِرُونَ\n\";s:13:\"numberInSurah\";i:3;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:322;s:4:\"ruku\";i:278;s:11:\"hizbQuarter\";i:129;s:5:\"sajda\";b:0;}i:3;a:9:{s:6:\"number\";i:2487;s:4:\"text\";s:170:\"قَالَ رَبِّی یَعۡلَمُ ٱلۡقَوۡلَ فِی ٱلسَّمَاۤءِ وَٱلۡأَرۡضِۖ وَهُوَ ٱلسَّمِیعُ ٱلۡعَلِیمُ\n\";s:13:\"numberInSurah\";i:4;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:322;s:4:\"ruku\";i:278;s:11:\"hizbQuarter\";i:129;s:5:\"sajda\";b:0;}i:4;a:9:{s:6:\"number\";i:2488;s:4:\"text\";s:244:\"بَلۡ قَالُوۤا۟ أَضۡغَـٰثُ أَحۡلَـٰمِۭ بَلِ ٱفۡتَرَىٰهُ بَلۡ هُوَ شَاعِرࣱ فَلۡیَأۡتِنَا بِـَٔایَةࣲ كَمَاۤ أُرۡسِلَ ٱلۡأَوَّلُونَ\n\";s:13:\"numberInSurah\";i:5;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:322;s:4:\"ruku\";i:278;s:11:\"hizbQuarter\";i:129;s:5:\"sajda\";b:0;}i:5;a:9:{s:6:\"number\";i:2489;s:4:\"text\";s:148:\"مَاۤ ءَامَنَتۡ قَبۡلَهُم مِّن قَرۡیَةٍ أَهۡلَكۡنَـٰهَاۤۖ أَفَهُمۡ یُؤۡمِنُونَ\n\";s:13:\"numberInSurah\";i:6;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:322;s:4:\"ruku\";i:278;s:11:\"hizbQuarter\";i:129;s:5:\"sajda\";b:0;}i:6;a:9:{s:6:\"number\";i:2490;s:4:\"text\";s:235:\"وَمَاۤ أَرۡسَلۡنَا قَبۡلَكَ إِلَّا رِجَالࣰا نُّوحِیۤ إِلَیۡهِمۡۖ فَسۡـَٔلُوۤا۟ أَهۡلَ ٱلذِّكۡرِ إِن كُنتُمۡ لَا تَعۡلَمُونَ\n\";s:13:\"numberInSurah\";i:7;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:322;s:4:\"ruku\";i:278;s:11:\"hizbQuarter\";i:129;s:5:\"sajda\";b:0;}i:7;a:9:{s:6:\"number\";i:2491;s:4:\"text\";s:160:\"وَمَا جَعَلۡنَـٰهُمۡ جَسَدࣰا لَّا یَأۡكُلُونَ ٱلطَّعَامَ وَمَا كَانُوا۟ خَـٰلِدِینَ\n\";s:13:\"numberInSurah\";i:8;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:322;s:4:\"ruku\";i:278;s:11:\"hizbQuarter\";i:129;s:5:\"sajda\";b:0;}i:8;a:9:{s:6:\"number\";i:2492;s:4:\"text\";s:180:\"ثُمَّ صَدَقۡنَـٰهُمُ ٱلۡوَعۡدَ فَأَنجَیۡنَـٰهُمۡ وَمَن نَّشَاۤءُ وَأَهۡلَكۡنَا ٱلۡمُسۡرِفِینَ\n\";s:13:\"numberInSurah\";i:9;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:322;s:4:\"ruku\";i:278;s:11:\"hizbQuarter\";i:129;s:5:\"sajda\";b:0;}i:9;a:9:{s:6:\"number\";i:2493;s:4:\"text\";s:149:\"لَقَدۡ أَنزَلۡنَاۤ إِلَیۡكُمۡ كِتَـٰبࣰا فِیهِ ذِكۡرُكُمۡۚ أَفَلَا تَعۡقِلُونَ\n\";s:13:\"numberInSurah\";i:10;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:322;s:4:\"ruku\";i:278;s:11:\"hizbQuarter\";i:129;s:5:\"sajda\";b:0;}i:10;a:9:{s:6:\"number\";i:2494;s:4:\"text\";s:172:\"وَكَمۡ قَصَمۡنَا مِن قَرۡیَةࣲ كَانَتۡ ظَالِمَةࣰ وَأَنشَأۡنَا بَعۡدَهَا قَوۡمًا ءَاخَرِینَ\n\";s:13:\"numberInSurah\";i:11;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:323;s:4:\"ruku\";i:279;s:11:\"hizbQuarter\";i:129;s:5:\"sajda\";b:0;}i:11;a:9:{s:6:\"number\";i:2495;s:4:\"text\";s:119:\"فَلَمَّاۤ أَحَسُّوا۟ بَأۡسَنَاۤ إِذَا هُم مِّنۡهَا یَرۡكُضُونَ\n\";s:13:\"numberInSurah\";i:12;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:323;s:4:\"ruku\";i:279;s:11:\"hizbQuarter\";i:129;s:5:\"sajda\";b:0;}i:12;a:9:{s:6:\"number\";i:2496;s:4:\"text\";s:196:\"لَا تَرۡكُضُوا۟ وَٱرۡجِعُوۤا۟ إِلَىٰ مَاۤ أُتۡرِفۡتُمۡ فِیهِ وَمَسَـٰكِنِكُمۡ لَعَلَّكُمۡ تُسۡـَٔلُونَ\n\";s:13:\"numberInSurah\";i:13;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:323;s:4:\"ruku\";i:279;s:11:\"hizbQuarter\";i:129;s:5:\"sajda\";b:0;}i:13;a:9:{s:6:\"number\";i:2497;s:4:\"text\";s:95:\"قَالُوا۟ یَـٰوَیۡلَنَاۤ إِنَّا كُنَّا ظَـٰلِمِینَ\n\";s:13:\"numberInSurah\";i:14;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:323;s:4:\"ruku\";i:279;s:11:\"hizbQuarter\";i:129;s:5:\"sajda\";b:0;}i:14;a:9:{s:6:\"number\";i:2498;s:4:\"text\";s:148:\"فَمَا زَالَت تِّلۡكَ دَعۡوَىٰهُمۡ حَتَّىٰ جَعَلۡنَـٰهُمۡ حَصِیدًا خَـٰمِدِینَ\n\";s:13:\"numberInSurah\";i:15;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:323;s:4:\"ruku\";i:279;s:11:\"hizbQuarter\";i:129;s:5:\"sajda\";b:0;}i:15;a:9:{s:6:\"number\";i:2499;s:4:\"text\";s:133:\"وَمَا خَلَقۡنَا ٱلسَّمَاۤءَ وَٱلۡأَرۡضَ وَمَا بَیۡنَهُمَا لَـٰعِبِینَ\n\";s:13:\"numberInSurah\";i:16;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:323;s:4:\"ruku\";i:279;s:11:\"hizbQuarter\";i:129;s:5:\"sajda\";b:0;}i:16;a:9:{s:6:\"number\";i:2500;s:4:\"text\";s:180:\"لَوۡ أَرَدۡنَاۤ أَن نَّتَّخِذَ لَهۡوࣰا لَّٱتَّخَذۡنَـٰهُ مِن لَّدُنَّاۤ إِن كُنَّا فَـٰعِلِینَ\n\";s:13:\"numberInSurah\";i:17;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:323;s:4:\"ruku\";i:279;s:11:\"hizbQuarter\";i:129;s:5:\"sajda\";b:0;}i:17;a:9:{s:6:\"number\";i:2501;s:4:\"text\";s:218:\"بَلۡ نَقۡذِفُ بِٱلۡحَقِّ عَلَى ٱلۡبَـٰطِلِ فَیَدۡمَغُهُۥ فَإِذَا هُوَ زَاهِقࣱۚ وَلَكُمُ ٱلۡوَیۡلُ مِمَّا تَصِفُونَ\n\";s:13:\"numberInSurah\";i:18;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:323;s:4:\"ruku\";i:279;s:11:\"hizbQuarter\";i:129;s:5:\"sajda\";b:0;}i:18;a:9:{s:6:\"number\";i:2502;s:4:\"text\";s:233:\"وَلَهُۥ مَن فِی ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِۚ وَمَنۡ عِندَهُۥ لَا یَسۡتَكۡبِرُونَ عَنۡ عِبَادَتِهِۦ وَلَا یَسۡتَحۡسِرُونَ\n\";s:13:\"numberInSurah\";i:19;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:323;s:4:\"ruku\";i:279;s:11:\"hizbQuarter\";i:129;s:5:\"sajda\";b:0;}i:19;a:9:{s:6:\"number\";i:2503;s:4:\"text\";s:97:\"یُسَبِّحُونَ ٱلَّیۡلَ وَٱلنَّهَارَ لَا یَفۡتُرُونَ\n\";s:13:\"numberInSurah\";i:20;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:323;s:4:\"ruku\";i:279;s:11:\"hizbQuarter\";i:129;s:5:\"sajda\";b:0;}i:20;a:9:{s:6:\"number\";i:2504;s:4:\"text\";s:114:\"أَمِ ٱتَّخَذُوۤا۟ ءَالِهَةࣰ مِّنَ ٱلۡأَرۡضِ هُمۡ یُنشِرُونَ\n\";s:13:\"numberInSurah\";i:21;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:323;s:4:\"ruku\";i:279;s:11:\"hizbQuarter\";i:129;s:5:\"sajda\";b:0;}i:21;a:9:{s:6:\"number\";i:2505;s:4:\"text\";s:213:\"لَوۡ كَانَ فِیهِمَاۤ ءَالِهَةٌ إِلَّا ٱللَّهُ لَفَسَدَتَاۚ فَسُبۡحَـٰنَ ٱللَّهِ رَبِّ ٱلۡعَرۡشِ عَمَّا یَصِفُونَ\n\";s:13:\"numberInSurah\";i:22;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:323;s:4:\"ruku\";i:279;s:11:\"hizbQuarter\";i:129;s:5:\"sajda\";b:0;}i:22;a:9:{s:6:\"number\";i:2506;s:4:\"text\";s:94:\"لَا یُسۡـَٔلُ عَمَّا یَفۡعَلُ وَهُمۡ یُسۡـَٔلُونَ\n\";s:13:\"numberInSurah\";i:23;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:323;s:4:\"ruku\";i:279;s:11:\"hizbQuarter\";i:129;s:5:\"sajda\";b:0;}i:23;a:9:{s:6:\"number\";i:2507;s:4:\"text\";s:347:\"أَمِ ٱتَّخَذُوا۟ مِن دُونِهِۦۤ ءَالِهَةࣰۖ قُلۡ هَاتُوا۟ بُرۡهَـٰنَكُمۡۖ هَـٰذَا ذِكۡرُ مَن مَّعِیَ وَذِكۡرُ مَن قَبۡلِیۚ بَلۡ أَكۡثَرُهُمۡ لَا یَعۡلَمُونَ ٱلۡحَقَّۖ فَهُم مُّعۡرِضُونَ\n\";s:13:\"numberInSurah\";i:24;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:323;s:4:\"ruku\";i:279;s:11:\"hizbQuarter\";i:129;s:5:\"sajda\";b:0;}i:24;a:9:{s:6:\"number\";i:2508;s:4:\"text\";s:225:\"وَمَاۤ أَرۡسَلۡنَا مِن قَبۡلِكَ مِن رَّسُولٍ إِلَّا نُوحِیۤ إِلَیۡهِ أَنَّهُۥ لَاۤ إِلَـٰهَ إِلَّاۤ أَنَا۠ فَٱعۡبُدُونِ\n\";s:13:\"numberInSurah\";i:25;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:324;s:4:\"ruku\";i:279;s:11:\"hizbQuarter\";i:129;s:5:\"sajda\";b:0;}i:25;a:9:{s:6:\"number\";i:2509;s:4:\"text\";s:162:\"وَقَالُوا۟ ٱتَّخَذَ ٱلرَّحۡمَـٰنُ وَلَدࣰاۗ سُبۡحَـٰنَهُۥۚ بَلۡ عِبَادࣱ مُّكۡرَمُونَ\n\";s:13:\"numberInSurah\";i:26;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page