;b:0;}i:16;a:9:{s:6:\"number\";i:2612;s:4:\"text\";s:415:\"إِنَّ ٱلَّذِینَ ءَامَنُوا۟ وَٱلَّذِینَ هَادُوا۟ وَٱلصَّـٰبِـِٔینَ وَٱلنَّصَـٰرَىٰ وَٱلۡمَجُوسَ وَٱلَّذِینَ أَشۡرَكُوۤا۟ إِنَّ ٱللَّهَ یَفۡصِلُ بَیۡنَهُمۡ یَوۡمَ ٱلۡقِیَـٰمَةِۚ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَیۡءࣲ شَهِیدٌ\n\";s:13:\"numberInSurah\";i:17;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:334;s:4:\"ruku\";i:286;s:11:\"hizbQuarter\";i:133;s:5:\"sajda\";b:0;}i:17;a:9:{s:6:\"number\";i:2613;s:4:\"text\";s:589:\"أَلَمۡ تَرَ أَنَّ ٱللَّهَ یَسۡجُدُ لَهُۥ مَن فِی ٱلسَّمَـٰوَ ٰ⁠تِ وَمَن فِی ٱلۡأَرۡضِ وَٱلشَّمۡسُ وَٱلۡقَمَرُ وَٱلنُّجُومُ وَٱلۡجِبَالُ وَٱلشَّجَرُ وَٱلدَّوَاۤبُّ وَكَثِیرࣱ مِّنَ ٱلنَّاسِۖ وَكَثِیرٌ حَقَّ عَلَیۡهِ ٱلۡعَذَابُۗ وَمَن یُهِنِ ٱللَّهُ فَمَا لَهُۥ مِن مُّكۡرِمٍۚ إِنَّ ٱللَّهَ یَفۡعَلُ مَا یَشَاۤءُ ۩\n\";s:13:\"numberInSurah\";i:18;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:334;s:4:\"ruku\";i:286;s:11:\"hizbQuarter\";i:133;s:5:\"sajda\";a:3:{s:2:\"id\";i:6;s:11:\"recommended\";b:1;s:10:\"obligatory\";b:0;}}i:18;a:9:{s:6:\"number\";i:2614;s:4:\"text\";s:286:\"۞ هَـٰذَانِ خَصۡمَانِ ٱخۡتَصَمُوا۟ فِی رَبِّهِمۡۖ فَٱلَّذِینَ كَفَرُوا۟ قُطِّعَتۡ لَهُمۡ ثِیَابࣱ مِّن نَّارࣲ یُصَبُّ مِن فَوۡقِ رُءُوسِهِمُ ٱلۡحَمِیمُ\n\";s:13:\"numberInSurah\";i:19;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:334;s:4:\"ruku\";i:286;s:11:\"hizbQuarter\";i:134;s:5:\"sajda\";b:0;}i:19;a:9:{s:6:\"number\";i:2615;s:4:\"text\";s:90:\"یُصۡهَرُ بِهِۦ مَا فِی بُطُونِهِمۡ وَٱلۡجُلُودُ\n\";s:13:\"numberInSurah\";i:20;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:334;s:4:\"ruku\";i:286;s:11:\"hizbQuarter\";i:134;s:5:\"sajda\";b:0;}i:20;a:9:{s:6:\"number\";i:2616;s:4:\"text\";s:63:\"وَلَهُم مَّقَـٰمِعُ مِنۡ حَدِیدࣲ\n\";s:13:\"numberInSurah\";i:21;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:334;s:4:\"ruku\";i:286;s:11:\"hizbQuarter\";i:134;s:5:\"sajda\";b:0;}i:21;a:9:{s:6:\"number\";i:2617;s:4:\"text\";s:198:\"كُلَّمَاۤ أَرَادُوۤا۟ أَن یَخۡرُجُوا۟ مِنۡهَا مِنۡ غَمٍّ أُعِیدُوا۟ فِیهَا وَذُوقُوا۟ عَذَابَ ٱلۡحَرِیقِ\n\";s:13:\"numberInSurah\";i:22;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:334;s:4:\"ruku\";i:286;s:11:\"hizbQuarter\";i:134;s:5:\"sajda\";b:0;}i:22;a:9:{s:6:\"number\";i:2618;s:4:\"text\";s:392:\"إِنَّ ٱللَّهَ یُدۡخِلُ ٱلَّذِینَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ جَنَّـٰتࣲ تَجۡرِی مِن تَحۡتِهَا ٱلۡأَنۡهَـٰرُ یُحَلَّوۡنَ فِیهَا مِنۡ أَسَاوِرَ مِن ذَهَبࣲ وَلُؤۡلُؤࣰاۖ وَلِبَاسُهُمۡ فِیهَا حَرِیرࣱ\n\";s:13:\"numberInSurah\";i:23;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:334;s:4:\"ruku\";i:287;s:11:\"hizbQuarter\";i:134;s:5:\"sajda\";b:0;}i:23;a:9:{s:6:\"number\";i:2619;s:4:\"text\";s:157:\"وَهُدُوۤا۟ إِلَى ٱلطَّیِّبِ مِنَ ٱلۡقَوۡلِ وَهُدُوۤا۟ إِلَىٰ صِرَ ٰ⁠طِ ٱلۡحَمِیدِ\n\";s:13:\"numberInSurah\";i:24;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:335;s:4:\"ruku\";i:287;s:11:\"hizbQuarter\";i:134;s:5:\"sajda\";b:0;}i:24;a:9:{s:6:\"number\";i:2620;s:4:\"text\";s:429:\"إِنَّ ٱلَّذِینَ كَفَرُوا۟ وَیَصُدُّونَ عَن سَبِیلِ ٱللَّهِ وَٱلۡمَسۡجِدِ ٱلۡحَرَامِ ٱلَّذِی جَعَلۡنَـٰهُ لِلنَّاسِ سَوَاۤءً ٱلۡعَـٰكِفُ فِیهِ وَٱلۡبَادِۚ وَمَن یُرِدۡ فِیهِ بِإِلۡحَادِۭ بِظُلۡمࣲ نُّذِقۡهُ مِنۡ عَذَابٍ أَلِیمࣲ\n\";s:13:\"numberInSurah\";i:25;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:335;s:4:\"ruku\";i:287;s:11:\"hizbQuarter\";i:134;s:5:\"sajda\";b:0;}i:25;a:9:{s:6:\"number\";i:2621;s:4:\"text\";s:311:\"وَإِذۡ بَوَّأۡنَا لِإِبۡرَ ٰ⁠هِیمَ مَكَانَ ٱلۡبَیۡتِ أَن لَّا تُشۡرِكۡ بِی شَیۡـࣰٔا وَطَهِّرۡ بَیۡتِیَ لِلطَّاۤىِٕفِینَ وَٱلۡقَاۤىِٕمِینَ وَٱلرُّكَّعِ ٱلسُّجُودِ\n\";s:13:\"numberInSurah\";i:26;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:335;s:4:\"ruku\";i:288;s:11:\"hizbQuarter\";i:134;s:5:\"sajda\";b:0;}i:26;a:9:{s:6:\"number\";i:2622;s:4:\"text\";s:207:\"وَأَذِّن فِی ٱلنَّاسِ بِٱلۡحَجِّ یَأۡتُوكَ رِجَالࣰا وَعَلَىٰ كُلِّ ضَامِرࣲ یَأۡتِینَ مِن كُلِّ فَجٍّ عَمِیقࣲ\n\";s:13:\"numberInSurah\";i:27;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:335;s:4:\"ruku\";i:288;s:11:\"hizbQuarter\";i:134;s:5:\"sajda\";b:0;}i:27;a:9:{s:6:\"number\";i:2623;s:4:\"text\";s:377:\"لِّیَشۡهَدُوا۟ مَنَـٰفِعَ لَهُمۡ وَیَذۡكُرُوا۟ ٱسۡمَ ٱللَّهِ فِیۤ أَیَّامࣲ مَّعۡلُومَـٰتٍ عَلَىٰ مَا رَزَقَهُم مِّنۢ بَهِیمَةِ ٱلۡأَنۡعَـٰمِۖ فَكُلُوا۟ مِنۡهَا وَأَطۡعِمُوا۟ ٱلۡبَاۤىِٕسَ ٱلۡفَقِیرَ\n\";s:13:\"numberInSurah\";i:28;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:335;s:4:\"ruku\";i:288;s:11:\"hizbQuarter\";i:134;s:5:\"sajda\";b:0;}i:28;a:9:{s:6:\"number\";i:2624;s:4:\"text\";s:182:\"ثُمَّ لۡیَقۡضُوا۟ تَفَثَهُمۡ وَلۡیُوفُوا۟ نُذُورَهُمۡ وَلۡیَطَّوَّفُوا۟ بِٱلۡبَیۡتِ ٱلۡعَتِیقِ\n\";s:13:\"numberInSurah\";i:29;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:335;s:4:\"ruku\";i:288;s:11:\"hizbQuarter\";i:134;s:5:\"sajda\";b:0;}i:29;a:9:{s:6:\"number\";i:2625;s:4:\"text\";s:425:\"ذَ ٰ⁠لِكَۖ وَمَن یُعَظِّمۡ حُرُمَـٰتِ ٱللَّهِ فَهُوَ خَیۡرࣱ لَّهُۥ عِندَ رَبِّهِۦۗ وَأُحِلَّتۡ لَكُمُ ٱلۡأَنۡعَـٰمُ إِلَّا مَا یُتۡلَىٰ عَلَیۡكُمۡۖ فَٱجۡتَنِبُوا۟ ٱلرِّجۡسَ مِنَ ٱلۡأَوۡثَـٰنِ وَٱجۡتَنِبُوا۟ قَوۡلَ ٱلزُّورِ\n\";s:13:\"numberInSurah\";i:30;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:335;s:4:\"ruku\";i:288;s:11:\"hizbQuarter\";i:134;s:5:\"sajda\";b:0;}i:30;a:9:{s:6:\"number\";i:2626;s:4:\"text\";s:333:\"حُنَفَاۤءَ لِلَّهِ غَیۡرَ مُشۡرِكِینَ بِهِۦۚ وَمَن یُشۡرِكۡ بِٱللَّهِ فَكَأَنَّمَا خَرَّ مِنَ ٱلسَّمَاۤءِ فَتَخۡطَفُهُ ٱلطَّیۡرُ أَوۡ تَهۡوِی بِهِ ٱلرِّیحُ فِی مَكَانࣲ سَحِیقࣲ\n\";s:13:\"numberInSurah\";i:31;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:336;s:4:\"ruku\";i:288;s:11:\"hizbQuarter\";i:134;s:5:\"sajda\";b:0;}i:31;a:9:{s:6:\"number\";i:2627;s:4:\"text\";s:157:\"ذَ ٰ⁠لِكَۖ وَمَن یُعَظِّمۡ شَعَـٰۤىِٕرَ ٱللَّهِ فَإِنَّهَا مِن تَقۡوَى ٱلۡقُلُوبِ\n\";s:13:\"numberInSurah\";i:32;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:336;s:4:\"ruku\";i:288;s:11:\"hizbQuarter\";i:134;s:5:\"sajda\";b:0;}i:32;a:9:{s:6:\"number\";i:2628;s:4:\"text\";s:181:\"لَكُمۡ فِیهَا مَنَـٰفِعُ إِلَىٰۤ أَجَلࣲ مُّسَمࣰّى ثُمَّ مَحِلُّهَاۤ إِلَى ٱلۡبَیۡتِ ٱلۡعَتِیقِ\n\";s:13:\"numberInSurah\";i:33;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:336;s:4:\"ruku\";i:288;s:11:\"hizbQuarter\";i:134;s:5:\"sajda\";b:0;}i:33;a:9:{s:6:\"number\";i:2629;s:4:\"text\";s:384:\"وَلِكُلِّ أُمَّةࣲ جَعَلۡنَا مَنسَكࣰا لِّیَذۡكُرُوا۟ ٱسۡمَ ٱللَّهِ عَلَىٰ مَا رَزَقَهُم مِّنۢ بَهِیمَةِ ٱلۡأَنۡعَـٰمِۗ فَإِلَـٰهُكُمۡ إِلَـٰهࣱ وَ ٰ⁠حِدࣱ فَلَهُۥۤ أَسۡلِمُوا۟ۗ وَبَشِّرِ ٱلۡمُخۡبِتِینَ\n\";s:13:\"numberInSurah\";i:34;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:336;s:4:\"ruku\";i:289;s:11:\"hizbQuarter\";i:134;s:5:\"sajda\";b:0;}i:34;a:9:{s:6:\"number\";i:2630;s:4:\"text\";s:293:\"ٱلَّذِینَ إِذَا ذُكِرَ ٱللَّهُ وَجِلَتۡ قُلُوبُهُمۡ وَٱلصَّـٰبِرِینَ عَلَىٰ مَاۤ أَصَابَهُمۡ وَٱلۡمُقِیمِی ٱلصَّلَوٰةِ وَمِمَّا رَزَقۡنَـٰهُمۡ یُنفِقُونَ\n\";s:13:\"numberInSurah\";i:35;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:336;s:4:\"ruku\";i:289;s:11:\"hizbQuarter\";i:134;s:5:\"sajda\";b:0;}i:35;a:9:{s:6:\"number\";i:2631;s:4:\"text\";s:522:\"وَٱلۡبُدۡنَ جَعَلۡنَـٰهَا لَكُم مِّن شَعَـٰۤىِٕرِ ٱللَّهِ لَكُمۡ فِیهَا خَیۡرࣱۖ فَٱذۡكُرُوا۟ ٱسۡمَ ٱللَّهِ عَلَیۡهَا صَوَاۤفَّۖ فَإِذَا وَجَبَتۡ جُنُوبُهَا فَكُلُوا۟ مِنۡهَا وَأَطۡعِمُوا۟ ٱلۡقَانِعَ وَٱلۡمُعۡتَرَّۚ كَذَ ٰ⁠لِكَ سَخَّرۡنَـٰهَا لَكُمۡ لَعَلَّكُمۡ تَشۡكُرُونَ\n\";s:13:\"numberInSurah\";i:36;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:336;s:4:\"ruku\";i:289;s:11:\"hizbQuarter\";i:134;s:5:\"sajda\";b:0;}i:36;a:9:{s:6:\"number\";i:2632;s:4:\"text\";s:364:\"لَن یَنَالَ ٱللَّهَ لُحُومُهَا وَلَا دِمَاۤؤُهَا وَلَـٰكِن یَنَالُهُ ٱلتَّقۡوَىٰ مِنكُمۡۚ كَذَ ٰ⁠لِكَ سَخَّرَهَا لَكُمۡ لِتُكَبِّرُوا۟ ٱللَّهَ عَلَىٰ مَا هَدَىٰكُمۡۗ وَبَشِّرِ ٱلۡمُحۡسِنِینَ\n\";s:13:\"numberInSurah\";i:37;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:336;s:4:\"ruku\";i:289;s:11:\"hizbQuarter\";i:134;s:5:\"sajda\";b:0;}i:37;a:9:{s:6:\"number\";i:2633;s:4:\"text\";s:199:\"۞ إِنَّ ٱللَّهَ یُدَ ٰ⁠فِعُ عَنِ ٱلَّذِینَ ءَامَنُوۤا۟ۗ إِنَّ ٱللَّهَ لَا یُحِبُّ كُلَّ خَوَّانࣲ كَفُورٍ\n\";s:13:\"numberInSurah\";i:38;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:336;s:4:\"ruku\";i:289;s:11:\"hizbQuarter\";i:135;s:5:\"sajda\";b:0;}i:38;a:9:{s:6:\"number\";i:2634;s:4:\"text\";s:188:\"أُذِنَ لِلَّذِینَ یُقَـٰتَلُونَ بِأَنَّهُمۡ ظُلِمُوا۟ۚ وَإِنَّ ٱللَّهَ عَلَىٰ نَصۡرِهِمۡ لَقَدِیرٌ\n\";s:13:\"numberInSurah\";i:39;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:337;s:4:\"ruku\";i:290;s:11:\"hizbQuarter\";i:135;s:5:\"sajda\";b:0;}i:39;a:9:{s:6:\"number\";i:2635;s:4:\"text\";s:613:\"ٱلَّذِینَ أُخۡرِجُوا۟ مِن دِیَـٰرِهِم بِغَیۡرِ حَقٍّ إِلَّاۤ أَن یَقُولُوا۟ رَبُّنَا ٱللَّهُۗ وَلَوۡلَا دَفۡعُ ٱللَّهِ ٱلنَّاسَ بَعۡضَهُم بِبَعۡضࣲ لَّهُدِّمَتۡ صَوَ ٰ⁠مِعُ وَبِیَعࣱ وَصَلَوَ ٰ⁠تࣱ وَمَسَـٰجِدُ یُذۡكَرُ فِیهَا ٱسۡمُ ٱللَّهِ كَثِیرࣰاۗ وَلَیَنصُرَنَّ ٱللَّهُ مَن یَنصُرُهُۥۤۚ إِنَّ ٱللَّهَ لَقَوِیٌّ عَزِیزٌ\n\";s:13:\"numberInSurah\";i:40;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:337;s:4:\"ruku\";i:290;s:11:\"hizbQuarter\";i:135;s:5:\"sajda\";b:0;}i:40;a:9:{s:6:\"number\";i:2636;s:4:\"text\";s:339:\"ٱلَّذِینَ إِن مَّكَّنَّـٰهُمۡ فِی ٱلۡأَرۡضِ أَقَامُوا۟ ٱلصَّلَوٰةَ وَءَاتَوُا۟ ٱلزَّكَوٰةَ وَأَمَرُوا۟ بِٱلۡمَعۡرُوفِ وَنَهَوۡا۟ عَنِ ٱلۡمُنكَرِۗ وَلِلَّهِ عَـٰقِبَةُ ٱلۡأُمُورِ\n\";s:13:\"numberInSurah\";i:41;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:337;s:4:\"ruku\";i:290;s:11:\"hizbQuarter\";i:135;s:5:\"sajda\";b:0;}i:41;a:9:{s:6:\"number\";i:2637;s:4:\"text\";s:149:\"وَإِن یُكَذِّبُوكَ فَقَدۡ كَذَّبَتۡ قَبۡلَهُمۡ قَوۡمُ نُوحࣲ وَعَادࣱ وَثَمُودُ\n\";s:13:\"numberInSurah\";i:42;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:337;s:4:\"ruku\";i:290;s:11:\"hizbQuarter\";i:135;s:5:\"sajda\";b:0;}i:42;a:9:{s:6:\"number\";i:2638;s:4:\"text\";s:77:\"وَقَوۡمُ إِبۡرَ ٰ⁠هِیمَ وَقَوۡمُ لُوطࣲ\n\";s:13:\"numberInSurah\";i:43;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:337;s:4:\"ruku\";i:290;s:11:\"hizbQuarter\";i:135;s:5:\"sajda\";b:0;}i:43;a:9:{s:6:\"number\";i:2639;s:4:\"text\";s:217:\"وَأَصۡحَـٰبُ مَدۡیَنَۖ وَكُذِّبَ مُوسَىٰۖ فَأَمۡلَیۡتُ لِلۡكَـٰفِرِینَ ثُمَّ أَخَذۡتُهُمۡۖ فَكَیۡفَ كَانَ نَكِیرِ\n\";s:13:\"numberInSurah\";i:44;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:337;s:4:\"ruku\";i:290;s:11:\"hizbQuarter\";i:135;s:5:\"sajda\";b:0;}i:44;a:9:{s:6:\"number\";i:2640;s:4:\"text\";s:256:\"فَكَأَیِّن مِّن قَرۡیَةٍ أَهۡلَكۡنَـٰهَا وَهِیَ ظَالِمَةࣱ فَهِیَ خَاوِیَةٌ عَلَىٰ عُرُوشِهَا وَبِئۡرࣲ مُّعَطَّلَةࣲ وَقَصۡرࣲ مَّشِیدٍ\n\";s:13:\"numberInSurah\";i:45;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:337;s:4:\"ruku\";i:290;s:11:\"hizbQuarter\";i:135;s:5:\"sajda\";b:0;}i:45;a:9:{s:6:\"number\";i:2641;s:4:\"text\";s:379:\"أَفَلَمۡ یَسِیرُوا۟ فِی ٱلۡأَرۡضِ فَتَكُونَ لَهُمۡ قُلُوبࣱ یَعۡقِلُونَ بِهَاۤ أَوۡ ءَاذَانࣱ یَسۡمَعُونَ بِهَاۖ فَإِنَّهَا لَا تَعۡمَى ٱلۡأَبۡصَـٰرُ وَلَـٰكِن تَعۡمَى ٱلۡقُلُوبُ ٱلَّتِی فِی ٱلصُّدُورِ\n\";s:13:\"numberInSurah\";i:46;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:337;s:4:\"ruku\";i:290;s:11:\"hizbQuarter\";i:135;s:5:\"sajda\";b:0;}i:46;a:9:{s:6:\"number\";i:2642;s:4:\"text\";s:251:\"وَیَسۡتَعۡجِلُونَكَ بِٱلۡعَذَابِ وَلَن یُخۡلِفَ ٱللَّهُ وَعۡدَهُۥۚ وَإِنَّ یَوۡمًا عِندَ رَبِّكَ كَأَلۡفِ سَنَةࣲ مِّمَّا تَعُدُّونَ\n\";s:13:\"numberInSurah\";i:47;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:338;s:4:\"ruku\";i:290;s:11:\"hizbQuarter\";i:135;s:5:\"sajda\";b:0;}i:47;a:9:{s:6:\"number\";i:2643;s:4:\"text\";s:186:\"وَكَأَیِّن مِّن قَرۡیَةٍ أَمۡلَیۡتُ لَهَا وَهِیَ ظَالِمَةࣱ ثُمَّ أَخَذۡتُهَا وَإِلَیَّ ٱلۡمَصِیرُ\n\";s:13:\"numberInSurah\";i:48;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:338;s:4:\"ruku\";i:290;s:11:\"hizbQuarter\";i:135;s:5:\"sajda\";b:0;}i:48;a:9:{s:6:\"number\";i:2644;s:4:\"text\";s:132:\"قُلۡ یَـٰۤأَیُّهَا ٱلنَّاسُ إِنَّمَاۤ أَنَا۠ لَكُمۡ نَذِیرࣱ مُّبِینࣱ\n\";s:13:\"numberInSurah\";i:49;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:338;s:4:\"ruku\";i:291;s:11:\"hizbQuarter\";i:135;s:5:\"sajda\";b:0;}i:49;a:9:{s:6:\"number\";i:2645;s:4:\"text\";s:167:\"فَٱلَّذِینَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ لَهُم مَّغۡفِرَةࣱ وَرِزۡقࣱ كَرِیمࣱ\n\";s:13:\"numberInSurah\";i:50;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:338;s:4:\"ruku\";i:291;s:11:\"hizbQuarter\";i:135;s:5:\"sajda\";b:0;}i:50;a:9:{s:6:\"number\";i:2646;s:4:\"text\";s:172:\"وَٱلَّذِینَ سَعَوۡا۟ فِیۤ ءَایَـٰتِنَا مُعَـٰجِزِینَ أُو۟لَـٰۤىِٕكَ أَصۡحَـٰبُ ٱلۡجَحِیمِ\n\";s:13:\"numberInSurah\";i:51;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:338;s:4:\"ruku\";i:291;s:11:\"hizbQuarter\";i:135;s:5:\"sajda\";b:0;}i:51;a:9:{s:6:\"number\";i:2647;s:4:\"text\";s:441:\"وَمَاۤ أَرۡسَلۡنَا مِن قَبۡلِكَ مِن رَّسُولࣲ وَلَا نَبِیٍّ إِلَّاۤ إِذَا تَمَنَّىٰۤ أَلۡقَى ٱلشَّیۡطَـٰنُ فِیۤ أُمۡنِیَّتِهِۦ فَیَنسَخُ ٱللَّهُ مَا یُلۡقِی ٱلشَّیۡطَـٰنُ ثُمَّ یُحۡكِمُ ٱللَّهُ ءَایَـٰتِهِۦۗ وَٱللَّهُ عَلِیمٌ حَكِیمࣱ\n\";s:13:\"numberInSurah\";i:52;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:338;s:4:\"ruku\";i:291;s:11:\"hizbQuarter\";i:135;s:5:\"sajda\";b:0;}i:52;a:9:{s:6:\"number\";i:2648;s:4:\"text\";s:299:\"لِّیَجۡعَلَ مَا یُلۡقِی ٱلشَّیۡطَـٰنُ فِتۡنَةࣰ لِّلَّذِینَ فِی قُلُوبِهِم مَّرَضࣱ وَٱلۡقَاسِیَةِ قُلُوبُهُمۡۗ وَإِنَّ ٱلظَّـٰلِمِینَ لَفِی شِقَاقِۭ بَعِیدࣲ\n\";s:13:\"numberInSurah\";i:53;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:338;s:4:\"ruku\";i:291;s:11:\"hizbQuarter\";i:135;s:5:\"sajda\";b:0;}i:53;a:9:{s:6:\"number\";i:2649;s:4:\"text\";s:379:\"وَلِیَعۡلَمَ ٱلَّذِینَ أُوتُوا۟ ٱلۡعِلۡمَ أَنَّهُ ٱلۡحَقُّ مِن رَّبِّكَ فَیُؤۡمِنُوا۟ بِهِۦ فَتُخۡبِتَ لَهُۥ قُلُوبُهُمۡۗ وَإِنَّ ٱللَّهَ لَهَادِ ٱلَّذِینَ ءَامَنُوۤا۟ إِلَىٰ صِرَ ٰ⁠طࣲ مُّسۡتَقِیمࣲ\n\";s:13:\"numberInSurah\";i:54;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:338;s:4:\"ruku\";i:291;s:11:\"hizbQuarter\";i:135;s:5:\"sajda\";b:0;}i:54;a:9:{s:6:\"number\";i:2650;s:4:\"text\";s:259:\"وَلَا یَزَالُ ٱلَّذِینَ كَفَرُوا۟ فِی مِرۡیَةࣲ مِّنۡهُ حَتَّىٰ تَأۡتِیَهُمُ ٱلسَّاعَةُ بَغۡتَةً أَوۡ یَأۡتِیَهُمۡ عَذَابُ یَوۡمٍ عَقِیمٍ\n\";s:13:\"numberInSurah\";i:55;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:338;s:4:\"ruku\";i:291;s:11:\"hizbQuarter\";i:135;s:5:\"sajda\";b:0;}i:55;a:9:{s:6:\"number\";i:2651;s:4:\"text\";s:245:\"ٱلۡمُلۡكُ یَوۡمَىِٕذࣲ لِّلَّهِ یَحۡكُمُ بَیۡنَهُمۡۚ فَٱلَّذِینَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ فِی جَنَّـٰتِ ٱلنَّعِیمِ\n\";s:13:\"numberInSurah\";i:56;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:339;s:4:\"ruku\";i:291;s:11:\"hizbQuarter\";i:135;s:5:\"sajda\";b:0;}i:56;a:9:{s:6:\"number\";i:2652;s:4:\"text\";s:178:\"وَٱلَّذِینَ كَفَرُوا۟ وَكَذَّبُوا۟ بِـَٔایَـٰتِنَا فَأُو۟لَـٰۤىِٕكَ لَهُمۡ عَذَابࣱ مُّهِینࣱ\n\";s:13:\"numberInSurah\";i:57;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:339;s:4:\"ruku\";i:291;s:11:\"hizbQuarter\";i:135;s:5:\"sajda\";b:0;}i:57;a:9:{s:6:\"number\";i:2653;s:4:\"text\";s:311:\"وَٱلَّذِینَ هَاجَرُوا۟ فِی سَبِیلِ ٱللَّهِ ثُمَّ قُتِلُوۤا۟ أَوۡ مَاتُوا۟ لَیَرۡزُقَنَّهُمُ ٱللَّهُ رِزۡقًا حَسَنࣰاۚ وَإِنَّ ٱللَّهَ لَهُوَ خَیۡرُ ٱلرَّ ٰ⁠زِقِینَ\n\";s:13:\"numberInSurah\";i:58;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:339;s:4:\"ruku\";i:292;s:11:\"hizbQuarter\";i:135;s:5:\"sajda\";b:0;}i:58;a:9:{s:6:\"number\";i:2654;s:4:\"text\";s:149:\"لَیُدۡخِلَنَّهُم مُّدۡخَلࣰا یَرۡضَوۡنَهُۥۚ وَإِنَّ ٱللَّهَ لَعَلِیمٌ حَلِیمࣱ\n\";s:13:\"numberInSurah\";i:59;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:339;s:4:\"ruku\";i:292;s:11:\"hizbQuarter\";i:135;s:5:\"sajda\";b:0;}i:59;a:9:{s:6:\"number\";i:2655;s:4:\"text\";s:252:\"۞ ذَ ٰ⁠لِكَۖ وَمَنۡ عَاقَبَ بِمِثۡلِ مَا عُوقِبَ بِهِۦ ثُمَّ بُغِیَ عَلَیۡهِ لَیَنصُرَنَّهُ ٱللَّهُۚ إِنَّ ٱللَّهَ لَعَفُوٌّ غَفُورࣱ\n\";s:13:\"numberInSurah\";i:60;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:339;s:4:\"ruku\";i:292;s:11:\"hizbQuarter\";i:136;s:5:\"sajda\";b:0;}i:60;a:9:{s:6:\"number\";i:2656;s:4:\"text\";s:238:\"ذَ ٰ⁠لِكَ بِأَنَّ ٱللَّهَ یُولِجُ ٱلَّیۡلَ فِی ٱلنَّهَارِ وَیُولِجُ ٱلنَّهَارَ فِی ٱلَّیۡلِ وَأَنَّ ٱللَّهَ سَمِیعُۢ بَصِیرࣱ\n\";s:13:\"numberInSurah\";i:61;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:339;s:4:\"ruku\";i:292;s:11:\"hizbQuarter\";i:136;s:5:\"sajda\";b:0;}i:61;a:9:{s:6:\"number\";i:2657;s:4:\"text\";s:255:\"ذَ ٰ⁠لِكَ بِأَنَّ ٱللَّهَ هُوَ ٱلۡحَقُّ وَأَنَّ مَا یَدۡعُونَ مِن دُونِهِۦ هُوَ ٱلۡبَـٰطِلُ وَأَنَّ ٱللَّهَ هُوَ ٱلۡعَلِیُّ ٱلۡكَبِیرُ\n\";s:13:\"numberInSurah\";i:62;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:339;s:4:\"ruku\";i:292;s:11:\"hizbQuarter\";i:136;s:5:\"sajda\";b:0;}i:62;a:9:{s:6:\"number\";i:2658;s:4:\"text\";s:231:\"أَلَمۡ تَرَ أَنَّ ٱللَّهَ أَنزَلَ مِنَ ٱلسَّمَاۤءِ مَاۤءࣰ فَتُصۡبِحُ ٱلۡأَرۡضُ مُخۡضَرَّةًۚ إِنَّ ٱللَّهَ لَطِیفٌ خَبِیرࣱ\n\";s:13:\"numberInSurah\";i:63;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:339;s:4:\"ruku\";i:292;s:11:\"hizbQuarter\";i:136;s:5:\"sajda\";b:0;}i:63;a:9:{s:6:\"number\";i:2659;s:4:\"text\";s:186:\"لَّهُۥ مَا فِی ٱلسَّمَـٰوَ ٰ⁠تِ وَمَا فِی ٱلۡأَرۡضِۚ وَإِنَّ ٱللَّهَ لَهُوَ ٱلۡغَنِیُّ ٱلۡحَمِیدُ\n\";s:13:\"numberInSurah\";i:64;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:339;s:4:\"ruku\";i:292;s:11:\"hizbQuarter\";i:136;s:5:\"sajda\";b:0;}i:64;a:9:{s:6:\"number\";i:2660;s:4:\"text\";s:415:\"أَلَمۡ تَرَ أَنَّ ٱللَّهَ سَخَّرَ لَكُم مَّا فِی ٱلۡأَرۡضِ وَٱلۡفُلۡكَ تَجۡرِی فِی ٱلۡبَحۡرِ بِأَمۡرِهِۦ وَیُمۡسِكُ ٱلسَّمَاۤءَ أَن تَقَعَ عَلَى ٱلۡأَرۡضِ إِلَّا بِإِذۡنِهِۦۤۚ إِنَّ ٱللَّهَ بِٱلنَّاسِ لَرَءُوفࣱ رَّحِیمࣱ\n\";s:13:\"numberInSurah\";i:65;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:340;s:4:\"ruku\";i:293;s:11:\"hizbQuarter\";i:136;s:5:\"sajda\";b:0;}i:65;a:9:{s:6:\"number\";i:2661;s:4:\"text\";s:179:\"وَهُوَ ٱلَّذِیۤ أَحۡیَاكُمۡ ثُمَّ یُمِیتُكُمۡ ثُمَّ یُحۡیِیكُمۡۗ إِنَّ ٱلۡإِنسَـٰنَ لَكَفُورࣱ\n\";s:13:\"numberInSurah\";i:66;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:340;s:4:\"ruku\";i:293;s:11:\"hizbQuarter\";i:136;s:5:\"sajda\";b:0;}i:66;a:9:{s:6:\"number\";i:2662;s:4:\"text\";s:286:\"لِّكُلِّ أُمَّةࣲ جَعَلۡنَا مَنسَكًا هُمۡ نَاسِكُوهُۖ فَلَا یُنَـٰزِعُنَّكَ فِی ٱلۡأَمۡرِۚ وَٱدۡعُ إِلَىٰ رَبِّكَۖ إِنَّكَ لَعَلَىٰ هُدࣰى مُّسۡتَقِیمࣲ\n\";s:13:\"numberInSurah\";i:67;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:340;s:4:\"ruku\";i:293;s:11:\"hizbQuarter\";i:136;s:5:\"sajda\";b:0;}i:67;a:9:{s:6:\"number\";i:2663;s:4:\"text\";s:113:\"وَإِن جَـٰدَلُوكَ فَقُلِ ٱللَّهُ أَعۡلَمُ بِمَا تَعۡمَلُونَ\n\";s:13:\"numberInSurah\";i:68;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:340;s:4:\"ruku\";i:293;s:11:\"hizbQuarter\";i:136;s:5:\"sajda\";b:0;}i:68;a:9:{s:6:\"number\";i:2664;s:4:\"text\";s:159:\"ٱللَّهُ یَحۡكُمُ بَیۡنَكُمۡ یَوۡمَ ٱلۡقِیَـٰمَةِ فِیمَا كُنتُمۡ فِیهِ تَخۡتَلِفُونَ\n\";s:13:\"numberInSurah\";i:69;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:340;s:4:\"ruku\";i:293;s:11:\"hizbQuarter\";i:136;s:5:\"sajda\";b:0;}i:69;a:9:{s:6:\"number\";i:2665;s:4:\"text\";s:267:\"أَلَمۡ تَعۡلَمۡ أَنَّ ٱللَّهَ یَعۡلَمُ مَا فِی ٱلسَّمَاۤءِ وَٱلۡأَرۡضِۚ إِنَّ ذَ ٰ⁠لِكَ فِی كِتَـٰبٍۚ إِنَّ ذَ ٰ⁠لِكَ عَلَى ٱللَّهِ یَسِیرࣱ\n\";s:13:\"numberInSurah\";i:70;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:340;s:4:\"ruku\";i:293;s:11:\"hizbQuarter\";i:136;s:5:\"sajda\";b:0;}i:70;a:9:{s:6:\"number\";i:2666;s:4:\"text\";s:259:\"وَیَعۡبُدُونَ مِن دُونِ ٱللَّهِ مَا لَمۡ یُنَزِّلۡ بِهِۦ سُلۡطَـٰنࣰا وَمَا لَیۡسَ لَهُم بِهِۦ عِلۡمࣱۗ وَمَا لِلظَّـٰلِمِینَ مِن نَّصِیرࣲ\n\";s:13:\"numberInSurah\";i:71;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:340;s:4:\"ruku\";i:293;s:11:\"hizbQuarter\";i:136;s:5:\"sajda\";b:0;}i:71;a:9:{s:6:\"number\";i:2667;s:4:\"text\";s:555:\"وَإِذَا تُتۡلَىٰ عَلَیۡهِمۡ ءَایَـٰتُنَا بَیِّنَـٰتࣲ تَعۡرِفُ فِی وُجُوهِ ٱلَّذِینَ كَفَرُوا۟ ٱلۡمُنكَرَۖ یَكَادُونَ یَسۡطُونَ بِٱلَّذِینَ یَتۡلُونَ عَلَیۡهِمۡ ءَایَـٰتِنَاۗ قُلۡ أَفَأُنَبِّئُكُم بِشَرࣲّ مِّن ذَ ٰ⁠لِكُمُۚ ٱلنَّارُ وَعَدَهَا ٱللَّهُ ٱلَّذِینَ كَفَرُوا۟ۖ وَبِئۡسَ ٱلۡمَصِیرُ\n\";s:13:\"numberInSurah\";i:72;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:340;s:4:\"ruku\";i:293;s:11:\"hizbQuarter\";i:136;s:5:\"sajda\";b:0;}i:72;a:9:{s:6:\"number\";i:2668;s:4:\"text\";s:487:\"یَـٰۤأَیُّهَا ٱلنَّاسُ ضُرِبَ مَثَلࣱ فَٱسۡتَمِعُوا۟ لَهُۥۤۚ إِنَّ ٱلَّذِینَ تَدۡعُونَ مِن دُونِ ٱللَّهِ لَن یَخۡلُقُوا۟ ذُبَابࣰا وَلَوِ ٱجۡتَمَعُوا۟ لَهُۥۖ وَإِن یَسۡلُبۡهُمُ ٱلذُّبَابُ شَیۡـࣰٔا لَّا یَسۡتَنقِذُوهُ مِنۡهُۚ ضَعُفَ ٱلطَّالِبُ وَٱلۡمَطۡلُوبُ\n\";s:13:\"numberInSurah\";i:73;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:341;s:4:\"ruku\";i:294;s:11:\"hizbQuarter\";i:136;s:5:\"sajda\";b:0;}i:73;a:9:{s:6:\"number\";i:2669;s:4:\"text\";s:135:\"مَا قَدَرُوا۟ ٱللَّهَ حَقَّ قَدۡرِهِۦۤۚ إِنَّ ٱللَّهَ لَقَوِیٌّ عَزِیزٌ\n\";s:13:\"numberInSurah\";i:74;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:341;s:4:\"ruku\";i:294;s:11:\"hizbQuarter\";i:136;s:5:\"sajda\";b:0;}i:74;a:9:{s:6:\"number\";i:2670;s:4:\"text\";s:185:\"ٱللَّهُ یَصۡطَفِی مِنَ ٱلۡمَلَـٰۤىِٕكَةِ رُسُلࣰا وَمِنَ ٱلنَّاسِۚ إِنَّ ٱللَّهَ سَمِیعُۢ بَصِیرࣱ\n\";s:13:\"numberInSurah\";i:75;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:341;s:4:\"ruku\";i:294;s:11:\"hizbQuarter\";i:136;s:5:\"sajda\";b:0;}i:75;a:9:{s:6:\"number\";i:2671;s:4:\"text\";s:162:\"یَعۡلَمُ مَا بَیۡنَ أَیۡدِیهِمۡ وَمَا خَلۡفَهُمۡۚ وَإِلَى ٱللَّهِ تُرۡجَعُ ٱلۡأُمُورُ\n\";s:13:\"numberInSurah\";i:76;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:341;s:4:\"ruku\";i:294;s:11:\"hizbQuarter\";i:136;s:5:\"sajda\";b:0;}i:76;a:9:{s:6:\"number\";i:2672;s:4:\"text\";s:250:\"یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ ٱرۡكَعُوا۟ وَٱسۡجُدُوا۟ وَٱعۡبُدُوا۟ رَبَّكُمۡ وَٱفۡعَلُوا۟ ٱلۡخَیۡرَ لَعَلَّكُمۡ تُفۡلِحُونَ ۩\n\";s:13:\"numberInSurah\";i:77;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:341;s:4:\"ruku\";i:294;s:11:\"hizbQuarter\";i:136;s:5:\"sajda\";a:3:{s:2:\"id\";i:7;s:11:\"recommended\";b:1;s:10:\"obligatory\";b:0;}}i:77;a:9:{s:6:\"number\";i:2673;s:4:\"text\";s:797:\"وَجَـٰهِدُوا۟ فِی ٱللَّهِ حَقَّ جِهَادِهِۦۚ هُوَ ٱجۡتَبَىٰكُمۡ وَمَا جَعَلَ عَلَیۡكُمۡ فِی ٱلدِّینِ مِنۡ حَرَجࣲۚ مِّلَّةَ أَبِیكُمۡ إِبۡرَ ٰ⁠هِیمَۚ هُوَ سَمَّىٰكُمُ ٱلۡمُسۡلِمِینَ مِن قَبۡلُ وَفِی هَـٰذَا لِیَكُونَ ٱلرَّسُولُ شَهِیدًا عَلَیۡكُمۡ وَتَكُونُوا۟ شُهَدَاۤءَ عَلَى ٱلنَّاسِۚ فَأَقِیمُوا۟ ٱلصَّلَوٰةَ وَءَاتُوا۟ ٱلزَّكَوٰةَ وَٱعۡتَصِمُوا۟ بِٱللَّهِ هُوَ مَوۡلَىٰكُمۡۖ فَنِعۡمَ ٱلۡمَوۡلَىٰ وَنِعۡمَ ٱلنَّصِیرُ\n\";s:13:\"numberInSurah\";i:78;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:341;s:4:\"ruku\";i:294;s:11:\"hizbQuarter\";i:136;s:5:\"sajda\";b:0;}}s:7:\"edition\";a:7:{s:10:\"identifier\";s:27:\"quran-uthmani-quran-academy\";s:8:\"language\";s:2:\"ar\";s:4:\"name\";s:67:\"القرآن الكريم برسم العثماني (quran-academy)\";s:11:\"englishName\";s:78:\"Modified Quran Uthmani Text from the Quran Academy to work with the Kitab font\";s:6:\"format\";s:4:\"text\";s:4:\"type\";s:5:\"quran\";s:9:\"direction\";s:3:\"rtl\";}}', 1794581355);
INSERT INTO `cache` (`key`, `value`, `expiration`) VALUES
('quranapp-cache-surah_22_fr.hamidullah', 'a:8:{s:6:\"number\";i:22;s:4:\"name\";s:29:\"سُورَةُ الحَجِّ\";s:11:\"englishName\";s:7:\"Al-Hajj\";s:22:\"englishNameTranslation\";s:14:\"The Pilgrimage\";s:14:\"revelationType\";s:7:\"Medinan\";s:13:\"numberOfAyahs\";i:78;s:5:\"ayahs\";a:78:{i:0;a:9:{s:6:\"number\";i:2596;s:4:\"text\";s:95:\"O hommes! Craignez votre Seigneur. Le séisme [qui précédera] l\'Heure est une chose terrible.\";s:13:\"numberInSurah\";i:1;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:332;s:4:\"ruku\";i:285;s:11:\"hizbQuarter\";i:133;s:5:\"sajda\";b:0;}i:1;a:9:{s:6:\"number\";i:2597;s:4:\"text\";s:225:\"Le jour où vous le verrez, toute nourrice oubliera ce qu\'elle allaitait, et toute femelle enceinte avortera de ce qu\'elle portait. Et tu verras les gens ivres, alors qu\'ils ne le sont pas. Mais le châtiment d\'Allah est dur.\";s:13:\"numberInSurah\";i:2;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:332;s:4:\"ruku\";i:285;s:11:\"hizbQuarter\";i:133;s:5:\"sajda\";b:0;}i:2;a:9:{s:6:\"number\";i:2598;s:4:\"text\";s:106:\"Et il y a des gens qui discutent au sujet d\'Allah sans aucune science, et qui suivent tout diable rebelle.\";s:13:\"numberInSurah\";i:3;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:332;s:4:\"ruku\";i:285;s:11:\"hizbQuarter\";i:133;s:5:\"sajda\";b:0;}i:3;a:9:{s:6:\"number\";i:2599;s:4:\"text\";s:151:\"Il a été prescrit à l\'égard de ce dernier qu\'il égarera quiconque le prendra pour maître, et qu\'il le guidera vers le châtiment de la fournaise.\";s:13:\"numberInSurah\";i:4;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:332;s:4:\"ruku\";i:285;s:11:\"hizbQuarter\";i:133;s:5:\"sajda\";b:0;}i:4;a:9:{s:6:\"number\";i:2600;s:4:\"text\";s:773:\"O hommes! Si vous doutez au sujet de la Résurrection, c\'est Nous qui vous avons créés de terre, puis d\'une goutte de sperme, puis d\'une adhérence puis d\'un embryon [normalement] formé aussi bien qu\'informe pour vous montrer [Notre Omnipotence] et Nous déposerons dans les matrices ce que Nous voulons jusqu\'à un terme fixé. Puis Nous vous en sortirons [à l\'état] de bébé, pour qu\'ensuite vous atteignez votre maturité. Il en est parmi vous qui meurent [jeunes] tandis que d\'autres parviennent au plus vil de l\'âge si bien qu\'ils ne savent plus rien de ce qu\'ils connaissaient auparavant. De même tu vois la terre desséchée: dès que Nous y faisons descendre de l\'eau elle remue, se gonfle, et fait pousser toutes sortes de splendides couples de végétaux.\";s:13:\"numberInSurah\";i:5;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:332;s:4:\"ruku\";i:285;s:11:\"hizbQuarter\";i:133;s:5:\"sajda\";b:0;}i:5;a:9:{s:6:\"number\";i:2601;s:4:\"text\";s:120:\"Il en est ainsi parce qu\'Allah est la vérité; et c\'est Lui qui rend la vie aux morts; et c\'est Lui qui est Omnipotent.\";s:13:\"numberInSurah\";i:6;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:333;s:4:\"ruku\";i:285;s:11:\"hizbQuarter\";i:133;s:5:\"sajda\";b:0;}i:6;a:9:{s:6:\"number\";i:2602;s:4:\"text\";s:109:\"Et que l\'Heure arrivera; pas de doute à son sujet, et qu\'Allah ressuscitera ceux qui sont dans les tombeaux.\";s:13:\"numberInSurah\";i:7;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:333;s:4:\"ruku\";i:285;s:11:\"hizbQuarter\";i:133;s:5:\"sajda\";b:0;}i:7;a:9:{s:6:\"number\";i:2603;s:4:\"text\";s:110:\"Or, il y a des gens qui discutent au sujet d\'Allah sans aucune science, ni guide, ni Livre pour les éclairer,\";s:13:\"numberInSurah\";i:8;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:333;s:4:\"ruku\";i:285;s:11:\"hizbQuarter\";i:133;s:5:\"sajda\";b:0;}i:8;a:9:{s:6:\"number\";i:2604;s:4:\"text\";s:191:\"affichant une attitude orgueilleuse pour égarer les gens du sentier d\'Allah. A lui l\'ignominie ici-bas; et Nous Lui ferons goûter le Jour de la Résurrection, le châtiment de la fournaise.\";s:13:\"numberInSurah\";i:9;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:333;s:4:\"ruku\";i:285;s:11:\"hizbQuarter\";i:133;s:5:\"sajda\";b:0;}i:9;a:9:{s:6:\"number\";i:2605;s:4:\"text\";s:119:\"Voilà, pour ce que tes deux mains ont préparé (ici-bas)! Cependant, Allah n\'est point injuste envers Ses serviteurs.\";s:13:\"numberInSurah\";i:10;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:333;s:4:\"ruku\";i:285;s:11:\"hizbQuarter\";i:133;s:5:\"sajda\";b:0;}i:10;a:9:{s:6:\"number\";i:2606;s:4:\"text\";s:256:\"Il en est parmi les gens qui adorent Allah marginalement. S\'il leur arrive un bien, ils s\'en tranquillisent, et s\'il leur arrive une épreuve, ils détournent leur visage, perdant ainsi (le bien) de l\'ici-bas et de l\'au-delà. Telle est la perte évidente!\";s:13:\"numberInSurah\";i:11;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:333;s:4:\"ruku\";i:286;s:11:\"hizbQuarter\";i:133;s:5:\"sajda\";b:0;}i:11;a:9:{s:6:\"number\";i:2607;s:4:\"text\";s:109:\"Ils invoquent en dehors d\'Allah, ce qui ne peut ni leur nuire ni leur profiter. Tel est l\'égarement profond!\";s:13:\"numberInSurah\";i:12;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:333;s:4:\"ruku\";i:286;s:11:\"hizbQuarter\";i:133;s:5:\"sajda\";b:0;}i:12;a:9:{s:6:\"number\";i:2608;s:4:\"text\";s:121:\"Ils invoquent ce dont le mal est certainement plus proche que l\'utilité. Quel mauvais allié, et quel mauvais compagnon!\";s:13:\"numberInSurah\";i:13;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:333;s:4:\"ruku\";i:286;s:11:\"hizbQuarter\";i:133;s:5:\"sajda\";b:0;}i:13;a:9:{s:6:\"number\";i:2609;s:4:\"text\";s:151:\"Ceux qui croient et font de bonnes œuvres, Allah les fait entrer aux Jardins sous lesquels coulent les ruisseaux, car Allah fait certes ce qu\'Il veut.\";s:13:\"numberInSurah\";i:14;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:333;s:4:\"ruku\";i:286;s:11:\"hizbQuarter\";i:133;s:5:\"sajda\";b:0;}i:14;a:9:{s:6:\"number\";i:2610;s:4:\"text\";s:199:\"Celui qui pense qu\'Allah ne le secourra pas dans l\'ici-bas et dans l\'au-delà qu\'il tende une corde jusqu\'au ciel, puis qu\'il la coupe, et qu\'il voie si sa ruse va faire disparaître ce qui l\'enrage.\";s:13:\"numberInSurah\";i:15;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:333;s:4:\"ruku\";i:286;s:11:\"hizbQuarter\";i:133;s:5:\"sajda\";b:0;}i:15;a:9:{s:6:\"number\";i:2611;s:4:\"text\";s:100:\"C\'est ainsi que Nous le fîmes descendre (Le Coran) en versets clairs et qu\'Allah guide qui Il veut.\";s:13:\"numberInSurah\";i:16;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:334;s:4:\"ruku\";i:286;s:11:\"hizbQuarter\";i:133;s:5:\"sajda\";b:0;}i:16;a:9:{s:6:\"number\";i:2612;s:4:\"text\";s:242:\"Certes, ceux qui ont cru, les Juifs, les Sabéens [les adorateurs des étoiles], les Nazaréens, les Mages et ceux qui donnent à Allah des associés, Allah tranchera entre eux le jour du Jugement, car Allah est certes témoin de toute chose.\";s:13:\"numberInSurah\";i:17;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:334;s:4:\"ruku\";i:286;s:11:\"hizbQuarter\";i:133;s:5:\"sajda\";b:0;}i:17;a:9:{s:6:\"number\";i:2613;s:4:\"text\";s:367:\"N\'as-tu pas vu que c\'est devant Allah que se prosternent tous ceux qui sont dans les cieux et tous ceux qui sont sur la terre, le soleil, la lune, les étoiles, les montagnes, les arbres, les animaux, ainsi que beaucoup de gens? Il y en a aussi beaucoup qui méritent le châtiment. Et quiconque Allah avilit n\'a personne pour l\'honorer, car Allah fait ce qu\'il veut.\";s:13:\"numberInSurah\";i:18;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:334;s:4:\"ruku\";i:286;s:11:\"hizbQuarter\";i:133;s:5:\"sajda\";a:3:{s:2:\"id\";i:6;s:11:\"recommended\";b:1;s:10:\"obligatory\";b:0;}}i:18;a:9:{s:6:\"number\";i:2614;s:4:\"text\";s:190:\"Voici deux clans adverses qui disputaient au sujet de leur Seigneur. A ceux qui ne croient pas, on taillera des vêtements de feu, tandis que sur leurs têtes on versera de l\'eau bouillante,\";s:13:\"numberInSurah\";i:19;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:334;s:4:\"ruku\";i:286;s:11:\"hizbQuarter\";i:134;s:5:\"sajda\";b:0;}i:19;a:9:{s:6:\"number\";i:2615;s:4:\"text\";s:71:\"qui fera fondre ce qui est dans leurs ventres de même que leurs peaux.\";s:13:\"numberInSurah\";i:20;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:334;s:4:\"ruku\";i:286;s:11:\"hizbQuarter\";i:134;s:5:\"sajda\";b:0;}i:20;a:9:{s:6:\"number\";i:2616;s:4:\"text\";s:42:\"Et il y aura pour eux des maillets de fer.\";s:13:\"numberInSurah\";i:21;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:334;s:4:\"ruku\";i:286;s:11:\"hizbQuarter\";i:134;s:5:\"sajda\";b:0;}i:21;a:9:{s:6:\"number\";i:2617;s:4:\"text\";s:153:\"Toutes les fois qu\'ils voudront en sortir (pour échapper) à la détresse, on les y remettra et (on leur dira): «Goûtez au châtiment de la Fournaise.\";s:13:\"numberInSurah\";i:22;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:334;s:4:\"ruku\";i:286;s:11:\"hizbQuarter\";i:134;s:5:\"sajda\";b:0;}i:22;a:9:{s:6:\"number\";i:2618;s:4:\"text\";s:214:\"Certes Allah introduit ceux qui croient et font de bonnes œuvres aux Jardins sous lesquels coulent les ruisseaux. Là, ils seront parés de bracelets d\'or, et aussi de perles; et leurs vêtements y seront de soie.\";s:13:\"numberInSurah\";i:23;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:334;s:4:\"ruku\";i:287;s:11:\"hizbQuarter\";i:134;s:5:\"sajda\";b:0;}i:23;a:9:{s:6:\"number\";i:2619;s:4:\"text\";s:105:\"Ils ont été guidés vers la bonne parole et ils ont été guidés vers le chemin Du Digne des louanges.\";s:13:\"numberInSurah\";i:24;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:335;s:4:\"ruku\";i:287;s:11:\"hizbQuarter\";i:134;s:5:\"sajda\";b:0;}i:24;a:9:{s:6:\"number\";i:2620;s:4:\"text\";s:291:\"Mais ceux qui mécroient et qui obstruent le sentier d\'Allah et celui de la Mosquée sacrée, que Nous avons établie pour les gens: aussi bien les résidents que ceux de passage... Quiconque cherche à y commettre un sacrilège injustement, Nous lui ferons goûter un châtiment douloureux,\";s:13:\"numberInSurah\";i:25;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:335;s:4:\"ruku\";i:287;s:11:\"hizbQuarter\";i:134;s:5:\"sajda\";b:0;}i:25;a:9:{s:6:\"number\";i:2621;s:4:\"text\";s:246:\"Et quand Nous indiquâmes pour Abraham le lieu de la Maison (La Kaaba) [en lui disant]: «Ne M\'associe rien; et purifie Ma Maison pour ceux qui tournent autour, pour ceux qui s\'y tiennent debout et pour ceux qui s\'y inclinent et se prosternent».\";s:13:\"numberInSurah\";i:26;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:335;s:4:\"ruku\";i:288;s:11:\"hizbQuarter\";i:134;s:5:\"sajda\";b:0;}i:26;a:9:{s:6:\"number\";i:2622;s:4:\"text\";s:136:\"Et fais aux gens une annonce pour le Hajj. Ils viendront vers toi, à pied, et aussi sur toute monture, venant de tout chemin éloigné,\";s:13:\"numberInSurah\";i:27;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:335;s:4:\"ruku\";i:288;s:11:\"hizbQuarter\";i:134;s:5:\"sajda\";b:0;}i:27;a:9:{s:6:\"number\";i:2623;s:4:\"text\";s:226:\"pour participer aux avantages qui leur ont été accordés et pour invoquer le nom d\'Allah aux jours fixés, sur la bête de cheptel qu\'Il leur a attribuée, «Mangez-en vous-mêmes et faites-en manger le besogneux misérable.\";s:13:\"numberInSurah\";i:28;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:335;s:4:\"ruku\";i:288;s:11:\"hizbQuarter\";i:134;s:5:\"sajda\";b:0;}i:28;a:9:{s:6:\"number\";i:2624;s:4:\"text\";s:167:\"Puis qu\'ils mettent fin à leurs interdits (qu\'ils nettoient leurs corps), qu\'ils remplissent leurs vœux, et qu\'ils fassent les circuits autour de l\'Antique Maison».\";s:13:\"numberInSurah\";i:29;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:335;s:4:\"ruku\";i:288;s:11:\"hizbQuarter\";i:134;s:5:\"sajda\";b:0;}i:29;a:9:{s:6:\"number\";i:2625;s:4:\"text\";s:306:\"Voilà [ce qui doit être observé] et quiconque prend en haute considération les limites sacrées d\'Allah cela lui sera meilleur auprès de son Seigneur. Le bétail, sauf ce qu\'on vous a cité, vous a été rendu licite. Abstenez-vous de la souillure des idoles et abstenez-vous des paroles mensongères.\";s:13:\"numberInSurah\";i:30;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:335;s:4:\"ruku\";i:288;s:11:\"hizbQuarter\";i:134;s:5:\"sajda\";b:0;}i:30;a:9:{s:6:\"number\";i:2626;s:4:\"text\";s:242:\"(Soyez) exclusivement [acquis à la religion] d\'Allah ne Lui associez rien; car quiconque associe à Allah, c\'est comme s\'il tombait du haut du ciel et que les oiseaux le happaient, ou que le vent le précipitait dans un abîme très profond.\";s:13:\"numberInSurah\";i:31;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:336;s:4:\"ruku\";i:288;s:11:\"hizbQuarter\";i:134;s:5:\"sajda\";b:0;}i:31;a:9:{s:6:\"number\";i:2627;s:4:\"text\";s:128:\"Voilà [ce qui est prescrit]. Et quiconque exalte les injonctions sacrées d\'Allah, s\'inspire en effet de la piété des cœurs.\";s:13:\"numberInSurah\";i:32;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:336;s:4:\"ruku\";i:288;s:11:\"hizbQuarter\";i:134;s:5:\"sajda\";b:0;}i:32;a:9:{s:6:\"number\";i:2628;s:4:\"text\";s:129:\"[De ces bêtes-là] vous tirez des avantages jusqu\'à un terme fixé; puis son lieu d\'immolation est auprès de l\'Antique Maison.\";s:13:\"numberInSurah\";i:33;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:336;s:4:\"ruku\";i:288;s:11:\"hizbQuarter\";i:134;s:5:\"sajda\";b:0;}i:33;a:9:{s:6:\"number\";i:2629;s:4:\"text\";s:262:\"A chaque communauté, Nous avons assigné un rite sacrificiel, afin qu\'ils prononcent le nom d\'Allah sur la bête de cheptel qu\'Il leur a attribuée. Votre Dieu est certes un Dieu unique. Soumettez-vous donc à Lui. Et fais bonne annonce à ceux qui s\'humilient,\";s:13:\"numberInSurah\";i:34;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:336;s:4:\"ruku\";i:289;s:11:\"hizbQuarter\";i:134;s:5:\"sajda\";b:0;}i:34;a:9:{s:6:\"number\";i:2630;s:4:\"text\";s:193:\"ceux dont les cœurs frémissent quand le nom d\'Allah est mentionné, ceux qui endurent ce qui les atteint et ceux qui accomplissent la Salât et dépensent de ce que Nous leur avons attribué.\";s:13:\"numberInSurah\";i:35;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:336;s:4:\"ruku\";i:289;s:11:\"hizbQuarter\";i:134;s:5:\"sajda\";b:0;}i:35;a:9:{s:6:\"number\";i:2631;s:4:\"text\";s:421:\"Nous vous avons désigné les chameaux (et les vaches) bien portants pour certains rites établis par Allah. Il y a en eux pour vous un bien. Prononcez donc sur eux le nom d\'Allah, quand ils ont eu la patte attachée, [prêts à être immolés]. Puis, lorsqu\'ils gisent sur le flanc, mangez-en, et nourrissez-en le besogneux discret et le mendiant. Ainsi Nous vous les avons assujettis afin que vous soyez reconnaissants.\";s:13:\"numberInSurah\";i:36;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:336;s:4:\"ruku\";i:289;s:11:\"hizbQuarter\";i:134;s:5:\"sajda\";b:0;}i:36;a:9:{s:6:\"number\";i:2632;s:4:\"text\";s:272:\"Ni leurs chairs ni leurs sangs n\'atteindront Allah, mais ce qui L\'atteint de votre part c\'est la piété. Ainsi vous les a-t-Il assujettis afin que vous proclamiez la grandeur d\'Allah, pour vous avoir mis sur le droit chemin. Et annonce la bonne nouvelle aux bienfaisants.\";s:13:\"numberInSurah\";i:37;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:336;s:4:\"ruku\";i:289;s:11:\"hizbQuarter\";i:134;s:5:\"sajda\";b:0;}i:37;a:9:{s:6:\"number\";i:2633;s:4:\"text\";s:80:\"Allah prend la défense de ceux qui croient. Allah n\'aime aucun traître ingrat.\";s:13:\"numberInSurah\";i:38;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:336;s:4:\"ruku\";i:289;s:11:\"hizbQuarter\";i:135;s:5:\"sajda\";b:0;}i:38;a:9:{s:6:\"number\";i:2634;s:4:\"text\";s:154:\"Autorisation est donnée à ceux qui sont attaqués (de se défendre) - parce que vraiment ils sont lésés; et Allah est certes Capable de les secourir -\";s:13:\"numberInSurah\";i:39;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:337;s:4:\"ruku\";i:290;s:11:\"hizbQuarter\";i:135;s:5:\"sajda\";b:0;}i:39;a:9:{s:6:\"number\";i:2635;s:4:\"text\";s:428:\"ceux qui ont été expulsés de leurs demeures, - contre toute justice, simplement parce qu\'ils disaient: «Allah est notre Seigneur». - Si Allah ne repoussait pas les gens les uns par les autres, les ermitages seraient démolis, ainsi que les églises, les synagogues et les mosquées où le nom d\'Allah est beaucoup invoqué. Allah soutient, certes, ceux qui soutiennent (Sa Religion). Allah est assurément Fort et Puissant,\";s:13:\"numberInSurah\";i:40;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:337;s:4:\"ruku\";i:290;s:11:\"hizbQuarter\";i:135;s:5:\"sajda\";b:0;}i:40;a:9:{s:6:\"number\";i:2636;s:4:\"text\";s:216:\"ceux qui, si Nous leur donnons la puissance sur terre, accomplissent la Salât, acquittent la Zakât, ordonnent le convenable et interdisent le blâmable. Cependant, l\'issue finale de toute chose appartient à Allah.\";s:13:\"numberInSurah\";i:41;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:337;s:4:\"ruku\";i:290;s:11:\"hizbQuarter\";i:135;s:5:\"sajda\";b:0;}i:41;a:9:{s:6:\"number\";i:2637;s:4:\"text\";s:157:\"Et s\'ils te traitent de menteur, [sache que] le peuple de Noé, les \'Aad, les Tamûd avant eux, ont aussi crié au mensonge (à l\'égard de leurs messagers),\";s:13:\"numberInSurah\";i:42;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:337;s:4:\"ruku\";i:290;s:11:\"hizbQuarter\";i:135;s:5:\"sajda\";b:0;}i:42;a:9:{s:6:\"number\";i:2638;s:4:\"text\";s:51:\"de même que le peuple d\'Abraham, le peuple de Lot.\";s:13:\"numberInSurah\";i:43;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:337;s:4:\"ruku\";i:290;s:11:\"hizbQuarter\";i:135;s:5:\"sajda\";b:0;}i:43;a:9:{s:6:\"number\";i:2639;s:4:\"text\";s:158:\"et les gens de Madyan. Et Moïse fut traité de menteur. Puis, J\'ai donné un répit aux mécréants; ensuite Je les ai saisis. Et quelle fut Ma réprobation!\";s:13:\"numberInSurah\";i:44;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:337;s:4:\"ruku\";i:290;s:11:\"hizbQuarter\";i:135;s:5:\"sajda\";b:0;}i:44;a:9:{s:6:\"number\";i:2640;s:4:\"text\";s:205:\"Que de cités, donc, avons-Nous fait périr, parce qu\'elles commettaient des tyrannies. Elles sont réduites à des toits écroulés: Que de puits désertés! Que de palais édifiés (et désertés aussi)!\";s:13:\"numberInSurah\";i:45;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:337;s:4:\"ruku\";i:290;s:11:\"hizbQuarter\";i:135;s:5:\"sajda\";b:0;}i:45;a:9:{s:6:\"number\";i:2641;s:4:\"text\";s:210:\"Que ne voyagent-ils sur la terre afin d\'avoir des cœurs pour comprendre, et des oreilles pour entendre? Car ce ne sont pas les yeux qui s\'aveuglent, mais, ce sont les cœurs dans les poitrines qui s\'aveuglent.\";s:13:\"numberInSurah\";i:46;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:337;s:4:\"ruku\";i:290;s:11:\"hizbQuarter\";i:135;s:5:\"sajda\";b:0;}i:46;a:9:{s:6:\"number\";i:2642;s:4:\"text\";s:189:\"Et ils te demandent de hâter [l\'arrivée] du châtiment. Jamais Allah ne manquera à Sa promesse. Cependant, un jour auprès de ton Seigneur, équivaut à mille ans de ce que vous comptez.\";s:13:\"numberInSurah\";i:47;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:338;s:4:\"ruku\";i:290;s:11:\"hizbQuarter\";i:135;s:5:\"sajda\";b:0;}i:47;a:9:{s:6:\"number\";i:2643;s:4:\"text\";s:142:\"A combien de cités n\'ai-Je pas donné répit alors qu\'elles commettaient des tyrannies? Ensuite, Je les ais saisies. Vers Moi est le devenir.\";s:13:\"numberInSurah\";i:48;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:338;s:4:\"ruku\";i:290;s:11:\"hizbQuarter\";i:135;s:5:\"sajda\";b:0;}i:48;a:9:{s:6:\"number\";i:2644;s:4:\"text\";s:82:\"Dis: «O hommes! Je ne suis pour vous, en vérité, qu\'un avertisseur explicite».\";s:13:\"numberInSurah\";i:49;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:338;s:4:\"ruku\";i:291;s:11:\"hizbQuarter\";i:135;s:5:\"sajda\";b:0;}i:49;a:9:{s:6:\"number\";i:2645;s:4:\"text\";s:86:\"Ceux donc qui croient et font de bonnes œuvres auront pardon et faveurs généreuses,\";s:13:\"numberInSurah\";i:50;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:338;s:4:\"ruku\";i:291;s:11:\"hizbQuarter\";i:135;s:5:\"sajda\";b:0;}i:50;a:9:{s:6:\"number\";i:2646;s:4:\"text\";s:124:\"tandis que ceux qui s\'efforcent à échapper (au châtiment mentionné dans) Nos versets, ceux-là sont les gens de l\'Enfer.\";s:13:\"numberInSurah\";i:51;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:338;s:4:\"ruku\";i:291;s:11:\"hizbQuarter\";i:135;s:5:\"sajda\";b:0;}i:51;a:9:{s:6:\"number\";i:2647;s:4:\"text\";s:327:\"Nous n\'avons envoyé, avant toi, ni Messager ni prophète qui n\'ait récité (ce qui lui a été révélé) sans que le Diable n\'ait essayé d\'intervenir [pour semer le doute dans le cœur des gens au sujet] de sa récitation. Allah abroge ce que le Diable suggère, et Allah renforce Ses versets. Allah est Omniscient et Sage.\";s:13:\"numberInSurah\";i:52;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:338;s:4:\"ruku\";i:291;s:11:\"hizbQuarter\";i:135;s:5:\"sajda\";b:0;}i:52;a:9:{s:6:\"number\";i:2648;s:4:\"text\";s:176:\"Afin de faire, de ce que jette le Diable, une tentation pour ceux qui ont une maladie au cœur et ceux qui ont le cœur dur... Les injustes sont certes dans un schisme profond.\";s:13:\"numberInSurah\";i:53;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:338;s:4:\"ruku\";i:291;s:11:\"hizbQuarter\";i:135;s:5:\"sajda\";b:0;}i:53;a:9:{s:6:\"number\";i:2649;s:4:\"text\";s:258:\"Et afin que ceux à qui le savoir a été donné sachent que (le Coran) est en effet, la Vérité venant de ton Seigneur, qu\'ils y croient alors, et que leurs cœurs s\'y soumettent en toute humilité. Allah guide certes vers le droit chemin ceux qui croient.\";s:13:\"numberInSurah\";i:54;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:338;s:4:\"ruku\";i:291;s:11:\"hizbQuarter\";i:135;s:5:\"sajda\";b:0;}i:54;a:9:{s:6:\"number\";i:2650;s:4:\"text\";s:176:\"Et ceux qui mécroient ne cesseront d\'être en doute à son sujet, jusqu\'à ce que l\'Heure les surprenne à l\'improviste ou que les atteigne le châtiment d\'un jour terrifiant.\";s:13:\"numberInSurah\";i:55;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:338;s:4:\"ruku\";i:291;s:11:\"hizbQuarter\";i:135;s:5:\"sajda\";b:0;}i:55;a:9:{s:6:\"number\";i:2651;s:4:\"text\";s:154:\"La souveraineté ce jour-là appartiendra à Allah qui jugera parmi eux. Ceux qui auront cru et fait de bonnes œuvres seront dans les Jardins du délice,\";s:13:\"numberInSurah\";i:56;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:339;s:4:\"ruku\";i:291;s:11:\"hizbQuarter\";i:135;s:5:\"sajda\";b:0;}i:56;a:9:{s:6:\"number\";i:2652;s:4:\"text\";s:111:\"et quant aux infidèles qui auront traité Nos révélations de mensonges, ils auront un châtiment avilissant!\";s:13:\"numberInSurah\";i:57;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:339;s:4:\"ruku\";i:291;s:11:\"hizbQuarter\";i:135;s:5:\"sajda\";b:0;}i:57;a:9:{s:6:\"number\";i:2653;s:4:\"text\";s:164:\"Ceux qui émigrent dans le sentier d\'Allah et qui sont tués ou meurent, Allah leur accordera certes une belle récompense, car Allah est le meilleur des donateurs.\";s:13:\"numberInSurah\";i:58;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:339;s:4:\"ruku\";i:292;s:11:\"hizbQuarter\";i:135;s:5:\"sajda\";b:0;}i:58;a:9:{s:6:\"number\";i:2654;s:4:\"text\";s:102:\"Il les fera, certes, entrer en un lieu qu\'ils agréeront, et Allah est certes Omniscient et Indulgent.\";s:13:\"numberInSurah\";i:59;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:339;s:4:\"ruku\";i:292;s:11:\"hizbQuarter\";i:135;s:5:\"sajda\";b:0;}i:59;a:9:{s:6:\"number\";i:2655;s:4:\"text\";s:198:\"Ainsi en est-il. Quiconque châtie de la même façon dont il a été châtié, et qu\'ensuite il est victime d\'un nouvel outrage, Allah l\'aidera, car Allah est certainement Absoluteur et Pardonneur.\";s:13:\"numberInSurah\";i:60;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:339;s:4:\"ruku\";i:292;s:11:\"hizbQuarter\";i:136;s:5:\"sajda\";b:0;}i:60;a:9:{s:6:\"number\";i:2656;s:4:\"text\";s:142:\"C\'est ainsi qu\'Allah fait pénétrer la nuit dans le jour, et fait pénétrer le jour dans la nuit. Allah est, certes, Audient et Clairvoyant.\";s:13:\"numberInSurah\";i:61;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:339;s:4:\"ruku\";i:292;s:11:\"hizbQuarter\";i:136;s:5:\"sajda\";b:0;}i:61;a:9:{s:6:\"number\";i:2657;s:4:\"text\";s:139:\"C\'est ainsi qu\'Allah est Lui le Vrai, alors que ce qu\'ils invoquent en dehors de Lui est le faux; c\'est Allah qui est le Sublime, le Grand.\";s:13:\"numberInSurah\";i:62;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:339;s:4:\"ruku\";i:292;s:11:\"hizbQuarter\";i:136;s:5:\"sajda\";b:0;}i:62;a:9:{s:6:\"number\";i:2658;s:4:\"text\";s:141:\"N\'as-tu pas vu qu\'Allah fait descendre l\'eau du ciel, et la terre devient alors verte? Allah est Plein de bonté et Parfaitement Connaisseur.\";s:13:\"numberInSurah\";i:63;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:339;s:4:\"ruku\";i:292;s:11:\"hizbQuarter\";i:136;s:5:\"sajda\";b:0;}i:63;a:9:{s:6:\"number\";i:2659;s:4:\"text\";s:136:\"A Lui appartient ce qui est dans les cieux et sur la terre. Allah est le seul qui se suffit à Lui-Même et qui est Le Digne de louange!\";s:13:\"numberInSurah\";i:64;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:339;s:4:\"ruku\";i:292;s:11:\"hizbQuarter\";i:136;s:5:\"sajda\";b:0;}i:64;a:9:{s:6:\"number\";i:2660;s:4:\"text\";s:263:\"N\'as-tu pas vu qu\'Allah vous a soumis tout ce qui est sur la terre ainsi que le vaisseau qui vogue sur la mer par Son ordre? Il retient le ciel de tomber sur la terre, sauf quand Il le permettra. Car Allah est Plein de bonté et de miséricorde envers les hommes.\";s:13:\"numberInSurah\";i:65;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:340;s:4:\"ruku\";i:293;s:11:\"hizbQuarter\";i:136;s:5:\"sajda\";b:0;}i:65;a:9:{s:6:\"number\";i:2661;s:4:\"text\";s:115:\"C\'est Lui qui vous donne la vie puis vous donne la mort, puis vous fait revivre. Vraiment l\'homme est très ingrat!\";s:13:\"numberInSurah\";i:66;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:340;s:4:\"ruku\";i:293;s:11:\"hizbQuarter\";i:136;s:5:\"sajda\";b:0;}i:66;a:9:{s:6:\"number\";i:2662;s:4:\"text\";s:178:\"A chaque communauté, Nous avons assigné un culte à suivre. Qu\'ils ne disputent donc point avec toi l\'ordre reçu! Et appelle à ton Seigneur. Tu es certes sur une voie droite.\";s:13:\"numberInSurah\";i:67;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:340;s:4:\"ruku\";i:293;s:11:\"hizbQuarter\";i:136;s:5:\"sajda\";b:0;}i:67;a:9:{s:6:\"number\";i:2663;s:4:\"text\";s:92:\"Et s\'ils discutent avec toi, alors dis: «C\'est Allah qui connaît mieux ce que vous faites.\";s:13:\"numberInSurah\";i:68;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:340;s:4:\"ruku\";i:293;s:11:\"hizbQuarter\";i:136;s:5:\"sajda\";b:0;}i:68;a:9:{s:6:\"number\";i:2664;s:4:\"text\";s:81:\"Allah jugera entre vous, au Jour de la Résurrection, ce en quoi vous divergez».\";s:13:\"numberInSurah\";i:69;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:340;s:4:\"ruku\";i:293;s:11:\"hizbQuarter\";i:136;s:5:\"sajda\";b:0;}i:69;a:9:{s:6:\"number\";i:2665;s:4:\"text\";s:136:\"Ne sais-tu pas qu\'Allah sait ce qu\'il y a dans le ciel et sur la terre? Tout cela est dans un Livre, et cela est pour Allah bien facile.\";s:13:\"numberInSurah\";i:70;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:340;s:4:\"ruku\";i:293;s:11:\"hizbQuarter\";i:136;s:5:\"sajda\";b:0;}i:70;a:9:{s:6:\"number\";i:2666;s:4:\"text\";s:174:\"Et ils adorent en dehors d\'Allah, ce en quoi Il n\'a fait descendre aucune preuve et ce dont ils n\'ont aucune connaissance. Et il n\'y aura pas de protecteur pour les injustes.\";s:13:\"numberInSurah\";i:71;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:340;s:4:\"ruku\";i:293;s:11:\"hizbQuarter\";i:136;s:5:\"sajda\";b:0;}i:71;a:9:{s:6:\"number\";i:2667;s:4:\"text\";s:334:\"Et quand on leur récite Nos versets bien clairs, tu discerneras la réprobation sur les visages de ceux qui ont mécru. Peu s\'en faut qu\'ils ne se jettent sur ceux qui leur récitent Nos versets. Dis: «Vous informerai-je de quelque chose de plus terrible? - Le Feu: Allah l\'a promis à ceux qui ont mécru. Et quel triste devenir!»\";s:13:\"numberInSurah\";i:72;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:340;s:4:\"ruku\";i:293;s:11:\"hizbQuarter\";i:136;s:5:\"sajda\";b:0;}i:72;a:9:{s:6:\"number\";i:2668;s:4:\"text\";s:326:\"O hommes! Une parabole vous est proposée, écoutez-la: «Ceux que vous invoquez en dehors d\'Allah ne sauraient même pas créer une mouche, quand même ils s\'uniraient pour cela. Et si la mouche les dépouillait de quelque chose, ils ne sauraient le lui reprendre. Le solliciteur et le sollicité sont [également] faibles!»\";s:13:\"numberInSurah\";i:73;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:341;s:4:\"ruku\";i:294;s:11:\"hizbQuarter\";i:136;s:5:\"sajda\";b:0;}i:73;a:9:{s:6:\"number\";i:2669;s:4:\"text\";s:82:\"Ils n\'ont pas estimé Allah à sa juste valeur; Allah est certes Fort et Puissant.\";s:13:\"numberInSurah\";i:74;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:341;s:4:\"ruku\";i:294;s:11:\"hizbQuarter\";i:136;s:5:\"sajda\";b:0;}i:74;a:9:{s:6:\"number\";i:2670;s:4:\"text\";s:98:\"Allah choisit des messagers parmi les Anges et parmi les hommes. Allah est Audient et Clairvoyant.\";s:13:\"numberInSurah\";i:75;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:341;s:4:\"ruku\";i:294;s:11:\"hizbQuarter\";i:136;s:5:\"sajda\";b:0;}i:75;a:9:{s:6:\"number\";i:2671;s:4:\"text\";s:88:\"Il sait ce qui est devant eux et derrière eux. Et c\'est vers Allah que tout retournera.\";s:13:\"numberInSurah\";i:76;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:341;s:4:\"ruku\";i:294;s:11:\"hizbQuarter\";i:136;s:5:\"sajda\";b:0;}i:76;a:9:{s:6:\"number\";i:2672;s:4:\"text\";s:120:\"O vous qui croyez! Inclinez-vous, prosternez-vous, adorez votre Seigneur, et faites le bien. Peut-être réussirez vous!\";s:13:\"numberInSurah\";i:77;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:341;s:4:\"ruku\";i:294;s:11:\"hizbQuarter\";i:136;s:5:\"sajda\";a:3:{s:2:\"id\";i:7;s:11:\"recommended\";b:1;s:10:\"obligatory\";b:0;}}i:77;a:9:{s:6:\"number\";i:2673;s:4:\"text\";s:512:\"Et luttez pour Allah avec tout l\'effort qu\'Il mérite. C\'est Lui qui vous a élus; et Il ne vous a imposé aucune gêne dans la religion, celle de votre père Abraham, lequel vous a déjà nommés «Musulmans» avant (ce Livre) et dans ce (Livre), afin que le Messager soit témoin contre vous, et que vous soyez vous-mêmes témoins contre les gens. Accomplissez donc la Salât, acquittez la Zakât et attachez-vous fortement à Allah. C\'est Lui votre Maître. Quel Excellent Maître! Et quel Excellent Soutien!\";s:13:\"numberInSurah\";i:78;s:3:\"juz\";i:17;s:6:\"manzil\";i:4;s:4:\"page\";i:341;s:4:\"ruku\";i:294;s:11:\"hizbQuarter\";i:136;s:5:\"sajda\";b:0;}}s:7:\"edition\";a:7:{s:10:\"identifier\";s:13:\"fr.hamidullah\";s:8:\"language\";s:2:\"fr\";s:4:\"name\";s:10:\"Hamidullah\";s:11:\"englishName\";s:19:\"Muhammad Hamidullah\";s:6:\"format\";s:4:\"text\";s:4:\"type\";s:11:\"translation\";s:9:\"direction\";s:3:\"ltr\";}}', 1794581355);
INSERT INTO `cache` (`key`, `value`, `expiration`) VALUES
('quranapp-cache-surah_23_ar.uthmani', 'a:8:{s:6:\"number\";i:23;s:4:\"name\";s:41:\"سُورَةُ المُؤۡمِنُونَ\";s:11:\"englishName\";s:11:\"Al-Muminoon\";s:22:\"englishNameTranslation\";s:13:\"The Believers\";s:14:\"revelationType\";s:6:\"Meccan\";s:13:\"numberOfAyahs\";i:118;s:5:\"ayahs\";a:118:{i:0;a:9:{s:6:\"number\";i:2674;s:4:\"text\";s:131:\"بِسۡمِ ٱللَّهِ ٱلرَّحۡمَـٰنِ ٱلرَّحِیمِ قَدۡ أَفۡلَحَ ٱلۡمُؤۡمِنُونَ\n\";s:13:\"numberInSurah\";i:1;s:3:\"juz\";i:18;s:6:\"manzil\";i:4;s:4:\"page\";i:342;s:4:\"ruku\";i:295;s:11:\"hizbQuarter\";i:137;s:5:\"sajda\";b:0;}i:1;a:9:{s:6:\"number\";i:2675;s:4:\"text\";s:81:\"ٱلَّذِینَ هُمۡ فِی صَلَاتِهِمۡ خَـٰشِعُونَ\n\";s:13:\"numberInSurah\";i:2;s:3:\"juz\";i:18;s:6:\"manzil\";i:4;s:4:\"page\";i:342;s:4:\"ruku\";i:295;s:11:\"hizbQuarter\";i:137;s:5:\"sajda\";b:0;}i:2;a:9:{s:6:\"number\";i:2676;s:4:\"text\";s:83:\"وَٱلَّذِینَ هُمۡ عَنِ ٱللَّغۡوِ مُعۡرِضُونَ\n\";s:13:\"numberInSurah\";i:3;s:3:\"juz\";i:18;s:6:\"manzil\";i:4;s:4:\"page\";i:342;s:4:\"ruku\";i:295;s:11:\"hizbQuarter\";i:137;s:5:\"sajda\";b:0;}i:3;a:9:{s:6:\"number\";i:2677;s:4:\"text\";s:80:\"وَٱلَّذِینَ هُمۡ لِلزَّكَوٰةِ فَـٰعِلُونَ\n\";s:13:\"numberInSurah\";i:4;s:3:\"juz\";i:18;s:6:\"manzil\";i:4;s:4:\"page\";i:342;s:4:\"ruku\";i:295;s:11:\"hizbQuarter\";i:137;s:5:\"sajda\";b:0;}i:4;a:9:{s:6:\"number\";i:2678;s:4:\"text\";s:82:\"وَٱلَّذِینَ هُمۡ لِفُرُوجِهِمۡ حَـٰفِظُونَ\n\";s:13:\"numberInSurah\";i:5;s:3:\"juz\";i:18;s:6:\"manzil\";i:4;s:4:\"page\";i:342;s:4:\"ruku\";i:295;s:11:\"hizbQuarter\";i:137;s:5:\"sajda\";b:0;}i:5;a:9:{s:6:\"number\";i:2679;s:4:\"text\";s:180:\"إِلَّا عَلَىٰۤ أَزۡوَ ٰ⁠جِهِمۡ أَوۡ مَا مَلَكَتۡ أَیۡمَـٰنُهُمۡ فَإِنَّهُمۡ غَیۡرُ مَلُومِینَ\n\";s:13:\"numberInSurah\";i:6;s:3:\"juz\";i:18;s:6:\"manzil\";i:4;s:4:\"page\";i:342;s:4:\"ruku\";i:295;s:11:\"hizbQuarter\";i:137;s:5:\"sajda\";b:0;}i:6;a:9:{s:6:\"number\";i:2680;s:4:\"text\";s:135:\"فَمَنِ ٱبۡتَغَىٰ وَرَاۤءَ ذَ ٰ⁠لِكَ فَأُو۟لَـٰۤىِٕكَ هُمُ ٱلۡعَادُونَ\n\";s:13:\"numberInSurah\";i:7;s:3:\"juz\";i:18;s:6:\"manzil\";i:4;s:4:\"page\";i:342;s:4:\"ruku\";i:295;s:11:\"hizbQuarter\";i:137;s:5:\"sajda\";b:0;}i:7;a:9:{s:6:\"number\";i:2681;s:4:\"text\";s:117:\"وَٱلَّذِینَ هُمۡ لِأَمَـٰنَـٰتِهِمۡ وَعَهۡدِهِمۡ رَ ٰ⁠عُونَ\n\";s:13:\"numberInSurah\";i:8;s:3:\"juz\";i:18;s:6:\"manzil\";i:4;s:4:\"page\";i:342;s:4:\"ruku\";i:295;s:11:\"hizbQuarter\";i:137;s:5:\"sajda\";b:0;}i:8;a:9:{s:6:\"number\";i:2682;s:4:\"text\";s:103:\"وَٱلَّذِینَ هُمۡ عَلَىٰ صَلَوَ ٰ⁠تِهِمۡ یُحَافِظُونَ\n\";s:13:\"numberInSurah\";i:9;s:3:\"juz\";i:18;s:6:\"manzil\";i:4;s:4:\"page\";i:342;s:4:\"ruku\";i:295;s:11:\"hizbQuarter\";i:137;s:5:\"sajda\";b:0;}i:9;a:9:{s:6:\"number\";i:2683;s:4:\"text\";s:71:\"أُو۟لَـٰۤىِٕكَ هُمُ ٱلۡوَ ٰ⁠رِثُونَ\n\";s:13:\"numberInSurah\";i:10;s:3:\"juz\";i:18;s:6:\"manzil\";i:4;s:4:\"page\";i:342;s:4:\"ruku\";i:295;s:11:\"hizbQuarter\";i:137;s:5:\"sajda\";b:0;}i:10;a:9:{s:6:\"number\";i:2684;s:4:\"text\";s:110:\"ٱلَّذِینَ یَرِثُونَ ٱلۡفِرۡدَوۡسَ هُمۡ فِیهَا خَـٰلِدُونَ\n\";s:13:\"numberInSurah\";i:11;s:3:\"juz\";i:18;s:6:\"manzil\";i:4;s:4:\"page\";i:342;s:4:\"ruku\";i:295;s:11:\"hizbQuarter\";i:137;s:5:\"sajda\";b:0;}i:11;a:9:{s:6:\"number\";i:2685;s:4:\"text\";s:111:\"وَلَقَدۡ خَلَقۡنَا ٱلۡإِنسَـٰنَ مِن سُلَـٰلَةࣲ مِّن طِینࣲ\n\";s:13:\"numberInSurah\";i:12;s:3:\"juz\";i:18;s:6:\"manzil\";i:4;s:4:\"page\";i:342;s:4:\"ruku\";i:295;s:11:\"hizbQuarter\";i:137;s:5:\"sajda\";b:0;}i:12;a:9:{s:6:\"number\";i:2686;s:4:\"text\";s:95:\"ثُمَّ جَعَلۡنَـٰهُ نُطۡفَةࣰ فِی قَرَارࣲ مَّكِینࣲ\n\";s:13:\"numberInSurah\";i:13;s:3:\"juz\";i:18;s:6:\"manzil\";i:4;s:4:\"page\";i:342;s:4:\"ruku\";i:295;s:11:\"hizbQuarter\";i:137;s:5:\"sajda\";b:0;}i:13;a:9:{s:6:\"number\";i:2687;s:4:\"text\";s:417:\"ثُمَّ خَلَقۡنَا ٱلنُّطۡفَةَ عَلَقَةࣰ فَخَلَقۡنَا ٱلۡعَلَقَةَ مُضۡغَةࣰ فَخَلَقۡنَا ٱلۡمُضۡغَةَ عِظَـٰمࣰا فَكَسَوۡنَا ٱلۡعِظَـٰمَ لَحۡمࣰا ثُمَّ أَنشَأۡنَـٰهُ خَلۡقًا ءَاخَرَۚ فَتَبَارَكَ ٱللَّهُ أَحۡسَنُ ٱلۡخَـٰلِقِینَ\n\";s:13:\"numberInSurah\";i:14;s:3:\"juz\";i:18;s:6:\"manzil\";i:4;s:4:\"pa