('quranapp-cache-surah_27_ar.uthmani', 'a:8:{s:6:\"number\";i:27;s:4:\"name\";s:33:\"سُورَةُ النَّمۡلِ\";s:11:\"englishName\";s:7:\"An-Naml\";s:22:\"englishNameTranslation\";s:7:\"The Ant\";s:14:\"revelationType\";s:6:\"Meccan\";s:13:\"numberOfAyahs\";i:93;s:5:\"ayahs\";a:93:{i:0;a:9:{s:6:\"number\";i:3160;s:4:\"text\";s:179:\"بِسۡمِ ٱللَّهِ ٱلرَّحۡمَـٰنِ ٱلرَّحِیمِ طسۤۚ تِلۡكَ ءَایَـٰتُ ٱلۡقُرۡءَانِ وَكِتَابࣲ مُّبِینٍ\n\";s:13:\"numberInSurah\";i:1;s:3:\"juz\";i:19;s:6:\"manzil\";i:5;s:4:\"page\";i:377;s:4:\"ruku\";i:327;s:11:\"hizbQuarter\";i:151;s:5:\"sajda\";b:0;}i:1;a:9:{s:6:\"number\";i:3161;s:4:\"text\";s:64:\"هُدࣰى وَبُشۡرَىٰ لِلۡمُؤۡمِنِینَ\n\";s:13:\"numberInSurah\";i:2;s:3:\"juz\";i:19;s:6:\"manzil\";i:5;s:4:\"page\";i:377;s:4:\"ruku\";i:327;s:11:\"hizbQuarter\";i:151;s:5:\"sajda\";b:0;}i:2;a:9:{s:6:\"number\";i:3162;s:4:\"text\";s:181:\"ٱلَّذِینَ یُقِیمُونَ ٱلصَّلَوٰةَ وَیُؤۡتُونَ ٱلزَّكَوٰةَ وَهُم بِٱلۡـَٔاخِرَةِ هُمۡ یُوقِنُونَ\n\";s:13:\"numberInSurah\";i:3;s:3:\"juz\";i:19;s:6:\"manzil\";i:5;s:4:\"page\";i:377;s:4:\"ruku\";i:327;s:11:\"hizbQuarter\";i:151;s:5:\"sajda\";b:0;}i:3;a:9:{s:6:\"number\";i:3163;s:4:\"text\";s:188:\"إِنَّ ٱلَّذِینَ لَا یُؤۡمِنُونَ بِٱلۡـَٔاخِرَةِ زَیَّنَّا لَهُمۡ أَعۡمَـٰلَهُمۡ فَهُمۡ یَعۡمَهُونَ\n\";s:13:\"numberInSurah\";i:4;s:3:\"juz\";i:19;s:6:\"manzil\";i:5;s:4:\"page\";i:377;s:4:\"ruku\";i:327;s:11:\"hizbQuarter\";i:151;s:5:\"sajda\";b:0;}i:4;a:9:{s:6:\"number\";i:3164;s:4:\"text\";s:180:\"أُو۟لَـٰۤىِٕكَ ٱلَّذِینَ لَهُمۡ سُوۤءُ ٱلۡعَذَابِ وَهُمۡ فِی ٱلۡـَٔاخِرَةِ هُمُ ٱلۡأَخۡسَرُونَ\n\";s:13:\"numberInSurah\";i:5;s:3:\"juz\";i:19;s:6:\"manzil\";i:5;s:4:\"page\";i:377;s:4:\"ruku\";i:327;s:11:\"hizbQuarter\";i:151;s:5:\"sajda\";b:0;}i:5;a:9:{s:6:\"number\";i:3165;s:4:\"text\";s:117:\"وَإِنَّكَ لَتُلَقَّى ٱلۡقُرۡءَانَ مِن لَّدُنۡ حَكِیمٍ عَلِیمٍ\n\";s:13:\"numberInSurah\";i:6;s:3:\"juz\";i:19;s:6:\"manzil\";i:5;s:4:\"page\";i:377;s:4:\"ruku\";i:327;s:11:\"hizbQuarter\";i:151;s:5:\"sajda\";b:0;}i:6;a:9:{s:6:\"number\";i:3166;s:4:\"text\";s:277:\"إِذۡ قَالَ مُوسَىٰ لِأَهۡلِهِۦۤ إِنِّیۤ ءَانَسۡتُ نَارࣰا سَـَٔاتِیكُم مِّنۡهَا بِخَبَرٍ أَوۡ ءَاتِیكُم بِشِهَابࣲ قَبَسࣲ لَّعَلَّكُمۡ تَصۡطَلُونَ\n\";s:13:\"numberInSurah\";i:7;s:3:\"juz\";i:19;s:6:\"manzil\";i:5;s:4:\"page\";i:377;s:4:\"ruku\";i:327;s:11:\"hizbQuarter\";i:151;s:5:\"sajda\";b:0;}i:7;a:9:{s:6:\"number\";i:3167;s:4:\"text\";s:218:\"فَلَمَّا جَاۤءَهَا نُودِیَ أَنۢ بُورِكَ مَن فِی ٱلنَّارِ وَمَنۡ حَوۡلَهَا وَسُبۡحَـٰنَ ٱللَّهِ رَبِّ ٱلۡعَـٰلَمِینَ\n\";s:13:\"numberInSurah\";i:8;s:3:\"juz\";i:19;s:6:\"manzil\";i:5;s:4:\"page\";i:377;s:4:\"ruku\";i:327;s:11:\"hizbQuarter\";i:151;s:5:\"sajda\";b:0;}i:8;a:9:{s:6:\"number\";i:3168;s:4:\"text\";s:112:\"یَـٰمُوسَىٰۤ إِنَّهُۥۤ أَنَا ٱللَّهُ ٱلۡعَزِیزُ ٱلۡحَكِیمُ\n\";s:13:\"numberInSurah\";i:9;s:3:\"juz\";i:19;s:6:\"manzil\";i:5;s:4:\"page\";i:377;s:4:\"ruku\";i:327;s:11:\"hizbQuarter\";i:151;s:5:\"sajda\";b:0;}i:9;a:9:{s:6:\"number\";i:3169;s:4:\"text\";s:315:\"وَأَلۡقِ عَصَاكَۚ فَلَمَّا رَءَاهَا تَهۡتَزُّ كَأَنَّهَا جَاۤنࣱّ وَلَّىٰ مُدۡبِرࣰا وَلَمۡ یُعَقِّبۡۚ یَـٰمُوسَىٰ لَا تَخَفۡ إِنِّی لَا یَخَافُ لَدَیَّ ٱلۡمُرۡسَلُونَ\n\";s:13:\"numberInSurah\";i:10;s:3:\"juz\";i:19;s:6:\"manzil\";i:5;s:4:\"page\";i:377;s:4:\"ruku\";i:327;s:11:\"hizbQuarter\";i:151;s:5:\"sajda\";b:0;}i:10;a:9:{s:6:\"number\";i:3170;s:4:\"text\";s:154:\"إِلَّا مَن ظَلَمَ ثُمَّ بَدَّلَ حُسۡنَۢا بَعۡدَ سُوۤءࣲ فَإِنِّی غَفُورࣱ رَّحِیمࣱ\n\";s:13:\"numberInSurah\";i:11;s:3:\"juz\";i:19;s:6:\"manzil\";i:5;s:4:\"page\";i:377;s:4:\"ruku\";i:327;s:11:\"hizbQuarter\";i:151;s:5:\"sajda\";b:0;}i:11;a:9:{s:6:\"number\";i:3171;s:4:\"text\";s:309:\"وَأَدۡخِلۡ یَدَكَ فِی جَیۡبِكَ تَخۡرُجۡ بَیۡضَاۤءَ مِنۡ غَیۡرِ سُوۤءࣲۖ فِی تِسۡعِ ءَایَـٰتٍ إِلَىٰ فِرۡعَوۡنَ وَقَوۡمِهِۦۤۚ إِنَّهُمۡ كَانُوا۟ قَوۡمࣰا فَـٰسِقِینَ\n\";s:13:\"numberInSurah\";i:12;s:3:\"juz\";i:19;s:6:\"manzil\";i:5;s:4:\"page\";i:377;s:4:\"ruku\";i:327;s:11:\"hizbQuarter\";i:151;s:5:\"sajda\";b:0;}i:12;a:9:{s:6:\"number\";i:3172;s:4:\"text\";s:153:\"فَلَمَّا جَاۤءَتۡهُمۡ ءَایَـٰتُنَا مُبۡصِرَةࣰ قَالُوا۟ هَـٰذَا سِحۡرࣱ مُّبِینࣱ\n\";s:13:\"numberInSurah\";i:13;s:3:\"juz\";i:19;s:6:\"manzil\";i:5;s:4:\"page\";i:377;s:4:\"ruku\";i:327;s:11:\"hizbQuarter\";i:151;s:5:\"sajda\";b:0;}i:13;a:9:{s:6:\"number\";i:3173;s:4:\"text\";s:227:\"وَجَحَدُوا۟ بِهَا وَٱسۡتَیۡقَنَتۡهَاۤ أَنفُسُهُمۡ ظُلۡمࣰا وَعُلُوࣰّاۚ فَٱنظُرۡ كَیۡفَ كَانَ عَـٰقِبَةُ ٱلۡمُفۡسِدِینَ\n\";s:13:\"numberInSurah\";i:14;s:3:\"juz\";i:19;s:6:\"manzil\";i:5;s:4:\"page\";i:378;s:4:\"ruku\";i:327;s:11:\"hizbQuarter\";i:151;s:5:\"sajda\";b:0;}i:14;a:9:{s:6:\"number\";i:3174;s:4:\"text\";s:277:\"وَلَقَدۡ ءَاتَیۡنَا دَاوُۥدَ وَسُلَیۡمَـٰنَ عِلۡمࣰاۖ وَقَالَا ٱلۡحَمۡدُ لِلَّهِ ٱلَّذِی فَضَّلَنَا عَلَىٰ كَثِیرࣲ مِّنۡ عِبَادِهِ ٱلۡمُؤۡمِنِینَ\n\";s:13:\"numberInSurah\";i:15;s:3:\"juz\";i:19;s:6:\"manzil\";i:5;s:4:\"page\";i:378;s:4:\"ruku\";i:328;s:11:\"hizbQuarter\";i:151;s:5:\"sajda\";b:0;}i:15;a:9:{s:6:\"number\";i:3175;s:4:\"text\";s:310:\"وَوَرِثَ سُلَیۡمَـٰنُ دَاوُۥدَۖ وَقَالَ یَـٰۤأَیُّهَا ٱلنَّاسُ عُلِّمۡنَا مَنطِقَ ٱلطَّیۡرِ وَأُوتِینَا مِن كُلِّ شَیۡءٍۖ إِنَّ هَـٰذَا لَهُوَ ٱلۡفَضۡلُ ٱلۡمُبِینُ\n\";s:13:\"numberInSurah\";i:16;s:3:\"juz\";i:19;s:6:\"manzil\";i:5;s:4:\"page\";i:378;s:4:\"ruku\";i:328;s:11:\"hizbQuarter\";i:151;s:5:\"sajda\";b:0;}i:16;a:9:{s:6:\"number\";i:3176;s:4:\"text\";s:171:\"وَحُشِرَ لِسُلَیۡمَـٰنَ جُنُودُهُۥ مِنَ ٱلۡجِنِّ وَٱلۡإِنسِ وَٱلطَّیۡرِ فَهُمۡ یُوزَعُونَ\n\";s:13:\"numberInSurah\";i:17;s:3:\"juz\";i:19;s:6:\"manzil\";i:5;s:4:\"page\";i:378;s:4:\"ruku\";i:328;s:11:\"hizbQuarter\";i:151;s:5:\"sajda\";b:0;}i:17;a:9:{s:6:\"number\";i:3177;s:4:\"text\";s:350:\"حَتَّىٰۤ إِذَاۤ أَتَوۡا۟ عَلَىٰ وَادِ ٱلنَّمۡلِ قَالَتۡ نَمۡلَةࣱ یَـٰۤأَیُّهَا ٱلنَّمۡلُ ٱدۡخُلُوا۟ مَسَـٰكِنَكُمۡ لَا یَحۡطِمَنَّكُمۡ سُلَیۡمَـٰنُ وَجُنُودُهُۥ وَهُمۡ لَا یَشۡعُرُونَ\n\";s:13:\"numberInSurah\";i:18;s:3:\"juz\";i:19;s:6:\"manzil\";i:5;s:4:\"page\";i:378;s:4:\"ruku\";i:328;s:11:\"hizbQuarter\";i:151;s:5:\"sajda\";b:0;}i:18;a:9:{s:6:\"number\";i:3178;s:4:\"text\";s:442:\"فَتَبَسَّمَ 