('quranapp-cache-surah_28_ar.uthmani', 'a:8:{s:6:\"number\";i:28;s:4:\"name\";s:31:\"سُورَةُ القَصَصِ\";s:11:\"englishName\";s:8:\"Al-Qasas\";s:22:\"englishNameTranslation\";s:11:\"The Stories\";s:14:\"revelationType\";s:6:\"Meccan\";s:13:\"numberOfAyahs\";i:88;s:5:\"ayahs\";a:88:{i:0;a:9:{s:6:\"number\";i:3253;s:4:\"text\";s:87:\"بِسۡمِ ٱللَّهِ ٱلرَّحۡمَـٰنِ ٱلرَّحِیمِ طسۤمۤ\n\";s:13:\"numberInSurah\";i:1;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:385;s:4:\"ruku\";i:334;s:11:\"hizbQuarter\";i:154;s:5:\"sajda\";b:0;}i:1;a:9:{s:6:\"number\";i:3254;s:4:\"text\";s:76:\"تِلۡكَ ءَایَـٰتُ ٱلۡكِتَـٰبِ ٱلۡمُبِینِ\n\";s:13:\"numberInSurah\";i:2;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:385;s:4:\"ruku\";i:334;s:11:\"hizbQuarter\";i:154;s:5:\"sajda\";b:0;}i:2;a:9:{s:6:\"number\";i:3255;s:4:\"text\";s:160:\"نَتۡلُوا۟ عَلَیۡكَ مِن نَّبَإِ مُوسَىٰ وَفِرۡعَوۡنَ بِٱلۡحَقِّ لِقَوۡمࣲ یُؤۡمِنُونَ\n\";s:13:\"numberInSurah\";i:3;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:385;s:4:\"ruku\";i:334;s:11:\"hizbQuarter\";i:154;s:5:\"sajda\";b:0;}i:3;a:9:{s:6:\"number\";i:3256;s:4:\"text\";s:357:\"إِنَّ فِرۡعَوۡنَ عَلَا فِی ٱلۡأَرۡضِ وَجَعَلَ أَهۡلَهَا شِیَعࣰا یَسۡتَضۡعِفُ طَاۤىِٕفَةࣰ مِّنۡهُمۡ یُذَبِّحُ أَبۡنَاۤءَهُمۡ وَیَسۡتَحۡیِۦ نِسَاۤءَهُمۡۚ إِنَّهُۥ كَانَ مِنَ ٱلۡمُفۡسِدِینَ\n\";s:13:\"numberInSurah\";i:4;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:385;s:4:\"ruku\";i:334;s:11:\"hizbQuarter\";i:154;s:5:\"sajda\";b:0;}i:4;a:9:{s:6:\"number\";i:3257;s:4:\"text\";s:241:\"وَنُرِیدُ أَن نَّمُنَّ عَلَى ٱلَّذِینَ ٱسۡتُضۡعِفُوا۟ فِی ٱلۡأَرۡضِ وَنَجۡعَلَهُمۡ أَىِٕمَّةࣰ وَنَجۡعَلَهُمُ ٱلۡوَ ٰ⁠رِثِینَ\n\";s:13:\"numberInSurah\";i:5;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:385;s:4:\"ruku\";i:334;s:11:\"hizbQuarter\";i:154;s:5:\"sajda\";b:0;}i:5;a:9:{s:6:\"number\";i:3258;s:4:\"text\";s:218:\"وَنُمَكِّنَ لَهُمۡ فِی ٱلۡأَرۡضِ وَنُرِیَ فِرۡعَوۡنَ وَهَـٰمَـٰنَ وَجُنُودَهُمَا مِنۡهُم مَّا كَانُوا۟ یَحۡذَرُونَ\n\";s:13:\"numberInSurah\";i:6;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:386;s:4:\"ruku\";i:334;s:11:\"hizbQuarter\";i:154;s:5:\"sajda\";b:0;}i:6;a:9:{s:6:\"number\";i:3259;s:4:\"text\";s:374:\"وَأَوۡحَیۡنَاۤ إِلَىٰۤ أُمِّ مُوسَىٰۤ أَنۡ أَرۡضِعِیهِۖ فَإِذَا خِفۡتِ عَلَیۡهِ فَأَلۡقِیهِ فِی ٱلۡیَمِّ وَلَا تَخَافِی وَلَا تَحۡزَنِیۤۖ إِنَّا رَاۤدُّوهُ إِلَیۡكِ وَجَاعِلُوهُ مِنَ ٱلۡمُرۡسَلِینَ\n\";s:13:\"numberInSurah\";i:7;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:386;s:4:\"ruku\";i:334;s:11:\"hizbQuarter\";i:154;s:5:\"sajda\";b:0;}i:7;a:9:{s:6:\"number\";i:3260;s:4:\"text\";s:262:\"فَٱلۡتَقَطَهُۥۤ ءَالُ فِرۡعَوۡنَ لِیَكُونَ لَهُمۡ عَدُوࣰّا وَحَزَنًاۗ إِنَّ فِرۡعَوۡنَ وَهَـٰمَـٰنَ وَجُنُودَهُمَا كَانُوا۟ خَـٰطِـِٔینَ\n\";s:13:\"numberInSurah\";i:8;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:386;s:4:\"ruku\";i:334;s:11:\"hizbQuarter\";i:154;s:5:\"sajda\";b:0;}i:8;a:9:{s:6:\"number\";i:3261;s:4:\"text\";s:280:\"وَقَالَتِ ٱمۡرَأَتُ فِرۡعَوۡنَ قُرَّتُ عَیۡنࣲ لِّی وَلَكَۖ لَا تَقۡتُلُوهُ عَسَىٰۤ أَن یَنفَعَنَاۤ أَوۡ نَتَّخِذَهُۥ وَلَدࣰا وَهُمۡ لَا یَشۡعُرُونَ\n\";s:13:\"numberInSurah\";i:9;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:386;s:4:\"ruku\";i:334;s:11:\"hizbQuarter\";i:154;s:5:\"sajda\";b:0;}i:9;a:9:{s:6:\"number\";i:3262;s:4:\"text\";s:269:\"وَأَصۡبَحَ فُؤَادُ أُمِّ مُوسَىٰ فَـٰرِغًاۖ إِن كَادَتۡ لَتُبۡدِی بِهِۦ لَوۡلَاۤ أَن رَّبَطۡنَا عَلَىٰ قَلۡبِهَا لِتَكُونَ مِنَ ٱلۡمُؤۡمِنِینَ\n\";s:13:\"numberInSurah\";i:10;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:386;s:4:\"ruku\";i:334;s:11:\"hizbQuarter\";i:154;s:5:\"sajda\";b:0;}i:10;a:9:{s:6:\"number\";i:3263;s:4:\"text\";s:157:\"وَقَالَتۡ لِأُخۡتِهِۦ قُصِّیهِۖ فَبَصُرَتۡ بِهِۦ عَن جُنُبࣲ وَهُمۡ لَا یَشۡعُرُونَ\n\";s:13:\"numberInSurah\";i:11;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:386;s:4:\"ruku\";i:334;s:11:\"hizbQuarter\";i:154;s:5:\"sajda\";b:0;}i:11;a:9:{s:6:\"number\";i:3264;s:4:\"text\";s:272:\"۞ وَحَرَّمۡنَا عَلَیۡهِ ٱلۡمَرَاضِعَ مِن قَبۡلُ فَقَالَتۡ هَلۡ أَدُلُّكُمۡ عَلَىٰۤ أَهۡلِ بَیۡتࣲ یَكۡفُلُونَهُۥ لَكُمۡ وَهُمۡ لَهُۥ نَـٰصِحُونَ\n\";s:13:\"numberInSurah\";i:12;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:386;s:4:\"ruku\";i:334;s:11:\"hizbQuarter\";i:155;s:5:\"sajda\";b:0;}i:12;a:9:{s:6:\"number\";i:3265;s:4:\"text\";s:286:\"فَرَدَدۡنَـٰهُ إِلَىٰۤ أُمِّهِۦ كَیۡ تَقَرَّ عَیۡنُهَا وَلَا تَحۡزَنَ وَلِتَعۡلَمَ أَنَّ وَعۡدَ ٱللَّهِ حَقࣱّ وَلَـٰكِنَّ أَكۡثَرَهُمۡ لَا یَعۡلَمُونَ\n\";s:13:\"numberInSurah\";i:13;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:386;s:4:\"ruku\";i:334;s:11:\"hizbQuarter\";i:155;s:5:\"sajda\";b:0;}i:13;a:9:{s:6:\"number\";i:3266;s:4:\"text\";s:214:\"وَلَمَّا بَلَغَ أَشُدَّهُۥ وَٱسۡتَوَىٰۤ ءَاتَیۡنَـٰهُ حُكۡمࣰا وَعِلۡمࣰاۚ وَكَذَ ٰ⁠لِكَ نَجۡزِی ٱلۡمُحۡسِنِینَ\n\";s:13:\"numberInSurah\";i:14;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:387;s:4:\"ruku\";i:335;s:11:\"hizbQuarter\";i:155;s:5:\"sajda\";b:0;}i:14;a:9:{s:6:\"number\";i:3267;s:4:\"text\";s:636:\"وَدَخَلَ ٱلۡمَدِینَةَ عَلَىٰ حِینِ غَفۡلَةࣲ مِّنۡ أَهۡلِهَا فَوَجَدَ فِیهَا رَجُلَیۡنِ یَقۡتَتِلَانِ هَـٰذَا مِن شِیعَتِهِۦ وَهَـٰذَا مِنۡ عَدُوِّهِۦۖ فَٱسۡتَغَـٰثَهُ ٱلَّذِی مِن شِیعَتِهِۦ عَلَى ٱلَّذِی مِنۡ عَدُوِّهِۦ فَوَكَزَهُۥ مُوسَىٰ فَقَضَىٰ عَلَیۡهِۖ قَالَ هَـٰذَا مِنۡ عَمَلِ ٱلشَّیۡطَـٰنِۖ إِنَّهُۥ عَدُوࣱّ مُّضِلࣱّ مُّبِینࣱ\n\";s:13:\"numberInSurah\";i:15;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:387;s:4:\"ruku\";i:335;s:11:\"hizbQuarter\";i:155;s:5:\"sajda\";b:0;}i:15;a:9:{s:6:\"number\";i:3268;s:4:\"text\";s:193:\"قَالَ رَبِّ إِنِّی ظَلَمۡتُ نَفۡسِی فَٱغۡفِرۡ لِی فَغَفَرَ لَهُۥۤۚ إِنَّهُۥ هُوَ ٱلۡغَفُورُ ٱلرَّحِیمُ\n\";s:13:\"numberInSurah\";i:16;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:387;s:4:\"ruku\";i:335;s:11:\"hizbQuarter\";i:155;s:5:\"sajda\";b:0;}i:16;a:9:{s:6:\"number\";i:3269;s:4:\"text\";s:150:\"قَالَ رَبِّ بِمَاۤ أَنۡعَمۡتَ عَلَیَّ فَلَنۡ أَكُونَ ظَهِیرࣰا لِّلۡمُجۡرِمِینَ\n\";s:13:\"numberInSurah\";i:17;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:387;s:4:\"ruku\";i:335;s:11:\"hizbQuarter\";i:155;s:5:\"sajda\";b:0;}i:17;a:9:{s:6:\"number\";i:3270;s:4:\"text\";s:303:\"فَأَصۡبَحَ فِی ٱلۡمَدِینَةِ خَاۤىِٕفࣰا یَتَرَقَّبُ فَإِذَا ٱلَّذِی ٱسۡتَنصَرَهُۥ بِٱلۡأَمۡسِ یَسۡتَصۡرِخُهُۥۚ قَالَ لَهُۥ مُوسَىٰۤ إِنَّكَ لَغَوِیࣱّ مُّبِینࣱ\n\";s:13:\"numberInSurah\";i:18;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:387;s:4:\"ruku\";i:335;s:11:\"hizbQuarter\";i:155;s:5:\"sajda\";b:0;}i:18;a:9:{s:6:\"number\";i:3271;s:4:\"text\";s:474:\"فَلَمَّاۤ أَنۡ أَرَادَ أَن یَبۡطِشَ بِٱلَّذِی هُوَ عَدُوࣱّ لَّهُمَا قَالَ یَـٰمُوسَىٰۤ أَتُرِیدُ أَن تَقۡتُلَنِی كَمَا قَتَلۡتَ نَفۡسَۢا بِٱلۡأَمۡسِۖ إِن تُرِیدُ إِلَّاۤ أَن تَكُونَ جَبَّارࣰا فِی ٱلۡأَرۡضِ وَمَا تُرِیدُ أَن تَكُونَ مِنَ ٱلۡمُصۡلِحِینَ\n\";s:13:\"numberInSurah\";i:19;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:387;s:4:\"ruku\";i:335;s:11:\"hizbQuarter\";i:155;s:5:\"sajda\";b:0;}i:19;a:9:{s:6:\"number\";i:3272;s:4:\"text\";s:307:\"وَجَاۤءَ رَجُلࣱ مِّنۡ أَقۡصَا ٱلۡمَدِینَةِ یَسۡعَىٰ قَالَ یَـٰمُوسَىٰۤ إِنَّ ٱلۡمَلَأَ یَأۡتَمِرُونَ بِكَ لِیَقۡتُلُوكَ فَٱخۡرُجۡ إِنِّی لَكَ مِنَ ٱلنَّـٰصِحِینَ\n\";s:13:\"numberInSurah\";i:20;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:387;s:4:\"ruku\";i:335;s:11:\"hizbQuarter\";i:155;s:5:\"sajda\";b:0;}i:20;a:9:{s:6:\"number\";i:3273;s:4:\"text\";s:175:\"فَخَرَجَ مِنۡهَا خَاۤىِٕفࣰا یَتَرَقَّبُۖ قَالَ رَبِّ نَجِّنِی مِنَ ٱلۡقَوۡمِ ٱلظَّـٰلِمِینَ\n\";s:13:\"numberInSurah\";i:21;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:387;s:4:\"ruku\";i:335;s:11:\"hizbQuarter\";i:155;s:5:\"sajda\";b:0;}i:21;a:9:{s:6:\"number\";i:3274;s:4:\"text\";s:181:\"وَلَمَّا تَوَجَّهَ تِلۡقَاۤءَ مَدۡیَنَ قَالَ عَسَىٰ رَبِّیۤ أَن یَهۡدِیَنِی سَوَاۤءَ ٱلسَّبِیلِ\n\";s:13:\"numberInSurah\";i:22;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:388;s:4:\"ruku\";i:336;s:11:\"hizbQuarter\";i:155;s:5:\"sajda\";b:0;}i:22;a:9:{s:6:\"number\";i:3275;s:4:\"text\";s:436:\"وَلَمَّا وَرَدَ مَاۤءَ مَدۡیَنَ وَجَدَ عَلَیۡهِ أُمَّةࣰ مِّنَ ٱلنَّاسِ یَسۡقُونَ وَوَجَدَ مِن دُونِهِمُ ٱمۡرَأَتَیۡنِ تَذُودَانِۖ قَالَ مَا خَطۡبُكُمَاۖ قَالَتَا لَا نَسۡقِی حَتَّىٰ یُصۡدِرَ ٱلرِّعَاۤءُۖ وَأَبُونَا شَیۡخࣱ كَبِیرࣱ\n\";s:13:\"numberInSurah\";i:23;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:388;s:4:\"ruku\";i:336;s:11:\"hizbQuarter\";i:155;s:5:\"sajda\";b:0;}i:23;a:9:{s:6:\"number\";i:3276;s:4:\"text\";s:217:\"فَسَقَىٰ لَهُمَا ثُمَّ تَوَلَّىٰۤ إِلَى ٱلظِّلِّ فَقَالَ رَبِّ إِنِّی لِمَاۤ أَنزَلۡتَ إِلَیَّ مِنۡ خَیۡرࣲ فَقِیرࣱ\n\";s:13:\"numberInSurah\";i:24;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:388;s:4:\"ruku\";i:336;s:11:\"hizbQuarter\";i:155;s:5:\"sajda\";b:0;}i:24;a:9:{s:6:\"number\";i:3277;s:4:\"text\";s:431:\"فَجَاۤءَتۡهُ إِحۡدَىٰهُمَا تَمۡشِی عَلَى ٱسۡتِحۡیَاۤءࣲ قَالَتۡ إِنَّ أَبِی یَدۡعُوكَ لِیَجۡزِیَكَ أَجۡرَ مَا سَقَیۡتَ لَنَاۚ فَلَمَّا جَاۤءَهُۥ وَقَصَّ عَلَیۡهِ ٱلۡقَصَصَ قَالَ لَا تَخَفۡۖ نَجَوۡتَ مِنَ ٱلۡقَوۡمِ ٱلظَّـٰلِمِینَ\n\";s:13:\"numberInSurah\";i:25;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:388;s:4:\"ruku\";i:336;s:11:\"hizbQuarter\";i:155;s:5:\"sajda\";b:0;}i:25;a:9:{s:6:\"number\";i:3278;s:4:\"text\";s:200:\"قَالَتۡ إِحۡدَىٰهُمَا یَـٰۤأَبَتِ ٱسۡتَـٔۡجِرۡهُۖ إِنَّ خَیۡرَ مَنِ ٱسۡتَـٔۡجَرۡتَ ٱلۡقَوِیُّ ٱلۡأَمِینُ\n\";s:13:\"numberInSurah\";i:26;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:388;s:4:\"ruku\";i:336;s:11:\"hizbQuarter\";i:155;s:5:\"sajda\";b:0;}i:26;a:9:{s:6:\"number\";i:3279;s:4:\"text\";s:457:\"قَالَ إِنِّیۤ أُرِیدُ أَنۡ أُنكِحَكَ إِحۡدَى ٱبۡنَتَیَّ هَـٰتَیۡنِ عَلَىٰۤ أَن تَأۡجُرَنِی ثَمَـٰنِیَ حِجَجࣲۖ فَإِنۡ أَتۡمَمۡتَ عَشۡرࣰا فَمِنۡ عِندِكَۖ وَمَاۤ أُرِیدُ أَنۡ أَشُقَّ عَلَیۡكَۚ سَتَجِدُنِیۤ إِن شَاۤءَ ٱللَّهُ مِنَ ٱلصَّـٰلِحِینَ\n\";s:13:\"numberInSurah\";i:27;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:388;s:4:\"ruku\";i:336;s:11:\"hizbQuarter\";i:155;s:5:\"sajda\";b:0;}i:27;a:9:{s:6:\"number\";i:3280;s:4:\"text\";s:254:\"قَالَ ذَ ٰ⁠لِكَ بَیۡنِی وَبَیۡنَكَۖ أَیَّمَا ٱلۡأَجَلَیۡنِ قَضَیۡتُ فَلَا عُدۡوَ ٰ⁠نَ عَلَیَّۖ وَٱللَّهُ عَلَىٰ مَا نَقُولُ وَكِیلࣱ\n\";s:13:\"numberInSurah\";i:28;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:388;s:4:\"ruku\";i:336;s:11:\"hizbQuarter\";i:155;s:5:\"sajda\";b:0;}i:28;a:9:{s:6:\"number\";i:3281;s:4:\"text\";s:453:\"۞ فَلَمَّا قَضَىٰ مُوسَى ٱلۡأَجَلَ وَسَارَ بِأَهۡلِهِۦۤ ءَانَسَ مِن جَانِبِ ٱلطُّورِ نَارࣰاۖ قَالَ لِأَهۡلِهِ ٱمۡكُثُوۤا۟ إِنِّیۤ ءَانَسۡتُ نَارࣰا لَّعَلِّیۤ ءَاتِیكُم مِّنۡهَا بِخَبَرٍ أَوۡ جَذۡوَةࣲ مِّنَ ٱلنَّارِ لَعَلَّكُمۡ تَصۡطَلُونَ\n\";s:13:\"numberInSurah\";i:29;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:389;s:4:\"ruku\";i:337;s:11:\"hizbQuarter\";i:156;s:5:\"sajda\";b:0;}i:29;a:9:{s:6:\"number\";i:3282;s:4:\"text\";s:325:\"فَلَمَّاۤ أَتَىٰهَا نُودِیَ مِن شَـٰطِىِٕ ٱلۡوَادِ ٱلۡأَیۡمَنِ فِی ٱلۡبُقۡعَةِ ٱلۡمُبَـٰرَكَةِ مِنَ ٱلشَّجَرَةِ أَن یَـٰمُوسَىٰۤ إِنِّیۤ أَنَا ٱللَّهُ رَبُّ ٱلۡعَـٰلَمِینَ\n\";s:13:\"numberInSurah\";i:30;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:389;s:4:\"ruku\";i:337;s:11:\"hizbQuarter\";i:156;s:5:\"sajda\";b:0;}i:30;a:9:{s:6:\"number\";i:3283;s:4:\"text\";s:323:\"وَأَنۡ أَلۡقِ عَصَاكَۚ فَلَمَّا رَءَاهَا تَهۡتَزُّ كَأَنَّهَا جَاۤنࣱّ وَلَّىٰ مُدۡبِرࣰا وَلَمۡ یُعَقِّبۡۚ یَـٰمُوسَىٰۤ أَقۡبِلۡ وَلَا تَخَفۡۖ إِنَّكَ مِنَ ٱلۡـَٔامِنِینَ\n\";s:13:\"numberInSurah\";i:31;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:389;s:4:\"ruku\";i:337;s:11:\"hizbQuarter\";i:156;s:5:\"sajda\";b:0;}i:31;a:9:{s:6:\"number\";i:3284;s:4:\"text\";s:427:\"ٱسۡلُكۡ یَدَكَ فِی جَیۡبِكَ تَخۡرُجۡ بَیۡضَاۤءَ مِنۡ غَیۡرِ سُوۤءࣲ وَٱضۡمُمۡ إِلَیۡكَ جَنَاحَكَ مِنَ ٱلرَّهۡبِۖ فَذَ ٰ⁠نِكَ بُرۡهَـٰنَانِ مِن رَّبِّكَ إِلَىٰ فِرۡعَوۡنَ وَمَلَإِی۟هِۦۤۚ إِنَّهُمۡ كَانُوا۟ قَوۡمࣰا فَـٰسِقِینَ\n\";s:13:\"numberInSurah\";i:32;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:389;s:4:\"ruku\";i:337;s:11:\"hizbQuarter\";i:156;s:5:\"sajda\";b:0;}i:32;a:9:{s:6:\"number\";i:3285;s:4:\"text\";s:134:\"قَالَ رَبِّ إِنِّی قَتَلۡتُ مِنۡهُمۡ نَفۡسࣰا فَأَخَافُ أَن یَقۡتُلُونِ\n\";s:13:\"numberInSurah\";i:33;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:389;s:4:\"ruku\";i:337;s:11:\"hizbQuarter\";i:156;s:5:\"sajda\";b:0;}i:33;a:9:{s:6:\"number\";i:3286;s:4:\"text\";s:236:\"وَأَخِی هَـٰرُونُ هُوَ أَفۡصَحُ مِنِّی لِسَانࣰا فَأَرۡسِلۡهُ مَعِیَ رِدۡءࣰا یُصَدِّقُنِیۤۖ إِنِّیۤ أَخَافُ أَن یُكَذِّبُونِ\n\";s:13:\"numberInSurah\";i:34;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:389;s:4:\"ruku\";i:337;s:11:\"hizbQuarter\";i:156;s:5:\"sajda\";b:0;}i:34;a:9:{s:6:\"number\";i:3287;s:4:\"text\";s:300:\"قَالَ سَنَشُدُّ عَضُدَكَ بِأَخِیكَ وَنَجۡعَلُ لَكُمَا سُلۡطَـٰنࣰا فَلَا یَصِلُونَ إِلَیۡكُمَا بِـَٔایَـٰتِنَاۤۚ أَنتُمَا وَمَنِ ٱتَّبَعَكُمَا ٱلۡغَـٰلِبُونَ\n\";s:13:\"numberInSurah\";i:35;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:389;s:4:\"ruku\";i:337;s:11:\"hizbQuarter\";i:156;s:5:\"sajda\";b:0;}i:35;a:9:{s:6:\"number\";i:3288;s:4:\"text\";s:310:\"فَلَمَّا جَاۤءَهُم مُّوسَىٰ بِـَٔایَـٰتِنَا بَیِّنَـٰتࣲ قَالُوا۟ مَا هَـٰذَاۤ إِلَّا سِحۡرࣱ مُّفۡتَرࣰى وَمَا سَمِعۡنَا بِهَـٰذَا فِیۤ ءَابَاۤىِٕنَا ٱلۡأَوَّلِینَ\n\";s:13:\"numberInSurah\";i:36;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:390;s:4:\"ruku\";i:337;s:11:\"hizbQuarter\";i:156;s:5:\"sajda\";b:0;}i:36;a:9:{s:6:\"number\";i:3289;s:4:\"text\";s:282:\"وَقَالَ مُوسَىٰ رَبِّیۤ أَعۡلَمُ بِمَن جَاۤءَ بِٱلۡهُدَىٰ مِنۡ عِندِهِۦ وَمَن تَكُونُ لَهُۥ عَـٰقِبَةُ ٱلدَّارِۚ إِنَّهُۥ لَا یُفۡلِحُ ٱلظَّـٰلِمُونَ\n\";s:13:\"numberInSurah\";i:37;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:390;s:4:\"ruku\";i:337;s:11:\"hizbQuarter\";i:156;s:5:\"sajda\";b:0;}i:37;a:9:{s:6:\"number\";i:3290;s:4:\"text\";s:454:\"وَقَالَ فِرۡعَوۡنُ یَـٰۤأَیُّهَا ٱلۡمَلَأُ مَا عَلِمۡتُ لَكُم مِّنۡ إِلَـٰهٍ غَیۡرِی فَأَوۡقِدۡ لِی یَـٰهَـٰمَـٰنُ عَلَى ٱلطِّینِ فَٱجۡعَل لِّی صَرۡحࣰا لَّعَلِّیۤ أَطَّلِعُ إِلَىٰۤ إِلَـٰهِ مُوسَىٰ وَإِنِّی لَأَظُنُّهُۥ مِنَ ٱلۡكَـٰذِبِینَ\n\";s:13:\"numberInSurah\";i:38;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:390;s:4:\"ruku\";i:337;s:11:\"hizbQuarter\";i:156;s:5:\"sajda\";b:0;}i:38;a:9:{s:6:\"number\";i:3291;s:4:\"text\";s:212:\"وَٱسۡتَكۡبَرَ هُوَ وَجُنُودُهُۥ فِی ٱلۡأَرۡضِ بِغَیۡرِ ٱلۡحَقِّ وَظَنُّوۤا۟ أَنَّهُمۡ إِلَیۡنَا لَا یُرۡجَعُونَ\n\";s:13:\"numberInSurah\";i:39;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:390;s:4:\"ruku\";i:337;s:11:\"hizbQuarter\";i:156;s:5:\"sajda\";b:0;}i:39;a:9:{s:6:\"number\";i:3292;s:4:\"text\";s:204:\"فَأَخَذۡنَـٰهُ وَجُنُودَهُۥ فَنَبَذۡنَـٰهُمۡ فِی ٱلۡیَمِّۖ فَٱنظُرۡ كَیۡفَ كَانَ عَـٰقِبَةُ ٱلظَّـٰلِمِینَ\n\";s:13:\"numberInSurah\";i:40;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:390;s:4:\"ruku\";i:337;s:11:\"hizbQuarter\";i:156;s:5:\"sajda\";b:0;}i:40;a:9:{s:6:\"number\";i:3293;s:4:\"text\";s:176:\"وَجَعَلۡنَـٰهُمۡ أَىِٕمَّةࣰ یَدۡعُونَ إِلَى ٱلنَّارِۖ وَیَوۡمَ ٱلۡقِیَـٰمَةِ لَا یُنصَرُونَ\n\";s:13:\"numberInSurah\";i:41;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:390;s:4:\"ruku\";i:337;s:11:\"hizbQuarter\";i:156;s:5:\"sajda\";b:0;}i:41;a:9:{s:6:\"number\";i:3294;s:4:\"text\";s:195:\"وَأَتۡبَعۡنَـٰهُمۡ فِی هَـٰذِهِ ٱلدُّنۡیَا لَعۡنَةࣰۖ وَیَوۡمَ ٱلۡقِیَـٰمَةِ هُم مِّنَ ٱلۡمَقۡبُوحِینَ\n\";s:13:\"numberInSurah\";i:42;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:390;s:4:\"ruku\";i:337;s:11:\"hizbQuarter\";i:156;s:5:\"sajda\";b:0;}i:42;a:9:{s:6:\"number\";i:3295;s:4:\"text\";s:304:\"وَلَقَدۡ ءَاتَیۡنَا مُوسَى ٱلۡكِتَـٰبَ مِنۢ بَعۡدِ مَاۤ أَهۡلَكۡنَا ٱلۡقُرُونَ ٱلۡأُولَىٰ بَصَاۤىِٕرَ لِلنَّاسِ وَهُدࣰى وَرَحۡمَةࣰ لَّعَلَّهُمۡ یَتَذَكَّرُونَ\n\";s:13:\"numberInSurah\";i:43;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:390;s:4:\"ruku\";i:338;s:11:\"hizbQuarter\";i:156;s:5:\"sajda\";b:0;}i:43;a:9:{s:6:\"number\";i:3296;s:4:\"text\";s:201:\"وَمَا كُنتَ بِجَانِبِ ٱلۡغَرۡبِیِّ إِذۡ قَضَیۡنَاۤ إِلَىٰ مُوسَى ٱلۡأَمۡرَ وَمَا كُنتَ مِنَ ٱلشَّـٰهِدِینَ\n\";s:13:\"numberInSurah\";i:44;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:391;s:4:\"ruku\";i:338;s:11:\"hizbQuarter\";i:156;s:5:\"sajda\";b:0;}i:44;a:9:{s:6:\"number\";i:3297;s:4:\"text\";s:336:\"وَلَـٰكِنَّاۤ أَنشَأۡنَا قُرُونࣰا فَتَطَاوَلَ عَلَیۡهِمُ ٱلۡعُمُرُۚ وَمَا كُنتَ ثَاوِیࣰا فِیۤ أَهۡلِ مَدۡیَنَ تَتۡلُوا۟ عَلَیۡهِمۡ ءَایَـٰتِنَا وَلَـٰكِنَّا كُنَّا مُرۡسِلِینَ\n\";s:13:\"numberInSurah\";i:45;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:391;s:4:\"ruku\";i:338;s:11:\"hizbQuarter\";i:156;s:5:\"sajda\";b:0;}i:45;a:9:{s:6:\"number\";i:3298;s:4:\"text\";s:323:\"وَمَا كُنتَ بِجَانِبِ ٱلطُّورِ إِذۡ نَادَیۡنَا وَلَـٰكِن رَّحۡمَةࣰ مِّن رَّبِّكَ لِتُنذِرَ قَوۡمࣰا مَّاۤ أَتَىٰهُم مِّن نَّذِیرࣲ مِّن قَبۡلِكَ لَعَلَّهُمۡ یَتَذَكَّرُونَ\n\";s:13:\"numberInSurah\";i:46;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:391;s:4:\"ruku\";i:338;s:11:\"hizbQuarter\";i:156;s:5:\"sajda\";b:0;}i:46;a:9:{s:6:\"number\";i:3299;s:4:\"text\";s:345:\"وَلَوۡلَاۤ أَن تُصِیبَهُم مُّصِیبَةُۢ بِمَا قَدَّمَتۡ أَیۡدِیهِمۡ فَیَقُولُوا۟ رَبَّنَا لَوۡلَاۤ أَرۡسَلۡتَ إِلَیۡنَا رَسُولࣰا فَنَتَّبِعَ ءَایَـٰتِكَ وَنَكُونَ مِنَ ٱلۡمُؤۡمِنِینَ\n\";s:13:\"numberInSurah\";i:47;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:391;s:4:\"ruku\";i:338;s:11:\"hizbQuarter\";i:156;s:5:\"sajda\";b:0;}i:47;a:9:{s:6:\"number\";i:3300;s:4:\"text\";s:425:\"فَلَمَّا جَاۤءَهُمُ ٱلۡحَقُّ مِنۡ عِندِنَا قَالُوا۟ لَوۡلَاۤ أُوتِیَ مِثۡلَ مَاۤ أُوتِیَ مُوسَىٰۤۚ أَوَلَمۡ یَكۡفُرُوا۟ بِمَاۤ أُوتِیَ مُوسَىٰ مِن قَبۡلُۖ قَالُوا۟ سِحۡرَانِ تَظَـٰهَرَا وَقَالُوۤا۟ إِنَّا بِكُلࣲّ كَـٰفِرُونَ\n\";s:13:\"numberInSurah\";i:48;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:391;s:4:\"ruku\";i:338;s:11:\"hizbQuarter\";i:156;s:5:\"sajda\";b:0;}i:48;a:9:{s:6:\"number\";i:3301;s:4:\"text\";s:202:\"قُلۡ فَأۡتُوا۟ بِكِتَـٰبࣲ مِّنۡ عِندِ ٱللَّهِ هُوَ أَهۡدَىٰ مِنۡهُمَاۤ أَتَّبِعۡهُ إِن كُنتُمۡ صَـٰدِقِینَ\n\";s:13:\"numberInSurah\";i:49;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:391;s:4:\"ruku\";i:338;s:11:\"hizbQuarter\";i:156;s:5:\"sajda\";b:0;}i:49;a:9:{s:6:\"number\";i:3302;s:4:\"text\";s:382:\"فَإِن لَّمۡ یَسۡتَجِیبُوا۟ لَكَ فَٱعۡلَمۡ أَنَّمَا یَتَّبِعُونَ أَهۡوَاۤءَهُمۡۚ وَمَنۡ أَضَلُّ مِمَّنِ ٱتَّبَعَ هَوَىٰهُ بِغَیۡرِ هُدࣰى مِّنَ ٱللَّهِۚ إِنَّ ٱللَّهَ لَا یَهۡدِی ٱلۡقَوۡمَ ٱلظَّـٰلِمِینَ\n\";s:13:\"numberInSurah\";i:50;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:391;s:4:\"ruku\";i:338;s:11:\"hizbQuarter\";i:156;s:5:\"sajda\";b:0;}i:50;a:9:{s:6:\"number\";i:3303;s:4:\"text\";s:125:\"۞ وَلَقَدۡ وَصَّلۡنَا لَهُمُ ٱلۡقَوۡلَ لَعَلَّهُمۡ یَتَذَكَّرُونَ\n\";s:13:\"numberInSurah\";i:51;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:392;s:4:\"ruku\";i:339;s:11:\"hizbQuarter\";i:157;s:5:\"sajda\";b:0;}i:51;a:9:{s:6:\"number\";i:3304;s:4:\"text\";s:140:\"ٱلَّذِینَ ءَاتَیۡنَـٰهُمُ ٱلۡكِتَـٰبَ مِن قَبۡلِهِۦ هُم بِهِۦ یُؤۡمِنُونَ\n\";s:13:\"numberInSurah\";i:52;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:392;s:4:\"ruku\";i:339;s:11:\"hizbQuarter\";i:157;s:5:\"sajda\";b:0;}i:52;a:9:{s:6:\"number\";i:3305;s:4:\"text\";s:239:\"وَإِذَا یُتۡلَىٰ عَلَیۡهِمۡ قَالُوۤا۟ ءَامَنَّا بِهِۦۤ إِنَّهُ ٱلۡحَقُّ مِن رَّبِّنَاۤ إِنَّا كُنَّا مِن قَبۡلِهِۦ مُسۡلِمِینَ\n\";s:13:\"numberInSurah\";i:53;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:392;s:4:\"ruku\";i:339;s:11:\"hizbQuarter\";i:157;s:5:\"sajda\";b:0;}i:53;a:9:{s:6:\"number\";i:3306;s:4:\"text\";s:270:\"أُو۟لَـٰۤىِٕكَ یُؤۡتَوۡنَ أَجۡرَهُم مَّرَّتَیۡنِ بِمَا صَبَرُوا۟ وَیَدۡرَءُونَ بِٱلۡحَسَنَةِ ٱلسَّیِّئَةَ وَمِمَّا رَزَقۡنَـٰهُمۡ یُنفِقُونَ\n\";s:13:\"numberInSurah\";i:54;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:392;s:4:\"ruku\";i:339;s:11:\"hizbQuarter\";i:157;s:5:\"sajda\";b:0;}i:54;a:9:{s:6:\"number\";i:3307;s:4:\"text\";s:289:\"وَإِذَا سَمِعُوا۟ ٱللَّغۡوَ أَعۡرَضُوا۟ عَنۡهُ وَقَالُوا۟ لَنَاۤ أَعۡمَـٰلُنَا وَلَكُمۡ أَعۡمَـٰلُكُمۡ سَلَـٰمٌ عَلَیۡكُمۡ لَا نَبۡتَغِی ٱلۡجَـٰهِلِینَ\n\";s:13:\"numberInSurah\";i:55;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:392;s:4:\"ruku\";i:339;s:11:\"hizbQuarter\";i:157;s:5:\"sajda\";b:0;}i:55;a:9:{s:6:\"number\";i:3308;s:4:\"text\";s:209:\"إِنَّكَ لَا تَهۡدِی مَنۡ أَحۡبَبۡتَ وَلَـٰكِنَّ ٱللَّهَ یَهۡدِی مَن یَشَاۤءُۚ وَهُوَ أَعۡلَمُ بِٱلۡمُهۡتَدِینَ\n\";s:13:\"numberInSurah\";i:56;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:392;s:4:\"ruku\";i:339;s:11:\"hizbQuarter\";i:157;s:5:\"sajda\";b:0;}i:56;a:9:{s:6:\"number\";i:3309;s:4:\"text\";s:430:\"وَقَالُوۤا۟ إِن نَّتَّبِعِ ٱلۡهُدَىٰ مَعَكَ نُتَخَطَّفۡ مِنۡ أَرۡضِنَاۤۚ أَوَلَمۡ نُمَكِّن لَّهُمۡ حَرَمًا ءَامِنࣰا یُجۡبَىٰۤ إِلَیۡهِ ثَمَرَ ٰ⁠تُ كُلِّ شَیۡءࣲ رِّزۡقࣰا مِّن لَّدُنَّا وَلَـٰكِنَّ أَكۡثَرَهُمۡ لَا یَعۡلَمُونَ\n\";s:13:\"numberInSurah\";i:57;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:392;s:4:\"ruku\";i:339;s:11:\"hizbQuarter\";i:157;s:5:\"sajda\";b:0;}i:57;a:9:{s:6:\"number\";i:3310;s:4:\"text\";s:304:\"وَكَمۡ أَهۡلَكۡنَا مِن قَرۡیَةِۭ بَطِرَتۡ مَعِیشَتَهَاۖ فَتِلۡكَ مَسَـٰكِنُهُمۡ لَمۡ تُسۡكَن مِّنۢ بَعۡدِهِمۡ إِلَّا قَلِیلࣰاۖ وَكُنَّا نَحۡنُ ٱلۡوَ ٰ⁠رِثِینَ\n\";s:13:\"numberInSurah\";i:58;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:392;s:4:\"ruku\";i:339;s:11:\"hizbQuarter\";i:157;s:5:\"sajda\";b:0;}i:58;a:9:{s:6:\"number\";i:3311;s:4:\"text\";s:339:\"وَمَا كَانَ رَبُّكَ مُهۡلِكَ ٱلۡقُرَىٰ حَتَّىٰ یَبۡعَثَ فِیۤ أُمِّهَا رَسُولࣰا یَتۡلُوا۟ عَلَیۡهِمۡ ءَایَـٰتِنَاۚ وَمَا كُنَّا مُهۡلِكِی ٱلۡقُرَىٰۤ إِلَّا وَأَهۡلُهَا ظَـٰلِمُونَ\n\";s:13:\"numberInSurah\";i:59;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:392;s:4:\"ruku\";i:339;s:11:\"hizbQuarter\";i:157;s:5:\"sajda\";b:0;}i:59;a:9:{s:6:\"number\";i:3312;s:4:\"text\";s:261:\"وَمَاۤ أُوتِیتُم مِّن شَیۡءࣲ فَمَتَـٰعُ ٱلۡحَیَوٰةِ ٱلدُّنۡیَا وَزِینَتُهَاۚ وَمَا عِندَ ٱللَّهِ خَیۡرࣱ وَأَبۡقَىٰۤۚ أَفَلَا تَعۡقِلُونَ\n\";s:13:\"numberInSurah\";i:60;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:393;s:4:\"ruku\";i:339;s:11:\"hizbQuarter\";i:157;s:5:\"sajda\";b:0;}i:60;a:9:{s:6:\"number\";i:3313;s:4:\"text\";s:302:\"أَفَمَن وَعَدۡنَـٰهُ وَعۡدًا حَسَنࣰا فَهُوَ لَـٰقِیهِ كَمَن مَّتَّعۡنَـٰهُ مَتَـٰعَ ٱلۡحَیَوٰةِ ٱلدُّنۡیَا ثُمَّ هُوَ یَوۡمَ ٱلۡقِیَـٰمَةِ مِنَ ٱلۡمُحۡضَرِینَ\n\";s:13:\"numberInSurah\";i:61;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:393;s:4:\"ruku\";i:340;s:11:\"hizbQuarter\";i:157;s:5:\"sajda\";b:0;}i:61;a:9:{s:6:\"number\";i:3314;s:4:\"text\";s:156:\"وَیَوۡمَ یُنَادِیهِمۡ فَیَقُولُ أَیۡنَ شُرَكَاۤءِیَ ٱلَّذِینَ كُنتُمۡ تَزۡعُمُونَ\n\";s:13:\"numberInSurah\";i:62;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:393;s:4:\"ruku\";i:340;s:11:\"hizbQuarter\";i:157;s:5:\"sajda\";b:0;}i:62;a:9:{s:6:\"number\";i:3315;s:4:\"text\";s:348:\"قَالَ ٱلَّذِینَ حَقَّ عَلَیۡهِمُ ٱلۡقَوۡلُ رَبَّنَا هَـٰۤؤُلَاۤءِ ٱلَّذِینَ أَغۡوَیۡنَاۤ أَغۡوَیۡنَـٰهُمۡ كَمَا غَوَیۡنَاۖ تَبَرَّأۡنَاۤ إِلَیۡكَۖ مَا كَانُوۤا۟ إِیَّانَا یَعۡبُدُونَ\n\";s:13:\"numberInSurah\";i:63;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:393;s:4:\"ruku\";i:340;s:11:\"hizbQuarter\";i:157;s:5:\"sajda\";b:0;}i:63;a:9:{s:6:\"number\";i:3316;s:4:\"text\";s:253:\"وَقِیلَ ٱدۡعُوا۟ شُرَكَاۤءَكُمۡ فَدَعَوۡهُمۡ فَلَمۡ یَسۡتَجِیبُوا۟ لَهُمۡ وَرَأَوُا۟ ٱلۡعَذَابَۚ لَوۡ أَنَّهُمۡ كَانُوا۟ یَهۡتَدُونَ\n\";s:13:\"numberInSurah\";i:64;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:393;s:4:\"ruku\";i:340;s:11:\"hizbQuarter\";i:157;s:5:\"sajda\";b:0;}i:64;a:9:{s:6:\"number\";i:3317;s:4:\"text\";s:126:\"وَیَوۡمَ یُنَادِیهِمۡ فَیَقُولُ مَاذَاۤ أَجَبۡتُمُ ٱلۡمُرۡسَلِینَ\n\";s:13:\"numberInSurah\";i:65;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:393;s:4:\"ruku\";i:340;s:11:\"hizbQuarter\";i:157;s:5:\"sajda\";b:0;}i:65;a:9:{s:6:\"number\";i:3318;s:4:\"text\";s:144:\"فَعَمِیَتۡ عَلَیۡهِمُ ٱلۡأَنۢبَاۤءُ یَوۡمَىِٕذࣲ فَهُمۡ لَا یَتَسَاۤءَلُونَ\n\";s:13:\"numberInSurah\";i:66;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:393;s:4:\"ruku\";i:340;s:11:\"hizbQuarter\";i:157;s:5:\"sajda\";b:0;}i:66;a:9:{s:6:\"number\";i:3319;s:4:\"text\";s:170:\"فَأَمَّا مَن تَابَ وَءَامَنَ وَعَمِلَ صَـٰلِحࣰا فَعَسَىٰۤ أَن یَكُونَ مِنَ ٱلۡمُفۡلِحِینَ\n\";s:13:\"numberInSurah\";i:67;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:393;s:4:\"ruku\";i:340;s:11:\"hizbQuarter\";i:157;s:5:\"sajda\";b:0;}i:67;a:9:{s:6:\"number\";i:3320;s:4:\"text\";s:238:\"وَرَبُّكَ یَخۡلُقُ مَا یَشَاۤءُ وَیَخۡتَارُۗ مَا كَانَ لَهُمُ ٱلۡخِیَرَةُۚ سُبۡحَـٰنَ ٱللَّهِ وَتَعَـٰلَىٰ عَمَّا یُشۡرِكُونَ\n\";s:13:\"numberInSurah\";i:68;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:393;s:4:\"ruku\";i:340;s:11:\"hizbQuarter\";i:157;s:5:\"sajda\";b:0;}i:68;a:9:{s:6:\"number\";i:3321;s:4:\"text\";s:115:\"وَرَبُّكَ یَعۡلَمُ مَا تُكِنُّ صُدُورُهُمۡ وَمَا یُعۡلِنُونَ\n\";s:13:\"numberInSurah\";i:69;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:393;s:4:\"ruku\";i:340;s:11:\"hizbQuarter\";i:157;s:5:\"sajda\";b:0;}i:69;a:9:{s:6:\"number\";i:3322;s:4:\"text\";s:243:\"وَهُوَ ٱللَّهُ لَاۤ إِلَـٰهَ إِلَّا هُوَۖ لَهُ ٱلۡحَمۡدُ فِی ٱلۡأُولَىٰ وَٱلۡـَٔاخِرَةِۖ وَلَهُ ٱلۡحُكۡمُ وَإِلَیۡهِ تُرۡجَعُونَ\n\";s:13:\"numberInSurah\";i:70;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:393;s:4:\"ruku\";i:340;s:11:\"hizbQuarter\";i:157;s:5:\"sajda\";b:0;}i:70;a:9:{s:6:\"number\";i:3323;s:4:\"text\";s:315:\"قُلۡ أَرَءَیۡتُمۡ إِن جَعَلَ ٱللَّهُ عَلَیۡكُمُ ٱلَّیۡلَ سَرۡمَدًا إِلَىٰ یَوۡمِ ٱلۡقِیَـٰمَةِ مَنۡ إِلَـٰهٌ غَیۡرُ ٱللَّهِ یَأۡتِیكُم بِضِیَاۤءٍۚ أَفَلَا تَسۡمَعُونَ\n\";s:13:\"numberInSurah\";i:71;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:394;s:4:\"ruku\";i:340;s:11:\"hizbQuarter\";i:157;s:5:\"sajda\";b:0;}i:71;a:9:{s:6:\"number\";i:3324;s:4:\"text\";s:350:\"قُلۡ أَرَءَیۡتُمۡ إِن جَعَلَ ٱللَّهُ عَلَیۡكُمُ ٱلنَّهَارَ سَرۡمَدًا إِلَىٰ یَوۡمِ ٱلۡقِیَـٰمَةِ مَنۡ إِلَـٰهٌ غَیۡرُ ٱللَّهِ یَأۡتِیكُم بِلَیۡلࣲ تَسۡكُنُونَ فِیهِۚ أَفَلَا تُبۡصِرُونَ\n\";s:13:\"numberInSurah\";i:72;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:394;s:4:\"ruku\";i:340;s:11:\"hizbQuarter\";i:157;s:5:\"sajda\";b:0;}i:72;a:9:{s:6:\"number\";i:3325;s:4:\"text\";s:249:\"وَمِن رَّحۡمَتِهِۦ جَعَلَ لَكُمُ ٱلَّیۡلَ وَٱلنَّهَارَ لِتَسۡكُنُوا۟ فِیهِ وَلِتَبۡتَغُوا۟ مِن فَضۡلِهِۦ وَلَعَلَّكُمۡ تَشۡكُرُونَ\n\";s:13:\"numberInSurah\";i:73;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:394;s:4:\"ruku\";i:340;s:11:\"hizbQuarter\";i:157;s:5:\"sajda\";b:0;}i:73;a:9:{s:6:\"number\";i:3326;s:4:\"text\";s:156:\"وَیَوۡمَ یُنَادِیهِمۡ فَیَقُولُ أَیۡنَ شُرَكَاۤءِیَ ٱلَّذِینَ كُنتُمۡ تَزۡعُمُونَ\n\";s:13:\"numberInSurah\";i:74;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:394;s:4:\"ruku\";i:340;s:11:\"hizbQuarter\";i:157;s:5:\"sajda\";b:0;}i:74;a:9:{s:6:\"number\";i:3327;s:4:\"text\";s:287:\"وَنَزَعۡنَا مِن كُلِّ أُمَّةࣲ شَهِیدࣰا فَقُلۡنَا هَاتُوا۟ بُرۡهَـٰنَكُمۡ فَعَلِمُوۤا۟ أَنَّ ٱلۡحَقَّ لِلَّهِ وَضَلَّ عَنۡهُم مَّا كَانُوا۟ یَفۡتَرُونَ\n\";s:13:\"numberInSurah\";i:75;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:394;s:4:\"ruku\";i:340;s:11:\"hizbQuarter\";i:157;s:5:\"sajda\";b:0;}i:75;a:9:{s:6:\"number\";i:3328;s:4:\"text\";s:458:\"۞ إِنَّ قَـٰرُونَ كَانَ مِن قَوۡمِ مُوسَىٰ فَبَغَىٰ عَلَیۡهِمۡۖ وَءَاتَیۡنَـٰهُ مِنَ ٱلۡكُنُوزِ مَاۤ إِنَّ مَفَاتِحَهُۥ لَتَنُوۤأُ بِٱلۡعُصۡبَةِ أُو۟لِی ٱلۡقُوَّةِ إِذۡ قَالَ لَهُۥ قَوۡمُهُۥ لَا تَفۡرَحۡۖ إِنَّ ٱللَّهَ لَا یُحِبُّ ٱلۡفَرِحِینَ\n\";s:13:\"numberInSurah\";i:76;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:394;s:4:\"ruku\";i:341;s:11:\"hizbQuarter\";i:158;s:5:\"sajda\";b:0;}i:76;a:9:{s:6:\"number\";i:3329;s:4:\"text\";s:420:\"وَٱبۡتَغِ فِیمَاۤ ءَاتَىٰكَ ٱللَّهُ ٱلدَّارَ ٱلۡـَٔاخِرَةَۖ وَلَا تَنسَ نَصِیبَكَ مِنَ ٱلدُّنۡیَاۖ وَأَحۡسِن كَمَاۤ أَحۡسَنَ ٱللَّهُ إِلَیۡكَۖ وَلَا تَبۡغِ ٱلۡفَسَادَ فِی ٱلۡأَرۡضِۖ إِنَّ ٱللَّهَ لَا یُحِبُّ ٱلۡمُفۡسِدِینَ\n\";s:13:\"numberInSurah\";i:77;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:394;s:4:\"ruku\";i:341;s:11:\"hizbQuarter\";i:158;s:5:\"sajda\";b:0;}i:77;a:9:{s:6:\"number\";i:3330;s:4:\"text\";s:428:\"قَالَ إِنَّمَاۤ أُوتِیتُهُۥ عَلَىٰ عِلۡمٍ عِندِیۤۚ أَوَلَمۡ یَعۡلَمۡ أَنَّ ٱللَّهَ قَدۡ أَهۡلَكَ مِن قَبۡلِهِۦ مِنَ ٱلۡقُرُونِ مَنۡ هُوَ أَشَدُّ مِنۡهُ قُوَّةࣰ وَأَكۡثَرُ جَمۡعࣰاۚ وَلَا یُسۡـَٔلُ عَن ذُنُوبِهِمُ ٱلۡمُجۡرِمُونَ\n\";s:13:\"numberInSurah\";i:78;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:395;s:4:\"ruku\";i:341;s:11:\"hizbQuarter\";i:158;s:5:\"sajda\";b:0;}i:78;a:9:{s:6:\"number\";i:3331;s:4:\"text\";s:317:\"فَخَرَجَ عَلَىٰ قَوۡمِهِۦ فِی زِینَتِهِۦۖ قَالَ ٱلَّذِینَ یُرِیدُونَ ٱلۡحَیَوٰةَ ٱلدُّنۡیَا یَـٰلَیۡتَ لَنَا مِثۡلَ مَاۤ أُوتِیَ قَـٰرُونُ إِنَّهُۥ لَذُو حَظٍّ عَظِیمࣲ\n\";s:13:\"numberInSurah\";i:79;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:395;s:4:\"ruku\";i:341;s:11:\"hizbQuarter\";i:158;s:5:\"sajda\";b:0;}i:79;a:9:{s:6:\"number\";i:3332;s:4:\"text\";s:284:\"وَقَالَ ٱلَّذِینَ أُوتُوا۟ ٱلۡعِلۡمَ وَیۡلَكُمۡ ثَوَابُ ٱللَّهِ خَیۡرࣱ لِّمَنۡ ءَامَنَ وَعَمِلَ صَـٰلِحࣰاۚ وَلَا یُلَقَّىٰهَاۤ إِلَّا ٱلصَّـٰبِرُونَ\n\";s:13:\"numberInSurah\";i:80;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:395;s:4:\"ruku\";i:341;s:11:\"hizbQuarter\";i:158;s:5:\"sajda\";b:0;}i:80;a:9:{s:6:\"number\";i:3333;s:4:\"text\";s:252:\"فَخَسَفۡنَا بِهِۦ وَبِدَارِهِ ٱلۡأَرۡضَ فَمَا كَانَ لَهُۥ مِن فِئَةࣲ یَنصُرُونَهُۥ مِن دُونِ ٱللَّهِ وَمَا كَانَ مِنَ ٱلۡمُنتَصِرِینَ\n\";s:13:\"numberInSurah\";i:81;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:395;s:4:\"ruku\";i:341;s:11:\"hizbQuarter\";i:158;s:5:\"sajda\";b:0;}i:81;a:9:{s:6:\"number\";i:3334;s:4:\"text\";s:466:\"وَأَصۡبَحَ ٱلَّذِینَ تَمَنَّوۡا۟ مَكَانَهُۥ بِٱلۡأَمۡسِ یَقُولُونَ وَیۡكَأَنَّ ٱللَّهَ یَبۡسُطُ ٱلرِّزۡقَ لِمَن یَشَاۤءُ مِنۡ عِبَادِهِۦ وَیَقۡدِرُۖ لَوۡلَاۤ أَن مَّنَّ ٱللَّهُ عَلَیۡنَا لَخَسَفَ بِنَاۖ وَیۡكَأَنَّهُۥ لَا یُفۡلِحُ ٱلۡكَـٰفِرُونَ\n\";s:13:\"numberInSurah\";i:82;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:395;s:4:\"ruku\";i:341;s:11:\"hizbQuarter\";i:158;s:5:\"sajda\";b:0;}i:82;a:9:{s:6:\"number\";i:3335;s:4:\"text\";s:264:\"تِلۡكَ ٱلدَّارُ ٱلۡـَٔاخِرَةُ نَجۡعَلُهَا لِلَّذِینَ لَا یُرِیدُونَ عُلُوࣰّا فِی ٱلۡأَرۡضِ وَلَا فَسَادࣰاۚ وَٱلۡعَـٰقِبَةُ لِلۡمُتَّقِینَ\n\";s:13:\"numberInSurah\";i:83;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:395;s:4:\"ruku\";i:341;s:11:\"hizbQuarter\";i:158;s:5:\"sajda\";b:0;}i:83;a:9:{s:6:\"number\";i:3336;s:4:\"text\";s:301:\"مَن جَاۤءَ بِٱلۡحَسَنَةِ فَلَهُۥ خَیۡرࣱ مِّنۡهَاۖ وَمَن جَاۤءَ بِٱلسَّیِّئَةِ فَلَا یُجۡزَى ٱلَّذِینَ عَمِلُوا۟ ٱلسَّیِّـَٔاتِ إِلَّا مَا كَانُوا۟ یَعۡمَلُونَ\n\";s:13:\"numberInSurah\";i:84;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:395;s:4:\"ruku\";i:341;s:11:\"hizbQuarter\";i:158;s:5:\"sajda\";b:0;}i:84;a:9:{s:6:\"number\";i:3337;s:4:\"text\";s:284:\"إِنَّ ٱلَّذِی فَرَضَ عَلَیۡكَ ٱلۡقُرۡءَانَ لَرَاۤدُّكَ إِلَىٰ مَعَادࣲۚ قُل رَّبِّیۤ أَعۡلَمُ مَن جَاۤءَ بِٱلۡهُدَىٰ وَمَنۡ هُوَ فِی ضَلَـٰلࣲ مُّبِینࣲ\n\";s:13:\"numberInSurah\";i:85;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:396;s:4:\"ruku\";i:341;s:11:\"hizbQuarter\";i:158;s:5:\"sajda\";b:0;}i:85;a:9:{s:6:\"number\";i:3338;s:4:\"text\";s:251:\"وَمَا كُنتَ تَرۡجُوۤا۟ أَن یُلۡقَىٰۤ إِلَیۡكَ ٱلۡكِتَـٰبُ إِلَّا رَحۡمَةࣰ مِّن رَّبِّكَۖ فَلَا تَكُونَنَّ ظَهِیرࣰا لِّلۡكَـٰفِرِینَ\n\";s:13:\"numberInSurah\";i:86;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:396;s:4:\"ruku\";i:341;s:11:\"hizbQuarter\";i:158;s:5:\"sajda\";b:0;}i:86;a:9:{s:6:\"number\";i:3339;s:4:\"text\";s:254:\"وَلَا یَصُدُّنَّكَ عَنۡ ءَایَـٰتِ ٱللَّهِ بَعۡدَ إِذۡ أُنزِلَتۡ إِلَیۡكَۖ وَٱدۡعُ إِلَىٰ رَبِّكَۖ وَلَا تَكُونَنَّ مِنَ ٱلۡمُشۡرِكِینَ\n\";s:13:\"numberInSurah\";i:87;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:396;s:4:\"ruku\";i:341;s:11:\"hizbQuarter\";i:158;s:5:\"sajda\";b:0;}i:87;a:9:{s:6:\"number\";i:3340;s:4:\"text\";s:279:\"وَلَا تَدۡعُ مَعَ ٱللَّهِ إِلَـٰهًا ءَاخَرَۘ لَاۤ إِلَـٰهَ إِلَّا هُوَۚ كُلُّ شَیۡءٍ هَالِكٌ إِلَّا وَجۡهَهُۥۚ لَهُ ٱلۡحُكۡمُ وَإِلَیۡهِ تُرۡجَعُونَ\n\";s:13:\"numberInSurah\";i:88;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:396;s:4:\"ruku\";i:341;s:11:\"hizbQuarter\";i:158;s:5:\"sajda\";b:0;}}s:7:\"edition\";a:7:{s:10:\"identifier\";s:27:\"quran-uthmani-quran-academy\";s:8:\"language\";s:2:\"ar\";s:4:\"name\";s:67:\"القرآن الكريم برسم العثماني (quran-academy)\";s:11:\"englishName\";s:78:\"Modified Quran Uthmani Text from the Quran Academy to work with the Kitab font\";s:6:\"format\";s:4:\"text\";s:4:\"type\";s:5:\"quran\";s:9:\"direction\";s:3:\"rtl\";}}', 1794581362);
INSERT INTO `cache` (`key`, `value`, `expiration`) VALUES
('quranapp-cache-surah_28_fr.hamidullah', 'a:8:{s:6:\"number\";i:28;s:4:\"name\";s:31:\"سُورَةُ القَصَصِ\";s:11:\"englishName\";s:8:\"Al-Qasas\";s:22:\"englishNameTranslation\";s:11:\"The Stories\";s:14:\"revelationType\";s:6:\"Meccan\";s:13:\"numberOfAyahs\";i:88;s:5:\"ayahs\";a:88:{i:0;a:9:{s:6:\"number\";i:3253;s:4:\"text\";s:17:\"T\'â, Sîn, Mîm.\";s:13:\"numberInSurah\";i:1;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:385;s:4:\"ruku\";i:334;s:11:\"hizbQuarter\";i:154;s:5:\"sajda\";b:0;}i:1;a:9:{s:6:\"number\";i:3254;s:4:\"text\";s:37:\"Voici les versets du Livre explicite.\";s:13:\"numberInSurah\";i:2;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:385;s:4:\"ruku\";i:334;s:11:\"hizbQuarter\";i:154;s:5:\"sajda\";b:0;}i:2;a:9:{s:6:\"number\";i:3255;s:4:\"text\";s:112:\"Nous te racontons en toute vérité, de l\'histoire de Moïse et de Pharaon, à l\'intention des gens qui croient.\";s:13:\"numberInSurah\";i:3;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:385;s:4:\"ruku\";i:334;s:11:\"hizbQuarter\";i:154;s:5:\"sajda\";b:0;}i:3;a:9:{s:6:\"number\";i:3256;s:4:\"text\";s:227:\"Pharaon était hautain sur terre; il répartit en clans ses habitants, afin d\'abuser de la faiblesse de l\'un d\'eux: Il égorgeait leurs fils et laissait vivantes leurs femmes. Il était vraiment parmi les fauteurs de désordre.\";s:13:\"numberInSurah\";i:4;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:385;s:4:\"ruku\";i:334;s:11:\"hizbQuarter\";i:154;s:5:\"sajda\";b:0;}i:4;a:9:{s:6:\"number\";i:3257;s:4:\"text\";s:124:\"Mais Nous voulions favoriser ceux qui avaient été faibles sur terre et en faire des dirigeants et en faire les héritiers,\";s:13:\"numberInSurah\";i:5;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:385;s:4:\"ruku\";i:334;s:11:\"hizbQuarter\";i:154;s:5:\"sajda\";b:0;}i:5;a:9:{s:6:\"number\";i:3258;s:4:\"text\";s:122:\"et les établir puissamment sur terre, et faire voir à Pharaon, à Hâmân, et à leurs soldats, ce dont ils redoutaient.\";s:13:\"numberInSurah\";i:6;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:386;s:4:\"ruku\";i:334;s:11:\"hizbQuarter\";i:154;s:5:\"sajda\";b:0;}i:6;a:9:{s:6:\"number\";i:3259;s:4:\"text\";s:211:\"Et Nous révélâmes à la mère de Moïse [ceci]: «Allaite-le. Et quand tu craindras pour lui, jette-le dans le flot. Et n\'aie pas peur et ne t\'attriste pas: Nous te le rendrons et ferons de lui un Messager».\";s:13:\"numberInSurah\";i:7;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:386;s:4:\"ruku\";i:334;s:11:\"hizbQuarter\";i:154;s:5:\"sajda\";b:0;}i:7;a:9:{s:6:\"number\";i:3260;s:4:\"text\";s:148:\"Les gens de Pharaon le recueillirent, pour qu\'il leur soit un ennemi et une source d\'affliction! Pharaon, Hâmân et leurs soldats étaient fautifs.\";s:13:\"numberInSurah\";i:8;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:386;s:4:\"ruku\";i:334;s:11:\"hizbQuarter\";i:154;s:5:\"sajda\";b:0;}i:8;a:9:{s:6:\"number\";i:3261;s:4:\"text\";s:184:\"Et la femme de Pharaon dit: «(Cet enfant) réjouira mon œil et le tien! Ne le tuez pas. Il pourrait nous être utile ou le prendrons-nous pour enfant». Et ils ne pressentaient rien.\";s:13:\"numberInSurah\";i:9;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:386;s:4:\"ruku\";i:334;s:11:\"hizbQuarter\";i:154;s:5:\"sajda\";b:0;}i:9;a:9:{s:6:\"number\";i:3262;s:4:\"text\";s:176:\"Et le cœur de la mère de Moïse devint vide. Peu s\'en fallut qu\'elle ne divulguât tout, si Nous n\'avions pas renforcé son cœur pour qu\'elle restât du nombre des croyants.\";s:13:\"numberInSurah\";i:10;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:386;s:4:\"ruku\";i:334;s:11:\"hizbQuarter\";i:154;s:5:\"sajda\";b:0;}i:10;a:9:{s:6:\"number\";i:3263;s:4:\"text\";s:99:\"Elle dit à sa sœur: «Suis-le» elle l\'aperçut alors de loin sans qu\'ils ne s\'en rendent compte.\";s:13:\"numberInSurah\";i:11;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:386;s:4:\"ruku\";i:334;s:11:\"hizbQuarter\";i:154;s:5:\"sajda\";b:0;}i:11;a:9:{s:6:\"number\";i:3264;s:4:\"text\";s:231:\"Nous lui avions interdit auparavant (le sein) des nourrices. Elle (la sœur de Moïse) dit donc: «Voulez-vous que je vous indique les gens d\'une maison qui s\'en chargeront pour vous tout en étant bienveillants à son égard?»...\";s:13:\"numberInSurah\";i:12;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:386;s:4:\"ruku\";i:334;s:11:\"hizbQuarter\";i:155;s:5:\"sajda\";b:0;}i:12;a:9:{s:6:\"number\";i:3265;s:4:\"text\";s:191:\"Ainsi Nous le rendîmes à sa mère, afin que son œil se réjouisse, qu\'elle ne s\'affligeât pas et qu\'elle sût que la promesse d\'Allah est vraie. Mais la plupart d\'entre eux ne savent pas.\";s:13:\"numberInSurah\";i:13;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:386;s:4:\"ruku\";i:334;s:11:\"hizbQuarter\";i:155;s:5:\"sajda\";b:0;}i:13;a:9:{s:6:\"number\";i:3266;s:4:\"text\";s:169:\"Et quand il eut atteint sa maturité et sa pleine formation, Nous lui donnâmes la faculté de juger et une science. C\'est ainsi que Nous récompensons les bienfaisants.\";s:13:\"numberInSurah\";i:14;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:387;s:4:\"ruku\";i:335;s:11:\"hizbQuarter\";i:155;s:5:\"sajda\";b:0;}i:14;a:9:{s:6:\"number\";i:3267;s:4:\"text\";s:374:\"Il entra dans la ville à un moment d\'inattention de ses habitants; il y trouva deux hommes qui se battaient, l\'un était de ses partisans et l\'autre de ses adversaires. L\'homme de son parti l\'appela au secours contre son ennemi. Moïse lui donna un coup de poing qui l\'acheva. - [Moïse] dit: «Cela est l\'œuvre du Diable. C\'est vraiment un ennemi, un égareur évident».\";s:13:\"numberInSurah\";i:15;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:387;s:4:\"ruku\";i:335;s:11:\"hizbQuarter\";i:155;s:5:\"sajda\";b:0;}i:15;a:9:{s:6:\"number\";i:3268;s:4:\"text\";s:147:\"Il dit: «Seigneur, je me suis fait du tort à moi-même; pardonne-moi». Et Il lui pardonna. C\'est Lui vraiment le Pardonneur, le Miséricordieux!\";s:13:\"numberInSurah\";i:16;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:387;s:4:\"ruku\";i:335;s:11:\"hizbQuarter\";i:155;s:5:\"sajda\";b:0;}i:16;a:9:{s:6:\"number\";i:3269;s:4:\"text\";s:104:\"Il dit: «Seigneur, grâce aux bienfaits dont tu m\'as comblé, jamais je ne soutiendrai les criminels».\";s:13:\"numberInSurah\";i:17;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:387;s:4:\"ruku\";i:335;s:11:\"hizbQuarter\";i:155;s:5:\"sajda\";b:0;}i:17;a:9:{s:6:\"number\";i:3270;s:4:\"text\";s:230:\"Le lendemain matin, il se trouva en ville, craintif et regardant autour de lui, quand voilà que celui qui lui avait demandé secours la veille, l\'appelait à grands cris. Moïse lui dit: «Tu es certes un provocateur déclaré».\";s:13:\"numberInSurah\";i:18;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:387;s:4:\"ruku\";i:335;s:11:\"hizbQuarter\";i:155;s:5:\"sajda\";b:0;}i:18;a:9:{s:6:\"number\";i:3271;s:4:\"text\";s:226:\"Quand il voulut porter un coup à leur ennemi commun, il (l\'Israélite) dit: «O Moïse, veux-tu me tuer comme tu as tué un homme hier? Tu ne veux être qu\'un tyran sur terre; et tu ne veux pas être parmi les bienfaiteurs».\";s:13:\"numberInSurah\";i:19;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:387;s:4:\"ruku\";i:335;s:11:\"hizbQuarter\";i:155;s:5:\"sajda\";b:0;}i:19;a:9:{s:6:\"number\";i:3272;s:4:\"text\";s:207:\"Et c\'est alors qu\'un homme vint du bout de la ville en courant et dit: «O Moïse, les notables sont en train de se concerter à ton sujet pour te tuer. Quitte (la ville). C\'est le conseil que je te donne».\";s:13:\"numberInSurah\";i:20;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:387;s:4:\"ruku\";i:335;s:11:\"hizbQuarter\";i:155;s:5:\"sajda\";b:0;}i:20;a:9:{s:6:\"number\";i:3273;s:4:\"text\";s:108:\"Il sortit de là, craintif, regardant autour de lui. Il dit: «Seigneur, sauve-moi de [ce] peuple injuste!»\";s:13:\"numberInSurah\";i:21;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:387;s:4:\"ruku\";i:335;s:11:\"hizbQuarter\";i:155;s:5:\"sajda\";b:0;}i:21;a:9:{s:6:\"number\";i:3274;s:4:\"text\";s:106:\"Et lorsqu\'il se dirigea vers Madyan, il dit: «Je souhaite que mon Seigneur me guide sur la voie droite».\";s:13:\"numberInSurah\";i:22;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:388;s:4:\"ruku\";i:336;s:11:\"hizbQuarter\";i:155;s:5:\"sajda\";b:0;}i:22;a:9:{s:6:\"number\";i:3275;s:4:\"text\";s:325:\"Et quand il fut arrivé au point d\'eau de Madyan, il y trouva un attroupement de gens abreuvant [leurs bêtes] et il trouva aussi deux femmes se tenant à l\'écart et retenant [leurs bêtes]. Il dit: «Que voulez-vous?» Elles dirent: «Nous n\'abreuverons que quand les bergers seront partis; et notre père est fort âgé».\";s:13:\"numberInSurah\";i:23;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:388;s:4:\"ruku\";i:336;s:11:\"hizbQuarter\";i:155;s:5:\"sajda\";b:0;}i:23;a:9:{s:6:\"number\";i:3276;s:4:\"text\";s:140:\"Il abreuva [les bêtes] pour elles puis retourna à l\'ombre et dit: «Seigneur, j\'ai grand besoin du bien que tu feras descendre vers moi».\";s:13:\"numberInSurah\";i:24;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:388;s:4:\"ruku\";i:336;s:11:\"hizbQuarter\";i:155;s:5:\"sajda\";b:0;}i:24;a:9:{s:6:\"number\";i:3277;s:4:\"text\";s:311:\"Puis l\'une des deux femmes vint à lui, d\'une démarche timide, et lui dit: «Mon père t\'appelle pour te récompenser pour avoir abreuvé pour nous». Et quand il fut venu auprès de lui et qu\'il lui eut raconté son histoire, il (le vieillard) dit: «N\'aie aucune crainte: tu as échappé aux gens injustes».\";s:13:\"numberInSurah\";i:25;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:388;s:4:\"ruku\";i:336;s:11:\"hizbQuarter\";i:155;s:5:\"sajda\";b:0;}i:25;a:9:{s:6:\"number\";i:3278;s:4:\"text\";s:156:\"L\'une d\'elles dit: «O mon père, engage-le [à ton service] moyennant salaire, car le meilleur à engager c\'est celui qui est fort et digne de confiance».\";s:13:\"numberInSurah\";i:26;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:388;s:4:\"ruku\";i:336;s:11:\"hizbQuarter\";i:155;s:5:\"sajda\";b:0;}i:26;a:9:{s:6:\"number\";i:3279;s:4:\"text\";s:301:\"Il dit: «Je voudrais te marier à l\'une de mes deux filles que voici, à condition que tu travailles à mon service durant huit ans. Si tu achèves dix [années], ce sera de ton bon gré; je ne veux cependant rien t\'imposer d\'excessif. Tu me trouveras, si Allah le veut, du nombre des gens de bien».\";s:13:\"numberInSurah\";i:27;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:388;s:4:\"ruku\";i:336;s:11:\"hizbQuarter\";i:155;s:5:\"sajda\";b:0;}i:27;a:9:{s:6:\"number\";i:3280;s:4:\"text\";s:183:\"«C\'est (conclu) entre toi et moi, dit [Moïse]. Quel que soit celui des deux termes que je m\'assigne, il n\'y aura nulle pression sur moi. Et Allah est Garant de ce que nous disons».\";s:13:\"numberInSurah\";i:28;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:388;s:4:\"ruku\";i:336;s:11:\"hizbQuarter\";i:155;s:5:\"sajda\";b:0;}i:28;a:9:{s:6:\"number\";i:3281;s:4:\"text\";s:283:\"Puis, lorsque Moïse eut accompli la période convenue et qu\'il se mit en route avec sa famille, il vit un feu du côté du Mont. Il dit à sa famille: «Demeurez ici. J\'ai vu du feu. Peut-être vous en apporterai-je une nouvelle ou un tison de feu afin que vous vous réchauffiez».\";s:13:\"numberInSurah\";i:29;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:389;s:4:\"ruku\";i:337;s:11:\"hizbQuarter\";i:156;s:5:\"sajda\";b:0;}i:29;a:9:{s:6:\"number\";i:3282;s:4:\"text\";s:167:\"Puis quand il y arriva, on l\'appela, du flanc droit de la vallée, dans la place bénie, à partir de l\'arbre: «O Moïse! C\'est Moi Allah, le Seigneur de l\'univers».\";s:13:\"numberInSurah\";i:30;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:389;s:4:\"ruku\";i:337;s:11:\"hizbQuarter\";i:156;s:5:\"sajda\";b:0;}i:30;a:9:{s:6:\"number\";i:3283;s:4:\"text\";s:212:\"Et: «Jette ton bâton» Puis quand il le vit remuer comme si c\'était un serpent, il tourna le dos sans même se retourner. «O Moïse! Approche et n\'aie pas peur: tu es du nombre de ceux qui sont en sécurité.\";s:13:\"numberInSurah\";i:31;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:389;s:4:\"ruku\";i:337;s:11:\"hizbQuarter\";i:156;s:5:\"sajda\";b:0;}i:31;a:9:{s:6:\"number\";i:3284;s:4:\"text\";s:247:\"Introduis ta main dans l\'ouverture de ta tunique: elle sortira blanche sans aucun mal. Et serre ton bras contre toi pour ne pas avoir peur. Voilà donc deux preuves de ton Seigneur pour Pharaon et ses notables. Ce sont vraiment des gens pervers».\";s:13:\"numberInSurah\";i:32;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:389;s:4:\"ruku\";i:337;s:11:\"hizbQuarter\";i:156;s:5:\"sajda\";b:0;}i:32;a:9:{s:6:\"number\";i:3285;s:4:\"text\";s:81:\"«Seigneur, dit [Moïse], j\'ai tué un des leurs et je crains qu\'ils ne me tuent.\";s:13:\"numberInSurah\";i:33;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:389;s:4:\"ruku\";i:337;s:11:\"hizbQuarter\";i:156;s:5:\"sajda\";b:0;}i:33;a:9:{s:6:\"number\";i:3286;s:4:\"text\";s:180:\"Mais Aaron, mon frère, est plus éloquent que moi. Envoie-le donc avec moi comme auxiliaire, pour déclarer ma véracité: je crains, vraiment, qu\'ils ne me traitent de menteur».\";s:13:\"numberInSurah\";i:34;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:389;s:4:\"ruku\";i:337;s:11:\"hizbQuarter\";i:156;s:5:\"sajda\";b:0;}i:34;a:9:{s:6:\"number\";i:3287;s:4:\"text\";s:234:\"[Allah] dit: «Nous allons, par ton frère, fortifier ton bras, et vous donner des arguments irréfutables; ils ne sauront vous atteindre, grâce à Nos signes [Nos miracles]. Vous deux et ceux qui vous suivront seront les vainqueurs.\";s:13:\"numberInSurah\";i:35;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:389;s:4:\"ruku\";i:337;s:11:\"hizbQuarter\";i:156;s:5:\"sajda\";b:0;}i:35;a:9:{s:6:\"number\";i:3288;s:4:\"text\";s:181:\"Puis, quand Moïse vint à eux avec Nos prodiges évidents, ils dirent: «Ce n\'est là que magie inventée. Jamais nous n\'avons entendu parler de cela chez nos premiers ancêtres».\";s:13:\"numberInSurah\";i:36;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:390;s:4:\"ruku\";i:337;s:11:\"hizbQuarter\";i:156;s:5:\"sajda\";b:0;}i:36;a:9:{s:6:\"number\";i:3289;s:4:\"text\";s:172:\"Et Moïse dit: «Mon Seigneur connaît mieux qui est venu de Sa part avec la guidée, et à qui appartiendra la Demeure finale. Vraiment, les injustes ne réussiront pas».\";s:13:\"numberInSurah\";i:37;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:390;s:4:\"ruku\";i:337;s:11:\"hizbQuarter\";i:156;s:5:\"sajda\";b:0;}i:37;a:9:{s:6:\"number\";i:3290;s:4:\"text\";s:261:\"Et Pharaon dit: «O notables, je ne connais pas de divinité pour vous, autre que moi. Hâmân, allume-moi du feu sur l\'argile puis construis-moi une tour peut-être alors monterai-je jusqu\'au Dieu de Moïse. Je pense plutôt qu\'il est du nombre des menteurs».\";s:13:\"numberInSurah\";i:38;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:390;s:4:\"ruku\";i:337;s:11:\"hizbQuarter\";i:156;s:5:\"sajda\";b:0;}i:38;a:9:{s:6:\"number\";i:3291;s:4:\"text\";s:135:\"Et il s\'enfla d\'orgueil sur terre ainsi que ses soldats, sans aucun droit. Et ils pensèrent qu\'ils ne seraient pas ramenés vers Nous.\";s:13:\"numberInSurah\";i:39;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:390;s:4:\"ruku\";i:337;s:11:\"hizbQuarter\";i:156;s:5:\"sajda\";b:0;}i:39;a:9:{s:6:\"number\";i:3292;s:4:\"text\";s:123:\"Nous le saisîmes donc, ainsi que ses soldats, et les jetâmes dans le flot. Regarde donc ce qu\'il est advenu des injustes!\";s:13:\"numberInSurah\";i:40;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:390;s:4:\"ruku\";i:337;s:11:\"hizbQuarter\";i:156;s:5:\"sajda\";b:0;}i:40;a:9:{s:6:\"number\";i:3293;s:4:\"text\";s:122:\"Nous fîmes d\'eux des dirigeants qui appellent les gens au Feu. Et au Jour de la Résurrection ils ne seront pas secourus.\";s:13:\"numberInSurah\";i:41;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:390;s:4:\"ruku\";i:337;s:11:\"hizbQuarter\";i:156;s:5:\"sajda\";b:0;}i:41;a:9:{s:6:\"number\";i:3294;s:4:\"text\";s:128:\"Nous les fîmes suivre, dans cette vie ici-bas, d\'une malédiction. Et au Jour de la Résurrection, ils seront parmi les honnis.\";s:13:\"numberInSurah\";i:42;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:390;s:4:\"ruku\";i:337;s:11:\"hizbQuarter\";i:156;s:5:\"sajda\";b:0;}i:42;a:9:{s:6:\"number\";i:3295;s:4:\"text\";s:215:\"Nous avons en effet, donné le Livre à Moïse, - après avoir fait périr les anciennes générations, - en tant que preuves illuminantes pour les gens, ainsi que guidée et miséricorde afin qu\'ils se souviennent.\";s:13:\"numberInSurah\";i:43;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:390;s:4:\"ruku\";i:338;s:11:\"hizbQuarter\";i:156;s:5:\"sajda\";b:0;}i:43;a:9:{s:6:\"number\";i:3296;s:4:\"text\";s:142:\"Tu n\'étais pas sur le versant ouest (du Sinaï), quand Nous avons décrété les commandements à Moïse; tu n\'étais pas parmi les témoins.\";s:13:\"numberInSurah\";i:44;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:391;s:4:\"ruku\";i:338;s:11:\"hizbQuarter\";i:156;s:5:\"sajda\";b:0;}i:44;a:9:{s:6:\"number\";i:3297;s:4:\"text\";s:212:\"Mais Nous avons fait naître des générations dont l\'âge s\'est prolongé. Et tu n\'étais pas [non plus] résident parmi les gens de Madyan leur récitant Nos versets; mais c\'est Nous qui envoyons les Messagers.\";s:13:\"numberInSurah\";i:45;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:391;s:4:\"ruku\";i:338;s:11:\"hizbQuarter\";i:156;s:5:\"sajda\";b:0;}i:45;a:9:{s:6:\"number\";i:3298;s:4:\"text\";s:219:\"Et tu n\'étais pas au flanc du Mont Tor quand Nous avons appelé. Mais (tu es venu comme) une miséricorde de ton Seigneur, pour avertir un peuple à qui nul avertisseur avant toi n\'est venu, afin qu\'ils se souviennent.\";s:13:\"numberInSurah\";i:46;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:391;s:4:\"ruku\";i:338;s:11:\"hizbQuarter\";i:156;s:5:\"sajda\";b:0;}i:46;a:9:{s:6:\"number\";i:3299;s:4:\"text\";s:238:\"Si un malheur les atteignait en rétribution de ce que leurs propres mains avaient préparé, ils diraient: «Seigneur, pourquoi ne nous as-Tu pas envoyé un Messager? Nous aurions alors suivi Tes versets et nous aurions été croyants».\";s:13:\"numberInSurah\";i:47;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:391;s:4:\"ruku\";i:338;s:11:\"hizbQuarter\";i:156;s:5:\"sajda\";b:0;}i:47;a:9:{s:6:\"number\";i:3300;s:4:\"text\";s:302:\"Mais quand la vérité leur est venue de Notre part, ils ont dit: «Si seulement il avait reçu la même chose que Moïse! «Est-ce qu\'ils n\'ont pas nié ce qui auparavant fut apporté à Moïse? Ils dirent: «Deux magies se sont mutuellement soutenues!» Et ils dirent: «Nous n\'avons foi en aucune».\";s:13:\"numberInSurah\";i:48;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:391;s:4:\"ruku\";i:338;s:11:\"hizbQuarter\";i:156;s:5:\"sajda\";b:0;}i:48;a:9:{s:6:\"number\";i:3301;s:4:\"text\";s:137:\"Dis-leur: «Apportez donc un Livre venant d\'Allah qui soit meilleur guide que ces deux-là, et je le suivrai si vous êtes véridiques».\";s:13:\"numberInSurah\";i:49;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:391;s:4:\"ruku\";i:338;s:11:\"hizbQuarter\";i:156;s:5:\"sajda\";b:0;}i:49;a:9:{s:6:\"number\";i:3302;s:4:\"text\";s:223:\"Mais s\'ils ne te répondent pas, sache alors que c\'est seulement leurs passions qu\'ils suivent. Et qui est plus égaré que celui qui suit sa passion sans une guidée d\'Allah? Allah vraiment, ne guide pas les gens injustes.\";s:13:\"numberInSurah\";i:50;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:391;s:4:\"ruku\";i:338;s:11:\"hizbQuarter\";i:156;s:5:\"sajda\";b:0;}i:50;a:9:{s:6:\"number\";i:3303;s:4:\"text\";s:79:\"Nous leur avons déjà exposé la Parole (le Coran) afin qu\'ils se souviennent.\";s:13:\"numberInSurah\";i:51;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:392;s:4:\"ruku\";i:339;s:11:\"hizbQuarter\";i:157;s:5:\"sajda\";b:0;}i:51;a:9:{s:6:\"number\";i:3304;s:4:\"text\";s:75:\"Ceux à qui, avant lui [le Coran], Nous avons apporté le Livre, y croient.\";s:13:\"numberInSurah\";i:52;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:392;s:4:\"ruku\";i:339;s:11:\"hizbQuarter\";i:157;s:5:\"sajda\";b:0;}i:52;a:9:{s:6:\"number\";i:3305;s:4:\"text\";s:162:\"Et quand on le leur récite, ils disent: «Nous y croyons. Ceci est bien la vérité émanant de notre Seigneur. Déjà avant son arrivée, nous étions Soumis».\";s:13:\"numberInSurah\";i:53;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:392;s:4:\"ruku\";i:339;s:11:\"hizbQuarter\";i:157;s:5:\"sajda\";b:0;}i:53;a:9:{s:6:\"number\";i:3306;s:4:\"text\";s:174:\"Voilà ceux qui recevront deux fois leur récompense pour leur endurance, pour avoir répondu au mal par le bien, et pour avoir dépensé de ce que Nous leur avons attribué;\";s:13:\"numberInSurah\";i:54;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:392;s:4:\"ruku\";i:339;s:11:\"hizbQuarter\";i:157;s:5:\"sajda\";b:0;}i:54;a:9:{s:6:\"number\";i:3307;s:4:\"text\";s:172:\"et quand ils entendent des futilités, ils s\'en détournent et disent: «A nous nos actions, et à vous les vôtres. Paix sur vous. Nous ne recherchons pas les ignorants».\";s:13:\"numberInSurah\";i:55;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:392;s:4:\"ruku\";i:339;s:11:\"hizbQuarter\";i:157;s:5:\"sajda\";b:0;}i:55;a:9:{s:6:\"number\";i:3308;s:4:\"text\";s:134:\"Tu [Muhammad] ne diriges pas celui que tu aimes: mais c\'est Allah qui guide qui Il veut. Il connaît mieux cependant les bien-guidés.\";s:13:\"numberInSurah\";i:56;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:392;s:4:\"ruku\";i:339;s:11:\"hizbQuarter\";i:157;s:5:\"sajda\";b:0;}i:56;a:9:{s:6:\"number\";i:3309;s:4:\"text\";s:292:\"Et ils dirent: «Si nous suivons avec toi la bonne voie, on nous arrachera de notre terre». - Ne les avons-Nous pas établis dans une enceinte sacrée, sûre, vers laquelle des produits de toute sorte sont apportés comme attribution de Notre part? Mais la plupart d\'entre eux ne savent pas.\";s:13:\"numberInSurah\";i:57;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:392;s:4:\"ruku\";i:339;s:11:\"hizbQuarter\";i:157;s:5:\"sajda\";b:0;}i:57;a:9:{s:6:\"number\";i:3310;s:4:\"text\";s:233:\"Et combien avons-Nous fait périr de cités qui étaient ingrates (alors que leurs habitants vivaient dans l\'abondance), et voilà qu\'après eux leurs demeures ne sont que très peu habitées, et c\'est Nous qui en fûmes l\'héritier.\";s:13:\"numberInSurah\";i:58;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:392;s:4:\"ruku\";i:339;s:11:\"hizbQuarter\";i:157;s:5:\"sajda\";b:0;}i:58;a:9:{s:6:\"number\";i:3311;s:4:\"text\";s:209:\"Ton Seigneur ne fait pas périr des cités avant d\'avoir envoyé dans leur métropole un Messager pour leur réciter Nos versets. Et Nous ne faisons périr les cités que lorsque leurs habitants sont injustes.\";s:13:\"numberInSurah\";i:59;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:392;s:4:\"ruku\";i:339;s:11:\"hizbQuarter\";i:157;s:5:\"sajda\";b:0;}i:59;a:9:{s:6:\"number\";i:3312;s:4:\"text\";s:190:\"Tout ce qui vous a été donné est la jouissance éphémère de la vie ici-bas et sa parure, alors que ce qui est auprès d\'Allah est meilleur et plus durable... Ne comprenez-vous donc pas?\";s:13:\"numberInSurah\";i:60;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:393;s:4:\"ruku\";i:339;s:11:\"hizbQuarter\";i:157;s:5:\"sajda\";b:0;}i:60;a:9:{s:6:\"number\";i:3313;s:4:\"text\";s:259:\"Celui à qui Nous avons fait une belle promesse dont il verra l\'accomplissement, est-il comparable à celui à qui Nous avons accordé la jouissance de la vie présente et qui sera ensuite le Jour de la Résurrection, de ceux qui comparaîtront (devant Nous).\";s:13:\"numberInSurah\";i:61;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:393;s:4:\"ruku\";i:340;s:11:\"hizbQuarter\";i:157;s:5:\"sajda\";b:0;}i:61;a:9:{s:6:\"number\";i:3314;s:4:\"text\";s:101:\"Et le jour où Il les appellera, Il dira: «Où sont ceux que vous prétendiez être Mes associés?»\";s:13:\"numberInSurah\";i:62;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:393;s:4:\"ruku\";i:340;s:11:\"hizbQuarter\";i:157;s:5:\"sajda\";b:0;}i:62;a:9:{s:6:\"number\";i:3315;s:4:\"text\";s:237:\"Ceux contre qui la Parole se réalisera diront: «Voici, Seigneur, ceux que nous avons séduits. Nous les avons séduits comme nous nous sommes dévoyés nous-mêmes. Nous les désavouons devant Toi: ce n\'est pas nous qu\'ils adoraient».\";s:13:\"numberInSurah\";i:63;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:393;s:4:\"ruku\";i:340;s:11:\"hizbQuarter\";i:157;s:5:\"sajda\";b:0;}i:63;a:9:{s:6:\"number\";i:3316;s:4:\"text\";s:212:\"Et on [leur] dira: «Appelez vos associés». Ils les appelleront, mais ceux-ci ne leur répondront pas. Quand ils verront le châtiment, ils désireront alors avoir suivi le chemin droit (dans la vie d\'ici-bas).\";s:13:\"numberInSurah\";i:64;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:393;s:4:\"ruku\";i:340;s:11:\"hizbQuarter\";i:157;s:5:\"sajda\";b:0;}i:64;a:9:{s:6:\"number\";i:3317;s:4:\"text\";s:85:\"Et le jour où Il les appellera et qu\'Il dira: «Que répondiez-vous aux Messagers?»\";s:13:\"numberInSurah\";i:65;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:393;s:4:\"ruku\";i:340;s:11:\"hizbQuarter\";i:157;s:5:\"sajda\";b:0;}i:65;a:9:{s:6:\"number\";i:3318;s:4:\"text\";s:90:\"Ce jour-là, leurs arguments deviendront obscurs et ils ne se poseront point de questions.\";s:13:\"numberInSurah\";i:66;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:393;s:4:\"ruku\";i:340;s:11:\"hizbQuarter\";i:157;s:5:\"sajda\";b:0;}i:66;a:9:{s:6:\"number\";i:3319;s:4:\"text\";s:112:\"Mais celui qui se sera repenti, qui aura cru et fait le bien, il se peut qu\'il soit parmi ceux qui réussissent.\";s:13:\"numberInSurah\";i:67;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:393;s:4:\"ruku\";i:340;s:11:\"hizbQuarter\";i:157;s:5:\"sajda\";b:0;}i:67;a:9:{s:6:\"number\";i:3320;s:4:\"text\";s:148:\"Ton Seigneur crée ce qu\'Il veut et Il choisit; il ne leur a jamais appartenu de choisir. Gloire à Allah! Il transcende ce qu\'ils associent à Lui!\";s:13:\"numberInSurah\";i:68;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:393;s:4:\"ruku\";i:340;s:11:\"hizbQuarter\";i:157;s:5:\"sajda\";b:0;}i:68;a:9:{s:6:\"number\";i:3321;s:4:\"text\";s:73:\"Ton Seigneur sait ce que cachent leurs poitrines et ce qu\'ils divulguent.\";s:13:\"numberInSurah\";i:69;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:393;s:4:\"ruku\";i:340;s:11:\"hizbQuarter\";i:157;s:5:\"sajda\";b:0;}i:69;a:9:{s:6:\"number\";i:3322;s:4:\"text\";s:157:\"C\'est lui Allah. Pas de divinité à part Lui. A Lui la louange ici-bas comme dans l\'au-delà. A Lui appartient le jugement. Et vers Lui vous serez ramenés.\";s:13:\"numberInSurah\";i:70;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:393;s:4:\"ruku\";i:340;s:11:\"hizbQuarter\";i:157;s:5:\"sajda\";b:0;}i:70;a:9:{s:6:\"number\";i:3323;s:4:\"text\";s:201:\"Dis: «Que diriez-vous? Si Allah vous assignait la nuit en permanence jusqu\'au Jour de la Résurrection, quelle divinité autre qu\'Allah pourrait vous apporter une lumière? N\'entendez-vous donc pas?»\";s:13:\"numberInSurah\";i:71;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:394;s:4:\"ruku\";i:340;s:11:\"hizbQuarter\";i:157;s:5:\"sajda\";b:0;}i:71;a:9:{s:6:\"number\";i:3324;s:4:\"text\";s:229:\"Dis: «Que diriez-vous? Si Allah vous assignait le jour en permanence jusqu\'au Jour de la Résurrection, quelle divinité autre qu\'Allah pourrait vous apporter une nuit durant laquelle vous reposeriez? N\'observez-vous donc pas?»\";s:13:\"numberInSurah\";i:72;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:394;s:4:\"ruku\";i:340;s:11:\"hizbQuarter\";i:157;s:5:\"sajda\";b:0;}i:72;a:9:{s:6:\"number\";i:3325;s:4:\"text\";s:166:\"C\'est de par Sa miséricorde qu\'Il vous a assigné la nuit et le jour: pour que vous vous y reposiez et cherchiez de Sa grâce, et afin que vous soyez reconnaissants.\";s:13:\"numberInSurah\";i:73;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:394;s:4:\"ruku\";i:340;s:11:\"hizbQuarter\";i:157;s:5:\"sajda\";b:0;}i:73;a:9:{s:6:\"number\";i:3326;s:4:\"text\";s:101:\"Et le jour où Il les appellera, Il dira: «Où sont ceux que vous prétendiez être Mes associés?»\";s:13:\"numberInSurah\";i:74;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:394;s:4:\"ruku\";i:340;s:11:\"hizbQuarter\";i:157;s:5:\"sajda\";b:0;}i:74;a:9:{s:6:\"number\";i:3327;s:4:\"text\";s:219:\"Cependant, Nous ferons sortir de chaque communauté un témoin, puis Nous dirons: «Apportez votre preuve décisive». Ils sauront alors que la Vérité est à Allah; et que ce qu\'ils avaient inventé les a abandonnés.\";s:13:\"numberInSurah\";i:75;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:394;s:4:\"ruku\";i:340;s:11:\"hizbQuarter\";i:157;s:5:\"sajda\";b:0;}i:75;a:9:{s:6:\"number\";i:3328;s:4:\"text\";s:280:\"En vérité, Coré [Karoûn] était du peuple de Moïse mais il était empli de violence envers eux. Nous lui avions donné des trésors dont les clefs pesaient lourd à toute une bande de gens forts. Son peuple lui dit: «Ne te réjouis point. Car Allah n\'aime pas les arrogants.\";s:13:\"numberInSurah\";i:76;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:394;s:4:\"ruku\";i:341;s:11:\"hizbQuarter\";i:158;s:5:\"sajda\";b:0;}i:76;a:9:{s:6:\"number\";i:3329;s:4:\"text\";s:258:\"Et recherche à travers ce qu\'Allah t\'a donné, la Demeure dernière. Et n\'oublie pas ta part en cette vie. Et sois bienfaisant comme Allah a été bienfaisant envers toi. Et ne recherche pas la corruption sur terre. Car Allah n\'aime point les corrupteurs».\";s:13:\"numberInSurah\";i:77;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:394;s:4:\"ruku\";i:341;s:11:\"hizbQuarter\";i:158;s:5:\"sajda\";b:0;}i:77;a:9:{s:6:\"number\";i:3330;s:4:\"text\";s:261:\"Il dit: «C\'est par une science que je possède que ceci m\'est venu». Ne savait-il pas qu\'avant lui Allah avait fait périr des générations supérieures à lui en force et plus riches en biens? Et les criminels ne seront pas interrogés sur leurs péchés»!\";s:13:\"numberInSurah\";i:78;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:395;s:4:\"ruku\";i:341;s:11:\"hizbQuarter\";i:158;s:5:\"sajda\";b:0;}i:78;a:9:{s:6:\"number\";i:3331;s:4:\"text\";s:205:\"Il sortit à son peuple dans tout son apparat. Ceux qui aimaient la vie présente dirent: «Si seulement nous avions comme ce qui a été donné à Coré. Il a été doté, certes, d\'une immense fortune».\";s:13:\"numberInSurah\";i:79;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:395;s:4:\"ruku\";i:341;s:11:\"hizbQuarter\";i:158;s:5:\"sajda\";b:0;}i:79;a:9:{s:6:\"number\";i:3332;s:4:\"text\";s:205:\"Tandis que ceux auxquels le savoir a été donné dirent: «Malheur à vous! La récompense d\'Allah est meilleure pour celui qui croit et fait le bien». Mais elle ne sera reçue que par ceux qui endurent.\";s:13:\"numberInSurah\";i:80;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:395;s:4:\"ruku\";i:341;s:11:\"hizbQuarter\";i:158;s:5:\"sajda\";b:0;}i:80;a:9:{s:6:\"number\";i:3333;s:4:\"text\";s:156:\"Nous fîmes donc que la terre l\'engloutît, lui et sa maison. Aucun clan en dehors d\'Allah ne fut là pour le secourir, et il ne pût se secourir lui-même.\";s:13:\"numberInSurah\";i:81;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:395;s:4:\"ruku\";i:341;s:11:\"hizbQuarter\";i:158;s:5:\"sajda\";b:0;}i:81;a:9:{s:6:\"number\";i:3334;s:4:\"text\";s:325:\"Et ceux qui, la veille, souhaitaient d\'être à sa place, se mirent à dire: «Ah! Il est vrai qu\'Allah augmente la part de qui Il veut, parmi Ses serviteurs, ou la restreint. Si Allah ne nous avait pas favorisés, Il nous aurait certainement fait engloutir. Ah! Il est vrai que ceux qui ne croient pas ne réussissent pas».\";s:13:\"numberInSurah\";i:82;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:395;s:4:\"ruku\";i:341;s:11:\"hizbQuarter\";i:158;s:5:\"sajda\";b:0;}i:82;a:9:{s:6:\"number\";i:3335;s:4:\"text\";s:175:\"Cette Demeure dernière, Nous la réservons à ceux qui ne recherchent, ni à s\'élever sur terre, ni à y semer la corruption. Cependant, l\'heureuse fin appartient aux pieux.\";s:13:\"numberInSurah\";i:83;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:395;s:4:\"ruku\";i:341;s:11:\"hizbQuarter\";i:158;s:5:\"sajda\";b:0;}i:83;a:9:{s:6:\"number\";i:3336;s:4:\"text\";s:202:\"Quiconque viendra avec le bien, aura meilleur que cela encore; et quiconque viendra avec le mal, (qu\'il sache que) ceux qui commettront des méfaits ne seront rétribués que selon ce qu\'ils ont commis.\";s:13:\"numberInSurah\";i:84;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:395;s:4:\"ruku\";i:341;s:11:\"hizbQuarter\";i:158;s:5:\"sajda\";b:0;}i:84;a:9:{s:6:\"number\";i:3337;s:4:\"text\";s:204:\"Celui qui t\'a prescrit le Coran te ramènera certainement là où tu (souhaites) retourner. Dis: «Mon Seigneur connaît mieux celui qui a apporté la guidée et celui qui est dans un égarement évident.\";s:13:\"numberInSurah\";i:85;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:396;s:4:\"ruku\";i:341;s:11:\"hizbQuarter\";i:158;s:5:\"sajda\";b:0;}i:85;a:9:{s:6:\"number\";i:3338;s:4:\"text\";s:167:\"Tu n\'espérais nullement que le Livre te serait révélé. Ceci n\'a été que par une miséricorde de ton Seigneur. Ne sois donc jamais un soutien pour les infidèles;\";s:13:\"numberInSurah\";i:86;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:396;s:4:\"ruku\";i:341;s:11:\"hizbQuarter\";i:158;s:5:\"sajda\";b:0;}i:86;a:9:{s:6:\"number\";i:3339;s:4:\"text\";s:184:\"et que ceux-ci ne te détournent point des versets d\'Allah une fois qu\'on les a fait descendre vers toi. Appelle les gens vers ton Seigneur et ne sois point du nombre des Associateurs.\";s:13:\"numberInSurah\";i:87;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:396;s:4:\"ruku\";i:341;s:11:\"hizbQuarter\";i:158;s:5:\"sajda\";b:0;}i:87;a:9:{s:6:\"number\";i:3340;s:4:\"text\";s:176:\"Et n\'invoque nulle autre divinité avec Allah. Point de divinité à part Lui. Tout doit périr, sauf Son Visage. A Lui appartient le jugement; et vers Lui vous serez ramenés.\";s:13:\"numberInSurah\";i:88;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:396;s:4:\"ruku\";i:341;s:11:\"hizbQuarter\";i:158;s:5:\"sajda\";b:0;}}s:7:\"edition\";a:7:{s:10:\"identifier\";s:13:\"fr.hamidullah\";s:8:\"language\";s:2:\"fr\";s:4:\"name\";s:10:\"Hamidullah\";s:11:\"englishName\";s:19:\"Muhammad Hamidullah\";s:6:\"format\";s:4:\"text\";s:4:\"type\";s:11:\"translation\";s:9:\"direction\";s:3:\"ltr\";}}', 1794581362);
INSERT INTO `cache` (`key`, `value`, `expiration`) VALUES
('quranapp-cache-surah_29_ar.uthmani', 'a:8:{s:6:\"number\";i:29;s:4:\"name\";s:39:\"سُورَةُ العَنكَبُوتِ\";s:11:\"englishName\";s:11:\"Al-Ankaboot\";s:22:\"englishNameTranslation\";s:10:\"The Spider\";s:14:\"revelationType\";s:6:\"Meccan\";s:13:\"numberOfAyahs\";i:69;s:5:\"ayahs\";a:69:{i:0;a:9:{s:6:\"number\";i:3341;s:4:\"text\";s:87:\"بِسۡمِ ٱللَّهِ ٱلرَّحۡمَـٰنِ ٱلرَّحِیمِ الۤمۤ\n\";s:13:\"numberInSurah\";i:1;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:396;s:4:\"ruku\";i:342;s:11:\"hizbQuarter\";i:159;s:5:\"sajda\";b:0;}i:1;a:9:{s:6:\"number\";i:3342;s:4:\"text\";s:158:\"أَحَسِبَ ٱلنَّاسُ أَن یُتۡرَكُوۤا۟ أَن یَقُولُوۤا۟ ءَامَنَّا وَهُمۡ لَا یُفۡتَنُونَ\n\";s:13:\"numberInSurah\";i:2;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:396;s:4:\"ruku\";i:342;s:11:\"hizbQuarter\";i:159;s:5:\"sajda\";b:0;}i:2;a:9:{s:6:\"number\";i:3343;s:4:\"text\";s:227:\"وَلَقَدۡ فَتَنَّا ٱلَّذِینَ مِن قَبۡلِهِمۡۖ فَلَیَعۡلَمَنَّ ٱللَّهُ ٱلَّذِینَ صَدَقُوا۟ وَلَیَعۡلَمَنَّ ٱلۡكَـٰذِبِینَ\n\";s:13:\"numberInSurah\";i:3;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:396;s:4:\"ruku\";i:342;s:11:\"hizbQuarter\";i:159;s:5:\"sajda\";b:0;}i:3;a:9:{s:6:\"number\";i:3344;s:4:\"text\";s:170:\"أَمۡ حَسِبَ ٱلَّذِینَ یَعۡمَلُونَ ٱلسَّیِّـَٔاتِ أَن یَسۡبِقُونَاۚ سَاۤءَ مَا یَحۡكُمُونَ\n\";s:13:\"numberInSurah\";i:4;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:396;s:4:\"ruku\";i:342;s:11:\"hizbQuarter\";i:159;s:5:\"sajda\";b:0;}i:4;a:9:{s:6:\"number\";i:3345;s:4:\"text\";s:187:\"مَن كَانَ یَرۡجُوا۟ لِقَاۤءَ ٱللَّهِ فَإِنَّ أَجَلَ ٱللَّهِ لَـَٔاتࣲۚ وَهُوَ ٱلسَّمِیعُ ٱلۡعَلِیمُ\n\";s:13:\"numberInSurah\";i:5;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:396;s:4:\"ruku\";i:342;s:11:\"hizbQuarter\";i:159;s:5:\"sajda\";b:0;}i:5;a:9:{s:6:\"number\";i:3346;s:4:\"text\";s:180:\"وَمَن جَـٰهَدَ فَإِنَّمَا یُجَـٰهِدُ لِنَفۡسِهِۦۤۚ إِنَّ ٱللَّهَ لَغَنِیٌّ عَنِ ٱلۡعَـٰلَمِینَ\n\";s:13:\"numberInSurah\";i:6;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:396;s:4:\"ruku\";i:342;s:11:\"hizbQuarter\";i:159;s:5:\"sajda\";b:0;}i:6;a:9:{s:6:\"number\";i:3347;s:4:\"text\";s:286:\"وَٱلَّذِینَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ لَنُكَفِّرَنَّ عَنۡهُمۡ سَیِّـَٔاتِهِمۡ وَلَنَجۡزِیَنَّهُمۡ أَحۡسَنَ ٱلَّذِی كَانُوا۟ یَعۡمَلُونَ\n\";s:13:\"numberInSurah\";i:7;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:397;s:4:\"ruku\";i:342;s:11:\"hizbQuarter\";i:159;s:5:\"sajda\";b:0;}i:7;a:9:{s:6:\"number\";i:3348;s:4:\"text\";s:373:\"وَوَصَّیۡنَا ٱلۡإِنسَـٰنَ بِوَ ٰ⁠لِدَیۡهِ حُسۡنࣰاۖ وَإِن جَـٰهَدَاكَ لِتُشۡرِكَ بِی مَا لَیۡسَ لَكَ بِهِۦ عِلۡمࣱ فَلَا تُطِعۡهُمَاۤۚ إِلَیَّ مَرۡجِعُكُمۡ فَأُنَبِّئُكُم بِمَا كُنتُمۡ تَعۡمَلُونَ\n\";s:13:\"numberInSurah\";i:8;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:397;s:4:\"ruku\";i:342;s:11:\"hizbQuarter\";i:159;s:5:\"sajda\";b:0;}i:8;a:9:{s:6:\"number\";i:3349;s:4:\"text\";s:169:\"وَٱلَّذِینَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ لَنُدۡخِلَنَّهُمۡ فِی ٱلصَّـٰلِحِینَ\n\";s:13:\"numberInSurah\";i:9;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:397;s:4:\"ruku\";i:342;s:11:\"hizbQuarter\";i:159;s:5:\"sajda\";b:0;}i:9;a:9:{s:6:\"number\";i:3350;s:4:\"text\";s:486:\"وَمِنَ ٱلنَّاسِ مَن یَقُولُ ءَامَنَّا بِٱللَّهِ فَإِذَاۤ أُوذِیَ فِی ٱللَّهِ جَعَلَ فِتۡنَةَ ٱلنَّاسِ كَعَذَابِ ٱللَّهِۖ وَلَىِٕن جَاۤءَ نَصۡرࣱ مِّن رَّبِّكَ لَیَقُولُنَّ إِنَّا كُنَّا مَعَكُمۡۚ أَوَلَیۡسَ ٱللَّهُ بِأَعۡلَمَ بِمَا فِی صُدُورِ ٱلۡعَـٰلَمِینَ\n\";s:13:\"numberInSurah\";i:10;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:397;s:4:\"ruku\";i:342;s:11:\"hizbQuarter\";i:159;s:5:\"sajda\";b:0;}i:10;a:9:{s:6:\"number\";i:3351;s:4:\"text\";s:150:\"وَلَیَعۡلَمَنَّ ٱللَّهُ ٱلَّذِینَ ءَامَنُوا۟ وَلَیَعۡلَمَنَّ ٱلۡمُنَـٰفِقِینَ\n\";s:13:\"numberInSurah\";i:11;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:397;s:4:\"ruku\";i:342;s:11:\"hizbQuarter\";i:159;s:5:\"sajda\";b:0;}i:11;a:9:{s:6:\"number\";i:3352;s:4:\"text\";s:344:\"وَقَالَ ٱلَّذِینَ كَفَرُوا۟ لِلَّذِینَ ءَامَنُوا۟ ٱتَّبِعُوا۟ سَبِیلَنَا وَلۡنَحۡمِلۡ خَطَـٰیَـٰكُمۡ وَمَا هُم بِحَـٰمِلِینَ مِنۡ خَطَـٰیَـٰهُم مِّن شَیۡءٍۖ إِنَّهُمۡ لَكَـٰذِبُونَ\n\";s:13:\"numberInSurah\";i:12;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:397;s:4:\"ruku\";i:342;s:11:\"hizbQuarter\";i:159;s:5:\"sajda\";b:0;}i:12;a:9:{s:6:\"number\";i:3353;s:4:\"text\";s:250:\"وَلَیَحۡمِلُنَّ أَثۡقَالَهُمۡ وَأَثۡقَالࣰا مَّعَ أَثۡقَالِهِمۡۖ وَلَیُسۡـَٔلُنَّ یَوۡمَ ٱلۡقِیَـٰمَةِ عَمَّا كَانُوا۟ یَفۡتَرُونَ\n\";s:13:\"numberInSurah\";i:13;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:397;s:4:\"ruku\";i:342;s:11:\"hizbQuarter\";i:159;s:5:\"sajda\";b:0;}i:13;a:9:{s:6:\"number\";i:3354;s:4:\"text\";s:273:\"وَلَقَدۡ أَرۡسَلۡنَا نُوحًا إِلَىٰ قَوۡمِهِۦ فَلَبِثَ فِیهِمۡ أَلۡفَ سَنَةٍ إِلَّا خَمۡسِینَ عَامࣰا فَأَخَذَهُمُ ٱلطُّوفَانُ وَهُمۡ ظَـٰلِمُونَ\n\";s:13:\"numberInSurah\";i:14;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:397;s:4:\"ruku\";i:343;s:11:\"hizbQuarter\";i:159;s:5:\"sajda\";b:0;}i:14;a:9:{s:6:\"number\";i:3355;s:4:\"text\";s:163:\"فَأَنجَیۡنَـٰهُ وَأَصۡحَـٰبَ ٱلسَّفِینَةِ وَجَعَلۡنَـٰهَاۤ ءَایَةࣰ لِّلۡعَـٰلَمِینَ\n\";s:13:\"numberInSurah\";i:15;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:398;s:4:\"ruku\";i:343;s:11:\"hizbQuarter\";i:159;s:5:\"sajda\";b:0;}i:15;a:9:{s:6:\"number\";i:3356;s:4:\"text\";s:236:\"وَإِبۡرَ ٰ⁠هِیمَ إِذۡ قَالَ لِقَوۡمِهِ ٱعۡبُدُوا۟ ٱللَّهَ وَٱتَّقُوهُۖ ذَ ٰ⁠لِكُمۡ خَیۡرࣱ لَّكُمۡ إِن كُنتُمۡ تَعۡلَمُونَ\n\";s:13:\"numberInSurah\";i:16;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:398;s:4:\"ruku\";i:343;s:11:\"hizbQuarter\";i:159;s:5:\"sajda\";b:0;}i:16;a:9:{s:6:\"number\";i:3357;s:4:\"text\";s:461:\"إِنَّمَا تَعۡبُدُونَ مِن دُونِ ٱللَّهِ أَوۡثَـٰنࣰا وَتَخۡلُقُونَ إِفۡكًاۚ إِنَّ ٱلَّذِینَ تَعۡبُدُونَ مِن دُونِ ٱللَّهِ لَا یَمۡلِكُونَ لَكُمۡ رِزۡقࣰا فَٱبۡتَغُوا۟ عِندَ ٱللَّهِ ٱلرِّزۡقَ وَٱعۡبُدُوهُ وَٱشۡكُرُوا۟ لَهُۥۤۖ إِلَیۡهِ تُرۡجَعُونَ\n\";s:13:\"numberInSurah\";i:17;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:398;s:4:\"ruku\";i:343;s:11:\"hizbQuarter\";i:159;s:5:\"sajda\";b:0;}i:17;a:9:{s:6:\"number\";i:3358;s:4:\"text\";s:210:\"وَإِن تُكَذِّبُوا۟ فَقَدۡ كَذَّبَ أُمَمࣱ مِّن قَبۡلِكُمۡۖ وَمَا عَلَى ٱلرَّسُولِ إِلَّا ٱلۡبَلَـٰغُ ٱلۡمُبِینُ\n\";s:13:\"numberInSurah\";i:18;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:398;s:4:\"ruku\";i:343;s:11:\"hizbQuarter\";i:159;s:5:\"sajda\";b:0;}i:18;a:9:{s:6:\"number\";i:3359;s:4:\"text\";s:208:\"أَوَلَمۡ یَرَوۡا۟ كَیۡفَ یُبۡدِئُ ٱللَّهُ ٱلۡخَلۡقَ ثُمَّ یُعِیدُهُۥۤۚ إِنَّ ذَ ٰ⁠لِكَ عَلَى ٱللَّهِ یَسِیرࣱ\n\";s:13:\"numberInSurah\";i:19;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:398;s:4:\"ruku\";i:343;s:11:\"hizbQuarter\";i:159;s:5:\"sajda\";b:0;}i:19;a:9:{s:6:\"number\";i:3360;s:4:\"text\";s:295:\"قُلۡ سِیرُوا۟ فِی ٱلۡأَرۡضِ فَٱنظُرُوا۟ كَیۡفَ بَدَأَ ٱلۡخَلۡقَۚ ثُمَّ ٱللَّهُ یُنشِئُ ٱلنَّشۡأَةَ ٱلۡـَٔاخِرَةَۚ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَیۡءࣲ قَدِیرࣱ\n\";s:13:\"numberInSurah\";i:20;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:398;s:4:\"ruku\";i:343;s:11:\"hizbQuarter\";i:159;s:5:\"sajda\";b:0;}i:20;a:9:{s:6:\"number\";i:3361;s:4:\"text\";s:134:\"یُعَذِّبُ مَن یَشَاۤءُ وَیَرۡحَمُ مَن یَشَاۤءُۖ وَإِلَیۡهِ تُقۡلَبُونَ\n\";s:13:\"numberInSurah\";i:21;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:398;s:4:\"ruku\";i:343;s:11:\"hizbQuarter\";i:159;s:5:\"sajda\";b:0;}i:21;a:9:{s:6:\"number\";i:3362;s:4:\"text\";s:229:\"وَمَاۤ أَنتُم بِمُعۡجِزِینَ فِی ٱلۡأَرۡضِ وَلَا فِی ٱلسَّمَاۤءِۖ وَمَا لَكُم مِّن دُونِ ٱللَّهِ مِن وَلِیࣲّ وَلَا نَصِیرࣲ\n\";s:13:\"numberInSurah\";i:22;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:398;s:4:\"ruku\";i:343;s:11:\"hizbQuarter\";i:159;s:5:\"sajda\";b:0;}i:22;a:9:{s:6:\"number\";i:3363;s:4:\"text\";s:268:\"وَٱلَّذِینَ كَفَرُوا۟ بِـَٔایَـٰتِ ٱللَّهِ وَلِقَاۤىِٕهِۦۤ أُو۟لَـٰۤىِٕكَ یَىِٕسُوا۟ مِن رَّحۡمَتِی وَأُو۟لَـٰۤىِٕكَ لَهُمۡ عَذَابٌ أَلِیمࣱ\n\";s:13:\"numberInSurah\";i:23;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:398;s:4:\"ruku\";i:344;s:11:\"hizbQuarter\";i:159;s:5:\"sajda\";b:0;}i:23;a:9:{s:6:\"number\";i:3364;s:4:\"text\";s:322:\"فَمَا كَانَ جَوَابَ قَوۡمِهِۦۤ إِلَّاۤ أَن قَالُوا۟ ٱقۡتُلُوهُ أَوۡ حَرِّقُوهُ فَأَنجَىٰهُ ٱللَّهُ مِنَ ٱلنَّارِۚ إِنَّ فِی ذَ ٰ⁠لِكَ لَـَٔایَـٰتࣲ لِّقَوۡمࣲ یُؤۡمِنُونَ\n\";s:13:\"numberInSurah\";i:24;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:399;s:4:\"ruku\";i:344;s:11:\"hizbQuarter\";i:159;s:5:\"sajda\";b:0;}i:24;a:9:{s:6:\"number\";i:3365;s:4:\"text\";s:472:\"وَقَالَ إِنَّمَا ٱتَّخَذۡتُم مِّن دُونِ ٱللَّهِ أَوۡثَـٰنࣰا مَّوَدَّةَ بَیۡنِكُمۡ فِی ٱلۡحَیَوٰةِ ٱلدُّنۡیَاۖ ثُمَّ یَوۡمَ ٱلۡقِیَـٰمَةِ یَكۡفُرُ بَعۡضُكُم بِبَعۡضࣲ وَیَلۡعَنُ بَعۡضُكُم بَعۡضࣰا وَمَأۡوَىٰكُمُ ٱلنَّارُ وَمَا لَكُم مِّن نَّـٰصِرِینَ\n\";s:13:\"numberInSurah\";i:25;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:399;s:4:\"ruku\";i:344;s:11:\"hizbQuarter\";i:159;s:5:\"sajda\";b:0;}i:25;a:9:{s:6:\"number\";i:3366;s:4:\"text\";s:194:\"۞ فَـَٔامَنَ لَهُۥ لُوطࣱۘ وَقَالَ إِنِّی مُهَاجِرٌ إِلَىٰ رَبِّیۤۖ إِنَّهُۥ هُوَ ٱلۡعَزِیزُ ٱلۡحَكِیمُ\n\";s:13:\"numberInSurah\";i:26;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:399;s:4:\"ruku\";i:344;s:11:\"hizbQuarter\";i:160;s:5:\"sajda\";b:0;}i:26;a:9:{s:6:\"number\";i:3367;s:4:\"text\";s:364:\"وَوَهَبۡنَا لَهُۥۤ إِسۡحَـٰقَ وَیَعۡقُوبَ وَجَعَلۡنَا فِی ذُرِّیَّتِهِ ٱلنُّبُوَّةَ وَٱلۡكِتَـٰبَ وَءَاتَیۡنَـٰهُ أَجۡرَهُۥ فِی ٱلدُّنۡیَاۖ وَإِنَّهُۥ فِی ٱلۡـَٔاخِرَةِ لَمِنَ ٱلصَّـٰلِحِینَ\n\";s:13:\"numberInSurah\";i:27;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:399;s:4:\"ruku\";i:344;s:11:\"hizbQuarter\";i:160;s:5:\"sajda\";b:0;}i:27;a:9:{s:6:\"number\";i:3368;s:4:\"text\";s:231:\"وَلُوطًا إِذۡ قَالَ لِقَوۡمِهِۦۤ إِنَّكُمۡ لَتَأۡتُونَ ٱلۡفَـٰحِشَةَ مَا سَبَقَكُم بِهَا مِنۡ أَحَدࣲ مِّنَ ٱلۡعَـٰلَمِینَ\n\";s:13:\"numberInSurah\";i:28;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:399;s:4:\"ruku\";i:344;s:11:\"hizbQuarter\";i:160;s:5:\"sajda\";b:0;}i:28;a:9:{s:6:\"number\";i:3369;s:4:\"text\";s:395:\"أَىِٕنَّكُمۡ لَتَأۡتُونَ ٱلرِّجَالَ وَتَقۡطَعُونَ ٱلسَّبِیلَ وَتَأۡتُونَ فِی نَادِیكُمُ ٱلۡمُنكَرَۖ فَمَا كَانَ جَوَابَ قَوۡمِهِۦۤ إِلَّاۤ أَن قَالُوا۟ ٱئۡتِنَا بِعَذَابِ ٱللَّهِ إِن كُنتَ مِنَ ٱلصَّـٰدِقِینَ\n\";s:13:\"numberInSurah\";i:29;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:399;s:4:\"ruku\";i:344;s:11:\"hizbQuarter\";i:160;s:5:\"sajda\";b:0;}i:29;a:9:{s:6:\"number\";i:3370;s:4:\"text\";s:100:\"قَالَ رَبِّ ٱنصُرۡنِی عَلَى ٱلۡقَوۡمِ ٱلۡمُفۡسِدِینَ\n\";s:13:\"numberInSurah\";i:30;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:399;s:4:\"ruku\";i:344;s:11:\"hizbQuarter\";i:160;s:5:\"sajda\";b:0;}i:30;a:9:{s:6:\"number\";i:3371;s:4:\"text\";s:295:\"وَلَمَّا جَاۤءَتۡ رُسُلُنَاۤ إِبۡرَ ٰ⁠هِیمَ بِٱلۡبُشۡرَىٰ قَالُوۤا۟ إِنَّا مُهۡلِكُوۤا۟ أَهۡلِ هَـٰذِهِ ٱلۡقَرۡیَةِۖ إِنَّ أَهۡلَهَا كَانُوا۟ ظَـٰلِمِینَ\n\";s:13:\"numberInSurah\";i:31;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:400;s:4:\"ruku\";i:345;s:11:\"hizbQuarter\";i:160;s:5:\"sajda\";b:0;}i:31;a:9:{s:6:\"number\";i:3372;s:4:\"text\";s:275:\"قَالَ إِنَّ فِیهَا لُوطࣰاۚ قَالُوا۟ نَحۡنُ أَعۡلَمُ بِمَن فِیهَاۖ لَنُنَجِّیَنَّهُۥ وَأَهۡلَهُۥۤ إِلَّا ٱمۡرَأَتَهُۥ كَانَتۡ مِنَ ٱلۡغَـٰبِرِینَ\n\";s:13:\"numberInSurah\";i:32;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:400;s:4:\"ruku\";i:345;s:11:\"hizbQuarter\";i:160;s:5:\"sajda\";b:0;}i:32;a:9:{s:6:\"number\";i:3373;s:4:\"text\";s:361:\"وَلَمَّاۤ أَن جَاۤءَتۡ رُسُلُنَا لُوطࣰا سِیۤءَ بِهِمۡ وَضَاقَ بِهِمۡ ذَرۡعࣰاۖ وَقَالُوا۟ لَا تَخَفۡ وَلَا تَحۡزَنۡ إِنَّا مُنَجُّوكَ وَأَهۡلَكَ إِلَّا ٱمۡرَأَتَكَ كَانَتۡ مِنَ ٱلۡغَـٰبِرِینَ\n\";s:13:\"numberInSurah\";i:33;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:400;s:4:\"ruku\";i:345;s:11:\"hizbQuarter\";i:160;s:5:\"sajda\";b:0;}i:33;a:9:{s:6:\"number\";i:3374;s:4:\"text\";s:203:\"إِنَّا مُنزِلُونَ عَلَىٰۤ أَهۡلِ هَـٰذِهِ ٱلۡقَرۡیَةِ رِجۡزࣰا مِّنَ ٱلسَّمَاۤءِ بِمَا كَانُوا۟ یَفۡسُقُونَ\n\";s:13:\"numberInSurah\";i:34;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:400;s:4:\"ruku\";i:345;s:11:\"hizbQuarter\";i:160;s:5:\"sajda\";b:0;}i:34;a:9:{s:6:\"number\";i:3375;s:4:\"text\";s:133:\"وَلَقَد تَّرَكۡنَا مِنۡهَاۤ ءَایَةَۢ بَیِّنَةࣰ لِّقَوۡمࣲ یَعۡقِلُونَ\n\";s:13:\"numberInSurah\";i:35;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:400;s:4:\"ruku\";i:345;s:11:\"hizbQuarter\";i:160;s:5:\"sajda\";b:0;}i:35;a:9:{s:6:\"number\";i:3376;s:4:\"text\";s:289:\"وَإِلَىٰ مَدۡیَنَ أَخَاهُمۡ شُعَیۡبࣰا فَقَالَ یَـٰقَوۡمِ ٱعۡبُدُوا۟ ٱللَّهَ وَٱرۡجُوا۟ ٱلۡیَوۡمَ ٱلۡـَٔاخِرَ وَلَا تَعۡثَوۡا۟ فِی ٱلۡأَرۡضِ مُفۡسِدِینَ\n\";s:13:\"numberInSurah\";i:36;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:400;s:4:\"ruku\";i:345;s:11:\"hizbQuarter\";i:160;s:5:\"sajda\";b:0;}i:36;a:9:{s:6:\"number\";i:3377;s:4:\"text\";s:153:\"فَكَذَّبُوهُ فَأَخَذَتۡهُمُ ٱلرَّجۡفَةُ فَأَصۡبَحُوا۟ فِی دَارِهِمۡ جَـٰثِمِینَ\n\";s:13:\"numberInSurah\";i:37;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:400;s:4:\"ruku\";i:345;s:11:\"hizbQuarter\";i:160;s:5:\"sajda\";b:0;}i:37;a:9:{s:6:\"number\";i:3378;s:4:\"text\";s:319:\"وَعَادࣰا وَثَمُودَا۟ وَقَد تَّبَیَّنَ لَكُم مِّن مَّسَـٰكِنِهِمۡۖ وَزَیَّنَ لَهُمُ ٱلشَّیۡطَـٰنُ أَعۡمَـٰلَهُمۡ فَصَدَّهُمۡ عَنِ ٱلسَّبِیلِ وَكَانُوا۟ مُسۡتَبۡصِرِینَ\n\";s:13:\"numberInSurah\";i:38;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:400;s:4:\"ruku\";i:345;s:11:\"hizbQuarter\";i:160;s:5:\"sajda\";b:0;}i:38;a:9:{s:6:\"number\";i:3379;s:4:\"text\";s:271:\"وَقَـٰرُونَ وَفِرۡعَوۡنَ وَهَـٰمَـٰنَۖ وَلَقَدۡ جَاۤءَهُم مُّوسَىٰ بِٱلۡبَیِّنَـٰتِ فَٱسۡتَكۡبَرُوا۟ فِی ٱلۡأَرۡضِ وَمَا كَانُوا۟ سَـٰبِقِینَ\n\";s:13:\"numberInSurah\";i:39;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:401;s:4:\"ruku\";i:345;s:11:\"hizbQuarter\";i:160;s:5:\"sajda\";b:0;}i:39;a:9:{s:6:\"number\";i:3380;s:4:\"text\";s:505:\"فَكُلًّا أَخَذۡنَا بِذَنۢبِهِۦۖ فَمِنۡهُم مَّنۡ أَرۡسَلۡنَا عَلَیۡهِ حَاصِبࣰا وَمِنۡهُم مَّنۡ أَخَذَتۡهُ ٱلصَّیۡحَةُ وَمِنۡهُم مَّنۡ خَسَفۡنَا بِهِ ٱلۡأَرۡضَ وَمِنۡهُم مَّنۡ أَغۡرَقۡنَاۚ وَمَا كَانَ ٱللَّهُ لِیَظۡلِمَهُمۡ وَلَـٰكِن كَانُوۤا۟ أَنفُسَهُمۡ یَظۡلِمُونَ\n\";s:13:\"numberInSurah\";i:40;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:401;s:4:\"ruku\";i:345;s:11:\"hizbQuarter\";i:160;s:5:\"sajda\";b:0;}i:40;a:9:{s:6:\"number\";i:3381;s:4:\"text\";s:344:\"مَثَلُ ٱلَّذِینَ ٱتَّخَذُوا۟ مِن دُونِ ٱللَّهِ أَوۡلِیَاۤءَ كَمَثَلِ ٱلۡعَنكَبُوتِ ٱتَّخَذَتۡ بَیۡتࣰاۖ وَإِنَّ أَوۡهَنَ ٱلۡبُیُوتِ لَبَیۡتُ ٱلۡعَنكَبُوتِۚ لَوۡ كَانُوا۟ یَعۡلَمُونَ\n\";s:13:\"numberInSurah\";i:41;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:401;s:4:\"ruku\";i:345;s:11:\"hizbQuarter\";i:160;s:5:\"sajda\";b:0;}i:41;a:9:{s:6:\"number\";i:3382;s:4:\"text\";s:171:\"إِنَّ ٱللَّهَ یَعۡلَمُ مَا یَدۡعُونَ مِن دُونِهِۦ مِن شَیۡءࣲۚ وَهُوَ ٱلۡعَزِیزُ ٱلۡحَكِیمُ\n\";s:13:\"numberInSurah\";i:42;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:401;s:4:\"ruku\";i:345;s:11:\"hizbQuarter\";i:160;s:5:\"sajda\";b:0;}i:42;a:9:{s:6:\"number\";i:3383;s:4:\"text\";s:166:\"وَتِلۡكَ ٱلۡأَمۡثَـٰلُ نَضۡرِبُهَا لِلنَّاسِۖ وَمَا یَعۡقِلُهَاۤ إِلَّا ٱلۡعَـٰلِمُونَ\n\";s:13:\"numberInSurah\";i:43;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:401;s:4:\"ruku\";i:345;s:11:\"hizbQuarter\";i:160;s:5:\"sajda\";b:0;}i:43;a:9:{s:6:\"number\";i:3384;s:4:\"text\";s:203:\"خَلَقَ ٱللَّهُ ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضَ بِٱلۡحَقِّۚ إِنَّ فِی ذَ ٰ⁠لِكَ لَـَٔایَةࣰ لِّلۡمُؤۡمِنِینَ\n\";s:13:\"numberInSurah\";i:44;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:401;s:4:\"ruku\";i:345;s:11:\"hizbQuarter\";i:160;s:5:\"sajda\";b:0;}i:44;a:9:{s:6:\"number\";i:3385;s:4:\"text\";s:361:\"ٱتۡلُ مَاۤ أُوحِیَ إِلَیۡكَ مِنَ ٱلۡكِتَـٰبِ وَأَقِمِ ٱلصَّلَوٰةَۖ إِنَّ ٱلصَّلَوٰةَ تَنۡهَىٰ عَنِ ٱلۡفَحۡشَاۤءِ وَٱلۡمُنكَرِۗ وَلَذِكۡرُ ٱللَّهِ أَكۡبَرُۗ وَٱللَّهُ یَعۡلَمُ مَا تَصۡنَعُونَ\n\";s:13:\"numberInSurah\";i:45;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:401;s:4:\"ruku\";i:346;s:11:\"hizbQuarter\";i:160;s:5:\"sajda\";b:0;}i:45;a:9:{s:6:\"number\";i:3386;s:4:\"text\";s:473:\"۞ وَلَا تُجَـٰدِلُوۤا۟ أَهۡلَ ٱلۡكِتَـٰبِ إِلَّا بِٱلَّتِی هِیَ أَحۡسَنُ إِلَّا ٱلَّذِینَ ظَلَمُوا۟ مِنۡهُمۡۖ وَقُولُوۤا۟ ءَامَنَّا بِٱلَّذِیۤ أُنزِلَ إِلَیۡنَا وَأُنزِلَ إِلَیۡكُمۡ وَإِلَـٰهُنَا وَإِلَـٰهُكُمۡ وَ ٰ⁠حِدࣱ وَنَحۡنُ لَهُۥ مُسۡلِمُونَ\n\";s:13:\"numberInSurah\";i:46;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:402;s:4:\"ruku\";i:346;s:11:\"hizbQuarter\";i:161;s:5:\"sajda\";b:0;}i:46;a:9:{s:6:\"number\";i:3387;s:4:\"text\";s:387:\"وَكَذَ ٰ⁠لِكَ أَنزَلۡنَاۤ إِلَیۡكَ ٱلۡكِتَـٰبَۚ فَٱلَّذِینَ ءَاتَیۡنَـٰهُمُ ٱلۡكِتَـٰبَ یُؤۡمِنُونَ بِهِۦۖ وَمِنۡ هَـٰۤؤُلَاۤءِ مَن یُؤۡمِنُ بِهِۦۚ وَمَا یَجۡحَدُ بِـَٔایَـٰتِنَاۤ إِلَّا ٱلۡكَـٰفِرُونَ\n\";s:13:\"numberInSurah\";i:47;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:402;s:4:\"ruku\";i:346;s:11:\"hizbQuarter\";i:161;s:5:\"sajda\";b:0;}i:47;a:9:{s:6:\"number\";i:3388;s:4:\"text\";s:213:\"وَمَا كُنتَ تَتۡلُوا۟ مِن قَبۡلِهِۦ مِن كِتَـٰبࣲ وَلَا تَخُطُّهُۥ بِیَمِینِكَۖ إِذࣰا لَّٱرۡتَابَ ٱلۡمُبۡطِلُونَ\n\";s:13:\"numberInSurah\";i:48;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:402;s:4:\"ruku\";i:346;s:11:\"hizbQuarter\";i:161;s:5:\"sajda\";b:0;}i:48;a:9:{s:6:\"number\";i:3389;s:4:\"text\";s:245:\"بَلۡ هُوَ ءَایَـٰتُۢ بَیِّنَـٰتࣱ فِی صُدُورِ ٱلَّذِینَ أُوتُوا۟ ٱلۡعِلۡمَۚ وَمَا یَجۡحَدُ بِـَٔایَـٰتِنَاۤ إِلَّا ٱلظَّـٰلِمُونَ\n\";s:13:\"numberInSurah\";i:49;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:402;s:4:\"ruku\";i:346;s:11:\"hizbQuarter\";i:161;s:5:\"sajda\";b:0;}i:49;a:9:{s:6:\"number\";i:3390;s:4:\"text\";s:268:\"وَقَالُوا۟ لَوۡلَاۤ أُنزِلَ عَلَیۡهِ ءَایَـٰتࣱ مِّن رَّبِّهِۦۚ قُلۡ إِنَّمَا ٱلۡـَٔایَـٰتُ عِندَ ٱللَّهِ وَإِنَّمَاۤ أَنَا۠ نَذِیرࣱ مُّبِینٌ\n\";s:13:\"numberInSurah\";i:50;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:402;s:4:\"ruku\";i:346;s:11:\"hizbQuarter\";i:161;s:5:\"sajda\";b:0;}i:50;a:9:{s:6:\"number\";i:3391;s:4:\"text\";s:277:\"أَوَلَمۡ یَكۡفِهِمۡ أَنَّاۤ أَنزَلۡنَا عَلَیۡكَ ٱلۡكِتَـٰبَ یُتۡلَىٰ عَلَیۡهِمۡۚ إِنَّ فِی ذَ ٰ⁠لِكَ لَرَحۡمَةࣰ وَذِكۡرَىٰ لِقَوۡمࣲ یُؤۡمِنُونَ\n\";s:13:\"numberInSurah\";i:51;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:402;s:4:\"ruku\";i:346;s:11:\"hizbQuarter\";i:161;s:5:\"sajda\";b:0;}i:51;a:9:{s:6:\"number\";i:3392;s:4:\"text\";s:372:\"قُلۡ كَفَىٰ بِٱللَّهِ بَیۡنِی وَبَیۡنَكُمۡ شَهِیدࣰاۖ یَعۡلَمُ مَا فِی ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِۗ وَٱلَّذِینَ ءَامَنُوا۟ بِٱلۡبَـٰطِلِ وَكَفَرُوا۟ بِٱللَّهِ أُو۟لَـٰۤىِٕكَ هُمُ ٱلۡخَـٰسِرُونَ\n\";s:13:\"numberInSurah\";i:52;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:402;s:4:\"ruku\";i:347;s:11:\"hizbQuarter\";i:161;s:5:\"sajda\";b:0;}i:52;a:9:{s:6:\"number\";i:3393;s:4:\"text\";s:267:\"وَیَسۡتَعۡجِلُونَكَ بِٱلۡعَذَابِ وَلَوۡلَاۤ أَجَلࣱ مُّسَمࣰّى لَّجَاۤءَهُمُ ٱلۡعَذَابُۚ وَلَیَأۡتِیَنَّهُم بَغۡتَةࣰ وَهُمۡ لَا یَشۡعُرُونَ\n\";s:13:\"numberInSurah\";i:53;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:403;s:4:\"ruku\";i:347;s:11:\"hizbQuarter\";i:161;s:5:\"sajda\";b:0;}i:53;a:9:{s:6:\"number\";i:3394;s:4:\"text\";s:152:\"یَسۡتَعۡجِلُونَكَ بِٱلۡعَذَابِ وَإِنَّ جَهَنَّمَ لَمُحِیطَةُۢ بِٱلۡكَـٰفِرِینَ\n\";s:13:\"numberInSurah\";i:54;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:403;s:4:\"ruku\";i:347;s:11:\"hizbQuarter\";i:161;s:5:\"sajda\";b:0;}i:54;a:9:{s:6:\"number\";i:3395;s:4:\"text\";s:217:\"یَوۡمَ یَغۡشَىٰهُمُ ٱلۡعَذَابُ مِن فَوۡقِهِمۡ وَمِن تَحۡتِ أَرۡجُلِهِمۡ وَیَقُولُ ذُوقُوا۟ مَا كُنتُمۡ تَعۡمَلُونَ\n\";s:13:\"numberInSurah\";i:55;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:403;s:4:\"ruku\";i:347;s:11:\"hizbQuarter\";i:161;s:5:\"sajda\";b:0;}i:55;a:9:{s:6:\"number\";i:3396;s:4:\"text\";s:169:\"یَـٰعِبَادِیَ ٱلَّذِینَ ءَامَنُوۤا۟ إِنَّ أَرۡضِی وَ ٰ⁠سِعَةࣱ فَإِیَّـٰیَ فَٱعۡبُدُونِ\n\";s:13:\"numberInSurah\";i:56;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:403;s:4:\"ruku\";i:347;s:11:\"hizbQuarter\";i:161;s:5:\"sajda\";b:0;}i:56;a:9:{s:6:\"number\";i:3397;s:4:\"text\";s:122:\"كُلُّ نَفۡسࣲ ذَاۤىِٕقَةُ ٱلۡمَوۡتِۖ ثُمَّ إِلَیۡنَا تُرۡجَعُونَ\n\";s:13:\"numberInSurah\";i:57;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:403;s:4:\"ruku\";i:347;s:11:\"hizbQuarter\";i:161;s:5:\"sajda\";b:0;}i:57;a:9:{s:6:\"number\";i:3398;s:4:\"text\";s:342:\"وَٱلَّذِینَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ لَنُبَوِّئَنَّهُم مِّنَ ٱلۡجَنَّةِ غُرَفࣰا تَجۡرِی مِن تَحۡتِهَا ٱلۡأَنۡهَـٰرُ خَـٰلِدِینَ فِیهَاۚ نِعۡمَ أَجۡرُ ٱلۡعَـٰمِلِینَ\n\";s:13:\"numberInSurah\";i:58;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:403;s:4:\"ruku\";i:347;s:11:\"hizbQuarter\";i:161;s:5:\"sajda\";b:0;}i:58;a:9:{s:6:\"number\";i:3399;s:4:\"text\";s:103:\"ٱلَّذِینَ صَبَرُوا۟ وَعَلَىٰ رَبِّهِمۡ یَتَوَكَّلُونَ\n\";s:13:\"numberInSurah\";i:59;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:403;s:4:\"ruku\";i:347;s:11:\"hizbQuarter\";i:161;s:5:\"sajda\";b:0;}i:59;a:9:{s:6:\"number\";i:3400;s:4:\"text\";s:215:\"وَكَأَیِّن مِّن دَاۤبَّةࣲ لَّا تَحۡمِلُ رِزۡقَهَا ٱللَّهُ یَرۡزُقُهَا وَإِیَّاكُمۡۚ وَهُوَ ٱلسَّمِیعُ ٱلۡعَلِیمُ\n\";s:13:\"numberInSurah\";i:60;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:403;s:4:\"ruku\";i:347;s:11:\"hizbQuarter\";i:161;s:5:\"sajda\";b:0;}i:60;a:9:{s:6:\"number\";i:3401;s:4:\"text\";s:267:\"وَلَىِٕن سَأَلۡتَهُم مَّنۡ خَلَقَ ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضَ وَسَخَّرَ ٱلشَّمۡسَ وَٱلۡقَمَرَ لَیَقُولُنَّ ٱللَّهُۖ فَأَنَّىٰ یُؤۡفَكُونَ\n\";s:13:\"numberInSurah\";i:61;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:403;s:4:\"ruku\";i:347;s:11:\"hizbQuarter\";i:161;s:5:\"sajda\";b:0;}i:61;a:9:{s:6:\"number\";i:3402;s:4:\"text\";s:215:\"ٱللَّهُ یَبۡسُطُ ٱلرِّزۡقَ لِمَن یَشَاۤءُ مِنۡ عِبَادِهِۦ وَیَقۡدِرُ لَهُۥۤۚ إِنَّ ٱللَّهَ بِكُلِّ شَیۡءٍ عَلِیمࣱ\n\";s:13:\"numberInSurah\";i:62;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:403;s:4:\"ruku\";i:347;s:11:\"hizbQuarter\";i:161;s:5:\"sajda\";b:0;}i:62;a:9:{s:6:\"number\";i:3403;s:4:\"text\";s:351:\"وَلَىِٕن سَأَلۡتَهُم مَّن نَّزَّلَ مِنَ ٱلسَّمَاۤءِ مَاۤءࣰ فَأَحۡیَا بِهِ ٱلۡأَرۡضَ مِنۢ بَعۡدِ مَوۡتِهَا لَیَقُولُنَّ ٱللَّهُۚ قُلِ ٱلۡحَمۡدُ لِلَّهِۚ بَلۡ أَكۡثَرُهُمۡ لَا یَعۡقِلُونَ\n\";s:13:\"numberInSurah\";i:63;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:403;s:4:\"ruku\";i:347;s:11:\"hizbQuarter\";i:161;s:5:\"sajda\";b:0;}i:63;a:9:{s:6:\"number\";i:3404;s:4:\"text\";s:269:\"وَمَا هَـٰذِهِ ٱلۡحَیَوٰةُ ٱلدُّنۡیَاۤ إِلَّا لَهۡوࣱ وَلَعِبࣱۚ وَإِنَّ ٱلدَّارَ ٱلۡـَٔاخِرَةَ لَهِیَ ٱلۡحَیَوَانُۚ لَوۡ كَانُوا۟ یَعۡلَمُونَ\n\";s:13:\"numberInSurah\";i:64;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:404;s:4:\"ruku\";i:348;s:11:\"hizbQuarter\";i:161;s:5:\"sajda\";b:0;}i:64;a:9:{s:6:\"number\";i:3405;s:4:\"text\";s:252:\"فَإِذَا رَكِبُوا۟ فِی ٱلۡفُلۡكِ دَعَوُا۟ ٱللَّهَ مُخۡلِصِینَ لَهُ ٱلدِّینَ فَلَمَّا نَجَّىٰهُمۡ إِلَى ٱلۡبَرِّ إِذَا هُمۡ یُشۡرِكُونَ\n\";s:13:\"numberInSurah\";i:65;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:404;s:4:\"ruku\";i:348;s:11:\"hizbQuarter\";i:161;s:5:\"sajda\";b:0;}i:65;a:9:{s:6:\"number\";i:3406;s:4:\"text\";s:150:\"لِیَكۡفُرُوا۟ بِمَاۤ ءَاتَیۡنَـٰهُمۡ وَلِیَتَمَتَّعُوا۟ۚ فَسَوۡفَ یَعۡلَمُونَ\n\";s:13:\"numberInSurah\";i:66;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:404;s:4:\"ruku\";i:348;s:11:\"hizbQuarter\";i:161;s:5:\"sajda\";b:0;}i:66;a:9:{s:6:\"number\";i:3407;s:4:\"text\";s:296:\"أَوَلَمۡ یَرَوۡا۟ أَنَّا جَعَلۡنَا حَرَمًا ءَامِنࣰا وَیُتَخَطَّفُ ٱلنَّاسُ مِنۡ حَوۡلِهِمۡۚ أَفَبِٱلۡبَـٰطِلِ یُؤۡمِنُونَ وَبِنِعۡمَةِ ٱللَّهِ یَكۡفُرُونَ\n\";s:13:\"numberInSurah\";i:67;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:404;s:4:\"ruku\";i:348;s:11:\"hizbQuarter\";i:161;s:5:\"sajda\";b:0;}i:67;a:9:{s:6:\"number\";i:3408;s:4:\"text\";s:278:\"وَمَنۡ أَظۡلَمُ مِمَّنِ ٱفۡتَرَىٰ عَلَى ٱللَّهِ كَذِبًا أَوۡ كَذَّبَ بِٱلۡحَقِّ لَمَّا جَاۤءَهُۥۤۚ أَلَیۡسَ فِی جَهَنَّمَ مَثۡوࣰى لِّلۡكَـٰفِرِینَ\n\";s:13:\"numberInSurah\";i:68;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:404;s:4:\"ruku\";i:348;s:11:\"hizbQuarter\";i:161;s:5:\"sajda\";b:0;}i:68;a:9:{s:6:\"number\";i:3409;s:4:\"text\";s:187:\"وَٱلَّذِینَ جَـٰهَدُوا۟ فِینَا لَنَهۡدِیَنَّهُمۡ سُبُلَنَاۚ وَإِنَّ ٱللَّهَ لَمَعَ ٱلۡمُحۡسِنِینَ\n\";s:13:\"numberInSurah\";i:69;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:404;s:4:\"ruku\";i:348;s:11:\"hizbQuarter\";i:161;s:5:\"sajda\";b:0;}}s:7:\"edition\";a:7:{s:10:\"identifier\";s:27:\"quran-uthmani-quran-academy\";s:8:\"language\";s:2:\"ar\";s:4:\"name\";s:67:\"القرآن الكريم برسم العثماني (quran-academy)\";s:11:\"englishName\";s:78:\"Modified Quran Uthmani Text from the Quran Academy to work with the Kitab font\";s:6:\"format\";s:4:\"text\";s:4:\"type\";s:5:\"quran\";s:9:\"direction\";s:3:\"rtl\";}}', 1794581363),
('quranapp-cache-surah_29_fr.hamidullah', 'a:8:{s:6:\"number\";i:29;s:4:\"name\";s:39:\"سُورَةُ العَنكَبُوتِ\";s:11:\"englishName\";s:11:\"Al-Ankaboot\";s:22:\"englishNameTranslation\";s:10:\"The Spider\";s:14:\"revelationType\";s:6:\"Meccan\";s:13:\"numberOfAyahs\";i:69;s:5:\"ayahs\";a:69:{i:0;a:9:{s:6:\"number\";i:3341;s:4:\"text\";s:17:\"Alif, Lâm, Mîm.\";s:13:\"numberInSurah\";i:1;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:396;s:4:\"ruku\";i:342;s:11:\"hizbQuarter\";i:159;s:5:\"sajda\";b:0;}i:1;a:9:{s:6:\"number\";i:3342;s:4:\"text\";s:90:\"Est-ce que les gens pensent qu\'on les laissera dire: «Nous croyons!» sans les éprouver?\";s:13:\"numberInSurah\";i:2;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:396;s:4:\"ruku\";i:342;s:11:\"hizbQuarter\";i:159;s:5:\"sajda\";b:0;}i:2;a:9:{s:6:\"number\";i:3343;s:4:\"text\";s:130:\"Certes, Nous avons éprouvé ceux qui ont vécu avant eux; [Ainsi] Allah connaît ceux qui disent la vérité et ceux qui mentent.\";s:13:\"numberInSurah\";i:3;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:396;s:4:\"ruku\";i:342;s:11:\"hizbQuarter\";i:159;s:5:\"sajda\";b:0;}i:3;a:9:{s:6:\"number\";i:3344;s:4:\"text\";s:111:\"Ou bien ceux qui commettent des méfaits, comptent-ils pouvoir Nous échapper? Comme leur jugement est mauvais!\";s:13:\"numberInSurah\";i:4;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:396;s:4:\"ruku\";i:342;s:11:\"hizbQuarter\";i:159;s:5:\"sajda\";b:0;}i:4;a:9:{s:6:\"number\";i:3345;s:4:\"text\";s:121:\"Celui qui espère rencontrer Allah, le terme fixé par Allah va certainement venir. Et c\'est Lui l\'Audient, l\'Omniscient.\";s:13:\"numberInSurah\";i:5;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:396;s:4:\"ruku\";i:342;s:11:\"hizbQuarter\";i:159;s:5:\"sajda\";b:0;}i:5;a:9:{s:6:\"number\";i:3346;s:4:\"text\";s:92:\"Et quiconque lutte, ne lutte que pour lui-même, car Allah peut Se passer de tout l\'univers.\";s:13:\"numberInSurah\";i:6;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:396;s:4:\"ruku\";i:342;s:11:\"hizbQuarter\";i:159;s:5:\"sajda\";b:0;}i:6;a:9:{s:6:\"number\";i:3347;s:4:\"text\";s:178:\"Et quant à ceux qui croient et font de bonnes œuvres, Nous leur effacerons leurs méfaits, et Nous les rétribuerons de la meilleure récompense pour ce qu\'ils auront accompli.\";s:13:\"numberInSurah\";i:7;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:397;s:4:\"ruku\";i:342;s:11:\"hizbQuarter\";i:159;s:5:\"sajda\";b:0;}i:7;a:9:{s:6:\"number\";i:3348;s:4:\"text\";s:247:\"Et Nous avons enjoint à l\'homme de bien traiter ses père et mère, et «si ceux-ci te forcent à M\'associer, ce dont tu n\'as aucun savoir, alors ne leur obéis pas». Vers Moi est votre retour, et alors Je vous informerai de ce que vous faisiez.\";s:13:\"numberInSurah\";i:8;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:397;s:4:\"ruku\";i:342;s:11:\"hizbQuarter\";i:159;s:5:\"sajda\";b:0;}i:8;a:9:{s:6:\"number\";i:3349;s:4:\"text\";s:115:\"Et quant à ceux qui croient et font de bonnes œuvres, Nous les ferons certainement entrer parmi les gens de bien.\";s:13:\"numberInSurah\";i:9;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:397;s:4:\"ruku\";i:342;s:11:\"hizbQuarter\";i:159;s:5:\"sajda\";b:0;}i:9;a:9:{s:6:\"number\";i:3350;s:4:\"text\";s:375:\"Parmi les gens il en est qui disent: «Nous croyons en Allah» puis, si on les fait souffrir pour la cause d\'Allah, ils considèrent l\'épreuve de la part des hommes comme un châtiment d\'Allah. Or, s\'il vient du secours de ton Seigneur, ils diront certes: «Nous étions avec vous!» Allah n\'est-Il pas le meilleur à savoir ce qu\'il y a dans les poitrines de tout le monde?\";s:13:\"numberInSurah\";i:10;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:397;s:4:\"ruku\";i:342;s:11:\"hizbQuarter\";i:159;s:5:\"sajda\";b:0;}i:10;a:9:{s:6:\"number\";i:3351;s:4:\"text\";s:81:\"Allah connaît parfaitement les croyants et connaît parfaitement les hypocrites.\";s:13:\"numberInSurah\";i:11;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:397;s:4:\"ruku\";i:342;s:11:\"hizbQuarter\";i:159;s:5:\"sajda\";b:0;}i:11;a:9:{s:6:\"number\";i:3352;s:4:\"text\";s:197:\"Et ceux qui ne croient pas disent à ceux qui croient; «Suivez notre sentier, et que nous supportions vos fautes». Mais ils ne supporteront rien de leurs fautes. En vérité ce sont des menteurs.\";s:13:\"numberInSurah\";i:12;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:397;s:4:\"ruku\";i:342;s:11:\"hizbQuarter\";i:159;s:5:\"sajda\";b:0;}i:12;a:9:{s:6:\"number\";i:3353;s:4:\"text\";s:190:\"Et très certainement, ils porteront leurs fardeaux et d\'autres fardeaux en plus de leurs propres fardeaux. et ils seront interrogés, le Jour de la Résurrection, sur ce qu\'ils inventaient.\";s:13:\"numberInSurah\";i:13;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:397;s:4:\"ruku\";i:342;s:11:\"hizbQuarter\";i:159;s:5:\"sajda\";b:0;}i:13;a:9:{s:6:\"number\";i:3354;s:4:\"text\";s:169:\"Et en effet, Nous avons envoyé Noé vers son peuple. Il demeura parmi eux mille ans moins cinquante années. Puis le déluge les emporta alors qu\'ils étaient injustes.\";s:13:\"numberInSurah\";i:14;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:397;s:4:\"ruku\";i:343;s:11:\"hizbQuarter\";i:159;s:5:\"sajda\";b:0;}i:14;a:9:{s:6:\"number\";i:3355;s:4:\"text\";s:102:\"Puis Nous le sauvâmes, lui et les gens de l\'arche; et Nous en fîmes un avertissement pour l\'univers.\";s:13:\"numberInSurah\";i:15;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:398;s:4:\"ruku\";i:343;s:11:\"hizbQuarter\";i:159;s:5:\"sajda\";b:0;}i:15;a:9:{s:6:\"number\";i:3356;s:4:\"text\";s:116:\"Et Abraham, quand il dit à son peuple; «Adorez Allah et craignez-Le: cela vous est bien meilleur si vous saviez».\";s:13:\"numberInSurah\";i:16;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:398;s:4:\"ruku\";i:343;s:11:\"hizbQuarter\";i:159;s:5:\"sajda\";b:0;}i:16;a:9:{s:6:\"number\";i:3357;s:4:\"text\";s:295:\"Vous n\'adorez que des idoles, en dehors d\'Allah, et vous forgez un mensonge. Ceux que vous adorez en dehors d\'Allah ne possèdent aucun moyen pour vous procurer nourriture; recherchez votre subsistance auprès d\'Allah. Adorez-Le et soyez-Lui reconnaissants. C\'est à Lui que vous serez ramenés.\";s:13:\"numberInSurah\";i:17;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:398;s:4:\"ruku\";i:343;s:11:\"hizbQuarter\";i:159;s:5:\"sajda\";b:0;}i:17;a:9:{s:6:\"number\";i:3358;s:4:\"text\";s:170:\"Et si vous criez au mensonge, d\'autres nations avant vous, ont aussi traité (leurs prophètes) de menteurs. Au Messager, cependant, n\'incombe que la transmission claire.\";s:13:\"numberInSurah\";i:18;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:398;s:4:\"ruku\";i:343;s:11:\"hizbQuarter\";i:159;s:5:\"sajda\";b:0;}i:18;a:9:{s:6:\"number\";i:3359;s:4:\"text\";s:97:\"Ne voient-ils pas comment Allah commence la création puis la refait? Cela est facile pour Allah.\";s:13:\"numberInSurah\";i:19;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:398;s:4:\"ruku\";i:343;s:11:\"hizbQuarter\";i:159;s:5:\"sajda\";b:0;}i:19;a:9:{s:6:\"number\";i:3360;s:4:\"text\";s:148:\"Dis: «Parcourez la terre et voyez comment Il a commencé la création. Puis comment Allah crée la génération ultime. Car Allah est Omnipotent».\";s:13:\"numberInSurah\";i:20;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:398;s:4:\"ruku\";i:343;s:11:\"hizbQuarter\";i:159;s:5:\"sajda\";b:0;}i:20;a:9:{s:6:\"number\";i:3361;s:4:\"text\";s:102:\"Il châtie qui Il veut et fait miséricorde à qui Il veut; et c\'est vers Lui que vous serez ramenés.\";s:13:\"numberInSurah\";i:21;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:398;s:4:\"ruku\";i:343;s:11:\"hizbQuarter\";i:159;s:5:\"sajda\";b:0;}i:21;a:9:{s:6:\"number\";i:3362;s:4:\"text\";s:143:\"Et vous ne pourrez vous opposer à Sa puissance ni sur terre, ni au ciel; et il n\'y a pas pour vous, en dehors d\'Allah, ni allié ni secoureur.\";s:13:\"numberInSurah\";i:22;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:398;s:4:\"ruku\";i:343;s:11:\"hizbQuarter\";i:159;s:5:\"sajda\";b:0;}i:22;a:9:{s:6:\"number\";i:3363;s:4:\"text\";s:145:\"Et ceux qui ne croient pas aux versets d\'Allah et à Sa rencontre, désespèrent de Ma miséricorde. Et ceux-là auront un châtiment douloureux.\";s:13:\"numberInSurah\";i:23;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:398;s:4:\"ruku\";i:344;s:11:\"hizbQuarter\";i:159;s:5:\"sajda\";b:0;}i:23;a:9:{s:6:\"number\";i:3364;s:4:\"text\";s:147:\"Son peuple ne fit d\'autre réponse que: «tuez-le ou brûlez-le». Mais Allah le sauva du feu. C\'est bien là des signes pour des gens qui croient.\";s:13:\"numberInSurah\";i:24;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:399;s:4:\"ruku\";i:344;s:11:\"hizbQuarter\";i:159;s:5:\"sajda\";b:0;}i:24;a:9:{s:6:\"number\";i:3365;s:4:\"text\";s:326:\"Et [Abraham] dit: «En effet, c\'est pour cimenter des liens entre vous-mêmes dans la vie présente, que vous avez adopté des idoles, en dehors d\'Allah. Ensuite, le Jour de la Résurrection, les uns rejetteront les autres, et les uns maudiront les autres, tandis que vous aurez le Feu pour refuge, n\'aurez pas de protecteurs.\";s:13:\"numberInSurah\";i:25;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:399;s:4:\"ruku\";i:344;s:11:\"hizbQuarter\";i:159;s:5:\"sajda\";b:0;}i:25;a:9:{s:6:\"number\";i:3366;s:4:\"text\";s:103:\"Lot crut en lui. Il dit: «Moi, j\'émigre vers mon Seigneur, car c\'est Lui le Tout Puissant, le Sage».\";s:13:\"numberInSurah\";i:26;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:399;s:4:\"ruku\";i:344;s:11:\"hizbQuarter\";i:160;s:5:\"sajda\";b:0;}i:26;a:9:{s:6:\"number\";i:3367;s:4:\"text\";s:200:\"Nous lui donnâmes Isaac et Jacob, et plaçâmes dans sa descendance la prophétie et le Livre. Nous lui accordâmes sa récompense ici-bas, tandis que dans l\'au-delà, il sera parmi les gens de bien.\";s:13:\"numberInSurah\";i:27;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:399;s:4:\"ruku\";i:344;s:11:\"hizbQuarter\";i:160;s:5:\"sajda\";b:0;}i:27;a:9:{s:6:\"number\";i:3368;s:4:\"text\";s:121:\"Et Lot, quand il dit à son peuple: «Vraiment, vous commettez la turpitude où nul dans l\'univers ne vous a précédés.\";s:13:\"numberInSurah\";i:28;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:399;s:4:\"ruku\";i:344;s:11:\"hizbQuarter\";i:160;s:5:\"sajda\";b:0;}i:28;a:9:{s:6:\"number\";i:3369;s:4:\"text\";s:259:\"Aurez-vous commerce charnel avec des mâles? Pratiquerez-vous le brigandage? Commettrez-vous le blâmable dans votre assemblée?» Mais son peuple ne fit d\'autre réponse que: «Fais que le châtiment d\'Allah nous vienne, si tu es du nombre des véridiques».\";s:13:\"numberInSurah\";i:29;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:399;s:4:\"ruku\";i:344;s:11:\"hizbQuarter\";i:160;s:5:\"sajda\";b:0;}i:29;a:9:{s:6:\"number\";i:3370;s:4:\"text\";s:70:\"Il dit: «Seigneur, donne-moi victoire sur ce peuple de corrupteurs!»\";s:13:\"numberInSurah\";i:30;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:399;s:4:\"ruku\";i:344;s:11:\"hizbQuarter\";i:160;s:5:\"sajda\";b:0;}i:30;a:9:{s:6:\"number\";i:3371;s:4:\"text\";s:160:\"Et quand Nos Anges apportèrent à Abraham la bonne annonce, ils dirent: «Nous allons anéantir les habitants de cette cité car ses habitants sont injustes».\";s:13:\"numberInSurah\";i:31;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:400;s:4:\"ruku\";i:345;s:11:\"hizbQuarter\";i:160;s:5:\"sajda\";b:0;}i:31;a:9:{s:6:\"number\";i:3372;s:4:\"text\";s:191:\"Il dit: «Mais Lot s\'y trouve!» Ils dirent: «Nous savons parfaitement qui y habite: nous le sauverons certainement, lui et sa famille, excepté sa femme qui sera parmi ceux qui périront».\";s:13:\"numberInSurah\";i:32;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:400;s:4:\"ruku\";i:345;s:11:\"hizbQuarter\";i:160;s:5:\"sajda\";b:0;}i:32;a:9:{s:6:\"number\";i:3373;s:4:\"text\";s:250:\"Et quand Nos Anges vinrent à Lot, il fut affligé pour eux, et se sentit incapable de les protéger. Ils lui dirent: «Ne crains rien et ne t\'afflige pas... Nous te sauverons ainsi que ta famille, excepté ta femme qui sera parmi ceux qui périront.\";s:13:\"numberInSurah\";i:33;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:400;s:4:\"ruku\";i:345;s:11:\"hizbQuarter\";i:160;s:5:\"sajda\";b:0;}i:33;a:9:{s:6:\"number\";i:3374;s:4:\"text\";s:99:\"Nous ferons tomber du ciel un châtiment sur les habitants de cette cité, pour leur perversité».\";s:13:\"numberInSurah\";i:34;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:400;s:4:\"ruku\";i:345;s:11:\"hizbQuarter\";i:160;s:5:\"sajda\";b:0;}i:34;a:9:{s:6:\"number\";i:3375;s:4:\"text\";s:130:\"Et certainement, Nous avons laissé (des ruines de cette cité) un signe (d\'avertissement) évident pour des gens qui comprennent.\";s:13:\"numberInSurah\";i:35;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:400;s:4:\"ruku\";i:345;s:11:\"hizbQuarter\";i:160;s:5:\"sajda\";b:0;}i:35;a:9:{s:6:\"number\";i:3376;s:4:\"text\";s:177:\"De même, aux Madyan (Nous envoyâmes) leur frère Chuayb qui leur dit: «O mon peuple, adorez Allah et attendez-vous au Jour dernier, et ne semez pas la corruption sur terre».\";s:13:\"numberInSurah\";i:36;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:400;s:4:\"ruku\";i:345;s:11:\"hizbQuarter\";i:160;s:5:\"sajda\";b:0;}i:36;a:9:{s:6:\"number\";i:3377;s:4:\"text\";s:117:\"Mais ils le traitèrent de menteur. Le cataclysme les saisit, et au matin, ils gisaient sans vie dans leurs demeures.\";s:13:\"numberInSurah\";i:37;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:400;s:4:\"ruku\";i:345;s:11:\"hizbQuarter\";i:160;s:5:\"sajda\";b:0;}i:37;a:9:{s:6:\"number\";i:3378;s:4:\"text\";s:264:\"De même (Nous anéantîmes) les \'Aad et les Thamûd. - Vous le voyez clairement à travers leurs habitations - Le Diable, cependant, leur avait embelli leurs actions, au point de les repousser loin du Sentier; ils étaient pourtant invités à être clairvoyants.\";s:13:\"numberInSurah\";i:38;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:400;s:4:\"ruku\";i:345;s:11:\"hizbQuarter\";i:160;s:5:\"sajda\";b:0;}i:38;a:9:{s:6:\"number\";i:3379;s:4:\"text\";s:170:\"De même (Nous détruisîmes) Coré, Pharaon et Hâmân. Alors que Moïse leur apporta des preuves, ils s\'enorgueillirent sur terre. Et ils n\'ont pas pu [Nous] échapper.\";s:13:\"numberInSurah\";i:39;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:401;s:4:\"ruku\";i:345;s:11:\"hizbQuarter\";i:160;s:5:\"sajda\";b:0;}i:39;a:9:{s:6:\"number\";i:3380;s:4:\"text\";s:304:\"Nous saisîmes donc chacun pour son péché: Il y en eut sur qui Nous envoyâmes un ouragan; il y en eut que le Cri saisit; il y en eut que Nous fîmes engloutir par la terre; et il y en eut que Nous noyâmes. Cependant, Allah n\'est pas tel à leur faire du tort; mais ils ont fait du tort à eux-mêmes.\";s:13:\"numberInSurah\";i:40;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:401;s:4:\"ruku\";i:345;s:11:\"hizbQuarter\";i:160;s:5:\"sajda\";b:0;}i:40;a:9:{s:6:\"number\";i:3381;s:4:\"text\";s:186:\"Ceux qui ont pris des protecteurs en dehors d\'Allah ressemblent à l\'araignée qui s\'est donnée maison. Or la maison la plus fragile est celle de l\'araignée. Si seulement ils savaient!\";s:13:\"numberInSurah\";i:41;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:401;s:4:\"ruku\";i:345;s:11:\"hizbQuarter\";i:160;s:5:\"sajda\";b:0;}i:41;a:9:{s:6:\"number\";i:3382;s:4:\"text\";s:101:\"Allah connaît toute chose qu\'ils invoquent en dehors de Lui. Et c\'est Lui le Tout Puissant, le Sage.\";s:13:\"numberInSurah\";i:42;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:401;s:4:\"ruku\";i:345;s:11:\"hizbQuarter\";i:160;s:5:\"sajda\";b:0;}i:42;a:9:{s:6:\"number\";i:3383;s:4:\"text\";s:97:\"Telles sont les paraboles que Nous citons aux gens; cependant, seuls les savants les comprennent.\";s:13:\"numberInSurah\";i:43;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:401;s:4:\"ruku\";i:345;s:11:\"hizbQuarter\";i:160;s:5:\"sajda\";b:0;}i:43;a:9:{s:6:\"number\";i:3384;s:4:\"text\";s:114:\"C\'est pour une juste raison qu\'Allah a créé les cieux et la terre. Voilà bien là une preuve pour les croyants.\";s:13:\"numberInSurah\";i:44;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:401;s:4:\"ruku\";i:345;s:11:\"hizbQuarter\";i:160;s:5:\"sajda\";b:0;}i:44;a:9:{s:6:\"number\";i:3385;s:4:\"text\";s:219:\"Récite ce qui t\'est révélé du Livre et accomplis la Salât. En vérité la Salât préserve de la turpitude et du blâmable. Le rappel d\'Allah est certes ce qu\'il y a de plus grand. Et Allah sait ce que vous faites.\";s:13:\"numberInSurah\";i:45;s:3:\"juz\";i:20;s:6:\"manzil\";i:5;s:4:\"page\";i:401;s:4:\"ruku\";i:346;s:11:\"hizbQuarter\";i:160;s:5:\"sajda\";b:0;}i:45;a:9:{s:6:\"number\";i:3386;s:4:\"text\";s:288:\"Et ne discutez que de la meilleure façon avec les gens du Livre, sauf ceux d\'entre eux qui sont injustes. Et dites: «Nous croyons en ce qu\'on a fait descendre vers nous et descendre vers vous, tandis que notre Dieu et votre Dieu est le même, et c\'est à Lui que nous nous soumettons».\";s:13:\"numberInSurah\";i:46;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:402;s:4:\"ruku\";i:346;s:11:\"hizbQuarter\";i:161;s:5:\"sajda\";b:0;}i:46;a:9:{s:6:\"number\";i:3387;s:4:\"text\";s:200:\"C\'est ainsi que Nous t\'avons fait descendre le Livre (le Coran). Ceux à qui Nous avons donné le Livre y croient. Et parmi ceux-ci, il en est qui y croient. Seuls les mécréants renient Nos versets.\";s:13:\"numberInSurah\";i:47;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:402;s:4:\"ruku\";i:346;s:11:\"hizbQuarter\";i:161;s:5:\"sajda\";b:0;}i:47;a:9:{s:6:\"number\";i:3388;s:4:\"text\";s:146:\"Et avant cela, tu ne récitais aucun livre et tu n\'en écrivais aucun de ta main droite. Sinon, ceux qui nient la vérité auraient eu des doutes.\";s:13:\"numberInSurah\";i:48;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:402;s:4:\"ruku\";i:346;s:11:\"hizbQuarter\";i:161;s:5:\"sajda\";b:0;}i:48;a:9:{s:6:\"number\";i:3389;s:4:\"text\";s:162:\"Il consiste plutôt en des versets évidents, (préservés) dans les poitrines de ceux à qui le savoir a été donné. Et seuls les injustes renient Nos versets.\";s:13:\"numberInSurah\";i:49;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:402;s:4:\"ruku\";i:346;s:11:\"hizbQuarter\";i:161;s:5:\"sajda\";b:0;}i:49;a:9:{s:6:\"number\";i:3390;s:4:\"text\";s:194:\"Et ils dirent: «Pourquoi n\'a-t-on pas fait descendre sur lui des prodiges de la part de son Seigneur?» Dis: «Les prodiges sont auprès d\'Allah. Moi, je ne suis qu\'un avertisseur bien clair».\";s:13:\"numberInSurah\";i:50;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:402;s:4:\"ruku\";i:346;s:11:\"hizbQuarter\";i:161;s:5:\"sajda\";b:0;}i:50;a:9:{s:6:\"number\";i:3391;s:4:\"text\";s:184:\"Ne leur suffit-il donc point que Nous ayons fait descendre sur toi le Livre et qu\'il leur soit récité? Il y a assurément là une miséricorde et un rappel pour des gens qui croient.\";s:13:\"numberInSurah\";i:51;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:402;s:4:\"ruku\";i:346;s:11:\"hizbQuarter\";i:161;s:5:\"sajda\";b:0;}i:51;a:9:{s:6:\"number\";i:3392;s:4:\"text\";s:196:\"Dis: «Allah suffit comme témoin entre moi et vous». Il sait ce qui est dans les cieux et la terre. Et quant à ceux qui croient au faux et ne croient pas en Allah, ceux-là seront les perdants.\";s:13:\"numberInSurah\";i:52;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:402;s:4:\"ruku\";i:347;s:11:\"hizbQuarter\";i:161;s:5:\"sajda\";b:0;}i:52;a:9:{s:6:\"number\";i:3393;s:4:\"text\";s:206:\"Et ils te demandent de hâter [la venue] du châtiment. S\'il n\'y avait pas eu un terme fixé, le châtiment leur serait certes venu. Et assurément, il leur viendra soudain, sans qu\'ils en aient conscience.\";s:13:\"numberInSurah\";i:53;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:403;s:4:\"ruku\";i:347;s:11:\"hizbQuarter\";i:161;s:5:\"sajda\";b:0;}i:53;a:9:{s:6:\"number\";i:3394;s:4:\"text\";s:110:\"Ils te demandent de hâter [la venue] du châtiment, tandis que l\'Enfer cerne les mécréants de toutes parts.\";s:13:\"numberInSurah\";i:54;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:403;s:4:\"ruku\";i:347;s:11:\"hizbQuarter\";i:161;s:5:\"sajda\";b:0;}i:54;a:9:{s:6:\"number\";i:3395;s:4:\"text\";s:124:\"Le jour où le châtiment les enveloppera d\'en haut et sous leurs pieds. Il [leur] dira: «Goûtez à ce que vous faisiez!»\";s:13:\"numberInSurah\";i:55;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:403;s:4:\"ruku\";i:347;s:11:\"hizbQuarter\";i:161;s:5:\"sajda\";b:0;}i:55;a:9:{s:6:\"number\";i:3396;s:4:\"text\";s:75:\"O Mes serviteurs qui avaient cru! Ma terre est bien vaste. Adorez-Moi donc!\";s:13:\"numberInSurah\";i:56;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:403;s:4:\"ruku\";i:347;s:11:\"hizbQuarter\";i:161;s:5:\"sajda\";b:0;}i:56;a:9:{s:6:\"number\";i:3397;s:4:\"text\";s:77:\"Toute âme goûtera la mort. Ensuite c\'est vers Nous que vous serez ramenés.\";s:13:\"numberInSurah\";i:57;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:403;s:4:\"ruku\";i:347;s:11:\"hizbQuarter\";i:161;s:5:\"sajda\";b:0;}i:57;a:9:{s:6:\"number\";i:3398;s:4:\"text\";s:249:\"Et quant à ceux qui croient et accomplissent de bonnes œuvres, Nous les installerons certes à l\'étage dans le Paradis sous lequel coulent les ruisseaux, pour y demeurer éternellement. Quelle belle récompense que celle de ceux qui font le bien,\";s:13:\"numberInSurah\";i:58;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:403;s:4:\"ruku\";i:347;s:11:\"hizbQuarter\";i:161;s:5:\"sajda\";b:0;}i:58;a:9:{s:6:\"number\";i:3399;s:4:\"text\";s:57:\"qui endurent, et placent leur confiance en leur Seigneur!\";s:13:\"numberInSurah\";i:59;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:403;s:4:\"ruku\";i:347;s:11:\"hizbQuarter\";i:161;s:5:\"sajda\";b:0;}i:59;a:9:{s:6:\"number\";i:3400;s:4:\"text\";s:143:\"Que de bêtes ne se chargent point de leur propre nourriture! C\'est Allah qui les nourrit ainsi que vous. Et c\'est Lui l\'Audient, l\'Omniscient.\";s:13:\"numberInSurah\";i:60;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:403;s:4:\"ruku\";i:347;s:11:\"hizbQuarter\";i:161;s:5:\"sajda\";b:0;}i:60;a:9:{s:6:\"number\";i:3401;s:4:\"text\";s:206:\"Si tu leur demandes: «Qui a créé les cieux et la terre, et assujetti le soleil et la lune?», ils diront très certainement: «Allah». Comment se fait-il qu\'ensuite ils se détournent (du chemin droit)?\";s:13:\"numberInSurah\";i:61;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:403;s:4:\"ruku\";i:347;s:11:\"hizbQuarter\";i:161;s:5:\"sajda\";b:0;}i:61;a:9:{s:6:\"number\";i:3402;s:4:\"text\";s:113:\"Allah dispense largement ou restreint Ses dons à qui Il veut parmi Ses serviteurs. Certes, Allah est Omniscient.\";s:13:\"numberInSurah\";i:62;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:403;s:4:\"ruku\";i:347;s:11:\"hizbQuarter\";i:161;s:5:\"sajda\";b:0;}i:62;a:9:{s:6:\"number\";i:3403;s:4:\"text\";s:232:\"Si tu leur demandes: «Qui a fait descendre du ciel une eau avec laquelle Il fit revivre la terre après sa mort?», ils diront très certainement: «Allah». Dis: «Louange à Allah!» Mais la plupart d\'entre eux ne raisonnent pas.\";s:13:\"numberInSurah\";i:63;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:403;s:4:\"ruku\";i:347;s:11:\"hizbQuarter\";i:161;s:5:\"sajda\";b:0;}i:63;a:9:{s:6:\"number\";i:3404;s:4:\"text\";s:117:\"Cette vie d\'ici-bas n\'est qu\'amusement et jeu. La Demeure de l\'au-delà est assurément la vraie vie. S\'ils savaient!\";s:13:\"numberInSurah\";i:64;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:404;s:4:\"ruku\";i:348;s:11:\"hizbQuarter\";i:161;s:5:\"sajda\";b:0;}i:64;a:9:{s:6:\"number\";i:3405;s:4:\"text\";s:217:\"Quand ils montent en bateau, ils invoquent Allah Lui vouant exclusivement leur culte. Une fois qu\'Il les a sauvés [des dangers de la mer en les ramenant] sur la terre ferme, voilà qu\'ils [Lui] donnent des associés.\";s:13:\"numberInSurah\";i:65;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:404;s:4:\"ruku\";i:348;s:11:\"hizbQuarter\";i:161;s:5:\"sajda\";b:0;}i:65;a:9:{s:6:\"number\";i:3406;s:4:\"text\";s:100:\"Qu\'ils nient ce que nous leur avons donné et jouissent des biens de ce monde! Ils sauront bientôt!\";s:13:\"numberInSurah\";i:66;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:404;s:4:\"ruku\";i:348;s:11:\"hizbQuarter\";i:161;s:5:\"sajda\";b:0;}i:66;a:9:{s:6:\"number\";i:3407;s:4:\"text\";s:191:\"Ne voient-ils pas que vraiment Nous avons fait un sanctuaire sûr [la Mecque], alors que tout autour d\'eux on enlève les gens? Croiront-ils donc au faux et nieront-ils les bienfaits d\'Allah?\";s:13:\"numberInSurah\";i:67;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:404;s:4:\"ruku\";i:348;s:11:\"hizbQuarter\";i:161;s:5:\"sajda\";b:0;}i:67;a:9:{s:6:\"number\";i:3408;s:4:\"text\";s:180:\"Et quel pire injuste que celui qui invente un mensonge contre Allah, ou qui dément la Vérité quand elle lui parvient? N\'est-ce pas dans l\'Enfer une demeure pour les mécréants?\";s:13:\"numberInSurah\";i:68;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:404;s:4:\"ruku\";i:348;s:11:\"hizbQuarter\";i:161;s:5:\"sajda\";b:0;}i:68;a:9:{s:6:\"number\";i:3409;s:4:\"text\";s:135:\"Et quant à ceux qui luttent pour Notre cause, Nous les guiderons certes sur Nos sentiers. Allah est en vérité avec les bienfaisants.\";s:13:\"numberInSurah\";i:69;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:404;s:4:\"ruku\";i:348;s:11:\"hizbQuarter\";i:161;s:5:\"sajda\";b:0;}}s:7:\"edition\";a:7:{s:10:\"identifier\";s:13:\"fr.hamidullah\";s:8:\"language\";s:2:\"fr\";s:4:\"name\";s:10:\"Hamidullah\";s:11:\"englishName\";s:19:\"Muhammad Hamidullah\";s:6:\"format\";s:4:\"text\";s:4:\"type\";s:11:\"translation\";s:9:\"direction\";s:3:\"ltr\";}}', 1794581363);
INSERT INTO `cache` (`key`, `value`, `expiration`) VALUES
('quranapp-cache-surah_30_ar.uthmani', 'a:8:{s:6:\"number\";i:30;s:4:\"name\";s:31:\"سُورَةُ الرُّومِ\";s:11:\"englishName\";s:7:\"Ar-Room\";s:22:\"englishNameTranslation\";s:10:\"The Romans\";s:14:\"revelationType\";s:6:\"Meccan\";s:13:\"numberOfAyahs\";i:60;s:5:\"ayahs\";a:60:{i:0;a:9:{s:6:\"number\";i:3410;s:4:\"text\";s:87:\"بِسۡمِ ٱللَّهِ ٱلرَّحۡمَـٰنِ ٱلرَّحِیمِ الۤمۤ\n\";s:13:\"numberInSurah\";i:1;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:404;s:4:\"ruku\";i:349;s:11:\"hizbQuarter\";i:162;s:5:\"sajda\";b:0;}i:1;a:9:{s:6:\"number\";i:3411;s:4:\"text\";s:34:\"غُلِبَتِ ٱلرُّومُ\n\";s:13:\"numberInSurah\";i:2;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:404;s:4:\"ruku\";i:349;s:11:\"hizbQuarter\";i:162;s:5:\"sajda\";b:0;}i:2;a:9:{s:6:\"number\";i:3412;s:4:\"text\";s:126:\"فِیۤ أَدۡنَى ٱلۡأَرۡضِ وَهُم مِّنۢ بَعۡدِ غَلَبِهِمۡ سَیَغۡلِبُونَ\n\";s:13:\"numberInSurah\";i:3;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:404;s:4:\"ruku\";i:349;s:11:\"hizbQuarter\";i:162;s:5:\"sajda\";b:0;}i:3;a:9:{s:6:\"number\";i:3413;s:4:\"text\";s:193:\"فِی بِضۡعِ سِنِینَۗ لِلَّهِ ٱلۡأَمۡرُ مِن قَبۡلُ وَمِنۢ بَعۡدُۚ وَیَوۡمَىِٕذࣲ یَفۡرَحُ ٱلۡمُؤۡمِنُونَ\n\";s:13:\"numberInSurah\";i:4;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:404;s:4:\"ruku\";i:349;s:11:\"hizbQuarter\";i:162;s:5:\"sajda\";b:0;}i:4;a:9:{s:6:\"number\";i:3414;s:4:\"text\";s:130:\"بِنَصۡرِ ٱللَّهِۚ یَنصُرُ مَن یَشَاۤءُۖ وَهُوَ ٱلۡعَزِیزُ ٱلرَّحِیمُ\n\";s:13:\"numberInSurah\";i:5;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:404;s:4:\"ruku\";i:349;s:11:\"hizbQuarter\";i:162;s:5:\"sajda\";b:0;}i:5;a:9:{s:6:\"number\";i:3415;s:4:\"text\";s:175:\"وَعۡدَ ٱللَّهِۖ لَا یُخۡلِفُ ٱللَّهُ وَعۡدَهُۥ وَلَـٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا یَعۡلَمُونَ\n\";s:13:\"numberInSurah\";i:6;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:405;s:4:\"ruku\";i:349;s:11:\"hizbQuarter\";i:162;s:5:\"sajda\";b:0;}i:6;a:9:{s:6:\"number\";i:3416;s:4:\"text\";s:179:\"یَعۡلَمُونَ ظَـٰهِرࣰا مِّنَ ٱلۡحَیَوٰةِ ٱلدُّنۡیَا وَهُمۡ عَنِ ٱلۡـَٔاخِرَةِ هُمۡ غَـٰفِلُونَ\n\";s:13:\"numberInSurah\";i:7;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:405;s:4:\"ruku\";i:349;s:11:\"hizbQuarter\";i:162;s:5:\"sajda\";b:0;}i:7;a:9:{s:6:\"number\";i:3417;s:4:\"text\";s:413:\"أَوَلَمۡ یَتَفَكَّرُوا۟ فِیۤ أَنفُسِهِمۗ مَّا خَلَقَ ٱللَّهُ ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضَ وَمَا بَیۡنَهُمَاۤ إِلَّا بِٱلۡحَقِّ وَأَجَلࣲ مُّسَمࣰّىۗ وَإِنَّ كَثِیرࣰا مِّنَ ٱلنَّاسِ بِلِقَاۤىِٕ رَبِّهِمۡ لَكَـٰفِرُونَ\n\";s:13:\"numberInSurah\";i:8;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:405;s:4:\"ruku\";i:349;s:11:\"hizbQuarter\";i:162;s:5:\"sajda\";b:0;}i:8;a:9:{s:6:\"number\";i:3418;s:4:\"text\";s:605:\"أَوَلَمۡ یَسِیرُوا۟ فِی ٱلۡأَرۡضِ فَیَنظُرُوا۟ كَیۡفَ كَانَ عَـٰقِبَةُ ٱلَّذِینَ مِن قَبۡلِهِمۡۚ كَانُوۤا۟ أَشَدَّ مِنۡهُمۡ قُوَّةࣰ وَأَثَارُوا۟ ٱلۡأَرۡضَ وَعَمَرُوهَاۤ أَكۡثَرَ مِمَّا عَمَرُوهَا وَجَاۤءَتۡهُمۡ رُسُلُهُم بِٱلۡبَیِّنَـٰتِۖ فَمَا كَانَ ٱللَّهُ لِیَظۡلِمَهُمۡ وَلَـٰكِن كَانُوۤا۟ أَنفُسَهُمۡ یَظۡلِمُونَ\n\";s:13:\"numberInSurah\";i:9;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:405;s:4:\"ruku\";i:349;s:11:\"hizbQuarter\";i:162;s:5:\"sajda\";b:0;}i:9;a:9:{s:6:\"number\";i:3419;s:4:\"text\";s:245:\"ثُمَّ كَانَ عَـٰقِبَةَ ٱلَّذِینَ أَسَـٰۤـُٔوا۟ ٱلسُّوۤأَىٰۤ أَن كَذَّبُوا۟ بِـَٔایَـٰتِ ٱللَّهِ وَكَانُوا۟ بِهَا یَسۡتَهۡزِءُونَ\n\";s:13:\"numberInSurah\";i:10;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:405;s:4:\"ruku\";i:349;s:11:\"hizbQuarter\";i:162;s:5:\"sajda\";b:0;}i:10;a:9:{s:6:\"number\";i:3420;s:4:\"text\";s:138:\"ٱللَّهُ یَبۡدَؤُا۟ ٱلۡخَلۡقَ ثُمَّ یُعِیدُهُۥ ثُمَّ إِلَیۡهِ تُرۡجَعُونَ\n\";s:13:\"numberInSurah\";i:11;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:405;s:4:\"ruku\";i:350;s:11:\"hizbQuarter\";i:162;s:5:\"sajda\";b:0;}i:11;a:9:{s:6:\"number\";i:3421;s:4:\"text\";s:99:\"وَیَوۡمَ تَقُومُ ٱلسَّاعَةُ یُبۡلِسُ ٱلۡمُجۡرِمُونَ\n\";s:13:\"numberInSurah\";i:12;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:405;s:4:\"ruku\";i:350;s:11:\"hizbQuarter\";i:162;s:5:\"sajda\";b:0;}i:12;a:9:{s:6:\"number\";i:3422;s:4:\"text\";s:183:\"وَلَمۡ یَكُن لَّهُم مِّن شُرَكَاۤىِٕهِمۡ شُفَعَـٰۤؤُا۟ وَكَانُوا۟ بِشُرَكَاۤىِٕهِمۡ كَـٰفِرِینَ\n\";s:13:\"numberInSurah\";i:13;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:405;s:4:\"ruku\";i:350;s:11:\"hizbQuarter\";i:162;s:5:\"sajda\";b:0;}i:13;a:9:{s:6:\"number\";i:3423;s:4:\"text\";s:106:\"وَیَوۡمَ تَقُومُ ٱلسَّاعَةُ یَوۡمَىِٕذࣲ یَتَفَرَّقُونَ\n\";s:13:\"numberInSurah\";i:14;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:405;s:4:\"ruku\";i:350;s:11:\"hizbQuarter\";i:162;s:5:\"sajda\";b:0;}i:14;a:9:{s:6:\"number\";i:3424;s:4:\"text\";s:172:\"فَأَمَّا ٱلَّذِینَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ فَهُمۡ فِی رَوۡضَةࣲ یُحۡبَرُونَ\n\";s:13:\"numberInSurah\";i:15;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:405;s:4:\"ruku\";i:350;s:11:\"hizbQuarter\";i:162;s:5:\"sajda\";b:0;}i:15;a:9:{s:6:\"number\";i:3425;s:4:\"text\";s:245:\"وَأَمَّا ٱلَّذِینَ كَفَرُوا۟ وَكَذَّبُوا۟ بِـَٔایَـٰتِنَا وَلِقَاۤىِٕ ٱلۡـَٔاخِرَةِ فَأُو۟لَـٰۤىِٕكَ فِی ٱلۡعَذَابِ مُحۡضَرُونَ\n\";s:13:\"numberInSurah\";i:16;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:406;s:4:\"ruku\";i:350;s:11:\"hizbQuarter\";i:162;s:5:\"sajda\";b:0;}i:16;a:9:{s:6:\"number\";i:3426;s:4:\"text\";s:108:\"فَسُبۡحَـٰنَ ٱللَّهِ حِینَ تُمۡسُونَ وَحِینَ تُصۡبِحُونَ\n\";s:13:\"numberInSurah\";i:17;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:406;s:4:\"ruku\";i:350;s:11:\"hizbQuarter\";i:162;s:5:\"sajda\";b:0;}i:17;a:9:{s:6:\"number\";i:3427;s:4:\"text\";s:157:\"وَلَهُ ٱلۡحَمۡدُ فِی ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِ وَعَشِیࣰّا وَحِینَ تُظۡهِرُونَ\n\";s:13:\"numberInSurah\";i:18;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:406;s:4:\"ruku\";i:350;s:11:\"hizbQuarter\";i:162;s:5:\"sajda\";b:0;}i:18;a:9:{s:6:\"number\";i:3428;s:4:\"text\";s:254:\"یُخۡرِجُ ٱلۡحَیَّ مِنَ ٱلۡمَیِّتِ وَیُخۡرِجُ ٱلۡمَیِّتَ مِنَ ٱلۡحَیِّ وَیُحۡیِ ٱلۡأَرۡضَ بَعۡدَ مَوۡتِهَاۚ وَكَذَ ٰ⁠لِكَ تُخۡرَجُونَ\n\";s:13:\"numberInSurah\";i:19;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:406;s:4:\"ruku\";i:350;s:11:\"hizbQuarter\";i:162;s:5:\"sajda\";b:0;}i:19;a:9:{s:6:\"number\";i:3429;s:4:\"text\";s:169:\"وَمِنۡ ءَایَـٰتِهِۦۤ أَنۡ خَلَقَكُم مِّن تُرَابࣲ ثُمَّ إِذَاۤ أَنتُم بَشَرࣱ تَنتَشِرُونَ\n\";s:13:\"numberInSurah\";i:20;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:406;s:4:\"ruku\";i:351;s:11:\"hizbQuarter\";i:162;s:5:\"sajda\";b:0;}i:20;a:9:{s:6:\"number\";i:3430;s:4:\"text\";s:380:\"وَمِنۡ ءَایَـٰتِهِۦۤ أَنۡ خَلَقَ لَكُم مِّنۡ أَنفُسِكُمۡ أَزۡوَ ٰ⁠جࣰا لِّتَسۡكُنُوۤا۟ إِلَیۡهَا وَجَعَلَ بَیۡنَكُم مَّوَدَّةࣰ وَرَحۡمَةًۚ إِنَّ فِی ذَ ٰ⁠لِكَ لَـَٔایَـٰتࣲ لِّقَوۡمࣲ یَتَفَكَّرُونَ\n\";s:13:\"numberInSurah\";i:21;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:406;s:4:\"ruku\";i:351;s:11:\"hizbQuarter\";i:162;s:5:\"sajda\";b:0;}i:21;a:9:{s:6:\"number\";i:3431;s:4:\"text\";s:302:\"وَمِنۡ ءَایَـٰتِهِۦ خَلۡقُ ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِ وَٱخۡتِلَـٰفُ أَلۡسِنَتِكُمۡ وَأَلۡوَ ٰ⁠نِكُمۡۚ إِنَّ فِی ذَ ٰ⁠لِكَ لَـَٔایَـٰتࣲ لِّلۡعَـٰلِمِینَ\n\";s:13:\"numberInSurah\";i:22;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:406;s:4:\"ruku\";i:351;s:11:\"hizbQuarter\";i:162;s:5:\"sajda\";b:0;}i:22;a:9:{s:6:\"number\";i:3432;s:4:\"text\";s:278:\"وَمِنۡ ءَایَـٰتِهِۦ مَنَامُكُم بِٱلَّیۡلِ وَٱلنَّهَارِ وَٱبۡتِغَاۤؤُكُم مِّن فَضۡلِهِۦۤۚ إِنَّ فِی ذَ ٰ⁠لِكَ لَـَٔایَـٰتࣲ لِّقَوۡمࣲ یَسۡمَعُونَ\n\";s:13:\"numberInSurah\";i:23;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:406;s:4:\"ruku\";i:351;s:11:\"hizbQuarter\";i:162;s:5:\"sajda\";b:0;}i:23;a:9:{s:6:\"number\";i:3433;s:4:\"text\";s:372:\"وَمِنۡ ءَایَـٰتِهِۦ یُرِیكُمُ ٱلۡبَرۡقَ خَوۡفࣰا وَطَمَعࣰا وَیُنَزِّلُ مِنَ ٱلسَّمَاۤءِ مَاۤءࣰ فَیُحۡیِۦ بِهِ ٱلۡأَرۡضَ بَعۡدَ مَوۡتِهَاۤۚ إِنَّ فِی ذَ ٰ⁠لِكَ لَـَٔایَـٰتࣲ لِّقَوۡمࣲ یَعۡقِلُونَ\n\";s:13:\"numberInSurah\";i:24;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:406;s:4:\"ruku\";i:351;s:11:\"hizbQuarter\";i:162;s:5:\"sajda\";b:0;}i:24;a:9:{s:6:\"number\";i:3434;s:4:\"text\";s:273:\"وَمِنۡ ءَایَـٰتِهِۦۤ أَن تَقُومَ ٱلسَّمَاۤءُ وَٱلۡأَرۡضُ بِأَمۡرِهِۦۚ ثُمَّ إِذَا دَعَاكُمۡ دَعۡوَةࣰ مِّنَ ٱلۡأَرۡضِ إِذَاۤ أَنتُمۡ تَخۡرُجُونَ\n\";s:13:\"numberInSurah\";i:25;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:407;s:4:\"ruku\";i:351;s:11:\"hizbQuarter\";i:162;s:5:\"sajda\";b:0;}i:25;a:9:{s:6:\"number\";i:3435;s:4:\"text\";s:137:\"وَلَهُۥ مَن فِی ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِۖ كُلࣱّ لَّهُۥ قَـٰنِتُونَ\n\";s:13:\"numberInSurah\";i:26;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:407;s:4:\"ruku\";i:351;s:11:\"hizbQuarter\";i:162;s:5:\"sajda\";b:0;}i:26;a:9:{s:6:\"number\";i:3436;s:4:\"text\";s:326:\"وَهُوَ ٱلَّذِی یَبۡدَؤُا۟ ٱلۡخَلۡقَ ثُمَّ یُعِیدُهُۥ وَهُوَ أَهۡوَنُ عَلَیۡهِۚ وَلَهُ ٱلۡمَثَلُ ٱلۡأَعۡلَىٰ فِی ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِۚ وَهُوَ ٱلۡعَزِیزُ ٱلۡحَكِیمُ\n\";s:13:\"numberInSurah\";i:27;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:407;s:4:\"ruku\";i:351;s:11:\"hizbQuarter\";i:162;s:5:\"sajda\";b:0;}i:27;a:9:{s:6:\"number\";i:3437;s:4:\"text\";s:474:\"ضَرَبَ لَكُم مَّثَلࣰا مِّنۡ أَنفُسِكُمۡۖ هَل لَّكُم مِّن مَّا مَلَكَتۡ أَیۡمَـٰنُكُم مِّن شُرَكَاۤءَ فِی مَا رَزَقۡنَـٰكُمۡ فَأَنتُمۡ فِیهِ سَوَاۤءࣱ تَخَافُونَهُمۡ كَخِیفَتِكُمۡ أَنفُسَكُمۡۚ كَذَ ٰ⁠لِكَ نُفَصِّلُ ٱلۡـَٔایَـٰتِ لِقَوۡمࣲ یَعۡقِلُونَ\n\";s:13:\"numberInSurah\";i:28;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:407;s:4:\"ruku\";i:352;s:11:\"hizbQuarter\";i:162;s:5:\"sajda\";b:0;}i:28;a:9:{s:6:\"number\";i:3438;s:4:\"text\";s:249:\"بَلِ ٱتَّبَعَ ٱلَّذِینَ ظَلَمُوۤا۟ أَهۡوَاۤءَهُم بِغَیۡرِ عِلۡمࣲۖ فَمَن یَهۡدِی مَنۡ أَضَلَّ ٱللَّهُۖ وَمَا لَهُم مِّن نَّـٰصِرِینَ\n\";s:13:\"numberInSurah\";i:29;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:407;s:4:\"ruku\";i:352;s:11:\"hizbQuarter\";i:162;s:5:\"sajda\";b:0;}i:29;a:9:{s:6:\"number\";i:3439;s:4:\"text\";s:377:\"فَأَقِمۡ وَجۡهَكَ لِلدِّینِ حَنِیفࣰاۚ فِطۡرَتَ ٱللَّهِ ٱلَّتِی فَطَرَ ٱلنَّاسَ عَلَیۡهَاۚ لَا تَبۡدِیلَ لِخَلۡقِ ٱللَّهِۚ ذَ ٰ⁠لِكَ ٱلدِّینُ ٱلۡقَیِّمُ وَلَـٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا یَعۡلَمُونَ\n\";s:13:\"numberInSurah\";i:30;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:407;s:4:\"ruku\";i:352;s:11:\"hizbQuarter\";i:162;s:5:\"sajda\";b:0;}i:30;a:9:{s:6:\"number\";i:3440;s:4:\"text\";s:182:\"۞ مُنِیبِینَ إِلَیۡهِ وَٱتَّقُوهُ وَأَقِیمُوا۟ ٱلصَّلَوٰةَ وَلَا تَكُونُوا۟ مِنَ ٱلۡمُشۡرِكِینَ\n\";s:13:\"numberInSurah\";i:31;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:407;s:4:\"ruku\";i:352;s:11:\"hizbQuarter\";i:163;s:5:\"sajda\";b:0;}i:31;a:9:{s:6:\"number\";i:3441;s:4:\"text\";s:184:\"مِنَ ٱلَّذِینَ فَرَّقُوا۟ دِینَهُمۡ وَكَانُوا۟ شِیَعࣰاۖ كُلُّ حِزۡبِۭ بِمَا لَدَیۡهِمۡ فَرِحُونَ\n\";s:13:\"numberInSurah\";i:32;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:407;s:4:\"ruku\";i:352;s:11:\"hizbQuarter\";i:163;s:5:\"sajda\";b:0;}i:32;a:9:{s:6:\"number\";i:3442;s:4:\"text\";s:296:\"وَإِذَا مَسَّ ٱلنَّاسَ ضُرࣱّ دَعَوۡا۟ رَبَّهُم مُّنِیبِینَ إِلَیۡهِ ثُمَّ إِذَاۤ أَذَاقَهُم مِّنۡهُ رَحۡمَةً إِذَا فَرِیقࣱ مِّنۡهُم بِرَبِّهِمۡ یُشۡرِكُونَ\n\";s:13:\"numberInSurah\";i:33;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:408;s:4:\"ruku\";i:352;s:11:\"hizbQuarter\";i:163;s:5:\"sajda\";b:0;}i:33;a:9:{s:6:\"number\";i:3443;s:4:\"text\";s:142:\"لِیَكۡفُرُوا۟ بِمَاۤ ءَاتَیۡنَـٰهُمۡۚ فَتَمَتَّعُوا۟ فَسَوۡفَ تَعۡلَمُونَ\n\";s:13:\"numberInSurah\";i:34;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:408;s:4:\"ruku\";i:352;s:11:\"hizbQuarter\";i:163;s:5:\"sajda\";b:0;}i:34;a:9:{s:6:\"number\";i:3444;s:4:\"text\";s:173:\"أَمۡ أَنزَلۡنَا عَلَیۡهِمۡ سُلۡطَـٰنࣰا فَهُوَ یَتَكَلَّمُ بِمَا كَانُوا۟ بِهِۦ یُشۡرِكُونَ\n\";s:13:\"numberInSurah\";i:35;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:408;s:4:\"ruku\";i:352;s:11:\"hizbQuarter\";i:163;s:5:\"sajda\";b:0;}i:35;a:9:{s:6:\"number\";i:3445;s:4:\"text\";s:252:\"وَإِذَاۤ أَذَقۡنَا ٱلنَّاسَ رَحۡمَةࣰ فَرِحُوا۟ بِهَاۖ وَإِن تُصِبۡهُمۡ سَیِّئَةُۢ بِمَا قَدَّمَتۡ أَیۡدِیهِمۡ إِذَا هُمۡ یَقۡنَطُونَ\n\";s:13:\"numberInSurah\";i:36;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:408;s:4:\"ruku\";i:352;s:11:\"hizbQuarter\";i:163;s:5:\"sajda\";b:0;}i:36;a:9:{s:6:\"number\";i:3446;s:4:\"text\";s:255:\"أَوَلَمۡ یَرَوۡا۟ أَنَّ ٱللَّهَ یَبۡسُطُ ٱلرِّزۡقَ لِمَن یَشَاۤءُ وَیَقۡدِرُۚ إِنَّ فِی ذَ ٰ⁠لِكَ لَـَٔایَـٰتࣲ لِّقَوۡمࣲ یُؤۡمِنُونَ\n\";s:13:\"numberInSurah\";i:37;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:408;s:4:\"ruku\";i:352;s:11:\"hizbQuarter\";i:163;s:5:\"sajda\";b:0;}i:37;a:9:{s:6:\"number\";i:3447;s:4:\"text\";s:311:\"فَـَٔاتِ ذَا ٱلۡقُرۡبَىٰ حَقَّهُۥ وَٱلۡمِسۡكِینَ وَٱبۡنَ ٱلسَّبِیلِۚ ذَ ٰ⁠لِكَ خَیۡرࣱ لِّلَّذِینَ یُرِیدُونَ وَجۡهَ ٱللَّهِۖ وَأُو۟لَـٰۤىِٕكَ هُمُ ٱلۡمُفۡلِحُونَ\n\";s:13:\"numberInSurah\";i:38;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:408;s:4:\"ruku\";i:352;s:11:\"hizbQuarter\";i:163;s:5:\"sajda\";b:0;}i:38;a:9:{s:6:\"number\";i:3448;s:4:\"text\";s:374:\"وَمَاۤ ءَاتَیۡتُم مِّن رِّبࣰا لِّیَرۡبُوَا۟ فِیۤ أَمۡوَ ٰ⁠لِ ٱلنَّاسِ فَلَا یَرۡبُوا۟ عِندَ ٱللَّهِۖ وَمَاۤ ءَاتَیۡتُم مِّن زَكَوٰةࣲ تُرِیدُونَ وَجۡهَ ٱللَّهِ فَأُو۟لَـٰۤىِٕكَ هُمُ ٱلۡمُضۡعِفُونَ\n\";s:13:\"numberInSurah\";i:39;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:408;s:4:\"ruku\";i:352;s:11:\"hizbQuarter\";i:163;s:5:\"sajda\";b:0;}i:39;a:9:{s:6:\"number\";i:3449;s:4:\"text\";s:367:\"ٱللَّهُ ٱلَّذِی خَلَقَكُمۡ ثُمَّ رَزَقَكُمۡ ثُمَّ یُمِیتُكُمۡ ثُمَّ یُحۡیِیكُمۡۖ هَلۡ مِن شُرَكَاۤىِٕكُم مَّن یَفۡعَلُ مِن ذَ ٰ⁠لِكُم مِّن شَیۡءࣲۚ سُبۡحَـٰنَهُۥ وَتَعَـٰلَىٰ عَمَّا یُشۡرِكُونَ\n\";s:13:\"numberInSurah\";i:40;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:408;s:4:\"ruku\";i:352;s:11:\"hizbQuarter\";i:163;s:5:\"sajda\";b:0;}i:40;a:9:{s:6:\"number\";i:3450;s:4:\"text\";s:259:\"ظَهَرَ ٱلۡفَسَادُ فِی ٱلۡبَرِّ وَٱلۡبَحۡرِ بِمَا كَسَبَتۡ أَیۡدِی ٱلنَّاسِ لِیُذِیقَهُم بَعۡضَ ٱلَّذِی عَمِلُوا۟ لَعَلَّهُمۡ یَرۡجِعُونَ\n\";s:13:\"numberInSurah\";i:41;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:408;s:4:\"ruku\";i:353;s:11:\"hizbQuarter\";i:163;s:5:\"sajda\";b:0;}i:41;a:9:{s:6:\"number\";i:3451;s:4:\"text\";s:220:\"قُلۡ سِیرُوا۟ فِی ٱلۡأَرۡضِ فَٱنظُرُوا۟ كَیۡفَ كَانَ عَـٰقِبَةُ ٱلَّذِینَ مِن قَبۡلُۚ كَانَ أَكۡثَرُهُم مُّشۡرِكِینَ\n\";s:13:\"numberInSurah\";i:42;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:409;s:4:\"ruku\";i:353;s:11:\"hizbQuarter\";i:163;s:5:\"sajda\";b:0;}i:42;a:9:{s:6:\"number\";i:3452;s:4:\"text\";s:244:\"فَأَقِمۡ وَجۡهَكَ لِلدِّینِ ٱلۡقَیِّمِ مِن قَبۡلِ أَن یَأۡتِیَ یَوۡمࣱ لَّا مَرَدَّ لَهُۥ مِنَ ٱللَّهِۖ یَوۡمَىِٕذࣲ یَصَّدَّعُونَ\n\";s:13:\"numberInSurah\";i:43;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:409;s:4:\"ruku\";i:353;s:11:\"hizbQuarter\";i:163;s:5:\"sajda\";b:0;}i:43;a:9:{s:6:\"number\";i:3453;s:4:\"text\";s:162:\"مَن كَفَرَ فَعَلَیۡهِ كُفۡرُهُۥۖ وَمَنۡ عَمِلَ صَـٰلِحࣰا فَلِأَنفُسِهِمۡ یَمۡهَدُونَ\n\";s:13:\"numberInSurah\";i:44;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:409;s:4:\"ruku\";i:353;s:11:\"hizbQuarter\";i:163;s:5:\"sajda\";b:0;}i:44;a:9:{s:6:\"number\";i:3454;s:4:\"text\";s:213:\"لِیَجۡزِیَ ٱلَّذِینَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ مِن فَضۡلِهِۦۤۚ إِنَّهُۥ لَا یُحِبُّ ٱلۡكَـٰفِرِینَ\n\";s:13:\"numberInSurah\";i:45;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:409;s:4:\"ruku\";i:353;s:11:\"hizbQuarter\";i:163;s:5:\"sajda\";b:0;}i:45;a:9:{s:6:\"number\";i:3455;s:4:\"text\";s:354:\"وَمِنۡ ءَایَـٰتِهِۦۤ أَن یُرۡسِلَ ٱلرِّیَاحَ مُبَشِّرَ ٰ⁠تࣲ وَلِیُذِیقَكُم مِّن رَّحۡمَتِهِۦ وَلِتَجۡرِیَ ٱلۡفُلۡكُ بِأَمۡرِهِۦ وَلِتَبۡتَغُوا۟ مِن فَضۡلِهِۦ وَلَعَلَّكُمۡ تَشۡكُرُونَ\n\";s:13:\"numberInSurah\";i:46;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:409;s:4:\"ruku\";i:353;s:11:\"hizbQuarter\";i:163;s:5:\"sajda\";b:0;}i:46;a:9:{s:6:\"number\";i:3456;s:4:\"text\";s:340:\"وَلَقَدۡ أَرۡسَلۡنَا مِن قَبۡلِكَ رُسُلًا إِلَىٰ قَوۡمِهِمۡ فَجَاۤءُوهُم بِٱلۡبَیِّنَـٰتِ فَٱنتَقَمۡنَا مِنَ ٱلَّذِینَ أَجۡرَمُوا۟ۖ وَكَانَ حَقًّا عَلَیۡنَا نَصۡرُ ٱلۡمُؤۡمِنِینَ\n\";s:13:\"numberInSurah\";i:47;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:409;s:4:\"ruku\";i:353;s:11:\"hizbQuarter\";i:163;s:5:\"sajda\";b:0;}i:47;a:9:{s:6:\"number\";i:3457;s:4:\"text\";s:472:\"ٱللَّهُ ٱلَّذِی یُرۡسِلُ ٱلرِّیَـٰحَ فَتُثِیرُ سَحَابࣰا فَیَبۡسُطُهُۥ فِی ٱلسَّمَاۤءِ كَیۡفَ یَشَاۤءُ وَیَجۡعَلُهُۥ كِسَفࣰا فَتَرَى ٱلۡوَدۡقَ یَخۡرُجُ مِنۡ خِلَـٰلِهِۦۖ فَإِذَاۤ أَصَابَ بِهِۦ مَن یَشَاۤءُ مِنۡ عِبَادِهِۦۤ إِذَا هُمۡ یَسۡتَبۡشِرُونَ\n\";s:13:\"numberInSurah\";i:48;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:409;s:4:\"ruku\";i:353;s:11:\"hizbQuarter\";i:163;s:5:\"sajda\";b:0;}i:48;a:9:{s:6:\"number\";i:3458;s:4:\"text\";s:148:\"وَإِن كَانُوا۟ مِن قَبۡلِ أَن یُنَزَّلَ عَلَیۡهِم مِّن قَبۡلِهِۦ لَمُبۡلِسِینَ\n\";s:13:\"numberInSurah\";i:49;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:409;s:4:\"ruku\";i:353;s:11:\"hizbQuarter\";i:163;s:5:\"sajda\";b:0;}i:49;a:9:{s:6:\"number\";i:3459;s:4:\"text\";s:305:\"فَٱنظُرۡ إِلَىٰۤ ءَاثَـٰرِ رَحۡمَتِ ٱللَّهِ كَیۡفَ یُحۡیِ ٱلۡأَرۡضَ بَعۡدَ مَوۡتِهَاۤۚ إِنَّ ذَ ٰ⁠لِكَ لَمُحۡیِ ٱلۡمَوۡتَىٰۖ وَهُوَ عَلَىٰ كُلِّ شَیۡءࣲ قَدِیرࣱ\n\";s:13:\"numberInSurah\";i:50;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:409;s:4:\"ruku\";i:353;s:11:\"hizbQuarter\";i:163;s:5:\"sajda\";b:0;}i:50;a:9:{s:6:\"number\";i:3460;s:4:\"text\";s:173:\"وَلَىِٕنۡ أَرۡسَلۡنَا رِیحࣰا فَرَأَوۡهُ مُصۡفَرࣰّا لَّظَلُّوا۟ مِنۢ بَعۡدِهِۦ یَكۡفُرُونَ\n\";s:13:\"numberInSurah\";i:51;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:410;s:4:\"ruku\";i:353;s:11:\"hizbQuarter\";i:163;s:5:\"sajda\";b:0;}i:51;a:9:{s:6:\"number\";i:3461;s:4:\"text\";s:187:\"فَإِنَّكَ لَا تُسۡمِعُ ٱلۡمَوۡتَىٰ وَلَا تُسۡمِعُ ٱلصُّمَّ ٱلدُّعَاۤءَ إِذَا وَلَّوۡا۟ مُدۡبِرِینَ\n\";s:13:\"numberInSurah\";i:52;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:410;s:4:\"ruku\";i:353;s:11:\"hizbQuarter\";i:163;s:5:\"sajda\";b:0;}i:52;a:9:{s:6:\"number\";i:3462;s:4:\"text\";s:226:\"وَمَاۤ أَنتَ بِهَـٰدِ ٱلۡعُمۡیِ عَن ضَلَـٰلَتِهِمۡۖ إِن تُسۡمِعُ إِلَّا مَن یُؤۡمِنُ بِـَٔایَـٰتِنَا فَهُم مُّسۡلِمُونَ\n\";s:13:\"numberInSurah\";i:53;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:410;s:4:\"ruku\";i:353;s:11:\"hizbQuarter\";i:163;s:5:\"sajda\";b:0;}i:53;a:9:{s:6:\"number\";i:3463;s:4:\"text\";s:351:\"۞ ٱللَّهُ ٱلَّذِی خَلَقَكُم مِّن ضَعۡفࣲ ثُمَّ جَعَلَ مِنۢ بَعۡدِ ضَعۡفࣲ قُوَّةࣰ ثُمَّ جَعَلَ مِنۢ بَعۡدِ قُوَّةࣲ ضَعۡفࣰا وَشَیۡبَةࣰۚ یَخۡلُقُ مَا یَشَاۤءُۚ وَهُوَ ٱلۡعَلِیمُ ٱلۡقَدِیرُ\n\";s:13:\"numberInSurah\";i:54;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:410;s:4:\"ruku\";i:354;s:11:\"hizbQuarter\";i:164;s:5:\"sajda\";b:0;}i:54;a:9:{s:6:\"number\";i:3464;s:4:\"text\";s:221:\"وَیَوۡمَ تَقُومُ ٱلسَّاعَةُ یُقۡسِمُ ٱلۡمُجۡرِمُونَ مَا لَبِثُوا۟ غَیۡرَ سَاعَةࣲۚ كَذَ ٰ⁠لِكَ كَانُوا۟ یُؤۡفَكُونَ\n\";s:13:\"numberInSurah\";i:55;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:410;s:4:\"ruku\";i:354;s:11:\"hizbQuarter\";i:164;s:5:\"sajda\";b:0;}i:55;a:9:{s:6:\"number\";i:3465;s:4:\"text\";s:346:\"وَقَالَ ٱلَّذِینَ أُوتُوا۟ ٱلۡعِلۡمَ وَٱلۡإِیمَـٰنَ لَقَدۡ لَبِثۡتُمۡ فِی كِتَـٰبِ ٱللَّهِ إِلَىٰ یَوۡمِ ٱلۡبَعۡثِۖ فَهَـٰذَا یَوۡمُ ٱلۡبَعۡثِ وَلَـٰكِنَّكُمۡ كُنتُمۡ لَا تَعۡلَمُونَ\n\";s:13:\"numberInSurah\";i:56;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:410;s:4:\"ruku\";i:354;s:11:\"hizbQuarter\";i:164;s:5:\"sajda\";b:0;}i:56;a:9:{s:6:\"number\";i:3466;s:4:\"text\";s:170:\"فَیَوۡمَىِٕذࣲ لَّا یَنفَعُ ٱلَّذِینَ ظَلَمُوا۟ مَعۡذِرَتُهُمۡ وَلَا هُمۡ یُسۡتَعۡتَبُونَ\n\";s:13:\"numberInSurah\";i:57;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:410;s:4:\"ruku\";i:354;s:11:\"hizbQuarter\";i:164;s:5:\"sajda\";b:0;}i:57;a:9:{s:6:\"number\";i:3467;s:4:\"text\";s:321:\"وَلَقَدۡ ضَرَبۡنَا لِلنَّاسِ فِی هَـٰذَا ٱلۡقُرۡءَانِ مِن كُلِّ مَثَلࣲۚ وَلَىِٕن جِئۡتَهُم بِـَٔایَةࣲ لَّیَقُولَنَّ ٱلَّذِینَ كَفَرُوۤا۟ إِنۡ أَنتُمۡ إِلَّا مُبۡطِلُونَ\n\";s:13:\"numberInSurah\";i:58;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:410;s:4:\"ruku\";i:354;s:11:\"hizbQuarter\";i:164;s:5:\"sajda\";b:0;}i:58;a:9:{s:6:\"number\";i:3468;s:4:\"text\";s:134:\"كَذَ ٰ⁠لِكَ یَطۡبَعُ ٱللَّهُ عَلَىٰ قُلُوبِ ٱلَّذِینَ لَا یَعۡلَمُونَ\n\";s:13:\"numberInSurah\";i:59;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:410;s:4:\"ruku\";i:354;s:11:\"hizbQuarter\";i:164;s:5:\"sajda\";b:0;}i:59;a:9:{s:6:\"number\";i:3469;s:4:\"text\";s:163:\"فَٱصۡبِرۡ إِنَّ وَعۡدَ ٱللَّهِ حَقࣱّۖ وَلَا یَسۡتَخِفَّنَّكَ ٱلَّذِینَ لَا یُوقِنُونَ\n\";s:13:\"numberInSurah\";i:60;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:410;s:4:\"ruku\";i:354;s:11:\"hizbQuarter\";i:164;s:5:\"sajda\";b:0;}}s:7:\"edition\";a:7:{s:10:\"identifier\";s:27:\"quran-uthmani-quran-academy\";s:8:\"language\";s:2:\"ar\";s:4:\"name\";s:67:\"القرآن الكريم برسم العثماني (quran-academy)\";s:11:\"englishName\";s:78:\"Modified Quran Uthmani Text from the Quran Academy to work with the Kitab font\";s:6:\"format\";s:4:\"text\";s:4:\"type\";s:5:\"quran\";s:9:\"direction\";s:3:\"rtl\";}}', 1794581364),
('quranapp-cache-surah_30_fr.hamidullah', 'a:8:{s:6:\"number\";i:30;s:4:\"name\";s:31:\"سُورَةُ الرُّومِ\";s:11:\"englishName\";s:7:\"Ar-Room\";s:22:\"englishNameTranslation\";s:10:\"The Romans\";s:14:\"revelationType\";s:6:\"Meccan\";s:13:\"numberOfAyahs\";i:60;s:5:\"ayahs\";a:60:{i:0;a:9:{s:6:\"number\";i:3410;s:4:\"text\";s:17:\"Alif, Lâm, Mîm.\";s:13:\"numberInSurah\";i:1;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:404;s:4:\"ruku\";i:349;s:11:\"hizbQuarter\";i:162;s:5:\"sajda\";b:0;}i:1;a:9:{s:6:\"number\";i:3411;s:4:\"text\";s:30:\"Les Romains ont été vaincus,\";s:13:\"numberInSurah\";i:2;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:404;s:4:\"ruku\";i:349;s:11:\"hizbQuarter\";i:162;s:5:\"sajda\";b:0;}i:2;a:9:{s:6:\"number\";i:3412;s:4:\"text\";s:71:\"dans le pays voisin, et après leur défaite ils seront les vainqueurs,\";s:13:\"numberInSurah\";i:3;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:404;s:4:\"ruku\";i:349;s:11:\"hizbQuarter\";i:162;s:5:\"sajda\";b:0;}i:3;a:9:{s:6:\"number\";i:3413;s:4:\"text\";s:125:\"dans quelques années. A Allah appartient le commandement, au début et à la fin, et ce jour-là les Croyants se réjouiront\";s:13:\"numberInSurah\";i:4;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:404;s:4:\"ruku\";i:349;s:11:\"hizbQuarter\";i:162;s:5:\"sajda\";b:0;}i:4;a:9:{s:6:\"number\";i:3414;s:4:\"text\";s:95:\"du secours d\'Allah. Il secourt qui Il veut et Il est le Tout Puissant, le Tout Miséricordieux.\";s:13:\"numberInSurah\";i:5;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:404;s:4:\"ruku\";i:349;s:11:\"hizbQuarter\";i:162;s:5:\"sajda\";b:0;}i:5;a:9:{s:6:\"number\";i:3415;s:4:\"text\";s:110:\"C\'est [là] la promesse d\'Allah. Allah ne manque jamais à Sa promesse mais la plupart des gens ne savent pas.\";s:13:\"numberInSurah\";i:6;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:405;s:4:\"ruku\";i:349;s:11:\"hizbQuarter\";i:162;s:5:\"sajda\";b:0;}i:6;a:9:{s:6:\"number\";i:3416;s:4:\"text\";s:92:\"Ils connaissent un aspect de la vie présente, tandis qu\'ils sont inattentifs à l\'au-delà.\";s:13:\"numberInSurah\";i:7;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:405;s:4:\"ruku\";i:349;s:11:\"hizbQuarter\";i:162;s:5:\"sajda\";b:0;}i:7;a:9:{s:6:\"number\";i:3417;s:4:\"text\";s:220:\"N\'ont-ils pas médité en eux-mêmes? Allah n\'a créé les cieux et la terre et ce qui est entre eux, qu\'à juste raison et pour un terme fixé. Beaucoup de gens cependant ne croient pas en la rencontre de leur Seigneur.\";s:13:\"numberInSurah\";i:8;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:405;s:4:\"ruku\";i:349;s:11:\"hizbQuarter\";i:162;s:5:\"sajda\";b:0;}i:8;a:9:{s:6:\"number\";i:3418;s:4:\"text\";s:357:\"N\'ont-ils pas parcouru la terre pour voir ce qu\'il est advenu de ceux qui ont vécu avant eux? Ceux-là les surpassaient en puissance et avaient labouré et peuplé la terre bien plus qu\'ils ne l\'ont fait eux-mêmes. Leurs messagers leur vinrent avec des preuves évidentes. Ce n\'est pas Allah qui leur fit du tort; mais ils se firent du tort à eux-mêmes.\";s:13:\"numberInSurah\";i:9;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:405;s:4:\"ruku\";i:349;s:11:\"hizbQuarter\";i:162;s:5:\"sajda\";b:0;}i:9;a:9:{s:6:\"number\";i:3419;s:4:\"text\";s:125:\"Puis, mauvaise fut la fin de ceux qui faisaient le mal, ayant traité de mensonges les versets d\'Allah et les ayant raillés.\";s:13:\"numberInSurah\";i:10;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:405;s:4:\"ruku\";i:349;s:11:\"hizbQuarter\";i:162;s:5:\"sajda\";b:0;}i:10;a:9:{s:6:\"number\";i:3420;s:4:\"text\";s:96:\"C\'est Allah qui commence la création; ensuite Il la refait; puis, vers Lui vous serez ramenés.\";s:13:\"numberInSurah\";i:11;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:405;s:4:\"ruku\";i:350;s:11:\"hizbQuarter\";i:162;s:5:\"sajda\";b:0;}i:11;a:9:{s:6:\"number\";i:3421;s:4:\"text\";s:77:\"Et le jour où l\'Heure arrivera, les criminels seront frappés de désespoir.\";s:13:\"numberInSurah\";i:12;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:405;s:4:\"ruku\";i:350;s:11:\"hizbQuarter\";i:162;s:5:\"sajda\";b:0;}i:12;a:9:{s:6:\"number\";i:3422;s:4:\"text\";s:119:\"Et ils n\'auront point d\'intercesseurs parmi ceux qu\'ils associaient [à Allah] et ils renieront même leurs divinités.\";s:13:\"numberInSurah\";i:13;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:405;s:4:\"ruku\";i:350;s:11:\"hizbQuarter\";i:162;s:5:\"sajda\";b:0;}i:13;a:9:{s:6:\"number\";i:3423;s:4:\"text\";s:82:\"Le jour où l\'Heure arrivera, ce jour-là ils se sépareront [les uns des autres].\";s:13:\"numberInSurah\";i:14;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:405;s:4:\"ruku\";i:350;s:11:\"hizbQuarter\";i:162;s:5:\"sajda\";b:0;}i:14;a:9:{s:6:\"number\";i:3424;s:4:\"text\";s:80:\"Ceux qui auront cru et accompli de bonnes œuvres se réjouiront dans un jardin;\";s:13:\"numberInSurah\";i:15;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:405;s:4:\"ruku\";i:350;s:11:\"hizbQuarter\";i:162;s:5:\"sajda\";b:0;}i:15;a:9:{s:6:\"number\";i:3425;s:4:\"text\";s:157:\"et quant à ceux qui n\'auront pas cru et auront traité de mensonges Nos signes ainsi que la rencontre de l\'au-delà, ceux-là seront emmenés au châtiment.\";s:13:\"numberInSurah\";i:16;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:406;s:4:\"ruku\";i:350;s:11:\"hizbQuarter\";i:162;s:5:\"sajda\";b:0;}i:16;a:9:{s:6:\"number\";i:3426;s:4:\"text\";s:36:\"Glorifiez Allah donc, soir et matin!\";s:13:\"numberInSurah\";i:17;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:406;s:4:\"ruku\";i:350;s:11:\"hizbQuarter\";i:162;s:5:\"sajda\";b:0;}i:17;a:9:{s:6:\"number\";i:3427;s:4:\"text\";s:95:\"A Lui toute louange dans les cieux et la terre, dans l\'après-midi et au milieu de la journée.\";s:13:\"numberInSurah\";i:18;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:406;s:4:\"ruku\";i:350;s:11:\"hizbQuarter\";i:162;s:5:\"sajda\";b:0;}i:18;a:9:{s:6:\"number\";i:3428;s:4:\"text\";s:185:\"Du mort, Il fait sortir le vivant, et du vivant, Il fait sortir le mort. Et Il redonne la vie à la terre après sa mort. Et c\'est ainsi que l\'on vous fera sortir (à la résurrection).\";s:13:\"numberInSurah\";i:19;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:406;s:4:\"ruku\";i:350;s:11:\"hizbQuarter\";i:162;s:5:\"sajda\";b:0;}i:19;a:9:{s:6:\"number\";i:3429;s:4:\"text\";s:113:\"Parmi Ses signes: Il vous a créés de terre, - puis, vous voilà des hommes qui se dispersent [dans le monde] -.\";s:13:\"numberInSurah\";i:20;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:406;s:4:\"ruku\";i:351;s:11:\"hizbQuarter\";i:162;s:5:\"sajda\";b:0;}i:20;a:9:{s:6:\"number\";i:3430;s:4:\"text\";s:230:\"Et parmi Ses signes Il a créé de vous, pour vous, des épouses pour que vous viviez en tranquillité avec elles et Il a mis entre vous de l\'affection et de la bonté. Il y a en cela des preuves pour des gens qui réfléchissent.\";s:13:\"numberInSurah\";i:21;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:406;s:4:\"ruku\";i:351;s:11:\"hizbQuarter\";i:162;s:5:\"sajda\";b:0;}i:21;a:9:{s:6:\"number\";i:3431;s:4:\"text\";s:153:\"Et parmi Ses signes la création des cieux et de la terre et la variété de vos idiomes et de vos couleurs. Il y a en cela des preuves pour les savants.\";s:13:\"numberInSurah\";i:22;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:406;s:4:\"ruku\";i:351;s:11:\"hizbQuarter\";i:162;s:5:\"sajda\";b:0;}i:22;a:9:{s:6:\"number\";i:3432;s:4:\"text\";s:145:\"Et parmi Ses signes votre sommeil la nuit et le jour, et aussi votre quête de Sa grâce. Il y a en cela des preuves pour des gens qui entendent.\";s:13:\"numberInSurah\";i:23;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:406;s:4:\"ruku\";i:351;s:11:\"hizbQuarter\";i:162;s:5:\"sajda\";b:0;}i:23;a:9:{s:6:\"number\";i:3433;s:4:\"text\";s:248:\"Et parmi Ses signes Il vous montre l\'éclair avec crainte (de la foudre) et espoir (de la pluie), et fait descendre du ciel une eau avec laquelle Il redonne la vie à la terre après sa mort. Il y a en cela des preuves pour des gens qui raisonnent.\";s:13:\"numberInSurah\";i:24;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:406;s:4:\"ruku\";i:351;s:11:\"hizbQuarter\";i:162;s:5:\"sajda\";b:0;}i:24;a:9:{s:6:\"number\";i:3434;s:4:\"text\";s:152:\"Et parmi Ses signes le ciel et la terre sont maintenus par Son ordre; ensuite lorsqu\'Il vous appellera d\'un appel, voilà que de la terre vous surgirez.\";s:13:\"numberInSurah\";i:25;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:407;s:4:\"ruku\";i:351;s:11:\"hizbQuarter\";i:162;s:5:\"sajda\";b:0;}i:25;a:9:{s:6:\"number\";i:3435;s:4:\"text\";s:87:\"A Lui tous ceux qui sont dans les cieux et la terre: tous Lui sont entièrement soumis.\";s:13:\"numberInSurah\";i:26;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:407;s:4:\"ruku\";i:351;s:11:\"hizbQuarter\";i:162;s:5:\"sajda\";b:0;}i:26;a:9:{s:6:\"number\";i:3436;s:4:\"text\";s:182:\"Et c\'est Lui qui commence la création puis la refait; et cela Lui est plus facile. Il a la transcendance absolue dans les cieux et sur la terre. C\'est Lui le Tout Puissant, le Sage.\";s:13:\"numberInSurah\";i:27;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:407;s:4:\"ruku\";i:351;s:11:\"hizbQuarter\";i:162;s:5:\"sajda\";b:0;}i:27;a:9:{s:6:\"number\";i:3437;s:4:\"text\";s:317:\"Il vous a cité une parabole de vous-mêmes: Avez-vous associé vos esclaves à ce que Nous vous avons attribué en sorte que vous soyez tous égaux [en droit de propriété] et que vous les craignez [autant] que vous vous craignez mutuellement? C\'est ainsi que Nous exposons Nos versets pour des gens qui raisonnent.\";s:13:\"numberInSurah\";i:28;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:407;s:4:\"ruku\";i:352;s:11:\"hizbQuarter\";i:162;s:5:\"sajda\";b:0;}i:28;a:9:{s:6:\"number\";i:3438;s:4:\"text\";s:168:\"Ceux qui ont été injustes ont plutôt suivi leurs propres passions, sans savoir. Qui donc peut guider celui qu\'Allah égare? Et ils n\'ont pas pour eux, de protecteur.\";s:13:\"numberInSurah\";i:29;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:407;s:4:\"ruku\";i:352;s:11:\"hizbQuarter\";i:162;s:5:\"sajda\";b:0;}i:29;a:9:{s:6:\"number\";i:3439;s:4:\"text\";s:250:\"Dirige tout ton être vers la religion exclusivement [pour Allah], telle est la nature qu\'Allah a originellement donnée aux hommes - pas de changement à la création d\'Allah -. Voilà la religion de droiture; mais la plupart des gens ne savent pas.\";s:13:\"numberInSurah\";i:30;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:407;s:4:\"ruku\";i:352;s:11:\"hizbQuarter\";i:162;s:5:\"sajda\";b:0;}i:30;a:9:{s:6:\"number\";i:3440;s:4:\"text\";s:104:\"Revenez repentants vers Lui; craignez-Le, accomplissez la Salât et ne soyez pas parmi les associateurs,\";s:13:\"numberInSurah\";i:31;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:407;s:4:\"ruku\";i:352;s:11:\"hizbQuarter\";i:163;s:5:\"sajda\";b:0;}i:31;a:9:{s:6:\"number\";i:3441;s:4:\"text\";s:113:\"parmi ceux qui ont divisé leur religion et sont devenus des sectes, chaque parti exultant de ce qu\'il détenait.\";s:13:\"numberInSurah\";i:32;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:407;s:4:\"ruku\";i:352;s:11:\"hizbQuarter\";i:163;s:5:\"sajda\";b:0;}i:32;a:9:{s:6:\"number\";i:3442;s:4:\"text\";s:221:\"Et quand un mal touche les gens, ils invoquent leur Seigneur en revenant à Lui repentants. Puis s\'Il leur fait goûter de Sa part une miséricorde, voilà qu\'une partie d\'entre eux donnent à leur Seigneur des associés,\";s:13:\"numberInSurah\";i:33;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:408;s:4:\"ruku\";i:352;s:11:\"hizbQuarter\";i:163;s:5:\"sajda\";b:0;}i:33;a:9:{s:6:\"number\";i:3443;s:4:\"text\";s:116:\"en sorte qu\'ils deviennent ingrats envers ce que Nous leur avons donné. «Et jouissez donc. Vous saurez bientôt».\";s:13:\"numberInSurah\";i:34;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:408;s:4:\"ruku\";i:352;s:11:\"hizbQuarter\";i:163;s:5:\"sajda\";b:0;}i:34;a:9:{s:6:\"number\";i:3444;s:4:\"text\";s:108:\"Avons-Nous fait descendre sur eux une autorité (un Livre) telle qu\'elle parle de ce qu\'ils Lui associaient?\";s:13:\"numberInSurah\";i:35;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:408;s:4:\"ruku\";i:352;s:11:\"hizbQuarter\";i:163;s:5:\"sajda\";b:0;}i:35;a:9:{s:6:\"number\";i:3445;s:4:\"text\";s:187:\"Et quand Nous faisons goûter une miséricorde aux gens, ils en exultent. Mais si un malheur les atteint à cause de ce que leurs propres mains ont préparé, voilà qu\'ils désespèrent.\";s:13:\"numberInSurah\";i:36;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:408;s:4:\"ruku\";i:352;s:11:\"hizbQuarter\";i:163;s:5:\"sajda\";b:0;}i:36;a:9:{s:6:\"number\";i:3446;s:4:\"text\";s:130:\"N\'ont-ils pas vu qu\'Allah dispense Ses dons ou les restreint à qui Il veut? Il y a en cela des preuves pour des gens qui croient.\";s:13:\"numberInSurah\";i:37;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:408;s:4:\"ruku\";i:352;s:11:\"hizbQuarter\";i:163;s:5:\"sajda\";b:0;}i:37;a:9:{s:6:\"number\";i:3447;s:4:\"text\";s:197:\"Donne donc au proche parent son dû, ainsi qu\'au pauvre, et au voyageur en détresse. Cela est meilleur pour ceux qui recherchent la face d\'Allah (Sa satisfaction); et ce sont eux qui réussissent.\";s:13:\"numberInSurah\";i:38;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:408;s:4:\"ruku\";i:352;s:11:\"hizbQuarter\";i:163;s:5:\"sajda\";b:0;}i:38;a:9:{s:6:\"number\";i:3448;s:4:\"text\";s:272:\"Tout ce que vous donnerez à usure pour augmenter vos biens aux dépens des biens d\'autrui ne les accroît pas auprès d\'Allah, mais ce que vous donnez comme Zakât, tout en cherchant la Face d\'Allah (Sa satisfaction)... Ceux-là verront [leurs récompenses] multipliées.\";s:13:\"numberInSurah\";i:39;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:408;s:4:\"ruku\";i:352;s:11:\"hizbQuarter\";i:163;s:5:\"sajda\";b:0;}i:39;a:9:{s:6:\"number\";i:3449;s:4:\"text\";s:232:\"C\'est Allah qui vous a créés et vous a nourris. Ensuite Il vous fera mourir, puis Il vous redonnera vie. Y en a-t-il, parmi vos associés, qui fasse quoi que ce soit de tout cela? Gloire à Lui! Il transcende ce qu\'on Lui associe.\";s:13:\"numberInSurah\";i:40;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:408;s:4:\"ruku\";i:352;s:11:\"hizbQuarter\";i:163;s:5:\"sajda\";b:0;}i:40;a:9:{s:6:\"number\";i:3450;s:4:\"text\";s:231:\"La corruption est apparue sur la terre et dans la mer à cause de ce que les gens ont accompli de leurs propres mains; afin qu\'[Allah] leur fasse goûter une partie de ce qu\'ils ont œuvré; peut-être reviendront-ils (vers Allah).\";s:13:\"numberInSurah\";i:41;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:408;s:4:\"ruku\";i:353;s:11:\"hizbQuarter\";i:163;s:5:\"sajda\";b:0;}i:41;a:9:{s:6:\"number\";i:3451;s:4:\"text\";s:138:\"Dis: «Parcourez la terre et regardez ce qu\'il est advenu de ceux qui ont vécu avant. La plupart d\'entre eux étaient des associateurs».\";s:13:\"numberInSurah\";i:42;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:409;s:4:\"ruku\";i:353;s:11:\"hizbQuarter\";i:163;s:5:\"sajda\";b:0;}i:42;a:9:{s:6:\"number\";i:3452;s:4:\"text\";s:152:\"Dirige tout ton être vers la religion de droiture, avant que ne vienne d\'Allah un jour qu\'on ne peut repousser. Ce jour-là [les gens] seront divisés:\";s:13:\"numberInSurah\";i:43;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:409;s:4:\"ruku\";i:353;s:11:\"hizbQuarter\";i:163;s:5:\"sajda\";b:0;}i:43;a:9:{s:6:\"number\";i:3453;s:4:\"text\";s:161:\"Celui qui aura mécru subira [les conséquences] de son infidélité. Et quiconque aura œuvré en bien... C\'est pour eux-mêmes qu\'ils préparent (leur avenir),\";s:13:\"numberInSurah\";i:44;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:409;s:4:\"ruku\";i:353;s:11:\"hizbQuarter\";i:163;s:5:\"sajda\";b:0;}i:44;a:9:{s:6:\"number\";i:3454;s:4:\"text\";s:138:\"afin qu\'[Allah] récompense par Sa grâce ceux qui croient et accomplissent les bonnes œuvres. En vérité, Il n\'aime pas les infidèles.\";s:13:\"numberInSurah\";i:45;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:409;s:4:\"ruku\";i:353;s:11:\"hizbQuarter\";i:163;s:5:\"sajda\";b:0;}i:45;a:9:{s:6:\"number\";i:3455;s:4:\"text\";s:224:\"Parmi Ses signes, Il envoie les vents comme annonciateurs, pour vous faire goûter de Sa miséricorde et pour que le vaisseau vogue, par Son ordre, et que vous recherchiez de Sa grâce. Peut-être seriez-vous reconnaissants!\";s:13:\"numberInSurah\";i:46;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:409;s:4:\"ruku\";i:353;s:11:\"hizbQuarter\";i:163;s:5:\"sajda\";b:0;}i:46;a:9:{s:6:\"number\";i:3456;s:4:\"text\";s:237:\"Nous avons effectivement envoyé avant toi des Messagers vers leurs peuples et ils leur apportèrent les preuves. Nous Nous vengeâmes de ceux qui commirent les crimes [de la négation]; et c\'était Notre devoir de secourir les croyants.\";s:13:\"numberInSurah\";i:47;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:409;s:4:\"ruku\";i:353;s:11:\"hizbQuarter\";i:163;s:5:\"sajda\";b:0;}i:47;a:9:{s:6:\"number\";i:3457;s:4:\"text\";s:290:\"Allah, c\'est Lui qui envoie les vents qui soulèvent des nuages; puis Il les étend dans le ciel comme Il veut; et Il les met en morceaux. Tu vois alors la pluie sortir de leurs profondeurs. Puis, lorsqu\'Il atteint avec elle qui Il veut parmi Ses serviteurs, les voilà qui se réjouissent,\";s:13:\"numberInSurah\";i:48;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:409;s:4:\"ruku\";i:353;s:11:\"hizbQuarter\";i:163;s:5:\"sajda\";b:0;}i:48;a:9:{s:6:\"number\";i:3458;s:4:\"text\";s:92:\"même s\'ils étaient auparavant, avant qu\'on ne l\'ait fait descendre sur eux, désespérés.\";s:13:\"numberInSurah\";i:49;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:409;s:4:\"ruku\";i:353;s:11:\"hizbQuarter\";i:163;s:5:\"sajda\";b:0;}i:49;a:9:{s:6:\"number\";i:3459;s:4:\"text\";s:163:\"Regarde donc les effets de la miséricorde d\'Allah comment Il redonne la vie à la terre après sa mort. C\'est Lui qui fait revivre les morts et Il est Omnipotent.\";s:13:\"numberInSurah\";i:50;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:409;s:4:\"ruku\";i:353;s:11:\"hizbQuarter\";i:163;s:5:\"sajda\";b:0;}i:50;a:9:{s:6:\"number\";i:3460;s:4:\"text\";s:144:\"Et si Nous envoyons un vent et qu\'ils voient jaunir [leur végétation], ils demeurent après cela ingrats (oubliant les bienfaits antérieurs).\";s:13:\"numberInSurah\";i:51;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:410;s:4:\"ruku\";i:353;s:11:\"hizbQuarter\";i:163;s:5:\"sajda\";b:0;}i:51;a:9:{s:6:\"number\";i:3461;s:4:\"text\";s:130:\"En vérité, tu ne fais pas entendre les morts; et tu ne fais pas entendre aux sourds l\'appel, s\'ils s\'en vont en tournant le dos.\";s:13:\"numberInSurah\";i:52;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:410;s:4:\"ruku\";i:353;s:11:\"hizbQuarter\";i:163;s:5:\"sajda\";b:0;}i:52;a:9:{s:6:\"number\";i:3462;s:4:\"text\";s:172:\"Tu n\'es pas celui qui guide les aveugles hors de leur égarement. Tu ne fais entendre que ceux qui croient en Nos versets et qui sont alors entièrement soumis [musulmans].\";s:13:\"numberInSurah\";i:53;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:410;s:4:\"ruku\";i:353;s:11:\"hizbQuarter\";i:163;s:5:\"sajda\";b:0;}i:53;a:9:{s:6:\"number\";i:3463;s:4:\"text\";s:233:\"Allah, c\'est Lui qui vous a créés faibles; puis après la faiblesse, Il vous donne la force; puis après la force, Il vous réduit à la faiblesse et à la vieillesse: Il crée ce qu\'Il veut et c\'est Lui l\'Omniscient, l\'Omnipotent.\";s:13:\"numberInSurah\";i:54;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:410;s:4:\"ruku\";i:354;s:11:\"hizbQuarter\";i:164;s:5:\"sajda\";b:0;}i:54;a:9:{s:6:\"number\";i:3464;s:4:\"text\";s:150:\"Et le jour où l\'Heure arrivera, les criminels jureront qu\'ils n\'ont demeuré qu\'une heure. C\'est ainsi qu\'ils ont été détournés (de la vérité);\";s:13:\"numberInSurah\";i:55;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:410;s:4:\"ruku\";i:354;s:11:\"hizbQuarter\";i:164;s:5:\"sajda\";b:0;}i:55;a:9:{s:6:\"number\";i:3465;s:4:\"text\";s:216:\"tandis que ceux à qui le savoir et la foi furent donnés diront: «Vous avez demeuré d\'après le Décret d\'Allah, jusqu\'au Jour de la Résurrection, voici le Jour de la Résurrection, - mais vous ne saviez point».\";s:13:\"numberInSurah\";i:56;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:410;s:4:\"ruku\";i:354;s:11:\"hizbQuarter\";i:164;s:5:\"sajda\";b:0;}i:56;a:9:{s:6:\"number\";i:3466;s:4:\"text\";s:125:\"ce jour-là donc, les excuses ne seront pas utiles aux injustes et on ne leur demandera pas à chercher à plaire à [Allah].\";s:13:\"numberInSurah\";i:57;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:410;s:4:\"ruku\";i:354;s:11:\"hizbQuarter\";i:164;s:5:\"sajda\";b:0;}i:57;a:9:{s:6:\"number\";i:3467;s:4:\"text\";s:200:\"Et dans ce Coran, Nous avons certes cité, pour les gens, des exemples de toutes sortes. Et si tu leur apportes un prodige, ceux qui ne croient pas diront: «Certes, vous n\'êtes que des imposteurs».\";s:13:\"numberInSurah\";i:58;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:410;s:4:\"ruku\";i:354;s:11:\"hizbQuarter\";i:164;s:5:\"sajda\";b:0;}i:58;a:9:{s:6:\"number\";i:3468;s:4:\"text\";s:65:\"C\'est ainsi qu\'Allah scelle les cœurs de ceux qui ne savent pas.\";s:13:\"numberInSurah\";i:59;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:410;s:4:\"ruku\";i:354;s:11:\"hizbQuarter\";i:164;s:5:\"sajda\";b:0;}i:59;a:9:{s:6:\"number\";i:3469;s:4:\"text\";s:118:\"Sois donc patient, car la promesse d\'Allah est vérité. Et que ceux qui ne croient pas fermement ne t\'ébranlent pas!\";s:13:\"numberInSurah\";i:60;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:410;s:4:\"ruku\";i:354;s:11:\"hizbQuarter\";i:164;s:5:\"sajda\";b:0;}}s:7:\"edition\";a:7:{s:10:\"identifier\";s:13:\"fr.hamidullah\";s:8:\"language\";s:2:\"fr\";s:4:\"name\";s:10:\"Hamidullah\";s:11:\"englishName\";s:19:\"Muhammad Hamidullah\";s:6:\"format\";s:4:\"text\";s:4:\"type\";s:11:\"translation\";s:9:\"direction\";s:3:\"ltr\";}}', 1794581364);
INSERT INTO `cache` (`key`, `value`, `expiration`) VALUES
('quranapp-cache-surah_31_ar.uthmani', 'a:8:{s:6:\"number\";i:31;s:4:\"name\";s:33:\"سُورَةُ لُقۡمَانَ\";s:11:\"englishName\";s:6:\"Luqman\";s:22:\"englishNameTranslation\";s:6:\"Luqman\";s:14:\"revelationType\";s:6:\"Meccan\";s:13:\"numberOfAyahs\";i:34;s:5:\"ayahs\";a:34:{i:0;a:9:{s:6:\"number\";i:3470;s:4:\"text\";s:87:\"بِسۡمِ ٱللَّهِ ٱلرَّحۡمَـٰنِ ٱلرَّحِیمِ الۤمۤ\n\";s:13:\"numberInSurah\";i:1;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:411;s:4:\"ruku\";i:355;s:11:\"hizbQuarter\";i:164;s:5:\"sajda\";b:0;}i:1;a:9:{s:6:\"number\";i:3471;s:4:\"text\";s:76:\"تِلۡكَ ءَایَـٰتُ ٱلۡكِتَـٰبِ ٱلۡحَكِیمِ\n\";s:13:\"numberInSurah\";i:2;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:411;s:4:\"ruku\";i:355;s:11:\"hizbQuarter\";i:164;s:5:\"sajda\";b:0;}i:2;a:9:{s:6:\"number\";i:3472;s:4:\"text\";s:67:\"هُدࣰى وَرَحۡمَةࣰ لِّلۡمُحۡسِنِینَ\n\";s:13:\"numberInSurah\";i:3;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:411;s:4:\"ruku\";i:355;s:11:\"hizbQuarter\";i:164;s:5:\"sajda\";b:0;}i:3;a:9:{s:6:\"number\";i:3473;s:4:\"text\";s:181:\"ٱلَّذِینَ یُقِیمُونَ ٱلصَّلَوٰةَ وَیُؤۡتُونَ ٱلزَّكَوٰةَ وَهُم بِٱلۡـَٔاخِرَةِ هُمۡ یُوقِنُونَ\n\";s:13:\"numberInSurah\";i:4;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:411;s:4:\"ruku\";i:355;s:11:\"hizbQuarter\";i:164;s:5:\"sajda\";b:0;}i:4;a:9:{s:6:\"number\";i:3474;s:4:\"text\";s:157:\"أُو۟لَـٰۤىِٕكَ عَلَىٰ هُدࣰى مِّن رَّبِّهِمۡۖ وَأُو۟لَـٰۤىِٕكَ هُمُ ٱلۡمُفۡلِحُونَ\n\";s:13:\"numberInSurah\";i:5;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:411;s:4:\"ruku\";i:355;s:11:\"hizbQuarter\";i:164;s:5:\"sajda\";b:0;}i:5;a:9:{s:6:\"number\";i:3475;s:4:\"text\";s:299:\"وَمِنَ ٱلنَّاسِ مَن یَشۡتَرِی لَهۡوَ ٱلۡحَدِیثِ لِیُضِلَّ عَن سَبِیلِ ٱللَّهِ بِغَیۡرِ عِلۡمࣲ وَیَتَّخِذَهَا هُزُوًاۚ أُو۟لَـٰۤىِٕكَ لَهُمۡ عَذَابࣱ مُّهِینࣱ\n\";s:13:\"numberInSurah\";i:6;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:411;s:4:\"ruku\";i:355;s:11:\"hizbQuarter\";i:164;s:5:\"sajda\";b:0;}i:6;a:9:{s:6:\"number\";i:3476;s:4:\"text\";s:282:\"وَإِذَا تُتۡلَىٰ عَلَیۡهِ ءَایَـٰتُنَا وَلَّىٰ مُسۡتَكۡبِرࣰا كَأَن لَّمۡ یَسۡمَعۡهَا كَأَنَّ فِیۤ أُذُنَیۡهِ وَقۡرࣰاۖ فَبَشِّرۡهُ بِعَذَابٍ أَلِیمٍ\n\";s:13:\"numberInSurah\";i:7;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:411;s:4:\"ruku\";i:355;s:11:\"hizbQuarter\";i:164;s:5:\"sajda\";b:0;}i:7;a:9:{s:6:\"number\";i:3477;s:4:\"text\";s:158:\"إِنَّ ٱلَّذِینَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ لَهُمۡ جَنَّـٰتُ ٱلنَّعِیمِ\n\";s:13:\"numberInSurah\";i:8;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:411;s:4:\"ruku\";i:355;s:11:\"hizbQuarter\";i:164;s:5:\"sajda\";b:0;}i:8;a:9:{s:6:\"number\";i:3478;s:4:\"text\";s:137:\"خَـٰلِدِینَ فِیهَاۖ وَعۡدَ ٱللَّهِ حَقࣰّاۚ وَهُوَ ٱلۡعَزِیزُ ٱلۡحَكِیمُ\n\";s:13:\"numberInSurah\";i:9;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:411;s:4:\"ruku\";i:355;s:11:\"hizbQuarter\";i:164;s:5:\"sajda\";b:0;}i:9;a:9:{s:6:\"number\";i:3479;s:4:\"text\";s:437:\"خَلَقَ ٱلسَّمَـٰوَ ٰ⁠تِ بِغَیۡرِ عَمَدࣲ تَرَوۡنَهَاۖ وَأَلۡقَىٰ فِی ٱلۡأَرۡضِ رَوَ ٰ⁠سِیَ أَن تَمِیدَ بِكُمۡ وَبَثَّ فِیهَا مِن كُلِّ دَاۤبَّةࣲۚ وَأَنزَلۡنَا مِنَ ٱلسَّمَاۤءِ مَاۤءࣰ فَأَنۢبَتۡنَا فِیهَا مِن كُلِّ زَوۡجࣲ كَرِیمٍ\n\";s:13:\"numberInSurah\";i:10;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:411;s:4:\"ruku\";i:355;s:11:\"hizbQuarter\";i:164;s:5:\"sajda\";b:0;}i:10;a:9:{s:6:\"number\";i:3480;s:4:\"text\";s:216:\"هَـٰذَا خَلۡقُ ٱللَّهِ فَأَرُونِی مَاذَا خَلَقَ ٱلَّذِینَ مِن دُونِهِۦۚ بَلِ ٱلظَّـٰلِمُونَ فِی ضَلَـٰلࣲ مُّبِینࣲ\n\";s:13:\"numberInSurah\";i:11;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:411;s:4:\"ruku\";i:355;s:11:\"hizbQuarter\";i:164;s:5:\"sajda\";b:0;}i:11;a:9:{s:6:\"number\";i:3481;s:4:\"text\";s:299:\"وَلَقَدۡ ءَاتَیۡنَا لُقۡمَـٰنَ ٱلۡحِكۡمَةَ أَنِ ٱشۡكُرۡ لِلَّهِۚ وَمَن یَشۡكُرۡ فَإِنَّمَا یَشۡكُرُ لِنَفۡسِهِۦۖ وَمَن كَفَرَ فَإِنَّ ٱللَّهَ غَنِیٌّ حَمِیدࣱ\n\";s:13:\"numberInSurah\";i:12;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:412;s:4:\"ruku\";i:356;s:11:\"hizbQuarter\";i:164;s:5:\"sajda\";b:0;}i:12;a:9:{s:6:\"number\";i:3482;s:4:\"text\";s:229:\"وَإِذۡ قَالَ لُقۡمَـٰنُ لِٱبۡنِهِۦ وَهُوَ یَعِظُهُۥ یَـٰبُنَیَّ لَا تُشۡرِكۡ بِٱللَّهِۖ إِنَّ ٱلشِّرۡكَ لَظُلۡمٌ عَظِیمࣱ\n\";s:13:\"numberInSurah\";i:13;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:412;s:4:\"ruku\";i:356;s:11:\"hizbQuarter\";i:164;s:5:\"sajda\";b:0;}i:13;a:9:{s:6:\"number\";i:3483;s:4:\"text\";s:320:\"وَوَصَّیۡنَا ٱلۡإِنسَـٰنَ بِوَ ٰ⁠لِدَیۡهِ حَمَلَتۡهُ أُمُّهُۥ وَهۡنًا عَلَىٰ وَهۡنࣲ وَفِصَـٰلُهُۥ فِی عَامَیۡنِ أَنِ ٱشۡكُرۡ لِی وَلِوَ ٰ⁠لِدَیۡكَ إِلَیَّ ٱلۡمَصِیرُ\n\";s:13:\"numberInSurah\";i:14;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:412;s:4:\"ruku\";i:356;s:11:\"hizbQuarter\";i:164;s:5:\"sajda\";b:0;}i:14;a:9:{s:6:\"number\";i:3484;s:4:\"text\";s:457:\"وَإِن جَـٰهَدَاكَ عَلَىٰۤ أَن تُشۡرِكَ بِی مَا لَیۡسَ لَكَ بِهِۦ عِلۡمࣱ فَلَا تُطِعۡهُمَاۖ وَصَاحِبۡهُمَا فِی ٱلدُّنۡیَا مَعۡرُوفࣰاۖ وَٱتَّبِعۡ سَبِیلَ مَنۡ أَنَابَ إِلَیَّۚ ثُمَّ إِلَیَّ مَرۡجِعُكُمۡ فَأُنَبِّئُكُم بِمَا كُنتُمۡ تَعۡمَلُونَ\n\";s:13:\"numberInSurah\";i:15;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:412;s:4:\"ruku\";i:356;s:11:\"hizbQuarter\";i:164;s:5:\"sajda\";b:0;}i:15;a:9:{s:6:\"number\";i:3485;s:4:\"text\";s:345:\"یَـٰبُنَیَّ إِنَّهَاۤ إِن تَكُ مِثۡقَالَ حَبَّةࣲ مِّنۡ خَرۡدَلࣲ فَتَكُن فِی صَخۡرَةٍ أَوۡ فِی ٱلسَّمَـٰوَ ٰ⁠تِ أَوۡ فِی ٱلۡأَرۡضِ یَأۡتِ بِهَا ٱللَّهُۚ إِنَّ ٱللَّهَ لَطِیفٌ خَبِیرࣱ\n\";s:13:\"numberInSurah\";i:16;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:412;s:4:\"ruku\";i:356;s:11:\"hizbQuarter\";i:164;s:5:\"sajda\";b:0;}i:16;a:9:{s:6:\"number\";i:3486;s:4:\"text\";s:287:\"یَـٰبُنَیَّ أَقِمِ ٱلصَّلَوٰةَ وَأۡمُرۡ بِٱلۡمَعۡرُوفِ وَٱنۡهَ عَنِ ٱلۡمُنكَرِ وَٱصۡبِرۡ عَلَىٰ مَاۤ أَصَابَكَۖ إِنَّ ذَ ٰ⁠لِكَ مِنۡ عَزۡمِ ٱلۡأُمُورِ\n\";s:13:\"numberInSurah\";i:17;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:412;s:4:\"ruku\";i:356;s:11:\"hizbQuarter\";i:164;s:5:\"sajda\";b:0;}i:17;a:9:{s:6:\"number\";i:3487;s:4:\"text\";s:226:\"وَلَا تُصَعِّرۡ خَدَّكَ لِلنَّاسِ وَلَا تَمۡشِ فِی ٱلۡأَرۡضِ مَرَحًاۖ إِنَّ ٱللَّهَ لَا یُحِبُّ كُلَّ مُخۡتَالࣲ فَخُورࣲ\n\";s:13:\"numberInSurah\";i:18;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:412;s:4:\"ruku\";i:356;s:11:\"hizbQuarter\";i:164;s:5:\"sajda\";b:0;}i:18;a:9:{s:6:\"number\";i:3488;s:4:\"text\";s:183:\"وَٱقۡصِدۡ فِی مَشۡیِكَ وَٱغۡضُضۡ مِن صَوۡتِكَۚ إِنَّ أَنكَرَ ٱلۡأَصۡوَ ٰ⁠تِ لَصَوۡتُ ٱلۡحَمِیرِ\n\";s:13:\"numberInSurah\";i:19;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:412;s:4:\"ruku\";i:356;s:11:\"hizbQuarter\";i:164;s:5:\"sajda\";b:0;}i:19;a:9:{s:6:\"number\";i:3489;s:4:\"text\";s:460:\"أَلَمۡ تَرَوۡا۟ أَنَّ ٱللَّهَ سَخَّرَ لَكُم مَّا فِی ٱلسَّمَـٰوَ ٰ⁠تِ وَمَا فِی ٱلۡأَرۡضِ وَأَسۡبَغَ عَلَیۡكُمۡ نِعَمَهُۥ ظَـٰهِرَةࣰ وَبَاطِنَةࣰۗ وَمِنَ ٱلنَّاسِ مَن یُجَـٰدِلُ فِی ٱللَّهِ بِغَیۡرِ عِلۡمࣲ وَلَا هُدࣰى وَلَا كِتَـٰبࣲ مُّنِیرࣲ\n\";s:13:\"numberInSurah\";i:20;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:413;s:4:\"ruku\";i:357;s:11:\"hizbQuarter\";i:164;s:5:\"sajda\";b:0;}i:20;a:9:{s:6:\"number\";i:3490;s:4:\"text\";s:345:\"وَإِذَا قِیلَ لَهُمُ ٱتَّبِعُوا۟ مَاۤ أَنزَلَ ٱللَّهُ قَالُوا۟ بَلۡ نَتَّبِعُ مَا وَجَدۡنَا عَلَیۡهِ ءَابَاۤءَنَاۤۚ أَوَلَوۡ كَانَ ٱلشَّیۡطَـٰنُ یَدۡعُوهُمۡ إِلَىٰ عَذَابِ ٱلسَّعِیرِ\n\";s:13:\"numberInSurah\";i:21;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:413;s:4:\"ruku\";i:357;s:11:\"hizbQuarter\";i:164;s:5:\"sajda\";b:0;}i:21;a:9:{s:6:\"number\";i:3491;s:4:\"text\";s:269:\"۞ وَمَن یُسۡلِمۡ وَجۡهَهُۥۤ إِلَى ٱللَّهِ وَهُوَ مُحۡسِنࣱ فَقَدِ ٱسۡتَمۡسَكَ بِٱلۡعُرۡوَةِ ٱلۡوُثۡقَىٰۗ وَإِلَى ٱللَّهِ عَـٰقِبَةُ ٱلۡأُمُورِ\n\";s:13:\"numberInSurah\";i:22;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:413;s:4:\"ruku\";i:357;s:11:\"hizbQuarter\";i:165;s:5:\"sajda\";b:0;}i:22;a:9:{s:6:\"number\";i:3492;s:4:\"text\";s:263:\"وَمَن كَفَرَ فَلَا یَحۡزُنكَ كُفۡرُهُۥۤۚ إِلَیۡنَا مَرۡجِعُهُمۡ فَنُنَبِّئُهُم بِمَا عَمِلُوۤا۟ۚ إِنَّ ٱللَّهَ عَلِیمُۢ بِذَاتِ ٱلصُّدُورِ\n\";s:13:\"numberInSurah\";i:23;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:413;s:4:\"ruku\";i:357;s:11:\"hizbQuarter\";i:165;s:5:\"sajda\";b:0;}i:23;a:9:{s:6:\"number\";i:3493;s:4:\"text\";s:127:\"نُمَتِّعُهُمۡ قَلِیلࣰا ثُمَّ نَضۡطَرُّهُمۡ إِلَىٰ عَذَابٍ غَلِیظࣲ\n\";s:13:\"numberInSurah\";i:24;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:413;s:4:\"ruku\";i:357;s:11:\"hizbQuarter\";i:165;s:5:\"sajda\";b:0;}i:24;a:9:{s:6:\"number\";i:3494;s:4:\"text\";s:273:\"وَلَىِٕن سَأَلۡتَهُم مَّنۡ خَلَقَ ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضَ لَیَقُولُنَّ ٱللَّهُۚ قُلِ ٱلۡحَمۡدُ لِلَّهِۚ بَلۡ أَكۡثَرُهُمۡ لَا یَعۡلَمُونَ\n\";s:13:\"numberInSurah\";i:25;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:413;s:4:\"ruku\";i:357;s:11:\"hizbQuarter\";i:165;s:5:\"sajda\";b:0;}i:25;a:9:{s:6:\"number\";i:3495;s:4:\"text\";s:166:\"لِلَّهِ مَا فِی ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِۚ إِنَّ ٱللَّهَ هُوَ ٱلۡغَنِیُّ ٱلۡحَمِیدُ\n\";s:13:\"numberInSurah\";i:26;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:413;s:4:\"ruku\";i:357;s:11:\"hizbQuarter\";i:165;s:5:\"sajda\";b:0;}i:26;a:9:{s:6:\"number\";i:3496;s:4:\"text\";s:330:\"وَلَوۡ أَنَّمَا فِی ٱلۡأَرۡضِ مِن شَجَرَةٍ أَقۡلَـٰمࣱ وَٱلۡبَحۡرُ یَمُدُّهُۥ مِنۢ بَعۡدِهِۦ سَبۡعَةُ أَبۡحُرࣲ مَّا نَفِدَتۡ كَلِمَـٰتُ ٱللَّهِۚ إِنَّ ٱللَّهَ عَزِیزٌ حَكِیمࣱ\n\";s:13:\"numberInSurah\";i:27;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:413;s:4:\"ruku\";i:357;s:11:\"hizbQuarter\";i:165;s:5:\"sajda\";b:0;}i:27;a:9:{s:6:\"number\";i:3497;s:4:\"text\";s:178:\"مَّا خَلۡقُكُمۡ وَلَا بَعۡثُكُمۡ إِلَّا كَنَفۡسࣲ وَ ٰ⁠حِدَةٍۚ إِنَّ ٱللَّهَ سَمِیعُۢ بَصِیرٌ\n\";s:13:\"numberInSurah\";i:28;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:413;s:4:\"ruku\";i:357;s:11:\"hizbQuarter\";i:165;s:5:\"sajda\";b:0;}i:28;a:9:{s:6:\"number\";i:3498;s:4:\"text\";s:393:\"أَلَمۡ تَرَ أَنَّ ٱللَّهَ یُولِجُ ٱلَّیۡلَ فِی ٱلنَّهَارِ وَیُولِجُ ٱلنَّهَارَ فِی ٱلَّیۡلِ وَسَخَّرَ ٱلشَّمۡسَ وَٱلۡقَمَرَۖ كُلࣱّ یَجۡرِیۤ إِلَىٰۤ أَجَلࣲ مُّسَمࣰّى وَأَنَّ ٱللَّهَ بِمَا تَعۡمَلُونَ خَبِیرࣱ\n\";s:13:\"numberInSurah\";i:29;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:414;s:4:\"ruku\";i:357;s:11:\"hizbQuarter\";i:165;s:5:\"sajda\";b:0;}i:29;a:9:{s:6:\"number\";i:3499;s:4:\"text\";s:244:\"ذَ ٰ⁠لِكَ بِأَنَّ ٱللَّهَ هُوَ ٱلۡحَقُّ وَأَنَّ مَا یَدۡعُونَ مِن دُونِهِ ٱلۡبَـٰطِلُ وَأَنَّ ٱللَّهَ هُوَ ٱلۡعَلِیُّ ٱلۡكَبِیرُ\n\";s:13:\"numberInSurah\";i:30;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:414;s:4:\"ruku\";i:357;s:11:\"hizbQuarter\";i:165;s:5:\"sajda\";b:0;}i:30;a:9:{s:6:\"number\";i:3500;s:4:\"text\";s:308:\"أَلَمۡ تَرَ أَنَّ ٱلۡفُلۡكَ تَجۡرِی فِی ٱلۡبَحۡرِ بِنِعۡمَتِ ٱللَّهِ لِیُرِیَكُم مِّنۡ ءَایَـٰتِهِۦۤۚ إِنَّ فِی ذَ ٰ⁠لِكَ لَـَٔایَـٰتࣲ لِّكُلِّ صَبَّارࣲ شَكُورࣲ\n\";s:13:\"numberInSurah\";i:31;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:414;s:4:\"ruku\";i:357;s:11:\"hizbQuarter\";i:165;s:5:\"sajda\";b:0;}i:31;a:9:{s:6:\"number\";i:3501;s:4:\"text\";s:386:\"وَإِذَا غَشِیَهُم مَّوۡجࣱ كَٱلظُّلَلِ دَعَوُا۟ ٱللَّهَ مُخۡلِصِینَ لَهُ ٱلدِّینَ فَلَمَّا نَجَّىٰهُمۡ إِلَى ٱلۡبَرِّ فَمِنۡهُم مُّقۡتَصِدࣱۚ وَمَا یَجۡحَدُ بِـَٔایَـٰتِنَاۤ إِلَّا كُلُّ خَتَّارࣲ كَفُورࣲ\n\";s:13:\"numberInSurah\";i:32;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:414;s:4:\"ruku\";i:357;s:11:\"hizbQuarter\";i:165;s:5:\"sajda\";b:0;}i:32;a:9:{s:6:\"number\";i:3502;s:4:\"text\";s:498:\"یَـٰۤأَیُّهَا ٱلنَّاسُ ٱتَّقُوا۟ رَبَّكُمۡ وَٱخۡشَوۡا۟ یَوۡمࣰا لَّا یَجۡزِی وَالِدٌ عَن وَلَدِهِۦ وَلَا مَوۡلُودٌ هُوَ جَازٍ عَن وَالِدِهِۦ شَیۡـًٔاۚ إِنَّ وَعۡدَ ٱللَّهِ حَقࣱّۖ فَلَا تَغُرَّنَّكُمُ ٱلۡحَیَوٰةُ ٱلدُّنۡیَا وَلَا یَغُرَّنَّكُم بِٱللَّهِ ٱلۡغَرُورُ\n\";s:13:\"numberInSurah\";i:33;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:414;s:4:\"ruku\";i:357;s:11:\"hizbQuarter\";i:165;s:5:\"sajda\";b:0;}i:33;a:9:{s:6:\"number\";i:3503;s:4:\"text\";s:412:\"إِنَّ ٱللَّهَ عِندَهُۥ عِلۡمُ ٱلسَّاعَةِ وَیُنَزِّلُ ٱلۡغَیۡثَ وَیَعۡلَمُ مَا فِی ٱلۡأَرۡحَامِۖ وَمَا تَدۡرِی نَفۡسࣱ مَّاذَا تَكۡسِبُ غَدࣰاۖ وَمَا تَدۡرِی نَفۡسُۢ بِأَیِّ أَرۡضࣲ تَمُوتُۚ إِنَّ ٱللَّهَ عَلِیمٌ خَبِیرُۢ\n\";s:13:\"numberInSurah\";i:34;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:414;s:4:\"ruku\";i:357;s:11:\"hizbQuarter\";i:165;s:5:\"sajda\";b:0;}}s:7:\"edition\";a:7:{s:10:\"identifier\";s:27:\"quran-uthmani-quran-academy\";s:8:\"language\";s:2:\"ar\";s:4:\"name\";s:67:\"القرآن الكريم برسم العثماني (quran-academy)\";s:11:\"englishName\";s:78:\"Modified Quran Uthmani Text from the Quran Academy to work with the Kitab font\";s:6:\"format\";s:4:\"text\";s:4:\"type\";s:5:\"quran\";s:9:\"direction\";s:3:\"rtl\";}}', 1794581365),
('quranapp-cache-surah_31_fr.hamidullah', 'a:8:{s:6:\"number\";i:31;s:4:\"name\";s:33:\"سُورَةُ لُقۡمَانَ\";s:11:\"englishName\";s:6:\"Luqman\";s:22:\"englishNameTranslation\";s:6:\"Luqman\";s:14:\"revelationType\";s:6:\"Meccan\";s:13:\"numberOfAyahs\";i:34;s:5:\"ayahs\";a:34:{i:0;a:9:{s:6:\"number\";i:3470;s:4:\"text\";s:17:\"Alif, Lâm, Mîm.\";s:13:\"numberInSurah\";i:1;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:411;s:4:\"ruku\";i:355;s:11:\"hizbQuarter\";i:164;s:5:\"sajda\";b:0;}i:1;a:9:{s:6:\"number\";i:3471;s:4:\"text\";s:44:\"Voici les versets du Livre plein de sagesse,\";s:13:\"numberInSurah\";i:2;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:411;s:4:\"ruku\";i:355;s:11:\"hizbQuarter\";i:164;s:5:\"sajda\";b:0;}i:2;a:9:{s:6:\"number\";i:3472;s:4:\"text\";s:52:\"c\'est un guide et une miséricorde aux bienfaisants,\";s:13:\"numberInSurah\";i:3;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:411;s:4:\"ruku\";i:355;s:11:\"hizbQuarter\";i:164;s:5:\"sajda\";b:0;}i:3;a:9:{s:6:\"number\";i:3473;s:4:\"text\";s:94:\"qui accomplissent la Salât, acquittent la Zakât et qui croient avec certitude en l\'au-delà.\";s:13:\"numberInSurah\";i:4;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:411;s:4:\"ruku\";i:355;s:11:\"hizbQuarter\";i:164;s:5:\"sajda\";b:0;}i:4;a:9:{s:6:\"number\";i:3474;s:4:\"text\";s:82:\"Ceux-là sont sur le chemin droit de leur Seigneur et ce sont eux les bienheureux.\";s:13:\"numberInSurah\";i:5;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:411;s:4:\"ruku\";i:355;s:11:\"hizbQuarter\";i:164;s:5:\"sajda\";b:0;}i:5;a:9:{s:6:\"number\";i:3475;s:4:\"text\";s:208:\"Et, parmi les hommes, il est [quelqu\'un] qui, dénué de science, achète de plaisants discours pour égarer hors du chemin d\'Allah et pour le prendre en raillerie. Ceux-là subiront un châtiment avilissant.\";s:13:\"numberInSurah\";i:6;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:411;s:4:\"ruku\";i:355;s:11:\"hizbQuarter\";i:164;s:5:\"sajda\";b:0;}i:6;a:9:{s:6:\"number\";i:3476;s:4:\"text\";s:206:\"Et quand on lui récite Nos versets, il tourne le dos avec orgueil, comme s\'il ne les avait point entendus, comme s\'il y avait un poids dans ses oreilles. Fais-lui donc l\'annonce d\'un châtiment douloureux.\";s:13:\"numberInSurah\";i:7;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:411;s:4:\"ruku\";i:355;s:11:\"hizbQuarter\";i:164;s:5:\"sajda\";b:0;}i:7;a:9:{s:6:\"number\";i:3477;s:4:\"text\";s:85:\"Ceux qui croient et accomplissent les bonnes œuvres auront les Jardins des délices,\";s:13:\"numberInSurah\";i:8;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:411;s:4:\"ruku\";i:355;s:11:\"hizbQuarter\";i:164;s:5:\"sajda\";b:0;}i:8;a:9:{s:6:\"number\";i:3478;s:4:\"text\";s:106:\"pour y demeurer éternellement, - c\'est en vérité une promesse d\'Allah-. C\'est Lui le Puissant, le Sage.\";s:13:\"numberInSurah\";i:9;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:411;s:4:\"ruku\";i:355;s:11:\"hizbQuarter\";i:164;s:5:\"sajda\";b:0;}i:9;a:9:{s:6:\"number\";i:3479;s:4:\"text\";s:338:\"Il a créé les cieux sans piliers que vous puissiez voir; et Il a enfoncé des montagnes fermes dans la terre pour l\'empêcher de basculer avec vous; et Il y a propagé des animaux de toute espèce. Et du ciel, Nous avons fait descendre une eau, avec laquelle Nous avons fait pousser des plantes productives par couples de toute espèce.\";s:13:\"numberInSurah\";i:10;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:411;s:4:\"ruku\";i:355;s:11:\"hizbQuarter\";i:164;s:5:\"sajda\";b:0;}i:10;a:9:{s:6:\"number\";i:3480;s:4:\"text\";s:151:\"«Voilà la création d\'Allah. Montrez-Moi donc ce qu\'ont créé, ceux qui sont en dehors de Lui?» Mais les injustes sont dans un égarement évident.\";s:13:\"numberInSurah\";i:11;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:411;s:4:\"ruku\";i:355;s:11:\"hizbQuarter\";i:164;s:5:\"sajda\";b:0;}i:11;a:9:{s:6:\"number\";i:3481;s:4:\"text\";s:261:\"Nous avons effectivement donné à Luqmân la sagesse: «Sois reconnaissant à Allah, car quiconque est reconnaissant, n\'est reconnaissant que pour soi-même; quant à celui qui est ingrat... En vérité, Allah se dispense de tout, et Il est digne de louange».\";s:13:\"numberInSurah\";i:12;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:412;s:4:\"ruku\";i:356;s:11:\"hizbQuarter\";i:164;s:5:\"sajda\";b:0;}i:12;a:9:{s:6:\"number\";i:3482;s:4:\"text\";s:170:\"Et lorsque Luqmân dit à son fils tout en l\'exhortant: «O mon fils, ne donne pas d\'associé à Allah, car l\'association à [Allah] est vraiment une injustice énorme.»\";s:13:\"numberInSurah\";i:13;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:412;s:4:\"ruku\";i:356;s:11:\"hizbQuarter\";i:164;s:5:\"sajda\";b:0;}i:13;a:9:{s:6:\"number\";i:3483;s:4:\"text\";s:256:\"Nous avons commandé à l\'homme [la bienfaisance envers] ses père et mère; sa mère l\'a porté [subissant pour lui] peine sur peine: son sevrage a lieu à deux ans. «Sois reconnaissant envers Moi ainsi qu\'envers tes parents. Vers Moi est la destination.\";s:13:\"numberInSurah\";i:14;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:412;s:4:\"ruku\";i:356;s:11:\"hizbQuarter\";i:164;s:5:\"sajda\";b:0;}i:14;a:9:{s:6:\"number\";i:3484;s:4:\"text\";s:296:\"Et si tous deux te forcent à M\'associer ce dont tu n\'as aucune connaissance, alors ne leur obéis pas; mais reste avec eux ici-bas de façon convenable. Et suis le sentier de celui qui se tourne vers Moi. Vers Moi, ensuite, est votre retour, et alors Je vous informerai de ce que vous faisiez».\";s:13:\"numberInSurah\";i:15;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:412;s:4:\"ruku\";i:356;s:11:\"hizbQuarter\";i:164;s:5:\"sajda\";b:0;}i:15;a:9:{s:6:\"number\";i:3485;s:4:\"text\";s:189:\"«O mon enfant, fût-ce le poids d\'un grain de moutarde, au fond d\'un rocher, ou dans les cieux ou dans la terre, Allah le fera venir. Allah est infiniment Doux et Parfaitement Connaisseur.\";s:13:\"numberInSurah\";i:16;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:412;s:4:\"ruku\";i:356;s:11:\"hizbQuarter\";i:164;s:5:\"sajda\";b:0;}i:16;a:9:{s:6:\"number\";i:3486;s:4:\"text\";s:179:\"O mon enfant accomplis la Salât, commande le convenable, interdis le blâmable et endure ce qui t\'arrive avec patience. Telle est la résolution à prendre dans toute entreprise!\";s:13:\"numberInSurah\";i:17;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:412;s:4:\"ruku\";i:356;s:11:\"hizbQuarter\";i:164;s:5:\"sajda\";b:0;}i:17;a:9:{s:6:\"number\";i:3487;s:4:\"text\";s:140:\"Et ne détourne pas ton visage des hommes, et ne foule pas la terre avec arrogance: car Allah n\'aime pas le présomptueux plein de gloriole.\";s:13:\"numberInSurah\";i:18;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:412;s:4:\"ruku\";i:356;s:11:\"hizbQuarter\";i:164;s:5:\"sajda\";b:0;}i:18;a:9:{s:6:\"number\";i:3488;s:4:\"text\";s:115:\"Sois modeste dans ta démarche, et baisse ta voix, car la plus détestée des voix, c\'est bien la voix des ânes».\";s:13:\"numberInSurah\";i:19;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:412;s:4:\"ruku\";i:356;s:11:\"hizbQuarter\";i:164;s:5:\"sajda\";b:0;}i:19;a:9:{s:6:\"number\";i:3489;s:4:\"text\";s:256:\"Ne voyez-vous pas qu\'Allah vous a assujetti ce qui est dans les cieux et sur la terre? Et Il vous a comblés de Ses bienfaits apparents et cachés. Et parmi les gens, il y en a qui disputent à propos d\'Allah, sans science, ni guidée, ni Livre éclairant.\";s:13:\"numberInSurah\";i:20;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:413;s:4:\"ruku\";i:357;s:11:\"hizbQuarter\";i:164;s:5:\"sajda\";b:0;}i:20;a:9:{s:6:\"number\";i:3490;s:4:\"text\";s:220:\"Et quand on leur dit: «Suivez ce qu\'Allah a fait descendre», ils disent: «Nous suivons plutôt ce sur quoi nous avons trouvé nos ancêtres». Est-ce donc même si le Diable les appelait au châtiment de la fournaise!\";s:13:\"numberInSurah\";i:21;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:413;s:4:\"ruku\";i:357;s:11:\"hizbQuarter\";i:164;s:5:\"sajda\";b:0;}i:21;a:9:{s:6:\"number\";i:3491;s:4:\"text\";s:158:\"Et quiconque soumet son être à Allah, tout en étant bienfaisant, s\'accroche réellement à l\'anse la plus ferme. La fin de toute chose appartient à Allah.\";s:13:\"numberInSurah\";i:22;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:413;s:4:\"ruku\";i:357;s:11:\"hizbQuarter\";i:165;s:5:\"sajda\";b:0;}i:22;a:9:{s:6:\"number\";i:3492;s:4:\"text\";s:177:\"Celui qui a mécru, que sa mécréance ne t\'afflige pas: vers Nous sera leur retour et Nous les informerons de ce qu\'ils faisaient. Allah connaît bien le contenu des poitrines.\";s:13:\"numberInSurah\";i:23;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:413;s:4:\"ruku\";i:357;s:11:\"hizbQuarter\";i:165;s:5:\"sajda\";b:0;}i:23;a:9:{s:6:\"number\";i:3493;s:4:\"text\";s:104:\"Nous leur donnons de la jouissance pour peu de temps; ensuite Nous les forcerons vers un dur châtiment.\";s:13:\"numberInSurah\";i:24;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:413;s:4:\"ruku\";i:357;s:11:\"hizbQuarter\";i:165;s:5:\"sajda\";b:0;}i:24;a:9:{s:6:\"number\";i:3494;s:4:\"text\";s:163:\"Si tu leur demandes: «Qui a créé les cieux et la terre?», ils diront, certes: «Allah!» Dis: «Louange à Allah!». Mais la plupart d\'entre eux ne savent pas.\";s:13:\"numberInSurah\";i:25;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:413;s:4:\"ruku\";i:357;s:11:\"hizbQuarter\";i:165;s:5:\"sajda\";b:0;}i:25;a:9:{s:6:\"number\";i:3495;s:4:\"text\";s:134:\"A Allah appartient tout ce qui est dans les cieux et en terre. Allah est Celui qui se suffit à Lui-même, Il est Le Digne de louange!\";s:13:\"numberInSurah\";i:26;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:413;s:4:\"ruku\";i:357;s:11:\"hizbQuarter\";i:165;s:5:\"sajda\";b:0;}i:26;a:9:{s:6:\"number\";i:3496;s:4:\"text\";s:260:\"Quand bien même tous les arbres de la terre se changeraient en calames [plumes pour écrire], quand bien même l\'océan serait un océan d\'encre où conflueraient sept autres océans, les paroles d\'Allah ne s\'épuiseraient pas. Car Allah est Puissant et Sage.\";s:13:\"numberInSurah\";i:27;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:413;s:4:\"ruku\";i:357;s:11:\"hizbQuarter\";i:165;s:5:\"sajda\";b:0;}i:27;a:9:{s:6:\"number\";i:3497;s:4:\"text\";s:157:\"Votre création et votre résurrection [à tous] sont [aussi faciles à Allah] que s\'il s\'agissait d\'une seule âme. Certes Allah est Audient et Clairvoyant.\";s:13:\"numberInSurah\";i:28;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:413;s:4:\"ruku\";i:357;s:11:\"hizbQuarter\";i:165;s:5:\"sajda\";b:0;}i:28;a:9:{s:6:\"number\";i:3498;s:4:\"text\";s:265:\"N\'as-tu pas vu qu\'Allah fait pénétrer la nuit dans le jour, et qu\'il fait pénétrer le jour dans la nuit, et qu\'Il a assujetti le soleil et la lune chacun poursuivant sa course jusqu\'à un terme fixé? Et Allah est Parfaitement Connaisseur de ce que vous faites.\";s:13:\"numberInSurah\";i:29;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:414;s:4:\"ruku\";i:357;s:11:\"hizbQuarter\";i:165;s:5:\"sajda\";b:0;}i:29;a:9:{s:6:\"number\";i:3499;s:4:\"text\";s:151:\"Il en est ainsi parce qu\'Allah est la Vérité, et que tout ce qu\'ils invoquent en dehors de Lui est le Faux, et qu\'Allah, c\'est Lui le Haut, le Grand.\";s:13:\"numberInSurah\";i:30;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:414;s:4:\"ruku\";i:357;s:11:\"hizbQuarter\";i:165;s:5:\"sajda\";b:0;}i:30;a:9:{s:6:\"number\";i:3500;s:4:\"text\";s:196:\"N\'as-tu pas vu que c\'est par la grâce d\'Allah que le vaisseau vogue dans la mer, afin qu\'Il vous fasse voir de Ses merveilles? Il y a en cela des preuves pour tout homme patient et reconnaissant.\";s:13:\"numberInSurah\";i:31;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:414;s:4:\"ruku\";i:357;s:11:\"hizbQuarter\";i:165;s:5:\"sajda\";b:0;}i:31;a:9:{s:6:\"number\";i:3501;s:4:\"text\";s:280:\"Quand une vague les recouvre comme des ombres, ils invoquent Allah, vouant leur culte exclusivement à Lui; et lorsqu\'Il les sauve, en les ramenant vers la terre ferme, certains d\'entre eux deviennent réticents; mais, seul le grand traître et le grand ingrat renient Nos signes.\";s:13:\"numberInSurah\";i:32;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:414;s:4:\"ruku\";i:357;s:11:\"hizbQuarter\";i:165;s:5:\"sajda\";b:0;}i:32;a:9:{s:6:\"number\";i:3502;s:4:\"text\";s:292:\"O hommes! Craignez votre Seigneur et redoutez un jour où le père ne répondra en quoi que ce soit pour son enfant, ni l\'enfant pour son père. La promesse d\'Allah est vérité. Que la vie présente ne vous trompe donc pas, et que le Trompeur (Satan) ne vous induise pas en erreur sur Allah!\";s:13:\"numberInSurah\";i:33;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:414;s:4:\"ruku\";i:357;s:11:\"hizbQuarter\";i:165;s:5:\"sajda\";b:0;}i:33;a:9:{s:6:\"number\";i:3503;s:4:\"text\";s:293:\"La connaissance de l\'Heure est auprès d\'Allah; et c\'est Lui qui fait tomber la pluie salvatrice; et Il sait ce qu\'il y a dans les matrices. Et personne ne sait ce qu\'il acquerra demain, et personne ne sait dans quelle terre il mourra. Certes, Allah est Omniscient et Parfaitement Connaisseur.\";s:13:\"numberInSurah\";i:34;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:414;s:4:\"ruku\";i:357;s:11:\"hizbQuarter\";i:165;s:5:\"sajda\";b:0;}}s:7:\"edition\";a:7:{s:10:\"identifier\";s:13:\"fr.hamidullah\";s:8:\"language\";s:2:\"fr\";s:4:\"name\";s:10:\"Hamidullah\";s:11:\"englishName\";s:19:\"Muhammad Hamidullah\";s:6:\"format\";s:4:\"text\";s:4:\"type\";s:11:\"translation\";s:9:\"direction\";s:3:\"ltr\";}}', 1794581365),
('quranapp-cache-surah_32_ar.uthmani', 'a:8:{s:6:\"number\";i:32;s:4:\"name\";s:37:\"سُورَةُ السَّجۡدَةِ\";s:11:\"englishName\";s:8:\"As-Sajda\";s:22:\"englishNameTranslation\";s:15:\"The Prostration\";s:14:\"revelationType\";s:6:\"Meccan\";s:13:\"numberOfAyahs\";i:30;s:5:\"ayahs\";a:30:{i:0;a:9:{s:6:\"number\";i:3504;s:4:\"text\";s:87:\"بِسۡمِ ٱللَّهِ ٱلرَّحۡمَـٰنِ ٱلرَّحِیمِ الۤمۤ\n\";s:13:\"numberInSurah\";i:1;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:415;s:4:\"ruku\";i:358;s:11:\"hizbQuarter\";i:165;s:5:\"sajda\";b:0;}i:1;a:9:{s:6:\"number\";i:3505;s:4:\"text\";s:120:\"تَنزِیلُ ٱلۡكِتَـٰبِ لَا رَیۡبَ فِیهِ مِن رَّبِّ ٱلۡعَـٰلَمِینَ\n\";s:13:\"numberInSurah\";i:2;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:415;s:4:\"ruku\";i:358;s:11:\"hizbQuarter\";i:165;s:5:\"sajda\";b:0;}i:2;a:9:{s:6:\"number\";i:3506;s:4:\"text\";s:278:\"أَمۡ یَقُولُونَ ٱفۡتَرَىٰهُۚ بَلۡ هُوَ ٱلۡحَقُّ مِن رَّبِّكَ لِتُنذِرَ قَوۡمࣰا مَّاۤ أَتَىٰهُم مِّن نَّذِیرࣲ مِّن قَبۡلِكَ لَعَلَّهُمۡ یَهۡتَدُونَ\n\";s:13:\"numberInSurah\";i:3;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:415;s:4:\"ruku\";i:358;s:11:\"hizbQuarter\";i:165;s:5:\"sajda\";b:0;}i:3;a:9:{s:6:\"number\";i:3507;s:4:\"text\";s:376:\"ٱللَّهُ ٱلَّذِی خَلَقَ ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضَ وَمَا بَیۡنَهُمَا فِی سِتَّةِ أَیَّامࣲ ثُمَّ ٱسۡتَوَىٰ عَلَى ٱلۡعَرۡشِۖ مَا لَكُم مِّن دُونِهِۦ مِن وَلِیࣲّ وَلَا شَفِیعٍۚ أَفَلَا تَتَذَكَّرُونَ\n\";s:13:\"numberInSurah\";i:4;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:415;s:4:\"ruku\";i:358;s:11:\"hizbQuarter\";i:165;s:5:\"sajda\";b:0;}i:4;a:9:{s:6:\"number\";i:3508;s:4:\"text\";s:267:\"یُدَبِّرُ ٱلۡأَمۡرَ مِنَ ٱلسَّمَاۤءِ إِلَى ٱلۡأَرۡضِ ثُمَّ یَعۡرُجُ إِلَیۡهِ فِی یَوۡمࣲ كَانَ مِقۡدَارُهُۥۤ أَلۡفَ سَنَةࣲ مِّمَّا تَعُدُّونَ\n\";s:13:\"numberInSurah\";i:5;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:415;s:4:\"ruku\";i:358;s:11:\"hizbQuarter\";i:165;s:5:\"sajda\";b:0;}i:5;a:9:{s:6:\"number\";i:3509;s:4:\"text\";s:130:\"ذَ ٰ⁠لِكَ عَـٰلِمُ ٱلۡغَیۡبِ وَٱلشَّهَـٰدَةِ ٱلۡعَزِیزُ ٱلرَّحِیمُ\n\";s:13:\"numberInSurah\";i:6;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:415;s:4:\"ruku\";i:358;s:11:\"hizbQuarter\";i:165;s:5:\"sajda\";b:0;}i:6;a:9:{s:6:\"number\";i:3510;s:4:\"text\";s:153:\"ٱلَّذِیۤ أَحۡسَنَ كُلَّ شَیۡءٍ خَلَقَهُۥۖ وَبَدَأَ خَلۡقَ ٱلۡإِنسَـٰنِ مِن طِینࣲ\n\";s:13:\"numberInSurah\";i:7;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:415;s:4:\"ruku\";i:358;s:11:\"hizbQuarter\";i:165;s:5:\"sajda\";b:0;}i:7;a:9:{s:6:\"number\";i:3511;s:4:\"text\";s:115:\"ثُمَّ جَعَلَ نَسۡلَهُۥ مِن سُلَـٰلَةࣲ مِّن مَّاۤءࣲ مَّهِینࣲ\n\";s:13:\"numberInSurah\";i:8;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:415;s:4:\"ruku\";i:358;s:11:\"hizbQuarter\";i:165;s:5:\"sajda\";b:0;}i:8;a:9:{s:6:\"number\";i:3512;s:4:\"text\";s:251:\"ثُمَّ سَوَّىٰهُ وَنَفَخَ فِیهِ مِن رُّوحِهِۦۖ وَجَعَلَ لَكُمُ ٱلسَّمۡعَ وَٱلۡأَبۡصَـٰرَ وَٱلۡأَفۡـِٔدَةَۚ قَلِیلࣰا مَّا تَشۡكُرُونَ\n\";s:13:\"numberInSurah\";i:9;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:415;s:4:\"ruku\";i:358;s:11:\"hizbQuarter\";i:165;s:5:\"sajda\";b:0;}i:9;a:9:{s:6:\"number\";i:3513;s:4:\"text\";s:223:\"وَقَالُوۤا۟ أَءِذَا ضَلَلۡنَا فِی ٱلۡأَرۡضِ أَءِنَّا لَفِی خَلۡقࣲ جَدِیدِۭۚ بَلۡ هُم بِلِقَاۤءِ رَبِّهِمۡ كَـٰفِرُونَ\n\";s:13:\"numberInSurah\";i:10;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:415;s:4:\"ruku\";i:358;s:11:\"hizbQuarter\";i:165;s:5:\"sajda\";b:0;}i:10;a:9:{s:6:\"number\";i:3514;s:4:\"text\";s:184:\"۞ قُلۡ یَتَوَفَّىٰكُم مَّلَكُ ٱلۡمَوۡتِ ٱلَّذِی وُكِّلَ بِكُمۡ ثُمَّ إِلَىٰ رَبِّكُمۡ تُرۡجَعُونَ\n\";s:13:\"numberInSurah\";i:11;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:415;s:4:\"ruku\";i:358;s:11:\"hizbQuarter\";i:166;s:5:\"sajda\";b:0;}i:11;a:9:{s:6:\"number\";i:3515;s:4:\"text\";s:300:\"وَلَوۡ تَرَىٰۤ إِذِ ٱلۡمُجۡرِمُونَ نَاكِسُوا۟ رُءُوسِهِمۡ عِندَ رَبِّهِمۡ رَبَّنَاۤ أَبۡصَرۡنَا وَسَمِعۡنَا فَٱرۡجِعۡنَا نَعۡمَلۡ صَـٰلِحًا إِنَّا مُوقِنُونَ\n\";s:13:\"numberInSurah\";i:12;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:416;s:4:\"ruku\";i:359;s:11:\"hizbQuarter\";i:166;s:5:\"sajda\";b:0;}i:12;a:9:{s:6:\"number\";i:3516;s:4:\"text\";s:282:\"وَلَوۡ شِئۡنَا لَـَٔاتَیۡنَا كُلَّ نَفۡسٍ هُدَىٰهَا وَلَـٰكِنۡ حَقَّ ٱلۡقَوۡلُ مِنِّی لَأَمۡلَأَنَّ جَهَنَّمَ مِنَ ٱلۡجِنَّةِ وَٱلنَّاسِ أَجۡمَعِینَ\n\";s:13:\"numberInSurah\";i:13;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:416;s:4:\"ruku\";i:359;s:11:\"hizbQuarter\";i:166;s:5:\"sajda\";b:0;}i:13;a:9:{s:6:\"number\";i:3517;s:4:\"text\";s:252:\"فَذُوقُوا۟ بِمَا نَسِیتُمۡ لِقَاۤءَ یَوۡمِكُمۡ هَـٰذَاۤ إِنَّا نَسِینَـٰكُمۡۖ وَذُوقُوا۟ عَذَابَ ٱلۡخُلۡدِ بِمَا كُنتُمۡ تَعۡمَلُونَ\n\";s:13:\"numberInSurah\";i:14;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:416;s:4:\"ruku\";i:359;s:11:\"hizbQuarter\";i:166;s:5:\"sajda\";b:0;}i:14;a:9:{s:6:\"number\";i:3518;s:4:\"text\";s:277:\"إِنَّمَا یُؤۡمِنُ بِـَٔایَـٰتِنَا ٱلَّذِینَ إِذَا ذُكِّرُوا۟ بِهَا خَرُّوا۟ سُجَّدࣰا وَسَبَّحُوا۟ بِحَمۡدِ رَبِّهِمۡ وَهُمۡ لَا یَسۡتَكۡبِرُونَ ۩\n\";s:13:\"numberInSurah\";i:15;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:416;s:4:\"ruku\";i:359;s:11:\"hizbQuarter\";i:166;s:5:\"sajda\";a:3:{s:2:\"id\";i:10;s:11:\"recommended\";b:0;s:10:\"obligatory\";b:1;}}i:15;a:9:{s:6:\"number\";i:3519;s:4:\"text\";s:221:\"تَتَجَافَىٰ جُنُوبُهُمۡ عَنِ ٱلۡمَضَاجِعِ یَدۡعُونَ رَبَّهُمۡ خَوۡفࣰا وَطَمَعࣰا وَمِمَّا رَزَقۡنَـٰهُمۡ یُنفِقُونَ\n\";s:13:\"numberInSurah\";i:16;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:416;s:4:\"ruku\";i:359;s:11:\"hizbQuarter\";i:166;s:5:\"sajda\";b:0;}i:16;a:9:{s:6:\"number\";i:3520;s:4:\"text\";s:193:\"فَلَا تَعۡلَمُ نَفۡسࣱ مَّاۤ أُخۡفِیَ لَهُم مِّن قُرَّةِ أَعۡیُنࣲ جَزَاۤءَۢ بِمَا كَانُوا۟ یَعۡمَلُونَ\n\";s:13:\"numberInSurah\";i:17;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:416;s:4:\"ruku\";i:359;s:11:\"hizbQuarter\";i:166;s:5:\"sajda\";b:0;}i:17;a:9:{s:6:\"number\";i:3521;s:4:\"text\";s:120:\"أَفَمَن كَانَ مُؤۡمِنࣰا كَمَن كَانَ فَاسِقࣰاۚ لَّا یَسۡتَوُۥنَ\n\";s:13:\"numberInSurah\";i:18;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:416;s:4:\"ruku\";i:359;s:11:\"hizbQuarter\";i:166;s:5:\"sajda\";b:0;}i:18;a:9:{s:6:\"number\";i:3522;s:4:\"text\";s:234:\"أَمَّا ٱلَّذِینَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ فَلَهُمۡ جَنَّـٰتُ ٱلۡمَأۡوَىٰ نُزُلَۢا بِمَا كَانُوا۟ یَعۡمَلُونَ\n\";s:13:\"numberInSurah\";i:19;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:416;s:4:\"ruku\";i:359;s:11:\"hizbQuarter\";i:166;s:5:\"sajda\";b:0;}i:19;a:9:{s:6:\"number\";i:3523;s:4:\"text\";s:367:\"وَأَمَّا ٱلَّذِینَ فَسَقُوا۟ فَمَأۡوَىٰهُمُ ٱلنَّارُۖ كُلَّمَاۤ أَرَادُوۤا۟ أَن یَخۡرُجُوا۟ مِنۡهَاۤ أُعِیدُوا۟ فِیهَا وَقِیلَ لَهُمۡ ذُوقُوا۟ عَذَابَ ٱلنَّارِ ٱلَّذِی كُنتُم بِهِۦ تُكَذِّبُونَ\n\";s:13:\"numberInSurah\";i:20;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:416;s:4:\"ruku\";i:359;s:11:\"hizbQuarter\";i:166;s:5:\"sajda\";b:0;}i:20;a:9:{s:6:\"number\";i:3524;s:4:\"text\";s:191:\"وَلَنُذِیقَنَّهُم مِّنَ ٱلۡعَذَابِ ٱلۡأَدۡنَىٰ دُونَ ٱلۡعَذَابِ ٱلۡأَكۡبَرِ لَعَلَّهُمۡ یَرۡجِعُونَ\n\";s:13:\"numberInSurah\";i:21;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:417;s:4:\"ruku\";i:359;s:11:\"hizbQuarter\";i:166;s:5:\"sajda\";b:0;}i:21;a:9:{s:6:\"number\";i:3525;s:4:\"text\";s:223:\"وَمَنۡ أَظۡلَمُ مِمَّن ذُكِّرَ بِـَٔایَـٰتِ رَبِّهِۦ ثُمَّ أَعۡرَضَ عَنۡهَاۤۚ إِنَّا مِنَ ٱلۡمُجۡرِمِینَ مُنتَقِمُونَ\n\";s:13:\"numberInSurah\";i:22;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:417;s:4:\"ruku\";i:359;s:11:\"hizbQuarter\";i:166;s:5:\"sajda\";b:0;}i:22;a:9:{s:6:\"number\";i:3526;s:4:\"text\";s:252:\"وَلَقَدۡ ءَاتَیۡنَا مُوسَى ٱلۡكِتَـٰبَ فَلَا تَكُن فِی مِرۡیَةࣲ مِّن لِّقَاۤىِٕهِۦۖ وَجَعَلۡنَـٰهُ هُدࣰى لِّبَنِیۤ إِسۡرَ ٰ⁠ۤءِیلَ\n\";s:13:\"numberInSurah\";i:23;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:417;s:4:\"ruku\";i:360;s:11:\"hizbQuarter\";i:166;s:5:\"sajda\";b:0;}i:23;a:9:{s:6:\"number\";i:3527;s:4:\"text\";s:211:\"وَجَعَلۡنَا مِنۡهُمۡ أَىِٕمَّةࣰ یَهۡدُونَ بِأَمۡرِنَا لَمَّا صَبَرُوا۟ۖ وَكَانُوا۟ بِـَٔایَـٰتِنَا یُوقِنُونَ\n\";s:13:\"numberInSurah\";i:24;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:417;s:4:\"ruku\";i:360;s:11:\"hizbQuarter\";i:166;s:5:\"sajda\";b:0;}i:24;a:9:{s:6:\"number\";i:3528;s:4:\"text\";s:181:\"إِنَّ رَبَّكَ هُوَ یَفۡصِلُ بَیۡنَهُمۡ یَوۡمَ ٱلۡقِیَـٰمَةِ فِیمَا كَانُوا۟ فِیهِ یَخۡتَلِفُونَ\n\";s:13:\"numberInSurah\";i:25;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:417;s:4:\"ruku\";i:360;s:11:\"hizbQuarter\";i:166;s:5:\"sajda\";b:0;}i:25;a:9:{s:6:\"number\";i:3529;s:4:\"text\";s:294:\"أَوَلَمۡ یَهۡدِ لَهُمۡ كَمۡ أَهۡلَكۡنَا مِن قَبۡلِهِم مِّنَ ٱلۡقُرُونِ یَمۡشُونَ فِی مَسَـٰكِنِهِمۡۚ إِنَّ فِی ذَ ٰ⁠لِكَ لَـَٔایَـٰتٍۚ أَفَلَا یَسۡمَعُونَ\n\";s:13:\"numberInSurah\";i:26;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:417;s:4:\"ruku\";i:360;s:11:\"hizbQuarter\";i:166;s:5:\"sajda\";b:0;}i:26;a:9:{s:6:\"number\";i:3530;s:4:\"text\";s:304:\"أَوَلَمۡ یَرَوۡا۟ أَنَّا نَسُوقُ ٱلۡمَاۤءَ إِلَى ٱلۡأَرۡضِ ٱلۡجُرُزِ فَنُخۡرِجُ بِهِۦ زَرۡعࣰا تَأۡكُلُ مِنۡهُ أَنۡعَـٰمُهُمۡ وَأَنفُسُهُمۡۚ أَفَلَا یُبۡصِرُونَ\n\";s:13:\"numberInSurah\";i:27;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:417;s:4:\"ruku\";i:360;s:11:\"hizbQuarter\";i:166;s:5:\"sajda\";b:0;}i:27;a:9:{s:6:\"number\";i:3531;s:4:\"text\";s:117:\"وَیَقُولُونَ مَتَىٰ هَـٰذَا ٱلۡفَتۡحُ إِن كُنتُمۡ صَـٰدِقِینَ\n\";s:13:\"numberInSurah\";i:28;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:417;s:4:\"ruku\";i:360;s:11:\"hizbQuarter\";i:166;s:5:\"sajda\";b:0;}i:28;a:9:{s:6:\"number\";i:3532;s:4:\"text\";s:171:\"قُلۡ یَوۡمَ ٱلۡفَتۡحِ لَا یَنفَعُ ٱلَّذِینَ كَفَرُوۤا۟ إِیمَـٰنُهُمۡ وَلَا هُمۡ یُنظَرُونَ\n\";s:13:\"numberInSurah\";i:29;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:417;s:4:\"ruku\";i:360;s:11:\"hizbQuarter\";i:166;s:5:\"sajda\";b:0;}i:29;a:9:{s:6:\"number\";i:3533;s:4:\"text\";s:103:\"فَأَعۡرِضۡ عَنۡهُمۡ وَٱنتَظِرۡ إِنَّهُم مُّنتَظِرُونَ\n\";s:13:\"numberInSurah\";i:30;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:417;s:4:\"ruku\";i:360;s:11:\"hizbQuarter\";i:166;s:5:\"sajda\";b:0;}}s:7:\"edition\";a:7:{s:10:\"identifier\";s:27:\"quran-uthmani-quran-academy\";s:8:\"language\";s:2:\"ar\";s:4:\"name\";s:67:\"القرآن الكريم برسم العثماني (quran-academy)\";s:11:\"englishName\";s:78:\"Modified Quran Uthmani Text from the Quran Academy to work with the Kitab font\";s:6:\"format\";s:4:\"text\";s:4:\"type\";s:5:\"quran\";s:9:\"direction\";s:3:\"rtl\";}}', 1794581366),
('quranapp-cache-surah_32_fr.hamidullah', 'a:8:{s:6:\"number\";i:32;s:4:\"name\";s:37:\"سُورَةُ السَّجۡدَةِ\";s:11:\"englishName\";s:8:\"As-Sajda\";s:22:\"englishNameTranslation\";s:15:\"The Prostration\";s:14:\"revelationType\";s:6:\"Meccan\";s:13:\"numberOfAyahs\";i:30;s:5:\"ayahs\";a:30:{i:0;a:9:{s:6:\"number\";i:3504;s:4:\"text\";s:17:\"Alif, Lâm, Mîm.\";s:13:\"numberInSurah\";i:1;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:415;s:4:\"ruku\";i:358;s:11:\"hizbQuarter\";i:165;s:5:\"sajda\";b:0;}i:1;a:9:{s:6:\"number\";i:3505;s:4:\"text\";s:80:\"La Révélation du Livre, nul doute là-dessus, émane du Seigneur de l\'univers.\";s:13:\"numberInSurah\";i:2;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:415;s:4:\"ruku\";i:358;s:11:\"hizbQuarter\";i:165;s:5:\"sajda\";b:0;}i:2;a:9:{s:6:\"number\";i:3506;s:4:\"text\";s:202:\"Diront-ils qu\'il (Muhammad) l\'a inventé? Ceci est, au contraire, la vérité venant de ton Seigneur pour que tu avertisses un peuple à qui nul avertisseur avant toi n\'est venu, afin qu\'ils se guident.\";s:13:\"numberInSurah\";i:3;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:415;s:4:\"ruku\";i:358;s:11:\"hizbQuarter\";i:165;s:5:\"sajda\";b:0;}i:3;a:9:{s:6:\"number\";i:3507;s:4:\"text\";s:221:\"Allah qui a créé en six jours les cieux et la terre, et ce qui est entre eux. Ensuite Il S\'est établi «Istawâ» sur le Trône. Vous n\'avez, en dehors de Lui, ni allié ni intercesseur. Ne vous rappelez-vous donc pas?\";s:13:\"numberInSurah\";i:4;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:415;s:4:\"ruku\";i:358;s:11:\"hizbQuarter\";i:165;s:5:\"sajda\";b:0;}i:4;a:9:{s:6:\"number\";i:3508;s:4:\"text\";s:130:\"Du ciel à la terre, Il administre l\'affaire, laquelle ensuite monte vers Lui en un jour équivalent à mille ans de votre calcul.\";s:13:\"numberInSurah\";i:5;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:415;s:4:\"ruku\";i:358;s:11:\"hizbQuarter\";i:165;s:5:\"sajda\";b:0;}i:5;a:9:{s:6:\"number\";i:3509;s:4:\"text\";s:92:\"C\'est Lui le Connaisseur [des mondes] inconnus et visibles, le Puissant, le Miséricordieux,\";s:13:\"numberInSurah\";i:6;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:415;s:4:\"ruku\";i:358;s:11:\"hizbQuarter\";i:165;s:5:\"sajda\";b:0;}i:6;a:9:{s:6:\"number\";i:3510;s:4:\"text\";s:104:\"qui a bien fait tout ce qu\'Il a créé. Et Il a commencé la création de l\'homme à partir de l\'argile,\";s:13:\"numberInSurah\";i:7;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:415;s:4:\"ruku\";i:358;s:11:\"hizbQuarter\";i:165;s:5:\"sajda\";b:0;}i:7;a:9:{s:6:\"number\";i:3511;s:4:\"text\";s:64:\"puis Il tira sa descendance d\'une goutte d\'eau vile [le sperme];\";s:13:\"numberInSurah\";i:8;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:415;s:4:\"ruku\";i:358;s:11:\"hizbQuarter\";i:165;s:5:\"sajda\";b:0;}i:8;a:9:{s:6:\"number\";i:3512;s:4:\"text\";s:154:\"puis Il lui donna sa forme parfaite et lui insuffla de Son Esprit. Et Il vous a assigné l\'ouïe, les yeux et le cœur. Que vous êtes peu reconnaissants!\";s:13:\"numberInSurah\";i:9;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:415;s:4:\"ruku\";i:358;s:11:\"hizbQuarter\";i:165;s:5:\"sajda\";b:0;}i:9;a:9:{s:6:\"number\";i:3513;s:4:\"text\";s:193:\"Et ils disent: «Quand nous serons perdus dans la terre [sous forme de poussière], redeviendrons-nous une création nouvelle?» En outre, ils ne croient pas en la rencontre avec leur Seigneur.\";s:13:\"numberInSurah\";i:10;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:415;s:4:\"ruku\";i:358;s:11:\"hizbQuarter\";i:165;s:5:\"sajda\";b:0;}i:10;a:9:{s:6:\"number\";i:3514;s:4:\"text\";s:119:\"Dis: «L\'Ange de la mort qui est chargé de vous, vous fera mourir. Ensuite, vous serez ramenés vers Votre Seigneur».\";s:13:\"numberInSurah\";i:11;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:415;s:4:\"ruku\";i:358;s:11:\"hizbQuarter\";i:166;s:5:\"sajda\";b:0;}i:11;a:9:{s:6:\"number\";i:3515;s:4:\"text\";s:229:\"Si tu voyais alors les criminels [comparaître], têtes basses devant leur Seigneur! «Notre Seigneur, Nous avons vu et entendu, renvoie-nous donc afin que nous puissions faire du bien; nous croyons [maintenant] avec certitude».\";s:13:\"numberInSurah\";i:12;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:416;s:4:\"ruku\";i:359;s:11:\"hizbQuarter\";i:166;s:5:\"sajda\";b:0;}i:12;a:9:{s:6:\"number\";i:3516;s:4:\"text\";s:170:\"«Si Nous voulions, Nous apporterions à chaque âme sa guidée. Mais la parole venant de Moi doit être réalisée: «J\'emplirai l\'Enfer de djinns et d\'hommes réunis».\";s:13:\"numberInSurah\";i:13;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:416;s:4:\"ruku\";i:359;s:11:\"hizbQuarter\";i:166;s:5:\"sajda\";b:0;}i:13;a:9:{s:6:\"number\";i:3517;s:4:\"text\";s:168:\"«Goûtez donc! Pour avoir oublié la rencontre de votre jour que voici. Nous aussi Nous vous avons oubliés. Goûtez au châtiment éternel pour ce que vous faisiez».\";s:13:\"numberInSurah\";i:14;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:416;s:4:\"ruku\";i:359;s:11:\"hizbQuarter\";i:166;s:5:\"sajda\";b:0;}i:14;a:9:{s:6:\"number\";i:3518;s:4:\"text\";s:179:\"Seuls croient en Nos versets ceux qui, lorsqu\'on les leur rappelle, tombent prosternés et, par des louanges à leur Seigneur, célèbrent Sa gloire et ne s\'enflent pas d\'orgueil.\";s:13:\"numberInSurah\";i:15;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:416;s:4:\"ruku\";i:359;s:11:\"hizbQuarter\";i:166;s:5:\"sajda\";a:3:{s:2:\"id\";i:10;s:11:\"recommended\";b:0;s:10:\"obligatory\";b:1;}}i:15;a:9:{s:6:\"number\";i:3519;s:4:\"text\";s:134:\"Ils s\'arrachent de leurs lits pour invoquer leur Seigneur, par crainte et espoir; et ils font largesse de ce que Nous leur attribuons.\";s:13:\"numberInSurah\";i:16;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:416;s:4:\"ruku\";i:359;s:11:\"hizbQuarter\";i:166;s:5:\"sajda\";b:0;}i:16;a:9:{s:6:\"number\";i:3520;s:4:\"text\";s:124:\"Aucun être ne sait ce qu\'on a réservé pour eux comme réjouissance pour les yeux, en récompense de ce qu\'ils œuvraient!\";s:13:\"numberInSurah\";i:17;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:416;s:4:\"ruku\";i:359;s:11:\"hizbQuarter\";i:166;s:5:\"sajda\";b:0;}i:17;a:9:{s:6:\"number\";i:3521;s:4:\"text\";s:84:\"Celui qui est croyant est-il comparable au pervers? (Non), ils ne sont point égaux.\";s:13:\"numberInSurah\";i:18;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:416;s:4:\"ruku\";i:359;s:11:\"hizbQuarter\";i:166;s:5:\"sajda\";b:0;}i:18;a:9:{s:6:\"number\";i:3522;s:4:\"text\";s:144:\"Ceux qui croient et accomplissent les bonnes œuvres, auront leur résidence dans les Jardins du Refuge, en récompense de ce qu\'ils œuvraient.\";s:13:\"numberInSurah\";i:19;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:416;s:4:\"ruku\";i:359;s:11:\"hizbQuarter\";i:166;s:5:\"sajda\";b:0;}i:19;a:9:{s:6:\"number\";i:3523;s:4:\"text\";s:215:\"Et quant à ceux qui auront été pervers, leur refuge sera le Feu: toutes les fois qu\'ils voudront en sortir, ils y seront ramenés, et on leur dira: «Goûtez au châtiment du Feu auquel vous refusiez de croire».\";s:13:\"numberInSurah\";i:20;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:416;s:4:\"ruku\";i:359;s:11:\"hizbQuarter\";i:166;s:5:\"sajda\";b:0;}i:20;a:9:{s:6:\"number\";i:3524;s:4:\"text\";s:133:\"Nous leur ferons certainement goûter au châtiment ici-bas, avant le grand châtiment afin qu\'ils retournent (vers le chemin droit)!\";s:13:\"numberInSurah\";i:21;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:417;s:4:\"ruku\";i:359;s:11:\"hizbQuarter\";i:166;s:5:\"sajda\";b:0;}i:21;a:9:{s:6:\"number\";i:3525;s:4:\"text\";s:145:\"Qui est plus injuste que celui à qui les versets d\'Allah sont rappelés et qui ensuite s\'en détourne? Nous nous vengerons certes des criminels.\";s:13:\"numberInSurah\";i:22;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:417;s:4:\"ruku\";i:359;s:11:\"hizbQuarter\";i:166;s:5:\"sajda\";b:0;}i:22;a:9:{s:6:\"number\";i:3526;s:4:\"text\";s:162:\"Nous avons effectivement donné à Moïse le Livre - ne sois donc pas en doute sur ta rencontre avec lui -, et l\'avons assigné comme guide aux Enfants d\'Israël.\";s:13:\"numberInSurah\";i:23;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:417;s:4:\"ruku\";i:360;s:11:\"hizbQuarter\";i:166;s:5:\"sajda\";b:0;}i:23;a:9:{s:6:\"number\";i:3527;s:4:\"text\";s:162:\"Et Nous avons désigné parmi eux des dirigeants qui guidaient (les gens) par Notre ordre aussi longtemps qu\'ils enduraient et croyaient fermement en Nos versets.\";s:13:\"numberInSurah\";i:24;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:417;s:4:\"ruku\";i:360;s:11:\"hizbQuarter\";i:166;s:5:\"sajda\";b:0;}i:24;a:9:{s:6:\"number\";i:3528;s:4:\"text\";s:110:\"Ton Seigneur, c\'est Lui qui décidera entre eux, au Jour de la Résurrection, de ce sur quoi ils divergeaient.\";s:13:\"numberInSurah\";i:25;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:417;s:4:\"ruku\";i:360;s:11:\"hizbQuarter\";i:166;s:5:\"sajda\";b:0;}i:25;a:9:{s:6:\"number\";i:3529;s:4:\"text\";s:201:\"N\'est-ce pas pour eux une indication le fait qu\'avant eux, Nous ayons fait périr tant de générations dans les maisons desquelles ils marchent? Il y a en cela des preuves! N\'écouteront-ils donc pas?\";s:13:\"numberInSurah\";i:26;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:417;s:4:\"ruku\";i:360;s:11:\"hizbQuarter\";i:166;s:5:\"sajda\";b:0;}i:26;a:9:{s:6:\"number\";i:3530;s:4:\"text\";s:175:\"N\'ont-ils pas vu que Nous poussons l\'eau vers un sol aride, qu\'ensuite Nous en faisons sortir une culture que consomment leurs bestiaux et eux-mêmes? Ne voient-ils donc pas,?\";s:13:\"numberInSurah\";i:27;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:417;s:4:\"ruku\";i:360;s:11:\"hizbQuarter\";i:166;s:5:\"sajda\";b:0;}i:27;a:9:{s:6:\"number\";i:3531;s:4:\"text\";s:69:\"Et ils disent: «A quand cette victoire, si vous êtes véridiques?»\";s:13:\"numberInSurah\";i:28;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:417;s:4:\"ruku\";i:360;s:11:\"hizbQuarter\";i:166;s:5:\"sajda\";b:0;}i:28;a:9:{s:6:\"number\";i:3532;s:4:\"text\";s:111:\"Dis: «Le jour de la Victoire, il sera inutile aux infidèles de croire! Et aucun délai ne leur sera donné».\";s:13:\"numberInSurah\";i:29;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:417;s:4:\"ruku\";i:360;s:11:\"hizbQuarter\";i:166;s:5:\"sajda\";b:0;}i:29;a:9:{s:6:\"number\";i:3533;s:4:\"text\";s:65:\"Eloigne-toi d\'eux et attends. Eux aussi demeurent dans l\'attente.\";s:13:\"numberInSurah\";i:30;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:417;s:4:\"ruku\";i:360;s:11:\"hizbQuarter\";i:166;s:5:\"sajda\";b:0;}}s:7:\"edition\";a:7:{s:10:\"identifier\";s:13:\"fr.hamidullah\";s:8:\"language\";s:2:\"fr\";s:4:\"name\";s:10:\"Hamidullah\";s:11:\"englishName\";s:19:\"Muhammad Hamidullah\";s:6:\"format\";s:4:\"text\";s:4:\"type\";s:11:\"translation\";s:9:\"direction\";s:3:\"ltr\";}}', 1794581366);
INSERT INTO `cache` (`key`, `value`, `expiration`) VALUES
('quranapp-cache-surah_33_ar.uthmani', 'a:8:{s:6:\"number\";i:33;s:4:\"name\";s:37:\"سُورَةُ الأَحۡزَابِ\";s:11:\"englishName\";s:9:\"Al-Ahzaab\";s:22:\"englishNameTranslation\";s:9:\"The Clans\";s:14:\"revelationType\";s:7:\"Medinan\";s:13:\"numberOfAyahs\";i:73;s:5:\"ayahs\";a:73:{i:0;a:9:{s:6:\"number\";i:3534;s:4:\"text\";s:316:\"بِسۡمِ ٱللَّهِ ٱلرَّحۡمَـٰنِ ٱلرَّحِیمِ یَـٰۤأَیُّهَا ٱلنَّبِیُّ ٱتَّقِ ٱللَّهۚ وَلَا تُطِعِ ٱلۡكَـٰفِرِینَ وَٱلۡمُنَـٰفِقِینَۗ إِنَّ ٱللَّهَ كَانَ عَلِیمًا حَكِیمࣰا\n\";s:13:\"numberInSurah\";i:1;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:418;s:4:\"ruku\";i:361;s:11:\"hizbQuarter\";i:167;s:5:\"sajda\";b:0;}i:1;a:9:{s:6:\"number\";i:3535;s:4:\"text\";s:177:\"وَٱتَّبِعۡ مَا یُوحَىٰۤ إِلَیۡكَ مِن رَّبِّكَۚ إِنَّ ٱللَّهَ كَانَ بِمَا تَعۡمَلُونَ خَبِیرࣰا\n\";s:13:\"numberInSurah\";i:2;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:418;s:4:\"ruku\";i:361;s:11:\"hizbQuarter\";i:167;s:5:\"sajda\";b:0;}i:2;a:9:{s:6:\"number\";i:3536;s:4:\"text\";s:105:\"وَتَوَكَّلۡ عَلَى ٱللَّهِۚ وَكَفَىٰ بِٱللَّهِ وَكِیلࣰا\n\";s:13:\"numberInSurah\";i:3;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:418;s:4:\"ruku\";i:361;s:11:\"hizbQuarter\";i:167;s:5:\"sajda\";b:0;}i:3;a:9:{s:6:\"number\";i:3537;s:4:\"text\";s:543:\"مَّا جَعَلَ ٱللَّهُ لِرَجُلࣲ مِّن قَلۡبَیۡنِ فِی جَوۡفِهِۦۚ وَمَا جَعَلَ أَزۡوَ ٰ⁠جَكُمُ ٱلَّـٰۤـِٔی تُظَـٰهِرُونَ مِنۡهُنَّ أُمَّهَـٰتِكُمۡۚ وَمَا جَعَلَ أَدۡعِیَاۤءَكُمۡ أَبۡنَاۤءَكُمۡۚ ذَ ٰ⁠لِكُمۡ قَوۡلُكُم بِأَفۡوَ ٰ⁠هِكُمۡۖ وَٱللَّهُ یَقُولُ ٱلۡحَقَّ وَهُوَ یَهۡدِی ٱلسَّبِیلَ\n\";s:13:\"numberInSurah\";i:4;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:418;s:4:\"ruku\";i:361;s:11:\"hizbQuarter\";i:167;s:5:\"sajda\";b:0;}i:4;a:9:{s:6:\"number\";i:3538;s:4:\"text\";s:528:\"ٱدۡعُوهُمۡ لِـَٔابَاۤىِٕهِمۡ هُوَ أَقۡسَطُ عِندَ ٱللَّهِۚ فَإِن لَّمۡ تَعۡلَمُوۤا۟ ءَابَاۤءَهُمۡ فَإِخۡوَ ٰ⁠نُكُمۡ فِی ٱلدِّینِ وَمَوَ ٰ⁠لِیكُمۡۚ وَلَیۡسَ عَلَیۡكُمۡ جُنَاحࣱ فِیمَاۤ أَخۡطَأۡتُم بِهِۦ وَلَـٰكِن مَّا تَعَمَّدَتۡ قُلُوبُكُمۡۚ وَكَانَ ٱللَّهُ غَفُورࣰا رَّحِیمًا\n\";s:13:\"numberInSurah\";i:5;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:418;s:4:\"ruku\";i:361;s:11:\"hizbQuarter\";i:167;s:5:\"sajda\";b:0;}i:5;a:9:{s:6:\"number\";i:3539;s:4:\"text\";s:598:\"ٱلنَّبِیُّ أَوۡلَىٰ بِٱلۡمُؤۡمِنِینَ مِنۡ أَنفُسِهِمۡۖ وَأَزۡوَ ٰ⁠جُهُۥۤ أُمَّهَـٰتُهُمۡۗ وَأُو۟لُوا۟ ٱلۡأَرۡحَامِ بَعۡضُهُمۡ أَوۡلَىٰ بِبَعۡضࣲ فِی كِتَـٰبِ ٱللَّهِ مِنَ ٱلۡمُؤۡمِنِینَ وَٱلۡمُهَـٰجِرِینَ إِلَّاۤ أَن تَفۡعَلُوۤا۟ إِلَىٰۤ أَوۡلِیَاۤىِٕكُم مَّعۡرُوفࣰاۚ كَانَ ذَ ٰ⁠لِكَ فِی ٱلۡكِتَـٰبِ مَسۡطُورࣰا\n\";s:13:\"numberInSurah\";i:6;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:418;s:4:\"ruku\";i:361;s:11:\"hizbQuarter\";i:167;s:5:\"sajda\";b:0;}i:6;a:9:{s:6:\"number\";i:3540;s:4:\"text\";s:317:\"وَإِذۡ أَخَذۡنَا مِنَ ٱلنَّبِیِّـۧنَ مِیثَـٰقَهُمۡ وَمِنكَ وَمِن نُّوحࣲ وَإِبۡرَ ٰ⁠هِیمَ وَمُوسَىٰ وَعِیسَى ٱبۡنِ مَرۡیَمَۖ وَأَخَذۡنَا مِنۡهُم مِّیثَـٰقًا غَلِیظࣰا\n\";s:13:\"numberInSurah\";i:7;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:419;s:4:\"ruku\";i:361;s:11:\"hizbQuarter\";i:167;s:5:\"sajda\";b:0;}i:7;a:9:{s:6:\"number\";i:3541;s:4:\"text\";s:169:\"لِّیَسۡـَٔلَ ٱلصَّـٰدِقِینَ عَن صِدۡقِهِمۡۚ وَأَعَدَّ لِلۡكَـٰفِرِینَ عَذَابًا أَلِیمࣰا\n\";s:13:\"numberInSurah\";i:8;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:419;s:4:\"ruku\";i:361;s:11:\"hizbQuarter\";i:167;s:5:\"sajda\";b:0;}i:8;a:9:{s:6:\"number\";i:3542;s:4:\"text\";s:388:\"یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ ٱذۡكُرُوا۟ نِعۡمَةَ ٱللَّهِ عَلَیۡكُمۡ إِذۡ جَاۤءَتۡكُمۡ جُنُودࣱ فَأَرۡسَلۡنَا عَلَیۡهِمۡ رِیحࣰا وَجُنُودࣰا لَّمۡ تَرَوۡهَاۚ وَكَانَ ٱللَّهُ بِمَا تَعۡمَلُونَ بَصِیرًا\n\";s:13:\"numberInSurah\";i:9;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:419;s:4:\"ruku\";i:362;s:11:\"hizbQuarter\";i:167;s:5:\"sajda\";b:0;}i:9;a:9:{s:6:\"number\";i:3543;s:4:\"text\";s:296:\"إِذۡ جَاۤءُوكُم مِّن فَوۡقِكُمۡ وَمِنۡ أَسۡفَلَ مِنكُمۡ وَإِذۡ زَاغَتِ ٱلۡأَبۡصَـٰرُ وَبَلَغَتِ ٱلۡقُلُوبُ ٱلۡحَنَاجِرَ وَتَظُنُّونَ بِٱللَّهِ ٱلظُّنُونَا۠\n\";s:13:\"numberInSurah\";i:10;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:419;s:4:\"ruku\";i:362;s:11:\"hizbQuarter\";i:167;s:5:\"sajda\";b:0;}i:10;a:9:{s:6:\"number\";i:3544;s:4:\"text\";s:134:\"هُنَالِكَ ٱبۡتُلِیَ ٱلۡمُؤۡمِنُونَ وَزُلۡزِلُوا۟ زِلۡزَالࣰا شَدِیدࣰا\n\";s:13:\"numberInSurah\";i:11;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:419;s:4:\"ruku\";i:362;s:11:\"hizbQuarter\";i:167;s:5:\"sajda\";b:0;}i:11;a:9:{s:6:\"number\";i:3545;s:4:\"text\";s:229:\"وَإِذۡ یَقُولُ ٱلۡمُنَـٰفِقُونَ وَٱلَّذِینَ فِی قُلُوبِهِم مَّرَضࣱ مَّا وَعَدَنَا ٱللَّهُ وَرَسُولُهُۥۤ إِلَّا غُرُورࣰا\n\";s:13:\"numberInSurah\";i:12;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:419;s:4:\"ruku\";i:362;s:11:\"hizbQuarter\";i:167;s:5:\"sajda\";b:0;}i:12;a:9:{s:6:\"number\";i:3546;s:4:\"text\";s:433:\"وَإِذۡ قَالَت طَّاۤىِٕفَةࣱ مِّنۡهُمۡ یَـٰۤأَهۡلَ یَثۡرِبَ لَا مُقَامَ لَكُمۡ فَٱرۡجِعُوا۟ۚ وَیَسۡتَـٔۡذِنُ فَرِیقࣱ مِّنۡهُمُ ٱلنَّبِیَّ یَقُولُونَ إِنَّ بُیُوتَنَا عَوۡرَةࣱ وَمَا هِیَ بِعَوۡرَةٍۖ إِن یُرِیدُونَ إِلَّا فِرَارࣰا\n\";s:13:\"numberInSurah\";i:13;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:419;s:4:\"ruku\";i:362;s:11:\"hizbQuarter\";i:167;s:5:\"sajda\";b:0;}i:13;a:9:{s:6:\"number\";i:3547;s:4:\"text\";s:247:\"وَلَوۡ دُخِلَتۡ عَلَیۡهِم مِّنۡ أَقۡطَارِهَا ثُمَّ سُىِٕلُوا۟ ٱلۡفِتۡنَةَ لَـَٔاتَوۡهَا وَمَا تَلَبَّثُوا۟ بِهَاۤ إِلَّا یَسِیرࣰا\n\";s:13:\"numberInSurah\";i:14;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:419;s:4:\"ruku\";i:362;s:11:\"hizbQuarter\";i:167;s:5:\"sajda\";b:0;}i:14;a:9:{s:6:\"number\";i:3548;s:4:\"text\";s:216:\"وَلَقَدۡ كَانُوا۟ عَـٰهَدُوا۟ ٱللَّهَ مِن قَبۡلُ لَا یُوَلُّونَ ٱلۡأَدۡبَـٰرَۚ وَكَانَ عَهۡدُ ٱللَّهِ مَسۡـُٔولࣰا\n\";s:13:\"numberInSurah\";i:15;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:419;s:4:\"ruku\";i:362;s:11:\"hizbQuarter\";i:167;s:5:\"sajda\";b:0;}i:15;a:9:{s:6:\"number\";i:3549;s:4:\"text\";s:225:\"قُل لَّن یَنفَعَكُمُ ٱلۡفِرَارُ إِن فَرَرۡتُم مِّنَ ٱلۡمَوۡتِ أَوِ ٱلۡقَتۡلِ وَإِذࣰا لَّا تُمَتَّعُونَ إِلَّا قَلِیلࣰا\n\";s:13:\"numberInSurah\";i:16;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:420;s:4:\"ruku\";i:362;s:11:\"hizbQuarter\";i:167;s:5:\"sajda\";b:0;}i:16;a:9:{s:6:\"number\";i:3550;s:4:\"text\";s:319:\"قُلۡ مَن ذَا ٱلَّذِی یَعۡصِمُكُم مِّنَ ٱللَّهِ إِنۡ أَرَادَ بِكُمۡ سُوۤءًا أَوۡ أَرَادَ بِكُمۡ رَحۡمَةࣰۚ وَلَا یَجِدُونَ لَهُم مِّن دُونِ ٱللَّهِ وَلِیࣰّا وَلَا نَصِیرࣰا\n\";s:13:\"numberInSurah\";i:17;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:420;s:4:\"ruku\";i:362;s:11:\"hizbQuarter\";i:167;s:5:\"sajda\";b:0;}i:17;a:9:{s:6:\"number\";i:3551;s:4:\"text\";s:277:\"۞ قَدۡ یَعۡلَمُ ٱللَّهُ ٱلۡمُعَوِّقِینَ مِنكُمۡ وَٱلۡقَاۤىِٕلِینَ لِإِخۡوَ ٰ⁠نِهِمۡ هَلُمَّ إِلَیۡنَاۖ وَلَا یَأۡتُونَ ٱلۡبَأۡسَ إِلَّا قَلِیلًا\n\";s:13:\"numberInSurah\";i:18;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:420;s:4:\"ruku\";i:362;s:11:\"hizbQuarter\";i:168;s:5:\"sajda\";b:0;}i:18;a:9:{s:6:\"number\";i:3552;s:4:\"text\";s:642:\"أَشِحَّةً عَلَیۡكُمۡۖ فَإِذَا جَاۤءَ ٱلۡخَوۡفُ رَأَیۡتَهُمۡ یَنظُرُونَ إِلَیۡكَ تَدُورُ أَعۡیُنُهُمۡ كَٱلَّذِی یُغۡشَىٰ عَلَیۡهِ مِنَ ٱلۡمَوۡتِۖ فَإِذَا ذَهَبَ ٱلۡخَوۡفُ سَلَقُوكُم بِأَلۡسِنَةٍ حِدَادٍ أَشِحَّةً عَلَى ٱلۡخَیۡرِۚ أُو۟لَـٰۤىِٕكَ لَمۡ یُؤۡمِنُوا۟ فَأَحۡبَطَ ٱللَّهُ أَعۡمَـٰلَهُمۡۚ وَكَانَ ذَ ٰ⁠لِكَ عَلَى ٱللَّهِ یَسِیرࣰا\n\";s:13:\"numberInSurah\";i:19;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:420;s:4:\"ruku\";i:362;s:11:\"hizbQuarter\";i:168;s:5:\"sajda\";b:0;}i:19;a:9:{s:6:\"number\";i:3553;s:4:\"text\";s:402:\"یَحۡسَبُونَ ٱلۡأَحۡزَابَ لَمۡ یَذۡهَبُوا۟ۖ وَإِن یَأۡتِ ٱلۡأَحۡزَابُ یَوَدُّوا۟ لَوۡ أَنَّهُم بَادُونَ فِی ٱلۡأَعۡرَابِ یَسۡـَٔلُونَ عَنۡ أَنۢبَاۤىِٕكُمۡۖ وَلَوۡ كَانُوا۟ فِیكُم مَّا قَـٰتَلُوۤا۟ إِلَّا قَلِیلࣰا\n\";s:13:\"numberInSurah\";i:20;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:420;s:4:\"ruku\";i:362;s:11:\"hizbQuarter\";i:168;s:5:\"sajda\";b:0;}i:20;a:9:{s:6:\"number\";i:3554;s:4:\"text\";s:265:\"لَّقَدۡ كَانَ لَكُمۡ فِی رَسُولِ ٱللَّهِ أُسۡوَةٌ حَسَنَةࣱ لِّمَن كَانَ یَرۡجُوا۟ ٱللَّهَ وَٱلۡیَوۡمَ ٱلۡـَٔاخِرَ وَذَكَرَ ٱللَّهَ كَثِیرࣰا\n\";s:13:\"numberInSurah\";i:21;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:420;s:4:\"ruku\";i:363;s:11:\"hizbQuarter\";i:168;s:5:\"sajda\";b:0;}i:21;a:9:{s:6:\"number\";i:3555;s:4:\"text\";s:332:\"وَلَمَّا رَءَا ٱلۡمُؤۡمِنُونَ ٱلۡأَحۡزَابَ قَالُوا۟ هَـٰذَا مَا وَعَدَنَا ٱللَّهُ وَرَسُولُهُۥ وَصَدَقَ ٱللَّهُ وَرَسُولُهُۥۚ وَمَا زَادَهُمۡ إِلَّاۤ إِیمَـٰنࣰا وَتَسۡلِیمࣰا\n\";s:13:\"numberInSurah\";i:22;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:420;s:4:\"ruku\";i:363;s:11:\"hizbQuarter\";i:168;s:5:\"sajda\";b:0;}i:22;a:9:{s:6:\"number\";i:3556;s:4:\"text\";s:302:\"مِّنَ ٱلۡمُؤۡمِنِینَ رِجَالࣱ صَدَقُوا۟ مَا عَـٰهَدُوا۟ ٱللَّهَ عَلَیۡهِۖ فَمِنۡهُم مَّن قَضَىٰ نَحۡبَهُۥ وَمِنۡهُم مَّن یَنتَظِرُۖ وَمَا بَدَّلُوا۟ تَبۡدِیلࣰا\n\";s:13:\"numberInSurah\";i:23;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:421;s:4:\"ruku\";i:363;s:11:\"hizbQuarter\";i:168;s:5:\"sajda\";b:0;}i:23;a:9:{s:6:\"number\";i:3557;s:4:\"text\";s:290:\"لِّیَجۡزِیَ ٱللَّهُ ٱلصَّـٰدِقِینَ بِصِدۡقِهِمۡ وَیُعَذِّبَ ٱلۡمُنَـٰفِقِینَ إِن شَاۤءَ أَوۡ یَتُوبَ عَلَیۡهِمۡۚ إِنَّ ٱللَّهَ كَانَ غَفُورࣰا رَّحِیمࣰا\n\";s:13:\"numberInSurah\";i:24;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:421;s:4:\"ruku\";i:363;s:11:\"hizbQuarter\";i:168;s:5:\"sajda\";b:0;}i:24;a:9:{s:6:\"number\";i:3558;s:4:\"text\";s:288:\"وَرَدَّ ٱللَّهُ ٱلَّذِینَ كَفَرُوا۟ بِغَیۡظِهِمۡ لَمۡ یَنَالُوا۟ خَیۡرࣰاۚ وَكَفَى ٱللَّهُ ٱلۡمُؤۡمِنِینَ ٱلۡقِتَالَۚ وَكَانَ ٱللَّهُ قَوِیًّا عَزِیزࣰا\n\";s:13:\"numberInSurah\";i:25;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:421;s:4:\"ruku\";i:363;s:11:\"hizbQuarter\";i:168;s:5:\"sajda\";b:0;}i:25;a:9:{s:6:\"number\";i:3559;s:4:\"text\";s:294:\"وَأَنزَلَ ٱلَّذِینَ ظَـٰهَرُوهُم مِّنۡ أَهۡلِ ٱلۡكِتَـٰبِ مِن صَیَاصِیهِمۡ وَقَذَفَ فِی قُلُوبِهِمُ ٱلرُّعۡبَ فَرِیقࣰا تَقۡتُلُونَ وَتَأۡسِرُونَ فَرِیقࣰا\n\";s:13:\"numberInSurah\";i:26;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:421;s:4:\"ruku\";i:363;s:11:\"hizbQuarter\";i:168;s:5:\"sajda\";b:0;}i:26;a:9:{s:6:\"number\";i:3560;s:4:\"text\";s:258:\"وَأَوۡرَثَكُمۡ أَرۡضَهُمۡ وَدِیَـٰرَهُمۡ وَأَمۡوَ ٰ⁠لَهُمۡ وَأَرۡضࣰا لَّمۡ تَطَـُٔوهَاۚ وَكَانَ ٱللَّهُ عَلَىٰ كُلِّ شَیۡءࣲ قَدِیرࣰا\n\";s:13:\"numberInSurah\";i:27;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:421;s:4:\"ruku\";i:363;s:11:\"hizbQuarter\";i:168;s:5:\"sajda\";b:0;}i:27;a:9:{s:6:\"number\";i:3561;s:4:\"text\";s:325:\"یَـٰۤأَیُّهَا ٱلنَّبِیُّ قُل لِّأَزۡوَ ٰ⁠جِكَ إِن كُنتُنَّ تُرِدۡنَ ٱلۡحَیَوٰةَ ٱلدُّنۡیَا وَزِینَتَهَا فَتَعَالَیۡنَ أُمَتِّعۡكُنَّ وَأُسَرِّحۡكُنَّ سَرَاحࣰا جَمِیلࣰا\n\";s:13:\"numberInSurah\";i:28;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:421;s:4:\"ruku\";i:364;s:11:\"hizbQuarter\";i:168;s:5:\"sajda\";b:0;}i:28;a:9:{s:6:\"number\";i:3562;s:4:\"text\";s:261:\"وَإِن كُنتُنَّ تُرِدۡنَ ٱللَّهَ وَرَسُولَهُۥ وَٱلدَّارَ ٱلۡـَٔاخِرَةَ فَإِنَّ ٱللَّهَ أَعَدَّ لِلۡمُحۡسِنَـٰتِ مِنكُنَّ أَجۡرًا عَظِیمࣰا\n\";s:13:\"numberInSurah\";i:29;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:421;s:4:\"ruku\";i:364;s:11:\"hizbQuarter\";i:168;s:5:\"sajda\";b:0;}i:29;a:9:{s:6:\"number\";i:3563;s:4:\"text\";s:291:\"یَـٰنِسَاۤءَ ٱلنَّبِیِّ مَن یَأۡتِ مِنكُنَّ بِفَـٰحِشَةࣲ مُّبَیِّنَةࣲ یُضَـٰعَفۡ لَهَا ٱلۡعَذَابُ ضِعۡفَیۡنِۚ وَكَانَ ذَ ٰ⁠لِكَ عَلَى ٱللَّهِ یَسِیرࣰا\n\";s:13:\"numberInSurah\";i:30;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:421;s:4:\"ruku\";i:364;s:11:\"hizbQuarter\";i:168;s:5:\"sajda\";b:0;}i:30;a:9:{s:6:\"number\";i:3564;s:4:\"text\";s:266:\"۞ وَمَن یَقۡنُتۡ مِنكُنَّ لِلَّهِ وَرَسُولِهِۦ وَتَعۡمَلۡ صَـٰلِحࣰا نُّؤۡتِهَاۤ أَجۡرَهَا مَرَّتَیۡنِ وَأَعۡتَدۡنَا لَهَا رِزۡقࣰا كَرِیمࣰا\n\";s:13:\"numberInSurah\";i:31;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:422;s:4:\"ruku\";i:364;s:11:\"hizbQuarter\";i:169;s:5:\"sajda\";b:0;}i:31;a:9:{s:6:\"number\";i:3565;s:4:\"text\";s:343:\"یَـٰنِسَاۤءَ ٱلنَّبِیِّ لَسۡتُنَّ كَأَحَدࣲ مِّنَ ٱلنِّسَاۤءِ إِنِ ٱتَّقَیۡتُنَّۚ فَلَا تَخۡضَعۡنَ بِٱلۡقَوۡلِ فَیَطۡمَعَ ٱلَّذِی فِی قَلۡبِهِۦ مَرَضࣱ وَقُلۡنَ قَوۡلࣰا مَّعۡرُوفࣰا\n\";s:13:\"numberInSurah\";i:32;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:422;s:4:\"ruku\";i:364;s:11:\"hizbQuarter\";i:169;s:5:\"sajda\";b:0;}i:32;a:9:{s:6:\"number\";i:3566;s:4:\"text\";s:498:\"وَقَرۡنَ فِی بُیُوتِكُنَّ وَلَا تَبَرَّجۡنَ تَبَرُّجَ ٱلۡجَـٰهِلِیَّةِ ٱلۡأُولَىٰۖ وَأَقِمۡنَ ٱلصَّلَوٰةَ وَءَاتِینَ ٱلزَّكَوٰةَ وَأَطِعۡنَ ٱللَّهَ وَرَسُولَهُۥۤۚ إِنَّمَا یُرِیدُ ٱللَّهُ لِیُذۡهِبَ عَنكُمُ ٱلرِّجۡسَ أَهۡلَ ٱلۡبَیۡتِ وَیُطَهِّرَكُمۡ تَطۡهِیرࣰا\n\";s:13:\"numberInSurah\";i:33;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:422;s:4:\"ruku\";i:364;s:11:\"hizbQuarter\";i:169;s:5:\"sajda\";b:0;}i:33;a:9:{s:6:\"number\";i:3567;s:4:\"text\";s:222:\"وَٱذۡكُرۡنَ مَا یُتۡلَىٰ فِی بُیُوتِكُنَّ مِنۡ ءَایَـٰتِ ٱللَّهِ وَٱلۡحِكۡمَةِۚ إِنَّ ٱللَّهَ كَانَ لَطِیفًا خَبِیرًا\n\";s:13:\"numberInSurah\";i:34;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:422;s:4:\"ruku\";i:364;s:11:\"hizbQuarter\";i:169;s:5:\"sajda\";b:0;}i:34;a:9:{s:6:\"number\";i:3568;s:4:\"text\";s:881:\"إِنَّ ٱلۡمُسۡلِمِینَ وَٱلۡمُسۡلِمَـٰتِ وَٱلۡمُؤۡمِنِینَ وَٱلۡمُؤۡمِنَـٰتِ وَٱلۡقَـٰنِتِینَ وَٱلۡقَـٰنِتَـٰتِ وَٱلصَّـٰدِقِینَ وَٱلصَّـٰدِقَـٰتِ وَٱلصَّـٰبِرِینَ وَٱلصَّـٰبِرَ ٰ⁠تِ وَٱلۡخَـٰشِعِینَ وَٱلۡخَـٰشِعَـٰتِ وَٱلۡمُتَصَدِّقِینَ وَٱلۡمُتَصَدِّقَـٰتِ وَٱلصَّـٰۤىِٕمِینَ وَٱلصَّـٰۤىِٕمَـٰتِ وَٱلۡحَـٰفِظِینَ فُرُوجَهُمۡ وَٱلۡحَـٰفِظَـٰتِ وَٱلذَّ ٰ⁠كِرِینَ ٱللَّهَ كَثِیرࣰا وَٱلذَّ ٰ⁠كِرَ ٰ⁠تِ أَعَدَّ ٱللَّهُ لَهُم مَّغۡفِرَةࣰ وَأَجۡرًا عَظِیمࣰا\n\";s:13:\"numberInSurah\";i:35;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:422;s:4:\"ruku\";i:365;s:11:\"hizbQuarter\";i:169;s:5:\"sajda\";b:0;}i:35;a:9:{s:6:\"number\";i:3569;s:4:\"text\";s:373:\"وَمَا كَانَ لِمُؤۡمِنࣲ وَلَا مُؤۡمِنَةٍ إِذَا قَضَى ٱللَّهُ وَرَسُولُهُۥۤ أَمۡرًا أَن یَكُونَ لَهُمُ ٱلۡخِیَرَةُ مِنۡ أَمۡرِهِمۡۗ وَمَن یَعۡصِ ٱللَّهَ وَرَسُولَهُۥ فَقَدۡ ضَلَّ ضَلَـٰلࣰا مُّبِینࣰا\n\";s:13:\"numberInSurah\";i:36;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:423;s:4:\"ruku\";i:365;s:11:\"hizbQuarter\";i:169;s:5:\"sajda\";b:0;}i:36;a:9:{s:6:\"number\";i:3570;s:4:\"text\";s:803:\"وَإِذۡ تَقُولُ لِلَّذِیۤ أَنۡعَمَ ٱللَّهُ عَلَیۡهِ وَأَنۡعَمۡتَ عَلَیۡهِ أَمۡسِكۡ عَلَیۡكَ زَوۡجَكَ وَٱتَّقِ ٱللَّهَ وَتُخۡفِی فِی نَفۡسِكَ مَا ٱللَّهُ مُبۡدِیهِ وَتَخۡشَى ٱلنَّاسَ وَٱللَّهُ أَحَقُّ أَن تَخۡشَىٰهُۖ فَلَمَّا قَضَىٰ زَیۡدࣱ مِّنۡهَا وَطَرࣰا زَوَّجۡنَـٰكَهَا لِكَیۡ لَا یَكُونَ عَلَى ٱلۡمُؤۡمِنِینَ حَرَجࣱ فِیۤ أَزۡوَ ٰ⁠جِ أَدۡعِیَاۤىِٕهِمۡ إِذَا قَضَوۡا۟ مِنۡهُنَّ وَطَرࣰاۚ وَكَانَ أَمۡرُ ٱللَّهِ مَفۡعُولࣰا\n\";s:13:\"numberInSurah\";i:37;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:423;s:4:\"ruku\";i:365;s:11:\"hizbQuarter\";i:169;s:5:\"sajda\";b:0;}i:37;a:9:{s:6:\"number\";i:3571;s:4:\"text\";s:306:\"مَّا كَانَ عَلَى ٱلنَّبِیِّ مِنۡ حَرَجࣲ فِیمَا فَرَضَ ٱللَّهُ لَهُۥۖ سُنَّةَ ٱللَّهِ فِی ٱلَّذِینَ خَلَوۡا۟ مِن قَبۡلُۚ وَكَانَ أَمۡرُ ٱللَّهِ قَدَرࣰا مَّقۡدُورًا\n\";s:13:\"numberInSurah\";i:38;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:423;s:4:\"ruku\";i:365;s:11:\"hizbQuarter\";i:169;s:5:\"sajda\";b:0;}i:38;a:9:{s:6:\"number\";i:3572;s:4:\"text\";s:246:\"ٱلَّذِینَ یُبَلِّغُونَ رِسَـٰلَـٰتِ ٱللَّهِ وَیَخۡشَوۡنَهُۥ وَلَا یَخۡشَوۡنَ أَحَدًا إِلَّا ٱللَّهَۗ وَكَفَىٰ بِٱللَّهِ حَسِیبࣰا\n\";s:13:\"numberInSurah\";i:39;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:423;s:4:\"ruku\";i:365;s:11:\"hizbQuarter\";i:169;s:5:\"sajda\";b:0;}i:39;a:9:{s:6:\"number\";i:3573;s:4:\"text\";s:277:\"مَّا كَانَ مُحَمَّدٌ أَبَاۤ أَحَدࣲ مِّن رِّجَالِكُمۡ وَلَـٰكِن رَّسُولَ ٱللَّهِ وَخَاتَمَ ٱلنَّبِیِّـۧنَۗ وَكَانَ ٱللَّهُ بِكُلِّ شَیۡءٍ عَلِیمࣰا\n\";s:13:\"numberInSurah\";i:40;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:423;s:4:\"ruku\";i:365;s:11:\"hizbQuarter\";i:169;s:5:\"sajda\";b:0;}i:40;a:9:{s:6:\"number\";i:3574;s:4:\"text\";s:137:\"یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ ٱذۡكُرُوا۟ ٱللَّهَ ذِكۡرࣰا كَثِیرࣰا\n\";s:13:\"numberInSurah\";i:41;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:423;s:4:\"ruku\";i:366;s:11:\"hizbQuarter\";i:169;s:5:\"sajda\";b:0;}i:41;a:9:{s:6:\"number\";i:3575;s:4:\"text\";s:64:\"وَسَبِّحُوهُ بُكۡرَةࣰ وَأَصِیلًا\n\";s:13:\"numberInSurah\";i:42;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:423;s:4:\"ruku\";i:366;s:11:\"hizbQuarter\";i:169;s:5:\"sajda\";b:0;}i:42;a:9:{s:6:\"number\";i:3576;s:4:\"text\";s:262:\"هُوَ ٱلَّذِی یُصَلِّی عَلَیۡكُمۡ وَمَلَـٰۤىِٕكَتُهُۥ لِیُخۡرِجَكُم مِّنَ ٱلظُّلُمَـٰتِ إِلَى ٱلنُّورِۚ وَكَانَ بِٱلۡمُؤۡمِنِینَ رَحِیمࣰا\n\";s:13:\"numberInSurah\";i:43;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:423;s:4:\"ruku\";i:366;s:11:\"hizbQuarter\";i:169;s:5:\"sajda\";b:0;}i:43;a:9:{s:6:\"number\";i:3577;s:4:\"text\";s:153:\"تَحِیَّتُهُمۡ یَوۡمَ یَلۡقَوۡنَهُۥ سَلَـٰمࣱۚ وَأَعَدَّ لَهُمۡ أَجۡرࣰا كَرِیمࣰا\n\";s:13:\"numberInSurah\";i:44;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:424;s:4:\"ruku\";i:366;s:11:\"hizbQuarter\";i:169;s:5:\"sajda\";b:0;}i:44;a:9:{s:6:\"number\";i:3578;s:4:\"text\";s:160:\"یَـٰۤأَیُّهَا ٱلنَّبِیُّ إِنَّاۤ أَرۡسَلۡنَـٰكَ شَـٰهِدࣰا وَمُبَشِّرࣰا وَنَذِیرࣰا\n\";s:13:\"numberInSurah\";i:45;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:424;s:4:\"ruku\";i:366;s:11:\"hizbQuarter\";i:169;s:5:\"sajda\";b:0;}i:45;a:9:{s:6:\"number\";i:3579;s:4:\"text\";s:112:\"وَدَاعِیًا إِلَى ٱللَّهِ بِإِذۡنِهِۦ وَسِرَاجࣰا مُّنِیرࣰا\n\";s:13:\"numberInSurah\";i:46;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:424;s:4:\"ruku\";i:366;s:11:\"hizbQuarter\";i:169;s:5:\"sajda\";b:0;}i:46;a:9:{s:6:\"number\";i:3580;s:4:\"text\";s:134:\"وَبَشِّرِ ٱلۡمُؤۡمِنِینَ بِأَنَّ لَهُم مِّنَ ٱللَّهِ فَضۡلࣰا كَبِیرࣰا\n\";s:13:\"numberInSurah\";i:47;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:424;s:4:\"ruku\";i:366;s:11:\"hizbQuarter\";i:169;s:5:\"sajda\";b:0;}i:47;a:9:{s:6:\"number\";i:3581;s:4:\"text\";s:229:\"وَلَا تُطِعِ ٱلۡكَـٰفِرِینَ وَٱلۡمُنَـٰفِقِینَ وَدَعۡ أَذَىٰهُمۡ وَتَوَكَّلۡ عَلَى ٱللَّهِۚ وَكَفَىٰ بِٱللَّهِ وَكِیلࣰا\n\";s:13:\"numberInSurah\";i:48;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:424;s:4:\"ruku\";i:366;s:11:\"hizbQuarter\";i:169;s:5:\"sajda\";b:0;}i:48;a:9:{s:6:\"number\";i:3582;s:4:\"text\";s:435:\"یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوۤا۟ إِذَا نَكَحۡتُمُ ٱلۡمُؤۡمِنَـٰتِ ثُمَّ طَلَّقۡتُمُوهُنَّ مِن قَبۡلِ أَن تَمَسُّوهُنَّ فَمَا لَكُمۡ عَلَیۡهِنَّ مِنۡ عِدَّةࣲ تَعۡتَدُّونَهَاۖ فَمَتِّعُوهُنَّ وَسَرِّحُوهُنَّ سَرَاحࣰا جَمِیلࣰا\n\";s:13:\"numberInSurah\";i:49;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:424;s:4:\"ruku\";i:366;s:11:\"hizbQuarter\";i:169;s:5:\"sajda\";b:0;}i:49;a:9:{s:6:\"number\";i:3583;s:4:\"text\";s:1088:\"یَـٰۤأَیُّهَا ٱلنَّبِیُّ إِنَّاۤ أَحۡلَلۡنَا لَكَ أَزۡوَ ٰ⁠جَكَ ٱلَّـٰتِیۤ ءَاتَیۡتَ أُجُورَهُنَّ وَمَا مَلَكَتۡ یَمِینُكَ مِمَّاۤ أَفَاۤءَ ٱللَّهُ عَلَیۡكَ وَبَنَاتِ عَمِّكَ وَبَنَاتِ عَمَّـٰتِكَ وَبَنَاتِ خَالِكَ وَبَنَاتِ خَـٰلَـٰتِكَ ٱلَّـٰتِی هَاجَرۡنَ مَعَكَ وَٱمۡرَأَةࣰ مُّؤۡمِنَةً إِن وَهَبَتۡ نَفۡسَهَا لِلنَّبِیِّ إِنۡ أَرَادَ ٱلنَّبِیُّ أَن یَسۡتَنكِحَهَا خَالِصَةࣰ لَّكَ مِن دُونِ ٱلۡمُؤۡمِنِینَۗ قَدۡ عَلِمۡنَا مَا فَرَضۡنَا عَلَیۡهِمۡ فِیۤ أَزۡوَ ٰ⁠جِهِمۡ وَمَا مَلَكَتۡ أَیۡمَـٰنُهُمۡ لِكَیۡلَا یَكُونَ عَلَیۡكَ حَرَجࣱۗ وَكَانَ ٱللَّهُ غَفُورࣰا رَّحِیمࣰا\n\";s:13:\"numberInSurah\";i:50;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:424;s:4:\"ruku\";i:366;s:11:\"hizbQuarter\";i:169;s:5:\"sajda\";b:0;}i:50;a:9:{s:6:\"number\";i:3584;s:4:\"text\";s:589:\"۞ تُرۡجِی مَن تَشَاۤءُ مِنۡهُنَّ وَتُـٔۡوِیۤ إِلَیۡكَ مَن تَشَاۤءُۖ وَمَنِ ٱبۡتَغَیۡتَ مِمَّنۡ عَزَلۡتَ فَلَا جُنَاحَ عَلَیۡكَۚ ذَ ٰ⁠لِكَ أَدۡنَىٰۤ أَن تَقَرَّ أَعۡیُنُهُنَّ وَلَا یَحۡزَنَّ وَیَرۡضَیۡنَ بِمَاۤ ءَاتَیۡتَهُنَّ كُلُّهُنَّۚ وَٱللَّهُ یَعۡلَمُ مَا فِی قُلُوبِكُمۡۚ وَكَانَ ٱللَّهُ عَلِیمًا حَلِیمࣰا\n\";s:13:\"numberInSurah\";i:51;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:425;s:4:\"ruku\";i:366;s:11:\"hizbQuarter\";i:170;s:5:\"sajda\";b:0;}i:51;a:9:{s:6:\"number\";i:3585;s:4:\"text\";s:370:\"لَّا یَحِلُّ لَكَ ٱلنِّسَاۤءُ مِنۢ بَعۡدُ وَلَاۤ أَن تَبَدَّلَ بِهِنَّ مِنۡ أَزۡوَ ٰ⁠جࣲ وَلَوۡ أَعۡجَبَكَ حُسۡنُهُنَّ إِلَّا مَا مَلَكَتۡ یَمِینُكَۗ وَكَانَ ٱللَّهُ عَلَىٰ كُلِّ شَیۡءࣲ رَّقِیبࣰا\n\";s:13:\"numberInSurah\";i:52;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:425;s:4:\"ruku\";i:366;s:11:\"hizbQuarter\";i:170;s:5:\"sajda\";b:0;}i:52;a:9:{s:6:\"number\";i:3586;s:4:\"text\";s:1217:\"یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ لَا تَدۡخُلُوا۟ بُیُوتَ ٱلنَّبِیِّ إِلَّاۤ أَن یُؤۡذَنَ لَكُمۡ إِلَىٰ طَعَامٍ غَیۡرَ نَـٰظِرِینَ إِنَىٰهُ وَلَـٰكِنۡ إِذَا دُعِیتُمۡ فَٱدۡخُلُوا۟ فَإِذَا طَعِمۡتُمۡ فَٱنتَشِرُوا۟ وَلَا مُسۡتَـٔۡنِسِینَ لِحَدِیثٍۚ إِنَّ ذَ ٰ⁠لِكُمۡ كَانَ یُؤۡذِی ٱلنَّبِیَّ فَیَسۡتَحۡیِۦ مِنكُمۡۖ وَٱللَّهُ لَا یَسۡتَحۡیِۦ مِنَ ٱلۡحَقِّۚ وَإِذَا سَأَلۡتُمُوهُنَّ مَتَـٰعࣰا فَسۡـَٔلُوهُنَّ مِن وَرَاۤءِ حِجَابࣲۚ ذَ ٰ⁠لِكُمۡ أَطۡهَرُ لِقُلُوبِكُمۡ وَقُلُوبِهِنَّۚ وَمَا كَانَ لَكُمۡ أَن تُؤۡذُوا۟ رَسُولَ ٱللَّهِ وَلَاۤ أَن تَنكِحُوۤا۟ أَزۡوَ ٰ⁠جَهُۥ مِنۢ بَعۡدِهِۦۤ أَبَدًاۚ إِنَّ ذَ ٰ⁠لِكُمۡ كَانَ عِندَ ٱللَّهِ عَظِیمًا\n\";s:13:\"numberInSurah\";i:53;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:425;s:4:\"ruku\";i:367;s:11:\"hizbQuarter\";i:170;s:5:\"sajda\";b:0;}i:53;a:9:{s:6:\"number\";i:3587;s:4:\"text\";s:158:\"إِن تُبۡدُوا۟ شَیۡـًٔا أَوۡ تُخۡفُوهُ فَإِنَّ ٱللَّهَ كَانَ بِكُلِّ شَیۡءٍ عَلِیمࣰا\n\";s:13:\"numberInSurah\";i:54;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:425;s:4:\"ruku\";i:367;s:11:\"hizbQuarter\";i:170;s:5:\"sajda\";b:0;}i:54;a:9:{s:6:\"number\";i:3588;s:4:\"text\";s:559:\"لَّا جُنَاحَ عَلَیۡهِنَّ فِیۤ ءَابَاۤىِٕهِنَّ وَلَاۤ أَبۡنَاۤىِٕهِنَّ وَلَاۤ إِخۡوَ ٰ⁠نِهِنَّ وَلَاۤ أَبۡنَاۤءِ إِخۡوَ ٰ⁠نِهِنَّ وَلَاۤ أَبۡنَاۤءِ أَخَوَ ٰ⁠تِهِنَّ وَلَا نِسَاۤىِٕهِنَّ وَلَا مَا مَلَكَتۡ أَیۡمَـٰنُهُنَّۗ وَٱتَّقِینَ ٱللَّهَۚ إِنَّ ٱللَّهَ كَانَ عَلَىٰ كُلِّ شَیۡءࣲ شَهِیدًا\n\";s:13:\"numberInSurah\";i:55;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:426;s:4:\"ruku\";i:367;s:11:\"hizbQuarter\";i:170;s:5:\"sajda\";b:0;}i:55;a:9:{s:6:\"number\";i:3589;s:4:\"text\";s:267:\"إِنَّ ٱللَّهَ وَمَلَـٰۤىِٕكَتَهُۥ یُصَلُّونَ عَلَى ٱلنَّبِیِّۚ یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ صَلُّوا۟ عَلَیۡهِ وَسَلِّمُوا۟ تَسۡلِیمًا\n\";s:13:\"numberInSurah\";i:56;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:426;s:4:\"ruku\";i:367;s:11:\"hizbQuarter\";i:170;s:5:\"sajda\";b:0;}i:56;a:9:{s:6:\"number\";i:3590;s:4:\"text\";s:254:\"إِنَّ ٱلَّذِینَ یُؤۡذُونَ ٱللَّهَ وَرَسُولَهُۥ لَعَنَهُمُ ٱللَّهُ فِی ٱلدُّنۡیَا وَٱلۡـَٔاخِرَةِ وَأَعَدَّ لَهُمۡ عَذَابࣰا مُّهِینࣰا\n\";s:13:\"numberInSurah\";i:57;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:426;s:4:\"ruku\";i:367;s:11:\"hizbQuarter\";i:170;s:5:\"sajda\";b:0;}i:57;a:9:{s:6:\"number\";i:3591;s:4:\"text\";s:257:\"وَٱلَّذِینَ یُؤۡذُونَ ٱلۡمُؤۡمِنِینَ وَٱلۡمُؤۡمِنَـٰتِ بِغَیۡرِ مَا ٱكۡتَسَبُوا۟ فَقَدِ ٱحۡتَمَلُوا۟ بُهۡتَـٰنࣰا وَإِثۡمࣰا مُّبِینࣰا\n\";s:13:\"numberInSurah\";i:58;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:426;s:4:\"ruku\";i:367;s:11:\"hizbQuarter\";i:170;s:5:\"sajda\";b:0;}i:58;a:9:{s:6:\"number\";i:3592;s:4:\"text\";s:417:\"یَـٰۤأَیُّهَا ٱلنَّبِیُّ قُل لِّأَزۡوَ ٰ⁠جِكَ وَبَنَاتِكَ وَنِسَاۤءِ ٱلۡمُؤۡمِنِینَ یُدۡنِینَ عَلَیۡهِنَّ مِن جَلَـٰبِیبِهِنَّۚ ذَ ٰ⁠لِكَ أَدۡنَىٰۤ أَن یُعۡرَفۡنَ فَلَا یُؤۡذَیۡنَۗ وَكَانَ ٱللَّهُ غَفُورࣰا رَّحِیمࣰا\n\";s:13:\"numberInSurah\";i:59;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:426;s:4:\"ruku\";i:368;s:11:\"hizbQuarter\";i:170;s:5:\"sajda\";b:0;}i:59;a:9:{s:6:\"number\";i:3593;s:4:\"text\";s:346:\"۞ لَّىِٕن لَّمۡ یَنتَهِ ٱلۡمُنَـٰفِقُونَ وَٱلَّذِینَ فِی قُلُوبِهِم مَّرَضࣱ وَٱلۡمُرۡجِفُونَ فِی ٱلۡمَدِینَةِ لَنُغۡرِیَنَّكَ بِهِمۡ ثُمَّ لَا یُجَاوِرُونَكَ فِیهَاۤ إِلَّا قَلِیلࣰا\n\";s:13:\"numberInSurah\";i:60;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:426;s:4:\"ruku\";i:368;s:11:\"hizbQuarter\";i:171;s:5:\"sajda\";b:0;}i:60;a:9:{s:6:\"number\";i:3594;s:4:\"text\";s:135:\"مَّلۡعُونِینَۖ أَیۡنَمَا ثُقِفُوۤا۟ أُخِذُوا۟ وَقُتِّلُوا۟ تَقۡتِیلࣰا\n\";s:13:\"numberInSurah\";i:61;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:426;s:4:\"ruku\";i:368;s:11:\"hizbQuarter\";i:171;s:5:\"sajda\";b:0;}i:61;a:9:{s:6:\"number\";i:3595;s:4:\"text\";s:175:\"سُنَّةَ ٱللَّهِ فِی ٱلَّذِینَ خَلَوۡا۟ مِن قَبۡلُۖ وَلَن تَجِدَ لِسُنَّةِ ٱللَّهِ تَبۡدِیلࣰا\n\";s:13:\"numberInSurah\";i:62;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:426;s:4:\"ruku\";i:368;s:11:\"hizbQuarter\";i:171;s:5:\"sajda\";b:0;}i:62;a:9:{s:6:\"number\";i:3596;s:4:\"text\";s:243:\"یَسۡـَٔلُكَ ٱلنَّاسُ عَنِ ٱلسَّاعَةِۖ قُلۡ إِنَّمَا عِلۡمُهَا عِندَ ٱللَّهِۚ وَمَا یُدۡرِیكَ لَعَلَّ ٱلسَّاعَةَ تَكُونُ قَرِیبًا\n\";s:13:\"numberInSurah\";i:63;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:427;s:4:\"ruku\";i:368;s:11:\"hizbQuarter\";i:171;s:5:\"sajda\";b:0;}i:63;a:9:{s:6:\"number\";i:3597;s:4:\"text\";s:117:\"إِنَّ ٱللَّهَ لَعَنَ ٱلۡكَـٰفِرِینَ وَأَعَدَّ لَهُمۡ سَعِیرًا\n\";s:13:\"numberInSurah\";i:64;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:427;s:4:\"ruku\";i:368;s:11:\"hizbQuarter\";i:171;s:5:\"sajda\";b:0;}i:64;a:9:{s:6:\"number\";i:3598;s:4:\"text\";s:131:\"خَـٰلِدِینَ فِیهَاۤ أَبَدࣰاۖ لَّا یَجِدُونَ وَلِیࣰّا وَلَا نَصِیرࣰا\n\";s:13:\"numberInSurah\";i:65;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:427;s:4:\"ruku\";i:368;s:11:\"hizbQuarter\";i:171;s:5:\"sajda\";b:0;}i:65;a:9:{s:6:\"number\";i:3599;s:4:\"text\";s:211:\"یَوۡمَ تُقَلَّبُ وُجُوهُهُمۡ فِی ٱلنَّارِ یَقُولُونَ یَـٰلَیۡتَنَاۤ أَطَعۡنَا ٱللَّهَ وَأَطَعۡنَا ٱلرَّسُولَا۠\n\";s:13:\"numberInSurah\";i:66;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:427;s:4:\"ruku\";i:368;s:11:\"hizbQuarter\";i:171;s:5:\"sajda\";b:0;}i:66;a:9:{s:6:\"number\";i:3600;s:4:\"text\";s:178:\"وَقَالُوا۟ رَبَّنَاۤ إِنَّاۤ أَطَعۡنَا سَادَتَنَا وَكُبَرَاۤءَنَا فَأَضَلُّونَا ٱلسَّبِیلَا۠\n\";s:13:\"numberInSurah\";i:67;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:427;s:4:\"ruku\";i:368;s:11:\"hizbQuarter\";i:171;s:5:\"sajda\";b:0;}i:67;a:9:{s:6:\"number\";i:3601;s:4:\"text\";s:150:\"رَبَّنَاۤ ءَاتِهِمۡ ضِعۡفَیۡنِ مِنَ ٱلۡعَذَابِ وَٱلۡعَنۡهُمۡ لَعۡنࣰا كَبِیرࣰا\n\";s:13:\"numberInSurah\";i:68;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:427;s:4:\"ruku\";i:368;s:11:\"hizbQuarter\";i:171;s:5:\"sajda\";b:0;}i:68;a:9:{s:6:\"number\";i:3602;s:4:\"text\";s:281:\"یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ لَا تَكُونُوا۟ كَٱلَّذِینَ ءَاذَوۡا۟ مُوسَىٰ فَبَرَّأَهُ ٱللَّهُ مِمَّا قَالُوا۟ۚ وَكَانَ عِندَ ٱللَّهِ وَجِیهࣰا\n\";s:13:\"numberInSurah\";i:69;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:427;s:4:\"ruku\";i:369;s:11:\"hizbQuarter\";i:171;s:5:\"sajda\";b:0;}i:69;a:9:{s:6:\"number\";i:3603;s:4:\"text\";s:156:\"یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ ٱتَّقُوا۟ ٱللَّهَ وَقُولُوا۟ قَوۡلࣰا سَدِیدࣰا\n\";s:13:\"numberInSurah\";i:70;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:427;s:4:\"ruku\";i:369;s:11:\"hizbQuarter\";i:171;s:5:\"sajda\";b:0;}i:70;a:9:{s:6:\"number\";i:3604;s:4:\"text\";s:238:\"یُصۡلِحۡ لَكُمۡ أَعۡمَـٰلَكُمۡ وَیَغۡفِرۡ لَكُمۡ ذُنُوبَكُمۡۗ وَمَن یُطِعِ ٱللَّهَ وَرَسُولَهُۥ فَقَدۡ فَازَ فَوۡزًا عَظِیمًا\n\";s:13:\"numberInSurah\";i:71;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:427;s:4:\"ruku\";i:369;s:11:\"hizbQuarter\";i:171;s:5:\"sajda\";b:0;}i:71;a:9:{s:6:\"number\";i:3605;s:4:\"text\";s:360:\"إِنَّا عَرَضۡنَا ٱلۡأَمَانَةَ عَلَى ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِ وَٱلۡجِبَالِ فَأَبَیۡنَ أَن یَحۡمِلۡنَهَا وَأَشۡفَقۡنَ مِنۡهَا وَحَمَلَهَا ٱلۡإِنسَـٰنُۖ إِنَّهُۥ كَانَ ظَلُومࣰا جَهُولࣰا\n\";s:13:\"numberInSurah\";i:72;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:427;s:4:\"ruku\";i:369;s:11:\"hizbQuarter\";i:171;s:5:\"sajda\";b:0;}i:72;a:9:{s:6:\"number\";i:3606;s:4:\"text\";s:360:\"لِّیُعَذِّبَ ٱللَّهُ ٱلۡمُنَـٰفِقِینَ وَٱلۡمُنَـٰفِقَـٰتِ وَٱلۡمُشۡرِكِینَ وَٱلۡمُشۡرِكَـٰتِ وَیَتُوبَ ٱللَّهُ عَلَى ٱلۡمُؤۡمِنِینَ وَٱلۡمُؤۡمِنَـٰتِۗ وَكَانَ ٱللَّهُ غَفُورࣰا رَّحِیمَۢا\n\";s:13:\"numberInSurah\";i:73;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:427;s:4:\"ruku\";i:369;s:11:\"hizbQuarter\";i:171;s:5:\"sajda\";b:0;}}s:7:\"edition\";a:7:{s:10:\"identifier\";s:27:\"quran-uthmani-quran-academy\";s:8:\"language\";s:2:\"ar\";s:4:\"name\";s:67:\"القرآن الكريم برسم العثماني (quran-academy)\";s:11:\"englishName\";s:78:\"Modified Quran Uthmani Text from the Quran Academy to work with the Kitab font\";s:6:\"format\";s:4:\"text\";s:4:\"type\";s:5:\"quran\";s:9:\"direction\";s:3:\"rtl\";}}', 1794581366);
INSERT INTO `cache` (`key`, `value`, `expiration`) VALUES
('quranapp-cache-surah_33_fr.hamidullah', 'a:8:{s:6:\"number\";i:33;s:4:\"name\";s:37:\"سُورَةُ الأَحۡزَابِ\";s:11:\"englishName\";s:9:\"Al-Ahzaab\";s:22:\"englishNameTranslation\";s:9:\"The Clans\";s:14:\"revelationType\";s:7:\"Medinan\";s:13:\"numberOfAyahs\";i:73;s:5:\"ayahs\";a:73:{i:0;a:9:{s:6:\"number\";i:3534;s:4:\"text\";s:113:\"O Prophète! Crains Allah et n\'obéis pas aux infidèles et aux hypocrites, car Allah demeure Omniscient et Sage.\";s:13:\"numberInSurah\";i:1;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:418;s:4:\"ruku\";i:361;s:11:\"hizbQuarter\";i:167;s:5:\"sajda\";b:0;}i:1;a:9:{s:6:\"number\";i:3535;s:4:\"text\";s:118:\"Et suis ce qui t\'est révélé émanant de Ton Seigneur. Car Allah est Parfaitement Connaisseur de ce que vous faites.\";s:13:\"numberInSurah\";i:2;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:418;s:4:\"ruku\";i:361;s:11:\"hizbQuarter\";i:167;s:5:\"sajda\";b:0;}i:2;a:9:{s:6:\"number\";i:3536;s:4:\"text\";s:65:\"Et place ta confiance en Allah. Allah te suffit comme protecteur.\";s:13:\"numberInSurah\";i:3;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:418;s:4:\"ruku\";i:361;s:11:\"hizbQuarter\";i:167;s:5:\"sajda\";b:0;}i:3;a:9:{s:6:\"number\";i:3537;s:4:\"text\";s:406:\"Allah n\'a pas placé à l\'homme deux cœurs dans sa poitrine. Il n\'a point assimilé à vos mères vos épouses [à qui vous dites en les répudiant]: «Tu es [aussi illicite] pour moi que le dos de ma mère». Il n\'a point fait de vos enfants adoptifs vos propres enfants. Ce sont des propos [qui sortent] de votre bouche. Mais Allah dit la vérité et c\'est Lui qui met [l\'homme] dans la bonne direction.\";s:13:\"numberInSurah\";i:4;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:418;s:4:\"ruku\";i:361;s:11:\"hizbQuarter\";i:167;s:5:\"sajda\";b:0;}i:4;a:9:{s:6:\"number\";i:3538;s:4:\"text\";s:365:\"Appelez-les du nom de leurs pères: c\'est plus équitable devant Allah. Mais si vous ne connaissez pas leurs pères, alors considérez-les comme vos frères en religion ou vos alliés. Nul blâme sur vous pour ce que vous faites par erreur, mais (vous serez blâmés pour) ce que vos cœurs font délibérément. Allah, cependant, est Pardonneur et Miséricordieux.\";s:13:\"numberInSurah\";i:5;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:418;s:4:\"ruku\";i:361;s:11:\"hizbQuarter\";i:167;s:5:\"sajda\";b:0;}i:5;a:9:{s:6:\"number\";i:3539;s:4:\"text\";s:413:\"Le Prophète a plus de droit sur les croyants qu\'ils n\'en ont sur eux-mêmes; et ses épouses sont leurs mères. Les liens de consanguinité ont [dans les successions] la priorité [sur les liens] unissant les croyants [de Médine] et les émigrés [de la Mecque] selon le livre d\'Allah, à moins que vous ne fassiez un testament convenable en faveur de vos frères en religion. Et cela est inscrit dans le Livre.\";s:13:\"numberInSurah\";i:6;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:418;s:4:\"ruku\";i:361;s:11:\"hizbQuarter\";i:167;s:5:\"sajda\";b:0;}i:6;a:9:{s:6:\"number\";i:3540;s:4:\"text\";s:181:\"Lorsque Nous prîmes des prophètes leur engagement, de même que de toi, de Noé, d\'Abraham, de Moïse, et de Jésus fils de Marie: et Nous avons pris d\'eux un engagement solennel,\";s:13:\"numberInSurah\";i:7;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:419;s:4:\"ruku\";i:361;s:11:\"hizbQuarter\";i:167;s:5:\"sajda\";b:0;}i:7;a:9:{s:6:\"number\";i:3541;s:4:\"text\";s:122:\"afin [qu\'Allah] interroge les véridiques sur leur sincérité. Et Il a préparé aux infidèles un châtiment douloureux.\";s:13:\"numberInSurah\";i:8;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:419;s:4:\"ruku\";i:361;s:11:\"hizbQuarter\";i:167;s:5:\"sajda\";b:0;}i:8;a:9:{s:6:\"number\";i:3542;s:4:\"text\";s:235:\"O vous qui croyez! Rappelez-vous le bienfait d\'Allah sur vous, quand des troupes vous sont venues et que Nous avons envoyé contre elles un vent et des troupes que vous n\'avez pas vues. Allah demeure Clairvoyant sur ce que vous faites.\";s:13:\"numberInSurah\";i:9;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:419;s:4:\"ruku\";i:362;s:11:\"hizbQuarter\";i:167;s:5:\"sajda\";b:0;}i:9;a:9:{s:6:\"number\";i:3543;s:4:\"text\";s:199:\"Quand ils vous vinrent d\'en haut et d\'en bas [de toutes parts], et que les regards étaient troublés, et les cœurs remontaient aux gorges, et vous faisiez sur Allah toutes sortes de suppositions...\";s:13:\"numberInSurah\";i:10;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:419;s:4:\"ruku\";i:362;s:11:\"hizbQuarter\";i:167;s:5:\"sajda\";b:0;}i:10;a:9:{s:6:\"number\";i:3544;s:4:\"text\";s:69:\"Les croyants furent alors éprouvés et secoués d\'une dure secousse.\";s:13:\"numberInSurah\";i:11;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:419;s:4:\"ruku\";i:362;s:11:\"hizbQuarter\";i:167;s:5:\"sajda\";b:0;}i:11;a:9:{s:6:\"number\";i:3545;s:4:\"text\";s:140:\"Et quand les hypocrites et ceux qui ont la maladie [le doute] au cœur disaient: «Allah et Son messager ne nous ont promis que tromperie».\";s:13:\"numberInSurah\";i:12;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:419;s:4:\"ruku\";i:362;s:11:\"hizbQuarter\";i:167;s:5:\"sajda\";b:0;}i:12;a:9:{s:6:\"number\";i:3546;s:4:\"text\";s:283:\"De même, un groupe d\'entre eux dit: «Gens de Yathrib! Ne demeurez pas ici. Retournez [chez vous]». Un groupe d\'entre eux demande au Prophète la permission de partir en disant: «Nos demeures sont sans protection», alors qu\'elles ne l\'étaient pas: ils ne voulaient que s\'enfuir.\";s:13:\"numberInSurah\";i:13;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:419;s:4:\"ruku\";i:362;s:11:\"hizbQuarter\";i:167;s:5:\"sajda\";b:0;}i:13;a:9:{s:6:\"number\";i:3547;s:4:\"text\";s:186:\"Et si une percée avait été faite sur eux par les flancs de la ville et qu\'ensuite on leur avait demandé de renier leur foi, ils auraient accepté certes, et n\'auraient guère tardé,\";s:13:\"numberInSurah\";i:14;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:419;s:4:\"ruku\";i:362;s:11:\"hizbQuarter\";i:167;s:5:\"sajda\";b:0;}i:14;a:9:{s:6:\"number\";i:3548;s:4:\"text\";s:164:\"tandis qu\'auparavant ils avaient pris l\'engagement envers Allah qu\'ils ne tourneraient pas le dos. Et il sera demandé compte de tout engagement vis-à-vis d\'Allah.\";s:13:\"numberInSurah\";i:15;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:419;s:4:\"ruku\";i:362;s:11:\"hizbQuarter\";i:167;s:5:\"sajda\";b:0;}i:15;a:9:{s:6:\"number\";i:3549;s:4:\"text\";s:182:\"Dis: «Jamais la fuite ne vous sera utile si c\'est la mort (sans combat) ou le meurtre (dans le combat) que vous fuyez; dans ce cas, vous ne jouirez (de la vie) que peu (de temps)».\";s:13:\"numberInSurah\";i:16;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:420;s:4:\"ruku\";i:362;s:11:\"hizbQuarter\";i:167;s:5:\"sajda\";b:0;}i:16;a:9:{s:6:\"number\";i:3550;s:4:\"text\";s:203:\"Dis: «Quel est celui qui peut vous protéger d\'Allah, s\'Il vous veut du mal ou s\'Il veut vous accorder une miséricorde?» Et ils ne trouveront pour eux-mêmes en dehors d\'Allah, ni allié ni secoureur.\";s:13:\"numberInSurah\";i:17;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:420;s:4:\"ruku\";i:362;s:11:\"hizbQuarter\";i:167;s:5:\"sajda\";b:0;}i:17;a:9:{s:6:\"number\";i:3551;s:4:\"text\";s:188:\"Certes, Allah connaît ceux d\'entre vous qui suscitent des obstacles, ainsi que ceux qui disent à leurs frères: «Venez à nous», tandis qu\'ils ne déploient que peu d\'ardeur au combat,\";s:13:\"numberInSurah\";i:18;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:420;s:4:\"ruku\";i:362;s:11:\"hizbQuarter\";i:168;s:5:\"sajda\";b:0;}i:18;a:9:{s:6:\"number\";i:3552;s:4:\"text\";s:381:\"avares à votre égard. Puis, quand leur vient la peur, tu les vois te regarder avec des yeux révulsés, comme ceux de quelqu\'un qui s\'est évanoui par peur de la mort. Une fois la peur passée, ils vous lacèrent avec des langues affilées, alors qu\'ils sont chiches à faire le bien. Ceux-là n\'ont jamais cru. Allah donc, rend vaines leurs actions. Et cela est facile à Allah.\";s:13:\"numberInSurah\";i:19;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:420;s:4:\"ruku\";i:362;s:11:\"hizbQuarter\";i:168;s:5:\"sajda\";b:0;}i:19;a:9:{s:6:\"number\";i:3553;s:4:\"text\";s:268:\"Ils pensent que les coalisés ne sont pas partis. Or si les coalisés revenaient, [ces gens-là] souhaiteraient être des nomades parmi les Bédouins et [se contenteraient] de demander de vos nouvelles. S\'ils étaient parmi vous, ils n\'auraient combattu que très peu.\";s:13:\"numberInSurah\";i:20;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:420;s:4:\"ruku\";i:362;s:11:\"hizbQuarter\";i:168;s:5:\"sajda\";b:0;}i:20;a:9:{s:6:\"number\";i:3554;s:4:\"text\";s:160:\"En effet, vous avez dans le Messager d\'Allah un excellent modèle [à suivre], pour quiconque espère en Allah et au Jour dernier et invoque Allah fréquemment.\";s:13:\"numberInSurah\";i:21;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:420;s:4:\"ruku\";i:363;s:11:\"hizbQuarter\";i:168;s:5:\"sajda\";b:0;}i:21;a:9:{s:6:\"number\";i:3555;s:4:\"text\";s:219:\"Et quand les croyants virent les coalisés, ils dirent: «Voilà ce qu\'Allah et Son messager nous avaient promis; et Allah et Son messager disaient la vérité». Et cela ne fit que croître leur foi et leur soumission.\";s:13:\"numberInSurah\";i:22;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:420;s:4:\"ruku\";i:363;s:11:\"hizbQuarter\";i:168;s:5:\"sajda\";b:0;}i:22;a:9:{s:6:\"number\";i:3556;s:4:\"text\";s:225:\"Il est, parmi les croyants, des hommes qui ont été sincères dans leur engagement envers Allah. Certains d\'entre eux ont atteint leur fin, et d\'autres attendent encore; et ils n\'ont varié aucunement (dans leur engagement);\";s:13:\"numberInSurah\";i:23;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:421;s:4:\"ruku\";i:363;s:11:\"hizbQuarter\";i:168;s:5:\"sajda\";b:0;}i:23;a:9:{s:6:\"number\";i:3557;s:4:\"text\";s:174:\"afin qu\'Allah récompense les véridiques pour leur sincérité, et châtie, s\'Il veut, les hypocrites, ou accepte leur repentir. Car Allah est Pardonneur et Miséricordieux.\";s:13:\"numberInSurah\";i:24;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:421;s:4:\"ruku\";i:363;s:11:\"hizbQuarter\";i:168;s:5:\"sajda\";b:0;}i:24;a:9:{s:6:\"number\";i:3558;s:4:\"text\";s:163:\"Et Allah a renvoyé, avec leur rage, les infidèles sans qu\'ils n\'aient obtenu aucun bien, et Allah a épargné aux croyants le combat. Allah est Fort et Puissant.\";s:13:\"numberInSurah\";i:25;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:421;s:4:\"ruku\";i:363;s:11:\"hizbQuarter\";i:168;s:5:\"sajda\";b:0;}i:25;a:9:{s:6:\"number\";i:3559;s:4:\"text\";s:223:\"Et Il a fait descendre de leurs forteresses ceux des gens du Livre qui les avaient soutenus [les coalisés], et Il a jeté l\'effroi dans leurs cœurs; un groupe d\'entre eux vous tuiez, et un groupe vous faisiez prisonniers.\";s:13:\"numberInSurah\";i:26;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:421;s:4:\"ruku\";i:363;s:11:\"hizbQuarter\";i:168;s:5:\"sajda\";b:0;}i:26;a:9:{s:6:\"number\";i:3560;s:4:\"text\";s:143:\"Et Il vous a fait hériter leur terre, leurs demeures, leurs biens, et aussi une terre que vous n\'aviez point foulée. Et Allah est Omnipotent.\";s:13:\"numberInSurah\";i:27;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:421;s:4:\"ruku\";i:363;s:11:\"hizbQuarter\";i:168;s:5:\"sajda\";b:0;}i:27;a:9:{s:6:\"number\";i:3561;s:4:\"text\";s:200:\"O Prophète! Dis à tes épouses: «Si c\'est la vie présente que vous désirez et sa parure, alors venez! Je vous donnerai [les moyens] d\'en jouir et vous libérerai [par un divorce] sans préjudice.\";s:13:\"numberInSurah\";i:28;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:421;s:4:\"ruku\";i:364;s:11:\"hizbQuarter\";i:168;s:5:\"sajda\";b:0;}i:28;a:9:{s:6:\"number\";i:3562;s:4:\"text\";s:160:\"Mais si c\'est Allah que vous voulez et Son messager ainsi que la Demeure dernière, Allah a préparé pour les bienfaisantes parmi vous une énorme récompense.\";s:13:\"numberInSurah\";i:29;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:421;s:4:\"ruku\";i:364;s:11:\"hizbQuarter\";i:168;s:5:\"sajda\";b:0;}i:29;a:9:{s:6:\"number\";i:3563;s:4:\"text\";s:156:\"O femmes du Prophète! Celle d\'entre vous qui commettra une turpitude prouvée, le châtiment lui sera doublé par deux fois! Et ceci est facile pour Allah.\";s:13:\"numberInSurah\";i:30;s:3:\"juz\";i:21;s:6:\"manzil\";i:5;s:4:\"page\";i:421;s:4:\"ruku\";i:364;s:11:\"hizbQuarter\";i:168;s:5:\"sajda\";b:0;}i:30;a:9:{s:6:\"number\";i:3564;s:4:\"text\";s:209:\"Et celle d\'entre vous qui est entièrement soumise à Allah et à Son messager et qui fait le bien, Nous lui accorderons deux fois sa récompense, et Nous avons préparé pour elle une généreuse attribution.\";s:13:\"numberInSurah\";i:31;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:422;s:4:\"ruku\";i:364;s:11:\"hizbQuarter\";i:169;s:5:\"sajda\";b:0;}i:31;a:9:{s:6:\"number\";i:3565;s:4:\"text\";s:250:\"O femmes du Prophète! Vous n\'êtes comparables à aucune autre femme. Si vous êtes pieuses, ne soyez pas trop complaisantes dans votre langage, afin que celui dont le cœur est malade [l\'hypocrite] ne vous convoite pas. Et tenez un langage décent.\";s:13:\"numberInSurah\";i:32;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:422;s:4:\"ruku\";i:364;s:11:\"hizbQuarter\";i:169;s:5:\"sajda\";b:0;}i:32;a:9:{s:6:\"number\";i:3566;s:4:\"text\";s:315:\"Restez dans vos foyers; et ne vous exhibez pas à la manière des femmes d\'avant l\'Islam (Jâhiliyah). Accomplissez la Salât, acquittez la Zakât et obéissez à Allah et à Son messager. Allah ne veut que vous débarrasser de toute souillure, ô gens de la maison [du prophète], et veut vous purifier pleinement.\";s:13:\"numberInSurah\";i:33;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:422;s:4:\"ruku\";i:364;s:11:\"hizbQuarter\";i:169;s:5:\"sajda\";b:0;}i:33;a:9:{s:6:\"number\";i:3567;s:4:\"text\";s:148:\"Et gardez dans vos mémoires ce qui, dans vos foyers, est récité des versets d\'Allah et de la sagesse. Allah est Doux et Parfaitement Connaisseur.\";s:13:\"numberInSurah\";i:34;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:422;s:4:\"ruku\";i:364;s:11:\"hizbQuarter\";i:169;s:5:\"sajda\";b:0;}i:34;a:9:{s:6:\"number\";i:3568;s:4:\"text\";s:361:\"Les Musulmans et Musulmanes, croyants et croyantes, obéissants et obéissantes, loyaux et loyales, endurants et endurantes, craignants et craignantes, donneurs et donneuses d\'aumône, jeûnants et jeûnantes, gardiens de leur chasteté et gardiennes, invocateurs souvent d\'Allah et invocatrices: Allah a préparé pour eux un pardon et une énorme récompense.\";s:13:\"numberInSurah\";i:35;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:422;s:4:\"ruku\";i:365;s:11:\"hizbQuarter\";i:169;s:5:\"sajda\";b:0;}i:35;a:9:{s:6:\"number\";i:3569;s:4:\"text\";s:262:\"Il n\'appartient pas à un croyant ou à une croyante, une fois qu\'Allah et Son messager ont décidé d\'une chose d\'avoir encore le choix dans leur façon d\'agir. Et quiconque désobéit à Allah et à Son messager, s\'est égaré certes, d\'un égarement évident.\";s:13:\"numberInSurah\";i:36;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:423;s:4:\"ruku\";i:365;s:11:\"hizbQuarter\";i:169;s:5:\"sajda\";b:0;}i:36;a:9:{s:6:\"number\";i:3570;s:4:\"text\";s:556:\"Quand tu disais à celui qu\'Allah avait comblé de bienfait, tout comme toi-même l\'avais comblé: «Garde pour toi ton épouse et crains Allah», et tu cachais en ton âme ce qu\'Allah allait rendre public. Tu craignais les gens, et c\'est Allah qui est plus digne de ta crainte. Puis quand Zayd eut cessé toute relation avec elle, Nous te la fîmes épouser, afin qu\'il n\'y ait aucun empêchement pour les croyants d\'épouser les femmes de leurs fils adoptifs, quand ceux-ci cessent toute relation avec elles. Le commandement d\'Allah doit être exécuté.\";s:13:\"numberInSurah\";i:37;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:423;s:4:\"ruku\";i:365;s:11:\"hizbQuarter\";i:169;s:5:\"sajda\";b:0;}i:37;a:9:{s:6:\"number\";i:3571;s:4:\"text\";s:188:\"Nul grief à faire au Prophète en ce qu\'Allah lui a imposé, conformément aux lois établies pour ceux qui vécurent antérieurement. Le commandement d\'Allah est un décret inéluctable.\";s:13:\"numberInSurah\";i:38;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:423;s:4:\"ruku\";i:365;s:11:\"hizbQuarter\";i:169;s:5:\"sajda\";b:0;}i:38;a:9:{s:6:\"number\";i:3572;s:4:\"text\";s:144:\"Ceux qui communiquaient les messages d\'Allah, Le craignaient et ne redoutaient nul autre qu\'Allah. Et Allah suffit pour tenir le compte de tout.\";s:13:\"numberInSurah\";i:39;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:423;s:4:\"ruku\";i:365;s:11:\"hizbQuarter\";i:169;s:5:\"sajda\";b:0;}i:39;a:9:{s:6:\"number\";i:3573;s:4:\"text\";s:134:\"Muhammad n\'a jamais été le père de l\'un de vos hommes, mais le messager d\'Allah et le dernier des prophètes. Allah est Omniscient.\";s:13:\"numberInSurah\";i:40;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:423;s:4:\"ruku\";i:365;s:11:\"hizbQuarter\";i:169;s:5:\"sajda\";b:0;}i:40;a:9:{s:6:\"number\";i:3574;s:4:\"text\";s:56:\"O vous qui croyez! Evoquez Allah d\'une façon abondante,\";s:13:\"numberInSurah\";i:41;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:423;s:4:\"ruku\";i:366;s:11:\"hizbQuarter\";i:169;s:5:\"sajda\";b:0;}i:41;a:9:{s:6:\"number\";i:3575;s:4:\"text\";s:51:\"et glorifiez-Le à la pointe et au déclin du jour.\";s:13:\"numberInSurah\";i:42;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:423;s:4:\"ruku\";i:366;s:11:\"hizbQuarter\";i:169;s:5:\"sajda\";b:0;}i:42;a:9:{s:6:\"number\";i:3576;s:4:\"text\";s:160:\"C\'est lui qui prie sur vous, - ainsi que Ses Anges -, afin qu\'Il vous fasse sortir des ténèbres à la lumière; et Il est Miséricordieux envers les croyants.\";s:13:\"numberInSurah\";i:43;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:423;s:4:\"ruku\";i:366;s:11:\"hizbQuarter\";i:169;s:5:\"sajda\";b:0;}i:43;a:9:{s:6:\"number\";i:3577;s:4:\"text\";s:125:\"Leur salutation au jour où ils Le rencontreront sera: «Salâm» [paix], et Il leur a préparé une généreuse récompense.\";s:13:\"numberInSurah\";i:44;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:424;s:4:\"ruku\";i:366;s:11:\"hizbQuarter\";i:169;s:5:\"sajda\";b:0;}i:44;a:9:{s:6:\"number\";i:3578;s:4:\"text\";s:82:\"O Prophète! Nous t\'avons envoyé [pour être] témoin, annonciateur, avertisseur,\";s:13:\"numberInSurah\";i:45;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:424;s:4:\"ruku\";i:366;s:11:\"hizbQuarter\";i:169;s:5:\"sajda\";b:0;}i:45;a:9:{s:6:\"number\";i:3579;s:4:\"text\";s:80:\"appelant (les gens) à Allah, par Sa permission; et comme une lampe éclairante.\";s:13:\"numberInSurah\";i:46;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:424;s:4:\"ruku\";i:366;s:11:\"hizbQuarter\";i:169;s:5:\"sajda\";b:0;}i:46;a:9:{s:6:\"number\";i:3580;s:4:\"text\";s:81:\"Et fais aux croyants la bonne annonce qu\'ils recevront d\'Allah une grande grâce.\";s:13:\"numberInSurah\";i:47;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:424;s:4:\"ruku\";i:366;s:11:\"hizbQuarter\";i:169;s:5:\"sajda\";b:0;}i:47;a:9:{s:6:\"number\";i:3581;s:4:\"text\";s:159:\"Et n\'obéis pas aux infidèles et aux hypocrites, ne prête pas attention à leur méchanceté et place ta confiance en Allah et Allah suffit comme protecteur.\";s:13:\"numberInSurah\";i:48;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:424;s:4:\"ruku\";i:366;s:11:\"hizbQuarter\";i:169;s:5:\"sajda\";b:0;}i:48;a:9:{s:6:\"number\";i:3582;s:4:\"text\";s:265:\"O vous qui croyez! Quand vous vous mariez avec des croyantes et qu\'ensuite vous divorcez d\'avec elles avant de les avoir touchées, vous ne pouvez leur imposer un délai d\'attente. Donnez-leur jouissance [d\'un bien] et libérez-les [par un divorce] sans préjudice.\";s:13:\"numberInSurah\";i:49;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:424;s:4:\"ruku\";i:366;s:11:\"hizbQuarter\";i:169;s:5:\"sajda\";b:0;}i:49;a:9:{s:6:\"number\";i:3583;s:4:\"text\";s:789:\"O Prophète! Nous t\'avons rendu licites tes épouses à qui tu as donné leur mahr (dot), ce que tu as possédé légalement parmi les captives [ou esclaves] qu\'Allah t\'a destinées, les filles de ton oncle paternel, les filles de tes tantes paternelles, les filles de ton oncle maternel, et les filles de tes tantes maternelles, - celles qui avaient émigré en ta compagnie -, ainsi que toute femme croyante si elle fait don de sa personne au Prophète, pourvu que le Prophète consente à se marier avec elle: c\'est là un privilège pour toi, à l\'exclusion des autres croyants. Nous savons certes, ce que Nous leur avons imposé au sujet de leurs épouses et des esclaves qu\'ils possèdent, afin qu\'il n\'y eût donc point de blâme contre toi. Allah est Pardonneur et Miséricordieux.\";s:13:\"numberInSurah\";i:50;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:424;s:4:\"ruku\";i:366;s:11:\"hizbQuarter\";i:169;s:5:\"sajda\";b:0;}i:50;a:9:{s:6:\"number\";i:3584;s:4:\"text\";s:420:\"Tu fais attendre qui tu veux d\'entre elles, et tu héberges chez toi qui tu veux. Puis il ne t\'est fait aucun grief si tu invites chez toi l\'une de celles que tu avais écartées. Voilà ce qui est le plus propre à les réjouir, à leur éviter tout chagrin et à leur faire accepter de bon cœur ce que tu leur as donné à toutes. Allah sait, cependant, ce qui est en vos cœurs. Et Allah est Omniscient et Indulgent.\";s:13:\"numberInSurah\";i:51;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:425;s:4:\"ruku\";i:366;s:11:\"hizbQuarter\";i:170;s:5:\"sajda\";b:0;}i:51;a:9:{s:6:\"number\";i:3585;s:4:\"text\";s:201:\"Il ne t\'est plus permis désormais de prendre [d\'autres] femmes, ni de changer d\'épouses, même si leur beauté te plaît; - à l\'exception des esclaves que tu possèdes. Et Allah observe toute chose.\";s:13:\"numberInSurah\";i:52;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:425;s:4:\"ruku\";i:366;s:11:\"hizbQuarter\";i:170;s:5:\"sajda\";b:0;}i:52;a:9:{s:6:\"number\";i:3586;s:4:\"text\";s:726:\"O vous qui croyez! N\'entrez pas dans les demeures du Prophète, à moins qu\'invitation ne vous soit faite à un repas, sans être là à attendre sa cuisson. Mais lorsqu\'on vous appelle, alors, entrez. Puis, quand vous aurez mangé, dispersez-vous, sans chercher à vous rendre familiers pour causer. Cela faisait de la peine au Prophète, mais il se gênait de vous (congédier), alors qu\'Allah ne se gêne pas de la vérité. Et si vous leur demandez (à ses femmes) quelque objet, demandez-le leur derrière un rideau: c\'est plus pur pour vos cœurs et leurs cœurs; vous ne devez pas faire de la peine au Messager d\'Allah, ni jamais vous marier avec ses épouses après lui; ce serait, auprès d\'Allah, un énorme péché.\";s:13:\"numberInSurah\";i:53;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:425;s:4:\"ruku\";i:367;s:11:\"hizbQuarter\";i:170;s:5:\"sajda\";b:0;}i:53;a:9:{s:6:\"number\";i:3587;s:4:\"text\";s:82:\"Que vous divulguiez une chose ou que vous la cachiez,... Allah demeure Omniscient.\";s:13:\"numberInSurah\";i:54;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:425;s:4:\"ruku\";i:367;s:11:\"hizbQuarter\";i:170;s:5:\"sajda\";b:0;}i:54;a:9:{s:6:\"number\";i:3588;s:4:\"text\";s:243:\"Nul grief sur elles au sujet de leurs pères, leurs fils, leurs frères, les fils de leurs frères, les fils de leurs sœurs, leurs femmes [de suite] et les esclaves qu\'elles possèdent. Et craignez Allah. Car Allah est témoin de toute chose.\";s:13:\"numberInSurah\";i:55;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:426;s:4:\"ruku\";i:367;s:11:\"hizbQuarter\";i:170;s:5:\"sajda\";b:0;}i:55;a:9:{s:6:\"number\";i:3589;s:4:\"text\";s:119:\"Certes, Allah et Ses Anges prient sur le Prophète; ô vous qui croyez priez sur lui et adressez [lui] vos salutations.\";s:13:\"numberInSurah\";i:56;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:426;s:4:\"ruku\";i:367;s:11:\"hizbQuarter\";i:170;s:5:\"sajda\";b:0;}i:56;a:9:{s:6:\"number\";i:3590;s:4:\"text\";s:132:\"Ceux qui offensent Allah et Son messager, Allah les maudit ici-bas, comme dans l\'au-delà et leur prépare un châtiment avilissant.\";s:13:\"numberInSurah\";i:57;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:426;s:4:\"ruku\";i:367;s:11:\"hizbQuarter\";i:170;s:5:\"sajda\";b:0;}i:57;a:9:{s:6:\"number\";i:3591;s:4:\"text\";s:134:\"Et ceux qui offensent les croyants et les croyantes sans qu\'ils l\'aient mérité, se chargent d\'une calomnie et d\'un péché évident.\";s:13:\"numberInSurah\";i:58;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:426;s:4:\"ruku\";i:367;s:11:\"hizbQuarter\";i:170;s:5:\"sajda\";b:0;}i:58;a:9:{s:6:\"number\";i:3592;s:4:\"text\";s:229:\"O Prophète! Dis à tes épouses, à tes filles, et aux femmes des croyants, de ramener sur elles leurs grands voiles: elles en seront plus vite reconnues et éviteront d\'être offensées. Allah est Pardonneur et Miséricordieux.\";s:13:\"numberInSurah\";i:59;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:426;s:4:\"ruku\";i:368;s:11:\"hizbQuarter\";i:170;s:5:\"sajda\";b:0;}i:59;a:9:{s:6:\"number\";i:3593;s:4:\"text\";s:220:\"Certes, si les hypocrites, ceux qui ont la maladie au cœur, et les alarmistes [semeurs de troubles] à Médine ne cessent pas, Nous t\'inciterons contre eux, et alors, ils n\'y resteront que peu de temps en ton voisinage.\";s:13:\"numberInSurah\";i:60;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:426;s:4:\"ruku\";i:368;s:11:\"hizbQuarter\";i:171;s:5:\"sajda\";b:0;}i:60;a:9:{s:6:\"number\";i:3594;s:4:\"text\";s:84:\"Ce sont des maudits. Où qu\'on les trouve, ils seront pris et tués impitoyablement:\";s:13:\"numberInSurah\";i:61;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:426;s:4:\"ruku\";i:368;s:11:\"hizbQuarter\";i:171;s:5:\"sajda\";b:0;}i:61;a:9:{s:6:\"number\";i:3595;s:4:\"text\";s:133:\"Telle était la loi établie par Allah envers ceux qui ont vécu auparavant et tu ne trouveras pas de changement dans la loi d\'Allah.\";s:13:\"numberInSurah\";i:62;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:426;s:4:\"ruku\";i:368;s:11:\"hizbQuarter\";i:171;s:5:\"sajda\";b:0;}i:62;a:9:{s:6:\"number\";i:3596;s:4:\"text\";s:143:\"Les gens t\'interrogent au sujet de l\'Heure. Dis: «Sa connaissance est exclusive à Allah». Qu\'en sais-tu? Il se peut que l\'Heure soit proche.\";s:13:\"numberInSurah\";i:63;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:427;s:4:\"ruku\";i:368;s:11:\"hizbQuarter\";i:171;s:5:\"sajda\";b:0;}i:63;a:9:{s:6:\"number\";i:3597;s:4:\"text\";s:64:\"Allah a maudit les infidèles et leur a préparé une fournaise,\";s:13:\"numberInSurah\";i:64;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:427;s:4:\"ruku\";i:368;s:11:\"hizbQuarter\";i:171;s:5:\"sajda\";b:0;}i:64;a:9:{s:6:\"number\";i:3598;s:4:\"text\";s:76:\"pour qu\'ils y demeurent éternellement, sans trouver ni allié ni secoureur.\";s:13:\"numberInSurah\";i:65;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:427;s:4:\"ruku\";i:368;s:11:\"hizbQuarter\";i:171;s:5:\"sajda\";b:0;}i:65;a:9:{s:6:\"number\";i:3599;s:4:\"text\";s:164:\"Le jour où leurs visages seront tournés et retournés dans le Feu, ils diront: «Hélas pour nous! Si seulement nous avions obéi à Allah et obéi au Messager!»\";s:13:\"numberInSurah\";i:66;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:427;s:4:\"ruku\";i:368;s:11:\"hizbQuarter\";i:171;s:5:\"sajda\";b:0;}i:66;a:9:{s:6:\"number\";i:3600;s:4:\"text\";s:123:\"Et ils dirent: «Seigneur, nous avons obéi à nos chefs et à nos grands. C\'est donc eux qui nous ont égarés du Sentier.\";s:13:\"numberInSurah\";i:67;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:427;s:4:\"ruku\";i:368;s:11:\"hizbQuarter\";i:171;s:5:\"sajda\";b:0;}i:67;a:9:{s:6:\"number\";i:3601;s:4:\"text\";s:97:\"O notre Seigneur, inflige-leur deux fois le châtiment et maudis les d\'une grande malédiction».\";s:13:\"numberInSurah\";i:68;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:427;s:4:\"ruku\";i:368;s:11:\"hizbQuarter\";i:171;s:5:\"sajda\";b:0;}i:68;a:9:{s:6:\"number\";i:3602;s:4:\"text\";s:159:\"O vous qui croyez! Ne soyez pas comme ceux qui ont offensé Moïse. Allah l\'a déclaré innocent de leurs accusations, car il était honorable auprès d\'Allah.\";s:13:\"numberInSurah\";i:69;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:427;s:4:\"ruku\";i:369;s:11:\"hizbQuarter\";i:171;s:5:\"sajda\";b:0;}i:69;a:9:{s:6:\"number\";i:3603;s:4:\"text\";s:58:\"O vous qui croyez! Craignez Allah et parlez avec droiture,\";s:13:\"numberInSurah\";i:70;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:427;s:4:\"ruku\";i:369;s:11:\"hizbQuarter\";i:171;s:5:\"sajda\";b:0;}i:70;a:9:{s:6:\"number\";i:3604;s:4:\"text\";s:145:\"afin qu\'Il améliore vos actions et vous pardonne vos péchés. Quiconque obéit à Allah et à Son messager obtient certes une grande réussite.\";s:13:\"numberInSurah\";i:71;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:427;s:4:\"ruku\";i:369;s:11:\"hizbQuarter\";i:171;s:5:\"sajda\";b:0;}i:71;a:9:{s:6:\"number\";i:3605;s:4:\"text\";s:288:\"Nous avions proposé aux cieux, à la terre et aux montagnes la responsabilité (de porter les charges de faire le bien et d\'éviter le mal). Ils ont refusé de la porter et en ont eu peur, alors que l\'homme s\'en est chargé; car il est très injuste [envers lui-même] et très ignorant.\";s:13:\"numberInSurah\";i:72;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:427;s:4:\"ruku\";i:369;s:11:\"hizbQuarter\";i:171;s:5:\"sajda\";b:0;}i:72;a:9:{s:6:\"number\";i:3606;s:4:\"text\";s:217:\"[Il en est ainsi] afin qu\'Allah châtie les hypocrites, hommes et femmes, et les associateurs et les associatrices et Allah accueille le repentir des croyants et des croyantes. Allah est Pardonneur et Miséricordieux.\";s:13:\"numberInSurah\";i:73;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:427;s:4:\"ruku\";i:369;s:11:\"hizbQuarter\";i:171;s:5:\"sajda\";b:0;}}s:7:\"edition\";a:7:{s:10:\"identifier\";s:13:\"fr.hamidullah\";s:8:\"language\";s:2:\"fr\";s:4:\"name\";s:10:\"Hamidullah\";s:11:\"englishName\";s:19:\"Muhammad Hamidullah\";s:6:\"format\";s:4:\"text\";s:4:\"type\";s:11:\"translation\";s:9:\"direction\";s:3:\"ltr\";}}', 1794581367),
('quranapp-cache-surah_34_ar.uthmani', 'a:8:{s:6:\"number\";i:34;s:4:\"name\";s:27:\"سُورَةُ سَبَإٍ\";s:11:\"englishName\";s:4:\"Saba\";s:22:\"englishNameTranslation\";s:5:\"Sheba\";s:14:\"revelationType\";s:6:\"Meccan\";s:13:\"numberOfAyahs\";i:54;s:5:\"ayahs\";a:54:{i:0;a:9:{s:6:\"number\";i:3607;s:4:\"text\";s:345:\"بِسۡمِ ٱللَّهِ ٱلرَّحۡمَـٰنِ ٱلرَّحِیمِ ٱلۡحَمۡدُ لِلَّهِ ٱلَّذِی لَهُۥ مَا فِی ٱلسَّمَـٰوَ ٰ⁠تِ وَمَا فِی ٱلۡأَرۡضِ وَلَهُ ٱلۡحَمۡدُ فِی ٱلۡـَٔاخِرَةِۚ وَهُوَ ٱلۡحَكِیمُ ٱلۡخَبِیرُ\n\";s:13:\"numberInSurah\";i:1;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:428;s:4:\"ruku\";i:370;s:11:\"hizbQuarter\";i:171;s:5:\"sajda\";b:0;}i:1;a:9:{s:6:\"number\";i:3608;s:4:\"text\";s:262:\"یَعۡلَمُ مَا یَلِجُ فِی ٱلۡأَرۡضِ وَمَا یَخۡرُجُ مِنۡهَا وَمَا یَنزِلُ مِنَ ٱلسَّمَاۤءِ وَمَا یَعۡرُجُ فِیهَاۚ وَهُوَ ٱلرَّحِیمُ ٱلۡغَفُورُ\n\";s:13:\"numberInSurah\";i:2;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:428;s:4:\"ruku\";i:370;s:11:\"hizbQuarter\";i:171;s:5:\"sajda\";b:0;}i:2;a:9:{s:6:\"number\";i:3609;s:4:\"text\";s:511:\"وَقَالَ ٱلَّذِینَ كَفَرُوا۟ لَا تَأۡتِینَا ٱلسَّاعَةُۖ قُلۡ بَلَىٰ وَرَبِّی لَتَأۡتِیَنَّكُمۡ عَـٰلِمِ ٱلۡغَیۡبِۖ لَا یَعۡزُبُ عَنۡهُ مِثۡقَالُ ذَرَّةࣲ فِی ٱلسَّمَـٰوَ ٰ⁠تِ وَلَا فِی ٱلۡأَرۡضِ وَلَاۤ أَصۡغَرُ مِن ذَ ٰ⁠لِكَ وَلَاۤ أَكۡبَرُ إِلَّا فِی كِتَـٰبࣲ مُّبِینࣲ\n\";s:13:\"numberInSurah\";i:3;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:428;s:4:\"ruku\";i:370;s:11:\"hizbQuarter\";i:171;s:5:\"sajda\";b:0;}i:3;a:9:{s:6:\"number\";i:3610;s:4:\"text\";s:217:\"لِّیَجۡزِیَ ٱلَّذِینَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِۚ أُو۟لَـٰۤىِٕكَ لَهُم مَّغۡفِرَةࣱ وَرِزۡقࣱ كَرِیمࣱ\n\";s:13:\"numberInSurah\";i:4;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:428;s:4:\"ruku\";i:370;s:11:\"hizbQuarter\";i:171;s:5:\"sajda\";b:0;}i:4;a:9:{s:6:\"number\";i:3611;s:4:\"text\";s:195:\"وَٱلَّذِینَ سَعَوۡ فِیۤ ءَایَـٰتِنَا مُعَـٰجِزِینَ أُو۟لَـٰۤىِٕكَ لَهُمۡ عَذَابࣱ مِّن رِّجۡزٍ أَلِیمࣱ\n\";s:13:\"numberInSurah\";i:5;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:428;s:4:\"ruku\";i:370;s:11:\"hizbQuarter\";i:171;s:5:\"sajda\";b:0;}i:5;a:9:{s:6:\"number\";i:3612;s:4:\"text\";s:266:\"وَیَرَى ٱلَّذِینَ أُوتُوا۟ ٱلۡعِلۡمَ ٱلَّذِیۤ أُنزِلَ إِلَیۡكَ مِن رَّبِّكَ هُوَ ٱلۡحَقَّ وَیَهۡدِیۤ إِلَىٰ صِرَ ٰ⁠طِ ٱلۡعَزِیزِ ٱلۡحَمِیدِ\n\";s:13:\"numberInSurah\";i:6;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:428;s:4:\"ruku\";i:370;s:11:\"hizbQuarter\";i:171;s:5:\"sajda\";b:0;}i:6;a:9:{s:6:\"number\";i:3613;s:4:\"text\";s:262:\"وَقَالَ ٱلَّذِینَ كَفَرُوا۟ هَلۡ نَدُلُّكُمۡ عَلَىٰ رَجُلࣲ یُنَبِّئُكُمۡ إِذَا مُزِّقۡتُمۡ كُلَّ مُمَزَّقٍ إِنَّكُمۡ لَفِی خَلۡقࣲ جَدِیدٍ\n\";s:13:\"numberInSurah\";i:7;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:428;s:4:\"ruku\";i:370;s:11:\"hizbQuarter\";i:171;s:5:\"sajda\";b:0;}i:7;a:9:{s:6:\"number\";i:3614;s:4:\"text\";s:264:\"أَفۡتَرَىٰ عَلَى ٱللَّهِ كَذِبًا أَم بِهِۦ جِنَّةُۢۗ بَلِ ٱلَّذِینَ لَا یُؤۡمِنُونَ بِٱلۡـَٔاخِرَةِ فِی ٱلۡعَذَابِ وَٱلضَّلَـٰلِ ٱلۡبَعِیدِ\n\";s:13:\"numberInSurah\";i:8;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:429;s:4:\"ruku\";i:370;s:11:\"hizbQuarter\";i:171;s:5:\"sajda\";b:0;}i:8;a:9:{s:6:\"number\";i:3615;s:4:\"text\";s:459:\"أَفَلَمۡ یَرَوۡا۟ إِلَىٰ مَا بَیۡنَ أَیۡدِیهِمۡ وَمَا خَلۡفَهُم مِّنَ ٱلسَّمَاۤءِ وَٱلۡأَرۡضِۚ إِن نَّشَأۡ نَخۡسِفۡ بِهِمُ ٱلۡأَرۡضَ أَوۡ نُسۡقِطۡ عَلَیۡهِمۡ كِسَفࣰا مِّنَ ٱلسَّمَاۤءِۚ إِنَّ فِی ذَ ٰ⁠لِكَ لَـَٔایَةࣰ لِّكُلِّ عَبۡدࣲ مُّنِیبࣲ\n\";s:13:\"numberInSurah\";i:9;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:429;s:4:\"ruku\";i:370;s:11:\"hizbQuarter\";i:171;s:5:\"sajda\";b:0;}i:9;a:9:{s:6:\"number\";i:3616;s:4:\"text\";s:220:\"۞ وَلَقَدۡ ءَاتَیۡنَا دَاوُۥدَ مِنَّا فَضۡلࣰاۖ یَـٰجِبَالُ أَوِّبِی مَعَهُۥ وَٱلطَّیۡرَۖ وَأَلَنَّا لَهُ ٱلۡحَدِیدَ\n\";s:13:\"numberInSurah\";i:10;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:429;s:4:\"ruku\";i:371;s:11:\"hizbQuarter\";i:172;s:5:\"sajda\";b:0;}i:10;a:9:{s:6:\"number\";i:3617;s:4:\"text\";s:206:\"أَنِ ٱعۡمَلۡ سَـٰبِغَـٰتࣲ وَقَدِّرۡ فِی ٱلسَّرۡدِۖ وَٱعۡمَلُوا۟ صَـٰلِحًاۖ إِنِّی بِمَا تَعۡمَلُونَ بَصِیرࣱ\n\";s:13:\"numberInSurah\";i:11;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:429;s:4:\"ruku\";i:371;s:11:\"hizbQuarter\";i:172;s:5:\"sajda\";b:0;}i:11;a:9:{s:6:\"number\";i:3618;s:4:\"text\";s:445:\"وَلِسُلَیۡمَـٰنَ ٱلرِّیحَ غُدُوُّهَا شَهۡرࣱ وَرَوَاحُهَا شَهۡرࣱۖ وَأَسَلۡنَا لَهُۥ عَیۡنَ ٱلۡقِطۡرِۖ وَمِنَ ٱلۡجِنِّ مَن یَعۡمَلُ بَیۡنَ یَدَیۡهِ بِإِذۡنِ رَبِّهِۦۖ وَمَن یَزِغۡ مِنۡهُمۡ عَنۡ أَمۡرِنَا نُذِقۡهُ مِنۡ عَذَابِ ٱلسَّعِیرِ\n\";s:13:\"numberInSurah\";i:12;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:429;s:4:\"ruku\";i:371;s:11:\"hizbQuarter\";i:172;s:5:\"sajda\";b:0;}i:12;a:9:{s:6:\"number\";i:3619;s:4:\"text\";s:349:\"یَعۡمَلُونَ لَهُۥ مَا یَشَاۤءُ مِن مَّحَـٰرِیبَ وَتَمَـٰثِیلَ وَجِفَانࣲ كَٱلۡجَوَابِ وَقُدُورࣲ رَّاسِیَـٰتٍۚ ٱعۡمَلُوۤا۟ ءَالَ دَاوُۥدَ شُكۡرࣰاۚ وَقَلِیلࣱ مِّنۡ عِبَادِیَ ٱلشَّكُورُ\n\";s:13:\"numberInSurah\";i:13;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:429;s:4:\"ruku\";i:371;s:11:\"hizbQuarter\";i:172;s:5:\"sajda\";b:0;}i:13;a:9:{s:6:\"number\";i:3620;s:4:\"text\";s:447:\"فَلَمَّا قَضَیۡنَا عَلَیۡهِ ٱلۡمَوۡتَ مَا دَلَّهُمۡ عَلَىٰ مَوۡتِهِۦۤ إِلَّا دَاۤبَّةُ ٱلۡأَرۡضِ تَأۡكُلُ مِنسَأَتَهُۥۖ فَلَمَّا خَرَّ تَبَیَّنَتِ ٱلۡجِنُّ أَن لَّوۡ كَانُوا۟ یَعۡلَمُونَ ٱلۡغَیۡبَ مَا لَبِثُوا۟ فِی ٱلۡعَذَابِ ٱلۡمُهِینِ\n\";s:13:\"numberInSurah\";i:14;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:429;s:4:\"ruku\";i:371;s:11:\"hizbQuarter\";i:172;s:5:\"sajda\";b:0;}i:14;a:9:{s:6:\"number\";i:3621;s:4:\"text\";s:321:\"لَقَدۡ كَانَ لِسَبَإࣲ فِی مَسۡكَنِهِمۡ ءَایَةࣱۖ جَنَّتَانِ عَن یَمِینࣲ وَشِمَالࣲۖ كُلُوا۟ مِن رِّزۡقِ رَبِّكُمۡ وَٱشۡكُرُوا۟ لَهُۥۚ بَلۡدَةࣱ طَیِّبَةࣱ وَرَبٌّ غَفُورࣱ\n\";s:13:\"numberInSurah\";i:15;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:430;s:4:\"ruku\";i:371;s:11:\"hizbQuarter\";i:172;s:5:\"sajda\";b:0;}i:15;a:9:{s:6:\"number\";i:3622;s:4:\"text\";s:315:\"فَأَعۡرَضُوا۟ فَأَرۡسَلۡنَا عَلَیۡهِمۡ سَیۡلَ ٱلۡعَرِمِ وَبَدَّلۡنَـٰهُم بِجَنَّتَیۡهِمۡ جَنَّتَیۡنِ ذَوَاتَیۡ أُكُلٍ خَمۡطࣲ وَأَثۡلࣲ وَشَیۡءࣲ مِّن سِدۡرࣲ قَلِیلࣲ\n\";s:13:\"numberInSurah\";i:16;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:430;s:4:\"ruku\";i:371;s:11:\"hizbQuarter\";i:172;s:5:\"sajda\";b:0;}i:16;a:9:{s:6:\"number\";i:3623;s:4:\"text\";s:148:\"ذَ ٰ⁠لِكَ جَزَیۡنَـٰهُم بِمَا كَفَرُوا۟ۖ وَهَلۡ نُجَـٰزِیۤ إِلَّا ٱلۡكَفُورَ\n\";s:13:\"numberInSurah\";i:17;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:430;s:4:\"ruku\";i:371;s:11:\"hizbQuarter\";i:172;s:5:\"sajda\";b:0;}i:17;a:9:{s:6:\"number\";i:3624;s:4:\"text\";s:315:\"وَجَعَلۡنَا بَیۡنَهُمۡ وَبَیۡنَ ٱلۡقُرَى ٱلَّتِی بَـٰرَكۡنَا فِیهَا قُرࣰى ظَـٰهِرَةࣰ وَقَدَّرۡنَا فِیهَا ٱلسَّیۡرَۖ سِیرُوا۟ فِیهَا لَیَالِیَ وَأَیَّامًا ءَامِنِینَ\n\";s:13:\"numberInSurah\";i:18;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:430;s:4:\"ruku\";i:371;s:11:\"hizbQuarter\";i:172;s:5:\"sajda\";b:0;}i:18;a:9:{s:6:\"number\";i:3625;s:4:\"text\";s:378:\"فَقَالُوا۟ رَبَّنَا بَـٰعِدۡ بَیۡنَ أَسۡفَارِنَا وَظَلَمُوۤا۟ أَنفُسَهُمۡ فَجَعَلۡنَـٰهُمۡ أَحَادِیثَ وَمَزَّقۡنَـٰهُمۡ كُلَّ مُمَزَّقٍۚ إِنَّ فِی ذَ ٰ⁠لِكَ لَـَٔایَـٰتࣲ لِّكُلِّ صَبَّارࣲ شَكُورࣲ\n\";s:13:\"numberInSurah\";i:19;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:430;s:4:\"ruku\";i:371;s:11:\"hizbQuarter\";i:172;s:5:\"sajda\";b:0;}i:19;a:9:{s:6:\"number\";i:3626;s:4:\"text\";s:187:\"وَلَقَدۡ صَدَّقَ عَلَیۡهِمۡ إِبۡلِیسُ ظَنَّهُۥ فَٱتَّبَعُوهُ إِلَّا فَرِیقࣰا مِّنَ ٱلۡمُؤۡمِنِینَ\n\";s:13:\"numberInSurah\";i:20;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:430;s:4:\"ruku\";i:371;s:11:\"hizbQuarter\";i:172;s:5:\"sajda\";b:0;}i:20;a:9:{s:6:\"number\";i:3627;s:4:\"text\";s:303:\"وَمَا كَانَ لَهُۥ عَلَیۡهِم مِّن سُلۡطَـٰنٍ إِلَّا لِنَعۡلَمَ مَن یُؤۡمِنُ بِٱلۡـَٔاخِرَةِ مِمَّنۡ هُوَ مِنۡهَا فِی شَكࣲّۗ وَرَبُّكَ عَلَىٰ كُلِّ شَیۡءٍ حَفِیظࣱ\n\";s:13:\"numberInSurah\";i:21;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:430;s:4:\"ruku\";i:371;s:11:\"hizbQuarter\";i:172;s:5:\"sajda\";b:0;}i:21;a:9:{s:6:\"number\";i:3628;s:4:\"text\";s:367:\"قُلِ ٱدۡعُوا۟ ٱلَّذِینَ زَعَمۡتُم مِّن دُونِ ٱللَّهِ لَا یَمۡلِكُونَ مِثۡقَالَ ذَرَّةࣲ فِی ٱلسَّمَـٰوَ ٰ⁠تِ وَلَا فِی ٱلۡأَرۡضِ وَمَا لَهُمۡ فِیهِمَا مِن شِرۡكࣲ وَمَا لَهُۥ مِنۡهُم مِّن ظَهِیرࣲ\n\";s:13:\"numberInSurah\";i:22;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:430;s:4:\"ruku\";i:372;s:11:\"hizbQuarter\";i:172;s:5:\"sajda\";b:0;}i:22;a:9:{s:6:\"number\";i:3629;s:4:\"text\";s:350:\"وَلَا تَنفَعُ ٱلشَّفَـٰعَةُ عِندَهُۥۤ إِلَّا لِمَنۡ أَذِنَ لَهُۥۚ حَتَّىٰۤ إِذَا فُزِّعَ عَن قُلُوبِهِمۡ قَالُوا۟ مَاذَا قَالَ رَبُّكُمۡۖ قَالُوا۟ ٱلۡحَقَّۖ وَهُوَ ٱلۡعَلِیُّ ٱلۡكَبِیرُ\n\";s:13:\"numberInSurah\";i:23;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:431;s:4:\"ruku\";i:372;s:11:\"hizbQuarter\";i:172;s:5:\"sajda\";b:0;}i:23;a:9:{s:6:\"number\";i:3630;s:4:\"text\";s:268:\"۞ قُلۡ مَن یَرۡزُقُكُم مِّنَ ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِۖ قُلِ ٱللَّهُۖ وَإِنَّاۤ أَوۡ إِیَّاكُمۡ لَعَلَىٰ هُدًى أَوۡ فِی ضَلَـٰلࣲ مُّبِینࣲ\n\";s:13:\"numberInSurah\";i:24;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:431;s:4:\"ruku\";i:372;s:11:\"hizbQuarter\";i:173;s:5:\"sajda\";b:0;}i:24;a:9:{s:6:\"number\";i:3631;s:4:\"text\";s:145:\"قُل لَّا تُسۡـَٔلُونَ عَمَّاۤ أَجۡرَمۡنَا وَلَا نُسۡـَٔلُ عَمَّا تَعۡمَلُونَ\n\";s:13:\"numberInSurah\";i:25;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:431;s:4:\"ruku\";i:372;s:11:\"hizbQuarter\";i:173;s:5:\"sajda\";b:0;}i:25;a:9:{s:6:\"number\";i:3632;s:4:\"text\";s:187:\"قُلۡ یَجۡمَعُ بَیۡنَنَا رَبُّنَا ثُمَّ یَفۡتَحُ بَیۡنَنَا بِٱلۡحَقِّ وَهُوَ ٱلۡفَتَّاحُ ٱلۡعَلِیمُ\n\";s:13:\"numberInSurah\";i:26;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:431;s:4:\"ruku\";i:372;s:11:\"hizbQuarter\";i:173;s:5:\"sajda\";b:0;}i:26;a:9:{s:6:\"number\";i:3633;s:4:\"text\";s:194:\"قُلۡ أَرُونِیَ ٱلَّذِینَ أَلۡحَقۡتُم بِهِۦ شُرَكَاۤءَۖ كَلَّاۚ بَلۡ هُوَ ٱللَّهُ ٱلۡعَزِیزُ ٱلۡحَكِیمُ\n\";s:13:\"numberInSurah\";i:27;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:431;s:4:\"ruku\";i:372;s:11:\"hizbQuarter\";i:173;s:5:\"sajda\";b:0;}i:27;a:9:{s:6:\"number\";i:3634;s:4:\"text\";s:223:\"وَمَاۤ أَرۡسَلۡنَـٰكَ إِلَّا كَاۤفَّةࣰ لِّلنَّاسِ بَشِیرࣰا وَنَذِیرࣰا وَلَـٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا یَعۡلَمُونَ\n\";s:13:\"numberInSurah\";i:28;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:431;s:4:\"ruku\";i:372;s:11:\"hizbQuarter\";i:173;s:5:\"sajda\";b:0;}i:28;a:9:{s:6:\"number\";i:3635;s:4:\"text\";s:117:\"وَیَقُولُونَ مَتَىٰ هَـٰذَا ٱلۡوَعۡدُ إِن كُنتُمۡ صَـٰدِقِینَ\n\";s:13:\"numberInSurah\";i:29;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:431;s:4:\"ruku\";i:372;s:11:\"hizbQuarter\";i:173;s:5:\"sajda\";b:0;}i:29;a:9:{s:6:\"number\";i:3636;s:4:\"text\";s:166:\"قُل لَّكُم مِّیعَادُ یَوۡمࣲ لَّا تَسۡتَـٔۡخِرُونَ عَنۡهُ سَاعَةࣰ وَلَا تَسۡتَقۡدِمُونَ\n\";s:13:\"numberInSurah\";i:30;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:431;s:4:\"ruku\";i:372;s:11:\"hizbQuarter\";i:173;s:5:\"sajda\";b:0;}i:30;a:9:{s:6:\"number\";i:3637;s:4:\"text\";s:574:\"وَقَالَ ٱلَّذِینَ كَفَرُوا۟ لَن نُّؤۡمِنَ بِهَـٰذَا ٱلۡقُرۡءَانِ وَلَا بِٱلَّذِی بَیۡنَ یَدَیۡهِۗ وَلَوۡ تَرَىٰۤ إِذِ ٱلظَّـٰلِمُونَ مَوۡقُوفُونَ عِندَ رَبِّهِمۡ یَرۡجِعُ بَعۡضُهُمۡ إِلَىٰ بَعۡضٍ ٱلۡقَوۡلَ یَقُولُ ٱلَّذِینَ ٱسۡتُضۡعِفُوا۟ لِلَّذِینَ ٱسۡتَكۡبَرُوا۟ لَوۡلَاۤ أَنتُمۡ لَكُنَّا مُؤۡمِنِینَ\n\";s:13:\"numberInSurah\";i:31;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:431;s:4:\"ruku\";i:373;s:11:\"hizbQuarter\";i:173;s:5:\"sajda\";b:0;}i:31;a:9:{s:6:\"number\";i:3638;s:4:\"text\";s:275:\"قَالَ ٱلَّذِینَ ٱسۡتَكۡبَرُوا۟ لِلَّذِینَ ٱسۡتُضۡعِفُوۤا۟ أَنَحۡنُ صَدَدۡنَـٰكُمۡ عَنِ ٱلۡهُدَىٰ بَعۡدَ إِذۡ جَاۤءَكُمۖ بَلۡ كُنتُم مُّجۡرِمِینَ\n\";s:13:\"numberInSurah\";i:32;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:432;s:4:\"ruku\";i:373;s:11:\"hizbQuarter\";i:173;s:5:\"sajda\";b:0;}i:32;a:9:{s:6:\"number\";i:3639;s:4:\"text\";s:629:\"وَقَالَ ٱلَّذِینَ ٱسۡتُضۡعِفُوا۟ لِلَّذِینَ ٱسۡتَكۡبَرُوا۟ بَلۡ مَكۡرُ ٱلَّیۡلِ وَٱلنَّهَارِ إِذۡ تَأۡمُرُونَنَاۤ أَن نَّكۡفُرَ بِٱللَّهِ وَنَجۡعَلَ لَهُۥۤ أَندَادࣰاۚ وَأَسَرُّوا۟ ٱلنَّدَامَةَ لَمَّا رَأَوُا۟ ٱلۡعَذَابَۚ وَجَعَلۡنَا ٱلۡأَغۡلَـٰلَ فِیۤ أَعۡنَاقِ ٱلَّذِینَ كَفَرُوا۟ۖ هَلۡ یُجۡزَوۡنَ إِلَّا مَا كَانُوا۟ یَعۡمَلُونَ\n\";s:13:\"numberInSurah\";i:33;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:432;s:4:\"ruku\";i:373;s:11:\"hizbQuarter\";i:173;s:5:\"sajda\";b:0;}i:33;a:9:{s:6:\"number\";i:3640;s:4:\"text\";s:221:\"وَمَاۤ أَرۡسَلۡنَا فِی قَرۡیَةࣲ مِّن نَّذِیرٍ إِلَّا قَالَ مُتۡرَفُوهَاۤ إِنَّا بِمَاۤ أُرۡسِلۡتُم بِهِۦ كَـٰفِرُونَ\n\";s:13:\"numberInSurah\";i:34;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:432;s:4:\"ruku\";i:373;s:11:\"hizbQuarter\";i:173;s:5:\"sajda\";b:0;}i:34;a:9:{s:6:\"number\";i:3641;s:4:\"text\";s:160:\"وَقَالُوا۟ نَحۡنُ أَكۡثَرُ أَمۡوَ ٰ⁠لࣰا وَأَوۡلَـٰدࣰا وَمَا نَحۡنُ بِمُعَذَّبِینَ\n\";s:13:\"numberInSurah\";i:35;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:432;s:4:\"ruku\";i:373;s:11:\"hizbQuarter\";i:173;s:5:\"sajda\";b:0;}i:35;a:9:{s:6:\"number\";i:3642;s:4:\"text\";s:205:\"قُلۡ إِنَّ رَبِّی یَبۡسُطُ ٱلرِّزۡقَ لِمَن یَشَاۤءُ وَیَقۡدِرُ وَلَـٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا یَعۡلَمُونَ\n\";s:13:\"numberInSurah\";i:36;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:432;s:4:\"ruku\";i:373;s:11:\"hizbQuarter\";i:173;s:5:\"sajda\";b:0;}i:36;a:9:{s:6:\"number\";i:3643;s:4:\"text\";s:422:\"وَمَاۤ أَمۡوَ ٰ⁠لُكُمۡ وَلَاۤ أَوۡلَـٰدُكُم بِٱلَّتِی تُقَرِّبُكُمۡ عِندَنَا زُلۡفَىٰۤ إِلَّا مَنۡ ءَامَنَ وَعَمِلَ صَـٰلِحࣰا فَأُو۟لَـٰۤىِٕكَ لَهُمۡ جَزَاۤءُ ٱلضِّعۡفِ بِمَا عَمِلُوا۟ وَهُمۡ فِی ٱلۡغُرُفَـٰتِ ءَامِنُونَ\n\";s:13:\"numberInSurah\";i:37;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:432;s:4:\"ruku\";i:374;s:11:\"hizbQuarter\";i:173;s:5:\"sajda\";b:0;}i:37;a:9:{s:6:\"number\";i:3644;s:4:\"text\";s:185:\"وَٱلَّذِینَ یَسۡعَوۡنَ فِیۤ ءَایَـٰتِنَا مُعَـٰجِزِینَ أُو۟لَـٰۤىِٕكَ فِی ٱلۡعَذَابِ مُحۡضَرُونَ\n\";s:13:\"numberInSurah\";i:38;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:432;s:4:\"ruku\";i:374;s:11:\"hizbQuarter\";i:173;s:5:\"sajda\";b:0;}i:38;a:9:{s:6:\"number\";i:3645;s:4:\"text\";s:315:\"قُلۡ إِنَّ رَبِّی یَبۡسُطُ ٱلرِّزۡقَ لِمَن یَشَاۤءُ مِنۡ عِبَادِهِۦ وَیَقۡدِرُ لَهُۥۚ وَمَاۤ أَنفَقۡتُم مِّن شَیۡءࣲ فَهُوَ یُخۡلِفُهُۥۖ وَهُوَ خَیۡرُ ٱلرَّ ٰ⁠زِقِینَ\n\";s:13:\"numberInSurah\";i:39;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:432;s:4:\"ruku\";i:374;s:11:\"hizbQuarter\";i:173;s:5:\"sajda\";b:0;}i:39;a:9:{s:6:\"number\";i:3646;s:4:\"text\";s:215:\"وَیَوۡمَ یَحۡشُرُهُمۡ جَمِیعࣰا ثُمَّ یَقُولُ لِلۡمَلَـٰۤىِٕكَةِ أَهَـٰۤؤُلَاۤءِ إِیَّاكُمۡ كَانُوا۟ یَعۡبُدُونَ\n\";s:13:\"numberInSurah\";i:40;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:433;s:4:\"ruku\";i:374;s:11:\"hizbQuarter\";i:173;s:5:\"sajda\";b:0;}i:40;a:9:{s:6:\"number\";i:3647;s:4:\"text\";s:227:\"قَالُوا۟ سُبۡحَـٰنَكَ أَنتَ وَلِیُّنَا مِن دُونِهِمۖ بَلۡ كَانُوا۟ یَعۡبُدُونَ ٱلۡجِنَّۖ أَكۡثَرُهُم بِهِم مُّؤۡمِنُونَ\n\";s:13:\"numberInSurah\";i:41;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:433;s:4:\"ruku\";i:374;s:11:\"hizbQuarter\";i:173;s:5:\"sajda\";b:0;}i:41;a:9:{s:6:\"number\";i:3648;s:4:\"text\";s:301:\"فَٱلۡیَوۡمَ لَا یَمۡلِكُ بَعۡضُكُمۡ لِبَعۡضࣲ نَّفۡعࣰا وَلَا ضَرࣰّا وَنَقُولُ لِلَّذِینَ ظَلَمُوا۟ ذُوقُوا۟ عَذَابَ ٱلنَّارِ ٱلَّتِی كُنتُم بِهَا تُكَذِّبُونَ\n\";s:13:\"numberInSurah\";i:42;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:433;s:4:\"ruku\";i:374;s:11:\"hizbQuarter\";i:173;s:5:\"sajda\";b:0;}i:42;a:9:{s:6:\"number\";i:3649;s:4:\"text\";s:558:\"وَإِذَا تُتۡلَىٰ عَلَیۡهِمۡ ءَایَـٰتُنَا بَیِّنَـٰتࣲ قَالُوا۟ مَا هَـٰذَاۤ إِلَّا رَجُلࣱ یُرِیدُ أَن یَصُدَّكُمۡ عَمَّا كَانَ یَعۡبُدُ ءَابَاۤؤُكُمۡ وَقَالُوا۟ مَا هَـٰذَاۤ إِلَّاۤ إِفۡكࣱ مُّفۡتَرࣰىۚ وَقَالَ ٱلَّذِینَ كَفَرُوا۟ لِلۡحَقِّ لَمَّا جَاۤءَهُمۡ إِنۡ هَـٰذَاۤ إِلَّا سِحۡرࣱ مُّبِینࣱ\n\";s:13:\"numberInSurah\";i:43;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:433;s:4:\"ruku\";i:374;s:11:\"hizbQuarter\";i:173;s:5:\"sajda\";b:0;}i:43;a:9:{s:6:\"number\";i:3650;s:4:\"text\";s:197:\"وَمَاۤ ءَاتَیۡنَـٰهُم مِّن كُتُبࣲ یَدۡرُسُونَهَاۖ وَمَاۤ أَرۡسَلۡنَاۤ إِلَیۡهِمۡ قَبۡلَكَ مِن نَّذِیرࣲ\n\";s:13:\"numberInSurah\";i:44;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:433;s:4:\"ruku\";i:374;s:11:\"hizbQuarter\";i:173;s:5:\"sajda\";b:0;}i:44;a:9:{s:6:\"number\";i:3651;s:4:\"text\";s:240:\"وَكَذَّبَ ٱلَّذِینَ مِن قَبۡلِهِمۡ وَمَا بَلَغُوا۟ مِعۡشَارَ مَاۤ ءَاتَیۡنَـٰهُمۡ فَكَذَّبُوا۟ رُسُلِیۖ فَكَیۡفَ كَانَ نَكِیرِ\n\";s:13:\"numberInSurah\";i:45;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:433;s:4:\"ruku\";i:374;s:11:\"hizbQuarter\";i:173;s:5:\"sajda\";b:0;}i:45;a:9:{s:6:\"number\";i:3652;s:4:\"text\";s:388:\"۞ قُلۡ إِنَّمَاۤ أَعِظُكُم بِوَ ٰ⁠حِدَةٍۖ أَن تَقُومُوا۟ لِلَّهِ مَثۡنَىٰ وَفُرَ ٰ⁠دَىٰ ثُمَّ تَتَفَكَّرُوا۟ۚ مَا بِصَاحِبِكُم مِّن جِنَّةٍۚ إِنۡ هُوَ إِلَّا نَذِیرࣱ لَّكُم بَیۡنَ یَدَیۡ عَذَابࣲ شَدِیدࣲ\n\";s:13:\"numberInSurah\";i:46;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:433;s:4:\"ruku\";i:375;s:11:\"hizbQuarter\";i:174;s:5:\"sajda\";b:0;}i:46;a:9:{s:6:\"number\";i:3653;s:4:\"text\";s:226:\"قُلۡ مَا سَأَلۡتُكُم مِّنۡ أَجۡرࣲ فَهُوَ لَكُمۡۖ إِنۡ أَجۡرِیَ إِلَّا عَلَى ٱللَّهِۖ وَهُوَ عَلَىٰ كُلِّ شَیۡءࣲ شَهِیدࣱ\n\";s:13:\"numberInSurah\";i:47;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:433;s:4:\"ruku\";i:375;s:11:\"hizbQuarter\";i:174;s:5:\"sajda\";b:0;}i:47;a:9:{s:6:\"number\";i:3654;s:4:\"text\";s:111:\"قُلۡ إِنَّ رَبِّی یَقۡذِفُ بِٱلۡحَقِّ عَلَّـٰمُ ٱلۡغُیُوبِ\n\";s:13:\"numberInSurah\";i:48;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:433;s:4:\"ruku\";i:375;s:11:\"hizbQuarter\";i:174;s:5:\"sajda\";b:0;}i:48;a:9:{s:6:\"number\";i:3655;s:4:\"text\";s:116:\"قُلۡ جَاۤءَ ٱلۡحَقُّ وَمَا یُبۡدِئُ ٱلۡبَـٰطِلُ وَمَا یُعِیدُ\n\";s:13:\"numberInSurah\";i:49;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:434;s:4:\"ruku\";i:375;s:11:\"hizbQuarter\";i:174;s:5:\"sajda\";b:0;}i:49;a:9:{s:6:\"number\";i:3656;s:4:\"text\";s:248:\"قُلۡ إِن ضَلَلۡتُ فَإِنَّمَاۤ أَضِلُّ عَلَىٰ نَفۡسِیۖ وَإِنِ ٱهۡتَدَیۡتُ فَبِمَا یُوحِیۤ إِلَیَّ رَبِّیۤۚ إِنَّهُۥ سَمِیعࣱ قَرِیبࣱ\n\";s:13:\"numberInSurah\";i:50;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:434;s:4:\"ruku\";i:375;s:11:\"hizbQuarter\";i:174;s:5:\"sajda\";b:0;}i:50;a:9:{s:6:\"number\";i:3657;s:4:\"text\";s:144:\"وَلَوۡ تَرَىٰۤ إِذۡ فَزِعُوا۟ فَلَا فَوۡتَ وَأُخِذُوا۟ مِن مَّكَانࣲ قَرِیبࣲ\n\";s:13:\"numberInSurah\";i:51;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:434;s:4:\"ruku\";i:375;s:11:\"hizbQuarter\";i:174;s:5:\"sajda\";b:0;}i:51;a:9:{s:6:\"number\";i:3658;s:4:\"text\";s:152:\"وَقَالُوۤا۟ ءَامَنَّا بِهِۦ وَأَنَّىٰ لَهُمُ ٱلتَّنَاوُشُ مِن مَّكَانِۭ بَعِیدࣲ\n\";s:13:\"numberInSurah\";i:52;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:434;s:4:\"ruku\";i:375;s:11:\"hizbQuarter\";i:174;s:5:\"sajda\";b:0;}i:52;a:9:{s:6:\"number\";i:3659;s:4:\"text\";s:157:\"وَقَدۡ كَفَرُوا۟ بِهِۦ مِن قَبۡلُۖ وَیَقۡذِفُونَ بِٱلۡغَیۡبِ مِن مَّكَانِۭ بَعِیدࣲ\n\";s:13:\"numberInSurah\";i:53;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:434;s:4:\"ruku\";i:375;s:11:\"hizbQuarter\";i:174;s:5:\"sajda\";b:0;}i:53;a:9:{s:6:\"number\";i:3660;s:4:\"text\";s:234:\"وَحِیلَ بَیۡنَهُمۡ وَبَیۡنَ مَا یَشۡتَهُونَ كَمَا فُعِلَ بِأَشۡیَاعِهِم مِّن قَبۡلُۚ إِنَّهُمۡ كَانُوا۟ فِی شَكࣲّ مُّرِیبِۭ\n\";s:13:\"numberInSurah\";i:54;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:434;s:4:\"ruku\";i:375;s:11:\"hizbQuarter\";i:174;s:5:\"sajda\";b:0;}}s:7:\"edition\";a:7:{s:10:\"identifier\";s:27:\"quran-uthmani-quran-academy\";s:8:\"language\";s:2:\"ar\";s:4:\"name\";s:67:\"القرآن الكريم برسم العثماني (quran-academy)\";s:11:\"englishName\";s:78:\"Modified Quran Uthmani Text from the Quran Academy to work with the Kitab font\";s:6:\"format\";s:4:\"text\";s:4:\"type\";s:5:\"quran\";s:9:\"direction\";s:3:\"rtl\";}}', 1794581367);
INSERT INTO `cache` (`key`, `value`, `expiration`) VALUES
('quranapp-cache-surah_34_fr.hamidullah', 'a:8:{s:6:\"number\";i:34;s:4:\"name\";s:27:\"سُورَةُ سَبَإٍ\";s:11:\"englishName\";s:4:\"Saba\";s:22:\"englishNameTranslation\";s:5:\"Sheba\";s:14:\"revelationType\";s:6:\"Meccan\";s:13:\"numberOfAyahs\";i:54;s:5:\"ayahs\";a:54:{i:0;a:9:{s:6:\"number\";i:3607;s:4:\"text\";s:184:\"Louange à Allah à qui appartient tout ce qui est dans les cieux et tout ce qui est sur la terre. Et louange à Lui dans l\'au-delà. Et c\'est Lui le Sage, le Parfaitement Connaisseur.\";s:13:\"numberInSurah\";i:1;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:428;s:4:\"ruku\";i:370;s:11:\"hizbQuarter\";i:171;s:5:\"sajda\";b:0;}i:1;a:9:{s:6:\"number\";i:3608;s:4:\"text\";s:144:\"Il sait ce qui pénètre en terre et ce qui en sort, ce qui descend du ciel et ce qui y remonte. Et c\'est Lui le Miséricordieux, le Pardonneur.\";s:13:\"numberInSurah\";i:2;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:428;s:4:\"ruku\";i:370;s:11:\"hizbQuarter\";i:171;s:5:\"sajda\";b:0;}i:2;a:9:{s:6:\"number\";i:3609;s:4:\"text\";s:358:\"Ceux qui ne croient pas disent: «L\'Heure ne nous viendra pas». Dis: «Par mon Seigneur! Très certainement, elle vous viendra. [Mon Seigneur] le Connaisseur de l\'Inconnaissable. Rien ne Lui échappe fût-il du poids d\'un atome dans les cieux, comme sur la terre. Et rien n\'existe de plus petit ni de plus grand, qui ne soit inscrit dans un Livre explicite,\";s:13:\"numberInSurah\";i:3;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:428;s:4:\"ruku\";i:370;s:11:\"hizbQuarter\";i:171;s:5:\"sajda\";b:0;}i:3;a:9:{s:6:\"number\";i:3610;s:4:\"text\";s:132:\"afin qu\'Il récompense ceux qui croient et accomplissent les bonnes œuvres. Pour ceux-ci, il y aura un pardon et un don généreux.\";s:13:\"numberInSurah\";i:4;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:428;s:4:\"ruku\";i:370;s:11:\"hizbQuarter\";i:171;s:5:\"sajda\";b:0;}i:4;a:9:{s:6:\"number\";i:3611;s:4:\"text\";s:108:\"Et ceux qui s\'efforcent de rendre vains Nos versets, ceux-là auront le châtiment d\'un supplice douloureux.\";s:13:\"numberInSurah\";i:5;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:428;s:4:\"ruku\";i:370;s:11:\"hizbQuarter\";i:171;s:5:\"sajda\";b:0;}i:5;a:9:{s:6:\"number\";i:3612;s:4:\"text\";s:180:\"Et ceux à qui le savoir a été donné voient que ce qu\'on t\'a fait descendre de la part de ton Seigneur est la vérité qui guide au chemin du Tout Puissant, du Digne de Louange.\";s:13:\"numberInSurah\";i:6;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:428;s:4:\"ruku\";i:370;s:11:\"hizbQuarter\";i:171;s:5:\"sajda\";b:0;}i:6;a:9:{s:6:\"number\";i:3613;s:4:\"text\";s:211:\"Et ceux qui ne croient pas dirent: «Voulez-vous que l\'on vous montre un homme qui vous prédise que lorsque vous serez complètement désintégrés, vous reparaîtrez, sans nul doute, en une nouvelle création?\";s:13:\"numberInSurah\";i:7;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:428;s:4:\"ruku\";i:370;s:11:\"hizbQuarter\";i:171;s:5:\"sajda\";b:0;}i:7;a:9:{s:6:\"number\";i:3614;s:4:\"text\";s:165:\"Invente-t-il un mensonge contre Allah? ou bien est-il fou?» [Non], mais ceux qui ne croient pas en l\'au-delà sont voués au châtiment et à l\'égarement lointain.\";s:13:\"numberInSurah\";i:8;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:429;s:4:\"ruku\";i:370;s:11:\"hizbQuarter\";i:171;s:5:\"sajda\";b:0;}i:8;a:9:{s:6:\"number\";i:3615;s:4:\"text\";s:249:\"Ne voient-ils donc pas ce qu\'il y a comme ciel et comme terre devant et derrière eux? Si Nous voulions, Nous ferions que la terre les engloutisse, ou que des morceaux du ciel tombent sur eux. Il y a en cela une preuve pour tout serviteur repentant.\";s:13:\"numberInSurah\";i:9;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:429;s:4:\"ruku\";i:370;s:11:\"hizbQuarter\";i:171;s:5:\"sajda\";b:0;}i:9;a:9:{s:6:\"number\";i:3616;s:4:\"text\";s:167:\"Nous avons certes accordé une grâce à David de Notre part. O montagnes et oiseaux, répétez avec lui (les louanges d\'Allah). Et pour lui, Nous avons amolli le fer,\";s:13:\"numberInSurah\";i:10;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:429;s:4:\"ruku\";i:371;s:11:\"hizbQuarter\";i:172;s:5:\"sajda\";b:0;}i:10;a:9:{s:6:\"number\";i:3617;s:4:\"text\";s:153:\"(en lui disant): «Fabrique des cottes de mailles complètes et mesure bien les mailles». Et faites le bien. Je suis Clairvoyant sur ce que vous faites.\";s:13:\"numberInSurah\";i:11;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:429;s:4:\"ruku\";i:371;s:11:\"hizbQuarter\";i:172;s:5:\"sajda\";b:0;}i:11;a:9:{s:6:\"number\";i:3618;s:4:\"text\";s:412:\"Et à Salomon (Nous avons assujetti) le vent, dont le parcours du matin équivaut à un mois (de marche) et le parcours du soir, un mois aussi. Et pour lui Nous avons fait couler la source de cuivre. Et parmi les djinns il y en a qui travaillaient sous ses ordres, par permission de son Seigneur. Quiconque d\'entre eux, cependant, déviait de Notre ordre, Nous lui faisions goûter au châtiment de la fournaise.\";s:13:\"numberInSurah\";i:12;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:429;s:4:\"ruku\";i:371;s:11:\"hizbQuarter\";i:172;s:5:\"sajda\";b:0;}i:12;a:9:{s:6:\"number\";i:3619;s:4:\"text\";s:235:\"Ils exécutaient pour lui ce qu\'il voulait: sanctuaires, statues, plateaux comme des bassins, et marmites bien ancrées. - «O famille de David, œuvrez par gratitude», alors qu\'il y a eu peu de Mes serviteurs qui sont reconnaissants.\";s:13:\"numberInSurah\";i:13;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:429;s:4:\"ruku\";i:371;s:11:\"hizbQuarter\";i:172;s:5:\"sajda\";b:0;}i:13;a:9:{s:6:\"number\";i:3620;s:4:\"text\";s:305:\"Puis, quand Nous décidâmes sa mort, il n\'y eut pour les avertir de sa mort que la «bête de terre», qui rongea sa canne. Puis lorsqu\'il s\'écroula, il apparut de toute évidence aux djinns que s\'ils savaient vraiment l\'inconnu, ils ne seraient pas restés dans le supplice humiliant [de la servitude].\";s:13:\"numberInSurah\";i:14;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:429;s:4:\"ruku\";i:371;s:11:\"hizbQuarter\";i:172;s:5:\"sajda\";b:0;}i:14;a:9:{s:6:\"number\";i:3621;s:4:\"text\";s:255:\"Il y avait assurément, pour la tribu de Saba\' un Signe dans leurs habitat: deux jardins, l\'un à droite et l\'autre à gauche. «Mangez de ce que votre Seigneur vous a attribué, et soyez-Lui reconnaissants: une bonne contrée et un Seigneur Pardonneur».\";s:13:\"numberInSurah\";i:15;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:430;s:4:\"ruku\";i:371;s:11:\"hizbQuarter\";i:172;s:5:\"sajda\";b:0;}i:15;a:9:{s:6:\"number\";i:3622;s:4:\"text\";s:187:\"Mais ils se détournèrent. Nous déchaînâmes contre eux l\'inondation du Barrage, et leur changeâmes leurs deux jardins en deux jardins aux fruits amers, tamaris et quelques jujubiers.\";s:13:\"numberInSurah\";i:16;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:430;s:4:\"ruku\";i:371;s:11:\"hizbQuarter\";i:172;s:5:\"sajda\";b:0;}i:16;a:9:{s:6:\"number\";i:3623;s:4:\"text\";s:105:\"Ainsi les rétribuâmes Nous pour leur mécréance. Saurions-Nous sanctionner un autre que le mécréant?\";s:13:\"numberInSurah\";i:17;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:430;s:4:\"ruku\";i:371;s:11:\"hizbQuarter\";i:172;s:5:\"sajda\";b:0;}i:17;a:9:{s:6:\"number\";i:3624;s:4:\"text\";s:231:\"Et Nous avions placé entre eux et les cités que Nous avions bénies, d\'autres cités proéminentes, et Nous avions évalué les étapes de voyage entre elles. «Voyagez entre elles pendant des nuits et des jours, en sécurité».\";s:13:\"numberInSurah\";i:18;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:430;s:4:\"ruku\";i:371;s:11:\"hizbQuarter\";i:172;s:5:\"sajda\";b:0;}i:18;a:9:{s:6:\"number\";i:3625;s:4:\"text\";s:280:\"Puis, ils dirent: «Seigneur, allonge les distances entre nos étapes», et ils se firent du tort à eux-mêmes. Nous fîmes d\'eux, donc, des sujets de légendes et les désintégrâmes totalement. Il y a en cela des avertissements pour tous grand endurant et grand reconnaissant.\";s:13:\"numberInSurah\";i:19;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:430;s:4:\"ruku\";i:371;s:11:\"hizbQuarter\";i:172;s:5:\"sajda\";b:0;}i:19;a:9:{s:6:\"number\";i:3626;s:4:\"text\";s:133:\"Et Satan a très certainement rendu véridique sa conjecture à leur égard. Ils l\'ont suivi donc, sauf un groupe parmi les croyants.\";s:13:\"numberInSurah\";i:20;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:430;s:4:\"ruku\";i:371;s:11:\"hizbQuarter\";i:172;s:5:\"sajda\";b:0;}i:20;a:9:{s:6:\"number\";i:3627;s:4:\"text\";s:201:\"Et pourtant il n\'avait sur eux aucun pouvoir si ce n\'est que Nous voulions distinguer celui qui croyait en l\'au-delà et celui qui doutait. Ton Seigneur, cependant, assure la sauvegarde de toute chose.\";s:13:\"numberInSurah\";i:21;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:430;s:4:\"ruku\";i:371;s:11:\"hizbQuarter\";i:172;s:5:\"sajda\";b:0;}i:21;a:9:{s:6:\"number\";i:3628;s:4:\"text\";s:265:\"Dis: «Invoquez ceux qu\'en dehors d\'Allah vous prétendez [être des divinités]. Ils ne possèdent même pas le poids d\'un atome, ni dans les cieux ni sur la terre. Ils n\'ont jamais été associés à leur création et Il n\'a personne parmi eux pour Le soutenir».\";s:13:\"numberInSurah\";i:22;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:430;s:4:\"ruku\";i:372;s:11:\"hizbQuarter\";i:172;s:5:\"sajda\";b:0;}i:22;a:9:{s:6:\"number\";i:3629;s:4:\"text\";s:251:\"L\'intercession auprès de Lui ne profite qu\'à celui en faveur duquel Il la permet. Quand ensuite la frayeur se sera éloignée de leurs cœurs, ils diront: «Qu\'a dit votre Seigneur?» Ils répondront: «La Vérité; C\'est Lui le Sublime, le Grand».\";s:13:\"numberInSurah\";i:23;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:431;s:4:\"ruku\";i:372;s:11:\"hizbQuarter\";i:172;s:5:\"sajda\";b:0;}i:23;a:9:{s:6:\"number\";i:3630;s:4:\"text\";s:153:\"Dis: «Qui vous nourrit du ciel et de la terre?» Dis: «Allah. C\'est nous ou bien vous qui sommes sur une bonne voie, ou dans un égarement manifeste».\";s:13:\"numberInSurah\";i:24;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:431;s:4:\"ruku\";i:372;s:11:\"hizbQuarter\";i:173;s:5:\"sajda\";b:0;}i:24;a:9:{s:6:\"number\";i:3631;s:4:\"text\";s:134:\"Dis: «Vous ne serez pas interrogés sur les crimes que nous avons commis, et nous ne serons pas interrogés sur ce que vous faites».\";s:13:\"numberInSurah\";i:25;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:431;s:4:\"ruku\";i:372;s:11:\"hizbQuarter\";i:173;s:5:\"sajda\";b:0;}i:25;a:9:{s:6:\"number\";i:3632;s:4:\"text\";s:129:\"Dis: «Notre Seigneur nous réunira, puis Il tranchera entre nous, avec la vérité, car c\'est Lui le Grand Juge, l\'Omniscient».\";s:13:\"numberInSurah\";i:26;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:431;s:4:\"ruku\";i:372;s:11:\"hizbQuarter\";i:173;s:5:\"sajda\";b:0;}i:26;a:9:{s:6:\"number\";i:3633;s:4:\"text\";s:130:\"Dis: «Montrez-moi ceux que vous Lui avez donnés comme associés. Eh bien, non! C\'est plutôt Lui, Allah, le Puissant, le Sage».\";s:13:\"numberInSurah\";i:27;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:431;s:4:\"ruku\";i:372;s:11:\"hizbQuarter\";i:173;s:5:\"sajda\";b:0;}i:27;a:9:{s:6:\"number\";i:3634;s:4:\"text\";s:132:\"Et Nous ne t\'avons envoyé qu\'en tant qu\'annonciateur et avertisseur pour toute l\'humanité. Mais la plupart des gens ne savent pas.\";s:13:\"numberInSurah\";i:28;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:431;s:4:\"ruku\";i:372;s:11:\"hizbQuarter\";i:173;s:5:\"sajda\";b:0;}i:28;a:9:{s:6:\"number\";i:3635;s:4:\"text\";s:69:\"Et ils disent: «A quand cette promesse, si vous êtes véridiques?»\";s:13:\"numberInSurah\";i:29;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:431;s:4:\"ruku\";i:372;s:11:\"hizbQuarter\";i:173;s:5:\"sajda\";b:0;}i:29;a:9:{s:6:\"number\";i:3636;s:4:\"text\";s:93:\"Dis: «Le rendez-vous est pour un jour que vous ne saurez retarder d\'une heure, ni avancer!»\";s:13:\"numberInSurah\";i:30;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:431;s:4:\"ruku\";i:372;s:11:\"hizbQuarter\";i:173;s:5:\"sajda\";b:0;}i:30;a:9:{s:6:\"number\";i:3637;s:4:\"text\";s:356:\"Et ceux qui avaient mécru dirent: «Jamais nous ne croirons à ce Coran ni à ce qui l\'a précédé». Et si tu pouvais voir quand les injustes seront debout devant leur Seigneur, se renvoyant la parole les uns aux autres! Ceux que l\'on considérait comme faibles diront à ceux qui s\'enorgueillissaient: «Sans vous, nous aurions certes été croyants».\";s:13:\"numberInSurah\";i:31;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:431;s:4:\"ruku\";i:373;s:11:\"hizbQuarter\";i:173;s:5:\"sajda\";b:0;}i:31;a:9:{s:6:\"number\";i:3638;s:4:\"text\";s:216:\"Ceux qui s\'enorgueillissaient diront à ceux qu\'ils considéraient comme faibles: «Est-ce nous qui vous avons repoussés de la bonne direction après qu\'elle vous fut venue? Mais vous étiez plutôt des criminels».\";s:13:\"numberInSurah\";i:32;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:432;s:4:\"ruku\";i:373;s:11:\"hizbQuarter\";i:173;s:5:\"sajda\";b:0;}i:32;a:9:{s:6:\"number\";i:3639;s:4:\"text\";s:399:\"Et ceux que l\'on considérait comme faibles diront à ceux qui s\'enorgueillissaient: «C\'était votre stratagème, plutôt, nuit et jour, de nous commander de ne pas croire en Allah et de Lui donner des égaux». Et ils cacheront leur regret quand ils verront le châtiment. Nous placerons des carcans aux cous de ceux qui ont mécru: les rétribuerait-on autrement que selon ce qu\'ils œuvraient?»\";s:13:\"numberInSurah\";i:33;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:432;s:4:\"ruku\";i:373;s:11:\"hizbQuarter\";i:173;s:5:\"sajda\";b:0;}i:33;a:9:{s:6:\"number\";i:3640;s:4:\"text\";s:162:\"Et Nous n\'avons envoyé aucun avertisseur dans une cité sans que ses gens aisés n\'aient dit: «Nous ne croyons pas au message avec lequel vous êtes envoyés».\";s:13:\"numberInSurah\";i:34;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:432;s:4:\"ruku\";i:373;s:11:\"hizbQuarter\";i:173;s:5:\"sajda\";b:0;}i:34;a:9:{s:6:\"number\";i:3641;s:4:\"text\";s:98:\"Et ils dirent: «Nous avons davantage de richesses et d\'enfants et nous ne serons pas châtiés».\";s:13:\"numberInSurah\";i:35;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:432;s:4:\"ruku\";i:373;s:11:\"hizbQuarter\";i:173;s:5:\"sajda\";b:0;}i:35;a:9:{s:6:\"number\";i:3642;s:4:\"text\";s:122:\"Dis: «Mon Seigneur dispense avec largesse ou restreint Ses dons à qui Il veut. Mais la plupart des gens ne savent pas».\";s:13:\"numberInSurah\";i:36;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:432;s:4:\"ruku\";i:373;s:11:\"hizbQuarter\";i:173;s:5:\"sajda\";b:0;}i:36;a:9:{s:6:\"number\";i:3643;s:4:\"text\";s:257:\"Ni vos biens ni vos enfants ne vous rapprocheront à proximité de Nous. Sauf celui qui croit et œuvre dans le bien. Ceux-là auront une double récompense pour ce qu\'ils œuvraient, tandis qu\'ils seront en sécurité, aux étages supérieurs (du Paradis).\";s:13:\"numberInSurah\";i:37;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:432;s:4:\"ruku\";i:374;s:11:\"hizbQuarter\";i:173;s:5:\"sajda\";b:0;}i:37;a:9:{s:6:\"number\";i:3644;s:4:\"text\";s:124:\"Et quant à ceux qui s\'efforcent à rendre Nos versets inefficients, ceux-là seront forcés de se présenter au châtiment.\";s:13:\"numberInSurah\";i:38;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:432;s:4:\"ruku\";i:374;s:11:\"hizbQuarter\";i:173;s:5:\"sajda\";b:0;}i:38;a:9:{s:6:\"number\";i:3645;s:4:\"text\";s:209:\"Dis: «Mon Seigneur dispense avec largesse ou restreint Ses dons à qui Il veut parmi ses serviteurs. Et toute dépense que vous faites [dans le bien], Il la remplace, et c\'est Lui le Meilleur des donateurs».\";s:13:\"numberInSurah\";i:39;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:432;s:4:\"ruku\";i:374;s:11:\"hizbQuarter\";i:173;s:5:\"sajda\";b:0;}i:39;a:9:{s:6:\"number\";i:3646;s:4:\"text\";s:103:\"Et un jour Il les rassemblera tous. Puis Il dira aux Anges: «Est-ce vous que ces gens-là adoraient?»\";s:13:\"numberInSurah\";i:40;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:433;s:4:\"ruku\";i:374;s:11:\"hizbQuarter\";i:173;s:5:\"sajda\";b:0;}i:40;a:9:{s:6:\"number\";i:3647;s:4:\"text\";s:139:\"Ils diront: «Gloire à Toi! Tu es notre Allié en dehors d\'eux. Ils adoraient plutôt les djinns, en qui la plupart d\'entre eux croyaient.\";s:13:\"numberInSurah\";i:41;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:433;s:4:\"ruku\";i:374;s:11:\"hizbQuarter\";i:173;s:5:\"sajda\";b:0;}i:41;a:9:{s:6:\"number\";i:3648;s:4:\"text\";s:186:\"Ce jour-là donc, vous n\'aurez aucun moyen pour profiter ou nuire les uns aux autres, tandis que Nous dirons aux injustes: «Goûtez au châtiment du Feu que vous traitiez de mensonge».\";s:13:\"numberInSurah\";i:42;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:433;s:4:\"ruku\";i:374;s:11:\"hizbQuarter\";i:173;s:5:\"sajda\";b:0;}i:42;a:9:{s:6:\"number\";i:3649;s:4:\"text\";s:329:\"Et quand Nos versets édifiants leur sont récités, ils disent: Ce n\'est là qu\'un homme qui veut vous repousser de ce que vos ancêtres adoraient». Et ils disent: «Ceci (Le Coran) n\'est qu\'un mensonge inventé». Et ceux qui ne croient pas disent de la Vérité quand elle leur vient: «Ce n\'est là qu\'une magie évidente!»\";s:13:\"numberInSurah\";i:43;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:433;s:4:\"ruku\";i:374;s:11:\"hizbQuarter\";i:173;s:5:\"sajda\";b:0;}i:43;a:9:{s:6:\"number\";i:3650;s:4:\"text\";s:122:\"[Pourtant] Nous ne leur avons pas donné de livres à étudier. Et Nous ne leur avons envoyé avant toi aucun avertisseur.\";s:13:\"numberInSurah\";i:44;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:433;s:4:\"ruku\";i:374;s:11:\"hizbQuarter\";i:173;s:5:\"sajda\";b:0;}i:44;a:9:{s:6:\"number\";i:3651;s:4:\"text\";s:245:\"Ceux d\'avant eux avaient [aussi] démenti (leurs messagers). [Les Mecquois] n\'ont pas atteint le dixième de ce que Nous leur avons donné [en force et en richesse]. Ils traitaient Mes Messagers de menteurs. Et quelle réprobation fut la mienne!\";s:13:\"numberInSurah\";i:45;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:433;s:4:\"ruku\";i:374;s:11:\"hizbQuarter\";i:173;s:5:\"sajda\";b:0;}i:45;a:9:{s:6:\"number\";i:3652;s:4:\"text\";s:262:\"Dis: «Je vous exhorte seulement à une chose: que pour Allah vous vous leviez, par deux ou isolément, et qu\'ensuite vous réfléchissiez. Votre compagnon (Muhammad) n\'est nullement possédé: il n\'est pour vous qu\'un avertisseur annonçant un dur châtiment».\";s:13:\"numberInSurah\";i:46;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:433;s:4:\"ruku\";i:375;s:11:\"hizbQuarter\";i:174;s:5:\"sajda\";b:0;}i:46;a:9:{s:6:\"number\";i:3653;s:4:\"text\";s:140:\"Dis: «Ce que je vous demande comme salaire, c\'est pour vous-mêmes. Car mon salaire n\'incombe qu\'à Allah. Il est Témoin de toute chose».\";s:13:\"numberInSurah\";i:47;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:433;s:4:\"ruku\";i:375;s:11:\"hizbQuarter\";i:174;s:5:\"sajda\";b:0;}i:47;a:9:{s:6:\"number\";i:3654;s:4:\"text\";s:119:\"Dis: «Certes, mon Seigneur lance la Vérité, [à Ses messagers], Il est le Parfait Connaisseur des inconnaissables».\";s:13:\"numberInSurah\";i:48;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:433;s:4:\"ruku\";i:375;s:11:\"hizbQuarter\";i:174;s:5:\"sajda\";b:0;}i:48;a:9:{s:6:\"number\";i:3655;s:4:\"text\";s:107:\"Dis: «La vérité [l\'Islam] est venue. Et le Faux [la mécréance] ne peut rien commencer ni renouveler».\";s:13:\"numberInSurah\";i:49;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:434;s:4:\"ruku\";i:375;s:11:\"hizbQuarter\";i:174;s:5:\"sajda\";b:0;}i:49;a:9:{s:6:\"number\";i:3656;s:4:\"text\";s:170:\"Dis: «Si je m\'égare, je ne m\'égare qu\'à mes dépens; tandis que si je me guide, alors c\'est grâce à ce que Mon Seigneur me révèle, car Il est Audient et Proche».\";s:13:\"numberInSurah\";i:50;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:434;s:4:\"ruku\";i:375;s:11:\"hizbQuarter\";i:174;s:5:\"sajda\";b:0;}i:50;a:9:{s:6:\"number\";i:3657;s:4:\"text\";s:114:\"Si tu les voyais quand ils seront saisis de peur, - pas d\'échappatoire pour eux -, et ils seront saisis de près!\";s:13:\"numberInSurah\";i:51;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:434;s:4:\"ruku\";i:375;s:11:\"hizbQuarter\";i:174;s:5:\"sajda\";b:0;}i:51;a:9:{s:6:\"number\";i:3658;s:4:\"text\";s:92:\"Ils diront alors: «Nous croyons en lui». - Mais comment atteindront-ils la foi de si loin?\";s:13:\"numberInSurah\";i:52;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:434;s:4:\"ruku\";i:375;s:11:\"hizbQuarter\";i:174;s:5:\"sajda\";b:0;}i:52;a:9:{s:6:\"number\";i:3659;s:4:\"text\";s:116:\"alors qu\'auparavant ils y avaient effectivement mécru et ils offensent l\'inconnu à partir d\'un endroit éloigné !\";s:13:\"numberInSurah\";i:53;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:434;s:4:\"ruku\";i:375;s:11:\"hizbQuarter\";i:174;s:5:\"sajda\";b:0;}i:53;a:9:{s:6:\"number\";i:3660;s:4:\"text\";s:149:\"On les empêchera d\'atteindre ce qu\'ils désirent, comme cela fut fait auparavant avec leurs semblables, car ils se trouvaient dans un doute profond.\";s:13:\"numberInSurah\";i:54;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:434;s:4:\"ruku\";i:375;s:11:\"hizbQuarter\";i:174;s:5:\"sajda\";b:0;}}s:7:\"edition\";a:7:{s:10:\"identifier\";s:13:\"fr.hamidullah\";s:8:\"language\";s:2:\"fr\";s:4:\"name\";s:10:\"Hamidullah\";s:11:\"englishName\";s:19:\"Muhammad Hamidullah\";s:6:\"format\";s:4:\"text\";s:4:\"type\";s:11:\"translation\";s:9:\"direction\";s:3:\"ltr\";}}', 1794581368),
('quranapp-cache-surah_35_ar.uthmani', 'a:8:{s:6:\"number\";i:35;s:4:\"name\";s:29:\"سُورَةُ فَاطِرٍ\";s:11:\"englishName\";s:6:\"Faatir\";s:22:\"englishNameTranslation\";s:14:\"The Originator\";s:14:\"revelationType\";s:6:\"Meccan\";s:13:\"numberOfAyahs\";i:45;s:5:\"ayahs\";a:45:{i:0;a:9:{s:6:\"number\";i:3661;s:4:\"text\";s:497:\"بِسۡمِ ٱللَّهِ ٱلرَّحۡمَـٰنِ ٱلرَّحِیمِ ٱلۡحَمۡدُ لِلَّهِ فَاطِرِ ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِ جَاعِلِ ٱلۡمَلَـٰۤىِٕكَةِ رُسُلًا أُو۟لِیۤ أَجۡنِحَةࣲ مَّثۡنَىٰ وَثُلَـٰثَ وَرُبَـٰعَۚ یَزِیدُ فِی ٱلۡخَلۡقِ مَا یَشَاۤءُۚ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَیۡءࣲ قَدِیرࣱ\n\";s:13:\"numberInSurah\";i:1;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:434;s:4:\"ruku\";i:376;s:11:\"hizbQuarter\";i:174;s:5:\"sajda\";b:0;}i:1;a:9:{s:6:\"number\";i:3662;s:4:\"text\";s:280:\"مَّا یَفۡتَحِ ٱللَّهُ لِلنَّاسِ مِن رَّحۡمَةࣲ فَلَا مُمۡسِكَ لَهَاۖ وَمَا یُمۡسِكۡ فَلَا مُرۡسِلَ لَهُۥ مِنۢ بَعۡدِهِۦۚ وَهُوَ ٱلۡعَزِیزُ ٱلۡحَكِیمُ\n\";s:13:\"numberInSurah\";i:2;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:434;s:4:\"ruku\";i:376;s:11:\"hizbQuarter\";i:174;s:5:\"sajda\";b:0;}i:2;a:9:{s:6:\"number\";i:3663;s:4:\"text\";s:357:\"یَـٰۤأَیُّهَا ٱلنَّاسُ ٱذۡكُرُوا۟ نِعۡمَتَ ٱللَّهِ عَلَیۡكُمۡۚ هَلۡ مِنۡ خَـٰلِقٍ غَیۡرُ ٱللَّهِ یَرۡزُقُكُم مِّنَ ٱلسَّمَاۤءِ وَٱلۡأَرۡضِۚ لَاۤ إِلَـٰهَ إِلَّا هُوَۖ فَأَنَّىٰ تُؤۡفَكُونَ\n\";s:13:\"numberInSurah\";i:3;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:434;s:4:\"ruku\";i:376;s:11:\"hizbQuarter\";i:174;s:5:\"sajda\";b:0;}i:3;a:9:{s:6:\"number\";i:3664;s:4:\"text\";s:178:\"وَإِن یُكَذِّبُوكَ فَقَدۡ كُذِّبَتۡ رُسُلࣱ مِّن قَبۡلِكَۚ وَإِلَى ٱللَّهِ تُرۡجَعُ ٱلۡأُمُورُ\n\";s:13:\"numberInSurah\";i:4;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:435;s:4:\"ruku\";i:376;s:11:\"hizbQuarter\";i:174;s:5:\"sajda\";b:0;}i:4;a:9:{s:6:\"number\";i:3665;s:4:\"text\";s:259:\"یَـٰۤأَیُّهَا ٱلنَّاسُ إِنَّ وَعۡدَ ٱللَّهِ حَقࣱّۖ فَلَا تَغُرَّنَّكُمُ ٱلۡحَیَوٰةُ ٱلدُّنۡیَا وَلَا یَغُرَّنَّكُم بِٱللَّهِ ٱلۡغَرُورُ\n\";s:13:\"numberInSurah\";i:5;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:435;s:4:\"ruku\";i:376;s:11:\"hizbQuarter\";i:174;s:5:\"sajda\";b:0;}i:5;a:9:{s:6:\"number\";i:3666;s:4:\"text\";s:244:\"إِنَّ ٱلشَّیۡطَـٰنَ لَكُمۡ عَدُوࣱّ فَٱتَّخِذُوهُ عَدُوًّاۚ إِنَّمَا یَدۡعُوا۟ حِزۡبَهُۥ لِیَكُونُوا۟ مِنۡ أَصۡحَـٰبِ ٱلسَّعِیرِ\n\";s:13:\"numberInSurah\";i:6;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:435;s:4:\"ruku\";i:376;s:11:\"hizbQuarter\";i:174;s:5:\"sajda\";b:0;}i:6;a:9:{s:6:\"number\";i:3667;s:4:\"text\";s:251:\"ٱلَّذِینَ كَفَرُوا۟ لَهُمۡ عَذَابࣱ شَدِیدࣱۖ وَٱلَّذِینَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ لَهُم مَّغۡفِرَةࣱ وَأَجۡرࣱ كَبِیرٌ\n\";s:13:\"numberInSurah\";i:7;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:435;s:4:\"ruku\";i:376;s:11:\"hizbQuarter\";i:174;s:5:\"sajda\";b:0;}i:7;a:9:{s:6:\"number\";i:3668;s:4:\"text\";s:394:\"أَفَمَن زُیِّنَ لَهُۥ سُوۤءُ عَمَلِهِۦ فَرَءَاهُ حَسَنࣰاۖ فَإِنَّ ٱللَّهَ یُضِلُّ مَن یَشَاۤءُ وَیَهۡدِی مَن یَشَاۤءُۖ فَلَا تَذۡهَبۡ نَفۡسُكَ عَلَیۡهِمۡ حَسَرَ ٰ⁠تٍۚ إِنَّ ٱللَّهَ عَلِیمُۢ بِمَا یَصۡنَعُونَ\n\";s:13:\"numberInSurah\";i:8;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:435;s:4:\"ruku\";i:377;s:11:\"hizbQuarter\";i:174;s:5:\"sajda\";b:0;}i:8;a:9:{s:6:\"number\";i:3669;s:4:\"text\";s:318:\"وَٱللَّهُ ٱلَّذِیۤ أَرۡسَلَ ٱلرِّیَـٰحَ فَتُثِیرُ سَحَابࣰا فَسُقۡنَـٰهُ إِلَىٰ بَلَدࣲ مَّیِّتࣲ فَأَحۡیَیۡنَا بِهِ ٱلۡأَرۡضَ بَعۡدَ مَوۡتِهَاۚ كَذَ ٰ⁠لِكَ ٱلنُّشُورُ\n\";s:13:\"numberInSurah\";i:9;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:435;s:4:\"ruku\";i:377;s:11:\"hizbQuarter\";i:174;s:5:\"sajda\";b:0;}i:9;a:9:{s:6:\"number\";i:3670;s:4:\"text\";s:450:\"مَن كَانَ یُرِیدُ ٱلۡعِزَّةَ فَلِلَّهِ ٱلۡعِزَّةُ جَمِیعًاۚ إِلَیۡهِ یَصۡعَدُ ٱلۡكَلِمُ ٱلطَّیِّبُ وَٱلۡعَمَلُ ٱلصَّـٰلِحُ یَرۡفَعُهُۥۚ وَٱلَّذِینَ یَمۡكُرُونَ ٱلسَّیِّـَٔاتِ لَهُمۡ عَذَابࣱ شَدِیدࣱۖ وَمَكۡرُ أُو۟لَـٰۤىِٕكَ هُوَ یَبُورُ\n\";s:13:\"numberInSurah\";i:10;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:435;s:4:\"ruku\";i:377;s:11:\"hizbQuarter\";i:174;s:5:\"sajda\";b:0;}i:10;a:9:{s:6:\"number\";i:3671;s:4:\"text\";s:505:\"وَٱللَّهُ خَلَقَكُم مِّن تُرَابࣲ ثُمَّ مِن نُّطۡفَةࣲ ثُمَّ جَعَلَكُمۡ أَزۡوَ ٰ⁠جࣰاۚ وَمَا تَحۡمِلُ مِنۡ أُنثَىٰ وَلَا تَضَعُ إِلَّا بِعِلۡمِهِۦۚ وَمَا یُعَمَّرُ مِن مُّعَمَّرࣲ وَلَا یُنقَصُ مِنۡ عُمُرِهِۦۤ إِلَّا فِی كِتَـٰبٍۚ إِنَّ ذَ ٰ⁠لِكَ عَلَى ٱللَّهِ یَسِیرࣱ\n\";s:13:\"numberInSurah\";i:11;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:435;s:4:\"ruku\";i:377;s:11:\"hizbQuarter\";i:174;s:5:\"sajda\";b:0;}i:11;a:9:{s:6:\"number\";i:3672;s:4:\"text\";s:522:\"وَمَا یَسۡتَوِی ٱلۡبَحۡرَانِ هَـٰذَا عَذۡبࣱ فُرَاتࣱ سَاۤىِٕغࣱ شَرَابُهُۥ وَهَـٰذَا مِلۡحٌ أُجَاجࣱۖ وَمِن كُلࣲّ تَأۡكُلُونَ لَحۡمࣰا طَرِیࣰّا وَتَسۡتَخۡرِجُونَ حِلۡیَةࣰ تَلۡبَسُونَهَاۖ وَتَرَى ٱلۡفُلۡكَ فِیهِ مَوَاخِرَ لِتَبۡتَغُوا۟ مِن فَضۡلِهِۦ وَلَعَلَّكُمۡ تَشۡكُرُونَ\n\";s:13:\"numberInSurah\";i:12;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:436;s:4:\"ruku\";i:377;s:11:\"hizbQuarter\";i:174;s:5:\"sajda\";b:0;}i:12;a:9:{s:6:\"number\";i:3673;s:4:\"text\";s:465:\"یُولِجُ ٱلَّیۡلَ فِی ٱلنَّهَارِ وَیُولِجُ ٱلنَّهَارَ فِی ٱلَّیۡلِ وَسَخَّرَ ٱلشَّمۡسَ وَٱلۡقَمَرَۖ كُلࣱّ یَجۡرِی لِأَجَلࣲ مُّسَمࣰّىۚ ذَ ٰ⁠لِكُمُ ٱللَّهُ رَبُّكُمۡ لَهُ ٱلۡمُلۡكُۚ وَٱلَّذِینَ تَدۡعُونَ مِن دُونِهِۦ مَا یَمۡلِكُونَ مِن قِطۡمِیرٍ\n\";s:13:\"numberInSurah\";i:13;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:436;s:4:\"ruku\";i:377;s:11:\"hizbQuarter\";i:174;s:5:\"sajda\";b:0;}i:13;a:9:{s:6:\"number\";i:3674;s:4:\"text\";s:323:\"إِن تَدۡعُوهُمۡ لَا یَسۡمَعُوا۟ دُعَاۤءَكُمۡ وَلَوۡ سَمِعُوا۟ مَا ٱسۡتَجَابُوا۟ لَكُمۡۖ وَیَوۡمَ ٱلۡقِیَـٰمَةِ یَكۡفُرُونَ بِشِرۡكِكُمۡۚ وَلَا یُنَبِّئُكَ مِثۡلُ خَبِیرࣲ\n\";s:13:\"numberInSurah\";i:14;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:436;s:4:\"ruku\";i:377;s:11:\"hizbQuarter\";i:174;s:5:\"sajda\";b:0;}i:14;a:9:{s:6:\"number\";i:3675;s:4:\"text\";s:187:\"۞ یَـٰۤأَیُّهَا ٱلنَّاسُ أَنتُمُ ٱلۡفُقَرَاۤءُ إِلَى ٱللَّهِۖ وَٱللَّهُ هُوَ ٱلۡغَنِیُّ ٱلۡحَمِیدُ\n\";s:13:\"numberInSurah\";i:15;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:436;s:4:\"ruku\";i:378;s:11:\"hizbQuarter\";i:175;s:5:\"sajda\";b:0;}i:15;a:9:{s:6:\"number\";i:3676;s:4:\"text\";s:96:\"إِن یَشَأۡ یُذۡهِبۡكُمۡ وَیَأۡتِ بِخَلۡقࣲ جَدِیدࣲ\n\";s:13:\"numberInSurah\";i:16;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:436;s:4:\"ruku\";i:378;s:11:\"hizbQuarter\";i:175;s:5:\"sajda\";b:0;}i:16;a:9:{s:6:\"number\";i:3677;s:4:\"text\";s:78:\"وَمَا ذَ ٰ⁠لِكَ عَلَى ٱللَّهِ بِعَزِیزࣲ\n\";s:13:\"numberInSurah\";i:17;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:436;s:4:\"ruku\";i:378;s:11:\"hizbQuarter\";i:175;s:5:\"sajda\";b:0;}i:17;a:9:{s:6:\"number\";i:3678;s:4:\"text\";s:568:\"وَلَا تَزِرُ وَازِرَةࣱ وِزۡرَ أُخۡرَىٰۚ وَإِن تَدۡعُ مُثۡقَلَةٌ إِلَىٰ حِمۡلِهَا لَا یُحۡمَلۡ مِنۡهُ شَیۡءࣱ وَلَوۡ كَانَ ذَا قُرۡبَىٰۤۗ إِنَّمَا تُنذِرُ ٱلَّذِینَ یَخۡشَوۡنَ رَبَّهُم بِٱلۡغَیۡبِ وَأَقَامُوا۟ ٱلصَّلَوٰةَۚ وَمَن تَزَكَّىٰ فَإِنَّمَا یَتَزَكَّىٰ لِنَفۡسِهِۦۚ وَإِلَى ٱللَّهِ ٱلۡمَصِیرُ\n\";s:13:\"numberInSurah\";i:18;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:436;s:4:\"ruku\";i:378;s:11:\"hizbQuarter\";i:175;s:5:\"sajda\";b:0;}i:18;a:9:{s:6:\"number\";i:3679;s:4:\"text\";s:78:\"وَمَا یَسۡتَوِی ٱلۡأَعۡمَىٰ وَٱلۡبَصِیرُ\n\";s:13:\"numberInSurah\";i:19;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:437;s:4:\"ruku\";i:378;s:11:\"hizbQuarter\";i:175;s:5:\"sajda\";b:0;}i:19;a:9:{s:6:\"number\";i:3680;s:4:\"text\";s:66:\"وَلَا ٱلظُّلُمَـٰتُ وَلَا ٱلنُّورُ\n\";s:13:\"numberInSurah\";i:20;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:437;s:4:\"ruku\";i:378;s:11:\"hizbQuarter\";i:175;s:5:\"sajda\";b:0;}i:20;a:9:{s:6:\"number\";i:3681;s:4:\"text\";s:60:\"وَلَا ٱلظِّلُّ وَلَا ٱلۡحَرُورُ\n\";s:13:\"numberInSurah\";i:21;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:437;s:4:\"ruku\";i:378;s:11:\"hizbQuarter\";i:175;s:5:\"sajda\";b:0;}i:21;a:9:{s:6:\"number\";i:3682;s:4:\"text\";s:253:\"وَمَا یَسۡتَوِی ٱلۡأَحۡیَاۤءُ وَلَا ٱلۡأَمۡوَ ٰ⁠تُۚ إِنَّ ٱللَّهَ یُسۡمِعُ مَن یَشَاۤءُۖ وَمَاۤ أَنتَ بِمُسۡمِعࣲ مَّن فِی ٱلۡقُبُورِ\n\";s:13:\"numberInSurah\";i:22;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:437;s:4:\"ruku\";i:378;s:11:\"hizbQuarter\";i:175;s:5:\"sajda\";b:0;}i:22;a:9:{s:6:\"number\";i:3683;s:4:\"text\";s:48:\"إِنۡ أَنتَ إِلَّا نَذِیرٌ\n\";s:13:\"numberInSurah\";i:23;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:437;s:4:\"ruku\";i:378;s:11:\"hizbQuarter\";i:175;s:5:\"sajda\";b:0;}i:23;a:9:{s:6:\"number\";i:3684;s:4:\"text\";s:197:\"إِنَّاۤ أَرۡسَلۡنَـٰكَ بِٱلۡحَقِّ بَشِیرࣰا وَنَذِیرࣰاۚ وَإِن مِّنۡ أُمَّةٍ إِلَّا خَلَا فِیهَا نَذِیرࣱ\n\";s:13:\"numberInSurah\";i:24;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:437;s:4:\"ruku\";i:378;s:11:\"hizbQuarter\";i:175;s:5:\"sajda\";b:0;}i:24;a:9:{s:6:\"number\";i:3685;s:4:\"text\";s:267:\"وَإِن یُكَذِّبُوكَ فَقَدۡ كَذَّبَ ٱلَّذِینَ مِن قَبۡلِهِمۡ جَاۤءَتۡهُمۡ رُسُلُهُم بِٱلۡبَیِّنَـٰتِ وَبِٱلزُّبُرِ وَبِٱلۡكِتَـٰبِ ٱلۡمُنِیرِ\n\";s:13:\"numberInSurah\";i:25;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:437;s:4:\"ruku\";i:378;s:11:\"hizbQuarter\";i:175;s:5:\"sajda\";b:0;}i:25;a:9:{s:6:\"number\";i:3686;s:4:\"text\";s:111:\"ثُمَّ أَخَذۡتُ ٱلَّذِینَ كَفَرُوا۟ۖ فَكَیۡفَ كَانَ نَكِیرِ\n\";s:13:\"numberInSurah\";i:26;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:437;s:4:\"ruku\";i:378;s:11:\"hizbQuarter\";i:175;s:5:\"sajda\";b:0;}i:26;a:9:{s:6:\"number\";i:3687;s:4:\"text\";s:401:\"أَلَمۡ تَرَ أَنَّ ٱللَّهَ أَنزَلَ مِنَ ٱلسَّمَاۤءِ مَاۤءࣰ فَأَخۡرَجۡنَا بِهِۦ ثَمَرَ ٰ⁠تࣲ مُّخۡتَلِفًا أَلۡوَ ٰ⁠نُهَاۚ وَمِنَ ٱلۡجِبَالِ جُدَدُۢ بِیضࣱ وَحُمۡرࣱ مُّخۡتَلِفٌ أَلۡوَ ٰ⁠نُهَا وَغَرَابِیبُ سُودࣱ\n\";s:13:\"numberInSurah\";i:27;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:437;s:4:\"ruku\";i:379;s:11:\"hizbQuarter\";i:175;s:5:\"sajda\";b:0;}i:27;a:9:{s:6:\"number\";i:3688;s:4:\"text\";s:335:\"وَمِنَ ٱلنَّاسِ وَٱلدَّوَاۤبِّ وَٱلۡأَنۡعَـٰمِ مُخۡتَلِفٌ أَلۡوَ ٰ⁠نُهُۥ كَذَ ٰ⁠لِكَۗ إِنَّمَا یَخۡشَى ٱللَّهَ مِنۡ عِبَادِهِ ٱلۡعُلَمَـٰۤؤُا۟ۗ إِنَّ ٱللَّهَ عَزِیزٌ غَفُورٌ\n\";s:13:\"numberInSurah\";i:28;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:437;s:4:\"ruku\";i:379;s:11:\"hizbQuarter\";i:175;s:5:\"sajda\";b:0;}i:28;a:9:{s:6:\"number\";i:3689;s:4:\"text\";s:303:\"إِنَّ ٱلَّذِینَ یَتۡلُونَ كِتَـٰبَ ٱللَّهِ وَأَقَامُوا۟ ٱلصَّلَوٰةَ وَأَنفَقُوا۟ مِمَّا رَزَقۡنَـٰهُمۡ سِرࣰّا وَعَلَانِیَةࣰ یَرۡجُونَ تِجَـٰرَةࣰ لَّن تَبُورَ\n\";s:13:\"numberInSurah\";i:29;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:437;s:4:\"ruku\";i:379;s:11:\"hizbQuarter\";i:175;s:5:\"sajda\";b:0;}i:29;a:9:{s:6:\"number\";i:3690;s:4:\"text\";s:160:\"لِیُوَفِّیَهُمۡ أُجُورَهُمۡ وَیَزِیدَهُم مِّن فَضۡلِهِۦۤۚ إِنَّهُۥ غَفُورࣱ شَكُورࣱ\n\";s:13:\"numberInSurah\";i:30;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:437;s:4:\"ruku\";i:379;s:11:\"hizbQuarter\";i:175;s:5:\"sajda\";b:0;}i:30;a:9:{s:6:\"number\";i:3691;s:4:\"text\";s:276:\"وَٱلَّذِیۤ أَوۡحَیۡنَاۤ إِلَیۡكَ مِنَ ٱلۡكِتَـٰبِ هُوَ ٱلۡحَقُّ مُصَدِّقࣰا لِّمَا بَیۡنَ یَدَیۡهِۗ إِنَّ ٱللَّهَ بِعِبَادِهِۦ لَخَبِیرُۢ بَصِیرࣱ\n\";s:13:\"numberInSurah\";i:31;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:438;s:4:\"ruku\";i:379;s:11:\"hizbQuarter\";i:175;s:5:\"sajda\";b:0;}i:31;a:9:{s:6:\"number\";i:3692;s:4:\"text\";s:415:\"ثُمَّ أَوۡرَثۡنَا ٱلۡكِتَـٰبَ ٱلَّذِینَ ٱصۡطَفَیۡنَا مِنۡ عِبَادِنَاۖ فَمِنۡهُمۡ ظَالِمࣱ لِّنَفۡسِهِۦ وَمِنۡهُم مُّقۡتَصِدࣱ وَمِنۡهُمۡ سَابِقُۢ بِٱلۡخَیۡرَ ٰ⁠تِ بِإِذۡنِ ٱللَّهِۚ ذَ ٰ⁠لِكَ هُوَ ٱلۡفَضۡلُ ٱلۡكَبِیرُ\n\";s:13:\"numberInSurah\";i:32;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:438;s:4:\"ruku\";i:379;s:11:\"hizbQuarter\";i:175;s:5:\"sajda\";b:0;}i:32;a:9:{s:6:\"number\";i:3693;s:4:\"text\";s:229:\"جَنَّـٰتُ عَدۡنࣲ یَدۡخُلُونَهَا یُحَلَّوۡنَ فِیهَا مِنۡ أَسَاوِرَ مِن ذَهَبࣲ وَلُؤۡلُؤࣰاۖ وَلِبَاسُهُمۡ فِیهَا حَرِیرࣱ\n\";s:13:\"numberInSurah\";i:33;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:438;s:4:\"ruku\";i:379;s:11:\"hizbQuarter\";i:175;s:5:\"sajda\";b:0;}i:33;a:9:{s:6:\"number\";i:3694;s:4:\"text\";s:186:\"وَقَالُوا۟ ٱلۡحَمۡدُ لِلَّهِ ٱلَّذِیۤ أَذۡهَبَ عَنَّا ٱلۡحَزَنَۖ إِنَّ رَبَّنَا لَغَفُورࣱ شَكُورٌ\n\";s:13:\"numberInSurah\";i:34;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:438;s:4:\"ruku\";i:379;s:11:\"hizbQuarter\";i:175;s:5:\"sajda\";b:0;}i:34;a:9:{s:6:\"number\";i:3695;s:4:\"text\";s:216:\"ٱلَّذِیۤ أَحَلَّنَا دَارَ ٱلۡمُقَامَةِ مِن فَضۡلِهِۦ لَا یَمَسُّنَا فِیهَا نَصَبࣱ وَلَا یَمَسُّنَا فِیهَا لُغُوبࣱ\n\";s:13:\"numberInSurah\";i:35;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:438;s:4:\"ruku\";i:379;s:11:\"hizbQuarter\";i:175;s:5:\"sajda\";b:0;}i:35;a:9:{s:6:\"number\";i:3696;s:4:\"text\";s:301:\"وَٱلَّذِینَ كَفَرُوا۟ لَهُمۡ نَارُ جَهَنَّمَ لَا یُقۡضَىٰ عَلَیۡهِمۡ فَیَمُوتُوا۟ وَلَا یُخَفَّفُ عَنۡهُم مِّنۡ عَذَابِهَاۚ كَذَ ٰ⁠لِكَ نَجۡزِی كُلَّ كَفُورࣲ\n\";s:13:\"numberInSurah\";i:36;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:438;s:4:\"ruku\";i:379;s:11:\"hizbQuarter\";i:175;s:5:\"sajda\";b:0;}i:36;a:9:{s:6:\"number\";i:3697;s:4:\"text\";s:437:\"وَهُمۡ یَصۡطَرِخُونَ فِیهَا رَبَّنَاۤ أَخۡرِجۡنَا نَعۡمَلۡ صَـٰلِحًا غَیۡرَ ٱلَّذِی كُنَّا نَعۡمَلُۚ أَوَلَمۡ نُعَمِّرۡكُم مَّا یَتَذَكَّرُ فِیهِ مَن تَذَكَّرَ وَجَاۤءَكُمُ ٱلنَّذِیرُۖ فَذُوقُوا۟ فَمَا لِلظَّـٰلِمِینَ مِن نَّصِیرٍ\n\";s:13:\"numberInSurah\";i:37;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:438;s:4:\"ruku\";i:379;s:11:\"hizbQuarter\";i:175;s:5:\"sajda\";b:0;}i:37;a:9:{s:6:\"number\";i:3698;s:4:\"text\";s:186:\"إِنَّ ٱللَّهَ عَـٰلِمُ غَیۡبِ ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِۚ إِنَّهُۥ عَلِیمُۢ بِذَاتِ ٱلصُّدُورِ\n\";s:13:\"numberInSurah\";i:38;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:438;s:4:\"ruku\";i:380;s:11:\"hizbQuarter\";i:175;s:5:\"sajda\";b:0;}i:38;a:9:{s:6:\"number\";i:3699;s:4:\"text\";s:408:\"هُوَ ٱلَّذِی جَعَلَكُمۡ خَلَـٰۤىِٕفَ فِی ٱلۡأَرۡضِۚ فَمَن كَفَرَ فَعَلَیۡهِ كُفۡرُهُۥۖ وَلَا یَزِیدُ ٱلۡكَـٰفِرِینَ كُفۡرُهُمۡ عِندَ رَبِّهِمۡ إِلَّا مَقۡتࣰاۖ وَلَا یَزِیدُ ٱلۡكَـٰفِرِینَ كُفۡرُهُمۡ إِلَّا خَسَارࣰا\n\";s:13:\"numberInSurah\";i:39;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:439;s:4:\"ruku\";i:380;s:11:\"hizbQuarter\";i:175;s:5:\"sajda\";b:0;}i:39;a:9:{s:6:\"number\";i:3700;s:4:\"text\";s:534:\"قُلۡ أَرَءَیۡتُمۡ شُرَكَاۤءَكُمُ ٱلَّذِینَ تَدۡعُونَ مِن دُونِ ٱللَّهِ أَرُونِی مَاذَا خَلَقُوا۟ مِنَ ٱلۡأَرۡضِ أَمۡ لَهُمۡ شِرۡكࣱ فِی ٱلسَّمَـٰوَ ٰ⁠تِ أَمۡ ءَاتَیۡنَـٰهُمۡ كِتَـٰبࣰا فَهُمۡ عَلَىٰ بَیِّنَتࣲ مِّنۡهُۚ بَلۡ إِن یَعِدُ ٱلظَّـٰلِمُونَ بَعۡضُهُم بَعۡضًا إِلَّا غُرُورًا\n\";s:13:\"numberInSurah\";i:40;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:439;s:4:\"ruku\";i:380;s:11:\"hizbQuarter\";i:175;s:5:\"sajda\";b:0;}i:40;a:9:{s:6:\"number\";i:3701;s:4:\"text\";s:322:\"۞ إِنَّ ٱللَّهَ یُمۡسِكُ ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضَ أَن تَزُولَاۚ وَلَىِٕن زَالَتَاۤ إِنۡ أَمۡسَكَهُمَا مِنۡ أَحَدࣲ مِّنۢ بَعۡدِهِۦۤۚ إِنَّهُۥ كَانَ حَلِیمًا غَفُورࣰا\n\";s:13:\"numberInSurah\";i:41;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:439;s:4:\"ruku\";i:380;s:11:\"hizbQuarter\";i:176;s:5:\"sajda\";b:0;}i:41;a:9:{s:6:\"number\";i:3702;s:4:\"text\";s:339:\"وَأَقۡسَمُوا۟ بِٱللَّهِ جَهۡدَ أَیۡمَـٰنِهِمۡ لَىِٕن جَاۤءَهُمۡ نَذِیرࣱ لَّیَكُونُنَّ أَهۡدَىٰ مِنۡ إِحۡدَى ٱلۡأُمَمِۖ فَلَمَّا جَاۤءَهُمۡ نَذِیرࣱ مَّا زَادَهُمۡ إِلَّا نُفُورًا\n\";s:13:\"numberInSurah\";i:42;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:439;s:4:\"ruku\";i:380;s:11:\"hizbQuarter\";i:176;s:5:\"sajda\";b:0;}i:42;a:9:{s:6:\"number\";i:3703;s:4:\"text\";s:452:\"ٱسۡتِكۡبَارࣰا فِی ٱلۡأَرۡضِ وَمَكۡرَ ٱلسَّیِّىِٕۚ وَلَا یَحِیقُ ٱلۡمَكۡرُ ٱلسَّیِّئُ إِلَّا بِأَهۡلِهِۦۚ فَهَلۡ یَنظُرُونَ إِلَّا سُنَّتَ ٱلۡأَوَّلِینَۚ فَلَن تَجِدَ لِسُنَّتِ ٱللَّهِ تَبۡدِیلࣰاۖ وَلَن تَجِدَ لِسُنَّتِ ٱللَّهِ تَحۡوِیلًا\n\";s:13:\"numberInSurah\";i:43;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:439;s:4:\"ruku\";i:380;s:11:\"hizbQuarter\";i:176;s:5:\"sajda\";b:0;}i:43;a:9:{s:6:\"number\";i:3704;s:4:\"text\";s:484:\"أَوَلَمۡ یَسِیرُوا۟ فِی ٱلۡأَرۡضِ فَیَنظُرُوا۟ كَیۡفَ كَانَ عَـٰقِبَةُ ٱلَّذِینَ مِن قَبۡلِهِمۡ وَكَانُوۤا۟ أَشَدَّ مِنۡهُمۡ قُوَّةࣰۚ وَمَا كَانَ ٱللَّهُ لِیُعۡجِزَهُۥ مِن شَیۡءࣲ فِی ٱلسَّمَـٰوَ ٰ⁠تِ وَلَا فِی ٱلۡأَرۡضِۚ إِنَّهُۥ كَانَ عَلِیمࣰا قَدِیرࣰا\n\";s:13:\"numberInSurah\";i:44;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:439;s:4:\"ruku\";i:380;s:11:\"hizbQuarter\";i:176;s:5:\"sajda\";b:0;}i:44;a:9:{s:6:\"number\";i:3705;s:4:\"text\";s:404:\"وَلَوۡ یُؤَاخِذُ ٱللَّهُ ٱلنَّاسَ بِمَا كَسَبُوا۟ مَا تَرَكَ عَلَىٰ ظَهۡرِهَا مِن دَاۤبَّةࣲ وَلَـٰكِن یُؤَخِّرُهُمۡ إِلَىٰۤ أَجَلࣲ مُّسَمࣰّىۖ فَإِذَا جَاۤءَ أَجَلُهُمۡ فَإِنَّ ٱللَّهَ كَانَ بِعِبَادِهِۦ بَصِیرَۢا\n\";s:13:\"numberInSurah\";i:45;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:440;s:4:\"ruku\";i:380;s:11:\"hizbQuarter\";i:176;s:5:\"sajda\";b:0;}}s:7:\"edition\";a:7:{s:10:\"identifier\";s:27:\"quran-uthmani-quran-academy\";s:8:\"language\";s:2:\"ar\";s:4:\"name\";s:67:\"القرآن الكريم برسم العثماني (quran-academy)\";s:11:\"englishName\";s:78:\"Modified Quran Uthmani Text from the Quran Academy to work with the Kitab font\";s:6:\"format\";s:4:\"text\";s:4:\"type\";s:5:\"quran\";s:9:\"direction\";s:3:\"rtl\";}}', 1794581369);
INSERT INTO `cache` (`key`, `value`, `expiration`) VALUES
('quranapp-cache-surah_35_fr.hamidullah', 'a:8:{s:6:\"number\";i:35;s:4:\"name\";s:29:\"سُورَةُ فَاطِرٍ\";s:11:\"englishName\";s:6:\"Faatir\";s:22:\"englishNameTranslation\";s:14:\"The Originator\";s:14:\"revelationType\";s:6:\"Meccan\";s:13:\"numberOfAyahs\";i:45;s:5:\"ayahs\";a:45:{i:0;a:9:{s:6:\"number\";i:3661;s:4:\"text\";s:194:\"Louange à Allah, Créateur des cieux et de la terre, qui a fait des Anges des messagers dotés de deux, trois ou quatre ailes. Il ajoute à la création ce qu\'Il veut, car Allah est Omnipotent.\";s:13:\"numberInSurah\";i:1;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:434;s:4:\"ruku\";i:376;s:11:\"hizbQuarter\";i:174;s:5:\"sajda\";b:0;}i:1;a:9:{s:6:\"number\";i:3662;s:4:\"text\";s:188:\"Ce qu\'Allah accorde en miséricorde aux gens, il n\'est personne à pouvoir le retenir. Et ce qu\'Il retient, il n\'est personne à le relâcher après Lui. Et c\'est Lui le Puissant, le Sage.\";s:13:\"numberInSurah\";i:2;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:434;s:4:\"ruku\";i:376;s:11:\"hizbQuarter\";i:174;s:5:\"sajda\";b:0;}i:2;a:9:{s:6:\"number\";i:3663;s:4:\"text\";s:246:\"O hommes! Rappelez-vous le bienfait d\'Allah sur vous: existe-t-il en dehors d\'Allah, un créateur qui du ciel et de la terre vous attribue votre subsistance? Point de divinité à part Lui! Comment pouvez-vous vous détourner [de cette vérité]?\";s:13:\"numberInSurah\";i:3;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:434;s:4:\"ruku\";i:376;s:11:\"hizbQuarter\";i:174;s:5:\"sajda\";b:0;}i:3;a:9:{s:6:\"number\";i:3664;s:4:\"text\";s:129:\"Et s\'ils te traitent de menteur, certes on a traité de menteurs des Messagers avant toi. Vers Allah cependant, tout est ramené.\";s:13:\"numberInSurah\";i:4;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:435;s:4:\"ruku\";i:376;s:11:\"hizbQuarter\";i:174;s:5:\"sajda\";b:0;}i:4;a:9:{s:6:\"number\";i:3665;s:4:\"text\";s:160:\"O hommes! La promesse d\'Allah est vérité. Ne laissez pas la vie présente vous tromper, et que le grand trompeur (Satan) ne vous trompe pas à propos d\'Allah!\";s:13:\"numberInSurah\";i:5;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:435;s:4:\"ruku\";i:376;s:11:\"hizbQuarter\";i:174;s:5:\"sajda\";b:0;}i:5;a:9:{s:6:\"number\";i:3666;s:4:\"text\";s:143:\"Le Diable est pour vous un ennemi. Prenez-le donc pour ennemi. Il ne fait qu\'appeler ses partisans pour qu\'ils soient des gens de la Fournaise.\";s:13:\"numberInSurah\";i:6;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:435;s:4:\"ruku\";i:376;s:11:\"hizbQuarter\";i:174;s:5:\"sajda\";b:0;}i:6;a:9:{s:6:\"number\";i:3667;s:4:\"text\";s:153:\"Ceux qui ont mécru auront un dur châtiment, tandis que ceux qui croient et accomplissent les bonnes œuvres auront un pardon et une grosse récompense.\";s:13:\"numberInSurah\";i:7;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:435;s:4:\"ruku\";i:376;s:11:\"hizbQuarter\";i:174;s:5:\"sajda\";b:0;}i:7;a:9:{s:6:\"number\";i:3668;s:4:\"text\";s:257:\"Eh quoi! Celui à qui on a enjolivé sa mauvaise action au point qu\'il la voit belle...? - Mais Allah égare qui Il veut, et guide qui Il veut - Que ton âme ne se répande donc pas en regrets pour eux: Allah est Parfaitement Savant de ce qu\'ils fabriquent.\";s:13:\"numberInSurah\";i:8;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:435;s:4:\"ruku\";i:377;s:11:\"hizbQuarter\";i:174;s:5:\"sajda\";b:0;}i:8;a:9:{s:6:\"number\";i:3669;s:4:\"text\";s:208:\"Et c\'est Allah qui envoie les vents qui soulèvent un nuage que Nous poussons ensuite vers une contrée morte; puis, Nous redonnons la vie à la terre après sa mort. C\'est ainsi que se fera la Résurrection!\";s:13:\"numberInSurah\";i:9;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:435;s:4:\"ruku\";i:377;s:11:\"hizbQuarter\";i:174;s:5:\"sajda\";b:0;}i:9;a:9:{s:6:\"number\";i:3670;s:4:\"text\";s:310:\"Quiconque veut la puissance (qu\'il la cherche auprès d\'Allah) car la puissance tout entière est à Allah: vers Lui monte la bonne parole, et Il élève haut la bonne action. Et quand à ceux qui complotent de mauvaises actions, ils auront un dur châtiment. Cependant, leur stratagème est voué à l\'échec.\";s:13:\"numberInSurah\";i:10;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:435;s:4:\"ruku\";i:377;s:11:\"hizbQuarter\";i:174;s:5:\"sajda\";b:0;}i:10;a:9:{s:6:\"number\";i:3671;s:4:\"text\";s:290:\"Et Allah vous a créés de terre, puis d\'une goutte de sperme, Il vous a ensuite établis en couples. Nulle femelle ne porte ni ne met bas sans qu\'Il le sache. Et aucune existence n\'est prolongée ou abrégée sans que cela soit consigné dans un livre. Cela est vraiment facile pour Allah.\";s:13:\"numberInSurah\";i:11;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:435;s:4:\"ruku\";i:377;s:11:\"hizbQuarter\";i:174;s:5:\"sajda\";b:0;}i:11;a:9:{s:6:\"number\";i:3672;s:4:\"text\";s:379:\"Les deux mers ne sont pas identiques: [l\'eau de] celle-ci est potable, douce et agréable à boire, et celle-là est salée, amère. Cependant de chacune vous mangez une chair fraîche, et vous extrayez un ornement que vous portez. Et tu vois le vaisseau fendre l\'eau avec bruit, pour que vous cherchiez certains [des produits] de Sa grâce. Peut-être serez-vous reconnaissants!\";s:13:\"numberInSurah\";i:12;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:436;s:4:\"ruku\";i:377;s:11:\"hizbQuarter\";i:174;s:5:\"sajda\";b:0;}i:12;a:9:{s:6:\"number\";i:3673;s:4:\"text\";s:332:\"Il fait que la nuit pénètre le jour et que le jour pénètre la nuit. Et Il a soumis le soleil et la lune. Chacun d\'eux s\'achemine vers un terme fixé. Tel est Allah, votre Seigneur: à Lui appartient la royauté, tandis que ceux que vous invoquez, en dehors de Lui, ne sont même pas maîtres de la pellicule d\'un noyau de datte.\";s:13:\"numberInSurah\";i:13;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:436;s:4:\"ruku\";i:377;s:11:\"hizbQuarter\";i:174;s:5:\"sajda\";b:0;}i:13;a:9:{s:6:\"number\";i:3674;s:4:\"text\";s:255:\"Si vous les invoquez, ils n\'entendent pas votre invocation; et même s\'ils entendaient, ils ne sauraient vous répondre. Et le jour du Jugement ils vont nier votre association. Nul ne peut te donner des nouvelles comme Celui qui est parfaitement informé.\";s:13:\"numberInSurah\";i:14;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:436;s:4:\"ruku\";i:377;s:11:\"hizbQuarter\";i:174;s:5:\"sajda\";b:0;}i:14;a:9:{s:6:\"number\";i:3675;s:4:\"text\";s:131:\"O hommes, vous êtes les indigents ayant besoin d\'Allah, et c\'est Allah, Lui qui se dispense de tout et Il est Le Digne de louange.\";s:13:\"numberInSurah\";i:15;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:436;s:4:\"ruku\";i:378;s:11:\"hizbQuarter\";i:175;s:5:\"sajda\";b:0;}i:15;a:9:{s:6:\"number\";i:3676;s:4:\"text\";s:83:\"S\'Il voulait, Il vous ferait disparaître, et ferait surgir une nouvelle création.\";s:13:\"numberInSurah\";i:16;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:436;s:4:\"ruku\";i:378;s:11:\"hizbQuarter\";i:175;s:5:\"sajda\";b:0;}i:16;a:9:{s:6:\"number\";i:3677;s:4:\"text\";s:41:\"Et cela n\'est point difficile pour Allah.\";s:13:\"numberInSurah\";i:17;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:436;s:4:\"ruku\";i:378;s:11:\"hizbQuarter\";i:175;s:5:\"sajda\";b:0;}i:17;a:9:{s:6:\"number\";i:3678;s:4:\"text\";s:403:\"Or, personne ne portera le fardeau d\'autrui. Et si une âme surchargée [de péchés] appelle à l\'aide, rien de sa charge ne sera supporté par une autre même si c\'est un proche parent. Tu n\'avertis en fait, que ceux qui craignent leur Seigneur malgré qu\'ils ne Le voient pas, et qui accomplissent la Salât. Et quiconque se purifie ne se purifie que pour lui-même, et vers Allah est la destination.\";s:13:\"numberInSurah\";i:18;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:436;s:4:\"ruku\";i:378;s:11:\"hizbQuarter\";i:175;s:5:\"sajda\";b:0;}i:18;a:9:{s:6:\"number\";i:3679;s:4:\"text\";s:51:\"L\'aveugle et celui qui voit ne sont pas semblables,\";s:13:\"numberInSurah\";i:19;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:437;s:4:\"ruku\";i:378;s:11:\"hizbQuarter\";i:175;s:5:\"sajda\";b:0;}i:19;a:9:{s:6:\"number\";i:3680;s:4:\"text\";s:33:\"ni les ténèbres et la lumière,\";s:13:\"numberInSurah\";i:20;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:437;s:4:\"ruku\";i:378;s:11:\"hizbQuarter\";i:175;s:5:\"sajda\";b:0;}i:20;a:9:{s:6:\"number\";i:3681;s:4:\"text\";s:33:\"ni l\'ombre et la chaleur ardente.\";s:13:\"numberInSurah\";i:21;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:437;s:4:\"ruku\";i:378;s:11:\"hizbQuarter\";i:175;s:5:\"sajda\";b:0;}i:21;a:9:{s:6:\"number\";i:3682;s:4:\"text\";s:176:\"De même, ne sont pas semblables les vivants et les morts. Allah fait entendre qui Il veut, alors que toi [Muhammad], tu ne peux faire entendre ceux qui sont dans les tombeaux.\";s:13:\"numberInSurah\";i:22;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:437;s:4:\"ruku\";i:378;s:11:\"hizbQuarter\";i:175;s:5:\"sajda\";b:0;}i:22;a:9:{s:6:\"number\";i:3683;s:4:\"text\";s:26:\"Tu n\'es qu\'un avertisseur.\";s:13:\"numberInSurah\";i:23;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:437;s:4:\"ruku\";i:378;s:11:\"hizbQuarter\";i:175;s:5:\"sajda\";b:0;}i:23;a:9:{s:6:\"number\";i:3684;s:4:\"text\";s:137:\"Nous t\'avons envoyé avec la Vérité en tant qu\'annonciateur et avertisseur. Il n\'est pas une nation qui n\'ait déjà eu un avertisseur.\";s:13:\"numberInSurah\";i:24;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:437;s:4:\"ruku\";i:378;s:11:\"hizbQuarter\";i:175;s:5:\"sajda\";b:0;}i:24;a:9:{s:6:\"number\";i:3685;s:4:\"text\";s:205:\"Et s\'ils te traitent de menteur, eh bien, ceux d\'avant eux avaient traité (leurs Messagers) de menteurs, cependant que leurs Messagers leur avaient apporté les preuves, les Ecrits et le Livre illuminant.\";s:13:\"numberInSurah\";i:25;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:437;s:4:\"ruku\";i:378;s:11:\"hizbQuarter\";i:175;s:5:\"sajda\";b:0;}i:25;a:9:{s:6:\"number\";i:3686;s:4:\"text\";s:74:\"Puis J\'ai saisi ceux qui ont mécru. Et quelle réprobation fut la Mienne!\";s:13:\"numberInSurah\";i:26;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:437;s:4:\"ruku\";i:378;s:11:\"hizbQuarter\";i:175;s:5:\"sajda\";b:0;}i:26;a:9:{s:6:\"number\";i:3687;s:4:\"text\";s:243:\"N\'as-tu pas vu que, du ciel, Allah fait descendre l\'eau? Puis Nous en faisons sortir des fruits de couleurs différentes. Et dans les montagnes, il y a des sillons blancs et rouges, de couleurs différentes, et des roches excessivement noires.\";s:13:\"numberInSurah\";i:27;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:437;s:4:\"ruku\";i:379;s:11:\"hizbQuarter\";i:175;s:5:\"sajda\";b:0;}i:27;a:9:{s:6:\"number\";i:3688;s:4:\"text\";s:194:\"Il y a pareillement des couleurs différentes, parmi les hommes, les animaux, et les bestiaux. Parmi Ses serviteurs, seuls les savants craignent Allah. Allah est, certes, Puissant et Pardonneur.\";s:13:\"numberInSurah\";i:28;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:437;s:4:\"ruku\";i:379;s:11:\"hizbQuarter\";i:175;s:5:\"sajda\";b:0;}i:28;a:9:{s:6:\"number\";i:3689;s:4:\"text\";s:193:\"Ceux qui récitent le Livre d\'Allah, accomplissent la Salât, et dépensent, en secret et en public de ce que Nous leur avons attribué, espèrent ainsi faire un commerce qui ne périra jamais,\";s:13:\"numberInSurah\";i:29;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:437;s:4:\"ruku\";i:379;s:11:\"hizbQuarter\";i:175;s:5:\"sajda\";b:0;}i:29;a:9:{s:6:\"number\";i:3690;s:4:\"text\";s:107:\"afin [qu\'Allah] les récompense pleinement et leur ajoute de Sa grâce. Il est Pardonneur et Reconnaissant.\";s:13:\"numberInSurah\";i:30;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:437;s:4:\"ruku\";i:379;s:11:\"hizbQuarter\";i:175;s:5:\"sajda\";b:0;}i:30;a:9:{s:6:\"number\";i:3691;s:4:\"text\";s:168:\"Et ce que Nous t\'avons révélé du Livre est la Vérité confirmant ce qui l\'a précédé. Certes Allah est Parfaitement Connaisseur et Clairvoyant sur Ses serviteurs.\";s:13:\"numberInSurah\";i:31;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:438;s:4:\"ruku\";i:379;s:11:\"hizbQuarter\";i:175;s:5:\"sajda\";b:0;}i:31;a:9:{s:6:\"number\";i:3692;s:4:\"text\";s:307:\"Ensuite, Nous fîmes héritiers du Livre ceux de Nos serviteurs que Nous avons choisis. Il en est parmi eux qui font du tort à eux-mêmes, d\'autres qui se tiennent sur une voie moyenne, et d\'autres avec la permission d\'Allah devancent [tous les autres] par leurs bonnes actions; telle est la grâce infinie\";s:13:\"numberInSurah\";i:32;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:438;s:4:\"ruku\";i:379;s:11:\"hizbQuarter\";i:175;s:5:\"sajda\";b:0;}i:32;a:9:{s:6:\"number\";i:3693;s:4:\"text\";s:123:\"Les jardins d\'Eden où ils entreront, parés de bracelets en or ainsi que de perles; et là, leurs vêtements sont de soie.\";s:13:\"numberInSurah\";i:33;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:438;s:4:\"ruku\";i:379;s:11:\"hizbQuarter\";i:175;s:5:\"sajda\";b:0;}i:33;a:9:{s:6:\"number\";i:3694;s:4:\"text\";s:125:\"Et ils diront: «Louange à Allah qui a écarté de nous l\'affliction. Notre Seigneur est certes Pardonneur et Reconnaissant.\";s:13:\"numberInSurah\";i:34;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:438;s:4:\"ruku\";i:379;s:11:\"hizbQuarter\";i:175;s:5:\"sajda\";b:0;}i:34;a:9:{s:6:\"number\";i:3695;s:4:\"text\";s:136:\"C\'est Lui qui nous a installés, par Sa grâce, dans la Demeure de la stabilité, où nulle fatigue, nulle lassitude ne nous touchent».\";s:13:\"numberInSurah\";i:35;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:438;s:4:\"ruku\";i:379;s:11:\"hizbQuarter\";i:175;s:5:\"sajda\";b:0;}i:35;a:9:{s:6:\"number\";i:3696;s:4:\"text\";s:193:\"Et ceux qui ont mécru auront le feu de l\'Enfer: on ne les achève pas pour qu\'ils meurent; on ne leur allège rien de ses tourments. C\'est ainsi que Nous récompensons tout négateur obstiné.\";s:13:\"numberInSurah\";i:36;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:438;s:4:\"ruku\";i:379;s:11:\"hizbQuarter\";i:175;s:5:\"sajda\";b:0;}i:36;a:9:{s:6:\"number\";i:3697;s:4:\"text\";s:344:\"Et là, ils hurleront: «Seigneur, fais-nous sortir; nous ferons le bien, contrairement à ce que nous faisions». «Ne vous avons-Nous pas donné une vie assez longue pour que celui qui réfléchit réfléchisse? L\'avertisseur, cependant, vous était venu. Et bien, goûtez (votre punition). Car pour les injustes, il n\'y a pas de secoureur».\";s:13:\"numberInSurah\";i:37;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:438;s:4:\"ruku\";i:379;s:11:\"hizbQuarter\";i:175;s:5:\"sajda\";b:0;}i:37;a:9:{s:6:\"number\";i:3698;s:4:\"text\";s:97:\"Allah connaît l\'Inconnaissable dans les cieux et la terre. Il connaît le contenu des poitrines.\";s:13:\"numberInSurah\";i:38;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:438;s:4:\"ruku\";i:380;s:11:\"hizbQuarter\";i:175;s:5:\"sajda\";b:0;}i:38;a:9:{s:6:\"number\";i:3699;s:4:\"text\";s:242:\"C\'est Lui qui a fait de vous des successeurs sur terre. Quiconque mécroit, sa mécréance retombera sur lui. Leur mécréance n\'ajoute aux mécréants qu\'opprobre auprès de leur Seigneur. Leur mécréance n\'ajoute que perte aux mécréants.\";s:13:\"numberInSurah\";i:39;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:439;s:4:\"ruku\";i:380;s:11:\"hizbQuarter\";i:175;s:5:\"sajda\";b:0;}i:39;a:9:{s:6:\"number\";i:3700;s:4:\"text\";s:347:\"Dis: «Voyez-vous vos associés que vous invoquez en dehors d\'Allah? Montrez-moi ce qu\'ils ont créé de la terre. Ont-ils été associés à la création des cieux? Ou leur avons-Nous apporté un Livre qui contienne des preuves [pour ce qu\'ils font?]» Non! Mais ce n\'est qu\'en tromperie que les injustes se font des promesses les uns aux autres.\";s:13:\"numberInSurah\";i:40;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:439;s:4:\"ruku\";i:380;s:11:\"hizbQuarter\";i:175;s:5:\"sajda\";b:0;}i:40;a:9:{s:6:\"number\";i:3701;s:4:\"text\";s:169:\"Allah retient les cieux et la terre pour qu\'ils ne s\'affaissent pas. Et s\'ils s\'affaissaient, nul autre après Lui ne pourra les retenir. Il est Indulgent et Pardonneur.\";s:13:\"numberInSurah\";i:41;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:439;s:4:\"ruku\";i:380;s:11:\"hizbQuarter\";i:176;s:5:\"sajda\";b:0;}i:41;a:9:{s:6:\"number\";i:3702;s:4:\"text\";s:249:\"Et ils ont juré solennellement par Allah, que si un avertisseur leur venait, ils seraient certes mieux guidés que n\'importe quelle autre communauté. Puis, quand un avertisseur (Muhammad) leur est venu, cela n\'a fait qu\'accroître leur répulsion,\";s:13:\"numberInSurah\";i:42;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:439;s:4:\"ruku\";i:380;s:11:\"hizbQuarter\";i:176;s:5:\"sajda\";b:0;}i:42;a:9:{s:6:\"number\";i:3703;s:4:\"text\";s:300:\"par orgueil sur terre et par manœuvre perfide. Cependant, la manœuvre perfide n\'enveloppe que ses propres auteurs. Attendent-ils donc un autre sort que celui des Anciens? Or, jamais tu ne trouveras de changement dans la règle d\'Allah et jamais tu ne trouveras de déviation dans la règle d\'Allah.\";s:13:\"numberInSurah\";i:43;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:439;s:4:\"ruku\";i:380;s:11:\"hizbQuarter\";i:176;s:5:\"sajda\";b:0;}i:43;a:9:{s:6:\"number\";i:3704;s:4:\"text\";s:260:\"N\'ont-ils donc jamais parcouru la terre pour voir ce qu\'il est advenu de ceux qui vécurent avant eux et qui étaient plus puissants qu\'eux? Et rien, dans les cieux ni sur terre ne saurait réduire l\'autorité d\'Allah. Car Il est certes Omniscient, Omnipotent.\";s:13:\"numberInSurah\";i:44;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:439;s:4:\"ruku\";i:380;s:11:\"hizbQuarter\";i:176;s:5:\"sajda\";b:0;}i:44;a:9:{s:6:\"number\";i:3705;s:4:\"text\";s:287:\"Et si Allah s\'en prenait aux gens pour ce qu\'ils acquièrent, Il ne laisserait à la surface [de la terre] aucun être vivant. Mais Il leur donne un délai jusqu\'à un terme fixé. Puis quand leur terme viendra... (Il se saisira d\'eux) car Allah est Très Clairvoyant sur Ses serviteurs.\";s:13:\"numberInSurah\";i:45;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:440;s:4:\"ruku\";i:380;s:11:\"hizbQuarter\";i:176;s:5:\"sajda\";b:0;}}s:7:\"edition\";a:7:{s:10:\"identifier\";s:13:\"fr.hamidullah\";s:8:\"language\";s:2:\"fr\";s:4:\"name\";s:10:\"Hamidullah\";s:11:\"englishName\";s:19:\"Muhammad Hamidullah\";s:6:\"format\";s:4:\"text\";s:4:\"type\";s:11:\"translation\";s:9:\"direction\";s:3:\"ltr\";}}', 1794581369),
('quranapp-cache-surah_36_ar.uthmani', 'a:8:{s:6:\"number\";i:36;s:4:\"name\";s:21:\"سُورَةُ يسٓ\";s:11:\"englishName\";s:6:\"Yaseen\";s:22:\"englishNameTranslation\";s:6:\"Yaseen\";s:14:\"revelationType\";s:6:\"Meccan\";s:13:\"numberOfAyahs\";i:83;s:5:\"ayahs\";a:83:{i:0;a:9:{s:6:\"number\";i:3706;s:4:\"text\";s:83:\"بِسۡمِ ٱللَّهِ ٱلرَّحۡمَـٰنِ ٱلرَّحِیمِ یسۤ\n\";s:13:\"numberInSurah\";i:1;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:440;s:4:\"ruku\";i:381;s:11:\"hizbQuarter\";i:176;s:5:\"sajda\";b:0;}i:1;a:9:{s:6:\"number\";i:3707;s:4:\"text\";s:50:\"وَٱلۡقُرۡءَانِ ٱلۡحَكِیمِ\n\";s:13:\"numberInSurah\";i:2;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:440;s:4:\"ruku\";i:381;s:11:\"hizbQuarter\";i:176;s:5:\"sajda\";b:0;}i:2;a:9:{s:6:\"number\";i:3708;s:4:\"text\";s:57:\"إِنَّكَ لَمِنَ ٱلۡمُرۡسَلِینَ\n\";s:13:\"numberInSurah\";i:3;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:440;s:4:\"ruku\";i:381;s:11:\"hizbQuarter\";i:176;s:5:\"sajda\";b:0;}i:3;a:9:{s:6:\"number\";i:3709;s:4:\"text\";s:61:\"عَلَىٰ صِرَ ٰ⁠طࣲ مُّسۡتَقِیمࣲ\n\";s:13:\"numberInSurah\";i:4;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:440;s:4:\"ruku\";i:381;s:11:\"hizbQuarter\";i:176;s:5:\"sajda\";b:0;}i:4;a:9:{s:6:\"number\";i:3710;s:4:\"text\";s:59:\"تَنزِیلَ ٱلۡعَزِیزِ ٱلرَّحِیمِ\n\";s:13:\"numberInSurah\";i:5;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:440;s:4:\"ruku\";i:381;s:11:\"hizbQuarter\";i:176;s:5:\"sajda\";b:0;}i:5;a:9:{s:6:\"number\";i:3711;s:4:\"text\";s:124:\"لِتُنذِرَ قَوۡمࣰا مَّاۤ أُنذِرَ ءَابَاۤؤُهُمۡ فَهُمۡ غَـٰفِلُونَ\n\";s:13:\"numberInSurah\";i:6;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:440;s:4:\"ruku\";i:381;s:11:\"hizbQuarter\";i:176;s:5:\"sajda\";b:0;}i:6;a:9:{s:6:\"number\";i:3712;s:4:\"text\";s:126:\"لَقَدۡ حَقَّ ٱلۡقَوۡلُ عَلَىٰۤ أَكۡثَرِهِمۡ فَهُمۡ لَا یُؤۡمِنُونَ\n\";s:13:\"numberInSurah\";i:7;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:440;s:4:\"ruku\";i:381;s:11:\"hizbQuarter\";i:176;s:5:\"sajda\";b:0;}i:7;a:9:{s:6:\"number\";i:3713;s:4:\"text\";s:179:\"إِنَّا جَعَلۡنَا فِیۤ أَعۡنَـٰقِهِمۡ أَغۡلَـٰلࣰا فَهِیَ إِلَى ٱلۡأَذۡقَانِ فَهُم مُّقۡمَحُونَ\n\";s:13:\"numberInSurah\";i:8;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:440;s:4:\"ruku\";i:381;s:11:\"hizbQuarter\";i:176;s:5:\"sajda\";b:0;}i:8;a:9:{s:6:\"number\";i:3714;s:4:\"text\";s:210:\"وَجَعَلۡنَا مِنۢ بَیۡنِ أَیۡدِیهِمۡ سَدࣰّا وَمِنۡ خَلۡفِهِمۡ سَدࣰّا فَأَغۡشَیۡنَـٰهُمۡ فَهُمۡ لَا یُبۡصِرُونَ\n\";s:13:\"numberInSurah\";i:9;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:440;s:4:\"ruku\";i:381;s:11:\"hizbQuarter\";i:176;s:5:\"sajda\";b:0;}i:9;a:9:{s:6:\"number\";i:3715;s:4:\"text\";s:144:\"وَسَوَاۤءٌ عَلَیۡهِمۡ ءَأَنذَرۡتَهُمۡ أَمۡ لَمۡ تُنذِرۡهُمۡ لَا یُؤۡمِنُونَ\n\";s:13:\"numberInSurah\";i:10;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:440;s:4:\"ruku\";i:381;s:11:\"hizbQuarter\";i:176;s:5:\"sajda\";b:0;}i:10;a:9:{s:6:\"number\";i:3716;s:4:\"text\";s:228:\"إِنَّمَا تُنذِرُ مَنِ ٱتَّبَعَ ٱلذِّكۡرَ وَخَشِیَ ٱلرَّحۡمَـٰنَ بِٱلۡغَیۡبِۖ فَبَشِّرۡهُ بِمَغۡفِرَةࣲ وَأَجۡرࣲ كَرِیمٍ\n\";s:13:\"numberInSurah\";i:11;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:440;s:4:\"ruku\";i:381;s:11:\"hizbQuarter\";i:176;s:5:\"sajda\";b:0;}i:11;a:9:{s:6:\"number\";i:3717;s:4:\"text\";s:244:\"إِنَّا نَحۡنُ نُحۡیِ ٱلۡمَوۡتَىٰ وَنَكۡتُبُ مَا قَدَّمُوا۟ وَءَاثَـٰرَهُمۡۚ وَكُلَّ شَیۡءٍ أَحۡصَیۡنَـٰهُ فِیۤ إِمَامࣲ مُّبِینࣲ\n\";s:13:\"numberInSurah\";i:12;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:440;s:4:\"ruku\";i:381;s:11:\"hizbQuarter\";i:176;s:5:\"sajda\";b:0;}i:12;a:9:{s:6:\"number\";i:3718;s:4:\"text\";s:148:\"وَٱضۡرِبۡ لَهُم مَّثَلًا أَصۡحَـٰبَ ٱلۡقَرۡیَةِ إِذۡ جَاۤءَهَا ٱلۡمُرۡسَلُونَ\n\";s:13:\"numberInSurah\";i:13;s:3:\"juz\";i:22;s:6:\"manzil\";i:5;s:4:\"page\";i:441;s:4:\"ruku\";i:382;s:11:\"hizbQuarter\";i:176;s:5:\"sajda\";b:0;}i:13;a:9:{s:6:\"number\";i:3719;s:4:\"text\";s:232:\"إِذۡ أَرۡسَلۡنَاۤ إِلَیۡهِمُ ٱثۡنَیۡنِ فَكَذَّبُوهُمَا فَعَزَّزۡنَا بِثَالِثࣲ فَقَالُوۤا۟ إِنَّاۤ إِلَیۡكُم مُّرۡسَلُونَ\n\";s:13:\"numberI