('quranapp-cache-surah_37_ar.uthmani', 'a:8:{s:6:\"number\";i:37;s:4:\"name\";s:39:\"سُورَةُ الصَّافَّاتِ\";s:11:\"englishName\";s:11:\"As-Saaffaat\";s:22:\"englishNameTranslation\";s:23:\"Those drawn up in Ranks\";s:14:\"revelationType\";s:6:\"Meccan\";s:13:\"numberOfAyahs\";i:182;s:5:\"ayahs\";a:182:{i:0;a:9:{s:6:\"number\";i:3789;s:4:\"text\";s:125:\"بِسۡمِ ٱللَّهِ ٱلرَّحۡمَـٰنِ ٱلرَّحِیمِ وَٱلصَّـٰۤفَّـٰتِ صَفࣰّا\n\";s:13:\"numberInSurah\";i:1;s:3:\"juz\";i:23;s:6:\"manzil\";i:6;s:4:\"page\";i:446;s:4:\"ruku\";i:386;s:11:\"hizbQuarter\";i:178;s:5:\"sajda\";b:0;}i:1;a:9:{s:6:\"number\";i:3790;s:4:\"text\";s:59:\"فَٱلزَّ ٰ⁠جِرَ ٰ⁠تِ زَجۡرࣰا\n\";s:13:\"numberInSurah\";i:2;s:3:\"juz\";i:23;s:6:\"manzil\";i:6;s:4:\"page\";i:446;s:4:\"ruku\";i:386;s:11:\"hizbQuarter\";i:178;s:5:\"sajda\";b:0;}i:2;a:9:{s:6:\"number\";i:3791;s:4:\"text\";s:50:\"فَٱلتَّـٰلِیَـٰتِ ذِكۡرًا\n\";s:13:\"numberInSurah\";i:3;s:3:\"juz\";i:23;s:6:\"manzil\";i:6;s:4:\"page\";i:446;s:4:\"ruku\";i:386;s:11:\"hizbQuarter\";i:178;s:5:\"sajda\";b:0;}i:3;a:9:{s:6:\"number\";i:3792;s:4:\"text\";s:62:\"إِنَّ إِلَـٰهَكُمۡ لَوَ ٰ⁠حِدࣱ\n\";s:13:\"numberInSurah\";i:4;s:3:\"juz\";i:23;s:6:\"manzil\";i:6;s:4:\"page\";i:446;s:4:\"ruku\";i:386;s:11:\"hizbQuarter\";i:178;s:5:\"sajda\";b:0;}i:4;a:9:{s:6:\"number\";i:3793;s:4:\"text\";s:147:\"رَّبُّ ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِ وَمَا بَیۡنَهُمَا وَرَبُّ ٱلۡمَشَـٰرِقِ\n\";s:13:\"numberInSurah\";i:5;s:3:\"juz\";i:23;s:6:\"manzil\";i:6;s:4:\"page\";i:446;s:4:\"ruku\";i:386;s:11:\"hizbQuarter\";i:178;s:5:\"sajda\";b:0;}i:5;a:9:{s:6:\"number\";i:3794;s:4:\"text\";s:120:\"إِنَّا زَیَّنَّا ٱلسَّمَاۤءَ ٱلدُّنۡیَا بِزِینَةٍ ٱلۡكَوَاكِبِ\n\";s:13:\"numberInSurah\";i:6;s:3:\"juz\";i:23;s:6:\"manzil\";i:6;s:4:\"page\";i:446;s:4:\"ruku\";i:386;s:11:\"hizbQuarter\";i:178;s:5:\"sajda\";b:0;}i:6;a:9:{s:6:\"number\";i:3795;s:4:\"text\";s:80:\"وَحِفۡظࣰا مِّن كُلِّ شَیۡطَـٰنࣲ مَّارِدࣲ\n\";s:13:\"numberInSurah\";i:7;s:3:\"juz\";i:23;s:6:\"manzil\";i:6;s:4:\"page\";i:446;s:4:\"ruku\";i