('quranapp-cache-surah_38_ar.uthmani', 'a:8:{s:6:\"number\";i:38;s:4:\"name\";s:19:\"سُورَةُ صٓ\";s:11:\"englishName\";s:4:\"Saad\";s:22:\"englishNameTranslation\";s:15:\"The letter Saad\";s:14:\"revelationType\";s:6:\"Meccan\";s:13:\"numberOfAyahs\";i:88;s:5:\"ayahs\";a:88:{i:0;a:9:{s:6:\"number\";i:3971;s:4:\"text\";s:138:\"بِسۡمِ ٱللَّهِ ٱلرَّحۡمَـٰنِ ٱلرَّحِیمِ صۤۚ وَٱلۡقُرۡءَانِ ذِی ٱلذِّكۡرِ\n\";s:13:\"numberInSurah\";i:1;s:3:\"juz\";i:23;s:6:\"manzil\";i:6;s:4:\"page\";i:453;s:4:\"ruku\";i:391;s:11:\"hizbQuarter\";i:181;s:5:\"sajda\";b:0;}i:1;a:9:{s:6:\"number\";i:3972;s:4:\"text\";s:90:\"بَلِ ٱلَّذِینَ كَفَرُوا۟ فِی عِزَّةࣲ وَشِقَاقࣲ\n\";s:13:\"numberInSurah\";i:2;s:3:\"juz\";i:23;s:6:\"manzil\";i:6;s:4:\"page\";i:453;s:4:\"ruku\";i:391;s:11:\"hizbQuarter\";i:181;s:5:\"sajda\";b:0;}i:2;a:9:{s:6:\"number\";i:3973;s:4:\"text\";s:146:\"كَمۡ أَهۡلَكۡنَا مِن قَبۡلِهِم مِّن قَرۡنࣲ فَنَادَوا۟ وَّلَاتَ حِینَ مَنَاصࣲ\n\";s:13:\"numberInSurah\";i:3;s:3:\"juz\";i:23;s:6:\"manzil\";i:6;s:4:\"page\";i:453;s:4:\"ruku\";i:391;s:11:\"hizbQuarter\";i:181;s:5:\"sajda\";b:0;}i:3;a:9:{s:6:\"number\";i:3974;s:4:\"text\";s:184:\"وَعَجِبُوۤا۟ أَن جَاۤءَهُم مُّنذِرࣱ مِّنۡهُمۡۖ وَقَالَ ٱلۡكَـٰفِرُونَ هَـٰذَا سَـٰحِرࣱ كَذَّابٌ\n\";s:13:\"numberInSurah\";i:4;s:3:\"juz\";i:23;s:6:\"manzil\";i:6;s:4:\"page\";i:453;s:4:\"ruku\";i:391;s:11:\"hizbQuarter\";i:181;s:5:\"sajda\";b:0;}i:4;a:9:{s:6:\"number\";i:3975;s:4:\"text\";s:148:\"أَجَعَلَ ٱلۡـَٔالِهَةَ إِلَـٰهࣰا وَ ٰ⁠حِدًاۖ إِنَّ هَـٰذَا لَشَیۡءٌ عُجَابࣱ\n\";s:13:\"numberInSurah\";i:5;s:3:\"juz\";i:23;s:6:\"manzil\";i:6;s:4:\"page\";i:453;s:4:\"ruku\";i:391;s:11:\"hizbQuarter\";i:181;s:5:\"sajda\";b:0;}i:5;a:9:{s:6:\"number\";i:3976;s:4:\"text\";s:211:\"وَٱنطَلَقَ ٱلۡمَلَأُ مِنۡهُمۡ أَنِ ٱمۡشُوا۟ وَٱصۡبِرُوا۟ عَلَىٰۤ ءَالِهَتِكُمۡۖ إِنَّ هَـٰذَا لَشَیۡءࣱ یُرَادُ\n\";s:13:\"numberInSurah\";i:6;s:3:\"juz\";i:23;s:6:\"manzil\";i:6;s:4:\"page\";i:453;s:4:\"ruku\";i:391;s:11:\"hizbQuarter\";i:181;s:5:\"sajda\";b:0;}i:6;a:9:{s:6:\"number\";i:3977;s:4:\"text\";s:162:\"مَا سَمِعۡنَا بِهَـٰذَا فِی ٱلۡمِلَّةِ ٱلۡـَٔاخِرَةِ إِنۡ هَـٰذَاۤ إِلَّا ٱخۡتِلَـٰقٌ\n\";s:13:\"numberInSurah\";i:7;s:3:\"juz\";i:23;s:6:\"manzil\";i:6;s:4:\"page\";i:453;s:4:\"ruku\";i:391;s:11:\"hizbQuarter\";i:181;s:5:\"sajda\";b:0;}i:7;a:9:{s:6:\"number\";i:3978;s:4:\"text\";s:206:\"أَءُنزِلَ عَلَیۡهِ ٱلذِّكۡرُ مِنۢ بَیۡنِنَاۚ بَلۡ هُمۡ فِی شَكࣲّ مِّن ذِكۡرِیۚ بَل لَّمَّا یَذُوقُوا۟ عَذَابِ\n\";s:13:\"numberInSurah\";i:8;s:3:\"juz\";i:23;s:6:\"manzil\";i:6;s:4:\"page\";i:453;s:4:\"ruku\";i:391;s:11:\"hizbQuarter\";i:181;s:5:\"sajda\";b:0;}i:8;a:9:{s:6:\"number\";i:3979;s:4:\"text\";s:127:\"أَمۡ عِندَهُمۡ خَزَاۤىِٕنُ رَحۡمَةِ رَبِّكَ ٱلۡعَزِیزِ ٱلۡوَهَّابِ\n\";s:13:\"numberInSurah\";i:9;s:3:\"juz\";i:23;s:6:\"manzil\";i:6;s:4:\"page\";i:453;s:4:\"ruku\";i:391;s:11:\"hizbQuarter\";i:181;s:5:\"sajda\";b:0;}i:9;a:9:{s:6:\"number\";i:3980;s:4:\"text\";s:194:\"أَمۡ لَهُم مُّلۡكُ ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِ وَمَا بَیۡنَهُمَاۖ فَلۡیَرۡتَقُوا۟ فِی ٱلۡأَسۡبَـٰبِ\n\";s:13:\"numberInSurah\";i:10;s:3:\"juz\";i:23;s:6:\"manzil\";i:6;s:4:\"page\";i:453;s:4:\"ruku\";i:391;s:11:\"hizbQuarter\";i:181;s:5:\"sajda\";b:0;}i:10;a:9:{s:6:\"number\";i:3981;s:4:\"text\";s:96:\"جُندࣱ مَّا هُنَالِكَ مَهۡزُومࣱ مِّنَ ٱلۡأَحۡزَابِ\n\";s:13:\"numberInSurah\";i:11;s:3:\"juz\";i:23;s:6:\"manzil\";i:6;s:4:\"page\";i:453;s:4:\"ruku\";i:391;s:11:\"hizbQuarter\";i:181;s:5:\"sajda\";b:0;}i:11;a:9:{s:6:\"number\";i:3982;s:4:\"text\";s:138:\"كَذَّبَتۡ قَبۡلَهُمۡ قَوۡمُ نُوحࣲ وَعَادࣱ وَفِرۡعَوۡنُ ذُو ٱلۡأَوۡتَادِ\n\";s:13:\"numberInSurah\";i:12;s:3:\"juz\";i:23;s:6:\"manzil\";i:6;s:4:\"page\";i:453;s:4:\"ruku\";i:391;s:11:\"hizbQuarter\";i:181;s:5:\"sajda\";b:0;}i:12;a:9:{s:6:\"number\";i:3983;s:4:\"text\";s:152:\"وَثَمُودُ وَقَوۡمُ لُوطࣲ وَأَصۡحَـٰبُ لۡـَٔیۡكَةِۚ أُو۟لَـٰۤىِٕكَ ٱلۡأَحۡزَابُ\n\";s:13:\"numberInSurah\";i:13;s:3:\"juz\";i:23;s:6:\"manzil\";i:6;s:4:\"page\";i:453;s:4:\"ruku\";i:391;s:11:\"hizbQuarter\";i:181;s:5:\"sajda\";b:0;}i:13;a:9:{s:6:\"number\";i:3984;s:4:\"text\";s:95:\"إِن كُلٌّ إِلَّا كَذَّبَ ٱلرُّسُلَ فَحَقَّ عِقَابِ\n\";s:13:\"numberInSurah\";i:14;s:3:\"juz\";i:23;s:6:\"manzil\";i:6;s:4:\"page\";i:453;s:4:\"ruku\";i:391;s:11:\"hizbQuarter\";i:181;s:5:\"sajda\";b:0;}i:14;a:9:{s:6:\"number\";i:3985;s:4:\"text\";s:153:\"وَمَا یَنظُرُ هَـٰۤؤُلَاۤءِ إِلَّا صَیۡحَةࣰ وَ ٰ⁠حِدَةࣰ مَّا لَهَا مِن فَوَاقࣲ\n\";s:13:\"numberInSurah\";i:15;s:3:\"juz\";i:23;s:6:\"manzil\";i:6;s:4:\"page\";i:453;s:4:\"ruku\";i:392;s:11:\"hizbQuarter\";i:181;s:5:\"sajda\";b:0;}i:15;a:9:{s:6:\"number\";i:3986;s:4:\"text\";s:128:\"وَقَالُوا۟ رَبَّنَا عَجِّل لَّنَا قِطَّنَا قَبۡلَ یَوۡمِ ٱلۡحِسَابِ\n\";s:13:\"numberInSurah\";i:16;s:3:\"juz\";i:23;s:6:\"manzil\";i:6;s:4:\"page\";i:453;s:4:\"ruku\";i:392;s:11:\"hizbQuarter\";i:181;s:5:\"sajda\";b:0;}i:16;a:9:{s:6:\"number\";i:3987;s:4:\"text\";s:175:\"ٱصۡبِرۡ عَلَىٰ مَا یَقُولُونَ وَٱذۡكُرۡ عَبۡدَنَا دَاوُۥدَ ذَا ٱلۡأَیۡدِۖ إِنَّهُۥۤ أَوَّابٌ\n\";s:13:\"numberInSurah\";i:17;s:3:\"juz\";i:23;s:6:\"manzil\";i:6;s:4:\"page\";i:454;s:4:\"ruku\";i:392;s:11:\"hizbQuarter\";i:181;s:5:\"sajda\";b:0;}i:17;a:9:{s:6:\"number\";i:3988;s:4:\"text\";s:147:\"إِنَّا سَخَّرۡنَا ٱلۡجِبَالَ مَعَهُۥ یُسَبِّحۡنَ بِٱلۡعَشِیِّ وَٱلۡإِشۡرَاقِ\n\";s:13:\"numberInSurah\";i:18;s:3:\"juz\";i:23;s:6:\"manzil\";i:6;s:4:\"page\";i:454;s:4:\"ruku\";i:392;s:11:\"hizbQuarter\";i:181;s:5:\"sajda\";b:0;}i:18;a:9:{s:6:\"number\";i:3989;s:4:\"text\";s:94:\"وَٱلطَّیۡرَ مَحۡشُورَةࣰۖ كُلࣱّ لَّهُۥۤ أَوَّابࣱ\n\";s:13:\"numberInSurah\";i:19;s:3:\"juz\";i:23;s:6:\"manzil\";i:6;s:4:\"page\";i:454;s:4:\"ruku\";i:392;s:11:\"hizbQuarter\";i:181;s:5:\"sajda\";b:0;}i:19;a:9:{s:6:\"number\";i:3990;s:4:\"text\";s:134:\"وَشَدَدۡنَا مُلۡكَهُۥ وَءَاتَیۡنَـٰهُ ٱلۡحِكۡمَةَ وَفَصۡلَ ٱلۡخِطَابِ\n\";s:13:\"numberInSurah\";i:20;s:3:\"juz\";i:23;s:6:\"manzil\";i:6;s:4:\"page\";i:454;s:4:\"ruku\";i:392;s:11:\"hizbQuarter\";i:181;s:5:\"sajda\";b:0;}i:20;a:9:{s:6:\"number\";i:3991;s:4:\"text\";s:128:\"۞ وَهَلۡ أَتَىٰكَ نَبَؤُا۟ ٱلۡخَصۡمِ إِذۡ تَسَوَّرُوا۟ ٱلۡمِحۡرَابَ\n\";s:13:\"numberInSurah\";i:21;s:3:\"juz\";i:23;s:6:\"manzil\";i:6;s:4:\"page\";i:454;s:4:\"ruku\";i:392;s:11:\"hizbQuarter\";i:182;s:5:\"sajda\";b:0;}i:21;a:9:{s:6:\"number\";i:3992;s:4:\"text\";s:376:\"إِذۡ دَخَلُوا۟ عَلَىٰ دَاوُۥدَ فَفَزِعَ مِنۡهُمۡۖ قَالُوا۟ لَا تَخَفۡۖ خَصۡمَانِ بَغَىٰ بَعۡضُنَا عَلَىٰ بَعۡضࣲ فَٱحۡكُم بَیۡنَنَا بِٱلۡحَقِّ وَلَا تُشۡطِطۡ وَٱهۡدِنَاۤ إِلَىٰ سَوَاۤءِ ٱلصِّرَ ٰ⁠طِ\n\";s:13:\"numberInSurah\";i:22;s:3:\"juz\";i:23;s:6:\"manzil\";i:6;s:4:\"page\";i:454;s:4:\"ruku\";i:392;s:11:\"hizbQuarter\";i:182;s:5:\"sajda\";b:0;}i:22;a:9:{s:6:\"number\";i:3993;s:4:\"text\";s:255:\"إِنَّ هَـٰذَاۤ أَخِی لَهُۥ تِسۡعࣱ وَتِسۡعُونَ نَعۡجَةࣰ وَلِیَ نَعۡجَةࣱ وَ ٰ⁠حِدَةࣱ فَقَالَ أَكۡفِلۡنِیهَا وَعَزَّنِی فِی ٱلۡخِطَابِ\n\";s:13:\"numberInSurah\";i:23;s:3:\"juz\";i:23;s:6:\"manzil\";i:6;s:4:\"page\";i:454;s:4:\"ruku\";i:392;s:11:\"hizbQuarter\";i:182;s:5:\"sajda\";b:0;}i:23;a:9:{s:6:\"number\";i:3994;s:4:\"text\";s:572:\"قَالَ لَقَدۡ ظَلَمَكَ بِسُؤَالِ نَعۡجَتِكَ إِلَىٰ نِعَاجِهِۦۖ وَإِنَّ كَثِیرࣰا مِّنَ ٱلۡخُلَطَاۤءِ لَیَبۡغِی بَعۡضُهُمۡ عَلَىٰ بَعۡضٍ إِلَّا ٱلَّذِینَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ وَقَلِیلࣱ مَّا هُمۡۗ وَظَنَّ دَاوُۥدُ أَنَّمَا فَتَنَّـٰهُ فَٱسۡتَغۡفَرَ رَبَّهُۥ وَخَرَّ رَاكِعࣰا وَأَنَابَ ۩\n\";s:13:\"numberInSurah\";i:24;s:3:\"juz\";i:23;s:6:\"manzil\";i:6;s:4:\"page\";i:454;s:4:\"ruku\";i:392;s:11:\"hizbQuarter\";i:182;s:5:\"sajda\";a:3:{s:2:\"id\";i:11;s:11:\"recommended\";b:1;s:10:\"obligatory\";b:0;}}i:24;a:9:{s:6:\"number\";i:3995;s:4:\"text\";s:156:\"فَغَفَرۡنَا لَهُۥ ذَ ٰ⁠لِكَۖ وَإِنَّ لَهُۥ عِندَنَا لَزُلۡفَىٰ وَحُسۡنَ مَـَٔابࣲ\n\";s:13:\"numberInSurah\";i:25;s:3:\"juz\";i:23;s:6:\"manzil\";i:6;s:4:\"page\";i:454;s:4:\"ruku\";i:392;s:11:\"hizbQuarter\";i:182;s:5:\"sajda\";b:0;}i:25;a:9:{s:6:\"number\";i:3996;s:4:\"text\";s:482:\"یَـٰدَاوُۥدُ إِنَّا جَعَلۡنَـٰكَ خَلِیفَةࣰ فِی ٱلۡأَرۡضِ فَٱحۡكُم بَیۡنَ ٱلنَّاسِ بِٱلۡحَقِّ وَلَا تَتَّبِعِ ٱلۡهَوَىٰ فَیُضِلَّكَ عَن سَبِیلِ ٱللَّهِۚ إِنَّ ٱلَّذِینَ یَضِلُّونَ عَن سَبِیلِ ٱللَّهِ لَهُمۡ عَذَابࣱ شَدِیدُۢ بِمَا نَسُوا۟ یَوۡمَ ٱلۡحِسَابِ\n\";s:13:\"numberInSurah\";i:26;s:3:\"juz\";i:23;s:6:\"manzil\";i:6;s:4:\"page\";i:454;s:4:\"ruku\";i:392;s:11:\"hizbQuarter\";i:182;s:5:\"sajda\";b:0;}i:26;a:9:{s:6:\"number\";i:3997;s:4:\"text\";s:290:\"وَمَا خَلَقۡنَا ٱلسَّمَاۤءَ وَٱلۡأَرۡضَ وَمَا بَیۡنَهُمَا بَـٰطِلࣰاۚ ذَ ٰ⁠لِكَ ظَنُّ ٱلَّذِینَ كَفَرُوا۟ۚ فَوَیۡلࣱ لِّلَّذِینَ كَفَرُوا۟ مِنَ ٱلنَّارِ\n\";s:13:\"numberInSurah\";i:27;s:3:\"juz\";i:23;s:6:\"manzil\";i:6;s:4:\"page\";i:455;s:4:\"ruku\";i:393;s:11:\"hizbQuarter\";i:182;s:5:\"sajda\";b:0;}i:27;a:9:{s:6:\"number\";i:3998;s:4:\"text\";s:259:\"أَمۡ نَجۡعَلُ ٱلَّذِینَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ كَٱلۡمُفۡسِدِینَ فِی ٱلۡأَرۡضِ أَمۡ نَجۡعَلُ ٱلۡمُتَّقِینَ كَٱلۡفُجَّارِ\n\";s:13:\"numberInSurah\";i:28;s:3:\"juz\";i:23;s:6:\"manzil\";i:6;s:4:\"page\";i:455;s:4:\"ruku\";i:393;s:11:\"hizbQuarter\";i:182;s:5:\"sajda\";b:0;}i:28;a:9:{s:6:\"number\";i:3999;s:4:\"text\";s:220:\"كِتَـٰبٌ أَنزَلۡنَـٰهُ إِلَیۡكَ مُبَـٰرَكࣱ لِّیَدَّبَّرُوۤا۟ ءَایَـٰتِهِۦ وَلِیَتَذَكَّرَ أُو۟لُوا۟ ٱلۡأَلۡبَـٰبِ\n\";s:13:\"numberInSurah\";i:29;s:3:\"juz\";i:23;s:6:\"manzil\";i:6;s:4:\"page\";i:455;s:4:\"ruku\";i:393;s:11:\"hizbQuarter\";i:182;s:5:\"sajda\";b:0;}i:29;a:9:{s:6:\"number\";i:4000;s:4:\"text\";s:139:\"وَوَهَبۡنَا لِدَاوُۥدَ سُلَیۡمَـٰنَۚ نِعۡمَ ٱلۡعَبۡدُ إِنَّهُۥۤ أَوَّابٌ\n\";s:13:\"numberInSurah\";i:30;s:3:\"juz\";i:23;s:6:\"manzil\";i:6;s:4:\"page\";i:455;s:4:\"ruku\";i:393;s:11:\"hizbQuarter\";i:182;s:5:\"sajda\";b:0;}i:30;a:9:{s:6:\"number\";i:4001;s:4:\"text\";s:116:\"إِذۡ عُرِضَ عَلَیۡهِ بِٱلۡعَشِیِّ ٱلصَّـٰفِنَـٰتُ ٱلۡجِیَادُ\n\";s:13:\"numberInSurah\";i:31;s:3:\"juz\";i:23;s:6:\"manzil\";i:6;s:4:\"page\";i:455;s:4:\"ruku\";i:393;s:11:\"hizbQuarter\";i:182;s:5:\"sajda\";b:0;}i:31;a:9:{s:6:\"number\";i:4002;s:4:\"text\";s:173:\"فَقَالَ إِنِّیۤ أَحۡبَبۡتُ حُبَّ ٱلۡخَیۡرِ عَن ذِكۡرِ رَبِّی حَتَّىٰ تَوَارَتۡ بِٱلۡحِجَابِ\n\";s:13:\"numberInSurah\";i:32;s:3:\"juz\";i:23;s:6:\"manzil\";i:6;s:4:\"page\