('quranapp-cache-surah_43_ar.uthmani', 'a:8:{s:6:\"number\";i:43;s:4:\"name\";s:37:\"سُورَةُ الزُّخۡرُفِ\";s:11:\"englishName\";s:10:\"Az-Zukhruf\";s:22:\"englishNameTranslation\";s:17:\"Ornaments of gold\";s:14:\"revelationType\";s:6:\"Meccan\";s:13:\"numberOfAyahs\";i:89;s:5:\"ayahs\";a:89:{i:0;a:9:{s:6:\"number\";i:4326;s:4:\"text\";s:83:\"بِسۡمِ ٱللَّهِ ٱلرَّحۡمَـٰنِ ٱلرَّحِیمِ حمۤ\n\";s:13:\"numberInSurah\";i:1;s:3:\"juz\";i:25;s:6:\"manzil\";i:6;s:4:\"page\";i:489;s:4:\"ruku\";i:424;s:11:\"hizbQuarter\";i:196;s:5:\"sajda\";b:0;}i:1;a:9:{s:6:\"number\";i:4327;s:4:\"text\";s:48:\"وَٱلۡكِتَـٰبِ ٱلۡمُبِینِ\n\";s:13:\"numberInSurah\";i:2;s:3:\"juz\";i:25;s:6:\"manzil\";i:6;s:4:\"page\";i:489;s:4:\"ruku\";i:424;s:11:\"hizbQuarter\";i:196;s:5:\"sajda\";b:0;}i:2;a:9:{s:6:\"number\";i:4328;s:4:\"text\";s:138:\"إِنَّا جَعَلۡنَـٰهُ قُرۡءَ ٰ⁠ نًا عَرَبِیࣰّا لَّعَلَّكُمۡ تَعۡقِلُونَ\n\";s:13:\"numberInSurah\";i:3;s:3:\"juz\";i:25;s:6:\"manzil\";i:6;s:4:\"page\";i:489;s:4:\"ruku\";i:424;s:11:\"hizbQuarter\";i:196;s:5:\"sajda\";b:0;}i:3;a:9:{s:6:\"number\";i:4329;s:4:\"text\";s:117:\"وَإِنَّهُۥ فِیۤ أُمِّ ٱلۡكِتَـٰبِ لَدَیۡنَا لَعَلِیٌّ حَكِیمٌ\n\";s:13:\"numberInSurah\";i:4;s:3:\"juz\";i:25;s:6:\"manzil\";i:6;s:4:\"page\";i:489;s:4:\"ruku\";i:424;s:11:\"hizbQuarter\";i:196;s:5:\"sajda\";b:0;}i:4;a:9:{s:6:\"number\";i:4330;s:4:\"text\";s:137:\"أَفَنَضۡرِبُ عَنكُمُ ٱلذِّكۡرَ صَفۡحًا أَن كُنتُمۡ قَوۡمࣰا مُّسۡرِفِینَ\n\";s:13:\"numberInSurah\";i:5;s:3:\"juz\";i:25;s:6:\"manzil\";i:6;s:4:\"page\";i:489;s:4:\"ruku\";i:424;s:11:\"hizbQuarter\";i:196;s:5:\"sajda\";b:0;}i:5;a:9:{s:6:\"number\";i:4331;s:4:\"text\";s:95:\"وَكَمۡ أَرۡسَلۡنَا مِن نَّبِیࣲّ فِی ٱلۡأَوَّلِینَ\n\";s:13:\"numberInSurah\";i:6;s:3:\"juz\";i:25;s:6:\"manzil\";i:6;s:4:\"page\";i:489;s:4:\"ruku\";i:424;s:11:\"hizbQuarter\";i:196;s:5:\"sajda\";b:0;}i:6;a:9:{s:6:\"number\";i:4332;s:4:\"text\";s:130:\"وَمَا یَأۡتِیهِم مِّن نَّبِیٍّ إِلَّا كَانُوا۟ بِهِۦ یَسۡتَهۡزِءُونَ\n\";s:13:\"numberInSurah\";i:7;s:3:\"juz\";i:25;s:6:\"manzil\";i:6;s:4:\"page\";i:489;s:4:\"ruku\";i:424;s:11:\"hizbQuarter\";i:196;s:5:\"sajda\";b:0;}i:7;a:9:{s:6:\"number\";i:4333;s:4:\"text\";s:132:\"فَأَهۡلَكۡنَاۤ أَشَدَّ مِنۡهُم بَطۡشࣰا وَمَضَىٰ مَثَلُ ٱلۡأَوَّلِینَ\n\";s:13:\"numberInSurah\";i:8;s:3:\"juz\";i:25;s:6:\"manzil\";i:6;s:4:\"page\";i:489;s:4:\"ruku\";i:424;s:11:\"hizbQuarter\";i:196;s:5:\"sajda\";b:0;}i:8;a:9:{s:6:\"number\";i:4334;s:4:\"text\";s:212:\"وَلَىِٕن سَأَلۡتَهُم مَّنۡ خَلَقَ ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضَ لَیَقُولُنَّ خَلَقَهُنَّ ٱلۡعَزِیزُ ٱلۡعَلِیمُ\n\";s:13:\"numberInSurah\";i:9;s:3:\"juz\";i:25;s:6:\"manzil\";i:6;s:4:\"page\";i:489;s:4:\"ruku\";i:424;s:11:\"hizbQuarter\";i:196;s:5:\"sajda\";b:0;}i:9;a:9:{s:6:\"number\";i:4335;s:4:\"text\";s:183:\"ٱلَّذِی جَعَلَ لَكُمُ ٱلۡأَرۡضَ مَهۡدࣰا وَجَعَلَ لَكُمۡ فِیهَا سُبُلࣰا لَّعَلَّكُمۡ تَهۡتَدُونَ\n\";s:13:\"numberInSurah\";i:10;s:3:\"juz\";i:25;s:6:\"manzil\";i:6;s:4:\"page\";i:489;s:4:\"ruku\";i:424;s:11:\"hizbQuarter\";i:196;s:5:\"sajda\";b:0;}i:10;a:9:{s:6:\"number\";i:4336;s:4:\"text\";s:221:\"وَٱلَّذِی نَزَّلَ مِنَ ٱلسَّمَاۤءِ مَاۤءَۢ بِقَدَرࣲ فَأَنشَرۡنَا بِهِۦ بَلۡدَةࣰ مَّیۡتࣰاۚ كَذَ ٰ⁠لِكَ تُخۡرَجُونَ\n\";s:13:\"numberInSurah\";i:11;s:3:\"juz\";i:25;s:6:\"manzil\";i:6;s:4:\"page\";i:490;s:4:\"ruku\";i:424;s:11:\"hizbQuarter\";i:196;s:5:\"sajda\";b:0;}i:11;a:9:{s:6:\"number\";i:4337;s:4:\"text\";s:199:\"وَٱلَّذِی خَلَقَ ٱلۡأَزۡوَ ٰ⁠جَ كُلَّهَا وَجَعَلَ لَكُم مِّنَ ٱلۡفُلۡكِ وَٱلۡأَنۡعَـٰمِ مَا تَرۡكَبُونَ\n\";s:13:\"numberInSurah\";i:12;s:3:\"juz\";i:25;s:6:\"manzil\";i:6;s:4:\"page\";i:490;s:4:\"ruku\";i:424;s:11:\"hizbQuarter\";i:196;s:5:\"sajda\";b:0;}i:12;a:9:{s:6:\"number\";i:4338;s:4:\"text\";s:346:\"لِتَسۡتَوُۥا۟ عَلَىٰ ظُهُورِهِۦ ثُمَّ تَذۡكُرُوا۟ نِعۡمَةَ رَبِّكُمۡ إِذَا ٱسۡتَوَیۡتُمۡ عَلَیۡهِ وَتَقُولُوا۟ سُبۡحَـٰنَ ٱلَّذِی سَخَّرَ لَنَا هَـٰذَا وَمَا كُنَّا لَهُۥ مُقۡرِنِینَ\n\";s:13:\"numberInSurah\";i:13;s:3:\"juz\";i:25;s:6:\"manzil\";i:6;s:4:\"page\";i:490;s:4:\"ruku\";i:424;s:11:\"hizbQuarter\";i:196;s:5:\"sajda\";