('quranapp-cache-surah_53_fr.hamidullah', 'a:8:{s:6:\"number\";i:53;s:4:\"name\";s:33:\"سُورَةُ النَّجۡمِ\";s:11:\"englishName\";s:7:\"An-Najm\";s:22:\"englishNameTranslation\";s:8:\"The Star\";s:14:\"revelationType\";s:6:\"Meccan\";s:13:\"numberOfAyahs\";i:62;s:5:\"ayahs\";a:62:{i:0;a:9:{s:6:\"number\";i:4785;s:4:\"text\";s:29:\"Par l\'étoile à son déclin!\";s:13:\"numberInSurah\";i:1;s:3:\"juz\";i:27;s:6:\"manzil\";i:7;s:4:\"page\";i:526;s:4:\"ruku\";i:460;s:11:\"hizbQuarter\";i:210;s:5:\"sajda\";b:0;}i:1;a:9:{s:6:\"number\";i:4786;s:4:\"text\";s:70:\"Votre compagnon ne s\'est pas égaré et n\'a pas été induit en erreur\";s:13:\"numberInSurah\";i:2;s:3:\"juz\";i:27;s:6:\"manzil\";i:7;s:4:\"page\";i:526;s:4:\"ruku\";i:460;s:11:\"hizbQuarter\";i:210;s:5:\"sajda\";b:0;}i:2;a:9:{s:6:\"number\";i:4787;s:4:\"text\";s:50:\"et il ne prononce rien sous l\'effet de la passion;\";s:13:\"numberInSurah\";i:3;s:3:\"juz\";i:27;s:6:\"manzil\";i:7;s:4:\"page\";i:526;s:4:\"ruku\";i:460;s:11:\"hizbQuarter\";i:210;s:5:\"sajda\";b:0;}i:3;a:9:{s:6:\"number\";i:4788;s:4:\"text\";s:52:\"ce n\'est rien d\'autre qu\'une révélation inspirée.\";s:13:\"numberInSurah\";i:4;s:3:\"juz\";i:27;s:6:\"manzil\";i:7;s:4:\"page\";i:526;s:4:\"ruku\";i:460;s:11:\"hizbQuarter\";i:210;s:5:\"sajda\";b:0;}i:4;a:9:{s:6:\"number\";i:4789;s:4:\"text\";s:61:\"Que lui a enseigné [l\'Ange Gabriel] à la force prodigieuse,\";s:13:\"numberInSurah\";i:5;s:3:\"juz\";i:27;s:6:\"manzil\";i:7;s:4:\"page\";i:526;s:4:\"ruku\";i:460;s:11:\"hizbQuarter\";i:210;s:5:\"sajda\";b:0;}i:5;a:9:{s:6:\"number\";i:4790;s:4:\"text\";s:83:\"doué de sagacité; c\'est alors qu\'il se montra sous sa forme réelle [angélique],\";s:13:\"numberInSurah\";i:6;s:3:\"juz\";i:27;s:6:\"manzil\";i:7;s:4:\"page\";i:526;s:4:\"ruku\";i:460;s:11:\"hizbQuarter\";i:210;s:5:\"sajda\";b:0;}i:6;a:9:{s:6:\"number\";i:4791;s:4:\"text\";s:48:\"alors qu\'il se trouvait à l\'horizon supérieur.\";s:13:\"numberInSurah\";i:7;s:3:\"juz\";i:27;s:6:\"manzil\";i:7;s:4:\"page\";i:526;s:4:\"ruku\";i:460;s:11:\"hizbQuarter\";i:210;s:5:\"sajda\";b:0;}i:7;a:9:{s:6:\"number\";i:4792;s:4:\"text\";s:50:\"Puis il se rapprocha et descendit encore plus bas,\";s:13:\"numberInSurah\";i:8;s:3:\"juz\";i:27;s:6:\"manzil\";i:7;s:4:\"page\";i:526;s:4:\"ruku\";i:460;s:11:\"hizbQuarter\";i:210;s:5:\"sajda\";b:0;}i:8;a:9:{s:6:\"number\";i:4793;s:4:\"text\";s:52:\"et fut à deux portées d\'arc, ou plus près encore.\";s:13:\"numberInSurah\";i:9;s:3:\"juz\";i:27;s:6:\"manzil\";i:7;s:4:\"page\";i:526;s:4:\"ruku\";i:460;s:11:\"hizbQuarter\";i:210;s:5:\"sajda\";b:0;}i:9;a:9:{s:6:\"number\";i:4794;s:4:\"text\";s:47:\"Il révéla à Son serviteur ce qu\'Il révéla.\";s:13:\"numberInSurah\";i:10;s:3:\"juz\";i:27;s:6:\"manzil\";i:7;s:4:\"page\";i:526;s:4:\"ruku\";i:460;s:11:\"hizbQuarter\";i:210;s:5:\"sajda\";b:0;}i:10;a:9:{s:6:\"number\";i:4795;s:4:\"text\";s:40:\"Le cœur n\'a pas menti en ce qu\'il a vu.\";s:13:\"numberInSurah\";i:11;s:3:\"juz\";i:27;s:6:\"manzil\";i:7;s:4:\"page\";i:526;s:4:\"ruku\";i:460;s:11:\"hizbQuarter\";i:210;s:5:\"sajda\";b:0;}i:11;a:9:{s:6:\"number\";i:4796;s:4:\"text\";s:38:\"Lui contestez-vous donc ce qu\'il voit?\";s:13:\"numberInSurah\";i:12;s:3:\"juz\";i:27;s:6:\"manzil\";i:7;s:4:\"page\";i:526;s:4:\"ruku\";i:460;s:11:\"hizbQuarter\";i:210;s:5:\"sajda\";b:0;}i:12;a:9:{s:6:\"number\";i:4797;s:4:\"text\";s:46:\"Il l\'a pourtant vu, lors d\'une autre descente,\";s:13:\"numberInSurah\";i:13;s:3:\"juz\";i:27;s:6:\"manzil\";i:7;s:4:\"page\";i:526;s:4:\"ruku\";i:460;s:11:\"hizbQuarter\";i:210;s:5:\"sajda\";b:0;}i:13;a:9:{s:6:\"number\";i:4798;s:4:\"text\";s:31:\"près de la Sidrat-ul-Muntahâ,\";s:13:\"numberInSurah\";i:14;s:3:\"juz\";i:27;s:6:\"manzil\";i:7;s:4:\"page\";i:526;s:4:\"ruku\";i:460;s:11:\"hizbQuarter\";i:210;s:5:\"sajda\";b:0;}i:14;a:9:{s:6:\"number\";i:4799;s:4:\"text\";s:42:\"près d\'elle se trouve le jardin de Ma\'w?:\";s:13:\"numberInSurah\";i:15;s:3:\"juz\";i:27;s:6:\"manzil\";i:7;s:4:\"page\";i:526;s:4:\"ruku\";i:460;s:11:\"hizbQuarter\";i:210;s:5:\"sajda\";b:0;}i:15;a:9:{s:6:\"number\";i:4800;s:4:\"text\";s:60:\"au moment où le lotus était couvert de ce qui le couvrait.\";s:13:\"numberInSurah\";i:16;s:3:\"juz\";i:27;s:6:\"manzil\";i:7;s:4:\"page\";i:526;s:4:\"ruku\";i:460;s:11:\"hizbQuarter\";i:210;s:5:\"sajda\";b:0;}i:16;a:9:{s:6:\"number\";i:4801;s:4:\"text\";s:54:\"la vue n\'a nullement dévié ni outrepassé la mesure.\";s:13:\"numberInSurah\";i:17;s:3:\"juz\";i:27;s:6:\"manzil\";i:7;s:4:\"page\";i:526;s:4:\"ruku\";i:460;s:11:\"hizbQuarter\";i:210;s:5:\"sajda\";b:0;}i:17;a:9:{s:6:\"number\";i:4802;s:4:\"text\";s:62:\"Il a bien vu certaines des grandes merveilles de son Seigneur.\";s:13:\"numberInSurah\";i:18;s:3:\"juz\";i:27;s:6:\"manzil\";i:7;s:4:\"page\";i:526;s:4:\"ruku\";i:460;s:11:\"hizbQuarter\";i:210;s:5:\"sajda\";b:0;}i:18;a:9:{s:6:\"number\";i:4803;s:4:\"text\";s:51:\"Que vous en semble [des divinités], Lât et Uuzzâ\";s:13:\"numberInSurah\";i:19;s:3:\"juz\";i:27;s:6:\"manzil\";i:7;s:4:\"page\";i:526;s:4:\"ruku\";i:460;s:11:\"hizbQuarter\";i:210;s:5:\"sajda\";b:0;}i:19;a:9:{s:6:\"number\";i:4804;s:4:\"text\";s:41:\"ainsi que Manât, cette troisième autre?\";s:13:\"numberInSurah\";i:20;s:3:\"juz\";i:27;s:6:\"manzil\";i:7;s:4:\"page\";i:526;s:4:\"ruku\";i:460;s:11:\"hizbQuarter\";i:210;s:5:\"sajda\";b:0;}i:20;a:9:{s:6:\"number\";i:4805;s:4:\"text\";s:46:\"Sera-ce à vous le garçon et à Lui la fille?\";s:13:\"numberInSurah\";i:21;s:3:\"juz\";i:27;s:6:\"manzil\";i:7;s:4:\"page\";i:526;s:4:\"ruku\";i:460;s:11:\"hizbQuarter\";i:210;s:5:\"sajda\";b:0;}i:21;a:9:{s:6:\"number\";i:4806;s:4:\"text\";s:35:\"Que voilà donc un partage injuste!\";s:13:\"numberInSurah\";i:22;s:3:\"juz\";i:27;s:6:\"manzil\";i:7;s:4:\"page\";i:526;s:4:\"ruku\";i:460;s:11:\"hizbQuarter\";i:210;s:5:\"sajda\";b:0;}i:22;a:9:{s:6:\"number\";i:4807;s:4:\"text\";s:246:\"Ce ne sont que des noms que vous avez inventés, vous et vos ancêtres. Allah n\'a fait descendre aucune preuve à leur sujet. Ils ne suivent que la conjecture et les passions de [leurs] âmes, alors que la guidée leur est venue de leur Seigneur.\";s:13:\"numberInSurah\";i:23;s:3:\"juz\";i:27;s:6:\"manzil\";i:7;s:4:\"page\";i:526;s:4:\"ruku\";i:460;s:11:\"hizbQuarter\";i:210;s:5:\"sajda\";b:0;}i:23;a:9:{s:6:\"number\";i:4808;s:4:\"text\";s:48:\"Ou bien l\'homme aura-t-il tout ce qu\'il désire?\";s:13:\"numberInSurah\";i:24;s:3:\"juz\";i:27;s:6:\"manzil\";i:7;s:4:\"page\";i:526;s:4:\"ruku\";i:460;s:11:\"hizbQuarter\";i:210;s:5:\"sajda\";b:0;}i:24;a:9:{s:6:\"number\";i:4809;s:4:\"text\";s:56:\"A Allah appartiennent la vie future et la vie d\'ici-bas.\";s:13:\"numberInSurah\";i:25;s:3:\"juz\";i:27;s:6:\"manzil\";i:7;s:4:\"page\";i:526;s:4:\"ruku\";i:460;s:11:\"hizbQuarter\";i:210;s:5:\"sajda\";b:0;}i:25;a:9:{s:6:\"number\";i:4810;s:4:\"text\";s:148:\"Et que d\'Anges dans les cieux dont l\'intercession ne sert à rien, sinon qu\'après qu\'Allah l\'aura permis, en faveur de qui Il veut et qu\'Il agrée.\";s:13:\"numberInSurah\";i:26;s:3:\"juz\";i:27;s:6:\"manzil\";i:7;s:4:\"page\";i:526;s:4:\"ruku\";i:461;s:11:\"hizbQuarter\";i:211;s:5:\"sajda\";b:0;}i:26;a:9:{s:6:\"number\";i:4811;s:4:\"text\";s:75:\"Ceux qui ne croient pas en l\'au-delà donnent aux Anges des noms de femmes,\";s:13:\"numberInSurah\";i:27;s:3:\"juz\";i:27;s:6:\"manzil\";i:7;s:4:\"page\";i:527;s:4:\"ruku\";i:461;s:11:\"hizbQuarter\";i:211;s:5:\"sajda\";b:0;}i:27;a:9:{s:6:\"number\";i:4812;s:4:\"text\";s:131:\"alors qu\'ils n\'en ont aucune science: ils ne suivent que la conjecture, alors que la conjecture ne sert à rien contre la vérité.\";s:13:\"numberInSurah\";i:28;s:3:\"juz\";i:27;s:6:\"manzil\";i:7;s:4:\"page\";i:527;s:4:\"ruku\";i:461;s:11:\"hizbQuarter\";i:211;s:5:\"sajda\";b:0;}i:28;a:9:{s:6:\"number\";i:4813;s:4:\"text\";s:99:\"Ecarte-toi donc, de celui qui tourne le dos à Notre rappel et qui ne désire que la vie présente.\";s:13:\"numberInSurah\";i:29;s:3:\"juz\";i:27;s:6:\"manzil\";i:7;s:4:\"page\";i:527;s:4:\"ruku\";i:461;s:11:\"hizbQuarter\";i:211;s:5:\"sajda\";b:0;}i:29;a:9:{s:6:\"number\";i:4814;s:4:\"text\";s:163:\"Voilà toute la portée de leur savoir. Certes ton Seigneur connaît parfaitement celui qui s\'égare de Son chemin et Il connaît parfaitement qui est bien guidé.\";s:13:\"numberInSurah\";i:30;s:3:\"juz\";i:27;s:6:\"manzil\";i:7;s:4:\"page\";i:527;s:4:\"ruku\";i:461;s:11:\"hizbQuarter\";i:211;s:5:\"sajda\";b:0;}i:30;a:9:{s:6:\"number\";i:4815;s:4:\"text\";s:197:\"A Allah appartient ce qui est dans les cieux et sur la terre afin qu\'Il rétribue ceux qui font le mal selon ce qu\'ils œuvrent, et récompense ceux qui font le bien par la meilleure [récompense],\";s:13:\"numberInSurah\";i:31;s:3:\"juz\";i:27;s:6:\"manzil\";i:7;s:4:\"page\";i:527;s:4:\"ruku\";i:461;s:11:\"hizbQuarter\";i:211;s:5:\"sajda\";b:0;}i:31;a:9:{s:6:\"number\";i:4816;s:4:\"text\";s:402:\"ceux qui évitent les plus grands péchés ainsi que les turpitudes et [qui ne commettent] que des fautes légères. Certes, le pardon de Ton Seigneur est immense. C\'est Lui qui vous connaît le mieux quand Il vous a produits de terre, et aussi quand vous étiez des embryons dans les ventres de vos mères. Ne vantez pas vous-mêmes votre pureté; c\'est Lui qui connaît mieux ceux qui [Le] craignent.\";s:13:\"numberInSurah\";i:32;s:3:\"juz\";i:27;s:6:\"manzil\";i:7;s:4:\"page\";i:527;s:4:\"ruku\";i:461;s:11:\"hizbQuarter\";i:211;s:5:\"sajda\";b:0;}i:32;a:9:{s:6:\"number\";i:4817;s:4:\"text\";s:35:\"Vois-tu celui qui s\'est détourné,\";s:13:\"numberInSurah\";i:33;s:3:\"juz\";i:27;s:6:\"manzil\";i:7;s:4:\"page\";i:527;s:4:\"ruku\";i:462;s:11:\"hizbQuarter\";i:211;s:5:\"sajda\";b:0;}i:33;a:9:{s:6:\"number\";i:4818;s:4:\"text\";s:46:\"donné peu et a [finalement] cessé de donner?\";s:13:\"numberInSurah\";i:34;s:3:\"juz\";i:27;s:6:\"manzil\";i:7;s:4:\"page\";i:527;s:4:\"ruku\";i:462;s:11:\"hizbQuarter\";i:211;s:5:\"sajda\";b:0;}i:34;a:9:{s:6:\"number\";i:4819;s:4:\"text\";s:63:\"Détient-il la science de l\'Inconnaissable en sorte qu\'il voit?\";s:13:\"numberInSurah\";i:35;s:3:\"juz\";i:27;s:6:\"manzil\";i:7;s:4:\"page\";i:527;s:4:\"ruku\";i:462;s:11:\"hizbQuarter\";i:211;s:5:\"sajda\";b:0;}i:35;a:9:{s:6:\"number\";i:4820;s:4:\"text\";s:71:\"Ne lui a-t-on pas annoncé ce qu\'il y avait dans les feuilles de Moïse\";s:13:\"numberInSurah\";i:36;s:3:\"juz\";i:27;s:6:\"manzil\";i:7;s:4:\"page\";i:527;s:4:\"ruku\";i:462;s:11:\"hizbQuarter\";i:211;s:5:\"sajda\";b:0;}i:36;a:9:{s:6:\"number\";i:4821;s:4:\"text\";s:72:\"et celles d\'Abraham qui a tenu parfaitement [sa promesse de transmettre]\";s:13:\"numberInSurah\";i:37;s:3:\"juz\";i:27;s:6:\"manzil\";i:7;s:4:\"page\";i:527;s:4:\"ruku\";i:462;s:11:\"hizbQuarter\";i:211;s:5:\"sajda\";b:0;}i:37;a:9:{s:6:\"number\";i:4822;s:4:\"text\";s:61:\"qu\'aucune [âme] ne portera le fardeau (le péché) d\'autrui,\";s:13:\"numberInSurah\";i:38;s:3:\"juz\";i:27;s:6:\"manzil\";i:7;s:4:\"page\";i:527;s:4:\"ruku\";i:462;s:11:\"hizbQuarter\";i:211;s:5:\"sajda\";b:0;}i:38;a:9:{s:6:\"number\";i:4823;s:4:\"text\";s:67:\"et qu\'en vérité, l\'homme n\'obtient que [le fruit] de ses efforts;\";s:13:\"numberInSurah\";i:39;s:3:\"juz\";i:27;s:6:\"manzil\";i:7;s:4:\"page\";i:527;s:4:\"ruku\";i:462;s:11:\"hizbQuarter\";i:211;s:5:\"sajda\";b:0;}i:39;a:9:{s:6:\"number\";i:4824;s:4:\"text\";s:74:\"et que son effort, en vérité, lui sera présenté (le jour du Jugement).\";s:13:\"numberInSurah\";i:40;s:3:\"juz\";i:27;s:6:\"manzil\";i:7;s:4:\"page\";i:527;s:4:\"ruku\";i:462;s:11:\"hizbQuarter\";i:211;s:5:\"sajda\";b:0;}i:40;a:9:{s:6:\"number\";i:4825;s:4:\"text\";s:43:\"Ensuite il en sera récompensé pleinement,\";s:13:\"numberInSurah\";i:41;s:3:\"juz\";i:27;s:6:\"manzil\";i:7;s:4:\"page\";i:527;s:4:\"ruku\";i:462;s:11:\"hizbQuarter\";i:211;s:5:\"sajda\";b:0;}i:41;a:9:{s:6:\"number\";i:4826;s:4:\"text\";s:52:\"et que tout aboutit, en vérité, vers ton Seigneur,\";s:13:\"numberInSurah\";i:42;s:3:\"juz\";i:27;s:6:\"manzil\";i:7;s:4:\"page\";i:527;s:4:\"ruku\";i:462;s:11:\"hizbQuarter\";i:211;s:5:\"sajda\";b:0;}i:42;a:9:{s:6:\"number\";i:4827;s:4:\"text\";s:55:\"et que c\'est Lui qui a fait rire et qui a fait pleurer,\";s:13:\"numberInSurah\";i:43;s:3:\"juz\";i:27;s:6:\"manzil\";i:7;s:4:\"page\";i:527;s:4:\"ruku\";i:462;s:11:\"hizbQuarter\";i:211;s:5:\"sajda\";b:0;}i:43;a:9:{s:6:\"number\";i:4828;s:4:\"text\";s:62:\"et que c\'est Lui qui a fait mourir et qui a ramené à la vie,\";s:13:\"numberInSurah\";i:44;s:3:\"juz\";i:27;s:6:\"manzil\";i:7;s:4:\"page\";i:527;s:4:\"ruku\";i:462;s:11:\"hizbQuarter\";i:211;s:5:\"sajda\";b:0;}i:44;a:9:{s:6:\"number\";i:4829;s:4:\"text\";s:83:\"et que c\'est Lui qui a crée les deux éléments de couple, le mâle et la femelle,\";s:13:\"numberInSurah\";i:45;s:3:\"juz\";i:27;s:6:\"manzil\";i:7;s:4:\"page\";i:528;s:4:\"ruku\";i:462;s:11:\"hizbQuarter\";i:211;s:5:\"sajda\";b:0;}i:45;a:9:{s:6:\"number\";i:4830;s:4:\"text\";s:48:\"d\'une goutte de sperme quand elle est éjaculée\";s:13:\"numberInSurah\";i:46;s:3:\"juz\";i:27;s:6:\"manzil\";i:7;s:4:\"page\";i:528;s:4:\"ruku\";i:462;s:11:\"hizbQuarter\";i:211;s:5:\"sajda\";b:0;}i:46;a:9:{s:6:\"number\";i:4831;s:4:\"text\";s:40:\"et que la seconde création Lui incombe,\";s:13:\"numberInSurah\";i:47;s:3:\"juz\";i:27;s:6:\"manzil\";i:7;s:4:\"page\";i:528;s:4:\"ruku\";i:462;s:11:\"hizbQuarter\";i:211;s:5:\"sajda\";b:0;}i:47;a:9:{s:6:\"number\";i:4832;s:4:\"text\";s:51:\"et c\'est Lui qui a enrichi et qui a fait acquérir.\";s:13:\"numberInSurah\";i:48;s:3:\"juz\";i:27;s:6:\"manzil\";i:7;s:4:\"page\";i:528;s:4:\"ruku\";i:462;s:11:\"hizbQuarter\";i:211;s:5:\"sajda\";b:0;}i:48;a:9:{s:6:\"number\";i:4833;s:4:\"text\";s:43:\"Et c\'est Lui qui est le Seigneur de Sirius,\";s:13:\"numberInSurah\";i:49;s:3:\"juz\";i:27;s:6:\"manzil\";i:7;s:4:\"page\";i:528;s:4:\"ruku\";i:462;s:11:\"hizbQuarter\";i:211;s:5:\"sajda\";b:0;}i:49;a:9:{s:6:\"number\";i:4834;s:4:\"text\";s:48:\"et c\'est Lui qui a fait périr les anciens \'Aad,\";s:13:\"numberInSurah\";i:50;s:3:\"juz\";i:27;s:6:\"manzil\";i:7;s:4:\"page\";i:528;s:4:\"ruku\";i:462;s:11:\"hizbQuarter\";i:211;s:5:\"sajda\";b:0;}i:50;a:9:{s:6:\"number\";i:4835;s:4:\"text\";s:58:\"ainsi que les Thamûd, et Il fit que rien n\'en subsistât,\";s:13:\"numberInSurah\";i:51;s:3:\"juz\";i:27;s:6:\"manzil\";i:7;s:4:\"page\";i:528;s:4:\"ruku\";i:462;s:11:\"hizbQuarter\";i:211;s:5:\"sajda\";b:0;}i:51;a:9:{s:6:\"number\";i:4836;s:4:\"text\";s:100:\"ainsi que le peuple de Noé antérieurement, car ils étaient encore plus injustes et plus violents,\";s:13:\"numberInSurah\";i:52;s:3:\"juz\";i:27;s:6:\"manzil\";i:7;s:4:\"page\";i:528;s:4:\"ruku\";i:462;s:11:\"hizbQuarter\";i:211;s:5:\"sajda\";b:0;}i:52;a:9:{s:6:\"number\";i:4837;s:4:\"text\";s:48:\"de même qu\'Il anéantit les villes renversées.\";s:13:\"numberInSurah\";i:53;s:3:\"juz\";i:27;s:6:\"manzil\";i:7;s:4:\"page\";i:528;s:4:\"ruku\";i:462;s:11:\"hizbQuarter\";i:211;s:5:\"sajda\";b:0;}i:53;a:9:{s:6:\"number\";i:4838;s:4:\"text\";s:45:\"Et les recouvrit de ce dont Il les recouvrit.\";s:13:\"numberInSurah\";i:54;s:3:\"juz\";i:27;s:6:\"manzil\";i:7;s:4:\"page\";i:528;s:4:\"ruku\";i:462;s:11:\"hizbQuarter\";i:211;s:5:\"sajda\";b:0;}i:54;a:9:{s:6:\"number\";i:4839;s:4:\"text\";s:59:\"Lequel donc des bienfaits de ton Seigneur mets-tu en doute?\";s:13:\"numberInSurah\";i:55;s:3:\"juz\";i:27;s:6:\"manzil\";i:7;s:4:\"page\";i:528;s:4:\"ruku\";i:462;s:11:\"hizbQuarter\";i:211;s:5:\"sajda\";b:0;}i:55;a:9:{s:6:\"number\";i:4840;s:4:\"text\";s:55:\"Voici un avertisseur analogue aux avertisseurs anciens:\";s:13:\"numberInSurah\";i:56;s:3:\"juz\";i:27;s:6:\"manzil\";i:7;s:4:\"page\";i:528;s:4:\"ruku\";i:462;s:11:\"hizbQuarter\";i:211;s:5:\"sajda\";b:0;}i:56;a:9:{s:6:\"number\";i:4841;s:4:\"text\";s:45:\"l\'Imminente (L\'heure du Jugement) s\'approche.\";s:13:\"numberInSurah\";i:57;s:3:\"juz\";i:27;s:6:\"manzil\";i:7;s:4:\"page\";i:528;s:4:\"ruku\";i:462;s:11:\"hizbQuarter\";i:211;s:5:\"sajda\";b:0;}i:57;a:9:{s:6:\"number\";i:4842;s:4:\"text\";s:52:\"Rien d\'autre en dehors d\'Allah ne peut la dévoiler.\";s:13:\"numberInSurah\";i:58;s:3:\"juz\";i:27;s:6:\"manzil\";i:7;s:4:\"page\";i:528;s:4:\"ruku\";i:462;s:11:\"hizbQuarter\";i:211;s:5:\"sajda\";b:0;}i:58;a:9:{s:6:\"number\";i:4843;s:4:\"text\";s:51:\"Quoi! vous étonnez-vous de ce discours (le Coran)?\";s:13:\"numberInSurah\";i:59;s:3:\"juz\";i:27;s:6:\"manzil\";i:7;s:4:\"page\";i:528;s:4:\"ruku\";i:462;s:11:\"hizbQuarter\";i:211;s:5:\"sajda\";b:0;}i:59;a:9:{s:6:\"number\";i:4844;s:4:\"text\";s:42:\"Et vous [en] riez et n\'[en] pleurez point?\";s:13:\"numberInSurah\";i:60;s:3:\"juz\";i:27;s:6:\"manzil\";i:7;s:4:\"page\";i:528;s:4:\"ruku\";i:462;s:11:\"hizbQuarter\";i:211;s:5:\"sajda\";b:0;}i:60;a:9:{s:6:\"number\";i:4845;s:4:\"text\";s:49:\"absorbés [que vous êtes] par votre distraction.\";s:13:\"numberInSurah\";i:61;s:3:\"juz\";i:27;s:6:\"manzil\";i:7;s:4:\"page\";i:528;s:4:\"ruku\";i:462;s:11:\"hizbQuarter\";i:211;s:5:\"sajda\";b:0;}i:61;a:9:{s:6:\"number\";i:4846;s:4:\"text\";s:43:\"Prosternez-vous donc à Allah et adorez-Le.\";s:13:\"numberInSurah\";i:62;s:3:\"juz\";i:27;s:6:\"manzil\";i:7;s:4:\"page\";i:528;s:4:\"ruku\";i:462;s:11:\"hizbQuarter\";i:211;s:5:\"sajda\";a:3:{s:2:\"id\";i:13;s:11:\"recommended\";b:0;s:10:\"obligatory\";b:1;}}}s:7:\"edition\";a:7:{s:10:\"identifier\";s:13:\"fr.hamidullah\";s:8:\"language\";s:2:\"fr\";s:4:\"name\";s:10:\"Hamidullah\";s:11:\"englishName\";s:19:\"Muhammad Hamidullah\";s:6:\"format\";s:4:\"text\";s:4:\"type\";s:11:\"translation\";s:9:\"direction\";s:3:\"ltr\";}}', 1794581386);
