('quranapp-cache-surah_62_ar.uthmani', 'a:8:{s:6:\"number\";i:62;s:4:\"name\";s:35:\"سُورَةُ الجُمُعَةِ\";s:11:\"englishName\";s:9:\"Al-Jumu\'a\";s:22:\"englishNameTranslation\";s:6:\"Friday\";s:14:\"revelationType\";s:7:\"Medinan\";s:13:\"numberOfAyahs\";i:11;s:5:\"ayahs\";a:11:{i:0;a:9:{s:6:\"number\";i:5178;s:4:\"text\";s:280:\"بِسۡمِ ٱللَّهِ ٱلرَّحۡمَـٰنِ ٱلرَّحِیمِ یُسَبِّحُ لِلَّهِ مَا فِی ٱلسَّمَـٰوَ ٰ⁠تِ وَمَا فِی ٱلۡأَرۡضِ ٱلۡمَلِكِ ٱلۡقُدُّوسِ ٱلۡعَزِیزِ ٱلۡحَكِیمِ\n\";s:13:\"numberInSurah\";i:1;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:553;s:4:\"ruku\";i:486;s:11:\"hizbQuarter\";i:221;s:5:\"sajda\";b:0;}i:1;a:9:{s:6:\"number\";i:5179;s:4:\"text\";s:382:\"هُوَ ٱلَّذِی بَعَثَ فِی ٱلۡأُمِّیِّـۧنَ رَسُولࣰا مِّنۡهُمۡ یَتۡلُوا۟ عَلَیۡهِمۡ ءَایَـٰتِهِۦ وَیُزَكِّیهِمۡ وَیُعَلِّمُهُمُ ٱلۡكِتَـٰبَ وَٱلۡحِكۡمَةَ وَإِن كَانُوا۟ مِن قَبۡلُ لَفِی ضَلَـٰلࣲ مُّبِینࣲ\n\";s:13:\"numberInSurah\";i:2;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:553;s:4:\"ruku\";i:486;s:11:\"hizbQuarter\";i:221;s:5:\"sajda\";b:0;}i:2;a:9:{s:6:\"number\";i:5180;s:4:\"text\";s:148:\"وَءَاخَرِینَ مِنۡهُمۡ لَمَّا یَلۡحَقُوا۟ بِهِمۡۚ وَهُوَ ٱلۡعَزِیزُ ٱلۡحَكِیمُ\n\";s:13:\"numberInSurah\";i:3;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:553;s:4:\"ruku\";i:486;s:11:\"hizbQuarter\";i:221;s:5:\"sajda\";b:0;}i:3;a:9:{s:6:\"number\";i:5181;s:4:\"text\";s:160:\"ذَ ٰ⁠لِكَ فَضۡلُ ٱللَّهِ یُؤۡتِیهِ مَن یَشَاۤءُۚ وَٱللَّهُ ذُو ٱلۡفَضۡلِ ٱلۡعَظِیمِ\n\";s:13:\"numberInSurah\";i:4;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:553;s:4:\"ruku\";i:486;s:11:\"hizbQuarter\";i:221;s:5:\"sajda\";b:0;}i:4;a:9:{s:6:\"number\";i:5182;s:4:\"text\";s:421:\"مَثَلُ ٱلَّذِینَ حُمِّلُوا۟ ٱلتَّوۡرَىٰةَ ثُمَّ لَمۡ یَحۡمِلُوهَا كَمَثَلِ ٱلۡحِمَارِ یَحۡمِلُ أَسۡفَارَۢاۚ بِئۡسَ مَثَلُ ٱلۡقَوۡمِ ٱلَّذِینَ كَذَّبُوا۟ بِـَٔایَـٰتِ ٱللَّهِۚ وَٱللَّهُ لَا یَهۡدِی ٱلۡقَوۡمَ ٱلظَّـٰلِمِینَ\n\";s:13:\"numberInSurah\";i:5;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:553;s:4:\"ruku\";i:486;s:11:\"hizbQuarter\";i:221;s:5:\"sajda\";b:0;}i:5;a:9:{s:6:\"number\";i:5183;s:4:\"text\";s:287:\"قُلۡ یَـٰۤأَیُّهَا ٱلَّذِینَ هَادُوۤا۟ إِن زَعَمۡتُمۡ أَنَّكُمۡ أَوۡلِیَاۤءُ لِلَّهِ مِن دُونِ ٱلنَّاسِ فَتَمَنَّوُا۟ ٱلۡمَوۡتَ إِن كُنتُمۡ صَـٰدِقِینَ\n\";s:13:\"numberInSurah\";i:6;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:553;s:4:\"ruku\";i:486;s:11:\"hizbQuarter\";i:221;s:5:\"sajda\";b:0;}i:6;a:9:{s:6:\"number\";i:5184;s:4:\"text\";s:187:\"وَلَا یَتَمَنَّوۡنَهُۥۤ أَبَدَۢا بِمَا قَدَّمَتۡ أَیۡدِیهِمۡۚ وَٱللَّهُ عَلِیمُۢ بِٱلظَّـٰلِمِینَ\n\";s:13:\"numberInSurah\";i:7;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:553;s:4:\"ruku\";i:486;s:11:\"hizbQuarter\";i:221;s:5:\"sajda\";b:0;}i:7;a:9:{s:6:\"number\";i:5185;s:4:\"text\";s:328:\"قُلۡ إِنَّ ٱلۡمَوۡتَ ٱلَّذِی تَفِرُّونَ مِنۡهُ فَإِنَّهُۥ مُلَـٰقِیكُمۡۖ ثُمَّ تُرَدُّونَ إِلَىٰ عَـٰلِمِ ٱلۡغَیۡبِ وَٱلشَّهَـٰدَةِ فَیُنَبِّئُكُم بِمَا كُنتُمۡ تَعۡمَلُونَ\n\";s:13:\"numberInSurah\";i:8;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:553;s:4:\"ruku\";i:486;s:11:\"hizbQuarter\";i:221;s:5:\"sajda\";b:0;}i:8;a:9:{s:6:\"number\";i:5186;s:4:\"text\";s:366:\"یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوۤا۟ إِذَا نُودِیَ لِلصَّلَوٰةِ مِن یَوۡمِ ٱلۡجُمُعَةِ فَٱسۡعَوۡا۟ إِلَىٰ ذِكۡرِ ٱللَّهِ وَذَرُوا۟ ٱلۡبَیۡعَۚ ذَ ٰ⁠لِكُمۡ خَیۡرࣱ لَّكُمۡ إِن كُنتُمۡ تَعۡلَمُونَ\n\";s:13:\"numberInSurah\";i:9;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:554;s:4:\"ruku\";i:487;s:11:\"hizbQuarter\";i:221;s:5:\"sajda\";b:0;}i:9;a:9:{s:6:\"number\";i:5187;s:4:\"text\";s:274:\"فَإِذَا قُضِیَتِ ٱلصَّلَوٰةُ فَٱنتَشِرُوا۟ فِی ٱلۡأَرۡضِ وَٱبۡتَغُوا۟ مِن فَضۡلِ ٱللَّهِ وَٱذۡكُرُوا۟ ٱللَّهَ كَثِیرࣰا لَّعَلَّكُمۡ تُفۡلِحُونَ\n\";s:13:\"numberInSurah\";i:10;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:554;s:4:\"ruku\";i:487;s:11:\"hizbQuarter\";i:221;s:5:\"sajda\";b:0;}i:10;a:9:{s:6:\"number\";i:5188;s:4:\"text\";s:359:\"وَإِذَا رَأَوۡا۟ تِجَـٰرَةً أَوۡ لَهۡوًا ٱنفَضُّوۤا۟ إِلَیۡهَا وَتَرَكُوكَ قَاۤىِٕمࣰاۚ قُلۡ مَا عِندَ ٱللَّهِ خَیۡرࣱ مِّنَ ٱللَّهۡوِ وَمِنَ ٱلتِّجَـٰرَةِۚ وَٱللَّهُ خَیۡرُ ٱلرَّ ٰ⁠زِقِینَ\n\";s:13:\"numberInSurah\";i:11;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:554;s:4:\"ruku\";i:487;s:11:\"hizbQuarter\";i:221;s:5:\"sajda\";b:0;}}s:7:\"edition\";a:7:{s:10:\"identifier\";s:27:\"quran-uthmani-quran-academy\";s:8:\"language\";s:2:\"ar\";s:4:\"name\";s:67:\"القرآن الكريم برسم العثماني (quran-academy)\";s:11:\"englishName\";s:78:\"Modified Quran Uthmani Text from the Quran Academy to work with the Kitab font\";s:6:\"format\";s:4:\"text\";s:4:\"type\";s:5:\"quran\";s:9:\"direction\";s:3:\"rtl\";}}', 1794581394),
('quranapp-cache-surah_62_fr.hamidullah', 'a:8:{s:6:\"number\";i:62;s:4:\"name\";s:35:\"سُورَةُ الجُمُعَةِ\";s:11:\"englishName\";s:9:\"Al-Jumu\'a\";s:22:\"englishNameTranslation\";s:6:\"Friday\";s:14:\"revelationType\";s:7:\"Medinan\";s:13:\"numberOfAyahs\";i:11;s:5:\"ayahs\";a:11:{i:0;a:9:{s:6:\"number\";i:5178;s:4:\"text\";s:114:\"Ce qui est dans les cieux et ce qui est sur la terre glorifient Allah, le Souverain, le Pur, le Puissant, le Sage.\";s:13:\"numberInSurah\";i:1;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:553;s:4:\"ruku\";i:486;s:11:\"hizbQuarter\";i:221;s:5:\"sajda\";b:0;}i:1;a:9:{s:6:\"number\";i:5179;s:4:\"text\";s:225:\"C\'est Lui qui a envoyé à des gens sans Livre (les Arabes) un Messager des leurs qui leur récite Ses versets, les purifie et leur enseigne le Livre et la Sagesse, bien qu\'ils étaient auparavant dans un égarement évident,\";s:13:\"numberInSurah\";i:2;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:553;s:4:\"ruku\";i:486;s:11:\"hizbQuarter\";i:221;s:5:\"sajda\";b:0;}i:2;a:9:{s:6:\"number\";i:5180;s:4:\"text\";s:99:\"ainsi qu\'à d\'autres parmi ceux qui ne les ont pas encore rejoints. C\'est Lui le Puissant, le Sage.\";s:13:\"numberInSurah\";i:3;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:553;s:4:\"ruku\";i:486;s:11:\"hizbQuarter\";i:221;s:5:\"sajda\";b:0;}i:3;a:9:{s:6:\"number\";i:5181;s:4:\"text\";s:103:\"Telle est la grâce d\'Allah qu\'Il donne à qui Il veut. Et Allah est le Détenteur de l\'énorme grâce.\";s:13:\"numberInSurah\";i:4;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:553;s:4:\"ruku\";i:486;s:11:\"hizbQuarter\";i:221;s:5:\"sajda\";b:0;}i:4;a:9:{s:6:\"number\";i:5182;s:4:\"text\";s:243:\"Ceux qui ont été chargés de la Thora mais qui ne l\'ont pas appliquée sont pareils à l\'âne qui porte des livres. Quel mauvais exemple que celui de ceux qui traitent de mensonges les versets d\'Allah et Allah ne guide pas les gens injustes.\";s:13:\"numberInSurah\";i:5;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:553;s:4:\"ruku\";i:486;s:11:\"hizbQuarter\";i:221;s:5:\"sajda\";b:0;}i:5;a:9:{s:6:\"number\";i:5183;s:4:\"text\";s:171:\"Dis: «O vous qui pratiquez le judaïsme! Si vous prétendez être les bien-aimés d\'Allah à l\'exclusion des autres, souhaitez, donc la mort, si vous êtes véridiques».\";s:13:\"numberInSurah\";i:6;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:553;s:4:\"ruku\";i:486;s:11:\"hizbQuarter\";i:221;s:5:\"sajda\";b:0;}i:6;a:9:{s:6:\"number\";i:5184;s:4:\"text\";s:124:\"Or, ils ne la souhaiteront jamais, à cause de ce que leurs mains ont préparé. Allah cependant connaît bien les injustes.\";s:13:\"numberInSurah\";i:7;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:553;s:4:\"ruku\";i:486;s:11:\"hizbQuarter\";i:221;s:5:\"sajda\";b:0;}i:7;a:9:{s:6:\"number\";i:5185;s:4:\"text\";s:212:\"Dis: «La mort que vous fuyez va certes vous rencontrer. Ensuite vous serez ramenés à Celui qui connaît parfaitement le monde Invisible et le monde visible et qui vous informera alors de ce que vous faisiez».\";s:13:\"numberInSurah\";i:8;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:553;s:4:\"ruku\";i:486;s:11:\"hizbQuarter\";i:221;s:5:\"sajda\";b:0;}i:8;a:9:{s:6:\"number\";i:5186;s:4:\"text\";s:179:\"O vous qui avez cru! Quand on appelle à la Salât du jour du Vendredi, accourez à l\'invocation d\'Allah et laissez tout négoce. Cela est bien meilleur pour vous, si vous saviez!\";s:13:\"numberInSurah\";i:9;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:554;s:4:\"ruku\";i:487;s:11:\"hizbQuarter\";i:221;s:5:\"sajda\";b:0;}i:9;a:9:{s:6:\"number\";i:5187;s:4:\"text\";s:166:\"Puis quand la Salât est achevée, dispersez-vous sur terre et recherchez [quelque effet] de la grâce d\'Allah, et invoquez beaucoup Allah afin que vous réussissiez.\";s:13:\"numberInSurah\";i:10;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:554;s:4:\"ruku\";i:487;s:11:\"hizbQuarter\";i:221;s:5:\"sajda\";b:0;}i:10;a:9:{s:6:\"number\";i:5188;s:4:\"text\";s:241:\"Quand ils entrevoient quelque commerce ou quelque divertissement, ils s\'y dispersent et te laissent debout. Dis: «Ce qui est auprès d\'Allah est bien meilleur que le divertissement et le commerce, et Allah est le Meilleur des pourvoyeurs».\";s:13:\"numberInSurah\";i:11;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:554;s:4:\"ruku\";i:487;s:11:\"hizbQuarter\";i:221;s:5:\"sajda\";b:0;}}s:7:\"edition\";a:7:{s:10:\"identifier\";s:13:\"fr.hamidullah\";s:8:\"language\";s:2:\"fr\";s:4:\"name\";s:10:\"Hamidullah\";s:11:\"englishName\";s:19:\"Muhammad Hamidullah\";s:6:\"format\";s:4:\"text\";s:4:\"type\";s:11:\"translation\";s:9:\"direction\";s:3:\"ltr\";}}', 1794581394),
('quranapp-cache-surah_63_ar.uthmani', 'a:8:{s:6:\"number\";i:63;s:4:\"name\";s:43:\"سُورَةُ المُنَافِقُونَ\";s:11:\"englishName\";s:14:\"Al-Munaafiqoon\";s:22:\"englishNameTranslation\";s:14:\"The Hypocrites\";s:14:\"revelationType\";s:7:\"Medinan\";s:13:\"numberOfAyahs\";i:11;s:5:\"ayahs\";a:11:{i:0;a:9:{s:6:\"number\";i:5189;s:4:\"text\";s:405:\"بِسۡمِ ٱللَّهِ ٱلرَّحۡمَـٰنِ ٱلرَّحِیمِ إِذَا جَاۤءَكَ ٱلۡمُنَـٰفِقُونَ قَالُوا۟ نَشۡهَدُ إِنَّكَ لَرَسُولُ ٱللَّهِۗ وَٱللَّهُ یَعۡلَمُ إِنَّكَ لَرَسُولُهُۥ وَٱللَّهُ یَشۡهَدُ إِنَّ ٱلۡمُنَـٰفِقِینَ لَكَـٰذِبُونَ\n\";s:13:\"numberInSurah\";i:1;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:554;s:4:\"ruku\";i:488;s:11:\"hizbQuarter\";i:221;s:5:\"sajda\";b:0;}i:1;a:9:{s:6:\"number\";i:5190;s:4:\"text\";s:209:\"ٱتَّخَذُوۤا۟ أَیۡمَـٰنَهُمۡ جُنَّةࣰ فَصَدُّوا۟ عَن سَبِیلِ ٱللَّهِۚ إِنَّهُمۡ سَاۤءَ مَا كَانُوا۟ یَعۡمَلُونَ\n\";s:13:\"numberInSurah\";i:2;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:554;s:4:\"ruku\";i:488;s:11:\"hizbQuarter\";i:221;s:5:\"sajda\";b:0;}i:2;a:9:{s:6:\"number\";i:5191;s:4:\"text\";s:191:\"ذَ ٰ⁠لِكَ بِأَنَّهُمۡ ءَامَنُوا۟ ثُمَّ كَفَرُوا۟ فَطُبِعَ عَلَىٰ قُلُوبِهِمۡ فَهُمۡ لَا یَفۡقَهُونَ\n\";s:13:\"numberInSurah\";i:3;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:554;s:4:\"ruku\";i:488;s:11:\"hizbQuarter\";i:221;s:5:\"sajda\";b:0;}i:3;a:9:{s:6:\"number\";i:5192;s:4:\"text\";s:447:\"۞ وَإِذَا رَأَیۡتَهُمۡ تُعۡجِبُكَ أَجۡسَامُهُمۡۖ وَإِن یَقُولُوا۟ تَسۡمَعۡ لِقَوۡلِهِمۡۖ كَأَنَّهُمۡ خُشُبࣱ مُّسَنَّدَةࣱۖ یَحۡسَبُونَ كُلَّ صَیۡحَةٍ عَلَیۡهِمۡۚ هُمُ ٱلۡعَدُوُّ فَٱحۡذَرۡهُمۡۚ قَـٰتَلَهُمُ ٱللَّهُۖ أَنَّىٰ یُؤۡفَكُونَ\n\";s:13:\"numberInSurah\";i:4;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:554;s:4:\"ruku\";i:488;s:11:\"hizbQuarter\";i:222;s:5:\"sajda\";b:0;}i:4;a:9:{s:6:\"number\";i:5193;s:4:\"text\";s:266:\"وَإِذَا قِیلَ لَهُمۡ تَعَالَوۡا۟ یَسۡتَغۡفِرۡ لَكُمۡ رَسُولُ ٱللَّهِ لَوَّوۡا۟ رُءُوسَهُمۡ وَرَأَیۡتَهُمۡ یَصُدُّونَ وَهُم مُّسۡتَكۡبِرُونَ\n\";s:13:\"numberInSurah\";i:5;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:555;s:4:\"ruku\";i:488;s:11:\"hizbQuarter\";i:222;s:5:\"sajda\";b:0;}i:5;a:9:{s:6:\"number\";i:5194;s:4:\"text\";s:286:\"سَوَاۤءٌ عَلَیۡهِمۡ أَسۡتَغۡفَرۡتَ لَهُمۡ أَمۡ لَمۡ تَسۡتَغۡفِرۡ لَهُمۡ لَن یَغۡفِرَ ٱللَّهُ لَهُمۡۚ إِنَّ ٱللَّهَ لَا یَهۡدِی ٱلۡقَوۡمَ ٱلۡفَـٰسِقِینَ\n\";s:13:\"numberInSurah\";i:6;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:555;s:4:\"ruku\";i:488;s:11:\"hizbQuarter\";i:222;s:5:\"sajda\";b:0;}i:6;a:9:{s:6:\"number\";i:5195;s:4:\"text\";s:366:\"هُمُ ٱلَّذِینَ یَقُولُونَ لَا تُنفِقُوا۟ عَلَىٰ مَنۡ عِندَ رَسُولِ ٱللَّهِ حَتَّىٰ یَنفَضُّوا۟ۗ وَلِلَّهِ خَزَاۤىِٕنُ ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِ وَلَـٰكِنَّ ٱلۡمُنَـٰفِقِینَ لَا یَفۡقَهُونَ\n\";s:13:\"numberInSurah\";i:7;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:555;s:4:\"ruku\";i:488;s:11:\"hizbQuarter\";i:222;s:5:\"sajda\";b:0;}i:7;a:9:{s:6:\"number\";i:5196;s:4:\"text\";s:369:\"یَقُولُونَ لَىِٕن رَّجَعۡنَاۤ إِلَى ٱلۡمَدِینَةِ لَیُخۡرِجَنَّ ٱلۡأَعَزُّ مِنۡهَا ٱلۡأَذَلَّۚ وَلِلَّهِ ٱلۡعِزَّةُ وَلِرَسُولِهِۦ وَلِلۡمُؤۡمِنِینَ وَلَـٰكِنَّ ٱلۡمُنَـٰفِقِینَ لَا یَعۡلَمُونَ\n\";s:13:\"numberInSurah\";i:8;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:555;s:4:\"ruku\";i:488;s:11:\"hizbQuarter\";i:222;s:5:\"sajda\";b:0;}i:8;a:9:{s:6:\"number\";i:5197;s:4:\"text\";s:327:\"یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ لَا تُلۡهِكُمۡ أَمۡوَ ٰ⁠لُكُمۡ وَلَاۤ أَوۡلَـٰدُكُمۡ عَن ذِكۡرِ ٱللَّهِۚ وَمَن یَفۡعَلۡ ذَ ٰ⁠لِكَ فَأُو۟لَـٰۤىِٕكَ هُمُ ٱلۡخَـٰسِرُونَ\n\";s:13:\"numberInSurah\";i:9;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:555;s:4:\"ruku\";i:489;s:11:\"hizbQuarter\";i:222;s:5:\"sajda\";b:0;}i:9;a:9:{s:6:\"number\";i:5198;s:4:\"text\";s:353:\"وَأَنفِقُوا۟ مِن مَّا رَزَقۡنَـٰكُم مِّن قَبۡلِ أَن یَأۡتِیَ أَحَدَكُمُ ٱلۡمَوۡتُ فَیَقُولَ رَبِّ لَوۡلَاۤ أَخَّرۡتَنِیۤ إِلَىٰۤ أَجَلࣲ قَرِیبࣲ فَأَصَّدَّقَ وَأَكُن مِّنَ ٱلصَّـٰلِحِینَ\n\";s:13:\"numberInSurah\";i:10;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:555;s:4:\"ruku\";i:489;s:11:\"hizbQuarter\";i:222;s:5:\"sajda\";b:0;}i:10;a:9:{s:6:\"number\";i:5199;s:4:\"text\";s:175:\"وَلَن یُؤَخِّرَ ٱللَّهُ نَفۡسًا إِذَا جَاۤءَ أَجَلُهَاۚ وَٱللَّهُ خَبِیرُۢ بِمَا تَعۡمَلُونَ\n\";s:13:\"numberInSurah\";i:11;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:555;s:4:\"ruku\";i:489;s:11:\"hizbQuarter\";i:222;s:5:\"sajda\";b:0;}}s:7:\"edition\";a:7:{s:10:\"identifier\";s:27:\"quran-uthmani-quran-academy\";s:8:\"language\";s:2:\"ar\";s:4:\"name\";s:67:\"القرآن الكريم برسم العثماني (quran-academy)\";s:11:\"englishName\";s:78:\"Modified Quran Uthmani Text from the Quran Academy to work with the Kitab font\";s:6:\"format\";s:4:\"text\";s:4:\"type\";s:5:\"quran\";s:9:\"direction\";s:3:\"rtl\";}}', 1794581395),
('quranapp-cache-surah_63_fr.hamidullah', 'a:8:{s:6:\"number\";i:63;s:4:\"name\";s:43:\"سُورَةُ المُنَافِقُونَ\";s:11:\"englishName\";s:14:\"Al-Munaafiqoon\";s:22:\"englishNameTranslation\";s:14:\"The Hypocrites\";s:14:\"revelationType\";s:7:\"Medinan\";s:13:\"numberOfAyahs\";i:11;s:5:\"ayahs\";a:11:{i:0;a:9:{s:6:\"number\";i:5189;s:4:\"text\";s:216:\"Quand les hypocrites viennent à toi, ils disent: «Nous attestons que tu es certes le Messager d\'Allah» Allah sait que tu es vraiment Son messager; et Allah atteste que les hypocrites sont assurément des menteurs.\";s:13:\"numberInSurah\";i:1;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:554;s:4:\"ruku\";i:488;s:11:\"hizbQuarter\";i:221;s:5:\"sajda\";b:0;}i:1;a:9:{s:6:\"number\";i:5190;s:4:\"text\";s:123:\"Ils prennent leurs serments pour bouclier et obstruent le chemin d\'Allah. Quelles mauvaises choses que ce qu\'ils faisaient!\";s:13:\"numberInSurah\";i:2;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:554;s:4:\"ruku\";i:488;s:11:\"hizbQuarter\";i:221;s:5:\"sajda\";b:0;}i:2;a:9:{s:6:\"number\";i:5191;s:4:\"text\";s:136:\"C\'est parce qu\'en vérité ils ont cru, puis rejeté la foi. Leurs cœurs donc, ont été scellés, de sorte qu\'ils ne comprennent rien.\";s:13:\"numberInSurah\";i:3;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:554;s:4:\"ruku\";i:488;s:11:\"hizbQuarter\";i:221;s:5:\"sajda\";b:0;}i:3;a:9:{s:6:\"number\";i:5192;s:4:\"text\";s:309:\"Et quand tu les vois, leurs corps t\'émerveillent; et s\'ils parlent tu écoutes leur parole. Ils sont comme des bûches appuyées (contre des murs) et ils pensent que chaque cri est dirigé contre eux. L\'ennemi c\'est eux. Prends y garde. Qu\'Allah les extermine! Comme les voilà détournés (du droit chemin).\";s:13:\"numberInSurah\";i:4;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:554;s:4:\"ruku\";i:488;s:11:\"hizbQuarter\";i:222;s:5:\"sajda\";b:0;}i:4;a:9:{s:6:\"number\";i:5193;s:4:\"text\";s:178:\"Et quand on leur dit: «Venez que le Messager d\'Allah implore le pardon pour vous», ils détournent leurs têtes, et tu les vois se détourner tandis qu\'ils s\'enflent d\'orgueil.\";s:13:\"numberInSurah\";i:5;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:555;s:4:\"ruku\";i:488;s:11:\"hizbQuarter\";i:222;s:5:\"sajda\";b:0;}i:5;a:9:{s:6:\"number\";i:5194;s:4:\"text\";s:159:\"C\'est égal, pour eux, que tu implores le pardon pour eux ou que tu ne le fasses pas: Allah ne leur pardonnera jamais, car Allah ne guide pas les gens pervers.\";s:13:\"numberInSurah\";i:6;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:555;s:4:\"ruku\";i:488;s:11:\"hizbQuarter\";i:222;s:5:\"sajda\";b:0;}i:6;a:9:{s:6:\"number\";i:5195;s:4:\"text\";s:235:\"Ce sont eux qui disent: «Ne dépensez point pour ceux qui sont auprès du Messager d\'Allah, afin qu\'ils se dispersent». Et c\'est à Allah qu\'appartiennent les trésors des cieux et de la terre, mais les hypocrites ne comprennent pas.\";s:13:\"numberInSurah\";i:7;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:555;s:4:\"ruku\";i:488;s:11:\"hizbQuarter\";i:222;s:5:\"sajda\";b:0;}i:7;a:9:{s:6:\"number\";i:5196;s:4:\"text\";s:224:\"Ils disent: «Si nous retournons à Médine, le plus puissant en fera assurément sortir le plus humble». Or c\'est à Allah qu\'est la puissance ainsi qu\'à Son messager et aux croyants. Mais les hypocrites ne le savent pas.\";s:13:\"numberInSurah\";i:8;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:555;s:4:\"ruku\";i:488;s:11:\"hizbQuarter\";i:222;s:5:\"sajda\";b:0;}i:8;a:9:{s:6:\"number\";i:5197;s:4:\"text\";s:152:\"O vous qui avez cru! Que ni vos biens ni vos enfants ne vous distraient du rappel d\'Allah. Et quiconque fait cela... alors ceux-là seront les perdants.\";s:13:\"numberInSurah\";i:9;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:555;s:4:\"ruku\";i:489;s:11:\"hizbQuarter\";i:222;s:5:\"sajda\";b:0;}i:9;a:9:{s:6:\"number\";i:5198;s:4:\"text\";s:225:\"Et dépensez de ce que Nous vous avons octroyé avant que la mort ne vienne à l\'un de vous et qu\'il dise alors: «Seigneur! si seulement Tu m\'accordais un court délai: je ferais l\'aumône et serais parmi les gens de bien».\";s:13:\"numberInSurah\";i:10;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:555;s:4:\"ruku\";i:489;s:11:\"hizbQuarter\";i:222;s:5:\"sajda\";b:0;}i:10;a:9:{s:6:\"number\";i:5199;s:4:\"text\";s:142:\"Allah cependant n\'accorde jamais de délai à une âme dont le terme est arrivé. Et Allah est Parfaitement Connaisseur de ce que vous faites.\";s:13:\"numberInSurah\";i:11;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:555;s:4:\"ruku\";i:489;s:11:\"hizbQuarter\";i:222;s:5:\"sajda\";b:0;}}s:7:\"edition\";a:7:{s:10:\"identifier\";s:13:\"fr.hamidullah\";s:8:\"language\";s:2:\"fr\";s:4:\"name\";s:10:\"Hamidullah\";s:11:\"englishName\";s:19:\"Muhammad Hamidullah\";s:6:\"format\";s:4:\"text\";s:4:\"type\";s:11:\"translation\";s:9:\"direction\";s:3:\"ltr\";}}', 1794581395),
('quranapp-cache-surah_64_ar.uthmani', 'a:8:{s:6:\"number\";i:64;s:4:\"name\";s:39:\"سُورَةُ التَّغَابُنِ\";s:11:\"englishName\";s:12:\"At-Taghaabun\";s:22:\"englishNameTranslation\";s:18:\"Mutual Disillusion\";s:14:\"revelationType\";s:7:\"Medinan\";s:13:\"numberOfAyahs\";i:18;s:5:\"ayahs\";a:18:{i:0;a:9:{s:6:\"number\";i:5200;s:4:\"text\";s:326:\"بِسۡمِ ٱللَّهِ ٱلرَّحۡمَـٰنِ ٱلرَّحِیمِ یُسَبِّحُ لِلَّهِ مَا فِی ٱلسَّمَـٰوَ ٰ⁠تِ وَمَا فِی ٱلۡأَرۡضِۖ لَهُ ٱلۡمُلۡكُ وَلَهُ ٱلۡحَمۡدُۖ وَهُوَ عَلَىٰ كُلِّ شَیۡءࣲ قَدِیرٌ\n\";s:13:\"numberInSurah\";i:1;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:556;s:4:\"ruku\";i:490;s:11:\"hizbQuarter\";i:222;s:5:\"sajda\";b:0;}i:1;a:9:{s:6:\"number\";i:5201;s:4:\"text\";s:187:\"هُوَ ٱلَّذِی خَلَقَكُمۡ فَمِنكُمۡ كَافِرࣱ وَمِنكُم مُّؤۡمِنࣱۚ وَٱللَّهُ بِمَا تَعۡمَلُونَ بَصِیرٌ\n\";s:13:\"numberInSurah\";i:2;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:556;s:4:\"ruku\";i:490;s:11:\"hizbQuarter\";i:222;s:5:\"sajda\";b:0;}i:2;a:9:{s:6:\"number\";i:5202;s:4:\"text\";s:205:\"خَلَقَ ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضَ بِٱلۡحَقِّ وَصَوَّرَكُمۡ فَأَحۡسَنَ صُوَرَكُمۡۖ وَإِلَیۡهِ ٱلۡمَصِیرُ\n\";s:13:\"numberInSurah\";i:3;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:556;s:4:\"ruku\";i:490;s:11:\"hizbQuarter\";i:222;s:5:\"sajda\";b:0;}i:3;a:9:{s:6:\"number\";i:5203;s:4:\"text\";s:246:\"یَعۡلَمُ مَا فِی ٱلسَّمَـٰوَ ٰ⁠تِ وَٱلۡأَرۡضِ وَیَعۡلَمُ مَا تُسِرُّونَ وَمَا تُعۡلِنُونَۚ وَٱللَّهُ عَلِیمُۢ بِذَاتِ ٱلصُّدُورِ\n\";s:13:\"numberInSurah\";i:4;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:556;s:4:\"ruku\";i:490;s:11:\"hizbQuarter\";i:222;s:5:\"sajda\";b:0;}i:4;a:9:{s:6:\"number\";i:5204;s:4:\"text\";s:214:\"أَلَمۡ یَأۡتِكُمۡ نَبَؤُا۟ ٱلَّذِینَ كَفَرُوا۟ مِن قَبۡلُ فَذَاقُوا۟ وَبَالَ أَمۡرِهِمۡ وَلَهُمۡ عَذَابٌ أَلِیمࣱ\n\";s:13:\"numberInSurah\";i:5;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:556;s:4:\"ruku\";i:490;s:11:\"hizbQuarter\";i:222;s:5:\"sajda\";b:0;}i:5;a:9:{s:6:\"number\";i:5205;s:4:\"text\";s:342:\"ذَ ٰ⁠لِكَ بِأَنَّهُۥ كَانَت تَّأۡتِیهِمۡ رُسُلُهُم بِٱلۡبَیِّنَـٰتِ فَقَالُوۤا۟ أَبَشَرࣱ یَهۡدُونَنَا فَكَفَرُوا۟ وَتَوَلَّوا۟ۖ وَّٱسۡتَغۡنَى ٱللَّهُۚ وَٱللَّهُ غَنِیٌّ حَمِیدࣱ\n\";s:13:\"numberInSurah\";i:6;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:556;s:4:\"ruku\";i:490;s:11:\"hizbQuarter\";i:222;s:5:\"sajda\";b:0;}i:6;a:9:{s:6:\"number\";i:5206;s:4:\"text\";s:301:\"زَعَمَ ٱلَّذِینَ كَفَرُوۤا۟ أَن لَّن یُبۡعَثُوا۟ۚ قُلۡ بَلَىٰ وَرَبِّی لَتُبۡعَثُنَّ ثُمَّ لَتُنَبَّؤُنَّ بِمَا عَمِلۡتُمۡۚ وَذَ ٰ⁠لِكَ عَلَى ٱللَّهِ یَسِیرࣱ\n\";s:13:\"numberInSurah\";i:7;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:556;s:4:\"ruku\";i:490;s:11:\"hizbQuarter\";i:222;s:5:\"sajda\";b:0;}i:7;a:9:{s:6:\"number\";i:5207;s:4:\"text\";s:201:\"فَـَٔامِنُوا۟ بِٱللَّهِ وَرَسُولِهِۦ وَٱلنُّورِ ٱلَّذِیۤ أَنزَلۡنَاۚ وَٱللَّهُ بِمَا تَعۡمَلُونَ خَبِیرࣱ\n\";s:13:\"numberInSurah\";i:8;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:556;s:4:\"ruku\";i:490;s:11:\"hizbQuarter\";i:222;s:5:\"sajda\";b:0;}i:8;a:9:{s:6:\"number\";i:5208;s:4:\"text\";s:516:\"یَوۡمَ یَجۡمَعُكُمۡ لِیَوۡمِ ٱلۡجَمۡعِۖ ذَ ٰ⁠لِكَ یَوۡمُ ٱلتَّغَابُنِۗ وَمَن یُؤۡمِنۢ بِٱللَّهِ وَیَعۡمَلۡ صَـٰلِحࣰا یُكَفِّرۡ عَنۡهُ سَیِّـَٔاتِهِۦ وَیُدۡخِلۡهُ جَنَّـٰتࣲ تَجۡرِی مِن تَحۡتِهَا ٱلۡأَنۡهَـٰرُ خَـٰلِدِینَ فِیهَاۤ أَبَدࣰاۚ ذَ ٰ⁠لِكَ ٱلۡفَوۡزُ ٱلۡعَظِیمُ\n\";s:13:\"numberInSurah\";i:9;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:556;s:4:\"ruku\";i:490;s:11:\"hizbQuarter\";i:222;s:5:\"sajda\";b:0;}i:9;a:9:{s:6:\"number\";i:5209;s:4:\"text\";s:243:\"وَٱلَّذِینَ كَفَرُوا۟ وَكَذَّبُوا۟ بِـَٔایَـٰتِنَاۤ أُو۟لَـٰۤىِٕكَ أَصۡحَـٰبُ ٱلنَّارِ خَـٰلِدِینَ فِیهَاۖ وَبِئۡسَ ٱلۡمَصِیرُ\n\";s:13:\"numberInSurah\";i:10;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:557;s:4:\"ruku\";i:490;s:11:\"hizbQuarter\";i:222;s:5:\"sajda\";b:0;}i:10;a:9:{s:6:\"number\";i:5210;s:4:\"text\";s:243:\"مَاۤ أَصَابَ مِن مُّصِیبَةٍ إِلَّا بِإِذۡنِ ٱللَّهِۗ وَمَن یُؤۡمِنۢ بِٱللَّهِ یَهۡدِ قَلۡبَهُۥۚ وَٱللَّهُ بِكُلِّ شَیۡءٍ عَلِیمࣱ\n\";s:13:\"numberInSurah\";i:11;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:557;s:4:\"ruku\";i:491;s:11:\"hizbQuarter\";i:222;s:5:\"sajda\";b:0;}i:11;a:9:{s:6:\"number\";i:5211;s:4:\"text\";s:225:\"وَأَطِیعُوا۟ ٱللَّهَ وَأَطِیعُوا۟ ٱلرَّسُولَۚ فَإِن تَوَلَّیۡتُمۡ فَإِنَّمَا عَلَىٰ رَسُولِنَا ٱلۡبَلَـٰغُ ٱلۡمُبِینُ\n\";s:13:\"numberInSurah\";i:12;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:557;s:4:\"ruku\";i:491;s:11:\"hizbQuarter\";i:222;s:5:\"sajda\";b:0;}i:12;a:9:{s:6:\"number\";i:5212;s:4:\"text\";s:155:\"ٱللَّهُ لَاۤ إِلَـٰهَ إِلَّا هُوَۚ وَعَلَى ٱللَّهِ فَلۡیَتَوَكَّلِ ٱلۡمُؤۡمِنُونَ\n\";s:13:\"numberInSurah\";i:13;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:557;s:4:\"ruku\";i:491;s:11:\"hizbQuarter\";i:222;s:5:\"sajda\";b:0;}i:13;a:9:{s:6:\"number\";i:5213;s:4:\"text\";s:366:\"یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوۤا۟ إِنَّ مِنۡ أَزۡوَ ٰ⁠جِكُمۡ وَأَوۡلَـٰدِكُمۡ عَدُوࣰّا لَّكُمۡ فَٱحۡذَرُوهُمۡۚ وَإِن تَعۡفُوا۟ وَتَصۡفَحُوا۟ وَتَغۡفِرُوا۟ فَإِنَّ ٱللَّهَ غَفُورࣱ رَّحِیمٌ\n\";s:13:\"numberInSurah\";i:14;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:557;s:4:\"ruku\";i:491;s:11:\"hizbQuarter\";i:222;s:5:\"sajda\";b:0;}i:14;a:9:{s:6:\"number\";i:5214;s:4:\"text\";s:172:\"إِنَّمَاۤ أَمۡوَ ٰ⁠لُكُمۡ وَأَوۡلَـٰدُكُمۡ فِتۡنَةࣱۚ وَٱللَّهُ عِندَهُۥۤ أَجۡرٌ عَظِیمࣱ\n\";s:13:\"numberInSurah\";i:15;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:557;s:4:\"ruku\";i:491;s:11:\"hizbQuarter\";i:222;s:5:\"sajda\";b:0;}i:15;a:9:{s:6:\"number\";i:5215;s:4:\"text\";s:317:\"فَٱتَّقُوا۟ ٱللَّهَ مَا ٱسۡتَطَعۡتُمۡ وَٱسۡمَعُوا۟ وَأَطِیعُوا۟ وَأَنفِقُوا۟ خَیۡرࣰا لِّأَنفُسِكُمۡۗ وَمَن یُوقَ شُحَّ نَفۡسِهِۦ فَأُو۟لَـٰۤىِٕكَ هُمُ ٱلۡمُفۡلِحُونَ\n\";s:13:\"numberInSurah\";i:16;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:557;s:4:\"ruku\";i:491;s:11:\"hizbQuarter\";i:222;s:5:\"sajda\";b:0;}i:16;a:9:{s:6:\"number\";i:5216;s:4:\"text\";s:199:\"إِن تُقۡرِضُوا۟ ٱللَّهَ قَرۡضًا حَسَنࣰا یُضَـٰعِفۡهُ لَكُمۡ وَیَغۡفِرۡ لَكُمۡۚ وَٱللَّهُ شَكُورٌ حَلِیمٌ\n\";s:13:\"numberInSurah\";i:17;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:557;s:4:\"ruku\";i:491;s:11:\"hizbQuarter\";i:222;s:5:\"sajda\";b:0;}i:17;a:9:{s:6:\"number\";i:5217;s:4:\"text\";s:109:\"عَـٰلِمُ ٱلۡغَیۡبِ وَٱلشَّهَـٰدَةِ ٱلۡعَزِیزُ ٱلۡحَكِیمُ\n\";s:13:\"numberInSurah\";i:18;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:557;s:4:\"ruku\";i:491;s:11:\"hizbQuarter\";i:222;s:5:\"sajda\";b:0;}}s:7:\"edition\";a:7:{s:10:\"identifier\";s:27:\"quran-uthmani-quran-academy\";s:8:\"language\";s:2:\"ar\";s:4:\"name\";s:67:\"القرآن الكريم برسم العثماني (quran-academy)\";s:11:\"englishName\";s:78:\"Modified Quran Uthmani Text from the Quran Academy to work with the Kitab font\";s:6:\"format\";s:4:\"text\";s:4:\"type\";s:5:\"quran\";s:9:\"direction\";s:3:\"rtl\";}}', 1794581395),
('quranapp-cache-surah_64_fr.hamidullah', 'a:8:{s:6:\"number\";i:64;s:4:\"name\";s:39:\"سُورَةُ التَّغَابُنِ\";s:11:\"englishName\";s:12:\"At-Taghaabun\";s:22:\"englishNameTranslation\";s:18:\"Mutual Disillusion\";s:14:\"revelationType\";s:7:\"Medinan\";s:13:\"numberOfAyahs\";i:18;s:5:\"ayahs\";a:18:{i:0;a:9:{s:6:\"number\";i:5200;s:4:\"text\";s:134:\"Ce qui est dans les cieux et ce qui est sur la terre glorifient Allah. A Lui la royauté et à Lui les louanges. Et Il est Omnipotent.\";s:13:\"numberInSurah\";i:1;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:556;s:4:\"ruku\";i:490;s:11:\"hizbQuarter\";i:222;s:5:\"sajda\";b:0;}i:1;a:9:{s:6:\"number\";i:5201;s:4:\"text\";s:119:\"C\'est Lui qui vous a créés. Parmi vous [il y a] mécréant et croyant. Allah observe parfaitement ce que vous faites.\";s:13:\"numberInSurah\";i:2;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:556;s:4:\"ruku\";i:490;s:11:\"hizbQuarter\";i:222;s:5:\"sajda\";b:0;}i:2;a:9:{s:6:\"number\";i:5202;s:4:\"text\";s:149:\"Il a créé les cieux et la terre en toute vérité et vous a donné votre forme et quelle belle forme Il vous a donnée! Et vers Lui est le devenir.\";s:13:\"numberInSurah\";i:3;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:556;s:4:\"ruku\";i:490;s:11:\"hizbQuarter\";i:222;s:5:\"sajda\";b:0;}i:3;a:9:{s:6:\"number\";i:5203;s:4:\"text\";s:158:\"Il sait ce qui est dans les cieux et la terre, et Il sait ce que vous cachez ainsi que ce que vous divulguez. Et Allah connaît bien le contenu des poitrines.\";s:13:\"numberInSurah\";i:4;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:556;s:4:\"ruku\";i:490;s:11:\"hizbQuarter\";i:222;s:5:\"sajda\";b:0;}i:4;a:9:{s:6:\"number\";i:5204;s:4:\"text\";s:180:\"Ne vous est-elle pas parvenue, la nouvelle de ceux qui auparavant ont mécru et qui ont goûté la conséquence néfaste de leur acte; ils auront en outre un châtiment douloureux.\";s:13:\"numberInSurah\";i:5;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:556;s:4:\"ruku\";i:490;s:11:\"hizbQuarter\";i:222;s:5:\"sajda\";b:0;}i:5;a:9:{s:6:\"number\";i:5205;s:4:\"text\";s:274:\"Il en est ainsi parce que leurs messagers leur venaient avec des preuves évidentes, et qu\'ils ont dit: «Sont-ce des hommes qui nous guideront?» Ils mécrurent alors et se détournèrent et Allah Se passa [d\'eux] et Allah Se suffit à Lui-même et Il est Digne de louange.\";s:13:\"numberInSurah\";i:6;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:556;s:4:\"ruku\";i:490;s:11:\"hizbQuarter\";i:222;s:5:\"sajda\";b:0;}i:6;a:9:{s:6:\"number\";i:5206;s:4:\"text\";s:236:\"Ceux qui ont mécru prétendent qu\'ils ne seront point ressuscités. Dis: «Mais si! Par mon Seigneur! Vous serez très certainement ressuscités; puis vous serez certes informés de ce que vous faisiez. Et cela est facile pour Allah».\";s:13:\"numberInSurah\";i:7;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:556;s:4:\"ruku\";i:490;s:11:\"hizbQuarter\";i:222;s:5:\"sajda\";b:0;}i:7;a:9:{s:6:\"number\";i:5207;s:4:\"text\";s:167:\"Croyez en Allah donc et en Son messager, ainsi qu\'en la Lumière [le Coran] que Nous avons fait descendre. Et Allah est Parfaitement Connaisseur de ce que vous faites.\";s:13:\"numberInSurah\";i:8;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:556;s:4:\"ruku\";i:490;s:11:\"hizbQuarter\";i:222;s:5:\"sajda\";b:0;}i:8;a:9:{s:6:\"number\";i:5208;s:4:\"text\";s:327:\"Le jour où Il vous réunira pour le jour du Rassemblement, ce sera le jour de la grande perte. Et celui qui croit en Allah et accomplit les bonnes œuvres, Il lui effacera ses mauvaises actions et le fera entrer dans des Jardins sous lesquels coulent les ruisseaux où ils demeureront éternellement. Voilà l\'énorme succès!\";s:13:\"numberInSurah\";i:9;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:556;s:4:\"ruku\";i:490;s:11:\"hizbQuarter\";i:222;s:5:\"sajda\";b:0;}i:9;a:9:{s:6:\"number\";i:5209;s:4:\"text\";s:157:\"Et ceux qui ont mécru et traité de mensonges Nos versets, ceux-là sont les gens du Feu où ils demeureront éternellement. Et quelle mauvaise destination!\";s:13:\"numberInSurah\";i:10;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:557;s:4:\"ruku\";i:490;s:11:\"hizbQuarter\";i:222;s:5:\"sajda\";b:0;}i:10;a:9:{s:6:\"number\";i:5210;s:4:\"text\";s:138:\"Nul malheur n\'atteint [l\'homme] que par la permission d\'Allah. Et quiconque croit en Allah, [Allah] guide son cœur. Allah est Omniscient.\";s:13:\"numberInSurah\";i:11;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:557;s:4:\"ruku\";i:491;s:11:\"hizbQuarter\";i:222;s:5:\"sajda\";b:0;}i:11;a:9:{s:6:\"number\";i:5211;s:4:\"text\";s:147:\"Obéissez à Allah et obéissez au Messager et si vous vous détournez... il n\'incombe à Notre messager que de transmettre en clair (son message).\";s:13:\"numberInSurah\";i:12;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:557;s:4:\"ruku\";i:491;s:11:\"hizbQuarter\";i:222;s:5:\"sajda\";b:0;}i:12;a:9:{s:6:\"number\";i:5212;s:4:\"text\";s:96:\"Allah nulle autre divinité que Lui! Et c\'est à Allah que les croyants [doivent] s\'en remettre.\";s:13:\"numberInSurah\";i:13;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:557;s:4:\"ruku\";i:491;s:11:\"hizbQuarter\";i:222;s:5:\"sajda\";b:0;}i:13;a:9:{s:6:\"number\";i:5213;s:4:\"text\";s:242:\"O vous qui avez cru, vous avez de vos épouses et de vos enfants un ennemi [une tentation]. Prenez-y garde donc. Mais si vous [les] excusez, passez sur [leurs] fautes et [leur] pardonnez, sachez qu\'Allah est Pardonneur, Très Miséricordieux.\";s:13:\"numberInSurah\";i:14;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:557;s:4:\"ruku\";i:491;s:11:\"hizbQuarter\";i:222;s:5:\"sajda\";b:0;}i:14;a:9:{s:6:\"number\";i:5214;s:4:\"text\";s:104:\"Vos biens et vos enfants ne sont qu\'une tentation, alors qu\'auprès d\'Allah est une énorme récompense.\";s:13:\"numberInSurah\";i:15;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:557;s:4:\"ruku\";i:491;s:11:\"hizbQuarter\";i:222;s:5:\"sajda\";b:0;}i:15;a:9:{s:6:\"number\";i:5215;s:4:\"text\";s:209:\"Craignez Allah, donc autant que vous pouvez, écoutez, obéissez et faites largesses. Ce sera un bien pour vous. Et quiconque a été protégé contre sa propre avidité... ceux-là sont ceux qui réussissent.\";s:13:\"numberInSurah\";i:16;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:557;s:4:\"ruku\";i:491;s:11:\"hizbQuarter\";i:222;s:5:\"sajda\";b:0;}i:16;a:9:{s:6:\"number\";i:5216;s:4:\"text\";s:144:\"Si vous faites à Allah un prêt sincère, Il le multipliera pour vous et vous pardonnera. Allah cependant est très Reconnaissant et Indulgent.\";s:13:\"numberInSurah\";i:17;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:557;s:4:\"ruku\";i:491;s:11:\"hizbQuarter\";i:222;s:5:\"sajda\";b:0;}i:17;a:9:{s:6:\"number\";i:5217;s:4:\"text\";s:84:\"Il est le Connaisseur du monde Invisible et visible, et Il est le Puissant, le Sage.\";s:13:\"numberInSurah\";i:18;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:557;s:4:\"ruku\";i:491;s:11:\"hizbQuarter\";i:222;s:5:\"sajda\";b:0;}}s:7:\"edition\";a:7:{s:10:\"identifier\";s:13:\"fr.hamidullah\";s:8:\"language\";s:2:\"fr\";s:4:\"name\";s:10:\"Hamidullah\";s:11:\"englishName\";s:19:\"Muhammad Hamidullah\";s:6:\"format\";s:4:\"text\";s:4:\"type\";s:11:\"translation\";s:9:\"direction\";s:3:\"ltr\";}}', 1794581396),
('quranapp-cache-surah_65_ar.uthmani', 'a:8:{s:6:\"number\";i:65;s:4:\"name\";s:35:\"سُورَةُ الطَّلَاقِ\";s:11:\"englishName\";s:9:\"At-Talaaq\";s:22:\"englishNameTranslation\";s:7:\"Divorce\";s:14:\"revelationType\";s:7:\"Medinan\";s:13:\"numberOfAyahs\";i:12;s:5:\"ayahs\";a:12:{i:0;a:9:{s:6:\"number\";i:5218;s:4:\"text\";s:818:\"بِسۡمِ ٱللَّهِ ٱلرَّحۡمَـٰنِ ٱلرَّحِیمِ یَـٰۤأَیُّهَا ٱلنَّبِیُّ إِذَا طَلَّقۡتُمُ ٱلنِّسَاۤءَ فَطَلِّقُوهُنَّ لِعِدَّتِهِنَّ وَأَحۡصُوا۟ ٱلۡعِدَّةَۖ وَٱتَّقُوا۟ ٱللَّهَ رَبَّكُمۡۖ لَا تُخۡرِجُوهُنَّ مِنۢ بُیُوتِهِنَّ وَلَا یَخۡرُجۡنَ إِلَّاۤ أَن یَأۡتِینَ بِفَـٰحِشَةࣲ مُّبَیِّنَةࣲۚ وَتِلۡكَ حُدُودُ ٱللَّهِۚ وَمَن یَتَعَدَّ حُدُودَ ٱللَّهِ فَقَدۡ ظَلَمَ نَفۡسَهُۥۚ لَا تَدۡرِی لَعَلَّ ٱللَّهَ یُحۡدِثُ بَعۡدَ ذَ ٰ⁠لِكَ أَمۡرࣰا\n\";s:13:\"numberInSurah\";i:1;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:558;s:4:\"ruku\";i:492;s:11:\"hizbQuarter\";i:223;s:5:\"sajda\";b:0;}i:1;a:9:{s:6:\"number\";i:5219;s:4:\"text\";s:553:\"فَإِذَا بَلَغۡنَ أَجَلَهُنَّ فَأَمۡسِكُوهُنَّ بِمَعۡرُوفٍ أَوۡ فَارِقُوهُنَّ بِمَعۡرُوفࣲ وَأَشۡهِدُوا۟ ذَوَیۡ عَدۡلࣲ مِّنكُمۡ وَأَقِیمُوا۟ ٱلشَّهَـٰدَةَ لِلَّهِۚ ذَ ٰ⁠لِكُمۡ یُوعَظُ بِهِۦ مَن كَانَ یُؤۡمِنُ بِٱللَّهِ وَٱلۡیَوۡمِ ٱلۡـَٔاخِرِۚ وَمَن یَتَّقِ ٱللَّهَ یَجۡعَل لَّهُۥ مَخۡرَجࣰا\n\";s:13:\"numberInSurah\";i:2;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:558;s:4:\"ruku\";i:492;s:11:\"hizbQuarter\";i:223;s:5:\"sajda\";b:0;}i:2;a:9:{s:6:\"number\";i:5220;s:4:\"text\";s:319:\"وَیَرۡزُقۡهُ مِنۡ حَیۡثُ لَا یَحۡتَسِبُۚ وَمَن یَتَوَكَّلۡ عَلَى ٱللَّهِ فَهُوَ حَسۡبُهُۥۤۚ إِنَّ ٱللَّهَ بَـٰلِغُ أَمۡرِهِۦۚ قَدۡ جَعَلَ ٱللَّهُ لِكُلِّ شَیۡءࣲ قَدۡرࣰا\n\";s:13:\"numberInSurah\";i:3;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:558;s:4:\"ruku\";i:492;s:11:\"hizbQuarter\";i:223;s:5:\"sajda\";b:0;}i:3;a:9:{s:6:\"number\";i:5221;s:4:\"text\";s:502:\"وَٱلَّـٰۤـِٔی یَىِٕسۡنَ مِنَ ٱلۡمَحِیضِ مِن نِّسَاۤىِٕكُمۡ إِنِ ٱرۡتَبۡتُمۡ فَعِدَّتُهُنَّ ثَلَـٰثَةُ أَشۡهُرࣲ وَٱلَّـٰۤـِٔی لَمۡ یَحِضۡنَۚ وَأُو۟لَـٰتُ ٱلۡأَحۡمَالِ أَجَلُهُنَّ أَن یَضَعۡنَ حَمۡلَهُنَّۚ وَمَن یَتَّقِ ٱللَّهَ یَجۡعَل لَّهُۥ مِنۡ أَمۡرِهِۦ یُسۡرࣰا\n\";s:13:\"numberInSurah\";i:4;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:558;s:4:\"ruku\";i:492;s:11:\"hizbQuarter\";i:223;s:5:\"sajda\";b:0;}i:4;a:9:{s:6:\"number\";i:5222;s:4:\"text\";s:246:\"ذَ ٰ⁠لِكَ أَمۡرُ ٱللَّهِ أَنزَلَهُۥۤ إِلَیۡكُمۡۚ وَمَن یَتَّقِ ٱللَّهَ یُكَفِّرۡ عَنۡهُ سَیِّـَٔاتِهِۦ وَیُعۡظِمۡ لَهُۥۤ أَجۡرًا\n\";s:13:\"numberInSurah\";i:5;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:558;s:4:\"ruku\";i:492;s:11:\"hizbQuarter\";i:223;s:5:\"sajda\";b:0;}i:5;a:9:{s:6:\"number\";i:5223;s:4:\"text\";s:622:\"أَسۡكِنُوهُنَّ مِنۡ حَیۡثُ سَكَنتُم مِّن وُجۡدِكُمۡ وَلَا تُضَاۤرُّوهُنَّ لِتُضَیِّقُوا۟ عَلَیۡهِنَّۚ وَإِن كُنَّ أُو۟لَـٰتِ حَمۡلࣲ فَأَنفِقُوا۟ عَلَیۡهِنَّ حَتَّىٰ یَضَعۡنَ حَمۡلَهُنَّۚ فَإِنۡ أَرۡضَعۡنَ لَكُمۡ فَـَٔاتُوهُنَّ أُجُورَهُنَّ وَأۡتَمِرُوا۟ بَیۡنَكُم بِمَعۡرُوفࣲۖ وَإِن تَعَاسَرۡتُمۡ فَسَتُرۡضِعُ لَهُۥۤ أُخۡرَىٰ\n\";s:13:\"numberInSurah\";i:6;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:559;s:4:\"ruku\";i:492;s:11:\"hizbQuarter\";i:223;s:5:\"sajda\";b:0;}i:6;a:9:{s:6:\"number\";i:5224;s:4:\"text\";s:384:\"لِیُنفِقۡ ذُو سَعَةࣲ مِّن سَعَتِهِۦۖ وَمَن قُدِرَ عَلَیۡهِ رِزۡقُهُۥ فَلۡیُنفِقۡ مِمَّاۤ ءَاتَىٰهُ ٱللَّهُۚ لَا یُكَلِّفُ ٱللَّهُ نَفۡسًا إِلَّا مَاۤ ءَاتَىٰهَاۚ سَیَجۡعَلُ ٱللَّهُ بَعۡدَ عُسۡرࣲ یُسۡرࣰا\n\";s:13:\"numberInSurah\";i:7;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:559;s:4:\"ruku\";i:492;s:11:\"hizbQuarter\";i:223;s:5:\"sajda\";b:0;}i:7;a:9:{s:6:\"number\";i:5225;s:4:\"text\";s:260:\"وَكَأَیِّن مِّن قَرۡیَةٍ عَتَتۡ عَنۡ أَمۡرِ رَبِّهَا وَرُسُلِهِۦ فَحَاسَبۡنَـٰهَا حِسَابࣰا شَدِیدࣰا وَعَذَّبۡنَـٰهَا عَذَابࣰا نُّكۡرࣰا\n\";s:13:\"numberInSurah\";i:8;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:559;s:4:\"ruku\";i:493;s:11:\"hizbQuarter\";i:223;s:5:\"sajda\";b:0;}i:8;a:9:{s:6:\"number\";i:5226;s:4:\"text\";s:123:\"فَذَاقَتۡ وَبَالَ أَمۡرِهَا وَكَانَ عَـٰقِبَةُ أَمۡرِهَا خُسۡرًا\n\";s:13:\"numberInSurah\";i:9;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:559;s:4:\"ruku\";i:493;s:11:\"hizbQuarter\";i:223;s:5:\"sajda\";b:0;}i:9;a:9:{s:6:\"number\";i:5227;s:4:\"text\";s:289:\"أَعَدَّ ٱللَّهُ لَهُمۡ عَذَابࣰا شَدِیدࣰاۖ فَٱتَّقُوا۟ ٱللَّهَ یَـٰۤأُو۟لِی ٱلۡأَلۡبَـٰبِ ٱلَّذِینَ ءَامَنُوا۟ۚ قَدۡ أَنزَلَ ٱللَّهُ إِلَیۡكُمۡ ذِكۡرࣰا\n\";s:13:\"numberInSurah\";i:10;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:559;s:4:\"ruku\";i:493;s:11:\"hizbQuarter\";i:223;s:5:\"sajda\";b:0;}i:10;a:9:{s:6:\"number\";i:5228;s:4:\"text\";s:625:\"رَّسُولࣰا یَتۡلُوا۟ عَلَیۡكُمۡ ءَایَـٰتِ ٱللَّهِ مُبَیِّنَـٰتࣲ لِّیُخۡرِجَ ٱلَّذِینَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ مِنَ ٱلظُّلُمَـٰتِ إِلَى ٱلنُّورِۚ وَمَن یُؤۡمِنۢ بِٱللَّهِ وَیَعۡمَلۡ صَـٰلِحࣰا یُدۡخِلۡهُ جَنَّـٰتࣲ تَجۡرِی مِن تَحۡتِهَا ٱلۡأَنۡهَـٰرُ خَـٰلِدِینَ فِیهَاۤ أَبَدࣰاۖ قَدۡ أَحۡسَنَ ٱللَّهُ لَهُۥ رِزۡقًا\n\";s:13:\"numberInSurah\";i:11;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:559;s:4:\"ruku\";i:493;s:11:\"hizbQuarter\";i:223;s:5:\"sajda\";b:0;}i:11;a:9:{s:6:\"number\";i:5229;s:4:\"text\";s:416:\"ٱللَّهُ ٱلَّذِی خَلَقَ سَبۡعَ سَمَـٰوَ ٰ⁠تࣲ وَمِنَ ٱلۡأَرۡضِ مِثۡلَهُنَّۖ یَتَنَزَّلُ ٱلۡأَمۡرُ بَیۡنَهُنَّ لِتَعۡلَمُوۤا۟ أَنَّ ٱللَّهَ عَلَىٰ كُلِّ شَیۡءࣲ قَدِیرࣱ وَأَنَّ ٱللَّهَ قَدۡ أَحَاطَ بِكُلِّ شَیۡءٍ عِلۡمَۢا\n\";s:13:\"numberInSurah\";i:12;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:559;s:4:\"ruku\";i:493;s:11:\"hizbQuarter\";i:223;s:5:\"sajda\";b:0;}}s:7:\"edition\";a:7:{s:10:\"identifier\";s:27:\"quran-uthmani-quran-academy\";s:8:\"language\";s:2:\"ar\";s:4:\"name\";s:67:\"القرآن الكريم برسم العثماني (quran-academy)\";s:11:\"englishName\";s:78:\"Modified Quran Uthmani Text from the Quran Academy to work with the Kitab font\";s:6:\"format\";s:4:\"text\";s:4:\"type\";s:5:\"quran\";s:9:\"direction\";s:3:\"rtl\";}}', 1794581396),
('quranapp-cache-surah_65_fr.hamidullah', 'a:8:{s:6:\"number\";i:65;s:4:\"name\";s:35:\"سُورَةُ الطَّلَاقِ\";s:11:\"englishName\";s:9:\"At-Talaaq\";s:22:\"englishNameTranslation\";s:7:\"Divorce\";s:14:\"revelationType\";s:7:\"Medinan\";s:13:\"numberOfAyahs\";i:12;s:5:\"ayahs\";a:12:{i:0;a:9:{s:6:\"number\";i:5218;s:4:\"text\";s:486:\"O Prophète! Quand vous répudiez les femmes, répudiez-les conformément à leur période d\'attente prescrite; et comptez la période; et craignez Allah votre Seigneur. Ne les faites pas sortir de leurs maisons, et qu\'elles n\'en sortent pas, à moins qu\'elles n\'aient commis une turpitude prouvée. Telles sont les lois d\'Allah. Quiconque cependant transgresse les lois d\'Allah, se fait du tort à lui-même. Tu ne sais pas si d\'ici là Allah ne suscitera pas quelque chose de nouveau!\";s:13:\"numberInSurah\";i:1;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:558;s:4:\"ruku\";i:492;s:11:\"hizbQuarter\";i:223;s:5:\"sajda\";b:0;}i:1;a:9:{s:6:\"number\";i:5219;s:4:\"text\";s:372:\"Puis quand elles atteignent le terme prescrit, retenez-les de façon convenable, ou séparez-vous d\'elles de façon convenable; et prenez deux hommes intègres parmi vous comme témoins. Et acquittez-vous du témoignage envers Allah. Voilà ce à quoi est exhorté celui qui croit en Allah et au Jour dernier. Et quiconque craint Allah, Il Lui donnera une issue favorable,\";s:13:\"numberInSurah\";i:2;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:558;s:4:\"ruku\";i:492;s:11:\"hizbQuarter\";i:223;s:5:\"sajda\";b:0;}i:2;a:9:{s:6:\"number\";i:5220;s:4:\"text\";s:223:\"et lui accordera Ses dons par [des moyens] sur lesquels il ne comptait pas. Et quiconque place sa confiance en Allah, Il [Allah] lui suffit. Allah atteint ce qu\'Il Se propose, et Allah a assigné une mesure à chaque chose.\";s:13:\"numberInSurah\";i:3;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:558;s:4:\"ruku\";i:492;s:11:\"hizbQuarter\";i:223;s:5:\"sajda\";b:0;}i:3;a:9:{s:6:\"number\";i:5221;s:4:\"text\";s:358:\"Si vous avez des doutes à propos (de la période d\'attente) de vos femmes qui n\'espèrent plus avoir de règles, leur délai est de trois mois. De même pour celles qui n\'ont pas encore de règles. Et quant à celles qui sont enceintes, leur période d\'attente se terminera à leur accouchement. Quiconque craint Allah cependant, Il lui facilite les choses.\";s:13:\"numberInSurah\";i:4;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:558;s:4:\"ruku\";i:492;s:11:\"hizbQuarter\";i:223;s:5:\"sajda\";b:0;}i:4;a:9:{s:6:\"number\";i:5222;s:4:\"text\";s:163:\"Tel est le commandement d\'Allah qu\'Il a fait descendre vers vous. Quiconque craint Allah cependant, Il lui efface ses fautes et lui accorde une grosse récompense.\";s:13:\"numberInSurah\";i:5;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:558;s:4:\"ruku\";i:492;s:11:\"hizbQuarter\";i:223;s:5:\"sajda\";b:0;}i:5;a:9:{s:6:\"number\";i:5223;s:4:\"text\";s:464:\"Et faites que ces femmes habitent où vous habitez, et suivant vos moyens. Et ne cherchez pas à leur nuire en les contraignant à vivre à l\'étroit. Et si elles sont enceintes, pourvoyez à leurs besoins jusqu\'à ce qu\'elles aient accouché. Puis, si elles allaitent [l\'enfant né] de vous, donnez-leur leurs salaires. Et concertez vous [à ce sujet] de façon convenable. Et si vous rencontrez des difficultés réciproques, alors, une autre allaitera pour lui.\";s:13:\"numberInSurah\";i:6;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:559;s:4:\"ruku\";i:492;s:11:\"hizbQuarter\";i:223;s:5:\"sajda\";b:0;}i:6;a:9:{s:6:\"number\";i:5224;s:4:\"text\";s:241:\"Que celui qui est aisé dépense de sa fortune; et que celui dont les biens sont restreints dépense selon ce qu\'Allah lui a accordé. Allah n\'impose à personne que selon ce qu\'Il lui a donné, et Allah fera succéder l\'aisance à la gêne.\";s:13:\"numberInSurah\";i:7;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:559;s:4:\"ruku\";i:492;s:11:\"hizbQuarter\";i:223;s:5:\"sajda\";b:0;}i:7;a:9:{s:6:\"number\";i:5225;s:4:\"text\";s:187:\"Que de cités ont refusé avec insolence le commandement de leur Seigneur et de Ses messagers! Nous leur en demandâmes compte avec sévérité, et les châtiâmes d\'un châtiment inouï.\";s:13:\"numberInSurah\";i:8;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:559;s:4:\"ruku\";i:493;s:11:\"hizbQuarter\";i:223;s:5:\"sajda\";b:0;}i:8;a:9:{s:6:\"number\";i:5226;s:4:\"text\";s:121:\"Elles goûtèrent donc la conséquence de leur comportement. Et le résultat final de leurs actions fut [leur] perdition.\";s:13:\"numberInSurah\";i:9;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:559;s:4:\"ruku\";i:493;s:11:\"hizbQuarter\";i:223;s:5:\"sajda\";b:0;}i:9;a:9:{s:6:\"number\";i:5227;s:4:\"text\";s:181:\"Allah a préparé pour eux un dur châtiment. Craignez Allah donc, ô vous qui êtes doués d\'intelligence, vous qui avez la foi. Certes, Allah a fait descendre vers vous un rappel,\";s:13:\"numberInSurah\";i:10;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:559;s:4:\"ruku\";i:493;s:11:\"hizbQuarter\";i:223;s:5:\"sajda\";b:0;}i:10;a:9:{s:6:\"number\";i:5228;s:4:\"text\";s:360:\"un Messager qui vous récite les versets d\'Allah comme preuves claires, afin de faire sortir ceux qui croient et accomplissent les bonnes œuvres des ténèbres à la lumière. Et quiconque croit en Allah et fait le bien, Il le fait entrer aux Jardins sous lesquels coulent les ruisseaux, pour y demeurer éternellement. Allah lui a fait une belle attribution.\";s:13:\"numberInSurah\";i:11;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:559;s:4:\"ruku\";i:493;s:11:\"hizbQuarter\";i:223;s:5:\"sajda\";b:0;}i:11;a:9:{s:6:\"number\";i:5229;s:4:\"text\";s:199:\"Allah qui a créé sept cieux et autant de terres. Entre eux [Son] commandement descend, afin que vous sachiez qu\'Allah est en vérité Omnipotent et qu\'Allah a embrassé toute chose de [Son] savoir.\";s:13:\"numberInSurah\";i:12;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:559;s:4:\"ruku\";i:493;s:11:\"hizbQuarter\";i:223;s:5:\"sajda\";b:0;}}s:7:\"edition\";a:7:{s:10:\"identifier\";s:13:\"fr.hamidullah\";s:8:\"language\";s:2:\"fr\";s:4:\"name\";s:10:\"Hamidullah\";s:11:\"englishName\";s:19:\"Muhammad Hamidullah\";s:6:\"format\";s:4:\"text\";s:4:\"type\";s:11:\"translation\";s:9:\"direction\";s:3:\"ltr\";}}', 1794581396);
INSERT INTO `cache` (`key`, `value`, `expiration`) VALUES
('quranapp-cache-surah_66_ar.uthmani', 'a:8:{s:6:\"number\";i:66;s:4:\"name\";s:39:\"سُورَةُ التَّحۡرِيمِ\";s:11:\"englishName\";s:9:\"At-Tahrim\";s:22:\"englishNameTranslation\";s:15:\"The Prohibition\";s:14:\"revelationType\";s:7:\"Medinan\";s:13:\"numberOfAyahs\";i:12;s:5:\"ayahs\";a:12:{i:0;a:9:{s:6:\"number\";i:5230;s:4:\"text\";s:324:\"بِسۡمِ ٱللَّهِ ٱلرَّحۡمَـٰنِ ٱلرَّحِیمِ یَـٰۤأَیُّهَا ٱلنَّبِیُّ لِمَ تُحَرِّمُ مَاۤ أَحَلَّ ٱللَّهُ لَكَۖ تَبۡتَغِی مَرۡضَاتَ أَزۡوَ ٰ⁠جِكَۚ وَٱللَّهُ غَفُورࣱ رَّحِیمࣱ\n\";s:13:\"numberInSurah\";i:1;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:560;s:4:\"ruku\";i:494;s:11:\"hizbQuarter\";i:224;s:5:\"sajda\";b:0;}i:1;a:9:{s:6:\"number\";i:5231;s:4:\"text\";s:201:\"قَدۡ فَرَضَ ٱللَّهُ لَكُمۡ تَحِلَّةَ أَیۡمَـٰنِكُمۡۚ وَٱللَّهُ مَوۡلَىٰكُمۡۖ وَهُوَ ٱلۡعَلِیمُ ٱلۡحَكِیمُ\n\";s:13:\"numberInSurah\";i:2;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:560;s:4:\"ruku\";i:494;s:11:\"hizbQuarter\";i:224;s:5:\"sajda\";b:0;}i:2;a:9:{s:6:\"number\";i:5232;s:4:\"text\";s:495:\"وَإِذۡ أَسَرَّ ٱلنَّبِیُّ إِلَىٰ بَعۡضِ أَزۡوَ ٰ⁠جِهِۦ حَدِیثࣰا فَلَمَّا نَبَّأَتۡ بِهِۦ وَأَظۡهَرَهُ ٱللَّهُ عَلَیۡهِ عَرَّفَ بَعۡضَهُۥ وَأَعۡرَضَ عَنۢ بَعۡضࣲۖ فَلَمَّا نَبَّأَهَا بِهِۦ قَالَتۡ مَنۡ أَنۢبَأَكَ هَـٰذَاۖ قَالَ نَبَّأَنِیَ ٱلۡعَلِیمُ ٱلۡخَبِیرُ\n\";s:13:\"numberInSurah\";i:3;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:560;s:4:\"ruku\";i:494;s:11:\"hizbQuarter\";i:224;s:5:\"sajda\";b:0;}i:3;a:9:{s:6:\"number\";i:5233;s:4:\"text\";s:379:\"إِن تَتُوبَاۤ إِلَى ٱللَّهِ فَقَدۡ صَغَتۡ قُلُوبُكُمَاۖ وَإِن تَظَـٰهَرَا عَلَیۡهِ فَإِنَّ ٱللَّهَ هُوَ مَوۡلَىٰهُ وَجِبۡرِیلُ وَصَـٰلِحُ ٱلۡمُؤۡمِنِینَۖ وَٱلۡمَلَـٰۤىِٕكَةُ بَعۡدَ ذَ ٰ⁠لِكَ ظَهِیرٌ\n\";s:13:\"numberInSurah\";i:4;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:560;s:4:\"ruku\";i:494;s:11:\"hizbQuarter\";i:224;s:5:\"sajda\";b:0;}i:4;a:9:{s:6:\"number\";i:5234;s:4:\"text\";s:377:\"عَسَىٰ رَبُّهُۥۤ إِن طَلَّقَكُنَّ أَن یُبۡدِلَهُۥۤ أَزۡوَ ٰ⁠جًا خَیۡرࣰا مِّنكُنَّ مُسۡلِمَـٰتࣲ مُّؤۡمِنَـٰتࣲ قَـٰنِتَـٰتࣲ تَـٰۤىِٕبَـٰتٍ عَـٰبِدَ ٰ⁠تࣲ سَـٰۤىِٕحَـٰتࣲ ثَیِّبَـٰتࣲ وَأَبۡكَارࣰا\n\";s:13:\"numberInSurah\";i:5;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:560;s:4:\"ruku\";i:494;s:11:\"hizbQuarter\";i:224;s:5:\"sajda\";b:0;}i:5;a:9:{s:6:\"number\";i:5235;s:4:\"text\";s:421:\"یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ قُوۤا۟ أَنفُسَكُمۡ وَأَهۡلِیكُمۡ نَارࣰا وَقُودُهَا ٱلنَّاسُ وَٱلۡحِجَارَةُ عَلَیۡهَا مَلَـٰۤىِٕكَةٌ غِلَاظࣱ شِدَادࣱ لَّا یَعۡصُونَ ٱللَّهَ مَاۤ أَمَرَهُمۡ وَیَفۡعَلُونَ مَا یُؤۡمَرُونَ\n\";s:13:\"numberInSurah\";i:6;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:560;s:4:\"ruku\";i:494;s:11:\"hizbQuarter\";i:224;s:5:\"sajda\";b:0;}i:6;a:9:{s:6:\"number\";i:5236;s:4:\"text\";s:203:\"یَـٰۤأَیُّهَا ٱلَّذِینَ كَفَرُوا۟ لَا تَعۡتَذِرُوا۟ ٱلۡیَوۡمَۖ إِنَّمَا تُجۡزَوۡنَ مَا كُنتُمۡ تَعۡمَلُونَ\n\";s:13:\"numberInSurah\";i:7;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:560;s:4:\"ruku\";i:494;s:11:\"hizbQuarter\";i:224;s:5:\"sajda\";b:0;}i:7;a:9:{s:6:\"number\";i:5237;s:4:\"text\";s:799:\"یَـٰۤأَیُّهَا ٱلَّذِینَ ءَامَنُوا۟ تُوبُوۤا۟ إِلَى ٱللَّهِ تَوۡبَةࣰ نَّصُوحًا عَسَىٰ رَبُّكُمۡ أَن یُكَفِّرَ عَنكُمۡ سَیِّـَٔاتِكُمۡ وَیُدۡخِلَكُمۡ جَنَّـٰتࣲ تَجۡرِی مِن تَحۡتِهَا ٱلۡأَنۡهَـٰرُ یَوۡمَ لَا یُخۡزِی ٱللَّهُ ٱلنَّبِیَّ وَٱلَّذِینَ ءَامَنُوا۟ مَعَهُۥۖ نُورُهُمۡ یَسۡعَىٰ بَیۡنَ أَیۡدِیهِمۡ وَبِأَیۡمَـٰنِهِمۡ یَقُولُونَ رَبَّنَاۤ أَتۡمِمۡ لَنَا نُورَنَا وَٱغۡفِرۡ لَنَاۤۖ إِنَّكَ عَلَىٰ كُلِّ شَیۡءࣲ قَدِیرࣱ\n\";s:13:\"numberInSurah\";i:8;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:561;s:4:\"ruku\";i:495;s:11:\"hizbQuarter\";i:224;s:5:\"sajda\";b:0;}i:8;a:9:{s:6:\"number\";i:5238;s:4:\"text\";s:255:\"یَـٰۤأَیُّهَا ٱلنَّبِیُّ جَـٰهِدِ ٱلۡكُفَّارَ وَٱلۡمُنَـٰفِقِینَ وَٱغۡلُظۡ عَلَیۡهِمۡۚ وَمَأۡوَىٰهُمۡ جَهَنَّمُۖ وَبِئۡسَ ٱلۡمَصِیرُ\n\";s:13:\"numberInSurah\";i:9;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:561;s:4:\"ruku\";i:495;s:11:\"hizbQuarter\";i:224;s:5:\"sajda\";b:0;}i:9;a:9:{s:6:\"number\";i:5239;s:4:\"text\";s:475:\"ضَرَبَ ٱللَّهُ مَثَلࣰا لِّلَّذِینَ كَفَرُوا۟ ٱمۡرَأَتَ نُوحࣲ وَٱمۡرَأَتَ لُوطࣲۖ كَانَتَا تَحۡتَ عَبۡدَیۡنِ مِنۡ عِبَادِنَا صَـٰلِحَیۡنِ فَخَانَتَاهُمَا فَلَمۡ یُغۡنِیَا عَنۡهُمَا مِنَ ٱللَّهِ شَیۡـࣰٔا وَقِیلَ ٱدۡخُلَا ٱلنَّارَ مَعَ ٱلدَّ ٰ⁠خِلِینَ\n\";s:13:\"numberInSurah\";i:10;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:561;s:4:\"ruku\";i:495;s:11:\"hizbQuarter\";i:224;s:5:\"sajda\";b:0;}i:10;a:9:{s:6:\"number\";i:5240;s:4:\"text\";s:394:\"وَضَرَبَ ٱللَّهُ مَثَلࣰا لِّلَّذِینَ ءَامَنُوا۟ ٱمۡرَأَتَ فِرۡعَوۡنَ إِذۡ قَالَتۡ رَبِّ ٱبۡنِ لِی عِندَكَ بَیۡتࣰا فِی ٱلۡجَنَّةِ وَنَجِّنِی مِن فِرۡعَوۡنَ وَعَمَلِهِۦ وَنَجِّنِی مِنَ ٱلۡقَوۡمِ ٱلظَّـٰلِمِینَ\n\";s:13:\"numberInSurah\";i:11;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:561;s:4:\"ruku\";i:495;s:11:\"hizbQuarter\";i:224;s:5:\"sajda\";b:0;}i:11;a:9:{s:6:\"number\";i:5241;s:4:\"text\";s:323:\"وَمَرۡیَمَ ٱبۡنَتَ عِمۡرَ ٰ⁠نَ ٱلَّتِیۤ أَحۡصَنَتۡ فَرۡجَهَا فَنَفَخۡنَا فِیهِ مِن رُّوحِنَا وَصَدَّقَتۡ بِكَلِمَـٰتِ رَبِّهَا وَكُتُبِهِۦ وَكَانَتۡ مِنَ ٱلۡقَـٰنِتِینَ\n\";s:13:\"numberInSurah\";i:12;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:561;s:4:\"ruku\";i:495;s:11:\"hizbQuarter\";i:224;s:5:\"sajda\";b:0;}}s:7:\"edition\";a:7:{s:10:\"identifier\";s:27:\"quran-uthmani-quran-academy\";s:8:\"language\";s:2:\"ar\";s:4:\"name\";s:67:\"القرآن الكريم برسم العثماني (quran-academy)\";s:11:\"englishName\";s:78:\"Modified Quran Uthmani Text from the Quran Academy to work with the Kitab font\";s:6:\"format\";s:4:\"text\";s:4:\"type\";s:5:\"quran\";s:9:\"direction\";s:3:\"rtl\";}}', 1794581397),
('quranapp-cache-surah_66_fr.hamidullah', 'a:8:{s:6:\"number\";i:66;s:4:\"name\";s:39:\"سُورَةُ التَّحۡرِيمِ\";s:11:\"englishName\";s:9:\"At-Tahrim\";s:22:\"englishNameTranslation\";s:15:\"The Prohibition\";s:14:\"revelationType\";s:7:\"Medinan\";s:13:\"numberOfAyahs\";i:12;s:5:\"ayahs\";a:12:{i:0;a:9:{s:6:\"number\";i:5230;s:4:\"text\";s:156:\"O Prophète! Pourquoi, en recherchant l\'agrément de tes femmes, t\'interdis-tu ce qu\'Allah t\'a rendu licite? Et Allah est Pardonneur, Très Miséricordieux.\";s:13:\"numberInSurah\";i:1;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:560;s:4:\"ruku\";i:494;s:11:\"hizbQuarter\";i:224;s:5:\"sajda\";b:0;}i:1;a:9:{s:6:\"number\";i:5231;s:4:\"text\";s:124:\"Allah vous a prescrit certes, de vous libérer de vos serments. Allah est votre Maître; et c\'est Lui l\'Omniscient, le Sage.\";s:13:\"numberInSurah\";i:2;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:560;s:4:\"ruku\";i:494;s:11:\"hizbQuarter\";i:224;s:5:\"sajda\";b:0;}i:2;a:9:{s:6:\"number\";i:5232;s:4:\"text\";s:338:\"Lorsque le Prophète confia un secret à l\'une de ses épouses et qu\'elle l\'eut divulgué et qu\'Allah l\'en eut informé, celui-ci en fit connaître une partie et passa sur une partie. Puis, quand il l\'en eut informée elle dit: «Qui t\'en a donné nouvelle?» Il dit: «C\'est l\'Omniscient, le Parfaitement Connaisseur qui m\'en a avisé».\";s:13:\"numberInSurah\";i:3;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:560;s:4:\"ruku\";i:494;s:11:\"hizbQuarter\";i:224;s:5:\"sajda\";b:0;}i:3;a:9:{s:6:\"number\";i:5233;s:4:\"text\";s:251:\"Si vous vous repentez à Allah c\'est que vos cœurs ont fléchi. Mais si vous vous soutenez l\'une l\'autre contre le Prophète, alors ses alliés seront Allah, Gabriel et les vertueux d\'entre les croyants, et les Anges sont par surcroît [son] soutien.\";s:13:\"numberInSurah\";i:4;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:560;s:4:\"ruku\";i:494;s:11:\"hizbQuarter\";i:224;s:5:\"sajda\";b:0;}i:4;a:9:{s:6:\"number\";i:5234;s:4:\"text\";s:206:\"S\'Il vous répudie, il se peut que son Seigneur lui donne en échange des épouses meilleures que vous, musulmanes, croyantes, obéissantes, repentantes, adoratrices, jeûneuses, déjà mariées ou vierges.\";s:13:\"numberInSurah\";i:5;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:560;s:4:\"ruku\";i:494;s:11:\"hizbQuarter\";i:224;s:5:\"sajda\";b:0;}i:5;a:9:{s:6:\"number\";i:5235;s:4:\"text\";s:266:\"O vous qui avez cru! Préservez vos personnes et vos familles, d\'un Feu dont le combustible sera les gens et les pierres, surveillé par des Anges rudes, durs, ne désobéissant jamais à Allah en ce qu\'Il leur commande, et faisant strictement ce qu\'on leur ordonne.\";s:13:\"numberInSurah\";i:6;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:560;s:4:\"ruku\";i:494;s:11:\"hizbQuarter\";i:224;s:5:\"sajda\";b:0;}i:6;a:9:{s:6:\"number\";i:5236;s:4:\"text\";s:114:\"O vous qui avez mécru! Ne vous excusez pas aujourd\'hui. Vous ne serez rétribués que selon ce que vous œuvriez.\";s:13:\"numberInSurah\";i:7;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:560;s:4:\"ruku\";i:494;s:11:\"hizbQuarter\";i:224;s:5:\"sajda\";b:0;}i:7;a:9:{s:6:\"number\";i:5237;s:4:\"text\";s:433:\"O vous qui avez cru! Repentez-vous à Allah d\'un repentir sincère. Il se peut que votre Seigneur vous efface vos fautes et qu\'Il vous fasse entrer dans des Jardins sous lesquels coulent les ruisseaux, le jour où Allah épargnera l\'ignominie au Prophète et à ceux qui croient avec lui. Leur lumière courra devant eux et à leur droite; ils diront: «Seigneur, parfais-nous notre lumière et pardonne-nous. Car Tu es Omnipotent».\";s:13:\"numberInSurah\";i:8;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:561;s:4:\"ruku\";i:495;s:11:\"hizbQuarter\";i:224;s:5:\"sajda\";b:0;}i:8;a:9:{s:6:\"number\";i:5238;s:4:\"text\";s:155:\"O Prophète! Mène la lutte contre les mécréants et les hypocrites et sois rude à leur égard. Leur refuge sera l\'Enfer, et quelle mauvaise destination!\";s:13:\"numberInSurah\";i:9;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:561;s:4:\"ruku\";i:495;s:11:\"hizbQuarter\";i:224;s:5:\"sajda\";b:0;}i:9;a:9:{s:6:\"number\";i:5239;s:4:\"text\";s:337:\"Allah a cité en parabole pour ceux qui ont mécru la femme de Noé et la femme de Lot. Elles étaient sous l\'autorité de deux vertueux de Nos serviteurs. Toutes deux les trahirent et ils ne furent d\'aucune aide pour [ces deux femmes] vis-à-vis d\'Allah. Et il [leur] fut dit: «Entrez au Feu toutes les deux, avec ceux qui y entrent»,\";s:13:\"numberInSurah\";i:10;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:561;s:4:\"ruku\";i:495;s:11:\"hizbQuarter\";i:224;s:5:\"sajda\";b:0;}i:10;a:9:{s:6:\"number\";i:5240;s:4:\"text\";s:232:\"et Allah a cité en parabole pour ceux qui croient, la femme de Pharaon, quand elle dit «Seigneur, construis-moi auprès de Toi une maison dans le Paradis, et sauve-moi de Pharaon et de son œuvre; et sauve-moi des gens injustes».\";s:13:\"numberInSurah\";i:11;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:561;s:4:\"ruku\";i:495;s:11:\"hizbQuarter\";i:224;s:5:\"sajda\";b:0;}i:11;a:9:{s:6:\"number\";i:5241;s:4:\"text\";s:226:\"De même, Marie, la fille d\'\'Imran qui avait préservé sa virginité; Nous y insufflâmes alors de Notre Esprit. Elle avait déclaré véridiques les paroles de son Seigneur ainsi que Ses Livres: elle fut parmi les dévoués.\";s:13:\"numberInSurah\";i:12;s:3:\"juz\";i:28;s:6:\"manzil\";i:7;s:4:\"page\";i:561;s:4:\"ruku\";i:495;s:11:\"hizbQuarter\";i:224;s:5:\"sajda\";b:0;}}s:7:\"edition\";a:7:{s:10:\"identifier\";s:13:\"fr.hamidullah\";s:8:\"language\";s:2:\"fr\";s:4:\"name\";s:10:\"Hamidullah\";s:11:\"englishName\";s:19:\"Muhammad Hamidullah\";s:6:\"format\";s:4:\"text\";s:4:\"type\";s:11:\"translation\";s:9:\"direction\";s:3:\"ltr\";}}', 1794581397),
('quranapp-cache-surah_67_ar.uthmani', 'a:8:{s:6:\"number\";i:67;s:4:\"name\";s:31:\"سُورَةُ المُلۡكِ\";s:11:\"englishName\";s:7:\"Al-Mulk\";s:22:\"englishNameTranslation\";s:15:\"The Sovereignty\";s:14:\"revelationType\";s:6:\"Meccan\";s:13:\"numberOfAyahs\";i:30;s:5:\"ayahs\";a:30:{i:0;a:9:{s:6:\"number\";i:5242;s:4:\"text\";s:214:\"بِسۡمِ ٱللَّهِ ٱلرَّحۡمَـٰنِ ٱلرَّحِیمِ تَبَـٰرَكَ ٱلَّذِی بِیَدِهِ ٱلۡمُلۡكُ وَهُوَ عَلَىٰ كُلِّ شَیۡءࣲ قَدِیرٌ\n\";s:13:\"numberInSurah\";i:1;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:562;s:4:\"ruku\";i:496;s:11:\"hizbQuarter\";i:225;s:5:\"sajda\";b:0;}i:1;a:9:{s:6:\"number\";i:5243;s:4:\"text\";s:212:\"ٱلَّذِی خَلَقَ ٱلۡمَوۡتَ وَٱلۡحَیَوٰةَ لِیَبۡلُوَكُمۡ أَیُّكُمۡ أَحۡسَنُ عَمَلࣰاۚ وَهُوَ ٱلۡعَزِیزُ ٱلۡغَفُورُ\n\";s:13:\"numberInSurah\";i:2;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:562;s:4:\"ruku\";i:496;s:11:\"hizbQuarter\";i:225;s:5:\"sajda\";b:0;}i:2;a:9:{s:6:\"number\";i:5244;s:4:\"text\";s:274:\"ٱلَّذِی خَلَقَ سَبۡعَ سَمَـٰوَ ٰ⁠تࣲ طِبَاقࣰاۖ مَّا تَرَىٰ فِی خَلۡقِ ٱلرَّحۡمَـٰنِ مِن تَفَـٰوُتࣲۖ فَٱرۡجِعِ ٱلۡبَصَرَ هَلۡ تَرَىٰ مِن فُطُورࣲ\n\";s:13:\"numberInSurah\";i:3;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:562;s:4:\"ruku\";i:496;s:11:\"hizbQuarter\";i:225;s:5:\"sajda\";b:0;}i:3;a:9:{s:6:\"number\";i:5245;s:4:\"text\";s:170:\"ثُمَّ ٱرۡجِعِ ٱلۡبَصَرَ كَرَّتَیۡنِ یَنقَلِبۡ إِلَیۡكَ ٱلۡبَصَرُ خَاسِئࣰا وَهُوَ حَسِیرࣱ\n\";s:13:\"numberInSurah\";i:4;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:562;s:4:\"ruku\";i:496;s:11:\"hizbQuarter\";i:225;s:5:\"sajda\";b:0;}i:4;a:9:{s:6:\"number\";i:5246;s:4:\"text\";s:267:\"وَلَقَدۡ زَیَّنَّا ٱلسَّمَاۤءَ ٱلدُّنۡیَا بِمَصَـٰبِیحَ وَجَعَلۡنَـٰهَا رُجُومࣰا لِّلشَّیَـٰطِینِۖ وَأَعۡتَدۡنَا لَهُمۡ عَذَابَ ٱلسَّعِیرِ\n\";s:13:\"numberInSurah\";i:5;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:562;s:4:\"ruku\";i:496;s:11:\"hizbQuarter\";i:225;s:5:\"sajda\";b:0;}i:5;a:9:{s:6:\"number\";i:5247;s:4:\"text\";s:141:\"وَلِلَّذِینَ كَفَرُوا۟ بِرَبِّهِمۡ عَذَابُ جَهَنَّمَۖ وَبِئۡسَ ٱلۡمَصِیرُ\n\";s:13:\"numberInSurah\";i:6;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:562;s:4:\"ruku\";i:496;s:11:\"hizbQuarter\";i:225;s:5:\"sajda\";b:0;}i:6;a:9:{s:6:\"number\";i:5248;s:4:\"text\";s:121:\"إِذَاۤ أُلۡقُوا۟ فِیهَا سَمِعُوا۟ لَهَا شَهِیقࣰا وَهِیَ تَفُورُ\n\";s:13:\"numberInSurah\";i:7;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:562;s:4:\"ruku\";i:496;s:11:\"hizbQuarter\";i:225;s:5:\"sajda\";b:0;}i:7;a:9:{s:6:\"number\";i:5249;s:4:\"text\";s:223:\"تَكَادُ تَمَیَّزُ مِنَ ٱلۡغَیۡظِۖ كُلَّمَاۤ أُلۡقِیَ فِیهَا فَوۡجࣱ سَأَلَهُمۡ خَزَنَتُهَاۤ أَلَمۡ یَأۡتِكُمۡ نَذِیرࣱ\n\";s:13:\"numberInSurah\";i:8;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:562;s:4:\"ruku\";i:496;s:11:\"hizbQuarter\";i:225;s:5:\"sajda\";b:0;}i:8;a:9:{s:6:\"number\";i:5250;s:4:\"text\";s:253:\"قَالُوا۟ بَلَىٰ قَدۡ جَاۤءَنَا نَذِیرࣱ فَكَذَّبۡنَا وَقُلۡنَا مَا نَزَّلَ ٱللَّهُ مِن شَیۡءٍ إِنۡ أَنتُمۡ إِلَّا فِی ضَلَـٰلࣲ كَبِیرࣲ\n\";s:13:\"numberInSurah\";i:9;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:562;s:4:\"ruku\";i:496;s:11:\"hizbQuarter\";i:225;s:5:\"sajda\";b:0;}i:9;a:9:{s:6:\"number\";i:5251;s:4:\"text\";s:157:\"وَقَالُوا۟ لَوۡ كُنَّا نَسۡمَعُ أَوۡ نَعۡقِلُ مَا كُنَّا فِیۤ أَصۡحَـٰبِ ٱلسَّعِیرِ\n\";s:13:\"numberInSurah\";i:10;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:562;s:4:\"ruku\";i:496;s:11:\"hizbQuarter\";i:225;s:5:\"sajda\";b:0;}i:10;a:9:{s:6:\"number\";i:5252;s:4:\"text\";s:122:\"فَٱعۡتَرَفُوا۟ بِذَنۢبِهِمۡ فَسُحۡقࣰا لِّأَصۡحَـٰبِ ٱلسَّعِیرِ\n\";s:13:\"numberInSurah\";i:11;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:562;s:4:\"ruku\";i:496;s:11:\"hizbQuarter\";i:225;s:5:\"sajda\";b:0;}i:11;a:9:{s:6:\"number\";i:5253;s:4:\"text\";s:160:\"إِنَّ ٱلَّذِینَ یَخۡشَوۡنَ رَبَّهُم بِٱلۡغَیۡبِ لَهُم مَّغۡفِرَةࣱ وَأَجۡرࣱ كَبِیرࣱ\n\";s:13:\"numberInSurah\";i:12;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:562;s:4:\"ruku\";i:496;s:11:\"hizbQuarter\";i:225;s:5:\"sajda\";b:0;}i:12;a:9:{s:6:\"number\";i:5254;s:4:\"text\";s:161:\"وَأَسِرُّوا۟ قَوۡلَكُمۡ أَوِ ٱجۡهَرُوا۟ بِهِۦۤۖ إِنَّهُۥ عَلِیمُۢ بِذَاتِ ٱلصُّدُورِ\n\";s:13:\"numberInSurah\";i:13;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:563;s:4:\"ruku\";i:496;s:11:\"hizbQuarter\";i:225;s:5:\"sajda\";b:0;}i:13;a:9:{s:6:\"number\";i:5255;s:4:\"text\";s:105:\"أَلَا یَعۡلَمُ مَنۡ خَلَقَ وَهُوَ ٱللَّطِیفُ ٱلۡخَبِیرُ\n\";s:13:\"numberInSurah\";i:14;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:563;s:4:\"ruku\";i:496;s:11:\"hizbQuarter\";i:225;s:5:\"sajda\";b:0;}i:14;a:9:{s:6:\"number\";i:5256;s:4:\"text\";s:231:\"هُوَ ٱلَّذِی جَعَلَ لَكُمُ ٱلۡأَرۡضَ ذَلُولࣰا فَٱمۡشُوا۟ فِی مَنَاكِبِهَا وَكُلُوا۟ مِن رِّزۡقِهِۦۖ وَإِلَیۡهِ ٱلنُّشُورُ\n\";s:13:\"numberInSurah\";i:15;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:563;s:4:\"ruku\";i:497;s:11:\"hizbQuarter\";i:225;s:5:\"sajda\";b:0;}i:15;a:9:{s:6:\"number\";i:5257;s:4:\"text\";s:155:\"ءَأَمِنتُم مَّن فِی ٱلسَّمَاۤءِ أَن یَخۡسِفَ بِكُمُ ٱلۡأَرۡضَ فَإِذَا هِیَ تَمُورُ\n\";s:13:\"numberInSurah\";i:16;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:563;s:4:\"ruku\";i:497;s:11:\"hizbQuarter\";i:225;s:5:\"sajda\";b:0;}i:16;a:9:{s:6:\"number\";i:5258;s:4:\"text\";s:189:\"أَمۡ أَمِنتُم مَّن فِی ٱلسَّمَاۤءِ أَن یُرۡسِلَ عَلَیۡكُمۡ حَاصِبࣰاۖ فَسَتَعۡلَمُونَ كَیۡفَ نَذِیرِ\n\";s:13:\"numberInSurah\";i:17;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:563;s:4:\"ruku\";i:497;s:11:\"hizbQuarter\";i:225;s:5:\"sajda\";b:0;}i:17;a:9:{s:6:\"number\";i:5259;s:4:\"text\";s:122:\"وَلَقَدۡ كَذَّبَ ٱلَّذِینَ مِن قَبۡلِهِمۡ فَكَیۡفَ كَانَ نَكِیرِ\n\";s:13:\"numberInSurah\";i:18;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:563;s:4:\"ruku\";i:497;s:11:\"hizbQuarter\";i:225;s:5:\"sajda\";b:0;}i:18;a:9:{s:6:\"number\";i:5260;s:4:\"text\";s:276:\"أَوَلَمۡ یَرَوۡا۟ إِلَى ٱلطَّیۡرِ فَوۡقَهُمۡ صَـٰۤفَّـٰتࣲ وَیَقۡبِضۡنَۚ مَا یُمۡسِكُهُنَّ إِلَّا ٱلرَّحۡمَـٰنُۚ إِنَّهُۥ بِكُلِّ شَیۡءِۭ بَصِیرٌ\n\";s:13:\"numberInSurah\";i:19;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:563;s:4:\"ruku\";i:497;s:11:\"hizbQuarter\";i:225;s:5:\"sajda\";b:0;}i:19;a:9:{s:6:\"number\";i:5261;s:4:\"text\";s:224:\"أَمَّنۡ هَـٰذَا ٱلَّذِی هُوَ جُندࣱ لَّكُمۡ یَنصُرُكُم مِّن دُونِ ٱلرَّحۡمَـٰنِۚ إِنِ ٱلۡكَـٰفِرُونَ إِلَّا فِی غُرُورٍ\n\";s:13:\"numberInSurah\";i:20;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:563;s:4:\"ruku\";i:497;s:11:\"hizbQuarter\";i:225;s:5:\"sajda\";b:0;}i:20;a:9:{s:6:\"number\";i:5262;s:4:\"text\";s:185:\"أَمَّنۡ هَـٰذَا ٱلَّذِی یَرۡزُقُكُمۡ إِنۡ أَمۡسَكَ رِزۡقَهُۥۚ بَل لَّجُّوا۟ فِی عُتُوࣲّ وَنُفُورٍ\n\";s:13:\"numberInSurah\";i:21;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:563;s:4:\"ruku\";i:497;s:11:\"hizbQuarter\";i:225;s:5:\"sajda\";b:0;}i:21;a:9:{s:6:\"number\";i:5263;s:4:\"text\";s:206:\"أَفَمَن یَمۡشِی مُكِبًّا عَلَىٰ وَجۡهِهِۦۤ أَهۡدَىٰۤ أَمَّن یَمۡشِی سَوِیًّا عَلَىٰ صِرَ ٰ⁠طࣲ مُّسۡتَقِیمࣲ\n\";s:13:\"numberInSurah\";i:22;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:563;s:4:\"ruku\";i:497;s:11:\"hizbQuarter\";i:225;s:5:\"sajda\";b:0;}i:22;a:9:{s:6:\"number\";i:5264;s:4:\"text\";s:223:\"قُلۡ هُوَ ٱلَّذِیۤ أَنشَأَكُمۡ وَجَعَلَ لَكُمُ ٱلسَّمۡعَ وَٱلۡأَبۡصَـٰرَ وَٱلۡأَفۡـِٔدَةَۚ قَلِیلࣰا مَّا تَشۡكُرُونَ\n\";s:13:\"numberInSurah\";i:23;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:563;s:4:\"ruku\";i:497;s:11:\"hizbQuarter\";i:225;s:5:\"sajda\";b:0;}i:23;a:9:{s:6:\"number\";i:5265;s:4:\"text\";s:124:\"قُلۡ هُوَ ٱلَّذِی ذَرَأَكُمۡ فِی ٱلۡأَرۡضِ وَإِلَیۡهِ تُحۡشَرُونَ\n\";s:13:\"numberInSurah\";i:24;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:563;s:4:\"ruku\";i:497;s:11:\"hizbQuarter\";i:225;s:5:\"sajda\";b:0;}i:24;a:9:{s:6:\"number\";i:5266;s:4:\"text\";s:117:\"وَیَقُولُونَ مَتَىٰ هَـٰذَا ٱلۡوَعۡدُ إِن كُنتُمۡ صَـٰدِقِینَ\n\";s:13:\"numberInSurah\";i:25;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:563;s:4:\"ruku\";i:497;s:11:\"hizbQuarter\";i:225;s:5:\"sajda\";b:0;}i:25;a:9:{s:6:\"number\";i:5267;s:4:\"text\";s:141:\"قُلۡ إِنَّمَا ٱلۡعِلۡمُ عِندَ ٱللَّهِ وَإِنَّمَاۤ أَنَا۠ نَذِیرࣱ مُّبِینࣱ\n\";s:13:\"numberInSurah\";i:26;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:563;s:4:\"ruku\";i:497;s:11:\"hizbQuarter\";i:225;s:5:\"sajda\";b:0;}i:26;a:9:{s:6:\"number\";i:5268;s:4:\"text\";s:214:\"فَلَمَّا رَأَوۡهُ زُلۡفَةࣰ سِیۤـَٔتۡ وُجُوهُ ٱلَّذِینَ كَفَرُوا۟ وَقِیلَ هَـٰذَا ٱلَّذِی كُنتُم بِهِۦ تَدَّعُونَ\n\";s:13:\"numberInSurah\";i:27;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:564;s:4:\"ruku\";i:497;s:11:\"hizbQuarter\";i:225;s:5:\"sajda\";b:0;}i:27;a:9:{s:6:\"number\";i:5269;s:4:\"text\";s:232:\"قُلۡ أَرَءَیۡتُمۡ إِنۡ أَهۡلَكَنِیَ ٱللَّهُ وَمَن مَّعِیَ أَوۡ رَحِمَنَا فَمَن یُجِیرُ ٱلۡكَـٰفِرِینَ مِنۡ عَذَابٍ أَلِیمࣲ\n\";s:13:\"numberInSurah\";i:28;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:564;s:4:\"ruku\";i:497;s:11:\"hizbQuarter\";i:225;s:5:\"sajda\";b:0;}i:28;a:9:{s:6:\"number\";i:5270;s:4:\"text\";s:215:\"قُلۡ هُوَ ٱلرَّحۡمَـٰنُ ءَامَنَّا بِهِۦ وَعَلَیۡهِ تَوَكَّلۡنَاۖ فَسَتَعۡلَمُونَ مَنۡ هُوَ فِی ضَلَـٰلࣲ مُّبِینࣲ\n\";s:13:\"numberInSurah\";i:29;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:564;s:4:\"ruku\";i:497;s:11:\"hizbQuarter\";i:225;s:5:\"sajda\";b:0;}i:29;a:9:{s:6:\"number\";i:5271;s:4:\"text\";s:166:\"قُلۡ أَرَءَیۡتُمۡ إِنۡ أَصۡبَحَ مَاۤؤُكُمۡ غَوۡرࣰا فَمَن یَأۡتِیكُم بِمَاۤءࣲ مَّعِینِۭ\n\";s:13:\"numberInSurah\";i:30;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:564;s:4:\"ruku\";i:497;s:11:\"hizbQuarter\";i:225;s:5:\"sajda\";b:0;}}s:7:\"edition\";a:7:{s:10:\"identifier\";s:27:\"quran-uthmani-quran-academy\";s:8:\"language\";s:2:\"ar\";s:4:\"name\";s:67:\"القرآن الكريم برسم العثماني (quran-academy)\";s:11:\"englishName\";s:78:\"Modified Quran Uthmani Text from the Quran Academy to work with the Kitab font\";s:6:\"format\";s:4:\"text\";s:4:\"type\";s:5:\"quran\";s:9:\"direction\";s:3:\"rtl\";}}', 1794581398),
('quranapp-cache-surah_67_fr.hamidullah', 'a:8:{s:6:\"number\";i:67;s:4:\"name\";s:31:\"سُورَةُ المُلۡكِ\";s:11:\"englishName\";s:7:\"Al-Mulk\";s:22:\"englishNameTranslation\";s:15:\"The Sovereignty\";s:14:\"revelationType\";s:6:\"Meccan\";s:13:\"numberOfAyahs\";i:30;s:5:\"ayahs\";a:30:{i:0;a:9:{s:6:\"number\";i:5242;s:4:\"text\";s:75:\"Béni soit celui dans la main de qui est la royauté, et Il est Omnipotent.\";s:13:\"numberInSurah\";i:1;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:562;s:4:\"ruku\";i:496;s:11:\"hizbQuarter\";i:225;s:5:\"sajda\";b:0;}i:1;a:9:{s:6:\"number\";i:5243;s:4:\"text\";s:154:\"Celui qui a créé la mort et la vie afin de vous éprouver (et de savoir) qui de vous est le meilleur en œuvre, et c\'est Lui le Puissant, le Pardonneur.\";s:13:\"numberInSurah\";i:2;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:562;s:4:\"ruku\";i:496;s:11:\"hizbQuarter\";i:225;s:5:\"sajda\";b:0;}i:2;a:9:{s:6:\"number\";i:5244;s:4:\"text\";s:181:\"Celui qui a créé sept cieux superposés sans que tu voies de disproportion en la création du Tout Miséricordieux. Ramène [sur elle] le regard. Y vois-tu une brèche quelconque?\";s:13:\"numberInSurah\";i:3;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:562;s:4:\"ruku\";i:496;s:11:\"hizbQuarter\";i:225;s:5:\"sajda\";b:0;}i:3;a:9:{s:6:\"number\";i:5245;s:4:\"text\";s:84:\"Puis, retourne ton regard à deux fois: le regard te reviendra humilié et frustré.\";s:13:\"numberInSurah\";i:4;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:562;s:4:\"ruku\";i:496;s:11:\"hizbQuarter\";i:225;s:5:\"sajda\";b:0;}i:4;a:9:{s:6:\"number\";i:5246;s:4:\"text\";s:208:\"Nous avons effectivement embelli le ciel le plus proche avec des lampes [des étoiles] dont Nous avons fait des projectiles pour lapider les diables et Nous leur avons préparé le châtiment de la Fournaise.\";s:13:\"numberInSurah\";i:5;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:562;s:4:\"ruku\";i:496;s:11:\"hizbQuarter\";i:225;s:5:\"sajda\";b:0;}i:5;a:9:{s:6:\"number\";i:5247;s:4:\"text\";s:101:\"Ceux qui ont mécru à leur Seigneur auront le châtiment de l\'Enfer. Et quelle mauvaise destination!\";s:13:\"numberInSurah\";i:6;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:562;s:4:\"ruku\";i:496;s:11:\"hizbQuarter\";i:225;s:5:\"sajda\";b:0;}i:6;a:9:{s:6:\"number\";i:5248;s:4:\"text\";s:87:\"Quand ils y seront jetés, ils lui entendront un gémissement, tandis qu\'il bouillonne.\";s:13:\"numberInSurah\";i:7;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:562;s:4:\"ruku\";i:496;s:11:\"hizbQuarter\";i:225;s:5:\"sajda\";b:0;}i:7;a:9:{s:6:\"number\";i:5249;s:4:\"text\";s:161:\"Peu s\'en faut que, de rage, il n\'éclate. Toutes les fois qu\'un groupe y est jeté, ses gardiens leur demandent: «Quoi! ne vous est-il pas venu d\'avertisseur?»\";s:13:\"numberInSurah\";i:8;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:562;s:4:\"ruku\";i:496;s:11:\"hizbQuarter\";i:225;s:5:\"sajda\";b:0;}i:8;a:9:{s:6:\"number\";i:5250;s:4:\"text\";s:186:\"Ils dirent: «Mais si! un avertisseur nous était venu certes, mais nous avons crié au mensonge et avons dit: Allah n\'a rien fait descendre: vous n\'êtes que dans un grand égarement».\";s:13:\"numberInSurah\";i:9;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:562;s:4:\"ruku\";i:496;s:11:\"hizbQuarter\";i:225;s:5:\"sajda\";b:0;}i:9;a:9:{s:6:\"number\";i:5251;s:4:\"text\";s:108:\"Et ils dirent: «Si nous avions écouté ou raisonné, nous ne serions pas parmi les gens de la Fournaise».\";s:13:\"numberInSurah\";i:10;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:562;s:4:\"ruku\";i:496;s:11:\"hizbQuarter\";i:225;s:5:\"sajda\";b:0;}i:10;a:9:{s:6:\"number\";i:5252;s:4:\"text\";s:86:\"Ils ont reconnu leur péché. Que les gens de la Fournaise soient anéantis à jamais.\";s:13:\"numberInSurah\";i:11;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:562;s:4:\"ruku\";i:496;s:11:\"hizbQuarter\";i:225;s:5:\"sajda\";b:0;}i:11;a:9:{s:6:\"number\";i:5253;s:4:\"text\";s:109:\"Ceux qui redoutent leur Seigneur bien qu\'ils ne L\'aient jamais vu auront un pardon et une grande récompense.\";s:13:\"numberInSurah\";i:12;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:562;s:4:\"ruku\";i:496;s:11:\"hizbQuarter\";i:225;s:5:\"sajda\";b:0;}i:12;a:9:{s:6:\"number\";i:5254;s:4:\"text\";s:89:\"Que vous cachiez votre parole ou la divulguiez Il connaît bien le contenu des poitrines.\";s:13:\"numberInSurah\";i:13;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:563;s:4:\"ruku\";i:496;s:11:\"hizbQuarter\";i:225;s:5:\"sajda\";b:0;}i:13;a:9:{s:6:\"number\";i:5255;s:4:\"text\";s:102:\"Ne connaît-Il pas ce qu\'Il a créé alors que c\'est Lui le Compatissant, le Parfaitement Connaisseur.\";s:13:\"numberInSurah\";i:14;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:563;s:4:\"ruku\";i:496;s:11:\"hizbQuarter\";i:225;s:5:\"sajda\";b:0;}i:14;a:9:{s:6:\"number\";i:5256;s:4:\"text\";s:139:\"C\'est Lui qui vous a soumis la terre: parcourez donc ses grandes étendues. Mangez de ce qu\'Il vous fournit. Vers Lui est la Résurrection.\";s:13:\"numberInSurah\";i:15;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:563;s:4:\"ruku\";i:497;s:11:\"hizbQuarter\";i:225;s:5:\"sajda\";b:0;}i:15;a:9:{s:6:\"number\";i:5257;s:4:\"text\";s:99:\"Etes-vous à l\'abri que Celui qui est au ciel vous enfouisse en la terre? Et voici qu\'elle tremble!\";s:13:\"numberInSurah\";i:16;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:563;s:4:\"ruku\";i:497;s:11:\"hizbQuarter\";i:225;s:5:\"sajda\";b:0;}i:16;a:9:{s:6:\"number\";i:5258;s:4:\"text\";s:137:\"Ou êtes-vous à l\'abri que Celui qui est au ciel envoie contre vous un ouragan de pierres? Vous saurez ainsi quel fut Mon avertissement.\";s:13:\"numberInSurah\";i:17;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:563;s:4:\"ruku\";i:497;s:11:\"hizbQuarter\";i:225;s:5:\"sajda\";b:0;}i:17;a:9:{s:6:\"number\";i:5259;s:4:\"text\";s:87:\"En effet, ceux d\'avant eux avaient crié au mensonge. Quelle fut alors Ma réprobation!\";s:13:\"numberInSurah\";i:18;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:563;s:4:\"ruku\";i:497;s:11:\"hizbQuarter\";i:225;s:5:\"sajda\";b:0;}i:18;a:9:{s:6:\"number\";i:5260;s:4:\"text\";s:178:\"N\'ont-ils pas vu les oiseaux au-dessus d\'eux, déployant et repliant leurs ailes tour à tour? Seul le Tout Miséricordieux les soutient. Car Il est sur toute chose, Clairvoyant.\";s:13:\"numberInSurah\";i:19;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:563;s:4:\"ruku\";i:497;s:11:\"hizbQuarter\";i:225;s:5:\"sajda\";b:0;}i:19;a:9:{s:6:\"number\";i:5261;s:4:\"text\";s:176:\"Quel est celui qui constituerait pour vous une armée [capable] de vous secourir, en dehors du Tout Miséricordieux? En vérité les mécréants sont dans l\'illusion complète.\";s:13:\"numberInSurah\";i:20;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:563;s:4:\"ruku\";i:497;s:11:\"hizbQuarter\";i:225;s:5:\"sajda\";b:0;}i:20;a:9:{s:6:\"number\";i:5262;s:4:\"text\";s:160:\"Ou quel est celui qui vous donnera votre subsistance s\'Il s\'arrête de fournir Son attribution? Mais ils persistent dans leur insolence et dans leur répulsion.\";s:13:\"numberInSurah\";i:21;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:563;s:4:\"ruku\";i:497;s:11:\"hizbQuarter\";i:225;s:5:\"sajda\";b:0;}i:21;a:9:{s:6:\"number\";i:5263;s:4:\"text\";s:112:\"Qui est donc mieux guidé? Celui qui marche face contre terre ou celui qui marche redressé sur un chemin droit.\";s:13:\"numberInSurah\";i:22;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:563;s:4:\"ruku\";i:497;s:11:\"hizbQuarter\";i:225;s:5:\"sajda\";b:0;}i:22;a:9:{s:6:\"number\";i:5264;s:4:\"text\";s:128:\"Dis: «C\'est Lui qui vous a créés et vous a donné l\'ouïe, les yeux et les cœurs». Mais vous êtes rarement reconnaissants!\";s:13:\"numberInSurah\";i:23;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:563;s:4:\"ruku\";i:497;s:11:\"hizbQuarter\";i:225;s:5:\"sajda\";b:0;}i:23;a:9:{s:6:\"number\";i:5265;s:4:\"text\";s:99:\"Dis: «C\'est Lui qui vous a répandus sur la terre, et c\'est vers Lui que vous serez rassemblés».\";s:13:\"numberInSurah\";i:24;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:563;s:4:\"ruku\";i:497;s:11:\"hizbQuarter\";i:225;s:5:\"sajda\";b:0;}i:24;a:9:{s:6:\"number\";i:5266;s:4:\"text\";s:68:\"Et ils disent: «A quand cette promesse si vous êtes véridiques?»\";s:13:\"numberInSurah\";i:25;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:563;s:4:\"ruku\";i:497;s:11:\"hizbQuarter\";i:225;s:5:\"sajda\";b:0;}i:25;a:9:{s:6:\"number\";i:5267;s:4:\"text\";s:86:\"Dis: «Allah seul [en] a la connaissance. Et moi je ne suis qu\'un avertisseur clair».\";s:13:\"numberInSurah\";i:26;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:563;s:4:\"ruku\";i:497;s:11:\"hizbQuarter\";i:225;s:5:\"sajda\";b:0;}i:26;a:9:{s:6:\"number\";i:5268;s:4:\"text\";s:158:\"Puis, quand ils verront (le châtiment) de près, les visages de ceux qui ont mécru seront affligés. Et il leur sera dit: «Voilà ce que vous réclamiez».\";s:13:\"numberInSurah\";i:27;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:564;s:4:\"ruku\";i:497;s:11:\"hizbQuarter\";i:225;s:5:\"sajda\";b:0;}i:27;a:9:{s:6:\"number\";i:5269;s:4:\"text\";s:185:\"Dis: «Que vous en semble? Qu\'Allah me fasse périr ainsi que ceux qui sont avec moi ou qu\'Il nous fasse miséricorde, qui protégera alors les mécréants d\'un châtiment douloureux?»\";s:13:\"numberInSurah\";i:28;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:564;s:4:\"ruku\";i:497;s:11:\"hizbQuarter\";i:225;s:5:\"sajda\";b:0;}i:28;a:9:{s:6:\"number\";i:5270;s:4:\"text\";s:173:\"Dis: «C\'est Lui, le Tout Miséricordieux. Nous croyons en Lui et c\'est en Lui que nous plaçons notre confiance. Vous saurez bientôt qui est dans un égarement évident».\";s:13:\"numberInSurah\";i:29;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:564;s:4:\"ruku\";i:497;s:11:\"hizbQuarter\";i:225;s:5:\"sajda\";b:0;}i:29;a:9:{s:6:\"number\";i:5271;s:4:\"text\";s:133:\"Dis: «Que vous en semble? Si votre eau était absorbée au plus profond de la terre, qui donc vous apporterait de l\'eau de source?»\";s:13:\"numberInSurah\";i:30;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:564;s:4:\"ruku\";i:497;s:11:\"hizbQuarter\";i:225;s:5:\"sajda\";b:0;}}s:7:\"edition\";a:7:{s:10:\"identifier\";s:13:\"fr.hamidullah\";s:8:\"language\";s:2:\"fr\";s:4:\"name\";s:10:\"Hamidullah\";s:11:\"englishName\";s:19:\"Muhammad Hamidullah\";s:6:\"format\";s:4:\"text\";s:4:\"type\";s:11:\"translation\";s:9:\"direction\";s:3:\"ltr\";}}', 1794581398),
('quranapp-cache-surah_68_ar.uthmani', 'a:8:{s:6:\"number\";i:68;s:4:\"name\";s:31:\"سُورَةُ القَلَمِ\";s:11:\"englishName\";s:8:\"Al-Qalam\";s:22:\"englishNameTranslation\";s:7:\"The Pen\";s:14:\"revelationType\";s:6:\"Meccan\";s:13:\"numberOfAyahs\";i:52;s:5:\"ayahs\";a:52:{i:0;a:9:{s:6:\"number\";i:5272;s:4:\"text\";s:140:\"بِسۡمِ ٱللَّهِ ٱلرَّحۡمَـٰنِ ٱلرَّحِیمِ نۤۚ وَٱلۡقَلَمِ وَمَا یَسۡطُرُونَ\n\";s:13:\"numberInSurah\";i:1;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:564;s:4:\"ruku\";i:498;s:11:\"hizbQuarter\";i:226;s:5:\"sajda\";b:0;}i:1;a:9:{s:6:\"number\";i:5273;s:4:\"text\";s:80:\"مَاۤ أَنتَ بِنِعۡمَةِ رَبِّكَ بِمَجۡنُونࣲ\n\";s:13:\"numberInSurah\";i:2;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:564;s:4:\"ruku\";i:498;s:11:\"hizbQuarter\";i:226;s:5:\"sajda\";b:0;}i:2;a:9:{s:6:\"number\";i:5274;s:4:\"text\";s:76:\"وَإِنَّ لَكَ لَأَجۡرًا غَیۡرَ مَمۡنُونࣲ\n\";s:13:\"numberInSurah\";i:3;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:564;s:4:\"ruku\";i:498;s:11:\"hizbQuarter\";i:226;s:5:\"sajda\";b:0;}i:3;a:9:{s:6:\"number\";i:5275;s:4:\"text\";s:65:\"وَإِنَّكَ لَعَلَىٰ خُلُقٍ عَظِیمࣲ\n\";s:13:\"numberInSurah\";i:4;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:564;s:4:\"ruku\";i:498;s:11:\"hizbQuarter\";i:226;s:5:\"sajda\";b:0;}i:4;a:9:{s:6:\"number\";i:5276;s:4:\"text\";s:52:\"فَسَتُبۡصِرُ وَیُبۡصِرُونَ\n\";s:13:\"numberInSurah\";i:5;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:564;s:4:\"ruku\";i:498;s:11:\"hizbQuarter\";i:226;s:5:\"sajda\";b:0;}i:5;a:9:{s:6:\"number\";i:5277;s:4:\"text\";s:50:\"بِأَییِّكُمُ ٱلۡمَفۡتُونُ\n\";s:13:\"numberInSurah\";i:6;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:564;s:4:\"ruku\";i:498;s:11:\"hizbQuarter\";i:226;s:5:\"sajda\";b:0;}i:6;a:9:{s:6:\"number\";i:5278;s:4:\"text\";s:165:\"إِنَّ رَبَّكَ هُوَ أَعۡلَمُ بِمَن ضَلَّ عَن سَبِیلِهِۦ وَهُوَ أَعۡلَمُ بِٱلۡمُهۡتَدِینَ\n\";s:13:\"numberInSurah\";i:7;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:564;s:4:\"ruku\";i:498;s:11:\"hizbQuarter\";i:226;s:5:\"sajda\";b:0;}i:7;a:9:{s:6:\"number\";i:5279;s:4:\"text\";s:55:\"فَلَا تُطِعِ ٱلۡمُكَذِّبِینَ\n\";s:13:\"numberInSurah\";i:8;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:564;s:4:\"ruku\";i:498;s:11:\"hizbQuarter\";i:226;s:5:\"sajda\";b:0;}i:8;a:9:{s:6:\"number\";i:5280;s:4:\"text\";s:70:\"وَدُّوا۟ لَوۡ تُدۡهِنُ فَیُدۡهِنُونَ\n\";s:13:\"numberInSurah\";i:9;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:564;s:4:\"ruku\";i:498;s:11:\"hizbQuarter\";i:226;s:5:\"sajda\";b:0;}i:9;a:9:{s:6:\"number\";i:5281;s:4:\"text\";s:70:\"وَلَا تُطِعۡ كُلَّ حَلَّافࣲ مَّهِینٍ\n\";s:13:\"numberInSurah\";i:10;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:564;s:4:\"ruku\";i:498;s:11:\"hizbQuarter\";i:226;s:5:\"sajda\";b:0;}i:10;a:9:{s:6:\"number\";i:5282;s:4:\"text\";s:61:\"هَمَّازࣲ مَّشَّاۤءِۭ بِنَمِیمࣲ\n\";s:13:\"numberInSurah\";i:11;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:564;s:4:\"ruku\";i:498;s:11:\"hizbQuarter\";i:226;s:5:\"sajda\";b:0;}i:11;a:9:{s:6:\"number\";i:5283;s:4:\"text\";s:75:\"مَّنَّاعࣲ لِّلۡخَیۡرِ مُعۡتَدٍ أَثِیمٍ\n\";s:13:\"numberInSurah\";i:12;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:564;s:4:\"ruku\";i:498;s:11:\"hizbQuarter\";i:226;s:5:\"sajda\";b:0;}i:12;a:9:{s:6:\"number\";i:5284;s:4:\"text\";s:66:\"عُتُلِّۭ بَعۡدَ ذَ ٰ⁠لِكَ زَنِیمٍ\n\";s:13:\"numberInSurah\";i:13;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:564;s:4:\"ruku\";i:498;s:11:\"hizbQuarter\";i:226;s:5:\"sajda\";b:0;}i:13;a:9:{s:6:\"number\";i:5285;s:4:\"text\";s:56:\"أَن كَانَ ذَا مَالࣲ وَبَنِینَ\n\";s:13:\"numberInSurah\";i:14;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:564;s:4:\"ruku\";i:498;s:11:\"hizbQuarter\";i:226;s:5:\"sajda\";b:0;}i:14;a:9:{s:6:\"number\";i:5286;s:4:\"text\";s:131:\"إِذَا تُتۡلَىٰ عَلَیۡهِ ءَایَـٰتُنَا قَالَ أَسَـٰطِیرُ ٱلۡأَوَّلِینَ\n\";s:13:\"numberInSurah\";i:15;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:564;s:4:\"ruku\";i:498;s:11:\"hizbQuarter\";i:226;s:5:\"sajda\";b:0;}i:15;a:9:{s:6:\"number\";i:5287;s:4:\"text