('quranapp-cache-surah_74_fr.hamidullah', 'a:8:{s:6:\"number\";i:74;s:4:\"name\";s:39:\"سُورَةُ المُدَّثِّرِ\";s:11:\"englishName\";s:14:\"Al-Muddaththir\";s:22:\"englishNameTranslation\";s:15:\"The Cloaked One\";s:14:\"revelationType\";s:6:\"Meccan\";s:13:\"numberOfAyahs\";i:56;s:5:\"ayahs\";a:56:{i:0;a:9:{s:6:\"number\";i:5496;s:4:\"text\";s:43:\"O, toi (Muhammad)! Le revêtu d\'un manteau!\";s:13:\"numberInSurah\";i:1;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:575;s:4:\"ruku\";i:510;s:11:\"hizbQuarter\";i:230;s:5:\"sajda\";b:0;}i:1;a:9:{s:6:\"number\";i:5497;s:4:\"text\";s:21:\"Lève-toi et avertis.\";s:13:\"numberInSurah\";i:2;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:575;s:4:\"ruku\";i:510;s:11:\"hizbQuarter\";i:230;s:5:\"sajda\";b:0;}i:2;a:9:{s:6:\"number\";i:5498;s:4:\"text\";s:42:\"Et de ton Seigneur, célèbre la grandeur.\";s:13:\"numberInSurah\";i:3;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:575;s:4:\"ruku\";i:510;s:11:\"hizbQuarter\";i:230;s:5:\"sajda\";b:0;}i:3;a:9:{s:6:\"number\";i:5499;s:4:\"text\";s:31:\"Et tes vêtements, purifie-les.\";s:13:\"numberInSurah\";i:4;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:575;s:4:\"ruku\";i:510;s:11:\"hizbQuarter\";i:230;s:5:\"sajda\";b:0;}i:4;a:9:{s:6:\"number\";i:5500;s:4:\"text\";s:32:\"Et de tout péché, écarte-toi.\";s:13:\"numberInSurah\";i:5;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:575;s:4:\"ruku\";i:510;s:11:\"hizbQuarter\";i:230;s:5:\"sajda\";b:0;}i:5;a:9:{s:6:\"number\";i:5501;s:4:\"text\";s:50:\"Et ne donne pas dans le but de recevoir davantage.\";s:13:\"numberInSurah\";i:6;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:575;s:4:\"ruku\";i:510;s:11:\"hizbQuarter\";i:230;s:5:\"sajda\";b:0;}i:6;a:9:{s:6:\"number\";i:5502;s:4:\"text\";s:29:\"Et pour ton Seigneur, endure.\";s:13:\"numberInSurah\";i:7;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:575;s:4:\"ruku\";i:510;s:11:\"hizbQuarter\";i:230;s:5:\"sajda\";b:0;}i:7;a:9:{s:6:\"number\";i:5503;s:4:\"text\";s:28:\"Quand on sonnera du Clairon,\";s:13:\"numberInSurah\";i:8;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:575;s:4:\"ruku\";i:510;s:11:\"hizbQuarter\";i:230;s:5:\"sajda\";b:0;}i:8;a:9:{s:6:\"number\";i:5504;s:4:\"text\";s:42:\"alors, ce jour-là sera un jour difficile,\";s:13:\"numberInSurah\";i:9;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:575;s:4:\"ruku\";i:510;s:11:\"hizbQuarter\";i:230;s:5:\"sajda\";b:0;}i:9;a:9:{s:6:\"number\";i:5505;s:4:\"text\";s:32:\"pas facile pour les mécréants.\";s:13:\"numberInSurah\";i:10;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:575;s:4:\"ruku\";i:510;s:11:\"hizbQuarter\";i:230;s:5:\"sajda\";b:0;}i:10;a:9:{s:6:\"number\";i:5506;s:4:\"text\";s:43:\"Laisse-Moi avec celui que J\'ai créé seul,\";s:13:\"numberInSurah\";i:11;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:575;s:4:\"ruku\";i:510;s:11:\"hizbQuarter\";i:230;s:5:\"sajda\";b:0;}i:11;a:9:{s:6:\"number\";i:5507;s:4:\"text\";s:41:\"et à qui J\'ai donné des biens étendus,\";s:13:\"numberInSurah\";i:12;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:575;s:4:\"ruku\";i:510;s:11:\"hizbQuarter\";i:230;s:5:\"sajda\";b:0;}i:12;a:9:{s:6:\"number\";i:5508;s:4:\"text\";s:51:\"et des enfants qui lui tiennent toujours compagnie,\";s:13:\"numberInSurah\";i:13;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:575;s:4:\"ruku\";i:510;s:11:\"hizbQuarter\";i:230;s:5:\"sajda\";b:0;}i:13;a:9:{s:6:\"number\";i:5509;s:4:\"text\";s:46:\"pour qui aussi J\'ai aplani toutes difficultés\";s:13:\"numberInSurah\";i:14;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:575;s:4:\"ruku\";i:510;s:11:\"hizbQuarter\";i:230;s:5:\"sajda\";b:0;}i:14;a:9:{s:6:\"number\";i:5510;s:4:\"text\";s:59:\"Cependant, il convoite [de Moi] que Je lui donne davantage.\";s:13:\"numberInSurah\";i:15;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:575;s:4:\"ruku\";i:510;s:11:\"hizbQuarter\";i:230;s:5:\"sajda\";b:0;}i:15;a:9:{s:6:\"number\";i:5511;s:4:\"text\";s:68:\"Pas du tout! Car il reniait nos versets (le Coran) avec entêtement.\";s:13:\"numberInSurah\";i:16;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:575;s:4:\"ruku\";i:510;s:11:\"hizbQuarter\";i:230;s:5:\"sajda\";b:0;}i:16;a:9:{s:6:\"number\";i:5512;s:4:\"text\";s:43:\"Je vais le contraindre à gravir une pente.\";s:13:\"numberInSurah\";i:17;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:575;s:4:\"ruku\";i:510;s:11:\"hizbQuarter\";i:230;s:5:\"sajda\";b:0;}i:17;a:9:{s:6:\"number\";i:5513;s:4:\"text\";s:34:\"Il a réfléchi. Et il a décidé.\";s:13:\"numberInSurah\";i:18;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:576;s:4:\"ruku\";i:510;s:11:\"hizbQuarter\";i:230;s:5:\"sajda\";b:0;}i:18;a:9:{s:6:\"number\";i:5514;s:4:\"text\";s:36:\"Qu\'il périsse! Comme il a décidé!\";s:13:\"numberInSurah\";i:19;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:576;s:4:\"ruku\";i:510;s:11:\"hizbQuarter\";i:230;s:5:\"sajda\";b:0;}i:19;a:9:{s:6:\"number\";i:5515;s:4:\"text\";s:53:\"Encore une fois, qu\'il périsse; comme il a décidé!\";s:13:\"numberInSurah\";i:20;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:576;s:4:\"ruku\";i:510;s:11:\"hizbQuarter\";i:230;s:5:\"sajda\";b:0;}i:20;a:9:{s:6:\"number\";i:5516;s:4:\"text\";s:23:\"Ensuite, il a regardé.\";s:13:\"numberInSurah\";i:21;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:576;s:4:\"ruku\";i:510;s:11:\"hizbQuarter\";i:230;s:5:\"sajda\";b:0;}i:21;a:9:{s:6:\"number\";i:5517;s:4:\"text\";s:45:\"Et il s\'est renfrogné et a durci son visage.\";s:13:\"numberInSurah\";i:22;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:576;s:4:\"ruku\";i:510;s:11:\"hizbQuarter\";i:230;s:5:\"sajda\";b:0;}i:22;a:9:{s:6:\"number\";i:5518;s:4:\"text\";s:53:\"Ensuite il a tourné le dos et s\'est enflé d\'orgueil\";s:13:\"numberInSurah\";i:23;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:576;s:4:\"ruku\";i:510;s:11:\"hizbQuarter\";i:230;s:5:\"sajda\";b:0;}i:23;a:9:{s:6:\"number\";i:5519;s:4:\"text\";s:56:\"Puis il a dit: «Ceci (le Coran) n\'est que magie apprise\";s:13:\"numberInSurah\";i:24;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:576;s:4:\"ruku\";i:510;s:11:\"hizbQuarter\";i:230;s:5:\"sajda\";b:0;}i:24;a:9:{s:6:\"number\";i:5520;s:4:\"text\";s:41:\"ce n\'est là que la parole d\'un humain».\";s:13:\"numberInSurah\";i:25;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:576;s:4:\"ruku\";i:510;s:11:\"hizbQuarter\";i:230;s:5:\"sajda\";b:0;}i:25;a:9:{s:6:\"number\";i:5521;s:4:\"text\";s:47:\"Je vais le brûler dans le Feu intense (Saqar).\";s:13:\"numberInSurah\";i:26;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:576;s:4:\"ruku\";i:510;s:11:\"hizbQuarter\";i:230;s:5:\"sajda\";b:0;}i:26;a:9:{s:6:\"number\";i:5522;s:4:\"text\";s:31:\"Et qui te dira ce qu\'est Saqar?\";s:13:\"numberInSurah\";i:27;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:576;s:4:\"ruku\";i:510;s:11:\"hizbQuarter\";i:230;s:5:\"sajda\";b:0;}i:27;a:9:{s:6:\"number\";i:5523;s:4:\"text\";s:37:\"Il ne laisse rien et n\'épargne rien;\";s:13:\"numberInSurah\";i:28;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:576;s:4:\"ruku\";i:510;s:11:\"hizbQuarter\";i:230;s:5:\"sajda\";b:0;}i:28;a:9:{s:6:\"number\";i:5524;s:4:\"text\";s:32:\"Il brûle la peau et la noircit.\";s:13:\"numberInSurah\";i:29;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:576;s:4:\"ruku\";i:510;s:11:\"hizbQuarter\";i:230;s:5:\"sajda\";b:0;}i:29;a:9:{s:6:\"number\";i:5525;s:4:\"text\";s:31:\"Ils sont dix neuf à y veiller.\";s:13:\"numberInSurah\";i:30;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:576;s:4:\"ruku\";i:510;s:11:\"hizbQuarter\";i:230;s:5:\"sajda\";b:0;}i:30;a:9:{s:6:\"number\";i:5526;s:4:\"text\";s:637:\"Nous n\'avons assigné comme gardiens du Feu que des Anges. Cependant, Nous n\'en avons fixé le nombre que pour éprouver les mécréants, et aussi afin que ceux à qui le Livre a été apporté soient convaincus, et que croisse la foi de ceux qui croient, et que ceux à qui le Livre a été apporté et les croyants n\'aient point de doute; et pour que ceux qui ont au cœur quelque maladie ainsi que les mécréants disent: «Qu\'a donc voulu Allah par cette parabole?» C\'est ainsi qu\'Allah égare qui Il veut et guide qui Il veut. Nul ne connaît les armées de ton Seigneur, à part Lui. Et ce n\'est là qu\'un rappel pour les humains.\";s:13:\"numberInSurah\";i:31;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:576;s:4:\"ruku\";i:510;s:11:\"hizbQuarter\";i:230;s:5:\"sajda\";b:0;}i:31;a:9:{s:6:\"number\";i:5527;s:4:\"text\";s:20:\"Non!... Par la lune!\";s:13:\"numberInSurah\";i:32;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:576;s:4:\"ruku\";i:511;s:11:\"hizbQuarter\";i:230;s:5:\"sajda\";b:0;}i:32;a:9:{s:6:\"number\";i:5528;s:4:\"text\";s:36:\"Et par la nuit quand elle se retire!\";s:13:\"numberInSurah\";i:33;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:576;s:4:\"ruku\";i:511;s:11:\"hizbQuarter\";i:230;s:5:\"sajda\";b:0;}i:33;a:9:{s:6:\"number\";i:5529;s:4:\"text\";s:40:\"Et par l\'aurore quand elle se découvre!\";s:13:\"numberInSurah\";i:34;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:576;s:4:\"ruku\";i:511;s:11:\"hizbQuarter\";i:230;s:5:\"sajda\";b:0;}i:34;a:9:{s:6:\"number\";i:5530;s:4:\"text\";s:43:\"[Saqar] est l\'un des plus grands [malheurs]\";s:13:\"numberInSurah\";i:35;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:576;s:4:\"ruku\";i:511;s:11:\"hizbQuarter\";i:230;s:5:\"sajda\";b:0;}i:35;a:9:{s:6:\"number\";i:5531;s:4:\"text\";s:35:\"un avertissement, pour les humains.\";s:13:\"numberInSurah\";i:36;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:576;s:4:\"ruku\";i:511;s:11:\"hizbQuarter\";i:230;s:5:\"sajda\";b:0;}i:36;a:9:{s:6:\"number\";i:5532;s:4:\"text\";s:47:\"Pour qui d\'entre vous, veut avancer ou reculer.\";s:13:\"numberInSurah\";i:37;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:576;s:4:\"ruku\";i:511;s:11:\"hizbQuarter\";i:230;s:5:\"sajda\";b:0;}i:37;a:9:{s:6:\"number\";i:5533;s:4:\"text\";s:46:\"Toute âme est l\'otage de ce qu\'elle a acquis.\";s:13:\"numberInSurah\";i:38;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:576;s:4:\"ruku\";i:511;s:11:\"hizbQuarter\";i:230;s:5:\"sajda\";b:0;}i:38;a:9:{s:6:\"number\";i:5534;s:4:\"text\";s:39:\"Sauf les gens de la droite (les élus):\";s:13:\"numberInSurah\";i:39;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:576;s:4:\"ruku\";i:511;s:11:\"hizbQuarter\";i:230;s:5:\"sajda\";b:0;}i:39;a:9:{s:6:\"number\";i:5535;s:4:\"text\";s:37:\"dans des Jardins, ils s\'interrogeront\";s:13:\"numberInSurah\";i:40;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:576;s:4:\"ruku\";i:511;s:11:\"hizbQuarter\";i:230;s:5:\"sajda\";b:0;}i:40;a:9:{s:6:\"number\";i:5536;s:4:\"text\";s:23:\"au sujet des criminels:\";s:13:\"numberInSurah\";i:41;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:576;s:4:\"ruku\";i:511;s:11:\"hizbQuarter\";i:230;s:5:\"sajda\";b:0;}i:41;a:9:{s:6:\"number\";i:5537;s:4:\"text\";s:45:\"«Qu\'est-ce qui vous a acheminés à Saqar?»\";s:13:\"numberInSurah\";i:42;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:576;s:4:\"ruku\";i:511;s:11:\"hizbQuarter\";i:230;s:5:\"sajda\";b:0;}i:42;a:9:{s:6:\"number\";i:5538;s:4:\"text\";s:65:\"Ils diront: «Nous n\'étions pas de ceux qui faisaient la Salât,\";s:13:\"numberInSurah\";i:43;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:576;s:4:\"ruku\";i:511;s:11:\"hizbQuarter\";i:230;s:5:\"sajda\";b:0;}i:43;a:9:{s:6:\"number\";i:5539;s:4:\"text\";s:38:\"et nous ne nourrissions pas le pauvre,\";s:13:\"numberInSurah\";i:44;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:576;s:4:\"ruku\";i:511;s:11:\"hizbQuarter\";i:230;s:5:\"sajda\";b:0;}i:44;a:9:{s:6:\"number\";i:5540;s:4:\"text\";s:71:\"et nous nous associions à ceux qui tenaient des conversations futiles,\";s:13:\"numberInSurah\";i:45;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:576;s:4:\"ruku\";i:511;s:11:\"hizbQuarter\";i:230;s:5:\"sajda\";b:0;}i:45;a:9:{s:6:\"number\";i:5541;s:4:\"text\";s:57:\"et nous traitions de mensonge le jour de la Rétribution,\";s:13:\"numberInSurah\";i:46;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:576;s:4:\"ruku\";i:511;s:11:\"hizbQuarter\";i:230;s:5:\"sajda\";b:0;}i:46;a:9:{s:6:\"number\";i:5542;s:4:\"text\";s:61:\"jusqu\'à ce que nous vînt la vérité évidente [la mort]».\";s:13:\"numberInSurah\";i:47;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:576;s:4:\"ruku\";i:511;s:11:\"hizbQuarter\";i:230;s:5:\"sajda\";b:0;}i:47;a:9:{s:6:\"number\";i:5543;s:4:\"text\";s:63:\"Ne leur profitera point donc, l\'intercession des intercesseurs.\";s:13:\"numberInSurah\";i:48;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:577;s:4:\"ruku\";i:511;s:11:\"hizbQuarter\";i:230;s:5:\"sajda\";b:0;}i:48;a:9:{s:6:\"number\";i:5544;s:4:\"text\";s:38:\"Qu\'ont-ils à se détourner du Rappel?\";s:13:\"numberInSurah\";i:49;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:577;s:4:\"ruku\";i:511;s:11:\"hizbQuarter\";i:230;s:5:\"sajda\";b:0;}i:49;a:9:{s:6:\"number\";i:5545;s:4:\"text\";s:40:\"Ils sont comme des onagres épouvantés,\";s:13:\"numberInSurah\";i:50;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:577;s:4:\"ruku\";i:511;s:11:\"hizbQuarter\";i:230;s:5:\"sajda\";b:0;}i:50;a:9:{s:6:\"number\";i:5546;s:4:\"text\";s:26:\"s\'enfuyant devant un lion.\";s:13:\"numberInSurah\";i:51;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:577;s:4:\"ruku\";i:511;s:11:\"hizbQuarter\";i:230;s:5:\"sajda\";b:0;}i:51;a:9:{s:6:\"number\";i:5547;s:4:\"text\";s:76:\"Chacun d\'eux voudrait plutôt qu\'on lui apporte des feuilles tout étalées.\";s:13:\"numberInSurah\";i:52;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:577;s:4:\"ruku\";i:511;s:11:\"hizbQuarter\";i:230;s:5:\"sajda\";b:0;}i:52;a:9:{s:6:\"number\";i:5548;s:4:\"text\";s:58:\"Ah! Non! C\'est plutôt qu\'ils ne craignent pas l\'au-delà.\";s:13:\"numberInSurah\";i:53;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:577;s:4:\"ruku\";i:511;s:11:\"hizbQuarter\";i:230;s:5:\"sajda\";b:0;}i:53;a:9:{s:6:\"number\";i:5549;s:4:\"text\";s:37:\"Ah! Non! Ceci est vraiment un Rappel.\";s:13:\"numberInSurah\";i:54;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:577;s:4:\"ruku\";i:511;s:11:\"hizbQuarter\";i:230;s:5:\"sajda\";b:0;}i:54;a:9:{s:6:\"number\";i:5550;s:4:\"text\";s:37:\"Quiconque veut, qu\'il se le rappelle.\";s:13:\"numberInSurah\";i:55;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:577;s:4:\"ruku\";i:511;s:11:\"hizbQuarter\";i:230;s:5:\"sajda\";b:0;}i:55;a:9:{s:6:\"number\";i:5551;s:4:\"text\";s:131:\"Mais ils ne se rappelleront que si Allah veut. C\'est Lui qui est Le plus digne d\'être craint; et c\'est Lui qui détient le pardon.\";s:13:\"numberInSurah\";i:56;s:3:\"juz\";i:29;s:6:\"manzil\";i:7;s:4:\"page\";i:577;s:4:\"ruku\";i:511;s:11:\"hizbQuarter\";i:230;s:5:\"sajda\";b:0;}}s:7:\"edition\";a:7:{s:10:\"identifier\";s:13:\"fr.hamidullah\";s:8:\"language\";s:2:\"fr\";s:4:\"name\";s:10:\"Hamidullah\";s:11:\"englishName\";s:19:\"Muhammad Hamidullah\";s:6:\"format\";s:4:\"text\";s:4:\"type\";s:11:\"translation\";s:9:\"direction\";s:3:\"ltr\";}}', 1794581404),
