('quranapp-cache-surah_84_fr.hamidullah', 'a:8:{s:6:\"number\";i:84;s:4:\"name\";s:37:\"سُورَةُ الانشِقَاقِ\";s:11:\"englishName\";s:12:\"Al-Inshiqaaq\";s:22:\"englishNameTranslation\";s:18:\"The Splitting Open\";s:14:\"revelationType\";s:6:\"Meccan\";s:13:\"numberOfAyahs\";i:25;s:5:\"ayahs\";a:25:{i:0;a:9:{s:6:\"number\";i:5885;s:4:\"text\";s:27:\"Quand le ciel se déchirera\";s:13:\"numberInSurah\";i:1;s:3:\"juz\";i:30;s:6:\"manzil\";i:7;s:4:\"page\";i:589;s:4:\"ruku\";i:526;s:11:\"hizbQuarter\";i:236;s:5:\"sajda\";b:0;}i:1;a:9:{s:6:\"number\";i:5886;s:4:\"text\";s:58:\"et obéira à son Seigneur - et fera ce qu\'il doit faire -\";s:13:\"numberInSurah\";i:2;s:3:\"juz\";i:30;s:6:\"manzil\";i:7;s:4:\"page\";i:589;s:4:\"ruku\";i:526;s:11:\"hizbQuarter\";i:236;s:5:\"sajda\";b:0;}i:2;a:9:{s:6:\"number\";i:5887;s:4:\"text\";s:30:\"et que la terre sera nivelée,\";s:13:\"numberInSurah\";i:3;s:3:\"juz\";i:30;s:6:\"manzil\";i:7;s:4:\"page\";i:589;s:4:\"ruku\";i:526;s:11:\"hizbQuarter\";i:236;s:5:\"sajda\";b:0;}i:3;a:9:{s:6:\"number\";i:5888;s:4:\"text\";s:69:\"et qu\'elle rejettera ce qui est en son sein (les morts) et se videra,\";s:13:\"numberInSurah\";i:4;s:3:\"juz\";i:30;s:6:\"manzil\";i:7;s:4:\"page\";i:589;s:4:\"ruku\";i:526;s:11:\"hizbQuarter\";i:236;s:5:\"sajda\";b:0;}i:4;a:9:{s:6:\"number\";i:5889;s:4:\"text\";s:68:\"et qu\'elle obéira à son Seigneur - et fera ce qu\'elle doit faire -\";s:13:\"numberInSurah\";i:5;s:3:\"juz\";i:30;s:6:\"manzil\";i:7;s:4:\"page\";i:589;s:4:\"ruku\";i:526;s:11:\"hizbQuarter\";i:236;s:5:\"sajda\";b:0;}i:5;a:9:{s:6:\"number\";i:5890;s:4:\"text\";s:86:\"O homme! Toi qui t\'efforces vers ton Seigneur sans relâche, tu Le rencontreras alors.\";s:13:\"numberInSurah\";i:6;s:3:\"juz\";i:30;s:6:\"manzil\";i:7;s:4:\"page\";i:589;s:4:\"ruku\";i:526;s:11:\"hizbQuarter\";i:236;s:5:\"sajda\";b:0;}i:6;a:9:{s:6:\"number\";i:5891;s:4:\"text\";s:46:\"Celui qui recevra son livre en sa main droite,\";s:13:\"numberInSurah\";i:7;s:3:\"juz\";i:30;s:6:\"manzil\"