('quranapp-cache-surah_87_fr.hamidullah', 'a:8:{s:6:\"number\";i:87;s:4:\"name\";s:35:\"سُورَةُ الأَعۡلَىٰ\";s:11:\"englishName\";s:8:\"Al-A\'laa\";s:22:\"englishNameTranslation\";s:13:\"The Most High\";s:14:\"revelationType\";s:6:\"Meccan\";s:13:\"numberOfAyahs\";i:19;s:5:\"ayahs\";a:19:{i:0;a:9:{s:6:\"number\";i:5949;s:4:\"text\";s:47:\"Glorifie le nom de ton Seigneur, le Très Haut,\";s:13:\"numberInSurah\";i:1;s:3:\"juz\";i:30;s:6:\"manzil\";i:7;s:4:\"page\";i:591;s:4:\"ruku\";i:529;s:11:\"hizbQuarter\";i:237;s:5:\"sajda\";b:0;}i:1;a:9:{s:6:\"number\";i:5950;s:4:\"text\";s:46:\"Celui Qui a créé et agencé harmonieusement,\";s:13:\"numberInSurah\";i:2;s:3:\"juz\";i:30;s:6:\"manzil\";i:7;s:4:\"page\";i:591;s:4:\"ruku\";i:529;s:11:\"hizbQuarter\";i:237;s:5:\"sajda\";b:0;}i:2;a:9:{s:6:\"number\";i:5951;s:4:\"text\";s:27:\"qui a décrété et guidé,\";s:13:\"numberInSurah\";i:3;s:3:\"juz\";i:30;s:6:\"manzil\";i:7;s:4:\"page\";i:591;s:4:\"ruku\";i:529;s:11:\"hizbQuarter\";i:237;s:5:\"sajda\";b:0;}i:3;a:9:{s:6:\"number\";i:5952;s:4:\"text\";s:35:\"et qui a fait pousser le pâturage,\";s:13:\"numberInSurah\";i:4;s:3:\"juz\";i:30;s:6:\"manzil\";i:7;s:4:\"page\";i:591;s:4:\"ruku\";i:529;s:11:\"hizbQuarter\";i:237;s:5:\"sajda\";b:0;}i:4;a:9:{s:6:\"number\";i:5953;s:4:\"text\";s:36:\"et en a fait ensuite un foin sombre.\";s:13:\"numberInSurah\";i:5;s:3:\"juz\";i:30;s:6:\"manzil\";i:7;s:4:\"page\";i:591;s:4:\"ruku\";i:529;s:11:\"hizbQuarter\";i:237;s:5:\"sajda\";b:0;}i:5;a:9:{s:6:\"number\";i:5954;s:4:\"text\";s:63:\"Nous te ferons réciter (le Coran), de sorte que tu n\'oublieras\";s:13:\"numberInSurah\";i:6;s:3:\"juz\";i:30;s:6:\"manzil\";i:7;s:4:\"page\";i:591;s:4:\"ruku\";i:529;s:11:\"hizbQuarter\";i:237;s:5:\"sajda\";b:0;}i:6;a:9:{s:6:\"number\";i:5955;s:4:\"text\";s:96:\"que ce qu\'Allah veut. Car, Il connaît ce qui paraît au grand jour ainsi que ce qui est caché.\";s:13:\"numberInSurah\";i:7;s:3:\"juz\";i:30;s:6:\"manzil\";i:7;s:4:\"page\";i:591;s:4:\"ruku\";i:529;s:11:\"hiz