('quranapp-cache-surah_93_fr.hamidullah', 'a:8:{s:6:\"number\";i:93;s:4:\"name\";s:33:\"سُورَةُ الضُّحَىٰ\";s:11:\"englishName\";s:9:\"Ad-Dhuhaa\";s:22:\"englishNameTranslation\";s:17:\"The Morning Hours\";s:14:\"revelationType\";s:6:\"Meccan\";s:13:\"numberOfAyahs\";i:11;s:5:\"ayahs\";a:11:{i:0;a:9:{s:6:\"number\";i:6080;s:4:\"text\";s:20:\"Par le Jour Montant!\";s:13:\"numberInSurah\";i:1;s:3:\"juz\";i:30;s:6:\"manzil\";i:7;s:4:\"page\";i:596;s:4:\"ruku\";i:535;s:11:\"hizbQuarter\";i:238;s:5:\"sajda\";b:0;}i:1;a:9:{s:6:\"number\";i:6081;s:4:\"text\";s:38:\"Et par la nuit quand elle couvre tout!\";s:13:\"numberInSurah\";i:2;s:3:\"juz\";i:30;s:6:\"manzil\";i:7;s:4:\"page\";i:596;s:4:\"ruku\";i:535;s:11:\"hizbQuarter\";i:238;s:5:\"sajda\";b:0;}i:2;a:9:{s:6:\"number\";i:6082;s:4:\"text\";s:48:\"Ton Seigneur ne t\'a ni abandonné, ni détesté.\";s:13:\"numberInSurah\";i:3;s:3:\"juz\";i:30;s:6:\"manzil\";i:7;s:4:\"page\";i:596;s:4:\"ruku\";i:535;s:11:\"hizbQuarter\";i:238;s:5:\"sajda\";b:0;}i:3;a:9:{s:6:\"number\";i:6083;s:4:\"text\";s:63:\"La vie dernière t\'est, certes, meilleure que la vie présente.\";s:13:\"numberInSurah\";i:4;s:3:\"juz\";i:30;s:6:\"manzil\";i:7;s:4:\"page\";i:596;s:4:\"ruku\";i:535;s:11:\"hizbQuarter\";i:238;s:5:\"sajda\";b:0;}i:4;a:9:{s:6:\"number\";i:6084;s:4:\"text\";s:75:\"Ton Seigneur t\'accordera certes [Ses faveurs], et alors tu seras satisfait.\";s:13:\"numberInSurah\";i:5;s:3:\"juz\";i:30;s:6:\"manzil\";i:7;s:4:\"page\";i:596;s:4:\"ruku\";i:535;s:11:\"hizbQuarter\";i:238;s:5:\"sajda\";b:0;}i:5;a:9:{s:6:\"number\";i:6085;s:4:\"text\";s:57:\"Ne t\'a-t-Il pas trouvé orphelin? Alors Il t\'a accueilli!\";s:13:\"numberInSurah\";i:6;s:3:\"juz\";i:30;s:6:\"manzil\";i:7;s:4:\"page\";i:596;s:4:\"ruku\";i:535;s:11:\"hizbQuarter\";i:238;s:5:\"sajda\";b:0;}i:6;a:9:{s:6:\"number\";i:6086;s:4:\"text\";s:53:\"Ne t\'a-t-Il pas trouvé égaré? Alors Il t\'a guidé.\";s:13:\"numberInSurah\";i:7;s:3:\"juz\";i:30;s:6:\"manzil\";i:7;s:4:\"page\";i:596;s:4:\"ruku\";i:535;s:11:\"hizbQuarter\";i:238;s:5:\"sajda\";b:0;}i:7;a:9:{s:6:\"number\";i:6087;s:4:\"text\";s:53:\"Ne t\'a-t-Il pas trouvé pauvre? Alors Il t\'a enrichi.\";s:13:\"numberInSurah\";i:8;s:3:\"juz\";i:30;s:6:\"manzil\";i:7;s:4:\"page\";i:596;s:4:\"ruku\";i:535;s:11:\"hizbQuarter\";i:238;s:5:\"sajda\";b:0;}i:8;a:9:{s:6:\"number\";i:6088;s:4:\"text\";s:47:\"Quant à l\'orphelin, donc, ne le maltraite pas.\";s:13:\"numberInSurah\";i:9;s:3:\"juz\";i:30;s:6:\"manzil\";i:7;s:4:\"page\";i:596;s:4:\"ruku\";i:535;s:11:\"hizbQuarter\";i:238;s:5:\"sajda\";b:0;}i:9;a:9:{s:6:\"number\";i:6089;s:4:\"text\";s:39:\"Quant au demandeur, ne le repousse pas.\";s:13:\"numberInSurah\";i:10;s:3:\"juz\";i:30;s:6:\"manzil\";i:7;s:4:\"page\";i:596;s:4:\"ruku\";i:535;s:11:\"hizbQuarter\";i:238;s:5:\"sajda\";b:0;}i:10;a:9:{s:6:\"number\";i:6090;s:4:\"text\";s:50:\"Et quant au bienfait de ton Seigneur, proclame-le.\";s:13:\"numberInSurah\";i:11;s:3:\"juz\";i:30;s:6:\"manzil\";i:7;s:4:\"page\";i:596;s:4:\"ruku\";i:535;s:11:\"hizbQuarter\";i:238;s:5:\"sajda\";b:0;}}s:7:\"edition\";a:7:{s:10:\"identifier\";s:13:\"fr.hamidullah\";s:8:\"language\";s:2:\"fr\";s:4:\"name\";s:10:\"Hamidullah\";s:11:\"englishName\";s:19:\"Muhammad Hamidullah\";s:6:\"format\";s:4:\"text\";s:4:\"type\";s:11:\"translation\";s:9:\"direction\";s:3:\"ltr\";}}', 1794581418),
