('quranapp-cache-surah_96_fr.hamidullah', 'a:8:{s:6:\"number\";i:96;s:4:\"name\";s:31:\"سُورَةُ العَلَقِ\";s:11:\"englishName\";s:7:\"Al-Alaq\";s:22:\"englishNameTranslation\";s:8:\"The Clot\";s:14:\"revelationType\";s:6:\"Meccan\";s:13:\"numberOfAyahs\";i:19;s:5:\"ayahs\";a:19:{i:0;a:9:{s:6:\"number\";i:6107;s:4:\"text\";s:41:\"Lis, au nom de ton Seigneur qui a créé,\";s:13:\"numberInSurah\";i:1;s:3:\"juz\";i:30;s:6:\"manzil\";i:7;s:4:\"page\";i:597;s:4:\"ruku\";i:538;s:11:\"hizbQuarter\";i:239;s:5:\"sajda\";b:0;}i:1;a:9:{s:6:\"number\";i:6108;s:4:\"text\";s:38:\"qui a créé l\'homme d\'une adhérence.\";s:13:\"numberInSurah\";i:2;s:3:\"juz\";i:30;s:6:\"manzil\";i:7;s:4:\"page\";i:597;s:4:\"ruku\";i:538;s:11:\"hizbQuarter\";i:239;s:5:\"sajda\";b:0;}i:2;a:9:{s:6:\"number\";i:6109;s:4:\"text\";s:37:\"Lis! Ton Seigneur est le Très Noble,\";s:13:\"numberInSurah\";i:3;s:3:\"juz\";i:30;s:6:\"manzil\";i:7;s:4:\"page\";i:597;s:4:\"ruku\";i:538;s:11:\"hizbQuarter\";i:239;s:5:\"sajda\";b:0;}i:3;a:9:{s:6:\"number\";i:6110;s:4:\"text\";s:41:\"qui a enseigné par la plume [le calame],\";s:13:\"numberInSurah\";i:4;s:3:\"juz\";i:30;s:6:\"manzil\";i:7;s:4:\"page\";i:597;s:4:\"ruku\";i:538;s:11:\"hizbQuarter\";i:239;s:5:\"sajda\";b:0;}i:4;a:9:{s:6:\"number\";i:6111;s:4:\"text\";s:46:\"a enseigné à l\'homme ce qu\'il ne savait pas.\";s:13:\"numberInSurah\";i:5;s:3:\"juz\";i:30;s:6:\"manzil\";i:7;s:4:\"page\";i:597;s:4:\"ruku\";i:538;s:11:\"hizbQuarter\";i:239;s:5:\"sajda\";b:0;}i:5;a:9:{s:6:\"number\";i:6112;s:4:\"text\";s:47:\"Prenez-garde! Vraiment l\'homme devient rebelle,\";s:13:\"numberInSurah\";i:6;s:3:\"juz\";i:30;s:6:\"manzil\";i:7;s:4:\"page\";i:597;s:4:\"ruku\";i:538;s:11:\"hizbQuarter\";i:239;s:5:\"sajda\";b:0;}i:6;a:9:{s:6:\"number\";i:6113;s:4:\"text\";s:79:\"dès qu\'il estime qu\'il peut se suffire à lui-même (à cause de sa richesse).\";s:13:\"numberInSurah\";i:7;s:3:\"juz\";i:30;s:6:\"manzil\";i:7;s:4:\"page\";i:597;s:4:\"ruku\";i:538;s:11:\"hizbQuarter\";i:239;s:5:\"sajda\";b:0;}i:7;a:9:{s:6:\"number\";i:6114;s:4:\"text\";s:47:\"Mais, c\'est vers ton Seigneur qu\'est le retour.\";s:13:\"numberInSurah\";i:8;s:3:\"juz\";i:30;s:6:\"manzil\";i:7;s:4:\"page\";i:597;s:4:\"ruku\";i:538;s:11:\"hizbQuarter\";i:239;s:5:\"sajda\";b:0;}i:8;a:9:{s:6:\"number\";i:6115;s:4:\"text\";s:27:\"As-tu vu celui qui interdit\";s:13:\"numberInSurah\";i:9;s:3:\"juz\";i:30;s:6:\"manzil\";i:7;s:4:\"page\";i:597;s:4:\"ruku\";i:538;s:11:\"hizbQuarter\";i:239;s:5:\"sajda\";b:0;}i:9;a:9:{s:6:\"number\";i:6116;s:4:\"text\";s:59:\"à un serviteur d\'Allah [Muhammad] de célébrer la Salât?\";s:13:\"numberInSurah\";i:10;s:3:\"juz\";i:30;s:6:\"manzil\";i:7;s:4:\"page\";i:597;s:4:\"ruku\";i:538;s:11:\"hizbQuarter\";i:239;s:5:\"sajda\";b:0;}i:10;a:9:{s:6:\"number\";i:6117;s:4:\"text\";s:35:\"Vois-tu s\'il est sur la bonne voie,\";s:13:\"numberInSurah\";i:11;s:3:\"juz\";i:30;s:6:\"manzil\";i:7;s:4:\"page\";i:597;s:4:\"ruku\";i:538;s:11:\"hizbQuarter\";i:239;s:5:\"sajda\";b:0;}i:11;a:9:{s:6:\"number\";i:6118;s:4:\"text\";s:27:\"ou s\'il ordonne la piété?\";s:13:\"numberInSurah\";i:12;s:3:\"juz\";i:30;s:6:\"manzil\";i:7;s:4:\"page\";i:597;s:4:\"ruku\";i:538;s:11:\"hizbQuarter\";i:239;s:5:\"sajda\";b:0;}i:12;a:9:{s:6:\"number\";i:6119;s:4:\"text\";s:38:\"Vois-tu s\'il dément et tourne le dos?\";s:13:\"numberInSurah\";i:13;s:3:\"juz\";i:30;s:6:\"manzil\";i:7;s:4:\"page\";i:597;s:4:\"ruku\";i:538;s:11:\"hizbQuarter\";i:239;s:5:\"sajda\";b:0;}i:13;a:9:{s:6:\"number\";i:6120;s:4:\"text\";s:39:\"Ne sait-il pas que vraiment Allah voit?\";s:13:\"numberInSurah\";i:14;s:3:\"juz\";i:30;s:6:\"manzil\";i:7;s:4:\"page\";i:597;s:4:\"ruku\";i:538;s:11:\"hizbQuarter\";i:239;s:5:\"sajda\";b:0;}i:14;a:9:{s:6:\"number\";i:6121;s:4:\"text\";s:69:\"Mais non! S\'il ne cesse pas, Nous le saisirons certes, par le toupet,\";s:13:\"numberInSurah\";i:15;s:3:\"juz\";i:30;s:6:\"manzil\";i:7;s:4:\"page\";i:597;s:4:\"ruku\";i:538;s:11:\"hizbQuarter\";i:239;s:5:\"sajda\";b:0;}i:15;a:9:{s:6:\"number\";i:6122;s:4:\"text\";s:38:\"le toupet d\'un menteur, d\'un pécheur.\";s:13:\"numberInSurah\";i:16;s:3:\"juz\";i:30;s:6:\"manzil\";i:7;s:4:\"page\";i:597;s:4:\"ruku\";i:538;s:11:\"hizbQuarter\";i:239;s:5:\"sajda\";b:0;}i:16;a:9:{s:6:\"number\";i:6123;s:4:\"text\";s:34:\"Qu\'il appelle donc son assemblée.\";s:13:\"numberInSurah\";i:17;s:3:\"juz\";i:30;s:6:\"manzil\";i:7;s:4:\"page\";i:597;s:4:\"ruku\";i:538;s:11:\"hizbQuarter\";i:239;s:5:\"sajda\";b:0;}i:17;a:9:{s:6:\"number\";i:6124;s:4:\"text\";s:43:\"Nous appellerons les gardiens [de l\'Enfer].\";s:13:\"numberInSurah\";i:18;s:3:\"juz\";i:30;s:6:\"manzil\";i:7;s:4:\"page\";i:597;s:4:\"ruku\";i:538;s:11:\"hizbQuarter\";i:239;s:5:\"sajda\";b:0;}i:18;a:9:{s:6:\"number\";i:6125;s:4:\"text\";s:60:\"Non! Ne lui obéis pas; mais prosterne-toi et rapproche-toi.\";s:13:\"numberInSurah\";i:19;s:3:\"juz\";i:30;s:6:\"manzil\";i:7;s:4:\"page\";i:597;s:4:\"ruku\";i:538;s:11:\"hizbQuarter\";i:239;s:5:\"sajda\";a:3:{s:2:\"id\";i:15;s:11:\"recommended\";b:0;s:10:\"obligatory\";b:1;}}}s:7:\"edition\";a:7:{s:10:\"identifier\";s:13:\"fr.hamidullah\";s:8:\"language\";s:2:\"fr\";s:4:\"name\";s:10:\"Hamidullah\";s:11:\"englishName\";s:19:\"Muhammad Hamidullah\";s:6:\"format\";s:4:\"text\";s:4:\"type\";s:11:\"translation\";s:9:\"direction\";s:3:\"ltr\";}}', 1794581420),
('quranapp-cache-surah_97_ar.uthmani', 'a:8:{s:6:\"number\";i:97;s:4:\"name\";s:31:\"سُورَةُ القَدۡرِ\";s:11:\"englishName\";s:7:\"Al-Qadr\";s:22:\"englishNameTranslation\";s:15:\"The Power, Fate\";s:14:\"revelationType\";s:6:\"Meccan\";s:13:\"numberOfAyahs\";i:5;s:5:\"ayahs\";a:5:{i:0;a:9:{s:6:\"number\";i:6126;s:4:\"text\";s:163:\"بِّسۡمِ ٱللَّهِ ٱلرَّحۡمَـٰنِ ٱلرَّحِیمِ إِنَّاۤ أَنزَلۡنَـٰهُ فِی لَیۡلَةِ ٱلۡقَدۡرِ\n\";s:13:\"numberInSurah\";i:1;s:3:\"juz\";i:30;s:6:\"manzil\";i:7;s:4:\"page\";i:598;s:4:\"ruku\";i:539;s:11:\"hizbQuarter\";i:239;s:5:\"sajda\";b:0;}i:1;a:9:{s:6:\"number\";i:6127;s:4:\"text\";s:77:\"وَمَاۤ أَدۡرَىٰكَ مَا لَیۡلَةُ ٱلۡقَدۡرِ\n\";s:13:\"numberInSurah\";i:2;s:3:\"juz\";i:30;s:6:\"manzil\";i:7;s:4:\"page\";i:598;s:4:\"ruku\";i:539;s:11:\"hizbQuarter\";i:239;s:5:\"sajda\";b:0;}i:2;a:9:{s:6:\"number\";i:6128;s:4:\"text\";s:88:\"لَیۡلَةُ ٱلۡقَدۡرِ خَیۡرࣱ مِّنۡ أَلۡفِ شَهۡرࣲ\n\";s:13:\"numberInSurah\";i:3;s:3:\"juz\";i:30;s:6:\"manzil\";i:7;s:4:\"page\";i:598;s:4:\"ruku\";i:539;s:11:\"hizbQuarter\";i:239;s:5:\"sajda\";b:0;}i:3;a:9:{s:6:\"number\";i:6129;s:4:\"text\";s:156:\"تَنَزَّلُ ٱلۡمَلَـٰۤىِٕكَةُ وَٱلرُّوحُ فِیهَا بِإِذۡنِ رَبِّهِم مِّن كُلِّ أَمۡرࣲ\n\";s:13:\"numberInSurah\";i:4;s:3:\"juz\";i:30;s:6:\"manzil\";i:7;s:4:\"page\";i:598;s:4:\"ruku\";i:539;s:11:\"hizbQuarter\";i:239;s:5:\"sajda\";b:0;}i:4;a:9:{s:6:\"number\";i:6130;s:4:\"text\";s:77:\"سَلَـٰمٌ هِیَ حَتَّىٰ مَطۡلَعِ ٱلۡفَجۡرِ\n\";s:13:\"numberInSurah\";i:5;s:3:\"juz\";i:30;s:6:\"manzil\";i:7;s:4:\"page\";i:598;s:4:\"ruku\";i:539;s:11:\"hizbQuarter\";i:239;s:5:\"sajda\";b:0;}}s:7:\"edition\";a:7:{s:10:\"identifier\";s:27:\"quran-uthmani-quran-academy\";s:8:\"language\";s:2:\"ar\";s:4:\"name\";s:67:\"القرآن الكريم برسم العثماني (quran-academy)\";s:11:\"englishName\";s:78:\"Modified Quran Uthmani Text from the Quran Academy to work with the Kitab font\";s:6:\"format\";s:4:\"text\";s:4:\"type\";s:5:\"quran\";s:9:\"direction\";s:3:\"rtl\";}}', 1794581420),
('quranapp-cache-surah_97_fr.hamidullah', 'a:8:{s:6:\"number\";i:97;s:4:\"name\";s:31:\"سُورَةُ القَدۡرِ\";s:11:\"englishName\";s:7:\"Al-Qadr\";s:22:\"englishNameTranslation\";s:15:\"The Power, Fate\";s:14:\"revelationType\";s:6:\"Meccan\";s:13:\"numberOfAyahs\";i:5;s:5:\"ayahs\";a:5:{i:0;a:9:{s:6:\"number\";i:6126;s:4:\"text\";s:73:\"Nous l\'avons certes, fait descendre (le Coran) pendant la nuit d\'Al-Qadr.\";s:13:\"numberInSurah\";i:1;s:3:\"juz\";i:30;s:6:\"manzil\";i:7;s:4:\"page\";i:598;s:4:\"ruku\";i:539;s:11:\"hizbQuarter\";i:239;s:5:\"sajda\";b:0;}i:1;a:9:{s:6:\"number\";i:6127;s:4:\"text\";s:43:\"Et qui te dira ce qu\'est la nuit d\'Al-Qadr?\";s:13:\"numberInSurah\";i:2;s:3:\"juz\";i:30;s:6:\"manzil\";i:7;s:4:\"page\";i:598;s:4:\"ruku\";i:539;s:11:\"hizbQuarter\";i:239;s:5:\"sajda\";b:0;}i:2;a:9:{s:6:\"number\";i:6128;s:4:\"text\";s:47:\"La nuit d\'Al-Qadr est meilleure que mille mois.\";s:13:\"numberInSurah\";i:3;s:3:\"juz\";i:30;s:6:\"manzil\";i:7;s:4:\"page\";i:598;s:4:\"ruku\";i:539;s:11:\"hizbQuarter\";i:239;s:5:\"sajda\";b:0;}i:3;a:9:{s:6:\"number\";i:6129;s:4:\"text\";s:105:\"Durant celle-ci descendent les Anges ainsi que l\'Esprit, par permission de leur Seigneur pour tout ordre.\";s:13:\"numberInSurah\";i:4;s:3:\"juz\";i:30;s:6:\"manzil\";i:7;s:4:\"page\";i:598;s:4:\"ruku\";i:539;s:11:\"hizbQuarter\";i:239;s:5:\"sajda\";b:0;}i:4;a:9:{s:6:\"number\";i:6130;s:4:\"text\";s:55:\"Elle est paix et salut jusqu\'à l\'apparition de l\'aube.\";s:13:\"numberInSurah\";i:5;s:3:\"juz\";i:30;s:6:\"manzil\";i:7;s:4:\"page\";i:598;s:4:\"ruku\";i:539;s:11:\"hizbQuarter\";i:239;s:5:\"sajda\";b:0;}}s:7:\"edition\";a:7:{s:10:\"identifier\";s:13:\"fr.hamidullah\";s:8:\"language\";s:2:\"fr\";s:4:\"name\";s:10:\"Hamidullah\";s:11:\"englishName\";s:19:\"Muhammad Hamidullah\";s:6:\"format\";s:4:\"text\";s:4:\"type\";s:11:\"translation\";s:9:\"direction\";s:3:\"ltr\";}}', 1794581421),
('quranapp-cache-surah_98_ar.uthmani', 'a:8:{s:6:\"number\";i:98;s:4:\"name\";s:37:\"سُورَةُ البَيِّنَةِ\";s:11:\"englishName\";s:10:\"Al-Bayyina\";s:22:\"englishNameTranslation\";s:12:\"The Evidence\";s:14:\"revelationType\";s:7:\"Medinan\";s:13:\"numberOfAyahs\";i:8;s:5:\"ayahs\";a:8:{i:0;a:9:{s:6:\"number\";i:6131;s:4:\"text\";s:302:\"بِسۡمِ ٱللَّهِ ٱلرَّحۡمَـٰنِ ٱلرَّحِیمِ لَمۡ یَكُنِ ٱلَّذِینَ كَفَرُوا۟ مِنۡ أَهۡلِ ٱلۡكِتَـٰبِ وَٱلۡمُشۡرِكِینَ مُنفَكِّینَ حَتَّىٰ تَأۡتِیَهُمُ ٱلۡبَیِّنَةُ\n\";s:13:\"numberInSurah\";i:1;s:3:\"juz\";i:30;s:6:\"manzil\";i:7;s:4:\"page\";i:598;s:4:\"ruku\";i:540;s:11:\"hizbQuarter\";i:239;s:5:\"sajda\";b:0;}i:1;a:9:{s:6:\"number\";i:6132;s:4:\"text\";s:103:\"رَسُولࣱ مِّنَ ٱللَّهِ یَتۡلُوا۟ صُحُفࣰا مُّطَهَّرَةࣰ\n\";s:13:\"numberInSurah\";i:2;s:3:\"juz\";i:30;s:6:\"manzil\";i:7;s:4:\"page\";i:598;s:4:\"ruku\";i:540;s:11:\"hizbQuarter\";i:239;s:5:\"sajda\";b:0;}i:2;a:9:{s:6:\"number\";i:6133;s:4:\"text\";s:47:\"فِیهَا كُتُبࣱ قَیِّمَةࣱ\n\";s:13:\"numberInSurah\";i:3;s:3:\"juz\";i:30;s:6:\"manzil\";i:7;s:4:\"page\";i:598;s:4:\"ruku\";i:540;s:11:\"hizbQuarter\";i:239;s:5:\"sajda\";b:0;}i:3;a:9:{s:6:\"number\";i:6134;s:4:\"text\";s:181:\"وَمَا تَفَرَّقَ ٱلَّذِینَ أُوتُوا۟ ٱلۡكِتَـٰبَ إِلَّا مِنۢ بَعۡدِ مَا جَاۤءَتۡهُمُ ٱلۡبَیِّنَةُ\n\";s:13:\"numberInSurah\";i:4;s:3:\"juz\";i:30;s:6:\"manzil\";i:7;s:4:\"page\";i:598;s:4:\"ruku\";i:540;s:11:\"hizbQuarter\";i:239;s:5:\"sajda\";b:0;}i:4;a:9:{s:6:\"number\";i:6135;s:4:\"text\";s:316:\"وَمَاۤ أُمِرُوۤا۟ إِلَّا لِیَعۡبُدُوا۟ ٱللَّهَ مُخۡلِصِینَ لَهُ ٱلدِّینَ حُنَفَاۤءَ وَیُقِیمُوا۟ ٱلصَّلَوٰةَ وَیُؤۡتُوا۟ ٱلزَّكَوٰةَۚ وَذَ ٰ⁠لِكَ دِینُ ٱلۡقَیِّمَةِ\n\";s:13:\"numberInSurah\";i:5;s:3:\"juz\";i:30;s:6:\"manzil\";i:7;s:4:\"page\";i:598;s:4:\"ruku\";i:540;s:11:\"hizbQuarter\";i:239;s:5:\"sajda\";b:0;}i:5;a:9:{s:6:\"number\";i:6136;s:4:\"text\";s:278:\"إِنَّ ٱلَّذِینَ كَفَرُوا۟ مِنۡ أَهۡلِ ٱلۡكِتَـٰبِ وَٱلۡمُشۡرِكِینَ فِی نَارِ جَهَنَّمَ خَـٰلِدِینَ فِیهَاۤۚ أُو۟لَـٰۤىِٕكَ هُمۡ شَرُّ ٱلۡبَرِیَّةِ\n\";s:13:\"numberInSurah\";i:6;s:3:\"juz\";i:30;s:6:\"manzil\";i:7;s:4:\"page\";i:598;s:4:\"ruku\";i:540;s:11:\"hizbQuarter\";i:239;s:5:\"sajda\";b:0;}i:6;a:9:{s:6:\"number\";i:6137;s:4:\"text\";s:181:\"إِنَّ ٱلَّذِینَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ أُو۟لَـٰۤىِٕكَ هُمۡ خَیۡرُ ٱلۡبَرِیَّةِ\n\";s:13:\"numberInSurah\";i:7;s:3:\"juz\";i:30;s:6:\"manzil\";i:7;s:4:\"page\";i:598;s:4:\"ruku\";i:540;s:11:\"hizbQuarter\";i:239;s:5:\"sajda\";b:0;}i:7;a:9:{s:6:\"number\";i:6138;s:4:\"text\";s:357:\"جَزَاۤؤُهُمۡ عِندَ رَبِّهِمۡ جَنَّـٰتُ عَدۡنࣲ تَجۡرِی مِن تَحۡتِهَا ٱلۡأَنۡهَـٰرُ خَـٰلِدِینَ فِیهَاۤ أَبَدࣰاۖ رَّضِیَ ٱللَّهُ عَنۡهُمۡ وَرَضُوا۟ عَنۡهُۚ ذَ ٰ⁠لِكَ لِمَنۡ خَشِیَ رَبَّهُۥ\n\";s:13:\"numberInSurah\";i:8;s:3:\"juz\";i:30;s:6:\"manzil\";i:7;s:4:\"page\";i:599;s:4:\"ruku\";i:540;s:11:\"hizbQuarter\";i:239;s:5:\"sajda\";b:0;}}s:7:\"edition\";a:7:{s:10:\"identifier\";s:27:\"quran-uthmani-quran-academy\";s:8:\"language\";s:2:\"ar\";s:4:\"name\";s:67:\"القرآن الكريم برسم العثماني (quran-academy)\";s:11:\"englishName\";s:78:\"Modified Quran Uthmani Text from the Quran Academy to work with the Kitab font\";s:6:\"format\";s:4:\"text\";s:4:\"type\";s:5:\"quran\";s:9:\"direction\";s:3:\"rtl\";}}', 1794581421),
('quranapp-cache-surah_98_fr.hamidullah', 'a:8:{s:6:\"number\";i:98;s:4:\"name\";s:37:\"سُورَةُ البَيِّنَةِ\";s:11:\"englishName\";s:10:\"Al-Bayyina\";s:22:\"englishNameTranslation\";s:12:\"The Evidence\";s:14:\"revelationType\";s:7:\"Medinan\";s:13:\"numberOfAyahs\";i:8;s:5:\"ayahs\";a:8:{i:0;a:9:{s:6:\"number\";i:6131;s:4:\"text\";s:146:\"Les infidèles parmi les gens du Livre, ainsi que les Associateurs, ne cesseront pas de mécroire jusqu\'à ce que leur vienne la Preuve évidente:\";s:13:\"numberInSurah\";i:1;s:3:\"juz\";i:30;s:6:\"manzil\";i:7;s:4:\"page\";i:598;s:4:\"ruku\";i:540;s:11:\"hizbQuarter\";i:239;s:5:\"sajda\";b:0;}i:1;a:9:{s:6:\"number\";i:6132;s:4:\"text\";s:74:\"un Messager, de la part d\'Allah, qui leur récite des feuilles purifiées,\";s:13:\"numberInSurah\";i:2;s:3:\"juz\";i:30;s:6:\"manzil\";i:7;s:4:\"page\";i:598;s:4:\"ruku\";i:540;s:11:\"hizbQuarter\";i:239;s:5:\"sajda\";b:0;}i:2;a:9:{s:6:\"number\";i:6133;s:4:\"text\";s:71:\"dans lesquelles se trouvent des prescriptions d\'une rectitude parfaite.\";s:13:\"numberInSurah\";i:3;s:3:\"juz\";i:30;s:6:\"manzil\";i:7;s:4:\"page\";i:598;s:4:\"ruku\";i:540;s:11:\"hizbQuarter\";i:239;s:5:\"sajda\";b:0;}i:3;a:9:{s:6:\"number\";i:6134;s:4:\"text\";s:98:\"Et ceux à qui le Livre a été donné ne se sont divisés qu\'après que la preuve leur fut venue.\";s:13:\"numberInSurah\";i:4;s:3:\"juz\";i:30;s:6:\"manzil\";i:7;s:4:\"page\";i:598;s:4:\"ruku\";i:540;s:11:\"hizbQuarter\";i:239;s:5:\"sajda\";b:0;}i:4;a:9:{s:6:\"number\";i:6135;s:4:\"text\";s:173:\"Il ne leur a été commandé, cependant, que d\'adorer Allah, Lui vouant un culte exclusif, d\'accomplir la Salât et d\'acquitter la Zakât. Et voilà la religion de droiture.\";s:13:\"numberInSurah\";i:5;s:3:\"juz\";i:30;s:6:\"manzil\";i:7;s:4:\"page\";i:598;s:4:\"ruku\";i:540;s:11:\"hizbQuarter\";i:239;s:5:\"sajda\";b:0;}i:5;a:9:{s:6:\"number\";i:6136;s:4:\"text\";s:169:\"Les infidèles parmi les gens du Livre, ainsi que les Associateurs iront au feu de l\'Enfer, pour y demeurer éternellement. De toute la création, ce sont eux les pires.\";s:13:\"numberInSurah\";i:6;s:3:\"juz\";i:30;s:6:\"manzil\";i:7;s:4:\"page\";i:598;s:4:\"ruku\";i:540;s:11:\"hizbQuarter\";i:239;s:5:\"sajda\";b:0;}i:6;a:9:{s:6:\"number\";i:6137;s:4:\"text\";s:107:\"Quant à ceux qui croient et accomplissent les bonnes œuvres, ce sont les meilleurs de toute la création.\";s:13:\"numberInSurah\";i:7;s:3:\"juz\";i:30;s:6:\"manzil\";i:7;s:4:\"page\";i:598;s:4:\"ruku\";i:540;s:11:\"hizbQuarter\";i:239;s:5:\"sajda\";b:0;}i:7;a:9:{s:6:\"number\";i:6138;s:4:\"text\";s:228:\"Leur récompense auprès d\'Allah sera les Jardins de séjour, sous lesquels coulent les ruisseaux, pour y demeurer éternellement. Allah les agrée et ils L\'agréent. Telle sera [la récompense] de celui qui craint son Seigneur.\";s:13:\"numberInSurah\";i:8;s:3:\"juz\";i:30;s:6:\"manzil\";i:7;s:4:\"page\";i:599;s:4:\"ruku\";i:540;s:11:\"hizbQuarter\";i:239;s:5:\"sajda\";b:0;}}s:7:\"edition\";a:7:{s:10:\"identifier\";s:13:\"fr.hamidullah\";s:8:\"language\";s:2:\"fr\";s:4:\"name\";s:10:\"Hamidullah\";s:11:\"englishName\";s:19:\"Muhammad Hamidullah\";s:6:\"format\";s:4:\"text\";s:4:\"type\";s:11:\"translation\";s:9:\"direction\";s:3:\"ltr\";}}', 1794581422),
('quranapp-cache-surah_99_ar.uthmani', 'a:8:{s:6:\"number\";i:99;s:4:\"name\";s:41:\"سُورَةُ الزَّلۡزَلَةِ\";s:11:\"englishName\";s:10:\"Az-Zalzala\";s:22:\"englishNameTranslation\";s:14:\"The Earthquake\";s:14:\"revelationType\";s:7:\"Medinan\";s:13:\"numberOfAyahs\";i:8;s:5:\"ayahs\";a:8:{i:0;a:9:{s:6:\"number\";i:6139;s:4:\"text\";s:152:\"بِسۡمِ ٱللَّهِ ٱلرَّحۡمَـٰنِ ٱلرَّحِیمِ إِذَا زُلۡزِلَتِ ٱلۡأَرۡضُ زِلۡزَالَهَا\n\";s:13:\"numberInSurah\";i:1;s:3:\"juz\";i:30;s:6:\"manzil\";i:7;s:4:\"page\";i:599;s:4:\"ruku\";i:541;s:11:\"hizbQuarter\";i:239;s:5:\"sajda\";b:0;}i:1;a:9:{s:6:\"number\";i:6140;s:4:\"text\";s:69:\"وَأَخۡرَجَتِ ٱلۡأَرۡضُ أَثۡقَالَهَا\n\";s:13:\"numberInSurah\";i:2;s:3:\"juz\";i:30;s:6:\"manzil\";i:7;s:4:\"page\";i:599;s:4:\"ruku\";i:541;s:11:\"hizbQuarter\";i:239;s:5:\"sajda\";b:0;}i:2;a:9:{s:6:\"number\";i:6141;s:4:\"text\";s:58:\"وَقَالَ ٱلۡإِنسَـٰنُ مَا لَهَا\n\";s:13:\"numberInSurah\";i:3;s:3:\"juz\";i:30;s:6:\"manzil\";i:7;s:4:\"page\";i:599;s:4:\"ruku\";i:541;s:11:\"hizbQuarter\";i:239;s:5:\"sajda\";b:0;}i:3;a:9:{s:6:\"number\";i:6142;s:4:\"text\";s:68:\"یَوۡمَىِٕذࣲ تُحَدِّثُ أَخۡبَارَهَا\n\";s:13:\"numberInSurah\";i:4;s:3:\"juz\";i:30;s:6:\"manzil\";i:7;s:4:\"page\";i:599;s:4:\"ruku\";i:541;s:11:\"hizbQuarter\";i:239;s:5:\"sajda\";b:0;}i:4;a:9:{s:6:\"number\";i:6143;s:4:\"text\";s:58:\"بِأَنَّ رَبَّكَ أَوۡحَىٰ لَهَا\n\";s:13:\"numberInSurah\";i:5;s:3:\"juz\";i:30;s:6:\"manzil\";i:7;s:4:\"page\";i:599;s:4:\"ruku\";i:541;s:11:\"hizbQuarter\";i:239;s:5:\"sajda\";b:0;}i:5;a:9:{s:6:\"number\";i:6144;s:4:\"text\";s:132:\"یَوۡمَىِٕذࣲ یَصۡدُرُ ٱلنَّاسُ أَشۡتَاتࣰا لِّیُرَوۡا۟ أَعۡمَـٰلَهُمۡ\n\";s:13:\"numberInSurah\";i:6;s:3:\"juz\";i:30;s:6:\"manzil\";i:7;s:4:\"page\";i:599;s:4:\"ruku\";i:541;s:11:\"hizbQuarter\";i:239;s:5:\"sajda\";b:0;}i:6;a:9:{s:6:\"number\";i:6145;s:4:\"text\";s:93:\"فَمَن یَعۡمَلۡ مِثۡقَالَ ذَرَّةٍ خَیۡرࣰا یَرَهُۥ\n\";s:13:\"numberInSurah\";i:7;s:3:\"juz\";i:30;s:6:\"manzil\";i:7;s:4:\"page\";i:599;s:4:\"ruku\";i:541;s:11:\"hizbQuarter\";i:239;s:5:\"sajda\";b:0;}i:7;a:9:{s:6:\"number\";i:6146;s:4:\"text\";s:92:\"وَمَن یَعۡمَلۡ مِثۡقَالَ ذَرَّةࣲ شَرࣰّا یَرَهُۥ\n\";s:13:\"numberInSurah\";i:8;s:3:\"juz\";i:30;s:6:\"manzil\";i:7;s:4:\"page\";i:599;s:4:\"ruku\";i:541;s:11:\"hizbQuarter\";i:239;s:5:\"sajda\";b:0;}}s:7:\"edition\";a:7:{s:10:\"identifier\";s:27:\"quran-uthmani-quran-academy\";s:8:\"language\";s:2:\"ar\";s:4:\"name\";s:67:\"القرآن الكريم برسم العثماني (quran-academy)\";s:11:\"englishName\";s:78:\"Modified Quran Uthmani Text from the Quran Academy to work with the Kitab font\";s:6:\"format\";s:4:\"text\";s:4:\"type\";s:5:\"quran\";s:9:\"direction\";s:3:\"rtl\";}}', 1794581422),
('quranapp-cache-surah_99_fr.hamidullah', 'a:8:{s:6:\"number\";i:99;s:4:\"name\";s:41:\"سُورَةُ الزَّلۡزَلَةِ\";s:11:\"englishName\";s:10:\"Az-Zalzala\";s:22:\"englishNameTranslation\";s:14:\"The Earthquake\";s:14:\"revelationType\";s:7:\"Medinan\";s:13:\"numberOfAyahs\";i:8;s:5:\"ayahs\";a:8:{i:0;a:9:{s:6:\"number\";i:6139;s:4:\"text\";s:50:\"Quand la terre tremblera d\'un violent tremblement,\";s:13:\"numberInSurah\";i:1;s:3:\"juz\";i:30;s:6:\"manzil\";i:7;s:4:\"page\";i:599;s:4:\"ruku\";i:541;s:11:\"hizbQuarter\";i:239;s:5:\"sajda\";b:0;}i:1;a:9:{s:6:\"number\";i:6140;s:4:\"text\";s:41:\"et que la terre fera sortir ses fardeaux,\";s:13:\"numberInSurah\";i:2;s:3:\"juz\";i:30;s:6:\"manzil\";i:7;s:4:\"page\";i:599;s:4:\"ruku\";i:541;s:11:\"hizbQuarter\";i:239;s:5:\"sajda\";b:0;}i:2;a:9:{s:6:\"number\";i:6141;s:4:\"text\";s:37:\"et que l\'homme dira: «Qu\'a-t-elle?»\";s:13:\"numberInSurah\";i:3;s:3:\"juz\";i:30;s:6:\"manzil\";i:7;s:4:\"page\";i:599;s:4:\"ruku\";i:541;s:11:\"hizbQuarter\";i:239;s:5:\"sajda\";b:0;}i:3;a:9:{s:6:\"number\";i:6142;s:4:\"text\";s:39:\"ce jour-là, elle contera son histoire,\";s:13:\"numberInSurah\";i:4;s:3:\"juz\";i:30;s:6:\"manzil\";i:7;s:4:\"page\";i:599;s:4:\"ruku\";i:541;s:11:\"hizbQuarter\";i:239;s:5:\"sajda\";b:0;}i:4;a:9:{s:6:\"number\";i:6143;s:4:\"text\";s:56:\"selon ce que ton Seigneur lui aura révélé [ordonné].\";s:13:\"numberInSurah\";i:5;s:3:\"juz\";i:30;s:6:\"manzil\";i:7;s:4:\"page\";i:599;s:4:\"ruku\";i:541;s:11:\"hizbQuarter\";i:239;s:5:\"sajda\";b:0;}i:5;a:9:{s:6:\"number\";i:6144;s:4:\"text\";s:90:\"Ce jour-là, les gens sortiront séparément pour que leur soient montrées leurs œuvres.\";s:13:\"numberInSurah\";i:6;s:3:\"juz\";i:30;s:6:\"manzil\";i:7;s:4:\"page\";i:599;s:4:\"ruku\";i:541;s:11:\"hizbQuarter\";i:239;s:5:\"sajda\";b:0;}i:6;a:9:{s:6:\"number\";i:6145;s:4:\"text\";s:61:\"Quiconque fait un bien fût-ce du poids d\'un atome, le verra,\";s:13:\"numberInSurah\";i:7;s:3:\"juz\";i:30;s:6:\"manzil\";i:7;s:4:\"page\";i:599;s:4:\"ruku\";i:541;s:11:\"hizbQuarter\";i:239;s:5:\"sajda\";b:0;}i:7;a:9:{s:6:\"number\";i:6146;s:4:\"text\";s:63:\"et quiconque fait un mal fût-ce du poids d\'un atome, le verra.\";s:13:\"numberInSurah\";i:8;s:3:\"juz\";i:30;s:6:\"manzil\";i:7;s:4:\"page\";i:599;s:4:\"ruku\";i:541;s:11:\"hizbQuarter\";i:239;s:5:\"sajda\";b:0;}}s:7:\"edition\";a:7:{s:10:\"identifier\";s:13:\"fr.hamidullah\";s:8:\"language\";s:2:\"fr\";s:4:\"name\";s:10:\"Hamidullah\";s:11:\"englishName\";s:19:\"Muhammad Hamidullah\";s:6:\"format\";s:4:\"text\";s:4:\"type\";s:11:\"translation\";s:9:\"direction\";s:3:\"ltr\";}}', 1794581422),
