(1, 1, 1, 1, 'بِسۡمِ ٱللَّهِ ٱلرَّحۡمَـٰنِ ٱلرَّحِیمِ', 'Au nom d\'Allah, le Tout Miséricordieux, le Très Miséricordieux.', NULL, 1, 1, 1, 1, '2026-07-10 13:04:28', '2026-11-12 14:48:49'),
(2, 1, 2, 2, 'ٱلۡحَمۡدُ لِلَّهِ رَبِّ ٱلۡعَـٰلَمِینَ', 'Louange à Allah, Seigneur de l\'univers.', NULL, 1, 1, 1, 1, '2026-07-10 13:04:28', '2026-11-12 14:48:49'),
